const labsJson = r'''{"labs":[{"id":"ohms-law","bench":"ohm","setup":{},"subject":"Physics","domain":"physics","levels":["10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["ohm's law","ohm","electricity","electric current","current","resistance","potential difference","voltage"],"title":{"en":"Ohm's law","hi":"ओम का नियम","kn":"ಓಮ್‌ನ ನಿಯಮ"},"summary":{"en":"Change the potential difference across a resistor and watch the current follow it.","hi":"प्रतिरोधक के सिरों का विभवांतर बदलें और देखें कि धारा उसके साथ कैसे बदलती है।","kn":"ರೋಧಕದ ತುದಿಗಳ ವಿಭವಾಂತರ ಬದಲಿಸಿ, ವಿದ್ಯುತ್ ಪ್ರವಾಹ ಅದರೊಂದಿಗೆ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ನೋಡಿ."},"aim":{"en":"To study how the current (I) through a resistor depends on the potential difference (V) across it, and to find its resistance.","hi":"किसी प्रतिरोधक में बहने वाली धारा (I) उसके सिरों के विभवांतर (V) पर कैसे निर्भर करती है, इसका अध्ययन करना और उसका प्रतिरोध ज्ञात करना।","kn":"ರೋಧಕದ ಮೂಲಕ ಹರಿಯುವ ವಿದ್ಯುತ್ ಪ್ರವಾಹ (I) ಅದರ ತುದಿಗಳ ನಡುವಿನ ವಿಭವಾಂತರ (V)ವನ್ನು ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ ಎಂದು ಅಧ್ಯಯನ ಮಾಡಿ, ಅದರ ರೋಧವನ್ನು ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"At a steady temperature, the current through a conductor is directly proportional to the potential difference across it: V = I × R. So the graph of V against I is a straight line through the origin, and its slope is the resistance R.","hi":"स्थिर ताप पर किसी चालक में धारा उसके सिरों के विभवांतर के अनुक्रमानुपाती होती है: V = I × R. इसलिए V और I का ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा होता है, और उसकी प्रवणता प्रतिरोध R है।","kn":"ಸ್ಥಿರ ತಾಪದಲ್ಲಿ ವಾಹಕದ ಮೂಲಕ ಹರಿಯುವ ಪ್ರವಾಹವು ಅದರ ತುದಿಗಳ ವಿಭವಾಂತರಕ್ಕೆ ನೇರ ಅನುಪಾತದಲ್ಲಿರುತ್ತದೆ: V = I × R. ಆದ್ದರಿಂದ V ಮತ್ತು I ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಹಾದುಹೋಗುವ ಸರಳರೇಖೆ; ಅದರ ಇಳಿಜಾರೇ ರೋಧ R."},"apparatus":[{"en":"Battery of cells (1.5 V each)","hi":"सेलों की बैटरी (हर सेल 1.5 V)","kn":"ಕೋಶಗಳ ಬ್ಯಾಟರಿ (ಪ್ರತಿ ಕೋಶ 1.5 V)"},{"en":"Plug key","hi":"प्लग कुंजी","kn":"ಪ್ಲಗ್ ಕೀ"},{"en":"Rheostat","hi":"धारा नियंत्रक (रिओस्टेट)","kn":"ರಿಯೋಸ್ಟಾಟ್ (ಪ್ರವಾಹ ನಿಯಂತ್ರಕ)"},{"en":"Resistor (nichrome wire)","hi":"प्रतिरोधक (नाइक्रोम तार)","kn":"ರೋಧಕ (ನೈಕ್ರೋಮ್ ತಂತಿ)"},{"en":"Ammeter","hi":"ऐमीटर","kn":"ಅಮ್ಮೀಟರ್"},{"en":"Voltmeter","hi":"वोल्टमीटर","kn":"ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"Connecting wires","hi":"संयोजक तार","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು"}],"steps":[{"en":"Connect the cells, plug key, rheostat, ammeter and resistor in series. Connect the voltmeter across the resistor (in parallel).","hi":"सेल, प्लग कुंजी, रिओस्टेट, ऐमीटर और प्रतिरोधक को श्रेणी में जोड़ें। वोल्टमीटर को प्रतिरोधक के सिरों पर (पार्श्व में) जोड़ें।","kn":"ಕೋಶಗಳು, ಪ್ಲಗ್ ಕೀ, ರಿಯೋಸ್ಟಾಟ್, ಅಮ್ಮೀಟರ್ ಮತ್ತು ರೋಧಕವನ್ನು ಸರಣಿಯಲ್ಲಿ ಜೋಡಿಸಿ. ವೋಲ್ಟ್‌ಮೀಟರನ್ನು ರೋಧಕದ ತುದಿಗಳಿಗೆ (ಸಮಾಂತರವಾಗಿ) ಜೋಡಿಸಿ."},{"en":"Check that the + terminals of the ammeter and voltmeter lead towards the + terminal of the battery.","hi":"जाँचें कि ऐमीटर और वोल्टमीटर के + सिरे बैटरी के + सिरे की ओर जुड़े हों।","kn":"ಅಮ್ಮೀಟರ್ ಮತ್ತು ವೋಲ್ಟ್‌ಮೀಟರ್‌ಗಳ + ತುದಿಗಳು ಬ್ಯಾಟರಿಯ + ತುದಿಯ ಕಡೆಗೆ ಜೋಡಣೆಯಾಗಿವೆಯೇ ಪರೀಕ್ಷಿಸಿ."},{"en":"Put in the key. Read the ammeter (I) and the voltmeter (V) and record the pair.","hi":"कुंजी लगाएँ। ऐमीटर (I) और वोल्टमीटर (V) का पाठ्यांक पढ़ें और लिखें।","kn":"ಕೀ ಹಾಕಿ. ಅಮ್ಮೀಟರ್ (I) ಮತ್ತು ವೋಲ್ಟ್‌ಮೀಟರ್ (V) ಓದಿ ದಾಖಲಿಸಿ."},{"en":"Move the rheostat slider, or add a cell, to change the current. Take at least five pairs of readings.","hi":"धारा बदलने के लिए रिओस्टेट की स्लाइडर खिसकाएँ या एक सेल और जोड़ें। कम से कम पाँच जोड़ी पाठ्यांक लें।","kn":"ಪ್ರವಾಹ ಬದಲಿಸಲು ರಿಯೋಸ್ಟಾಟ್ ಸರಿಸಿ ಅಥವಾ ಇನ್ನೊಂದು ಕೋಶ ಸೇರಿಸಿ. ಕನಿಷ್ಠ ಐದು ಜೋಡಿ ಓದುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಿ."},{"en":"Take the key out between readings so that the wire does not heat up.","hi":"दो पाठ्यांकों के बीच कुंजी निकाल दें ताकि तार गरम न हो।","kn":"ತಂತಿ ಬಿಸಿಯಾಗದಂತೆ ಎರಡು ಓದುಗಳ ನಡುವೆ ಕೀ ತೆಗೆಯಿರಿ."},{"en":"Work out V ÷ I for every reading and plot a graph of V against I.","hi":"हर पाठ्यांक के लिए V ÷ I निकालें और V तथा I का ग्राफ़ बनाएँ।","kn":"ಪ್ರತಿ ಓದಿಗೆ V ÷ I ಲೆಕ್ಕಿಸಿ, V ಮತ್ತು I ನಕ್ಷೆ ಎಳೆಯಿರಿ."},{"en":"Find the resistance from the average of V ÷ I, or from the slope of the graph.","hi":"V ÷ I के औसत से, या ग्राफ़ की प्रवणता से, प्रतिरोध ज्ञात करें।","kn":"V ÷ I ಸರಾಸರಿಯಿಂದ ಅಥವಾ ನಕ್ಷೆಯ ಇಳಿಜಾರಿನಿಂದ ರೋಧ ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"All connections must be tight and clean.","hi":"सभी संयोजन कसे हुए और साफ़ हों।","kn":"ಎಲ್ಲಾ ಸಂಪರ್ಕಗಳು ಬಿಗಿಯಾಗಿ ಮತ್ತು ಸ್ವಚ್ಛವಾಗಿರಲಿ."},{"en":"The ammeter goes in series and the voltmeter in parallel with the resistor.","hi":"ऐमीटर श्रेणी में और वोल्टमीटर प्रतिरोधक के पार्श्व में जुड़े।","kn":"ಅಮ್ಮೀಟರ್ ಸರಣಿಯಲ್ಲಿ, ವೋಲ್ಟ್‌ಮೀಟರ್ ರೋಧಕಕ್ಕೆ ಸಮಾಂತರವಾಗಿ ಇರಲಿ."},{"en":"Keep the key in only while taking a reading, and keep the current small.","hi":"कुंजी केवल पाठ्यांक लेते समय लगाएँ और धारा कम रखें।","kn":"ಓದು ತೆಗೆದುಕೊಳ್ಳುವಾಗ ಮಾತ್ರ ಕೀ ಹಾಕಿ, ಪ್ರವಾಹ ಕಡಿಮೆ ಇರಲಿ."},{"en":"Note the least count and any zero error of the meters.","hi":"मीटरों का अल्पतमांक और शून्य त्रुटि नोट करें।","kn":"ಮೀಟರ್‌ಗಳ ಕನಿಷ್ಠ ಎಣಿಕೆ ಮತ್ತು ಶೂನ್ಯ ದೋಷ ಗಮನಿಸಿ."}],"conclusion":{"en":"V ÷ I stays nearly the same for every reading and the V–I graph is a straight line through the origin: the current is directly proportional to the potential difference. This is Ohm's law.","hi":"हर पाठ्यांक में V ÷ I लगभग समान रहता है और V–I ग्राफ़ मूल बिंदु से जाती सीधी रेखा है: धारा विभवांतर के अनुक्रमानुपाती है। यही ओम का नियम है।","kn":"ಪ್ರತಿ ಓದಿನಲ್ಲಿ V ÷ I ಬಹುತೇಕ ಒಂದೇ ಆಗಿರುತ್ತದೆ ಮತ್ತು V–I ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ: ಪ್ರವಾಹವು ವಿಭವಾಂತರಕ್ಕೆ ನೇರ ಅನುಪಾತದಲ್ಲಿದೆ. ಇದೇ ಓಮ್‌ನ ನಿಯಮ."},"viva":[{"q":{"en":"What is Ohm's law?","hi":"ओम का नियम क्या है?","kn":"ಓಮ್‌ನ ನಿಯಮ ಏನು?"},"a":{"en":"At a steady temperature, the current through a conductor is directly proportional to the potential difference across its ends.","hi":"स्थिर ताप पर किसी चालक में धारा उसके सिरों के विभवांतर के अनुक्रमानुपाती होती है।","kn":"ಸ್ಥಿರ ತಾಪದಲ್ಲಿ ವಾಹಕದ ಮೂಲಕ ಹರಿಯುವ ಪ್ರವಾಹವು ಅದರ ತುದಿಗಳ ವಿಭವಾಂತರಕ್ಕೆ ನೇರ ಅನುಪಾತದಲ್ಲಿರುತ್ತದೆ."}},{"q":{"en":"How is an ammeter connected?","hi":"ऐमीटर कैसे जोड़ा जाता है?","kn":"ಅಮ್ಮೀಟರ್ ಹೇಗೆ ಜೋಡಿಸುತ್ತಾರೆ?"},"a":{"en":"In series with the resistor.","hi":"प्रतिरोधक के साथ श्रेणी में।","kn":"ರೋಧಕದೊಂದಿಗೆ ಸರಣಿಯಲ್ಲಿ."}},{"q":{"en":"How is a voltmeter connected?","hi":"वोल्टमीटर कैसे जोड़ा जाता है?","kn":"ವೋಲ್ಟ್‌ಮೀಟರ್ ಹೇಗೆ ಜೋಡಿಸುತ್ತಾರೆ?"},"a":{"en":"In parallel, across the resistor.","hi":"प्रतिरोधक के सिरों पर, पार्श्व में।","kn":"ರೋಧಕದ ತುದಿಗಳಿಗೆ, ಸಮಾಂತರವಾಗಿ."}},{"q":{"en":"What is the SI unit of resistance?","hi":"प्रतिरोध का SI मात्रक क्या है?","kn":"ರೋಧದ SI ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"The ohm (Ω).","hi":"ओम (Ω)।","kn":"ಓಮ್ (Ω)."}},{"q":{"en":"Why is the key taken out between readings?","hi":"पाठ्यांकों के बीच कुंजी क्यों निकाली जाती है?","kn":"ಓದುಗಳ ನಡುವೆ ಕೀ ಏಕೆ ತೆಗೆಯುತ್ತಾರೆ?"},"a":{"en":"So the wire does not heat up; heating would change its resistance.","hi":"ताकि तार गरम न हो; गरम होने से उसका प्रतिरोध बदल जाएगा।","kn":"ತಂತಿ ಬಿಸಿಯಾಗದಂತೆ; ಬಿಸಿಯಾದರೆ ಅದರ ರೋಧ ಬದಲಾಗುತ್ತದೆ."}}]},{"id":"resistors","bench":"resistors","setup":{},"subject":"Physics","domain":"physics","levels":["10","12"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["series","parallel","resistors","resistance","combination of resistors","equivalent resistance","electricity"],"title":{"en":"Resistors in series and parallel","hi":"श्रेणी और पार्श्व में प्रतिरोधक","kn":"ಸರಣಿ ಮತ್ತು ಸಮಾಂತರದಲ್ಲಿ ರೋಧಕಗಳು"},"summary":{"en":"Join two resistors end to end, then side by side, and measure the resistance of the combination.","hi":"दो प्रतिरोधकों को पहले सिरे से सिरा, फिर साथ-साथ जोड़ें और संयोजन का प्रतिरोध मापें।","kn":"ಎರಡು ರೋಧಕಗಳನ್ನು ಮೊದಲು ತುದಿಗೆ ತುದಿ, ನಂತರ ಪಕ್ಕಪಕ್ಕ ಜೋಡಿಸಿ, ಸಂಯೋಜನೆಯ ರೋಧ ಅಳೆಯಿರಿ."},"aim":{"en":"To find the equivalent resistance of two resistors joined in series and in parallel.","hi":"श्रेणी और पार्श्व में जुड़े दो प्रतिरोधकों का तुल्य प्रतिरोध ज्ञात करना।","kn":"ಸರಣಿ ಮತ್ತು ಸಮಾಂತರದಲ್ಲಿ ಜೋಡಿಸಿದ ಎರಡು ರೋಧಕಗಳ ಸಮಾನ ರೋಧ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"In series the same current flows through both resistors and Rs = R1 + R2. In parallel both have the same potential difference and 1/Rp = 1/R1 + 1/R2. The measured resistance of any combination is V ÷ I.","hi":"श्रेणी में दोनों प्रतिरोधकों में समान धारा बहती है और Rs = R1 + R2. पार्श्व में दोनों पर समान विभवांतर होता है और 1/Rp = 1/R1 + 1/R2. किसी भी संयोजन का मापा गया प्रतिरोध V ÷ I है।","kn":"ಸರಣಿಯಲ್ಲಿ ಎರಡೂ ರೋಧಕಗಳಲ್ಲಿ ಒಂದೇ ಪ್ರವಾಹ ಹರಿಯುತ್ತದೆ, Rs = R1 + R2. ಸಮಾಂತರದಲ್ಲಿ ಎರಡಕ್ಕೂ ಒಂದೇ ವಿಭವಾಂತರ, 1/Rp = 1/R1 + 1/R2. ಯಾವುದೇ ಸಂಯೋಜನೆಯ ಅಳತೆಯ ರೋಧ V ÷ I."},"apparatus":[{"en":"Battery","hi":"बैटरी","kn":"ಬ್ಯಾಟರಿ"},{"en":"Plug key","hi":"प्लग कुंजी","kn":"ಪ್ಲಗ್ ಕೀ"},{"en":"Two resistors","hi":"दो प्रतिरोधक","kn":"ಎರಡು ರೋಧಕಗಳು"},{"en":"Ammeter","hi":"ऐमीटर","kn":"ಅಮ್ಮೀಟರ್"},{"en":"Voltmeter","hi":"वोल्टमीटर","kn":"ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"Connecting wires","hi":"संयोजक तार","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು"}],"steps":[{"en":"Find the resistance of each resistor on its own and note R1 and R2.","hi":"हर प्रतिरोधक का प्रतिरोध अलग-अलग ज्ञात करें और R1 तथा R2 लिखें।","kn":"ಪ್ರತಿ ರೋಧಕದ ರೋಧವನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಕಂಡುಹಿಡಿದು R1 ಮತ್ತು R2 ಬರೆಯಿರಿ."},{"en":"Join R1 and R2 end to end (series) with the battery, key and ammeter. Connect the voltmeter across both resistors.","hi":"R1 और R2 को सिरे से सिरा (श्रेणी में) बैटरी, कुंजी और ऐमीटर के साथ जोड़ें। वोल्टमीटर दोनों प्रतिरोधकों के सिरों पर जोड़ें।","kn":"R1 ಮತ್ತು R2 ಅನ್ನು ತುದಿಗೆ ತುದಿ (ಸರಣಿ) ಬ್ಯಾಟರಿ, ಕೀ, ಅಮ್ಮೀಟರ್‌ನೊಂದಿಗೆ ಜೋಡಿಸಿ. ವೋಲ್ಟ್‌ಮೀಟರನ್ನು ಎರಡೂ ರೋಧಕಗಳ ತುದಿಗಳಿಗೆ ಜೋಡಿಸಿ."},{"en":"Put in the key, record V and I, and work out Rs = V ÷ I.","hi":"कुंजी लगाएँ, V और I लिखें, और Rs = V ÷ I निकालें।","kn":"ಕೀ ಹಾಕಿ, V ಮತ್ತು I ದಾಖಲಿಸಿ, Rs = V ÷ I ಲೆಕ್ಕಿಸಿ."},{"en":"Now join R1 and R2 side by side (parallel) between the same two points, with the voltmeter across the pair.","hi":"अब R1 और R2 को उन्हीं दो बिंदुओं के बीच साथ-साथ (पार्श्व में) जोड़ें, वोल्टमीटर जोड़ी के सिरों पर हो।","kn":"ಈಗ R1 ಮತ್ತು R2 ಅನ್ನು ಅದೇ ಎರಡು ಬಿಂದುಗಳ ನಡುವೆ ಪಕ್ಕಪಕ್ಕ (ಸಮಾಂತರ) ಜೋಡಿಸಿ; ವೋಲ್ಟ್‌ಮೀಟರ್ ಜೋಡಿಯ ತುದಿಗಳಿಗೆ."},{"en":"Record V and I again and work out Rp = V ÷ I.","hi":"फिर से V और I लिखें और Rp = V ÷ I निकालें।","kn":"ಮತ್ತೆ V ಮತ್ತು I ದಾಖಲಿಸಿ, Rp = V ÷ I ಲೆಕ್ಕಿಸಿ."},{"en":"Compare your answers with R1 + R2 and with R1R2 ÷ (R1 + R2).","hi":"अपने उत्तरों की तुलना R1 + R2 और R1R2 ÷ (R1 + R2) से करें।","kn":"ನಿಮ್ಮ ಉತ್ತರಗಳನ್ನು R1 + R2 ಮತ್ತು R1R2 ÷ (R1 + R2) ಜೊತೆ ಹೋಲಿಸಿ."},{"en":"Repeat with a different pair of resistors.","hi":"प्रतिरोधकों की किसी दूसरी जोड़ी के साथ दोहराएँ।","kn":"ಬೇರೆ ಜೋಡಿ ರೋಧಕಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Join the ends of the resistors firmly.","hi":"प्रतिरोधकों के सिरे मज़बूती से जोड़ें।","kn":"ರೋಧಕಗಳ ತುದಿಗಳನ್ನು ಬಿಗಿಯಾಗಿ ಜೋಡಿಸಿ."},{"en":"Keep the key in only while reading the meters.","hi":"कुंजी केवल मीटर पढ़ते समय लगाएँ।","kn":"ಮೀಟರ್ ಓದುವಾಗ ಮಾತ್ರ ಕೀ ಹಾಕಿ."},{"en":"The voltmeter must be across the whole combination.","hi":"वोल्टमीटर पूरे संयोजन के सिरों पर हो।","kn":"ವೋಲ್ಟ್‌ಮೀಟರ್ ಇಡೀ ಸಂಯೋಜನೆಯ ತುದಿಗಳಿಗೆ ಇರಲಿ."}],"conclusion":{"en":"In series the resistance is the sum of the two; in parallel it is less than the smaller of the two, as 1/Rp = 1/R1 + 1/R2 predicts.","hi":"श्रेणी में प्रतिरोध दोनों का योग होता है; पार्श्व में यह दोनों में छोटे से भी कम होता है, जैसा 1/Rp = 1/R1 + 1/R2 बताता है।","kn":"ಸರಣಿಯಲ್ಲಿ ರೋಧ ಎರಡರ ಮೊತ್ತ; ಸಮಾಂತರದಲ್ಲಿ ಅದು ಚಿಕ್ಕದಕ್ಕಿಂತಲೂ ಕಡಿಮೆ, 1/Rp = 1/R1 + 1/R2 ಹೇಳುವಂತೆ."},"viva":[{"q":{"en":"In series, what is the same in both resistors?","hi":"श्रेणी में दोनों प्रतिरोधकों में क्या समान रहता है?","kn":"ಸರಣಿಯಲ್ಲಿ ಎರಡೂ ರೋಧಕಗಳಲ್ಲಿ ಯಾವುದು ಒಂದೇ?"},"a":{"en":"The current.","hi":"धारा।","kn":"ಪ್ರವಾಹ."}},{"q":{"en":"In parallel, what is the same across both resistors?","hi":"पार्श्व में दोनों प्रतिरोधकों पर क्या समान रहता है?","kn":"ಸಮಾಂತರದಲ್ಲಿ ಎರಡೂ ರೋಧಕಗಳ ಮೇಲೆ ಯಾವುದು ಒಂದೇ?"},"a":{"en":"The potential difference.","hi":"विभवांतर।","kn":"ವಿಭವಾಂತರ."}},{"q":{"en":"Why are appliances at home connected in parallel?","hi":"घर के उपकरण पार्श्व में क्यों जोड़े जाते हैं?","kn":"ಮನೆಯ ಉಪಕರಣಗಳನ್ನು ಸಮಾಂತರವಾಗಿ ಏಕೆ ಜೋಡಿಸುತ್ತಾರೆ?"},"a":{"en":"Each gets the full voltage and can be switched on or off by itself; if one fails the others keep working.","hi":"हर उपकरण को पूरा वोल्टेज मिलता है और उसे अलग से चालू-बंद किया जा सकता है; एक खराब हो तो बाकी चलते रहते हैं।","kn":"ಪ್ರತಿಯೊಂದಕ್ಕೂ ಪೂರ್ಣ ವೋಲ್ಟೇಜ್ ಸಿಗುತ್ತದೆ, ಪ್ರತ್ಯೇಕವಾಗಿ ಆನ್-ಆಫ್ ಮಾಡಬಹುದು; ಒಂದು ಕೆಟ್ಟರೂ ಉಳಿದವು ಕೆಲಸ ಮಾಡುತ್ತವೆ."}},{"q":{"en":"What is the equivalent resistance of two 10 Ω resistors in parallel?","hi":"पार्श्व में जुड़े दो 10 Ω प्रतिरोधकों का तुल्य प्रतिरोध क्या है?","kn":"ಸಮಾಂತರದಲ್ಲಿರುವ ಎರಡು 10 Ω ರೋಧಕಗಳ ಸಮಾನ ರೋಧ ಎಷ್ಟು?"},"a":{"en":"5 Ω.","hi":"5 Ω।","kn":"5 Ω."}},{"q":{"en":"Is the resistance in parallel more or less than the smallest resistor?","hi":"पार्श्व संयोजन का प्रतिरोध सबसे छोटे प्रतिरोधक से अधिक होता है या कम?","kn":"ಸಮಾಂತರ ಸಂಯೋಜನೆಯ ರೋಧ ಚಿಕ್ಕ ರೋಧಕಕ್ಕಿಂತ ಹೆಚ್ಚೋ ಕಡಿಮೆಯೋ?"},"a":{"en":"Less.","hi":"कम।","kn":"ಕಡಿಮೆ."}}]},{"id":"glass-slab","bench":"slab","setup":{},"subject":"Physics","domain":"physics","levels":["10","12"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["refraction","glass slab","light","refraction of light","lateral displacement","refractive index","angle of incidence"],"title":{"en":"Refraction through a glass slab","hi":"काँच के स्लैब से अपवर्तन","kn":"ಗಾಜಿನ ಚಪ್ಪಡಿಯ ಮೂಲಕ ವಕ್ರೀಭವನ"},"summary":{"en":"Trace a ray of light through a rectangular glass slab and measure how it bends.","hi":"आयताकार काँच के स्लैब से गुज़रती प्रकाश किरण का पथ खींचें और मापें कि वह कैसे मुड़ती है।","kn":"ಆಯತಾಕಾರದ ಗಾಜಿನ ಚಪ್ಪಡಿಯ ಮೂಲಕ ಬೆಳಕಿನ ಕಿರಣದ ಪಥ ಎಳೆದು, ಅದು ಹೇಗೆ ಬಾಗುತ್ತದೆ ಅಳೆಯಿರಿ."},"aim":{"en":"To trace the path of a ray of light through a rectangular glass slab for different angles of incidence, and to measure the angles of incidence, refraction and emergence.","hi":"आपतन कोण के विभिन्न मानों के लिए आयताकार काँच के स्लैब से प्रकाश किरण का पथ खींचना, और आपतन, अपवर्तन तथा निर्गमन कोण मापना।","kn":"ಬೇರೆ ಬೇರೆ ಪತನ ಕೋನಗಳಿಗೆ ಆಯತಾಕಾರದ ಗಾಜಿನ ಚಪ್ಪಡಿಯ ಮೂಲಕ ಬೆಳಕಿನ ಕಿರಣದ ಪಥ ಎಳೆದು, ಪತನ, ವಕ್ರೀಭವನ ಮತ್ತು ನಿರ್ಗಮನ ಕೋನಗಳನ್ನು ಅಳೆಯುವುದು."},"principle":{"en":"Light slows down in glass, so it bends towards the normal as it enters and away from the normal as it leaves. The two faces are parallel, so the emergent ray is parallel to the incident ray (e = i) but shifted sideways. The refractive index of glass is n = sin i ÷ sin r.","hi":"काँच में प्रकाश धीमा हो जाता है, इसलिए प्रवेश करते समय वह अभिलंब की ओर और बाहर निकलते समय अभिलंब से दूर मुड़ता है। दोनों फलक समांतर हैं, इसलिए निर्गत किरण आपतित किरण के समांतर होती है (e = i) पर एक ओर खिसकी हुई। काँच का अपवर्तनांक n = sin i ÷ sin r है।","kn":"ಗಾಜಿನಲ್ಲಿ ಬೆಳಕು ನಿಧಾನವಾಗುತ್ತದೆ; ಒಳಬರುವಾಗ ಲಂಬದ ಕಡೆಗೆ, ಹೊರಹೋಗುವಾಗ ಲಂಬದಿಂದ ದೂರ ಬಾಗುತ್ತದೆ. ಎರಡು ಮುಖಗಳು ಸಮಾಂತರವಾದ್ದರಿಂದ ನಿರ್ಗಮನ ಕಿರಣ ಪತನ ಕಿರಣಕ್ಕೆ ಸಮಾಂತರ (e = i), ಆದರೆ ಪಕ್ಕಕ್ಕೆ ಸರಿದಿರುತ್ತದೆ. ಗಾಜಿನ ವಕ್ರೀಭವನ ಸೂಚ್ಯಂಕ n = sin i ÷ sin r."},"apparatus":[{"en":"Rectangular glass slab","hi":"आयताकार काँच का स्लैब","kn":"ಆಯತಾಕಾರದ ಗಾಜಿನ ಚಪ್ಪಡಿ"},{"en":"Drawing board and white sheet","hi":"ड्रॉइंग बोर्ड और सफ़ेद कागज़","kn":"ಡ್ರಾಯಿಂಗ್ ಬೋರ್ಡ್ ಮತ್ತು ಬಿಳಿ ಹಾಳೆ"},{"en":"Drawing pins and four ordinary pins","hi":"ड्रॉइंग पिन और चार साधारण पिन","kn":"ಡ್ರಾಯಿಂಗ್ ಪಿನ್‌ಗಳು ಮತ್ತು ನಾಲ್ಕು ಸಾಮಾನ್ಯ ಪಿನ್‌ಗಳು"},{"en":"Protractor","hi":"चाँदा","kn":"ಕೋನಮಾಪಕ"},{"en":"Scale and sharp pencil","hi":"पैमाना और नुकीली पेंसिल","kn":"ಅಳತೆಪಟ್ಟಿ ಮತ್ತು ಚೂಪಾದ ಪೆನ್ಸಿಲ್"}],"steps":[{"en":"Fix a white sheet on the drawing board, place the slab in the middle and trace its outline ABCD.","hi":"ड्रॉइंग बोर्ड पर सफ़ेद कागज़ लगाएँ, स्लैब बीच में रखें और उसकी रूपरेखा ABCD खींचें।","kn":"ಡ್ರಾಯಿಂಗ್ ಬೋರ್ಡ್ ಮೇಲೆ ಬಿಳಿ ಹಾಳೆ ಅಂಟಿಸಿ, ಚಪ್ಪಡಿ ಮಧ್ಯದಲ್ಲಿಟ್ಟು ಅದರ ರೂಪರೇಖೆ ABCD ಎಳೆಯಿರಿ."},{"en":"Draw a normal at a point on face AB, and an incident ray making an angle i with it (say 30°).","hi":"फलक AB के एक बिंदु पर अभिलंब खींचें, और उससे कोण i (मान लें 30°) बनाती आपतित किरण खींचें।","kn":"AB ಮುಖದ ಒಂದು ಬಿಂದುವಿನಲ್ಲಿ ಲಂಬ ಎಳೆದು, ಅದರೊಂದಿಗೆ i ಕೋನ (ಉದಾ. 30°) ಮಾಡುವ ಪತನ ಕಿರಣ ಎಳೆಯಿರಿ."},{"en":"Fix two pins P and Q upright on the incident ray.","hi":"आपतित किरण पर दो पिन P और Q सीधे लगाएँ।","kn":"ಪತನ ಕಿರಣದ ಮೇಲೆ P ಮತ್ತು Q ಎಂಬ ಎರಡು ಪಿನ್‌ಗಳನ್ನು ನೇರವಾಗಿ ನೆಡಿ."},{"en":"Looking through face CD, fix pins R and S so that they look in one line with the images of P and Q.","hi":"फलक CD से देखते हुए पिन R और S ऐसे लगाएँ कि वे P और Q के प्रतिबिंबों के साथ एक सीध में दिखें।","kn":"CD ಮುಖದ ಮೂಲಕ ನೋಡುತ್ತಾ, R ಮತ್ತು S ಪಿನ್‌ಗಳನ್ನು P ಮತ್ತು Q ಪ್ರತಿಬಿಂಬಗಳೊಂದಿಗೆ ಒಂದೇ ಸಾಲಿನಲ್ಲಿ ಕಾಣುವಂತೆ ನೆಡಿ."},{"en":"Remove the slab. Join R and S for the emergent ray, and join the points where the rays meet the faces for the refracted ray.","hi":"स्लैब हटाएँ। निर्गत किरण के लिए R और S को मिलाएँ, और अपवर्तित किरण के लिए उन बिंदुओं को मिलाएँ जहाँ किरणें फलकों से मिलती हैं।","kn":"ಚಪ್ಪಡಿ ತೆಗೆಯಿರಿ. ನಿರ್ಗಮನ ಕಿರಣಕ್ಕೆ R ಮತ್ತು S ಜೋಡಿಸಿ; ವಕ್ರೀಭೂತ ಕಿರಣಕ್ಕೆ ಕಿರಣಗಳು ಮುಖಗಳನ್ನು ಸಂಧಿಸುವ ಬಿಂದುಗಳನ್ನು ಜೋಡಿಸಿ."},{"en":"Measure the angles i, r and e with the protractor.","hi":"चाँदे से कोण i, r और e मापें।","kn":"ಕೋನಮಾಪಕದಿಂದ i, r ಮತ್ತು e ಕೋನಗಳನ್ನು ಅಳೆಯಿರಿ."},{"en":"Repeat for other angles of incidence, such as 40°, 50° and 60°.","hi":"दूसरे आपतन कोणों, जैसे 40°, 50° और 60° के लिए दोहराएँ।","kn":"40°, 50°, 60° ಮುಂತಾದ ಬೇರೆ ಪತನ ಕೋನಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Pins must stand upright and at least 5 cm apart.","hi":"पिन सीधे खड़े और कम से कम 5 cm दूर हों।","kn":"ಪಿನ್‌ಗಳು ನೇರವಾಗಿ, ಕನಿಷ್ಠ 5 cm ಅಂತರದಲ್ಲಿರಲಿ."},{"en":"Look at the feet of the pins, not their heads.","hi":"पिनों के सिर नहीं, उनके निचले सिरे देखें।","kn":"ಪಿನ್‌ಗಳ ತಲೆಯಲ್ಲ, ಅವುಗಳ ಬುಡ ನೋಡಿ."},{"en":"Do not move the slab while fixing the pins.","hi":"पिन लगाते समय स्लैब न हिलाएँ।","kn":"ಪಿನ್ ನೆಡುವಾಗ ಚಪ್ಪಡಿ ಸರಿಸಬೇಡಿ."},{"en":"Keep the angle of incidence between 30° and 60°.","hi":"आपतन कोण 30° और 60° के बीच रखें।","kn":"ಪತನ ಕೋನ 30° ಮತ್ತು 60° ನಡುವೆ ಇರಲಿ."}],"conclusion":{"en":"The ray bends towards the normal as it enters the glass (r is less than i) and away from it as it leaves. The angle of emergence equals the angle of incidence, so the emergent ray is parallel to the incident ray but laterally displaced.","hi":"काँच में प्रवेश करते समय किरण अभिलंब की ओर मुड़ती है (r, i से कम) और बाहर निकलते समय उससे दूर। निर्गमन कोण आपतन कोण के बराबर है, इसलिए निर्गत किरण आपतित किरण के समांतर पर पार्श्व रूप से विस्थापित होती है।","kn":"ಗಾಜಿಗೆ ಪ್ರವೇಶಿಸುವಾಗ ಕಿರಣ ಲಂಬದ ಕಡೆಗೆ ಬಾಗುತ್ತದೆ (r, i ಗಿಂತ ಕಡಿಮೆ), ಹೊರಬರುವಾಗ ದೂರ ಬಾಗುತ್ತದೆ. ನಿರ್ಗಮನ ಕೋನ ಪತನ ಕೋನಕ್ಕೆ ಸಮ; ಆದ್ದರಿಂದ ನಿರ್ಗಮನ ಕಿರಣ ಪತನ ಕಿರಣಕ್ಕೆ ಸಮಾಂತರ, ಆದರೆ ಪಾರ್ಶ್ವವಾಗಿ ಸ್ಥಳಾಂತರಗೊಂಡಿದೆ."},"viva":[{"q":{"en":"What is refraction of light?","hi":"प्रकाश का अपवर्तन क्या है?","kn":"ಬೆಳಕಿನ ವಕ್ರೀಭವನ ಎಂದರೇನು?"},"a":{"en":"The bending of light as it passes from one medium into another.","hi":"एक माध्यम से दूसरे माध्यम में जाते समय प्रकाश का मुड़ना।","kn":"ಒಂದು ಮಾಧ್ಯಮದಿಂದ ಇನ್ನೊಂದಕ್ಕೆ ಸಾಗುವಾಗ ಬೆಳಕು ಬಾಗುವುದು."}},{"q":{"en":"Why does light bend when it enters glass?","hi":"काँच में प्रवेश करते समय प्रकाश क्यों मुड़ता है?","kn":"ಗಾಜಿಗೆ ಪ್ರವೇಶಿಸುವಾಗ ಬೆಳಕು ಏಕೆ ಬಾಗುತ್ತದೆ?"},"a":{"en":"Its speed changes: light travels more slowly in glass than in air.","hi":"उसकी चाल बदल जाती है: काँच में प्रकाश हवा से धीमा चलता है।","kn":"ಅದರ ವೇಗ ಬದಲಾಗುತ್ತದೆ: ಗಾಜಿನಲ್ಲಿ ಬೆಳಕು ಗಾಳಿಗಿಂತ ನಿಧಾನ."}},{"q":{"en":"How are the angle of incidence and the angle of emergence related?","hi":"आपतन कोण और निर्गमन कोण में क्या संबंध है?","kn":"ಪತನ ಕೋನ ಮತ್ತು ನಿರ್ಗಮನ ಕೋನಗಳ ಸಂಬಂಧವೇನು?"},"a":{"en":"They are equal.","hi":"वे बराबर होते हैं।","kn":"ಅವು ಸಮ."}},{"q":{"en":"What is lateral displacement?","hi":"पार्श्व विस्थापन क्या है?","kn":"ಪಾರ್ಶ್ವ ಸ್ಥಳಾಂತರ ಎಂದರೇನು?"},"a":{"en":"The perpendicular distance between the incident ray (extended) and the emergent ray.","hi":"आपतित किरण (आगे बढ़ाई गई) और निर्गत किरण के बीच की लंबवत दूरी।","kn":"ಪತನ ಕಿರಣ (ವಿಸ್ತರಿಸಿದ) ಮತ್ತು ನಿರ್ಗಮನ ಕಿರಣಗಳ ನಡುವಿನ ಲಂಬ ಅಂತರ."}},{"q":{"en":"What is the refractive index of ordinary glass?","hi":"साधारण काँच का अपवर्तनांक कितना होता है?","kn":"ಸಾಮಾನ್ಯ ಗಾಜಿನ ವಕ್ರೀಭವನ ಸೂಚ್ಯಂಕ ಎಷ್ಟು?"},"a":{"en":"About 1.5.","hi":"लगभग 1.5।","kn":"ಸುಮಾರು 1.5."}}]},{"id":"lens-mirror","bench":"lens","setup":{},"subject":"Physics","domain":"physics","levels":["10","12"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["lens","lenses","convex lens","concave mirror","mirror","mirrors","spherical mirrors","focal length","image formation","light","reflection of light"],"title":{"en":"Focal length of a convex lens and a concave mirror","hi":"उत्तल लेंस और अवतल दर्पण की फोकस दूरी","kn":"ಪೀನ ಮಸೂರ ಮತ್ತು ನಿಮ್ನ ದರ್ಪಣದ ನಾಭಿದೂರ"},"summary":{"en":"Move the candle and the screen until the image is sharp, and find the focal length from u and v.","hi":"मोमबत्ती और पर्दे को तब तक खिसकाएँ जब तक प्रतिबिंब स्पष्ट न हो, और u तथा v से फोकस दूरी ज्ञात करें।","kn":"ಪ್ರತಿಬಿಂಬ ಸ್ಪಷ್ಟವಾಗುವವರೆಗೆ ಮೇಣದಬತ್ತಿ ಮತ್ತು ಪರದೆ ಸರಿಸಿ, u ಮತ್ತು v ಯಿಂದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To find the focal length of a convex lens and of a concave mirror by forming sharp images of an object on a screen, and to note the nature of the images.","hi":"पर्दे पर वस्तु के स्पष्ट प्रतिबिंब बनाकर उत्तल लेंस और अवतल दर्पण की फोकस दूरी ज्ञात करना, और प्रतिबिंबों की प्रकृति लिखना।","kn":"ಪರದೆಯ ಮೇಲೆ ವಸ್ತುವಿನ ಸ್ಪಷ್ಟ ಪ್ರತಿಬಿಂಬ ಪಡೆದು ಪೀನ ಮಸೂರ ಮತ್ತು ನಿಮ್ನ ದರ್ಪಣದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು, ಪ್ರತಿಬಿಂಬಗಳ ಸ್ವರೂಪ ಗಮನಿಸುವುದು."},"principle":{"en":"For a lens 1/v − 1/u = 1/f, and for a mirror 1/v + 1/u = 1/f (with the sign convention). For a real image, using distances as positive numbers, f = uv ÷ (u + v). The image of a very distant object forms at the focus.","hi":"लेंस के लिए 1/v − 1/u = 1/f और दर्पण के लिए 1/v + 1/u = 1/f (चिह्न परिपाटी के साथ)। वास्तविक प्रतिबिंब के लिए दूरियों को धनात्मक लेकर f = uv ÷ (u + v). बहुत दूर की वस्तु का प्रतिबिंब फोकस पर बनता है।","kn":"ಮಸೂರಕ್ಕೆ 1/v − 1/u = 1/f, ದರ್ಪಣಕ್ಕೆ 1/v + 1/u = 1/f (ಚಿಹ್ನೆ ಸಂಪ್ರದಾಯದೊಂದಿಗೆ). ನೈಜ ಪ್ರತಿಬಿಂಬಕ್ಕೆ ದೂರಗಳನ್ನು ಧನಾತ್ಮಕವಾಗಿ ತೆಗೆದುಕೊಂಡರೆ f = uv ÷ (u + v). ಬಹಳ ದೂರದ ವಸ್ತುವಿನ ಪ್ರತಿಬಿಂಬ ನಾಭಿಯಲ್ಲಿ ಮೂಡುತ್ತದೆ."},"apparatus":[{"en":"Optical bench or metre scale","hi":"प्रकाशिक बेंच या मीटर पैमाना","kn":"ಆಪ್ಟಿಕಲ್ ಬೆಂಚ್ ಅಥವಾ ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ"},{"en":"Convex lens and concave mirror with holders","hi":"स्टैंड सहित उत्तल लेंस और अवतल दर्पण","kn":"ಹಿಡಿಕೆಗಳೊಂದಿಗೆ ಪೀನ ಮಸೂರ ಮತ್ತು ನಿಮ್ನ ದರ್ಪಣ"},{"en":"Lit candle","hi":"जलती मोमबत्ती","kn":"ಉರಿಯುವ ಮೇಣದಬತ್ತಿ"},{"en":"White screen","hi":"सफ़ेद पर्दा","kn":"ಬಿಳಿ ಪರದೆ"}],"steps":[{"en":"Quick check: form the image of a distant window or tree on the screen. The distance from the lens (or mirror) to the screen is roughly f.","hi":"जल्दी जाँच: दूर की खिड़की या पेड़ का प्रतिबिंब पर्दे पर बनाएँ। लेंस (या दर्पण) से पर्दे तक की दूरी लगभग f है।","kn":"ತ್ವರಿತ ಪರೀಕ್ಷೆ: ದೂರದ ಕಿಟಕಿ ಅಥವಾ ಮರದ ಪ್ರತಿಬಿಂಬವನ್ನು ಪರದೆಯ ಮೇಲೆ ಪಡೆಯಿರಿ. ಮಸೂರ (ಅಥವಾ ದರ್ಪಣ)ದಿಂದ ಪರದೆಗಿರುವ ದೂರ ಸುಮಾರು f."},{"en":"Fix the lens in its holder and place the lit candle farther than f from it. Note the object distance u.","hi":"लेंस को स्टैंड में लगाएँ और जलती मोमबत्ती उससे f से अधिक दूरी पर रखें। वस्तु दूरी u लिखें।","kn":"ಮಸೂರವನ್ನು ಹಿಡಿಕೆಯಲ್ಲಿರಿಸಿ, ಉರಿಯುವ ಮೇಣದಬತ್ತಿಯನ್ನು f ಗಿಂತ ಹೆಚ್ಚು ದೂರದಲ್ಲಿಡಿ. ವಸ್ತು ದೂರ u ಬರೆಯಿರಿ."},{"en":"Move the screen back and forth until a sharp image of the flame forms. Note the image distance v.","hi":"पर्दे को आगे-पीछे खिसकाएँ जब तक लौ का स्पष्ट प्रतिबिंब न बने। प्रतिबिंब दूरी v लिखें।","kn":"ಜ್ವಾಲೆಯ ಸ್ಪಷ್ಟ ಪ್ರತಿಬಿಂಬ ಮೂಡುವವರೆಗೆ ಪರದೆಯನ್ನು ಮುಂದೆ-ಹಿಂದೆ ಸರಿಸಿ. ಪ್ರತಿಬಿಂಬ ದೂರ v ಬರೆಯಿರಿ."},{"en":"Work out f = uv ÷ (u + v).","hi":"f = uv ÷ (u + v) निकालें।","kn":"f = uv ÷ (u + v) ಲೆಕ್ಕಿಸಿ."},{"en":"Repeat for at least four other object distances and take the average of f.","hi":"कम से कम चार अन्य वस्तु दूरियों के लिए दोहराएँ और f का औसत लें।","kn":"ಕನಿಷ್ಠ ನಾಲ್ಕು ಬೇರೆ ವಸ್ತು ದೂರಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ, f ನ ಸರಾಸರಿ ತೆಗೆದುಕೊಳ್ಳಿ."},{"en":"Each time, note whether the image is real or virtual, inverted or erect, magnified or diminished.","hi":"हर बार लिखें कि प्रतिबिंब वास्तविक है या आभासी, उल्टा या सीधा, बड़ा या छोटा।","kn":"ಪ್ರತಿ ಬಾರಿ ಪ್ರತಿಬಿಂಬ ನೈಜವೋ ಮಿಥ್ಯವೋ, ತಲೆಕೆಳಗೋ ನೇರವೋ, ದೊಡ್ಡದೋ ಚಿಕ್ಕದೋ ಬರೆಯಿರಿ."},{"en":"Bring the candle closer than f. No image forms on the screen: the image is virtual. Repeat the experiment with the concave mirror.","hi":"मोमबत्ती को f से पास लाएँ। पर्दे पर कोई प्रतिबिंब नहीं बनता: प्रतिबिंब आभासी है। अवतल दर्पण के साथ प्रयोग दोहराएँ।","kn":"ಮೇಣದಬತ್ತಿಯನ್ನು f ಗಿಂತ ಹತ್ತಿರ ತನ್ನಿ. ಪರದೆಯ ಮೇಲೆ ಪ್ರತಿಬಿಂಬ ಮೂಡದು: ಅದು ಮಿಥ್ಯ ಪ್ರತಿಬಿಂಬ. ನಿಮ್ನ ದರ್ಪಣದೊಂದಿಗೆ ಪ್ರಯೋಗ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"The flame, the centre of the lens and the centre of the screen must be at the same height.","hi":"लौ, लेंस का केंद्र और पर्दे का केंद्र एक ही ऊँचाई पर हों।","kn":"ಜ್ವಾಲೆ, ಮಸೂರದ ಕೇಂದ್ರ ಮತ್ತು ಪರದೆಯ ಕೇಂದ್ರ ಒಂದೇ ಎತ್ತರದಲ್ಲಿರಲಿ."},{"en":"Keep the lens and mirror clean.","hi":"लेंस और दर्पण साफ़ रखें।","kn":"ಮಸೂರ ಮತ್ತು ದರ್ಪಣ ಸ್ವಚ್ಛವಾಗಿರಲಿ."},{"en":"Take the position where the image is sharpest.","hi":"वह स्थिति लें जहाँ प्रतिबिंब सबसे स्पष्ट हो।","kn":"ಪ್ರತಿಬಿಂಬ ಅತ್ಯಂತ ಸ್ಪಷ್ಟವಾಗಿರುವ ಸ್ಥಾನ ತೆಗೆದುಕೊಳ್ಳಿ."},{"en":"Measure distances from the centre of the lens or the pole of the mirror.","hi":"दूरियाँ लेंस के केंद्र या दर्पण के ध्रुव से मापें।","kn":"ದೂರಗಳನ್ನು ಮಸೂರದ ಕೇಂದ್ರ ಅಥವಾ ದರ್ಪಣದ ಧ್ರುವದಿಂದ ಅಳೆಯಿರಿ."}],"conclusion":{"en":"The average of uv ÷ (u + v) gives the focal length. When the object is beyond F the image is real and inverted and can be taken on a screen; when it is inside F the lens gives a virtual, erect, magnified image.","hi":"uv ÷ (u + v) का औसत फोकस दूरी देता है। वस्तु F से परे हो तो प्रतिबिंब वास्तविक और उल्टा होता है और पर्दे पर लिया जा सकता है; F के भीतर हो तो लेंस आभासी, सीधा और बड़ा प्रतिबिंब देता है।","kn":"uv ÷ (u + v) ಸರಾಸರಿಯೇ ನಾಭಿದೂರ. ವಸ್ತು F ಆಚೆ ಇದ್ದಾಗ ಪ್ರತಿಬಿಂಬ ನೈಜ, ತಲೆಕೆಳಗು, ಪರದೆಯ ಮೇಲೆ ಪಡೆಯಬಹುದು; F ಒಳಗಿದ್ದಾಗ ಮಸೂರ ಮಿಥ್ಯ, ನೇರ, ದೊಡ್ಡ ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"What is focal length?","hi":"फोकस दूरी क्या है?","kn":"ನಾಭಿದೂರ ಎಂದರೇನು?"},"a":{"en":"The distance between the optical centre (or pole) and the principal focus.","hi":"प्रकाशिक केंद्र (या ध्रुव) और मुख्य फोकस के बीच की दूरी।","kn":"ದೃಕ್ ಕೇಂದ್ರ (ಅಥವಾ ಧ್ರುವ) ಮತ್ತು ಪ್ರಧಾನ ನಾಭಿಯ ನಡುವಿನ ದೂರ."}},{"q":{"en":"Where does the image of a very distant object form?","hi":"बहुत दूर की वस्तु का प्रतिबिंब कहाँ बनता है?","kn":"ಬಹಳ ದೂರದ ವಸ್ತುವಿನ ಪ್ರತಿಬಿಂಬ ಎಲ್ಲಿ ಮೂಡುತ್ತದೆ?"},"a":{"en":"At the principal focus.","hi":"मुख्य फोकस पर।","kn":"ಪ್ರಧಾನ ನಾಭಿಯಲ್ಲಿ."}},{"q":{"en":"An object is at 2F of a convex lens. Describe the image.","hi":"वस्तु उत्तल लेंस के 2F पर है। प्रतिबिंब कैसा होगा?","kn":"ವಸ್ತು ಪೀನ ಮಸೂರದ 2F ನಲ್ಲಿದೆ. ಪ್ರತಿಬಿಂಬ ಹೇಗಿರುತ್ತದೆ?"},"a":{"en":"At 2F on the other side: real, inverted and the same size.","hi":"दूसरी ओर 2F पर: वास्तविक, उल्टा और समान आकार का।","kn":"ಇನ್ನೊಂದು ಬದಿಯ 2F ನಲ್ಲಿ: ನೈಜ, ತಲೆಕೆಳಗು, ಅದೇ ಗಾತ್ರ."}},{"q":{"en":"Which images can be taken on a screen?","hi":"कौन-से प्रतिबिंब पर्दे पर लिए जा सकते हैं?","kn":"ಯಾವ ಪ್ರತಿಬಿಂಬಗಳನ್ನು ಪರದೆಯ ಮೇಲೆ ಪಡೆಯಬಹುದು?"},"a":{"en":"Only real images.","hi":"केवल वास्तविक प्रतिबिंब।","kn":"ನೈಜ ಪ್ರತಿಬಿಂಬಗಳು ಮಾತ್ರ."}},{"q":{"en":"Give one use each of a convex lens and a concave mirror.","hi":"उत्तल लेंस और अवतल दर्पण का एक-एक उपयोग बताइए।","kn":"ಪೀನ ಮಸೂರ ಮತ್ತು ನಿಮ್ನ ದರ್ಪಣದ ತಲಾ ಒಂದು ಉಪಯೋಗ ತಿಳಿಸಿ."},"a":{"en":"Convex lens: magnifying glass. Concave mirror: shaving mirror or torch reflector.","hi":"उत्तल लेंस: आवर्धक लेंस। अवतल दर्पण: दाढ़ी बनाने का दर्पण या टॉर्च का परावर्तक।","kn":"ಪೀನ ಮಸೂರ: ಭೂತಗನ್ನಡಿ. ನಿಮ್ನ ದರ್ಪಣ: ಕ್ಷೌರದ ಕನ್ನಡಿ ಅಥವಾ ಟಾರ್ಚ್ ಪ್ರತಿಫಲಕ."}}]},{"id":"pendulum","bench":"pendulum","setup":{},"subject":"Physics","domain":"physics","levels":["7","9","11"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["pendulum","simple pendulum","oscillation","oscillations","time period","motion and time","motion","gravitation","gravity"],"title":{"en":"The simple pendulum","hi":"सरल लोलक","kn":"ಸರಳ ಲೋಲಕ"},"summary":{"en":"Time twenty swings, change the length, and see why a longer pendulum swings more slowly.","hi":"बीस दोलनों का समय लें, लंबाई बदलें, और देखें कि लंबा लोलक धीरे क्यों झूलता है।","kn":"ಇಪ್ಪತ್ತು ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆಯಿರಿ, ಉದ್ದ ಬದಲಿಸಿ, ಉದ್ದವಾದ ಲೋಲಕ ನಿಧಾನವಾಗಿ ತೂಗುವುದೇಕೆ ನೋಡಿ."},"aim":{"en":"To measure the time period of a simple pendulum, study how it depends on the length, and find the value of g.","hi":"सरल लोलक का आवर्तकाल मापना, लंबाई पर उसकी निर्भरता का अध्ययन करना और g का मान ज्ञात करना।","kn":"ಸರಳ ಲೋಲಕದ ಆವರ್ತಕಾಲ ಅಳೆದು, ಅದು ಉದ್ದವನ್ನು ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ ಅಧ್ಯಯನ ಮಾಡಿ, g ಯ ಬೆಲೆ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"For small swings the time period is T = 2π√(L ÷ g). It depends on the length L but not on the mass of the bob. So T² is proportional to L, and g = 4π²L ÷ T².","hi":"छोटे दोलनों के लिए आवर्तकाल T = 2π√(L ÷ g) होता है। यह लंबाई L पर निर्भर करता है, गोलक के द्रव्यमान पर नहीं। इसलिए T² लंबाई L के अनुक्रमानुपाती है, और g = 4π²L ÷ T².","kn":"ಚಿಕ್ಕ ಆಂದೋಲನಗಳಿಗೆ ಆವರ್ತಕಾಲ T = 2π√(L ÷ g). ಅದು ಉದ್ದ L ಅನ್ನು ಅವಲಂಬಿಸಿದೆ, ಗುಂಡಿನ ದ್ರವ್ಯರಾಶಿಯನ್ನಲ್ಲ. ಆದ್ದರಿಂದ T² ಉದ್ದ L ಗೆ ಅನುಪಾತದಲ್ಲಿದೆ, g = 4π²L ÷ T²."},"apparatus":[{"en":"Stand with clamp","hi":"क्लैंप सहित स्टैंड","kn":"ಕ್ಲ್ಯಾಂಪ್ ಇರುವ ಸ್ಟ್ಯಾಂಡ್"},{"en":"Strong thread","hi":"मज़बूत धागा","kn":"ಗಟ್ಟಿ ದಾರ"},{"en":"Metal bob (and bobs of other materials)","hi":"धातु का गोलक (और दूसरे पदार्थों के गोलक)","kn":"ಲೋಹದ ಗುಂಡು (ಮತ್ತು ಬೇರೆ ವಸ್ತುಗಳ ಗುಂಡುಗಳು)"},{"en":"Split cork","hi":"फटा कॉर्क","kn":"ಸೀಳಿದ ಕಾರ್ಕ್"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"},{"en":"Metre scale","hi":"मीटर पैमाना","kn":"ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ"}],"steps":[{"en":"Tie the bob to the thread and hang it from the clamp so that it swings freely. Measure L from the point of suspension to the centre of the bob.","hi":"गोलक को धागे से बाँधकर क्लैंप से लटकाएँ ताकि वह मुक्त रूप से झूले। निलंबन बिंदु से गोलक के केंद्र तक L मापें।","kn":"ಗುಂಡನ್ನು ದಾರಕ್ಕೆ ಕಟ್ಟಿ ಮುಕ್ತವಾಗಿ ತೂಗುವಂತೆ ಕ್ಲ್ಯಾಂಪ್‌ಗೆ ತೂಗುಹಾಕಿ. ತೂಗುಬಿಂದುವಿನಿಂದ ಗುಂಡಿನ ಕೇಂದ್ರದವರೆಗೆ L ಅಳೆಯಿರಿ."},{"en":"Pull the bob a little to one side (about 10°) and let it go without pushing.","hi":"गोलक को थोड़ा एक ओर (लगभग 10°) खींचकर बिना धक्का दिए छोड़ें।","kn":"ಗುಂಡನ್ನು ಸ್ವಲ್ಪ ಒಂದು ಕಡೆಗೆ (ಸುಮಾರು 10°) ಎಳೆದು ತಳ್ಳದೆ ಬಿಡಿ."},{"en":"Start the stopwatch as the bob passes the middle, and count 20 oscillations.","hi":"जब गोलक बीच से गुज़रे तब विराम घड़ी चालू करें और 20 दोलन गिनें।","kn":"ಗುಂಡು ಮಧ್ಯಸ್ಥಾನ ದಾಟುವಾಗ ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ, 20 ಆಂದೋಲನಗಳನ್ನು ಎಣಿಸಿ."},{"en":"Stop the watch at the 20th oscillation. The time period is T = time ÷ 20.","hi":"20वें दोलन पर घड़ी रोकें। आवर्तकाल T = समय ÷ 20.","kn":"20ನೇ ಆಂದೋಲನದಲ್ಲಿ ಗಡಿಯಾರ ನಿಲ್ಲಿಸಿ. ಆವರ್ತಕಾಲ T = ಸಮಯ ÷ 20."},{"en":"Repeat for at least five different lengths.","hi":"कम से कम पाँच अलग-अलग लंबाइयों के लिए दोहराएँ।","kn":"ಕನಿಷ್ಠ ಐದು ಬೇರೆ ಬೇರೆ ಉದ್ದಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Keep the length the same and change the bob for a heavier or lighter one. The time period does not change.","hi":"लंबाई समान रखकर भारी या हल्का गोलक लगाएँ। आवर्तकाल नहीं बदलता।","kn":"ಉದ್ದ ಅದೇ ಇಟ್ಟು ಭಾರವಾದ ಅಥವಾ ಹಗುರವಾದ ಗುಂಡು ಹಾಕಿ. ಆವರ್ತಕಾಲ ಬದಲಾಗದು."},{"en":"Plot T² against L and find g from the slope of the line.","hi":"T² और L का ग्राफ़ बनाएँ और रेखा की प्रवणता से g ज्ञात करें।","kn":"T² ಮತ್ತು L ನಕ್ಷೆ ಎಳೆದು ರೇಖೆಯ ಇಳಿಜಾರಿನಿಂದ g ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Keep the swings small.","hi":"दोलन छोटे रखें।","kn":"ಆಂದೋಲನಗಳು ಚಿಕ್ಕದಾಗಿರಲಿ."},{"en":"Use a light thread that does not stretch.","hi":"हल्का और न खिंचने वाला धागा लें।","kn":"ಹಗುರವಾದ, ಹಿಗ್ಗದ ದಾರ ಬಳಸಿ."},{"en":"Keep fans off so no air pushes the bob.","hi":"पंखे बंद रखें ताकि हवा गोलक को न धकेले।","kn":"ಗಾಳಿ ಗುಂಡನ್ನು ತಳ್ಳದಂತೆ ಫ್ಯಾನ್ ಆಫ್ ಮಾಡಿ."},{"en":"Start counting from zero as you start the watch.","hi":"घड़ी चालू करते समय गिनती शून्य से शुरू करें।","kn":"ಗಡಿಯಾರ ಆರಂಭಿಸುವಾಗ ಎಣಿಕೆಯನ್ನು ಸೊನ್ನೆಯಿಂದ ಆರಂಭಿಸಿ."}],"conclusion":{"en":"The time period grows with the length, and T² is proportional to L (a straight-line graph). The time period does not depend on the mass of the bob. The slope gives g close to 9.8 m/s².","hi":"आवर्तकाल लंबाई के साथ बढ़ता है, और T² लंबाई के अनुक्रमानुपाती है (सीधी रेखा का ग्राफ़)। आवर्तकाल गोलक के द्रव्यमान पर निर्भर नहीं करता। प्रवणता से g लगभग 9.8 m/s² मिलता है।","kn":"ಉದ್ದ ಹೆಚ್ಚಿದಂತೆ ಆವರ್ತಕಾಲ ಹೆಚ್ಚುತ್ತದೆ; T² ಉದ್ದಕ್ಕೆ ಅನುಪಾತದಲ್ಲಿದೆ (ಸರಳರೇಖೆ ನಕ್ಷೆ). ಆವರ್ತಕಾಲ ಗುಂಡಿನ ದ್ರವ್ಯರಾಶಿಯನ್ನು ಅವಲಂಬಿಸಿಲ್ಲ. ಇಳಿಜಾರಿನಿಂದ g ಸುಮಾರು 9.8 m/s²."},"viva":[{"q":{"en":"What is one oscillation?","hi":"एक दोलन क्या है?","kn":"ಒಂದು ಆಂದೋಲನ ಎಂದರೇನು?"},"a":{"en":"The bob going from one end to the other and back again.","hi":"गोलक का एक सिरे से दूसरे सिरे तक जाकर वापस आना।","kn":"ಗುಂಡು ಒಂದು ತುದಿಯಿಂದ ಇನ್ನೊಂದಕ್ಕೆ ಹೋಗಿ ಮರಳಿ ಬರುವುದು."}},{"q":{"en":"What is the time period?","hi":"आवर्तकाल क्या है?","kn":"ಆವರ್ತಕಾಲ ಎಂದರೇನು?"},"a":{"en":"The time taken for one oscillation.","hi":"एक दोलन में लगा समय।","kn":"ಒಂದು ಆಂದೋಲನಕ್ಕೆ ತೆಗೆದುಕೊಳ್ಳುವ ಸಮಯ."}},{"q":{"en":"Does the time period depend on the mass of the bob?","hi":"क्या आवर्तकाल गोलक के द्रव्यमान पर निर्भर करता है?","kn":"ಆವರ್ತಕಾಲ ಗುಂಡಿನ ದ್ರವ್ಯರಾಶಿಯನ್ನು ಅವಲಂಬಿಸಿದೆಯೇ?"},"a":{"en":"No.","hi":"नहीं।","kn":"ಇಲ್ಲ."}},{"q":{"en":"What happens to T if the length is made four times as long?","hi":"लंबाई चार गुना करने पर T का क्या होगा?","kn":"ಉದ್ದವನ್ನು ನಾಲ್ಕು ಪಟ್ಟು ಮಾಡಿದರೆ T ಏನಾಗುತ್ತದೆ?"},"a":{"en":"It doubles.","hi":"यह दोगुना हो जाएगा।","kn":"ಅದು ಎರಡರಷ್ಟಾಗುತ್ತದೆ."}},{"q":{"en":"Why do we time 20 oscillations instead of one?","hi":"हम एक की जगह 20 दोलनों का समय क्यों लेते हैं?","kn":"ಒಂದರ ಬದಲು 20 ಆಂದೋಲನಗಳ ಸಮಯ ಏಕೆ ಅಳೆಯುತ್ತೇವೆ?"},"a":{"en":"Our reaction time adds an error; spread over 20 oscillations it becomes much smaller.","hi":"हमारी प्रतिक्रिया में लगे समय से त्रुटि आती है; 20 दोलनों में बँटकर वह बहुत कम हो जाती है।","kn":"ನಮ್ಮ ಪ್ರತಿಕ್ರಿಯೆಯ ಸಮಯದಿಂದ ದೋಷ ಬರುತ್ತದೆ; 20 ಆಂದೋಲನಗಳಲ್ಲಿ ಹಂಚಿದಾಗ ಅದು ತುಂಬಾ ಕಡಿಮೆಯಾಗುತ್ತದೆ."}}]},{"id":"buoyancy","bench":"buoyancy","setup":{},"subject":"Physics","domain":"physics","levels":["8","9"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["buoyancy","archimedes","archimedes' principle","upthrust","floating","sinking","float","sink","density","relative density","force and pressure","gravitation"],"title":{"en":"Archimedes' principle","hi":"आर्किमिडीज़ का सिद्धांत","kn":"ಆರ್ಕಿಮಿಡೀಸ್ ತತ್ವ"},"summary":{"en":"Lower objects into water on a spring balance and compare the weight lost with the water pushed out.","hi":"कमानीदार तुला पर वस्तुएँ पानी में डुबोएँ और घटे हुए भार की तुलना बाहर निकले पानी से करें।","kn":"ಸ್ಪ್ರಿಂಗ್ ತಕ್ಕಡಿಯಲ್ಲಿ ವಸ್ತುಗಳನ್ನು ನೀರಿನಲ್ಲಿ ಇಳಿಸಿ, ಕಳೆದುಕೊಂಡ ತೂಕವನ್ನು ಹೊರಬಂದ ನೀರಿನೊಂದಿಗೆ ಹೋಲಿಸಿ."},"aim":{"en":"To show that an object immersed in a liquid loses weight equal to the weight of the liquid it displaces, and to see why some objects float.","hi":"यह दिखाना कि द्रव में डूबी वस्तु के भार में कमी उसके द्वारा हटाए गए द्रव के भार के बराबर होती है, और देखना कि कुछ वस्तुएँ क्यों तैरती हैं।","kn":"ದ್ರವದಲ್ಲಿ ಮುಳುಗಿಸಿದ ವಸ್ತು ತಾನು ಸ್ಥಳಾಂತರಿಸಿದ ದ್ರವದ ತೂಕದಷ್ಟು ತೂಕ ಕಳೆದುಕೊಳ್ಳುತ್ತದೆ ಎಂದು ತೋರಿಸುವುದು, ಕೆಲವು ವಸ್ತುಗಳು ಏಕೆ ತೇಲುತ್ತವೆ ನೋಡುವುದು."},"principle":{"en":"A liquid pushes up on anything in it. This upthrust equals the weight of the liquid displaced (Archimedes' principle). An object sinks if it is denser than the liquid and floats if it is less dense. Relative density = weight in air ÷ loss of weight in water.","hi":"द्रव अपने अंदर की हर वस्तु को ऊपर धकेलता है। यह उत्प्लावन बल हटाए गए द्रव के भार के बराबर होता है (आर्किमिडीज़ का सिद्धांत)। द्रव से अधिक घनी वस्तु डूबती है, कम घनी तैरती है। आपेक्षिक घनत्व = वायु में भार ÷ पानी में भार की कमी।","kn":"ದ್ರವ ತನ್ನಲ್ಲಿರುವ ಯಾವುದನ್ನೂ ಮೇಲಕ್ಕೆ ತಳ್ಳುತ್ತದೆ. ಈ ತೇಲುಬಲ ಸ್ಥಳಾಂತರಗೊಂಡ ದ್ರವದ ತೂಕಕ್ಕೆ ಸಮ (ಆರ್ಕಿಮಿಡೀಸ್ ತತ್ವ). ದ್ರವಕ್ಕಿಂತ ಸಾಂದ್ರವಾದ ವಸ್ತು ಮುಳುಗುತ್ತದೆ, ಕಡಿಮೆ ಸಾಂದ್ರವಾದದ್ದು ತೇಲುತ್ತದೆ. ಸಾಪೇಕ್ಷ ಸಾಂದ್ರತೆ = ಗಾಳಿಯಲ್ಲಿ ತೂಕ ÷ ನೀರಿನಲ್ಲಿ ತೂಕದ ನಷ್ಟ."},"apparatus":[{"en":"Spring balance","hi":"कमानीदार तुला","kn":"ಸ್ಪ್ರಿಂಗ್ ತಕ್ಕಡಿ"},{"en":"Objects: iron, aluminium, stone, glass, wood, wax","hi":"वस्तुएँ: लोहा, ऐलुमिनियम, पत्थर, काँच, लकड़ी, मोम","kn":"ವಸ್ತುಗಳು: ಕಬ್ಬಿಣ, ಅಲ್ಯೂಮಿನಿಯಂ, ಕಲ್ಲು, ಗಾಜು, ಮರ, ಮೇಣ"},{"en":"Overflow can","hi":"अतिप्रवाह पात्र","kn":"ಉಕ್ಕಿ ಹರಿಯುವ ಪಾತ್ರೆ"},{"en":"Measuring cylinder","hi":"मापक सिलिंडर","kn":"ಅಳತೆ ಸಿಲಿಂಡರ್"},{"en":"Water and salt water","hi":"पानी और नमक का पानी","kn":"ನೀರು ಮತ್ತು ಉಪ್ಪುನೀರು"},{"en":"Thread","hi":"धागा","kn":"ದಾರ"}],"steps":[{"en":"Fill the overflow can with water up to the spout and put the measuring cylinder under the spout.","hi":"अतिप्रवाह पात्र को टोंटी तक पानी से भरें और टोंटी के नीचे मापक सिलिंडर रखें।","kn":"ಉಕ್ಕಿ ಹರಿಯುವ ಪಾತ್ರೆಯನ್ನು ಕೊಳವೆಯವರೆಗೆ ನೀರಿನಿಂದ ತುಂಬಿಸಿ, ಕೊಳವೆಯ ಕೆಳಗೆ ಅಳತೆ ಸಿಲಿಂಡರ್ ಇಡಿ."},{"en":"Hang the object from the spring balance and note its weight in air.","hi":"वस्तु को कमानीदार तुला से लटकाकर वायु में उसका भार लिखें।","kn":"ವಸ್ತುವನ್ನು ಸ್ಪ್ರಿಂಗ್ ತಕ್ಕಡಿಗೆ ತೂಗುಹಾಕಿ ಗಾಳಿಯಲ್ಲಿ ಅದರ ತೂಕ ಬರೆಯಿರಿ."},{"en":"Lower the object slowly into the water until it is completely under water, without touching the can.","hi":"वस्तु को धीरे-धीरे पानी में तब तक उतारें जब तक वह पूरी डूब न जाए, पात्र को छुए बिना।","kn":"ವಸ್ತುವನ್ನು ಪಾತ್ರೆಗೆ ತಾಗದಂತೆ ಸಂಪೂರ್ಣ ಮುಳುಗುವವರೆಗೆ ನಿಧಾನವಾಗಿ ನೀರಿನಲ್ಲಿ ಇಳಿಸಿ."},{"en":"Note the new reading of the balance: the weight in water.","hi":"तुला का नया पाठ्यांक लिखें: पानी में भार।","kn":"ತಕ್ಕಡಿಯ ಹೊಸ ಓದು ಬರೆಯಿರಿ: ನೀರಿನಲ್ಲಿ ತೂಕ."},{"en":"Read the water collected in the cylinder. 1 mL of water weighs 1 g.","hi":"सिलिंडर में जमा पानी पढ़ें। 1 mL पानी का भार 1 g होता है।","kn":"ಸಿಲಿಂಡರ್‌ನಲ್ಲಿ ಸಂಗ್ರಹವಾದ ನೀರು ಓದಿ. 1 mL ನೀರಿನ ತೂಕ 1 g."},{"en":"Compare the loss of weight with the weight of the water displaced.","hi":"भार की कमी की तुलना हटाए गए पानी के भार से करें।","kn":"ತೂಕದ ನಷ್ಟವನ್ನು ಸ್ಥಳಾಂತರಗೊಂಡ ನೀರಿನ ತೂಕದೊಂದಿಗೆ ಹೋಲಿಸಿ."},{"en":"Repeat with the other objects and with salt water. Note which objects float.","hi":"दूसरी वस्तुओं और नमक के पानी के साथ दोहराएँ। लिखें कौन-सी वस्तुएँ तैरती हैं।","kn":"ಬೇರೆ ವಸ್ತುಗಳು ಮತ್ತು ಉಪ್ಪುನೀರಿನೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ. ಯಾವ ವಸ್ತುಗಳು ತೇಲುತ್ತವೆ ಬರೆಯಿರಿ."}],"precautions":[{"en":"The object must not touch the sides or bottom of the can.","hi":"वस्तु पात्र की दीवारों या तली को न छुए।","kn":"ವಸ್ತು ಪಾತ್ರೆಯ ಬದಿ ಅಥವಾ ತಳ ತಾಗಬಾರದು."},{"en":"Fill the can exactly up to the spout before you begin.","hi":"शुरू करने से पहले पात्र ठीक टोंटी तक भरें।","kn":"ಆರಂಭಿಸುವ ಮೊದಲು ಪಾತ್ರೆಯನ್ನು ಸರಿಯಾಗಿ ಕೊಳವೆಯವರೆಗೆ ತುಂಬಿಸಿ."},{"en":"Read the balance and the cylinder at eye level.","hi":"तुला और सिलिंडर आँख के स्तर पर पढ़ें।","kn":"ತಕ್ಕಡಿ ಮತ್ತು ಸಿಲಿಂಡರ್ ಅನ್ನು ಕಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ಓದಿ."},{"en":"Wait until the water stops dripping from the spout.","hi":"टोंटी से पानी टपकना बंद होने तक रुकें।","kn":"ಕೊಳವೆಯಿಂದ ನೀರು ತೊಟ್ಟಿಕ್ಕುವುದು ನಿಲ್ಲುವವರೆಗೆ ಕಾಯಿರಿ."}],"conclusion":{"en":"The loss of weight is equal to the weight of the liquid displaced. Objects denser than the liquid sink; less dense objects float. Salt water, being denser, gives a larger upthrust.","hi":"भार की कमी हटाए गए द्रव के भार के बराबर है। द्रव से अधिक घनी वस्तुएँ डूबती हैं; कम घनी तैरती हैं। नमक का पानी अधिक घना है, इसलिए अधिक उत्प्लावन बल देता है।","kn":"ತೂಕದ ನಷ್ಟ ಸ್ಥಳಾಂತರಗೊಂಡ ದ್ರವದ ತೂಕಕ್ಕೆ ಸಮ. ದ್ರವಕ್ಕಿಂತ ಸಾಂದ್ರವಾದ ವಸ್ತುಗಳು ಮುಳುಗುತ್ತವೆ; ಕಡಿಮೆ ಸಾಂದ್ರವಾದವು ತೇಲುತ್ತವೆ. ಉಪ್ಪುನೀರು ಹೆಚ್ಚು ಸಾಂದ್ರವಾದ್ದರಿಂದ ಹೆಚ್ಚು ತೇಲುಬಲ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"What is buoyant force (upthrust)?","hi":"उत्प्लावन बल क्या है?","kn":"ತೇಲುಬಲ ಎಂದರೇನು?"},"a":{"en":"The upward force a liquid exerts on an object in it.","hi":"द्रव द्वारा उसमें रखी वस्तु पर लगाया गया ऊपर की ओर का बल।","kn":"ದ್ರವ ತನ್ನಲ್ಲಿರುವ ವಸ್ತುವಿನ ಮೇಲೆ ಹಾಕುವ ಮೇಲ್ಮುಖ ಬಲ."}},{"q":{"en":"State Archimedes' principle.","hi":"आर्किमिडीज़ का सिद्धांत लिखिए।","kn":"ಆರ್ಕಿಮಿಡೀಸ್ ತತ್ವ ತಿಳಿಸಿ."},"a":{"en":"An object wholly or partly immersed in a liquid feels an upward force equal to the weight of the liquid it displaces.","hi":"द्रव में पूरी या आंशिक रूप से डूबी वस्तु पर ऊपर की ओर बल लगता है जो उसके द्वारा हटाए गए द्रव के भार के बराबर होता है।","kn":"ದ್ರವದಲ್ಲಿ ಪೂರ್ಣ ಅಥವಾ ಭಾಗಶಃ ಮುಳುಗಿದ ವಸ್ತುವಿನ ಮೇಲೆ, ಅದು ಸ್ಥಳಾಂತರಿಸಿದ ದ್ರವದ ತೂಕಕ್ಕೆ ಸಮನಾದ ಮೇಲ್ಮುಖ ಬಲ ವರ್ತಿಸುತ್ತದೆ."}},{"q":{"en":"An iron nail sinks but an iron ship floats. Why?","hi":"लोहे की कील डूब जाती है पर लोहे का जहाज़ तैरता है। क्यों?","kn":"ಕಬ್ಬಿಣದ ಮೊಳೆ ಮುಳುಗುತ್ತದೆ, ಆದರೆ ಕಬ್ಬಿಣದ ಹಡಗು ತೇಲುತ್ತದೆ. ಏಕೆ?"},"a":{"en":"The hollow ship displaces a large volume of water, so the upthrust can equal its weight; its average density is less than water.","hi":"खोखला जहाज़ बहुत अधिक पानी हटाता है, इसलिए उत्प्लावन बल उसके भार के बराबर हो जाता है; उसका औसत घनत्व पानी से कम है।","kn":"ಟೊಳ್ಳಾದ ಹಡಗು ಹೆಚ್ಚು ನೀರನ್ನು ಸ್ಥಳಾಂತರಿಸುತ್ತದೆ, ತೇಲುಬಲ ಅದರ ತೂಕಕ್ಕೆ ಸಮವಾಗುತ್ತದೆ; ಅದರ ಸರಾಸರಿ ಸಾಂದ್ರತೆ ನೀರಿಗಿಂತ ಕಡಿಮೆ."}},{"q":{"en":"Why is it easier to float in sea water?","hi":"समुद्र के पानी में तैरना आसान क्यों है?","kn":"ಸಮುದ್ರದ ನೀರಿನಲ್ಲಿ ತೇಲುವುದು ಏಕೆ ಸುಲಭ?"},"a":{"en":"Sea water is denser, so it gives a larger upthrust.","hi":"समुद्री पानी अधिक घना है, इसलिए अधिक उत्प्लावन बल देता है।","kn":"ಸಮುದ್ರದ ನೀರು ಹೆಚ್ಚು ಸಾಂದ್ರ, ಆದ್ದರಿಂದ ಹೆಚ್ಚು ತೇಲುಬಲ ನೀಡುತ್ತದೆ."}},{"q":{"en":"What is the relative density of iron?","hi":"लोहे का आपेक्षिक घनत्व कितना है?","kn":"ಕಬ್ಬಿಣದ ಸಾಪೇಕ್ಷ ಸಾಂದ್ರತೆ ಎಷ್ಟು?"},"a":{"en":"About 7.9.","hi":"लगभग 7.9।","kn":"ಸುಮಾರು 7.9."}}]},{"id":"indicators","bench":"indicators","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["7","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["acid","acids","base","bases","alkali","indicator","indicators","litmus","ph","salts","acids bases and salts","neutralisation","turmeric"],"title":{"en":"Acids, bases and indicators","hi":"अम्ल, क्षारक और सूचक","kn":"ಆಮ್ಲಗಳು, ಪ್ರತ್ಯಾಮ್ಲಗಳು ಮತ್ತು ಸೂಚಕಗಳು"},"summary":{"en":"Test ten everyday substances with litmus, turmeric, phenolphthalein and universal indicator, and find their pH.","hi":"दस रोज़मर्रा के पदार्थों को लिटमस, हल्दी, फिनॉल्फ्थेलिन और सार्वत्रिक सूचक से परखें और उनका pH ज्ञात करें।","kn":"ದಿನನಿತ್ಯದ ಹತ್ತು ವಸ್ತುಗಳನ್ನು ಲಿಟ್ಮಸ್, ಅರಿಶಿನ, ಫಿನಾಫ್ಥಲೀನ್ ಮತ್ತು ಸಾರ್ವತ್ರಿಕ ಸೂಚಕದಿಂದ ಪರೀಕ್ಷಿಸಿ, ಅವುಗಳ pH ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To sort common substances into acidic, basic and neutral using indicators, and to find their approximate pH with universal indicator.","hi":"सूचकों की सहायता से सामान्य पदार्थों को अम्लीय, क्षारकीय और उदासीन में बाँटना, और सार्वत्रिक सूचक से उनका लगभग pH ज्ञात करना।","kn":"ಸೂಚಕಗಳನ್ನು ಬಳಸಿ ಸಾಮಾನ್ಯ ವಸ್ತುಗಳನ್ನು ಆಮ್ಲೀಯ, ಪ್ರತ್ಯಾಮ್ಲೀಯ ಮತ್ತು ತಟಸ್ಥ ಎಂದು ವಿಂಗಡಿಸುವುದು, ಸಾರ್ವತ್ರಿಕ ಸೂಚಕದಿಂದ ಅವುಗಳ ಅಂದಾಜು pH ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"An indicator changes colour in an acid or a base. Acids turn blue litmus red; bases turn red litmus blue, turmeric reddish-brown and phenolphthalein pink. Universal indicator shows a different colour for each pH from 0 to 14: 7 is neutral, below 7 acidic, above 7 basic.","hi":"सूचक अम्ल या क्षारक में रंग बदलता है। अम्ल नीले लिटमस को लाल करते हैं; क्षारक लाल लिटमस को नीला, हल्दी को लाल-भूरा और फिनॉल्फ्थेलिन को गुलाबी करते हैं। सार्वत्रिक सूचक 0 से 14 तक हर pH पर अलग रंग दिखाता है: 7 उदासीन, 7 से कम अम्लीय, 7 से अधिक क्षारकीय।","kn":"ಸೂಚಕ ಆಮ್ಲ ಅಥವಾ ಪ್ರತ್ಯಾಮ್ಲದಲ್ಲಿ ಬಣ್ಣ ಬದಲಿಸುತ್ತದೆ. ಆಮ್ಲಗಳು ನೀಲಿ ಲಿಟ್ಮಸ್ ಅನ್ನು ಕೆಂಪಾಗಿಸುತ್ತವೆ; ಪ್ರತ್ಯಾಮ್ಲಗಳು ಕೆಂಪು ಲಿಟ್ಮಸ್ ಅನ್ನು ನೀಲಿ, ಅರಿಶಿನವನ್ನು ಕೆಂಪು-ಕಂದು, ಫಿನಾಫ್ಥಲೀನನ್ನು ಗುಲಾಬಿ ಮಾಡುತ್ತವೆ. ಸಾರ್ವತ್ರಿಕ ಸೂಚಕ 0–14 ರ ಪ್ರತಿ pH ಗೆ ಬೇರೆ ಬಣ್ಣ ತೋರಿಸುತ್ತದೆ: 7 ತಟಸ್ಥ, 7 ಕ್ಕಿಂತ ಕಡಿಮೆ ಆಮ್ಲೀಯ, ಹೆಚ್ಚು ಪ್ರತ್ಯಾಮ್ಲೀಯ."},"apparatus":[{"en":"Test tubes and stand","hi":"परखनलियाँ और स्टैंड","kn":"ಪರೀಕ್ಷಾನಳಿಕೆಗಳು ಮತ್ತು ಸ್ಟ್ಯಾಂಡ್"},{"en":"Droppers","hi":"ड्रॉपर","kn":"ಡ್ರಾಪರ್‌ಗಳು"},{"en":"Samples: lemon juice, vinegar, dilute hydrochloric acid, dilute sodium hydroxide, soap solution, baking soda solution, lime water, distilled water, salt solution, sugar solution","hi":"नमूने: नींबू का रस, सिरका, तनु हाइड्रोक्लोरिक अम्ल, तनु सोडियम हाइड्रॉक्साइड, साबुन का घोल, खाने के सोडे का घोल, चूने का पानी, आसुत जल, नमक का घोल, चीनी का घोल","kn":"ಮಾದರಿಗಳು: ನಿಂಬೆರಸ, ವಿನಿಗರ್, ಸಾರರಿಕ್ತ ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲ, ಸಾರರಿಕ್ತ ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್, ಸಾಬೂನಿನ ದ್ರಾವಣ, ಅಡುಗೆ ಸೋಡಾ ದ್ರಾವಣ, ಸುಣ್ಣದ ನೀರು, ಬಟ್ಟಿ ಇಳಿಸಿದ ನೀರು, ಉಪ್ಪಿನ ದ್ರಾವಣ, ಸಕ್ಕರೆ ದ್ರಾವಣ"},{"en":"Red and blue litmus paper, turmeric paper","hi":"लाल और नीला लिटमस पत्र, हल्दी पत्र","kn":"ಕೆಂಪು ಮತ್ತು ನೀಲಿ ಲಿಟ್ಮಸ್ ಕಾಗದ, ಅರಿಶಿನ ಕಾಗದ"},{"en":"China rose indicator, phenolphthalein, methyl orange","hi":"गुड़हल सूचक, फिनॉल्फ्थेलिन, मेथिल ऑरेंज","kn":"ದಾಸವಾಳದ ಸೂಚಕ, ಫಿನಾಫ್ಥಲೀನ್, ಮೀಥೈಲ್ ಆರೆಂಜ್"},{"en":"Universal indicator and pH colour chart","hi":"सार्वत्रिक सूचक और pH रंग चार्ट","kn":"ಸಾರ್ವತ್ರಿಕ ಸೂಚಕ ಮತ್ತು pH ಬಣ್ಣದ ಚಾರ್ಟ್"}],"steps":[{"en":"Put about 2 mL of each sample into a separate, clean, labelled test tube.","hi":"हर नमूने का लगभग 2 mL अलग, साफ़, नामांकित परखनली में लें।","kn":"ಪ್ರತಿ ಮಾದರಿಯ ಸುಮಾರು 2 mL ಅನ್ನು ಬೇರೆ ಬೇರೆ ಸ್ವಚ್ಛ, ಹೆಸರು ಬರೆದ ಪರೀಕ್ಷಾನಳಿಕೆಗೆ ಹಾಕಿ."},{"en":"With a clean dropper, put a drop of each sample on blue and on red litmus paper. Note any colour change.","hi":"साफ़ ड्रॉपर से हर नमूने की एक बूँद नीले और लाल लिटमस पत्र पर डालें। रंग में बदलाव लिखें।","kn":"ಸ್ವಚ್ಛ ಡ್ರಾಪರ್‌ನಿಂದ ಪ್ರತಿ ಮಾದರಿಯ ಒಂದು ಹನಿಯನ್ನು ನೀಲಿ ಮತ್ತು ಕೆಂಪು ಲಿಟ್ಮಸ್ ಕಾಗದದ ಮೇಲೆ ಹಾಕಿ. ಬಣ್ಣ ಬದಲಾವಣೆ ಬರೆಯಿರಿ."},{"en":"Test each sample with turmeric paper and with China rose indicator.","hi":"हर नमूने को हल्दी पत्र और गुड़हल सूचक से परखें।","kn":"ಪ್ರತಿ ಮಾದರಿಯನ್ನು ಅರಿಶಿನ ಕಾಗದ ಮತ್ತು ದಾಸವಾಳದ ಸೂಚಕದಿಂದ ಪರೀಕ್ಷಿಸಿ."},{"en":"Add two drops of phenolphthalein to each tube and note what happens.","hi":"हर परखनली में फिनॉल्फ्थेलिन की दो बूँदें डालें और देखें क्या होता है।","kn":"ಪ್ರತಿ ನಳಿಕೆಗೆ ಎರಡು ಹನಿ ಫಿನಾಫ್ಥಲೀನ್ ಹಾಕಿ, ಏನಾಗುತ್ತದೆ ಗಮನಿಸಿ."},{"en":"Add a few drops of universal indicator and match the colour with the pH chart.","hi":"सार्वत्रिक सूचक की कुछ बूँदें डालें और रंग का मिलान pH चार्ट से करें।","kn":"ಕೆಲವು ಹನಿ ಸಾರ್ವತ್ರಿಕ ಸೂಚಕ ಹಾಕಿ, ಬಣ್ಣವನ್ನು pH ಚಾರ್ಟ್‌ನೊಂದಿಗೆ ಹೊಂದಿಸಿ."},{"en":"Record the colour, the nature (acidic, basic or neutral) and the pH of each sample.","hi":"हर नमूने का रंग, प्रकृति (अम्लीय, क्षारकीय या उदासीन) और pH लिखें।","kn":"ಪ್ರತಿ ಮಾದರಿಯ ಬಣ್ಣ, ಸ್ವರೂಪ (ಆಮ್ಲೀಯ, ಪ್ರತ್ಯಾಮ್ಲೀಯ ಅಥವಾ ತಟಸ್ಥ) ಮತ್ತು pH ದಾಖಲಿಸಿ."},{"en":"Arrange the samples from the most acidic to the most basic.","hi":"नमूनों को सबसे अधिक अम्लीय से सबसे अधिक क्षारकीय के क्रम में लगाएँ।","kn":"ಮಾದರಿಗಳನ್ನು ಅತ್ಯಂತ ಆಮ್ಲೀಯದಿಂದ ಅತ್ಯಂತ ಪ್ರತ್ಯಾಮ್ಲೀಯದವರೆಗೆ ಜೋಡಿಸಿ."}],"precautions":[{"en":"Never taste any chemical.","hi":"किसी भी रसायन को कभी न चखें।","kn":"ಯಾವುದೇ ರಾಸಾಯನಿಕವನ್ನು ಎಂದೂ ರುಚಿ ನೋಡಬೇಡಿ."},{"en":"Handle hydrochloric acid and sodium hydroxide carefully; wash any spill with plenty of water.","hi":"हाइड्रोक्लोरिक अम्ल और सोडियम हाइड्रॉक्साइड सावधानी से संभालें; गिरने पर खूब पानी से धोएँ।","kn":"ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲ ಮತ್ತು ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್ ಎಚ್ಚರಿಕೆಯಿಂದ ಬಳಸಿ; ಚೆಲ್ಲಿದರೆ ಸಾಕಷ್ಟು ನೀರಿನಿಂದ ತೊಳೆಯಿರಿ."},{"en":"Rinse the dropper before using it for another sample.","hi":"दूसरे नमूने के लिए ड्रॉपर धोकर प्रयोग करें।","kn":"ಇನ್ನೊಂದು ಮಾದರಿಗೆ ಬಳಸುವ ಮೊದಲು ಡ್ರಾಪರ್ ತೊಳೆಯಿರಿ."},{"en":"Use only a few drops of indicator and compare colours in good light.","hi":"सूचक की केवल कुछ बूँदें डालें और अच्छी रोशनी में रंगों की तुलना करें।","kn":"ಸೂಚಕದ ಕೆಲವೇ ಹನಿ ಬಳಸಿ, ಉತ್ತಮ ಬೆಳಕಿನಲ್ಲಿ ಬಣ್ಣ ಹೋಲಿಸಿ."}],"conclusion":{"en":"Lemon juice, vinegar and hydrochloric acid are acidic (pH below 7). Soap solution, baking soda solution, lime water and sodium hydroxide are basic (pH above 7). Distilled water, salt solution and sugar solution are neutral (pH 7).","hi":"नींबू का रस, सिरका और हाइड्रोक्लोरिक अम्ल अम्लीय हैं (pH 7 से कम)। साबुन का घोल, खाने के सोडे का घोल, चूने का पानी और सोडियम हाइड्रॉक्साइड क्षारकीय हैं (pH 7 से अधिक)। आसुत जल, नमक का घोल और चीनी का घोल उदासीन हैं (pH 7)।","kn":"ನಿಂಬೆರಸ, ವಿನಿಗರ್ ಮತ್ತು ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲ ಆಮ್ಲೀಯ (pH 7 ಕ್ಕಿಂತ ಕಡಿಮೆ). ಸಾಬೂನಿನ ದ್ರಾವಣ, ಅಡುಗೆ ಸೋಡಾ ದ್ರಾವಣ, ಸುಣ್ಣದ ನೀರು ಮತ್ತು ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್ ಪ್ರತ್ಯಾಮ್ಲೀಯ (pH 7 ಕ್ಕಿಂತ ಹೆಚ್ಚು). ಬಟ್ಟಿ ನೀರು, ಉಪ್ಪಿನ ಮತ್ತು ಸಕ್ಕರೆ ದ್ರಾವಣ ತಟಸ್ಥ (pH 7)."},"viva":[{"q":{"en":"What is an indicator?","hi":"सूचक क्या है?","kn":"ಸೂಚಕ ಎಂದರೇನು?"},"a":{"en":"A substance that shows by a change of colour whether something is an acid or a base.","hi":"ऐसा पदार्थ जो रंग बदलकर बताता है कि कोई पदार्थ अम्ल है या क्षारक।","kn":"ಬಣ್ಣ ಬದಲಿಸಿ ಯಾವುದಾದರೂ ವಸ್ತು ಆಮ್ಲವೋ ಪ್ರತ್ಯಾಮ್ಲವೋ ತಿಳಿಸುವ ವಸ್ತು."}},{"q":{"en":"What colour is phenolphthalein in a base?","hi":"क्षारक में फिनॉल्फ्थेलिन का रंग क्या होता है?","kn":"ಪ್ರತ್ಯಾಮ್ಲದಲ್ಲಿ ಫಿನಾಫ್ಥಲೀನ್‌ನ ಬಣ್ಣ ಯಾವುದು?"},"a":{"en":"Pink.","hi":"गुलाबी।","kn":"ಗುಲಾಬಿ."}},{"q":{"en":"What is the pH of pure water?","hi":"शुद्ध जल का pH कितना होता है?","kn":"ಶುದ್ಧ ನೀರಿನ pH ಎಷ್ಟು?"},"a":{"en":"7.","hi":"7।","kn":"7."}},{"q":{"en":"Name two natural indicators.","hi":"दो प्राकृतिक सूचकों के नाम बताइए।","kn":"ಎರಡು ನೈಸರ್ಗಿಕ ಸೂಚಕಗಳನ್ನು ಹೆಸರಿಸಿ."},"a":{"en":"Turmeric and China rose (litmus, from lichens, is another).","hi":"हल्दी और गुड़हल (लाइकेन से बना लिटमस भी)।","kn":"ಅರಿಶಿನ ಮತ್ತು ದಾಸವಾಳ (ಕಲ್ಲುಹೂವಿನಿಂದ ಬರುವ ಲಿಟ್ಮಸ್ ಕೂಡ)."}},{"q":{"en":"Which is the stronger acid: pH 2 or pH 5?","hi":"कौन-सा अधिक प्रबल अम्ल है: pH 2 या pH 5?","kn":"ಯಾವುದು ಪ್ರಬಲ ಆಮ್ಲ: pH 2 ಅಥವಾ pH 5?"},"a":{"en":"pH 2.","hi":"pH 2।","kn":"pH 2."}}]},{"id":"displacement","bench":"displacement","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["8","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["reactivity series","reactivity","displacement","displacement reaction","metals","metals and non-metals","chemical reactions","copper sulphate","materials: metals and non-metals","metallurgy","activity series"],"title":{"en":"The reactivity series of metals","hi":"धातुओं की अभिक्रियाशीलता श्रेणी","kn":"ಲೋಹಗಳ ಪ್ರತಿಕ್ರಿಯಾಶೀಲತೆ ಸರಣಿ"},"summary":{"en":"Dip four metals into four salt solutions and use what happens to arrange them by reactivity.","hi":"चार धातुओं को चार लवण विलयनों में डुबोएँ और परिणामों से उन्हें अभिक्रियाशीलता के क्रम में लगाएँ।","kn":"ನಾಲ್ಕು ಲೋಹಗಳನ್ನು ನಾಲ್ಕು ಲವಣ ದ್ರಾವಣಗಳಲ್ಲಿ ಅದ್ದಿ, ನಡೆದದ್ದರಿಂದ ಅವುಗಳನ್ನು ಪ್ರತಿಕ್ರಿಯಾಶೀಲತೆಯ ಕ್ರಮದಲ್ಲಿ ಜೋಡಿಸಿ."},"aim":{"en":"To arrange aluminium, zinc, iron and copper in order of reactivity by placing each metal in solutions of the salts of the others.","hi":"हर धातु को दूसरी धातुओं के लवणों के विलयन में रखकर ऐलुमिनियम, जिंक, लोहा और ताँबा को अभिक्रियाशीलता के क्रम में लगाना।","kn":"ಪ್ರತಿ ಲೋಹವನ್ನು ಇತರ ಲೋಹಗಳ ಲವಣಗಳ ದ್ರಾವಣದಲ್ಲಿಟ್ಟು ಅಲ್ಯೂಮಿನಿಯಂ, ಸತು, ಕಬ್ಬಿಣ ಮತ್ತು ತಾಮ್ರವನ್ನು ಪ್ರತಿಕ್ರಿಯಾಶೀಲತೆಯ ಕ್ರಮದಲ್ಲಿ ಜೋಡಿಸುವುದು."},"principle":{"en":"A more reactive metal displaces a less reactive metal from a solution of its salt, for example Zn + CuSO₄ → ZnSO₄ + Cu. A less reactive metal cannot displace a more reactive one, so nothing happens.","hi":"अधिक अभिक्रियाशील धातु कम अभिक्रियाशील धातु को उसके लवण के विलयन से विस्थापित करती है, जैसे Zn + CuSO₄ → ZnSO₄ + Cu. कम अभिक्रियाशील धातु अधिक अभिक्रियाशील को विस्थापित नहीं कर सकती, इसलिए कुछ नहीं होता।","kn":"ಹೆಚ್ಚು ಪ್ರತಿಕ್ರಿಯಾಶೀಲ ಲೋಹ ಕಡಿಮೆ ಪ್ರತಿಕ್ರಿಯಾಶೀಲ ಲೋಹವನ್ನು ಅದರ ಲವಣದ ದ್ರಾವಣದಿಂದ ಸ್ಥಳಾಂತರಿಸುತ್ತದೆ, ಉದಾ: Zn + CuSO₄ → ZnSO₄ + Cu. ಕಡಿಮೆ ಪ್ರತಿಕ್ರಿಯಾಶೀಲ ಲೋಹ ಹೆಚ್ಚಿನದನ್ನು ಸ್ಥಳಾಂತರಿಸಲಾರದು; ಏನೂ ಆಗುವುದಿಲ್ಲ."},"apparatus":[{"en":"Test tubes and stand","hi":"परखनलियाँ और स्टैंड","kn":"ಪರೀಕ್ಷಾನಳಿಕೆಗಳು ಮತ್ತು ಸ್ಟ್ಯಾಂಡ್"},{"en":"Clean strips of aluminium, zinc, iron and copper","hi":"ऐलुमिनियम, जिंक, लोहे और ताँबे की साफ़ पट्टियाँ","kn":"ಅಲ್ಯೂಮಿನಿಯಂ, ಸತು, ಕಬ್ಬಿಣ ಮತ್ತು ತಾಮ್ರದ ಸ್ವಚ್ಛ ಪಟ್ಟಿಗಳು"},{"en":"Sandpaper","hi":"रेगमाल","kn":"ಮರಳುಕಾಗದ"},{"en":"Solutions of aluminium sulphate, zinc sulphate, iron(II) sulphate and copper sulphate","hi":"ऐलुमिनियम सल्फेट, जिंक सल्फेट, आयरन(II) सल्फेट और कॉपर सल्फेट के विलयन","kn":"ಅಲ್ಯೂಮಿನಿಯಂ ಸಲ್ಫೇಟ್, ಸತು ಸಲ್ಫೇಟ್, ಕಬ್ಬಿಣ(II) ಸಲ್ಫೇಟ್ ಮತ್ತು ತಾಮ್ರದ ಸಲ್ಫೇಟ್ ದ್ರಾವಣಗಳು"}],"steps":[{"en":"Rub the metal strips with sandpaper to remove the dull layer on them.","hi":"धातु की पट्टियों को रेगमाल से रगड़कर उन पर की मटमैली परत हटाएँ।","kn":"ಲೋಹದ ಪಟ್ಟಿಗಳ ಮೇಲಿನ ಮಂದ ಪದರವನ್ನು ಮರಳುಕಾಗದದಿಂದ ಉಜ್ಜಿ ತೆಗೆಯಿರಿ."},{"en":"Put about 5 mL of each salt solution into labelled test tubes and note their colours.","hi":"हर लवण विलयन का लगभग 5 mL नामांकित परखनलियों में लें और उनके रंग लिखें।","kn":"ಪ್ರತಿ ಲವಣ ದ್ರಾವಣದ ಸುಮಾರು 5 mL ಅನ್ನು ಹೆಸರು ಬರೆದ ನಳಿಕೆಗಳಿಗೆ ಹಾಕಿ ಬಣ್ಣಗಳನ್ನು ಬರೆಯಿರಿ."},{"en":"Dip one metal strip into each solution.","hi":"एक धातु की पट्टी हर विलयन में डुबोएँ।","kn":"ಒಂದು ಲೋಹದ ಪಟ್ಟಿಯನ್ನು ಪ್ರತಿ ದ್ರಾವಣದಲ್ಲಿ ಅದ್ದಿ."},{"en":"Leave them for about 20 minutes. Look at the colour of the solution and at the surface of the metal.","hi":"लगभग 20 मिनट छोड़ दें। विलयन का रंग और धातु की सतह देखें।","kn":"ಸುಮಾರು 20 ನಿಮಿಷ ಬಿಡಿ. ದ್ರಾವಣದ ಬಣ್ಣ ಮತ್ತು ಲೋಹದ ಮೇಲ್ಮೈ ಗಮನಿಸಿ."},{"en":"Record whether a reaction took place.","hi":"लिखें कि अभिक्रिया हुई या नहीं।","kn":"ಪ್ರತಿಕ್ರಿಯೆ ನಡೆಯಿತೇ ಇಲ್ಲವೇ ದಾಖಲಿಸಿ."},{"en":"Repeat with each of the other metals.","hi":"बाकी हर धातु के साथ दोहराएँ।","kn":"ಉಳಿದ ಪ್ರತಿ ಲೋಹದೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Count how many metals each metal displaced, and arrange the four in order of reactivity.","hi":"गिनें कि हर धातु ने कितनी धातुओं को विस्थापित किया, और चारों को अभिक्रियाशीलता के क्रम में लगाएँ।","kn":"ಪ್ರತಿ ಲೋಹ ಎಷ್ಟು ಲೋಹಗಳನ್ನು ಸ್ಥಳಾಂತರಿಸಿತು ಎಣಿಸಿ, ನಾಲ್ಕನ್ನೂ ಪ್ರತಿಕ್ರಿಯಾಶೀಲತೆಯ ಕ್ರಮದಲ್ಲಿ ಜೋಡಿಸಿ."}],"precautions":[{"en":"Clean the metal strips well before use.","hi":"प्रयोग से पहले धातु की पट्टियाँ अच्छी तरह साफ़ करें।","kn":"ಬಳಸುವ ಮೊದಲು ಲೋಹದ ಪಟ್ಟಿಗಳನ್ನು ಚೆನ್ನಾಗಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ."},{"en":"Do not shake the test tubes.","hi":"परखनलियाँ न हिलाएँ।","kn":"ಪರೀಕ್ಷಾನಳಿಕೆಗಳನ್ನು ಅಲುಗಾಡಿಸಬೇಡಿ."},{"en":"Copper sulphate is poisonous: do not touch your mouth, and wash your hands afterwards.","hi":"कॉपर सल्फेट विषैला है: मुँह को न छुएँ और बाद में हाथ धोएँ।","kn":"ತಾಮ್ರದ ಸಲ್ಫೇಟ್ ವಿಷಕಾರಿ: ಬಾಯಿ ಮುಟ್ಟಬೇಡಿ, ನಂತರ ಕೈ ತೊಳೆಯಿರಿ."}],"conclusion":{"en":"Aluminium displaces the other three, zinc displaces iron and copper, iron displaces only copper, and copper displaces none. The order of reactivity is Al > Zn > Fe > Cu.","hi":"ऐलुमिनियम बाकी तीनों को, जिंक लोहे और ताँबे को, लोहा केवल ताँबे को विस्थापित करता है, और ताँबा किसी को नहीं। अभिक्रियाशीलता का क्रम Al > Zn > Fe > Cu है।","kn":"ಅಲ್ಯೂಮಿನಿಯಂ ಉಳಿದ ಮೂರನ್ನೂ, ಸತು ಕಬ್ಬಿಣ ಮತ್ತು ತಾಮ್ರವನ್ನು, ಕಬ್ಬಿಣ ತಾಮ್ರವನ್ನು ಮಾತ್ರ ಸ್ಥಳಾಂತರಿಸುತ್ತದೆ; ತಾಮ್ರ ಯಾವುದನ್ನೂ ಇಲ್ಲ. ಪ್ರತಿಕ್ರಿಯಾಶೀಲತೆಯ ಕ್ರಮ Al > Zn > Fe > Cu."},"viva":[{"q":{"en":"What is a displacement reaction?","hi":"विस्थापन अभिक्रिया क्या है?","kn":"ಸ್ಥಳಾಂತರ ಪ್ರತಿಕ್ರಿಯೆ ಎಂದರೇನು?"},"a":{"en":"A reaction in which a more reactive element takes the place of a less reactive one in its compound.","hi":"ऐसी अभिक्रिया जिसमें अधिक अभिक्रियाशील तत्व किसी यौगिक में कम अभिक्रियाशील तत्व का स्थान ले लेता है।","kn":"ಹೆಚ್ಚು ಪ್ರತಿಕ್ರಿಯಾಶೀಲ ಧಾತು ಸಂಯುಕ್ತದಲ್ಲಿ ಕಡಿಮೆ ಪ್ರತಿಕ್ರಿಯಾಶೀಲ ಧಾತುವಿನ ಸ್ಥಾನ ಪಡೆಯುವ ಪ್ರತಿಕ್ರಿಯೆ."}},{"q":{"en":"Why does blue copper sulphate solution turn pale green when an iron nail is put in it?","hi":"लोहे की कील डालने पर नीला कॉपर सल्फेट विलयन हल्का हरा क्यों हो जाता है?","kn":"ಕಬ್ಬಿಣದ ಮೊಳೆ ಹಾಕಿದಾಗ ನೀಲಿ ತಾಮ್ರದ ಸಲ್ಫೇಟ್ ದ್ರಾವಣ ತಿಳಿ ಹಸಿರಾಗುವುದೇಕೆ?"},"a":{"en":"Iron displaces copper and forms iron sulphate, which is pale green; brown copper coats the nail.","hi":"लोहा ताँबे को विस्थापित करके आयरन सल्फेट बनाता है जो हल्का हरा है; कील पर भूरा ताँबा जम जाता है।","kn":"ಕಬ್ಬಿಣ ತಾಮ್ರವನ್ನು ಸ್ಥಳಾಂತರಿಸಿ ತಿಳಿ ಹಸಿರಾದ ಕಬ್ಬಿಣದ ಸಲ್ಫೇಟ್ ರೂಪಿಸುತ್ತದೆ; ಮೊಳೆಯ ಮೇಲೆ ಕಂದು ತಾಮ್ರ ಲೇಪನವಾಗುತ್ತದೆ."}},{"q":{"en":"Why are the metal strips cleaned first?","hi":"धातु की पट्टियाँ पहले क्यों साफ़ की जाती हैं?","kn":"ಲೋಹದ ಪಟ್ಟಿಗಳನ್ನು ಮೊದಲು ಏಕೆ ಸ್ವಚ್ಛಗೊಳಿಸುತ್ತಾರೆ?"},"a":{"en":"To remove the oxide layer, which would slow down or stop the reaction.","hi":"ऑक्साइड परत हटाने के लिए, जो अभिक्रिया को धीमा या बंद कर देती।","kn":"ಪ್ರತಿಕ್ರಿಯೆಯನ್ನು ನಿಧಾನಗೊಳಿಸುವ ಅಥವಾ ನಿಲ್ಲಿಸುವ ಆಕ್ಸೈಡ್ ಪದರ ತೆಗೆಯಲು."}},{"q":{"en":"Can copper displace iron from iron sulphate?","hi":"क्या ताँबा आयरन सल्फेट से लोहे को विस्थापित कर सकता है?","kn":"ತಾಮ್ರ ಕಬ್ಬಿಣದ ಸಲ್ಫೇಟ್‌ನಿಂದ ಕಬ್ಬಿಣವನ್ನು ಸ್ಥಳಾಂತರಿಸಬಲ್ಲದೇ?"},"a":{"en":"No, copper is less reactive than iron.","hi":"नहीं, ताँबा लोहे से कम अभिक्रियाशील है।","kn":"ಇಲ್ಲ, ತಾಮ್ರ ಕಬ್ಬಿಣಕ್ಕಿಂತ ಕಡಿಮೆ ಪ್ರತಿಕ್ರಿಯಾಶೀಲ."}},{"q":{"en":"Which of the four metals is the most reactive?","hi":"चारों में सबसे अधिक अभिक्रियाशील धातु कौन-सी है?","kn":"ನಾಲ್ಕರಲ್ಲಿ ಅತ್ಯಂತ ಪ್ರತಿಕ್ರಿಯಾಶೀಲ ಲೋಹ ಯಾವುದು?"},"a":{"en":"Aluminium.","hi":"ऐलुमिनियम।","kn":"ಅಲ್ಯೂಮಿನಿಯಂ."}}]},{"id":"microscope","bench":"microscope","setup":{},"subject":"Biology","domain":"biology","levels":["8","9","10","11"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["cell","cells","microscope","onion peel","cheek cells","stomata","yeast","budding","tissues","fundamental unit of life","cell structure","cell structure and functions","how do organisms reproduce"],"title":{"en":"Cells under the microscope","hi":"सूक्ष्मदर्शी में कोशिकाएँ","kn":"ಸೂಕ್ಷ್ಮದರ್ಶಕದಲ್ಲಿ ಜೀವಕೋಶಗಳು"},"summary":{"en":"Focus a microscope on onion peel, cheek cells, a leaf peel and yeast, and label what you see.","hi":"प्याज़ की झिल्ली, गाल की कोशिकाओं, पत्ती की झिल्ली और यीस्ट पर सूक्ष्मदर्शी फोकस करें और जो दिखे उसे नामांकित करें।","kn":"ಈರುಳ್ಳಿ ಸಿಪ್ಪೆ, ಕೆನ್ನೆಯ ಜೀವಕೋಶಗಳು, ಎಲೆಯ ಸಿಪ್ಪೆ ಮತ್ತು ಯೀಸ್ಟ್ ಮೇಲೆ ಸೂಕ್ಷ್ಮದರ್ಶಕ ಕೇಂದ್ರೀಕರಿಸಿ, ಕಂಡದ್ದನ್ನು ಗುರುತಿಸಿ."},"aim":{"en":"To prepare and study temporary mounts of onion peel, human cheek cells, a leaf peel showing stomata, and yeast, and to identify their parts.","hi":"प्याज़ की झिल्ली, मानव गाल की कोशिकाओं, रंध्र दिखाती पत्ती की झिल्ली और यीस्ट की अस्थायी स्लाइड बनाकर देखना और उनके भागों को पहचानना।","kn":"ಈರುಳ್ಳಿ ಸಿಪ್ಪೆ, ಮಾನವನ ಕೆನ್ನೆಯ ಜೀವಕೋಶಗಳು, ಪತ್ರರಂಧ್ರ ತೋರಿಸುವ ಎಲೆಯ ಸಿಪ್ಪೆ ಮತ್ತು ಯೀಸ್ಟ್‌ನ ತಾತ್ಕಾಲಿಕ ಸ್ಲೈಡ್ ಸಿದ್ಧಪಡಿಸಿ ಅಧ್ಯಯನ ಮಾಡುವುದು, ಅವುಗಳ ಭಾಗಗಳನ್ನು ಗುರುತಿಸುವುದು."},"principle":{"en":"Most cells are too small and too clear to see with the eye. A compound microscope magnifies them, and a stain colours some parts so they stand out: safranin for plant cells, methylene blue for cheek cells. Plant cells have a cell wall and a large vacuole; animal cells do not.","hi":"अधिकतर कोशिकाएँ आँख से देखने के लिए बहुत छोटी और पारदर्शी होती हैं। संयुक्त सूक्ष्मदर्शी उन्हें बड़ा दिखाता है, और अभिरंजक कुछ भागों को रंग देता है ताकि वे उभर आएँ: पादप कोशिकाओं के लिए सेफ्रानिन, गाल की कोशिकाओं के लिए मेथिलीन ब्लू। पादप कोशिकाओं में कोशिका भित्ति और बड़ी रसधानी होती है; जंतु कोशिकाओं में नहीं।","kn":"ಬಹುತೇಕ ಜೀವಕೋಶಗಳು ಕಣ್ಣಿಗೆ ಕಾಣಲು ತುಂಬಾ ಚಿಕ್ಕವು ಮತ್ತು ಪಾರದರ್ಶಕ. ಸಂಯುಕ್ತ ಸೂಕ್ಷ್ಮದರ್ಶಕ ಅವುಗಳನ್ನು ದೊಡ್ಡದಾಗಿ ತೋರಿಸುತ್ತದೆ; ಬಣ್ಣಕಾರಕ ಕೆಲವು ಭಾಗಗಳಿಗೆ ಬಣ್ಣ ನೀಡಿ ಎದ್ದು ಕಾಣುವಂತೆ ಮಾಡುತ್ತದೆ: ಸಸ್ಯ ಕೋಶಗಳಿಗೆ ಸಫ್ರಾನಿನ್, ಕೆನ್ನೆಯ ಕೋಶಗಳಿಗೆ ಮೀಥಿಲೀನ್ ನೀಲಿ. ಸಸ್ಯ ಕೋಶಗಳಿಗೆ ಕೋಶಭಿತ್ತಿ ಮತ್ತು ದೊಡ್ಡ ರಸದಾನಿ ಇರುತ್ತದೆ; ಪ್ರಾಣಿ ಕೋಶಗಳಿಗೆ ಇಲ್ಲ."},"apparatus":[{"en":"Compound microscope","hi":"संयुक्त सूक्ष्मदर्शी","kn":"ಸಂಯುಕ್ತ ಸೂಕ್ಷ್ಮದರ್ಶಕ"},{"en":"Slides and cover slips","hi":"स्लाइड और कवर स्लिप","kn":"ಸ್ಲೈಡ್‌ಗಳು ಮತ್ತು ಕವರ್ ಸ್ಲಿಪ್‌ಗಳು"},{"en":"Forceps, needle and brush","hi":"चिमटी, सुई और ब्रश","kn":"ಚಿಮುಟ, ಸೂಜಿ ಮತ್ತು ಬ್ರಷ್"},{"en":"Dropper and watch glass","hi":"ड्रॉपर और वॉच ग्लास","kn":"ಡ್ರಾಪರ್ ಮತ್ತು ವಾಚ್ ಗ್ಲಾಸ್"},{"en":"Glycerine and blotting paper","hi":"ग्लिसरीन और सोख्ता कागज़","kn":"ಗ್ಲಿಸರಿನ್ ಮತ್ತು ಒತ್ತುಕಾಗದ"},{"en":"Stains: safranin and methylene blue","hi":"अभिरंजक: सेफ्रानिन और मेथिलीन ब्लू","kn":"ಬಣ್ಣಕಾರಕಗಳು: ಸಫ್ರಾನಿನ್ ಮತ್ತು ಮೀಥಿಲೀನ್ ನೀಲಿ"},{"en":"Onion, clean toothpick, fresh leaf, yeast in sugar solution","hi":"प्याज़, साफ़ टूथपिक, ताज़ी पत्ती, चीनी के घोल में यीस्ट","kn":"ಈರುಳ್ಳಿ, ಸ್ವಚ್ಛ ಟೂತ್‌ಪಿಕ್, ತಾಜಾ ಎಲೆ, ಸಕ್ಕರೆ ದ್ರಾವಣದಲ್ಲಿ ಯೀಸ್ಟ್"}],"steps":[{"en":"Peel a thin, clear layer from the inner side of an onion scale, or gently scrape the inside of your cheek with a clean toothpick.","hi":"प्याज़ की शल्क के अंदर की ओर से पतली, पारदर्शी परत उतारें, या साफ़ टूथपिक से गाल के अंदर हल्के से खुरचें।","kn":"ಈರುಳ್ಳಿ ಪದರದ ಒಳಭಾಗದಿಂದ ತೆಳುವಾದ ಪಾರದರ್ಶಕ ಪದರ ಸುಲಿಯಿರಿ, ಅಥವಾ ಸ್ವಚ್ಛ ಟೂತ್‌ಪಿಕ್‌ನಿಂದ ಕೆನ್ನೆಯ ಒಳಭಾಗವನ್ನು ಮೃದುವಾಗಿ ಕೆರೆಯಿರಿ."},{"en":"Place it in a drop of water on a clean slide, add a drop of stain, wait a minute and remove the extra stain.","hi":"इसे साफ़ स्लाइड पर पानी की एक बूँद में रखें, अभिरंजक की एक बूँद डालें, एक मिनट रुकें और अतिरिक्त अभिरंजक हटा दें।","kn":"ಇದನ್ನು ಸ್ವಚ್ಛ ಸ್ಲೈಡ್‌ನ ಮೇಲೆ ನೀರಿನ ಹನಿಯಲ್ಲಿಡಿ, ಒಂದು ಹನಿ ಬಣ್ಣಕಾರಕ ಹಾಕಿ, ಒಂದು ನಿಮಿಷ ಕಾದು ಹೆಚ್ಚುವರಿ ಬಣ್ಣ ತೆಗೆಯಿರಿ."},{"en":"Add a drop of glycerine and lower a cover slip slowly with a needle so no air bubbles are trapped.","hi":"ग्लिसरीन की एक बूँद डालें और सुई की सहायता से कवर स्लिप धीरे से रखें ताकि हवा के बुलबुले न फँसें।","kn":"ಒಂದು ಹನಿ ಗ್ಲಿಸರಿನ್ ಹಾಕಿ, ಗಾಳಿಗುಳ್ಳೆ ಸಿಕ್ಕಿಬೀಳದಂತೆ ಸೂಜಿಯ ಸಹಾಯದಿಂದ ಕವರ್ ಸ್ಲಿಪ್ ನಿಧಾನವಾಗಿ ಇಳಿಸಿ."},{"en":"Wipe off extra liquid with blotting paper and put the slide on the stage of the microscope.","hi":"अतिरिक्त द्रव सोख्ता कागज़ से पोंछें और स्लाइड सूक्ष्मदर्शी के मंच पर रखें।","kn":"ಹೆಚ್ಚುವರಿ ದ್ರವವನ್ನು ಒತ್ತುಕಾಗದದಿಂದ ಒರೆಸಿ, ಸ್ಲೈಡನ್ನು ಸೂಕ್ಷ್ಮದರ್ಶಕದ ವೇದಿಕೆಯ ಮೇಲಿಡಿ."},{"en":"Focus first under low power (10×) with the coarse knob, then sharpen with the fine knob.","hi":"पहले कम क्षमता (10×) पर मोटे समायोजक से फोकस करें, फिर बारीक समायोजक से स्पष्ट करें।","kn":"ಮೊದಲು ಕಡಿಮೆ ವರ್ಧನೆಯಲ್ಲಿ (10×) ಒರಟು ತಿರುಗುಗುಬ್ಬಿಯಿಂದ ಕೇಂದ್ರೀಕರಿಸಿ, ನಂತರ ಸೂಕ್ಷ್ಮ ತಿರುಗುಗುಬ್ಬಿಯಿಂದ ಸ್ಪಷ್ಟಪಡಿಸಿ."},{"en":"Change to high power (40×) and focus with the fine knob only.","hi":"उच्च क्षमता (40×) पर जाएँ और केवल बारीक समायोजक से फोकस करें।","kn":"ಹೆಚ್ಚಿನ ವರ್ಧನೆಗೆ (40×) ಬದಲಿಸಿ, ಸೂಕ್ಷ್ಮ ತಿರುಗುಗುಬ್ಬಿಯಿಂದ ಮಾತ್ರ ಕೇಂದ್ರೀಕರಿಸಿ."},{"en":"Draw what you see and label the parts.","hi":"जो दिखे उसका चित्र बनाकर भागों को नामांकित करें।","kn":"ಕಂಡದ್ದರ ಚಿತ್ರ ಬಿಡಿಸಿ ಭಾಗಗಳನ್ನು ಗುರುತಿಸಿ."}],"precautions":[{"en":"Take a thin peel and do not let it fold.","hi":"पतली झिल्ली लें और उसे मुड़ने न दें।","kn":"ತೆಳು ಸಿಪ್ಪೆ ತೆಗೆದುಕೊಳ್ಳಿ, ಅದು ಮಡಚದಂತೆ ನೋಡಿ."},{"en":"Avoid air bubbles under the cover slip.","hi":"कवर स्लिप के नीचे हवा के बुलबुले न आने दें।","kn":"ಕವರ್ ಸ್ಲಿಪ್ ಕೆಳಗೆ ಗಾಳಿಗುಳ್ಳೆ ಬಾರದಂತೆ ನೋಡಿ."},{"en":"Do not use too much stain.","hi":"बहुत अधिक अभिरंजक न डालें।","kn":"ಹೆಚ್ಚು ಬಣ್ಣಕಾರಕ ಬಳಸಬೇಡಿ."},{"en":"Never lower the objective towards the slide while looking through the eyepiece.","hi":"नेत्रिका से देखते समय अभिदृश्यक को कभी स्लाइड की ओर नीचे न करें।","kn":"ನೇತ್ರಕದ ಮೂಲಕ ನೋಡುತ್ತಿರುವಾಗ ವಸ್ತುಕವನ್ನು ಸ್ಲೈಡ್‌ನ ಕಡೆಗೆ ಎಂದೂ ಇಳಿಸಬೇಡಿ."}],"conclusion":{"en":"Onion cells are brick-shaped with a cell wall, a nucleus and a large vacuole. Cheek cells are flat and irregular, with a nucleus but no cell wall. A leaf peel shows stomata: pores between two bean-shaped guard cells that contain chloroplasts. Yeast cells are oval, and some have buds growing from them.","hi":"प्याज़ की कोशिकाएँ ईंट जैसी होती हैं, जिनमें कोशिका भित्ति, केंद्रक और बड़ी रसधानी होती है। गाल की कोशिकाएँ चपटी और अनियमित होती हैं, केंद्रक होता है पर कोशिका भित्ति नहीं। पत्ती की झिल्ली में रंध्र दिखते हैं: दो सेम जैसी द्वार कोशिकाओं के बीच छिद्र, जिनमें हरितलवक होते हैं। यीस्ट की कोशिकाएँ अंडाकार होती हैं और कुछ पर मुकुल उगते दिखते हैं।","kn":"ಈರುಳ್ಳಿ ಕೋಶಗಳು ಇಟ್ಟಿಗೆ ಆಕಾರದವು; ಕೋಶಭಿತ್ತಿ, ಕೋಶಕೇಂದ್ರ ಮತ್ತು ದೊಡ್ಡ ರಸದಾನಿ ಇವೆ. ಕೆನ್ನೆಯ ಕೋಶಗಳು ಚಪ್ಪಟೆ, ಅನಿಯಮಿತ; ಕೋಶಕೇಂದ್ರ ಇದೆ, ಕೋಶಭಿತ್ತಿ ಇಲ್ಲ. ಎಲೆಯ ಸಿಪ್ಪೆಯಲ್ಲಿ ಪತ್ರರಂಧ್ರಗಳು: ಹರಿತ್ತಿಲಗಳಿರುವ ಎರಡು ಅವರೆಬೀಜಾಕಾರದ ಕಾವಲು ಕೋಶಗಳ ನಡುವಿನ ರಂಧ್ರ. ಯೀಸ್ಟ್ ಕೋಶಗಳು ಅಂಡಾಕಾರ; ಕೆಲವುಗಳಿಂದ ಮೊಗ್ಗುಗಳು ಬೆಳೆಯುತ್ತಿರುತ್ತವೆ."},"viva":[{"q":{"en":"Why is glycerine added to the slide?","hi":"स्लाइड पर ग्लिसरीन क्यों डाली जाती है?","kn":"ಸ್ಲೈಡ್‌ಗೆ ಗ್ಲಿಸರಿನ್ ಏಕೆ ಹಾಕುತ್ತಾರೆ?"},"a":{"en":"To stop the specimen from drying out.","hi":"ताकि नमूना सूखे नहीं।","kn":"ಮಾದರಿ ಒಣಗದಂತೆ ತಡೆಯಲು."}},{"q":{"en":"Which stain is used for onion peel?","hi":"प्याज़ की झिल्ली के लिए कौन-सा अभिरंजक प्रयोग होता है?","kn":"ಈರುಳ್ಳಿ ಸಿಪ್ಪೆಗೆ ಯಾವ ಬಣ್ಣಕಾರಕ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"Safranin.","hi":"सेफ्रानिन।","kn":"ಸಫ್ರಾನಿನ್."}},{"q":{"en":"Name two differences between the onion cells and the cheek cells you saw.","hi":"प्याज़ और गाल की कोशिकाओं में आपने कौन-से दो अंतर देखे?","kn":"ನೀವು ನೋಡಿದ ಈರುಳ್ಳಿ ಮತ್ತು ಕೆನ್ನೆಯ ಕೋಶಗಳ ಎರಡು ವ್ಯತ್ಯಾಸ ತಿಳಿಸಿ."},"a":{"en":"Onion cells have a cell wall and a large vacuole; cheek cells have neither.","hi":"प्याज़ की कोशिकाओं में कोशिका भित्ति और बड़ी रसधानी होती है; गाल की कोशिकाओं में दोनों नहीं।","kn":"ಈರುಳ್ಳಿ ಕೋಶಗಳಿಗೆ ಕೋಶಭಿತ್ತಿ ಮತ್ತು ದೊಡ್ಡ ರಸದಾನಿ ಇವೆ; ಕೆನ್ನೆಯ ಕೋಶಗಳಿಗೆ ಎರಡೂ ಇಲ್ಲ."}},{"q":{"en":"What do stomata do?","hi":"रंध्र क्या करते हैं?","kn":"ಪತ್ರರಂಧ್ರಗಳು ಏನು ಮಾಡುತ್ತವೆ?"},"a":{"en":"They let gases in and out of the leaf and let water vapour escape (transpiration).","hi":"वे पत्ती में गैसों को आने-जाने देते हैं और जलवाष्प को बाहर निकलने देते हैं (वाष्पोत्सर्जन)।","kn":"ಅವು ಎಲೆಯೊಳಗೆ ಅನಿಲಗಳು ಬಂದು ಹೋಗಲು ಮತ್ತು ನೀರಾವಿ ಹೊರಹೋಗಲು (ಬಾಷ್ಪವಿಸರ್ಜನೆ) ಅವಕಾಶ ನೀಡುತ್ತವೆ."}},{"q":{"en":"What is budding in yeast?","hi":"यीस्ट में मुकुलन क्या है?","kn":"ಯೀಸ್ಟ್‌ನಲ್ಲಿ ಮೊಗ್ಗುವಿಕೆ ಎಂದರೇನು?"},"a":{"en":"A small bud grows out of the parent cell and later separates: asexual reproduction.","hi":"जनक कोशिका से एक छोटा मुकुल निकलता है जो बाद में अलग हो जाता है: अलैंगिक जनन।","kn":"ಪೋಷಕ ಕೋಶದಿಂದ ಚಿಕ್ಕ ಮೊಗ್ಗು ಬೆಳೆದು ನಂತರ ಬೇರ್ಪಡುತ್ತದೆ: ಅಲೈಂಗಿಕ ಸಂತಾನೋತ್ಪತ್ತಿ."}}]},{"id":"probability","bench":"probability","setup":{},"subject":"Mathematics","domain":"maths","levels":["8","9","10","11"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["probability","chance","coin","dice","die","data handling","statistics","experimental probability"],"title":{"en":"Probability with coins and dice","hi":"सिक्के और पासे से प्रायिकता","kn":"ನಾಣ್ಯ ಮತ್ತು ದಾಳದೊಂದಿಗೆ ಸಂಭವನೀಯತೆ"},"summary":{"en":"Toss a coin or throw a die hundreds of times and watch the experimental probability settle down.","hi":"सिक्का सैकड़ों बार उछालें या पासा फेंकें और देखें कि प्रायोगिक प्रायिकता कैसे स्थिर होती जाती है।","kn":"ನಾಣ್ಯವನ್ನು ನೂರಾರು ಬಾರಿ ಚಿಮ್ಮಿಸಿ ಅಥವಾ ದಾಳ ಎಸೆದು, ಪ್ರಾಯೋಗಿಕ ಸಂಭವನೀಯತೆ ಹೇಗೆ ಸ್ಥಿರವಾಗುತ್ತದೆ ನೋಡಿ."},"aim":{"en":"To toss a coin and throw a die many times, and to compare the experimental probability with the theoretical probability.","hi":"सिक्के को कई बार उछालकर और पासे को कई बार फेंककर प्रायोगिक प्रायिकता की तुलना सैद्धांतिक प्रायिकता से करना।","kn":"ನಾಣ್ಯವನ್ನು ಹಲವು ಬಾರಿ ಚಿಮ್ಮಿಸಿ ಮತ್ತು ದಾಳವನ್ನು ಹಲವು ಬಾರಿ ಎಸೆದು, ಪ್ರಾಯೋಗಿಕ ಸಂಭವನೀಯತೆಯನ್ನು ಸೈದ್ಧಾಂತಿಕ ಸಂಭವನೀಯತೆಯೊಂದಿಗೆ ಹೋಲಿಸುವುದು."},"principle":{"en":"Experimental probability of an event = number of times it happened ÷ number of trials. The theoretical probability of a head is 1/2 and of any one face of a die is 1/6. The more trials we make, the closer the experimental value usually comes to the theoretical one.","hi":"किसी घटना की प्रायोगिक प्रायिकता = घटना कितनी बार हुई ÷ कुल प्रयास। चित आने की सैद्धांतिक प्रायिकता 1/2 और पासे के किसी एक फलक की 1/6 है। जितने अधिक प्रयास करें, प्रायोगिक मान प्रायः सैद्धांतिक मान के उतना ही पास आता है।","kn":"ಒಂದು ಘಟನೆಯ ಪ್ರಾಯೋಗಿಕ ಸಂಭವನೀಯತೆ = ಘಟನೆ ನಡೆದ ಬಾರಿಗಳು ÷ ಒಟ್ಟು ಪ್ರಯತ್ನಗಳು. ಶಿರ ಬರುವ ಸೈದ್ಧಾಂತಿಕ ಸಂಭವನೀಯತೆ 1/2, ದಾಳದ ಯಾವುದೇ ಒಂದು ಮುಖದ್ದು 1/6. ಪ್ರಯತ್ನಗಳು ಹೆಚ್ಚಿದಷ್ಟು ಪ್ರಾಯೋಗಿಕ ಬೆಲೆ ಸಾಮಾನ್ಯವಾಗಿ ಸೈದ್ಧಾಂತಿಕ ಬೆಲೆಗೆ ಹತ್ತಿರವಾಗುತ್ತದೆ."},"apparatus":[{"en":"A coin","hi":"एक सिक्का","kn":"ಒಂದು ನಾಣ್ಯ"},{"en":"A die","hi":"एक पासा","kn":"ಒಂದು ದಾಳ"},{"en":"Tally sheet and pencil","hi":"मिलान चिह्न तालिका और पेंसिल","kn":"ಗುರುತು ಹಾಳೆ ಮತ್ತು ಪೆನ್ಸಿಲ್"}],"steps":[{"en":"Toss the coin 10 times and tally the heads and tails.","hi":"सिक्के को 10 बार उछालें और चित-पट के मिलान चिह्न लगाएँ।","kn":"ನಾಣ್ಯವನ್ನು 10 ಬಾರಿ ಚಿಮ್ಮಿಸಿ ಶಿರ-ಪುಚ್ಛಗಳಿಗೆ ಗುರುತು ಹಾಕಿ."},{"en":"Work out the experimental probability of a head: heads ÷ tosses.","hi":"चित की प्रायोगिक प्रायिकता निकालें: चित ÷ उछालें।","kn":"ಶಿರದ ಪ್ರಾಯೋಗಿಕ ಸಂಭವನೀಯತೆ ಲೆಕ್ಕಿಸಿ: ಶಿರಗಳು ÷ ಚಿಮ್ಮುವಿಕೆಗಳು."},{"en":"Keep going to 50, 100, 500 and 1000 tosses (the lab can toss many at once) and record the probability each time.","hi":"50, 100, 500 और 1000 उछालों तक जारी रखें (प्रयोगशाला एक साथ कई बार उछाल सकती है) और हर बार प्रायिकता लिखें।","kn":"50, 100, 500 ಮತ್ತು 1000 ಚಿಮ್ಮುವಿಕೆಗಳವರೆಗೆ ಮುಂದುವರಿಸಿ (ಪ್ರಯೋಗಾಲಯ ಒಮ್ಮೆಗೆ ಹಲವು ಬಾರಿ ಚಿಮ್ಮಿಸಬಲ್ಲದು), ಪ್ರತಿ ಬಾರಿ ಸಂಭವನೀಯತೆ ದಾಖಲಿಸಿ."},{"en":"Compare each value with 1/2 and see how close it gets.","hi":"हर मान की तुलना 1/2 से करें और देखें वह कितना पास आता है।","kn":"ಪ್ರತಿ ಬೆಲೆಯನ್ನು 1/2 ರೊಂದಿಗೆ ಹೋಲಿಸಿ, ಎಷ್ಟು ಹತ್ತಿರ ಬರುತ್ತದೆ ನೋಡಿ."},{"en":"Throw the die 60 times and record how often each face shows.","hi":"पासे को 60 बार फेंकें और लिखें कि हर फलक कितनी बार आया।","kn":"ದಾಳವನ್ನು 60 ಬಾರಿ ಎಸೆದು ಪ್ರತಿ ಮುಖ ಎಷ್ಟು ಬಾರಿ ಬಂತು ದಾಖಲಿಸಿ."},{"en":"Find the experimental probability of each face and compare it with 1/6 ≈ 0.167.","hi":"हर फलक की प्रायोगिक प्रायिकता निकालें और 1/6 ≈ 0.167 से तुलना करें।","kn":"ಪ್ರತಿ ಮುಖದ ಪ್ರಾಯೋಗಿಕ ಸಂಭವನೀಯತೆ ಕಂಡುಹಿಡಿದು 1/6 ≈ 0.167 ರೊಂದಿಗೆ ಹೋಲಿಸಿ."},{"en":"Discuss why a small number of trials can give a result far from 1/2.","hi":"चर्चा करें कि कम प्रयासों में परिणाम 1/2 से दूर क्यों हो सकता है।","kn":"ಕಡಿಮೆ ಪ್ರಯತ್ನಗಳಲ್ಲಿ ಫಲಿತಾಂಶ 1/2 ರಿಂದ ಏಕೆ ದೂರವಿರಬಹುದು ಚರ್ಚಿಸಿ."}],"precautions":[{"en":"Toss the same way every time and let the coin land on its own.","hi":"हर बार एक ही तरह उछालें और सिक्के को अपने आप गिरने दें।","kn":"ಪ್ರತಿ ಬಾರಿ ಒಂದೇ ರೀತಿ ಚಿಮ್ಮಿಸಿ, ನಾಣ್ಯ ತಾನಾಗಿ ಬೀಳಲು ಬಿಡಿ."},{"en":"Count every trial, including the ones that look strange.","hi":"हर प्रयास गिनें, अजीब लगने वाले भी।","kn":"ವಿಚಿತ್ರ ಅನಿಸಿದವೂ ಸೇರಿ ಪ್ರತಿ ಪ್ರಯತ್ನ ಎಣಿಸಿ."}],"conclusion":{"en":"With few trials the experimental probability jumps around; with many trials it comes close to the theoretical value: about 1/2 for a head and about 1/6 for each face of a die.","hi":"कम प्रयासों में प्रायोगिक प्रायिकता बहुत बदलती है; अधिक प्रयासों में यह सैद्धांतिक मान के पास आ जाती है: चित के लिए लगभग 1/2 और पासे के हर फलक के लिए लगभग 1/6।","kn":"ಕಡಿಮೆ ಪ್ರಯತ್ನಗಳಲ್ಲಿ ಪ್ರಾಯೋಗಿಕ ಸಂಭವನೀಯತೆ ಏರುಪೇರಾಗುತ್ತದೆ; ಹೆಚ್ಚು ಪ್ರಯತ್ನಗಳಲ್ಲಿ ಅದು ಸೈದ್ಧಾಂತಿಕ ಬೆಲೆಗೆ ಹತ್ತಿರವಾಗುತ್ತದೆ: ಶಿರಕ್ಕೆ ಸುಮಾರು 1/2, ದಾಳದ ಪ್ರತಿ ಮುಖಕ್ಕೆ ಸುಮಾರು 1/6."},"viva":[{"q":{"en":"What is a trial?","hi":"प्रयास क्या है?","kn":"ಪ್ರಯತ್ನ ಎಂದರೇನು?"},"a":{"en":"Doing the experiment once, such as one toss of the coin.","hi":"प्रयोग को एक बार करना, जैसे सिक्के को एक बार उछालना।","kn":"ಪ್ರಯೋಗವನ್ನು ಒಮ್ಮೆ ಮಾಡುವುದು, ಉದಾ: ನಾಣ್ಯವನ್ನು ಒಮ್ಮೆ ಚಿಮ್ಮಿಸುವುದು."}},{"q":{"en":"What is the sum of the probabilities of all the outcomes?","hi":"सभी परिणामों की प्रायिकताओं का योग कितना होता है?","kn":"ಎಲ್ಲಾ ಫಲಿತಾಂಶಗಳ ಸಂಭವನೀಯತೆಗಳ ಮೊತ್ತ ಎಷ್ಟು?"},"a":{"en":"1.","hi":"1।","kn":"1."}},{"q":{"en":"What is the probability of an impossible event?","hi":"असंभव घटना की प्रायिकता कितनी होती है?","kn":"ಅಸಾಧ್ಯ ಘಟನೆಯ ಸಂಭವನೀಯತೆ ಎಷ್ಟು?"},"a":{"en":"0.","hi":"0।","kn":"0."}},{"q":{"en":"What is the probability of getting an even number on a die?","hi":"पासे पर सम संख्या आने की प्रायिकता क्या है?","kn":"ದಾಳದಲ್ಲಿ ಸಮಸಂಖ್ಯೆ ಬರುವ ಸಂಭವನೀಯತೆ ಎಷ್ಟು?"},"a":{"en":"3/6 = 1/2.","hi":"3/6 = 1/2।","kn":"3/6 = 1/2."}},{"q":{"en":"Will 100 tosses always give exactly 50 heads?","hi":"क्या 100 उछालों में हमेशा ठीक 50 चित आएँगे?","kn":"100 ಚಿಮ್ಮುವಿಕೆಗಳಲ್ಲಿ ಯಾವಾಗಲೂ ನಿಖರವಾಗಿ 50 ಶಿರ ಬರುತ್ತವೆಯೇ?"},"a":{"en":"No. It will usually be close to 50, but it can be a little more or less.","hi":"नहीं। प्रायः 50 के पास होगा, पर थोड़ा कम या अधिक भी हो सकता है।","kn":"ಇಲ್ಲ. ಸಾಮಾನ್ಯವಾಗಿ 50 ರ ಹತ್ತಿರವಿರುತ್ತದೆ, ಸ್ವಲ್ಪ ಹೆಚ್ಚು ಅಥವಾ ಕಡಿಮೆ ಇರಬಹುದು."}}]},{"id":"conductors","bench":"conductors","setup":{},"subject":"Physics","domain":"physics","levels":["6","7"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["electric circuit","circuits","circuit","conductors","insulators","electricity and circuits","electric current and its effects","components","bulb"],"title":{"en":"Conductors and insulators","hi":"चालक और विद्युतरोधी","kn":"ವಾಹಕಗಳು ಮತ್ತು ಅವಾಹಕಗಳು"},"summary":{"en":"Put everyday objects in the gap of a bulb circuit and see which ones let the current through.","hi":"बल्ब वाले परिपथ के खाली स्थान में रोज़ की चीज़ें रखें और देखें कि कौन-सी धारा को जाने देती हैं।","kn":"ಬಲ್ಬ್ ಇರುವ ಮಂಡಲದ ಅಂತರದಲ್ಲಿ ದಿನನಿತ್ಯದ ವಸ್ತುಗಳನ್ನಿಟ್ಟು, ಯಾವುವು ವಿದ್ಯುತ್ ಹರಿಯಲು ಬಿಡುತ್ತವೆ ನೋಡಿ."},"aim":{"en":"To find out which materials allow electricity to pass through them (conductors) and which do not (insulators), using a simple circuit with a bulb.","hi":"बल्ब वाले सरल परिपथ की सहायता से पता लगाना कि कौन-से पदार्थ विद्युत को अपने में से जाने देते हैं (चालक) और कौन-से नहीं (विद्युतरोधी)।","kn":"ಬಲ್ಬ್ ಇರುವ ಸರಳ ಮಂಡಲದ ಸಹಾಯದಿಂದ ಯಾವ ವಸ್ತುಗಳು ವಿದ್ಯುತ್ ಹರಿಯಲು ಬಿಡುತ್ತವೆ (ವಾಹಕಗಳು), ಯಾವುವು ಬಿಡುವುದಿಲ್ಲ (ಅವಾಹಕಗಳು) ಎಂದು ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"A bulb glows only when there is a complete path (a closed circuit) for the current from one terminal of the cell, through the bulb, back to the other terminal. An object placed in a gap completes the path only if it conducts electricity. Metals are good conductors; plastic, wood, rubber, glass and paper are insulators. Graphite (pencil lead) is a non-metal that conducts.","hi":"बल्ब तभी जलता है जब धारा के लिए सेल के एक सिरे से बल्ब होते हुए दूसरे सिरे तक पूरा रास्ता (बंद परिपथ) हो। खाली स्थान में रखी वस्तु रास्ता तभी पूरा करती है जब वह विद्युत की चालक हो। धातुएँ अच्छी चालक हैं; प्लास्टिक, लकड़ी, रबर, काँच और कागज़ विद्युतरोधी हैं। ग्रेफ़ाइट (पेंसिल की लीड) एक अधातु है जो विद्युत चालक है।","kn":"ಕೋಶದ ಒಂದು ತುದಿಯಿಂದ ಬಲ್ಬ್ ಮೂಲಕ ಇನ್ನೊಂದು ತುದಿಗೆ ಪ್ರವಾಹಕ್ಕೆ ಪೂರ್ಣ ದಾರಿ (ಮುಚ್ಚಿದ ಮಂಡಲ) ಇದ್ದಾಗ ಮಾತ್ರ ಬಲ್ಬ್ ಬೆಳಗುತ್ತದೆ. ಅಂತರದಲ್ಲಿಟ್ಟ ವಸ್ತು ವಿದ್ಯುತ್ ವಾಹಕವಾಗಿದ್ದರೆ ಮಾತ್ರ ದಾರಿ ಪೂರ್ಣಗೊಳಿಸುತ್ತದೆ. ಲೋಹಗಳು ಉತ್ತಮ ವಾಹಕಗಳು; ಪ್ಲಾಸ್ಟಿಕ್, ಮರ, ರಬ್ಬರ್, ಗಾಜು ಮತ್ತು ಕಾಗದ ಅವಾಹಕಗಳು. ಗ್ರಾಫೈಟ್ (ಪೆನ್ಸಿಲ್ ಸೀಸ) ವಿದ್ಯುತ್ ವಾಹಕವಾದ ಅಲೋಹ."},"apparatus":[{"en":"A cell in a holder","hi":"होल्डर में एक सेल","kn":"ಹಿಡಿಕೆಯಲ್ಲಿ ಒಂದು ಕೋಶ"},{"en":"Bulb in a holder","hi":"होल्डर में बल्ब","kn":"ಹಿಡಿಕೆಯಲ್ಲಿ ಬಲ್ಬ್"},{"en":"Switch","hi":"स्विच","kn":"ಸ್ವಿಚ್"},{"en":"Connecting wires with clips","hi":"क्लिप वाले संयोजक तार","kn":"ಕ್ಲಿಪ್ ಇರುವ ಸಂಪರ್ಕ ತಂತಿಗಳು"},{"en":"Objects to test: iron nail, copper wire, aluminium foil, coin, pencil lead, plastic scale, eraser, wooden stick, glass rod, paper","hi":"परखने की वस्तुएँ: लोहे की कील, ताँबे का तार, ऐलुमिनियम पन्नी, सिक्का, पेंसिल की लीड, प्लास्टिक का पैमाना, रबड़, लकड़ी की डंडी, काँच की छड़, कागज़","kn":"ಪರೀಕ್ಷಿಸಲು ವಸ್ತುಗಳು: ಕಬ್ಬಿಣದ ಮೊಳೆ, ತಾಮ್ರದ ತಂತಿ, ಅಲ್ಯೂಮಿನಿಯಂ ಹಾಳೆ, ನಾಣ್ಯ, ಪೆನ್ಸಿಲ್ ಸೀಸ, ಪ್ಲಾಸ್ಟಿಕ್ ಅಳತೆಪಟ್ಟಿ, ರಬ್ಬರ್, ಮರದ ಕಡ್ಡಿ, ಗಾಜಿನ ಕಡ್ಡಿ, ಕಾಗದ"}],"steps":[{"en":"Join the cell, switch and bulb with wires, leaving a gap between two free clips.","hi":"सेल, स्विच और बल्ब को तारों से जोड़ें, दो खुली क्लिपों के बीच खाली स्थान छोड़ें।","kn":"ಕೋಶ, ಸ್ವಿಚ್ ಮತ್ತು ಬಲ್ಬ್ ಅನ್ನು ತಂತಿಗಳಿಂದ ಜೋಡಿಸಿ, ಎರಡು ಬಿಡಿ ಕ್ಲಿಪ್‌ಗಳ ನಡುವೆ ಅಂತರ ಬಿಡಿ."},{"en":"Touch the two clips together and switch on. The bulb should glow: the circuit works.","hi":"दोनों क्लिपें आपस में छुआकर स्विच चालू करें। बल्ब जलना चाहिए: परिपथ ठीक है।","kn":"ಎರಡು ಕ್ಲಿಪ್‌ಗಳನ್ನು ಸ್ಪರ್ಶಿಸಿ ಸ್ವಿಚ್ ಆನ್ ಮಾಡಿ. ಬಲ್ಬ್ ಬೆಳಗಬೇಕು: ಮಂಡಲ ಸರಿಯಾಗಿದೆ."},{"en":"Switch off. Clip the first object into the gap.","hi":"स्विच बंद करें। पहली वस्तु को खाली स्थान में क्लिप करें।","kn":"ಸ್ವಿಚ್ ಆಫ್ ಮಾಡಿ. ಮೊದಲ ವಸ್ತುವನ್ನು ಅಂತರದಲ್ಲಿ ಕ್ಲಿಪ್ ಮಾಡಿ."},{"en":"Switch on and see whether the bulb glows.","hi":"स्विच चालू करें और देखें कि बल्ब जलता है या नहीं।","kn":"ಸ್ವಿಚ್ ಆನ್ ಮಾಡಿ, ಬಲ್ಬ್ ಬೆಳಗುತ್ತದೆಯೇ ನೋಡಿ."},{"en":"Record the object and whether it is a conductor or an insulator.","hi":"वस्तु और उसका चालक या विद्युतरोधी होना लिखें।","kn":"ವಸ್ತು ಮತ್ತು ಅದು ವಾಹಕವೋ ಅವಾಹಕವೋ ದಾಖಲಿಸಿ."},{"en":"Repeat for every object.","hi":"हर वस्तु के लिए दोहराएँ।","kn":"ಪ್ರತಿ ವಸ್ತುವಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Sort the objects into conductors and insulators and look for what the conductors have in common.","hi":"वस्तुओं को चालक और विद्युतरोधी में बाँटें और देखें कि चालकों में क्या समान है।","kn":"ವಸ್ತುಗಳನ್ನು ವಾಹಕ ಮತ್ತು ಅವಾಹಕಗಳಾಗಿ ವಿಂಗಡಿಸಿ, ವಾಹಕಗಳಲ್ಲಿ ಸಾಮಾನ್ಯವಾದುದೇನು ನೋಡಿ."}],"precautions":[{"en":"Never use the electricity from a wall socket for experiments: it can kill.","hi":"प्रयोगों में दीवार के सॉकेट की बिजली कभी न लें: यह जानलेवा हो सकती है।","kn":"ಪ್ರಯೋಗಗಳಿಗೆ ಗೋಡೆಯ ಸಾಕೆಟ್‌ನ ವಿದ್ಯುತ್ ಎಂದೂ ಬಳಸಬೇಡಿ: ಅದು ಪ್ರಾಣಾಪಾಯಕಾರಿ."},{"en":"Do not join the two ends of the cell directly with a wire; the cell gets used up quickly.","hi":"सेल के दोनों सिरों को सीधे तार से न जोड़ें; सेल जल्दी खत्म हो जाता है।","kn":"ಕೋಶದ ಎರಡೂ ತುದಿಗಳನ್ನು ನೇರವಾಗಿ ತಂತಿಯಿಂದ ಜೋಡಿಸಬೇಡಿ; ಕೋಶ ಬೇಗ ಖಾಲಿಯಾಗುತ್ತದೆ."},{"en":"Switch off before changing the object.","hi":"वस्तु बदलने से पहले स्विच बंद करें।","kn":"ವಸ್ತು ಬದಲಿಸುವ ಮೊದಲು ಸ್ವಿಚ್ ಆಫ್ ಮಾಡಿ."}],"conclusion":{"en":"The bulb glows with the iron nail, copper wire, aluminium foil, coin and pencil lead: these are conductors. It does not glow with plastic, rubber, wood, glass or paper: these are insulators. Metals conduct electricity; so does graphite, a non-metal.","hi":"लोहे की कील, ताँबे का तार, ऐलुमिनियम पन्नी, सिक्का और पेंसिल की लीड से बल्ब जलता है: ये चालक हैं। प्लास्टिक, रबड़, लकड़ी, काँच या कागज़ से नहीं जलता: ये विद्युतरोधी हैं। धातुएँ विद्युत की चालक हैं; ग्रेफ़ाइट भी, जो एक अधातु है।","kn":"ಕಬ್ಬಿಣದ ಮೊಳೆ, ತಾಮ್ರದ ತಂತಿ, ಅಲ್ಯೂಮಿನಿಯಂ ಹಾಳೆ, ನಾಣ್ಯ ಮತ್ತು ಪೆನ್ಸಿಲ್ ಸೀಸದಿಂದ ಬಲ್ಬ್ ಬೆಳಗುತ್ತದೆ: ಇವು ವಾಹಕಗಳು. ಪ್ಲಾಸ್ಟಿಕ್, ರಬ್ಬರ್, ಮರ, ಗಾಜು ಅಥವಾ ಕಾಗದದಿಂದ ಬೆಳಗದು: ಇವು ಅವಾಹಕಗಳು. ಲೋಹಗಳು ವಿದ್ಯುತ್ ವಾಹಕಗಳು; ಅಲೋಹವಾದ ಗ್ರಾಫೈಟ್ ಕೂಡ."},"viva":[{"q":{"en":"What is a closed circuit?","hi":"बंद परिपथ क्या है?","kn":"ಮುಚ್ಚಿದ ಮಂಡಲ ಎಂದರೇನು?"},"a":{"en":"A complete path for current from one terminal of the cell back to the other.","hi":"सेल के एक सिरे से दूसरे सिरे तक धारा का पूरा रास्ता।","kn":"ಕೋಶದ ಒಂದು ತುದಿಯಿಂದ ಇನ್ನೊಂದಕ್ಕೆ ಪ್ರವಾಹದ ಪೂರ್ಣ ದಾರಿ."}},{"q":{"en":"Why are electric wires covered with plastic?","hi":"बिजली के तारों पर प्लास्टिक क्यों चढ़ा होता है?","kn":"ವಿದ್ಯುತ್ ತಂತಿಗಳಿಗೆ ಪ್ಲಾಸ್ಟಿಕ್ ಹೊದಿಕೆ ಏಕೆ?"},"a":{"en":"Plastic is an insulator, so it keeps us safe from shocks.","hi":"प्लास्टिक विद्युतरोधी है, इसलिए झटके से बचाता है।","kn":"ಪ್ಲಾಸ್ಟಿಕ್ ಅವಾಹಕ, ಆದ್ದರಿಂದ ವಿದ್ಯುತ್ ಆಘಾತದಿಂದ ರಕ್ಷಿಸುತ್ತದೆ."}},{"q":{"en":"Name a non-metal that conducts electricity.","hi":"विद्युत की चालक एक अधातु का नाम बताइए।","kn":"ವಿದ್ಯುತ್ ವಾಹಕವಾದ ಒಂದು ಅಲೋಹವನ್ನು ಹೆಸರಿಸಿ."},"a":{"en":"Graphite (pencil lead).","hi":"ग्रेफ़ाइट (पेंसिल की लीड)।","kn":"ಗ್ರಾಫೈಟ್ (ಪೆನ್ಸಿಲ್ ಸೀಸ)."}},{"q":{"en":"The bulb does not glow even with a copper wire in the gap. Give two possible reasons.","hi":"खाली स्थान में ताँबे का तार होने पर भी बल्ब नहीं जलता। दो संभव कारण बताइए।","kn":"ಅಂತರದಲ್ಲಿ ತಾಮ್ರದ ತಂತಿ ಇದ್ದರೂ ಬಲ್ಬ್ ಬೆಳಗದು. ಎರಡು ಸಂಭವನೀಯ ಕಾರಣ ತಿಳಿಸಿ."},"a":{"en":"The bulb may be fused, the cell may be used up, or a connection may be loose.","hi":"बल्ब फ़्यूज़ हो सकता है, सेल खत्म हो सकता है, या कोई संयोजन ढीला हो सकता है।","kn":"ಬಲ್ಬ್ ಸುಟ್ಟಿರಬಹುದು, ಕೋಶ ಖಾಲಿಯಾಗಿರಬಹುದು ಅಥವಾ ಸಂಪರ್ಕ ಸಡಿಲವಾಗಿರಬಹುದು."}},{"q":{"en":"Why do electricians use screwdrivers with plastic or rubber handles?","hi":"बिजली मिस्त्री प्लास्टिक या रबर के हत्थे वाले पेचकस क्यों प्रयोग करते हैं?","kn":"ವಿದ್ಯುತ್ ಕೆಲಸಗಾರರು ಪ್ಲಾಸ್ಟಿಕ್ ಅಥವಾ ರಬ್ಬರ್ ಹಿಡಿಕೆಯ ಸ್ಕ್ರೂಡ್ರೈವರ್ ಏಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"The handle is an insulator, so current cannot pass into their hands.","hi":"हत्था विद्युतरोधी है, इसलिए धारा उनके हाथों में नहीं जा सकती।","kn":"ಹಿಡಿಕೆ ಅವಾಹಕ, ಆದ್ದರಿಂದ ಪ್ರವಾಹ ಅವರ ಕೈಗೆ ಹರಿಯದು."}}]},{"id":"magnets","bench":"magnets","setup":{},"subject":"Physics","domain":"physics","levels":["6","10"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["magnet","magnets","exploring magnets","fun with magnets","magnetic","poles","compass","magnetic field","magnetic effects of electric current","magnetic and heating effects","magnetism"],"title":{"en":"Magnets and their poles","hi":"चुंबक और उनके ध्रुव","kn":"ಕಾಂತಗಳು ಮತ್ತು ಅವುಗಳ ಧ್ರುವಗಳು"},"summary":{"en":"Test which objects a magnet pulls, bring poles together, and see the field with iron filings.","hi":"परखें कि चुंबक किन वस्तुओं को खींचता है, ध्रुवों को पास लाएँ, और लौह-चूर्ण से क्षेत्र देखें।","kn":"ಕಾಂತ ಯಾವ ವಸ್ತುಗಳನ್ನು ಆಕರ್ಷಿಸುತ್ತದೆ ಪರೀಕ್ಷಿಸಿ, ಧ್ರುವಗಳನ್ನು ಹತ್ತಿರ ತನ್ನಿ, ಕಬ್ಬಿಣದ ಪುಡಿಯಿಂದ ಕ್ಷೇತ್ರ ನೋಡಿ."},"aim":{"en":"To find which materials are magnetic, to show that like poles repel and unlike poles attract, and to see the pattern of the magnetic field around a bar magnet.","hi":"पता लगाना कि कौन-से पदार्थ चुंबकीय हैं, दिखाना कि समान ध्रुव प्रतिकर्षित और असमान ध्रुव आकर्षित करते हैं, और छड़ चुंबक के चारों ओर चुंबकीय क्षेत्र का पैटर्न देखना।","kn":"ಯಾವ ವಸ್ತುಗಳು ಕಾಂತೀಯ ಎಂದು ಕಂಡುಹಿಡಿಯುವುದು, ಸಜಾತೀಯ ಧ್ರುವಗಳು ವಿಕರ್ಷಿಸಿ ವಿಜಾತೀಯ ಧ್ರುವಗಳು ಆಕರ್ಷಿಸುತ್ತವೆ ಎಂದು ತೋರಿಸುವುದು, ದಂಡಕಾಂತದ ಸುತ್ತಲಿನ ಕಾಂತಕ್ಷೇತ್ರದ ಮಾದರಿ ನೋಡುವುದು."},"principle":{"en":"A magnet attracts iron, nickel and cobalt (magnetic materials) but not wood, plastic, glass, copper, aluminium or brass. Every magnet has a north and a south pole; like poles repel and unlike poles attract. Iron filings line up along the magnetic field lines, which run from the north pole to the south pole outside the magnet.","hi":"चुंबक लोहा, निकल और कोबाल्ट (चुंबकीय पदार्थ) को आकर्षित करता है, पर लकड़ी, प्लास्टिक, काँच, ताँबा, ऐलुमिनियम या पीतल को नहीं। हर चुंबक में उत्तर और दक्षिण ध्रुव होते हैं; समान ध्रुव प्रतिकर्षित और असमान ध्रुव आकर्षित करते हैं। लौह-चूर्ण चुंबकीय क्षेत्र रेखाओं के साथ सज जाता है, जो चुंबक के बाहर उत्तर ध्रुव से दक्षिण ध्रुव की ओर जाती हैं।","kn":"ಕಾಂತ ಕಬ್ಬಿಣ, ನಿಕ್ಕಲ್ ಮತ್ತು ಕೋಬಾಲ್ಟ್ (ಕಾಂತೀಯ ವಸ್ತುಗಳು) ಆಕರ್ಷಿಸುತ್ತದೆ, ಮರ, ಪ್ಲಾಸ್ಟಿಕ್, ಗಾಜು, ತಾಮ್ರ, ಅಲ್ಯೂಮಿನಿಯಂ ಅಥವಾ ಹಿತ್ತಾಳೆಯನ್ನಲ್ಲ. ಪ್ರತಿ ಕಾಂತಕ್ಕೆ ಉತ್ತರ ಮತ್ತು ದಕ್ಷಿಣ ಧ್ರುವಗಳಿವೆ; ಸಜಾತೀಯ ಧ್ರುವಗಳು ವಿಕರ್ಷಿಸುತ್ತವೆ, ವಿಜಾತೀಯ ಧ್ರುವಗಳು ಆಕರ್ಷಿಸುತ್ತವೆ. ಕಬ್ಬಿಣದ ಪುಡಿ ಕಾಂತಕ್ಷೇತ್ರ ರೇಖೆಗಳ ಉದ್ದಕ್ಕೂ ಜೋಡಿಸಿಕೊಳ್ಳುತ್ತದೆ; ಅವು ಕಾಂತದ ಹೊರಗೆ ಉತ್ತರ ಧ್ರುವದಿಂದ ದಕ್ಷಿಣ ಧ್ರುವಕ್ಕೆ ಸಾಗುತ್ತವೆ."},"apparatus":[{"en":"Two bar magnets with poles marked","hi":"ध्रुव अंकित दो छड़ चुंबक","kn":"ಧ್ರುವ ಗುರುತಿಸಿದ ಎರಡು ದಂಡಕಾಂತಗಳು"},{"en":"A small compass","hi":"एक छोटा कम्पास","kn":"ಒಂದು ಚಿಕ್ಕ ದಿಕ್ಸೂಚಿ"},{"en":"Iron filings and a sheet of paper","hi":"लौह-चूर्ण और एक कागज़","kn":"ಕಬ್ಬಿಣದ ಪುಡಿ ಮತ್ತು ಒಂದು ಹಾಳೆ"},{"en":"Objects: iron nail, steel spoon, pin, coin, rubber, plastic comb, wooden pencil, glass marble, aluminium foil, copper wire","hi":"वस्तुएँ: लोहे की कील, स्टील का चम्मच, पिन, सिक्का, रबड़, प्लास्टिक की कंघी, लकड़ी की पेंसिल, काँच की गोली, ऐलुमिनियम पन्नी, ताँबे का तार","kn":"ವಸ್ತುಗಳು: ಕಬ್ಬಿಣದ ಮೊಳೆ, ಉಕ್ಕಿನ ಚಮಚ, ಪಿನ್, ನಾಣ್ಯ, ರಬ್ಬರ್, ಪ್ಲಾಸ್ಟಿಕ್ ಬಾಚಣಿಗೆ, ಮರದ ಪೆನ್ಸಿಲ್, ಗಾಜಿನ ಗೋಲಿ, ಅಲ್ಯೂಮಿನಿಯಂ ಹಾಳೆ, ತಾಮ್ರದ ತಂತಿ"}],"steps":[{"en":"Bring a magnet close to each object in turn. Note whether it is pulled towards the magnet.","hi":"चुंबक को बारी-बारी से हर वस्तु के पास लाएँ। लिखें कि वह चुंबक की ओर खिंचती है या नहीं।","kn":"ಕಾಂತವನ್ನು ಒಂದೊಂದಾಗಿ ಪ್ರತಿ ವಸ್ತುವಿನ ಹತ್ತಿರ ತನ್ನಿ. ಅದು ಕಾಂತದ ಕಡೆ ಸೆಳೆಯಲ್ಪಡುತ್ತದೆಯೇ ಬರೆಯಿರಿ."},{"en":"Sort the objects into magnetic and non-magnetic.","hi":"वस्तुओं को चुंबकीय और अचुंबकीय में बाँटें।","kn":"ವಸ್ತುಗಳನ್ನು ಕಾಂತೀಯ ಮತ್ತು ಅಕಾಂತೀಯ ಎಂದು ವಿಂಗಡಿಸಿ."},{"en":"Place one magnet on a smooth surface. Bring the north pole of the second magnet near its north pole, then near its south pole.","hi":"एक चुंबक को चिकनी सतह पर रखें। दूसरे चुंबक का उत्तर ध्रुव उसके उत्तर ध्रुव के पास, फिर दक्षिण ध्रुव के पास लाएँ।","kn":"ಒಂದು ಕಾಂತವನ್ನು ನಯವಾದ ಮೇಲ್ಮೈ ಮೇಲಿಡಿ. ಎರಡನೇ ಕಾಂತದ ಉತ್ತರ ಧ್ರುವವನ್ನು ಅದರ ಉತ್ತರ ಧ್ರುವದ ಬಳಿ, ನಂತರ ದಕ್ಷಿಣ ಧ್ರುವದ ಬಳಿ ತನ್ನಿ."},{"en":"Note when the magnets pull together and when they push apart.","hi":"लिखें कि चुंबक कब एक-दूसरे को खींचते हैं और कब दूर धकेलते हैं।","kn":"ಕಾಂತಗಳು ಯಾವಾಗ ಒಂದನ್ನೊಂದು ಸೆಳೆಯುತ್ತವೆ, ಯಾವಾಗ ದೂರ ತಳ್ಳುತ್ತವೆ ಬರೆಯಿರಿ."},{"en":"Put a sheet of paper over a bar magnet and sprinkle iron filings on it. Tap the paper gently.","hi":"छड़ चुंबक पर कागज़ रखकर उस पर लौह-चूर्ण छिड़कें। कागज़ को हल्के से थपथपाएँ।","kn":"ದಂಡಕಾಂತದ ಮೇಲೆ ಹಾಳೆ ಇಟ್ಟು ಕಬ್ಬಿಣದ ಪುಡಿ ಉದುರಿಸಿ. ಹಾಳೆಯನ್ನು ಮೃದುವಾಗಿ ತಟ್ಟಿ."},{"en":"Draw the pattern the filings make. Move a compass around the magnet and draw its needle at each place.","hi":"चूर्ण से बने पैटर्न का चित्र बनाएँ। कम्पास को चुंबक के चारों ओर घुमाएँ और हर जगह उसकी सुई बनाएँ।","kn":"ಪುಡಿ ಮಾಡಿದ ಮಾದರಿ ಬಿಡಿಸಿ. ದಿಕ್ಸೂಚಿಯನ್ನು ಕಾಂತದ ಸುತ್ತ ಸರಿಸಿ ಪ್ರತಿ ಸ್ಥಳದಲ್ಲಿ ಅದರ ಸೂಜಿ ಬಿಡಿಸಿ."},{"en":"Join the needle directions into lines: these are the magnetic field lines.","hi":"सुई की दिशाओं को मिलाकर रेखाएँ बनाएँ: ये चुंबकीय क्षेत्र रेखाएँ हैं।","kn":"ಸೂಜಿಯ ದಿಕ್ಕುಗಳನ್ನು ಜೋಡಿಸಿ ರೇಖೆಗಳನ್ನಾಗಿಸಿ: ಇವೇ ಕಾಂತಕ್ಷೇತ್ರ ರೇಖೆಗಳು."}],"precautions":[{"en":"Do not drop or heat magnets; they lose their magnetism.","hi":"चुंबकों को गिराएँ या गरम न करें; उनका चुंबकत्व कम हो जाता है।","kn":"ಕಾಂತಗಳನ್ನು ಬೀಳಿಸಬೇಡಿ ಅಥವಾ ಬಿಸಿ ಮಾಡಬೇಡಿ; ಅವು ಕಾಂತತ್ವ ಕಳೆದುಕೊಳ್ಳುತ್ತವೆ."},{"en":"Keep magnets away from phones, cards and computers.","hi":"चुंबकों को फ़ोन, कार्ड और कंप्यूटर से दूर रखें।","kn":"ಕಾಂತಗಳನ್ನು ಫೋನ್, ಕಾರ್ಡ್ ಮತ್ತು ಕಂಪ್ಯೂಟರ್‌ಗಳಿಂದ ದೂರವಿಡಿ."},{"en":"Store bar magnets in pairs with unlike poles side by side, with keepers.","hi":"छड़ चुंबकों को जोड़ों में, असमान ध्रुव साथ-साथ रखकर, कीपर के साथ रखें।","kn":"ದಂಡಕಾಂತಗಳನ್ನು ಜೋಡಿಗಳಲ್ಲಿ, ವಿಜಾತೀಯ ಧ್ರುವಗಳು ಪಕ್ಕಪಕ್ಕದಲ್ಲಿರುವಂತೆ ಕೀಪರ್‌ಗಳೊಂದಿಗೆ ಇಡಿ."}],"conclusion":{"en":"Objects of iron and steel are attracted; wood, plastic, rubber, glass, copper and aluminium are not. Like poles repel and unlike poles attract. Iron filings show field lines that leave the north pole and enter the south pole, crowding near the poles where the magnet is strongest.","hi":"लोहे और स्टील की वस्तुएँ आकर्षित होती हैं; लकड़ी, प्लास्टिक, रबर, काँच, ताँबा और ऐलुमिनियम नहीं। समान ध्रुव प्रतिकर्षित और असमान ध्रुव आकर्षित करते हैं। लौह-चूर्ण क्षेत्र रेखाएँ दिखाता है जो उत्तर ध्रुव से निकलकर दक्षिण ध्रुव में जाती हैं और ध्रुवों के पास घनी होती हैं, जहाँ चुंबक सबसे प्रबल है।","kn":"ಕಬ್ಬಿಣ ಮತ್ತು ಉಕ್ಕಿನ ವಸ್ತುಗಳು ಆಕರ್ಷಿಸಲ್ಪಡುತ್ತವೆ; ಮರ, ಪ್ಲಾಸ್ಟಿಕ್, ರಬ್ಬರ್, ಗಾಜು, ತಾಮ್ರ ಮತ್ತು ಅಲ್ಯೂಮಿನಿಯಂ ಇಲ್ಲ. ಸಜಾತೀಯ ಧ್ರುವಗಳು ವಿಕರ್ಷಿಸುತ್ತವೆ, ವಿಜಾತೀಯ ಧ್ರುವಗಳು ಆಕರ್ಷಿಸುತ್ತವೆ. ಕಬ್ಬಿಣದ ಪುಡಿ ಉತ್ತರ ಧ್ರುವದಿಂದ ಹೊರಬಂದು ದಕ್ಷಿಣ ಧ್ರುವ ಸೇರುವ ಕ್ಷೇತ್ರ ರೇಖೆಗಳನ್ನು ತೋರಿಸುತ್ತದೆ; ಕಾಂತ ಅತ್ಯಂತ ಪ್ರಬಲವಾಗಿರುವ ಧ್ರುವಗಳ ಬಳಿ ಅವು ದಟ್ಟವಾಗಿರುತ್ತವೆ."},"viva":[{"q":{"en":"Name three magnetic materials.","hi":"तीन चुंबकीय पदार्थों के नाम बताइए।","kn":"ಮೂರು ಕಾಂತೀಯ ವಸ್ತುಗಳನ್ನು ಹೆಸರಿಸಿ."},"a":{"en":"Iron, nickel and cobalt.","hi":"लोहा, निकल और कोबाल्ट।","kn":"ಕಬ್ಬಿಣ, ನಿಕ್ಕಲ್ ಮತ್ತು ಕೋಬಾಲ್ಟ್."}},{"q":{"en":"What happens when the north poles of two magnets are brought together?","hi":"दो चुंबकों के उत्तर ध्रुव पास लाने पर क्या होता है?","kn":"ಎರಡು ಕಾಂತಗಳ ಉತ್ತರ ಧ್ರುವಗಳನ್ನು ಹತ್ತಿರ ತಂದಾಗ ಏನಾಗುತ್ತದೆ?"},"a":{"en":"They push each other away (repel).","hi":"वे एक-दूसरे को दूर धकेलते हैं (प्रतिकर्षण)।","kn":"ಅವು ಒಂದನ್ನೊಂದು ದೂರ ತಳ್ಳುತ್ತವೆ (ವಿಕರ್ಷಣೆ)."}},{"q":{"en":"Which is the surer test that something is a magnet: attraction or repulsion?","hi":"कोई वस्तु चुंबक है, इसकी पक्की जाँच कौन-सी है: आकर्षण या प्रतिकर्षण?","kn":"ಯಾವುದಾದರೂ ಕಾಂತವೆಂದು ಖಚಿತ ಪರೀಕ್ಷೆ ಯಾವುದು: ಆಕರ್ಷಣೆಯೋ ವಿಕರ್ಷಣೆಯೋ?"},"a":{"en":"Repulsion: a magnet attracts plain iron too, but only another magnet can repel it.","hi":"प्रतिकर्षण: चुंबक साधारण लोहे को भी आकर्षित करता है, पर प्रतिकर्षित केवल दूसरा चुंबक ही कर सकता है।","kn":"ವಿಕರ್ಷಣೆ: ಕಾಂತ ಸಾಮಾನ್ಯ ಕಬ್ಬಿಣವನ್ನೂ ಆಕರ್ಷಿಸುತ್ತದೆ, ಆದರೆ ವಿಕರ್ಷಿಸಲು ಇನ್ನೊಂದು ಕಾಂತವೇ ಬೇಕು."}},{"q":{"en":"In which direction does a freely hanging magnet come to rest?","hi":"स्वतंत्र रूप से लटका चुंबक किस दिशा में रुकता है?","kn":"ಮುಕ್ತವಾಗಿ ತೂಗುಬಿಟ್ಟ ಕಾಂತ ಯಾವ ದಿಕ್ಕಿನಲ್ಲಿ ನಿಲ್ಲುತ್ತದೆ?"},"a":{"en":"Along the north–south direction.","hi":"उत्तर–दक्षिण दिशा में।","kn":"ಉತ್ತರ–ದಕ್ಷಿಣ ದಿಕ್ಕಿನಲ್ಲಿ."}},{"q":{"en":"Where are the field lines closest together?","hi":"क्षेत्र रेखाएँ सबसे पास-पास कहाँ होती हैं?","kn":"ಕ್ಷೇತ್ರ ರೇಖೆಗಳು ಎಲ್ಲಿ ಅತ್ಯಂತ ಹತ್ತಿರವಾಗಿರುತ್ತವೆ?"},"a":{"en":"Near the poles, where the field is strongest.","hi":"ध्रुवों के पास, जहाँ क्षेत्र सबसे प्रबल होता है।","kn":"ಧ್ರುವಗಳ ಬಳಿ, ಕ್ಷೇತ್ರ ಅತ್ಯಂತ ಪ್ರಬಲವಾಗಿರುವಲ್ಲಿ."}}]},{"id":"shadows","bench":"shadows","setup":{},"subject":"Physics","domain":"physics","levels":["6","7"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["shadow","shadows","light shadows and reflections","opaque","transparent","translucent","light"],"title":{"en":"Light and shadows","hi":"प्रकाश और छायाएँ","kn":"ಬೆಳಕು ಮತ್ತು ನೆರಳುಗಳು"},"summary":{"en":"Shine a torch at different objects and see which cast a shadow and how its size changes.","hi":"अलग-अलग वस्तुओं पर टॉर्च डालें और देखें कि किनकी छाया बनती है और उसका आकार कैसे बदलता है।","kn":"ಬೇರೆ ಬೇರೆ ವಸ್ತುಗಳ ಮೇಲೆ ಟಾರ್ಚ್ ಬೆಳಕು ಹಾಕಿ, ಯಾವುದಕ್ಕೆ ನೆರಳು ಬೀಳುತ್ತದೆ, ಅದರ ಗಾತ್ರ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ನೋಡಿ."},"aim":{"en":"To sort objects into transparent, translucent and opaque, and to study how the size of a shadow depends on the distance of the object from the light.","hi":"वस्तुओं को पारदर्शी, पारभासी और अपारदर्शी में बाँटना, और यह अध्ययन करना कि छाया का आकार वस्तु की प्रकाश से दूरी पर कैसे निर्भर करता है।","kn":"ವಸ್ತುಗಳನ್ನು ಪಾರದರ್ಶಕ, ಅರೆಪಾರದರ್ಶಕ ಮತ್ತು ಅಪಾರದರ್ಶಕ ಎಂದು ವಿಂಗಡಿಸುವುದು, ನೆರಳಿನ ಗಾತ್ರ ಬೆಳಕಿನಿಂದ ವಸ್ತುವಿನ ದೂರವನ್ನು ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ ಅಧ್ಯಯನ ಮಾಡುವುದು."},"principle":{"en":"Light travels in straight lines. A transparent object lets almost all light through, a translucent object lets some through, and an opaque object lets none through, so an opaque object casts a dark shadow. The closer the object is to the torch, the bigger its shadow on the screen.","hi":"प्रकाश सीधी रेखाओं में चलता है। पारदर्शी वस्तु लगभग सारा प्रकाश जाने देती है, पारभासी कुछ प्रकाश, और अपारदर्शी बिलकुल नहीं, इसलिए अपारदर्शी वस्तु की गहरी छाया बनती है। वस्तु टॉर्च के जितने पास होगी, पर्दे पर उसकी छाया उतनी बड़ी होगी।","kn":"ಬೆಳಕು ಸರಳರೇಖೆಗಳಲ್ಲಿ ಸಾಗುತ್ತದೆ. ಪಾರದರ್ಶಕ ವಸ್ತು ಬಹುತೇಕ ಎಲ್ಲ ಬೆಳಕನ್ನು ಹಾಯಲು ಬಿಡುತ್ತದೆ, ಅರೆಪಾರದರ್ಶಕ ಸ್ವಲ್ಪ, ಅಪಾರದರ್ಶಕ ಏನೂ ಇಲ್ಲ; ಆದ್ದರಿಂದ ಅಪಾರದರ್ಶಕ ವಸ್ತುವಿನ ಗಾಢ ನೆರಳು ಬೀಳುತ್ತದೆ. ವಸ್ತು ಟಾರ್ಚ್‌ಗೆ ಹತ್ತಿರವಾದಷ್ಟೂ ಪರದೆಯ ಮೇಲೆ ಅದರ ನೆರಳು ದೊಡ್ಡದು."},"apparatus":[{"en":"Torch","hi":"टॉर्च","kn":"ಟಾರ್ಚ್"},{"en":"White screen or wall","hi":"सफ़ेद पर्दा या दीवार","kn":"ಬಿಳಿ ಪರದೆ ಅಥವಾ ಗೋಡೆ"},{"en":"Objects: glass sheet, butter paper, frosted glass, wooden block, steel plate, cardboard shape","hi":"वस्तुएँ: काँच की शीट, बटर पेपर, घिसा काँच, लकड़ी का गुटका, स्टील की प्लेट, गत्ते की आकृति","kn":"ವಸ್ತುಗಳು: ಗಾಜಿನ ಹಾಳೆ, ಬಟರ್ ಪೇಪರ್, ಮಬ್ಬು ಗಾಜು, ಮರದ ತುಂಡು, ಉಕ್ಕಿನ ತಟ್ಟೆ, ರಟ್ಟಿನ ಆಕೃತಿ"},{"en":"Metre scale","hi":"मीटर पैमाना","kn":"ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ"}],"steps":[{"en":"Darken the room. Put the torch on a table facing the screen, about 1 m away.","hi":"कमरे में अँधेरा करें। टॉर्च को मेज़ पर पर्दे की ओर मुँह करके लगभग 1 m दूर रखें।","kn":"ಕೋಣೆ ಕತ್ತಲಾಗಿಸಿ. ಟಾರ್ಚನ್ನು ಮೇಜಿನ ಮೇಲೆ ಪರದೆಗೆ ಮುಖಮಾಡಿ ಸುಮಾರು 1 m ದೂರದಲ್ಲಿಡಿ."},{"en":"Hold each object between the torch and the screen.","hi":"हर वस्तु को टॉर्च और पर्दे के बीच पकड़ें।","kn":"ಪ್ರತಿ ವಸ್ತುವನ್ನು ಟಾರ್ಚ್ ಮತ್ತು ಪರದೆಯ ನಡುವೆ ಹಿಡಿಯಿರಿ."},{"en":"See how much light passes through and what kind of shadow forms: dark, faint, or none.","hi":"देखें कितना प्रकाश पार जाता है और कैसी छाया बनती है: गहरी, हल्की या कोई नहीं।","kn":"ಎಷ್ಟು ಬೆಳಕು ಹಾಯುತ್ತದೆ, ಯಾವ ಬಗೆಯ ನೆರಳು ಬೀಳುತ್ತದೆ ನೋಡಿ: ಗಾಢ, ಮಸುಕು ಅಥವಾ ಇಲ್ಲವೇ ಇಲ್ಲ."},{"en":"Record each object as transparent, translucent or opaque.","hi":"हर वस्तु को पारदर्शी, पारभासी या अपारदर्शी के रूप में लिखें।","kn":"ಪ್ರತಿ ವಸ್ತುವನ್ನು ಪಾರದರ್ಶಕ, ಅರೆಪಾರದರ್ಶಕ ಅಥವಾ ಅಪಾರದರ್ಶಕ ಎಂದು ದಾಖಲಿಸಿ."},{"en":"Take the cardboard shape and move it closer to the torch, then closer to the screen.","hi":"गत्ते की आकृति लें और उसे टॉर्च के पास, फिर पर्दे के पास ले जाएँ।","kn":"ರಟ್ಟಿನ ಆಕೃತಿ ತೆಗೆದುಕೊಂಡು ಟಾರ್ಚ್ ಹತ್ತಿರ, ನಂತರ ಪರದೆಯ ಹತ್ತಿರ ಸರಿಸಿ."},{"en":"Measure the height of the shadow for each position.","hi":"हर स्थिति में छाया की ऊँचाई मापें।","kn":"ಪ್ರತಿ ಸ್ಥಾನದಲ್ಲಿ ನೆರಳಿನ ಎತ್ತರ ಅಳೆಯಿರಿ."},{"en":"Describe how the shadow size changes as the object moves.","hi":"बताइए कि वस्तु खिसकने पर छाया का आकार कैसे बदलता है।","kn":"ವಸ್ತು ಸರಿದಂತೆ ನೆರಳಿನ ಗಾತ್ರ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ವಿವರಿಸಿ."}],"precautions":[{"en":"Never look straight into a bright light.","hi":"तेज़ रोशनी में सीधे कभी न देखें।","kn":"ಪ್ರಖರ ಬೆಳಕಿನೊಳಗೆ ಎಂದೂ ನೇರವಾಗಿ ನೋಡಬೇಡಿ."},{"en":"Handle the glass sheet carefully by its edges.","hi":"काँच की शीट को किनारों से सावधानी से पकड़ें।","kn":"ಗಾಜಿನ ಹಾಳೆಯನ್ನು ಅಂಚುಗಳಿಂದ ಎಚ್ಚರಿಕೆಯಿಂದ ಹಿಡಿಯಿರಿ."},{"en":"Keep the torch still while measuring.","hi":"मापते समय टॉर्च को स्थिर रखें।","kn":"ಅಳೆಯುವಾಗ ಟಾರ್ಚ್ ಅಲುಗಾಡದಂತೆ ಇಡಿ."}],"conclusion":{"en":"Clear glass is transparent and casts almost no shadow; butter paper and frosted glass are translucent and cast faint shadows; wood, steel and cardboard are opaque and cast dark shadows. The nearer the object is to the torch, the larger its shadow.","hi":"साफ़ काँच पारदर्शी है और लगभग कोई छाया नहीं बनाता; बटर पेपर और घिसा काँच पारभासी हैं और हल्की छाया बनाते हैं; लकड़ी, स्टील और गत्ता अपारदर्शी हैं और गहरी छाया बनाते हैं। वस्तु टॉर्च के जितने पास हो, उसकी छाया उतनी बड़ी।","kn":"ಸ್ಪಷ್ಟ ಗಾಜು ಪಾರದರ್ಶಕ, ಬಹುತೇಕ ನೆರಳು ಬೀಳದು; ಬಟರ್ ಪೇಪರ್ ಮತ್ತು ಮಬ್ಬು ಗಾಜು ಅರೆಪಾರದರ್ಶಕ, ಮಸುಕು ನೆರಳು; ಮರ, ಉಕ್ಕು ಮತ್ತು ರಟ್ಟು ಅಪಾರದರ್ಶಕ, ಗಾಢ ನೆರಳು. ವಸ್ತು ಟಾರ್ಚ್‌ಗೆ ಹತ್ತಿರವಾದಷ್ಟೂ ನೆರಳು ದೊಡ್ಡದು."},"viva":[{"q":{"en":"What is needed to form a shadow?","hi":"छाया बनने के लिए क्या चाहिए?","kn":"ನೆರಳು ಮೂಡಲು ಏನು ಬೇಕು?"},"a":{"en":"A source of light, an opaque object and a screen (or surface) behind it.","hi":"प्रकाश का स्रोत, अपारदर्शी वस्तु और उसके पीछे पर्दा (या सतह)।","kn":"ಬೆಳಕಿನ ಆಕರ, ಅಪಾರದರ್ಶಕ ವಸ್ತು ಮತ್ತು ಅದರ ಹಿಂದೆ ಪರದೆ (ಅಥವಾ ಮೇಲ್ಮೈ)."}},{"q":{"en":"Give an example of a translucent object.","hi":"पारभासी वस्तु का एक उदाहरण दीजिए।","kn":"ಅರೆಪಾರದರ್ಶಕ ವಸ್ತುವಿಗೆ ಒಂದು ಉದಾಹರಣೆ ಕೊಡಿ."},"a":{"en":"Butter paper, frosted glass or thin cloth.","hi":"बटर पेपर, घिसा काँच या पतला कपड़ा।","kn":"ಬಟರ್ ಪೇಪರ್, ಮಬ್ಬು ಗಾಜು ಅಥವಾ ತೆಳು ಬಟ್ಟೆ."}},{"q":{"en":"Why are shadows always dark, even of a red ball?","hi":"लाल गेंद की छाया भी हमेशा काली क्यों होती है?","kn":"ಕೆಂಪು ಚೆಂಡಿನ ನೆರಳು ಕೂಡ ಯಾವಾಗಲೂ ಕಪ್ಪು ಏಕೆ?"},"a":{"en":"A shadow is the region where light does not reach, so it has no colour of its own.","hi":"छाया वह भाग है जहाँ प्रकाश नहीं पहुँचता, इसलिए उसका अपना कोई रंग नहीं होता।","kn":"ನೆರಳು ಬೆಳಕು ತಲುಪದ ಭಾಗ, ಆದ್ದರಿಂದ ಅದಕ್ಕೆ ತನ್ನದೇ ಬಣ್ಣವಿಲ್ಲ."}},{"q":{"en":"What does a shadow tell us about how light travels?","hi":"छाया हमें प्रकाश के चलने के बारे में क्या बताती है?","kn":"ಬೆಳಕು ಹೇಗೆ ಸಾಗುತ್ತದೆ ಎಂಬುದರ ಬಗ್ಗೆ ನೆರಳು ಏನು ಹೇಳುತ್ತದೆ?"},"a":{"en":"That light travels in straight lines.","hi":"कि प्रकाश सीधी रेखाओं में चलता है।","kn":"ಬೆಳಕು ಸರಳರೇಖೆಗಳಲ್ಲಿ ಸಾಗುತ್ತದೆ ಎಂದು."}},{"q":{"en":"How can you make a shadow bigger without moving the screen?","hi":"पर्दा हिलाए बिना छाया को बड़ा कैसे कर सकते हैं?","kn":"ಪರದೆ ಸರಿಸದೆ ನೆರಳನ್ನು ದೊಡ್ಡದಾಗಿಸುವುದು ಹೇಗೆ?"},"a":{"en":"Move the object closer to the torch.","hi":"वस्तु को टॉर्च के पास ले जाकर।","kn":"ವಸ್ತುವನ್ನು ಟಾರ್ಚ್‌ಗೆ ಹತ್ತಿರ ಸರಿಸಿ."}}]},{"id":"prism","bench":"prism","setup":{},"subject":"Physics","domain":"physics","levels":["10","12"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["prism","glass prism","dispersion","spectrum","the human eye and the colourful world","colourful world","rainbow","angle of deviation","refraction through a prism"],"title":{"en":"Refraction and dispersion by a prism","hi":"प्रिज़्म द्वारा अपवर्तन और विक्षेपण","kn":"ಪಟ್ಟಕದಿಂದ ವಕ್ರೀಭವನ ಮತ್ತು ವರ್ಣವಿಭಜನೆ"},"summary":{"en":"Trace a ray through a glass prism, measure its deviation, and split white light into colours.","hi":"काँच के प्रिज़्म से किरण का पथ खींचें, उसका विचलन मापें, और श्वेत प्रकाश को रंगों में बाँटें।","kn":"ಗಾಜಿನ ಪಟ್ಟಕದ ಮೂಲಕ ಕಿರಣದ ಪಥ ಎಳೆದು, ಅದರ ವಿಚಲನ ಅಳೆದು, ಬಿಳಿ ಬೆಳಕನ್ನು ಬಣ್ಣಗಳಾಗಿ ವಿಭಜಿಸಿ."},"aim":{"en":"To trace the path of a ray of light through a glass prism, to measure the angle of deviation for different angles of incidence, and to observe the dispersion of white light.","hi":"काँच के प्रिज़्म से प्रकाश किरण का पथ खींचना, विभिन्न आपतन कोणों के लिए विचलन कोण मापना, और श्वेत प्रकाश का विक्षेपण देखना।","kn":"ಗಾಜಿನ ಪಟ್ಟಕದ ಮೂಲಕ ಬೆಳಕಿನ ಕಿರಣದ ಪಥ ಎಳೆಯುವುದು, ಬೇರೆ ಬೇರೆ ಪತನ ಕೋನಗಳಿಗೆ ವಿಚಲನ ಕೋನ ಅಳೆಯುವುದು, ಬಿಳಿ ಬೆಳಕಿನ ವರ್ಣವಿಭಜನೆ ಗಮನಿಸುವುದು."},"principle":{"en":"A ray bends towards the base of the prism at both faces, so it comes out turned through an angle of deviation D = i + e − A, where A is the angle of the prism. D is smallest when the ray passes symmetrically (i = e). Different colours bend by slightly different amounts, violet the most and red the least, so white light spreads into a spectrum.","hi":"किरण प्रिज़्म के दोनों फलकों पर आधार की ओर मुड़ती है, इसलिए वह विचलन कोण D = i + e − A से मुड़कर निकलती है, जहाँ A प्रिज़्म कोण है। जब किरण सममित रूप से गुज़रती है (i = e) तब D न्यूनतम होता है। अलग-अलग रंग थोड़ा अलग मुड़ते हैं, बैंगनी सबसे अधिक और लाल सबसे कम, इसलिए श्वेत प्रकाश स्पेक्ट्रम में फैल जाता है।","kn":"ಕಿರಣ ಪಟ್ಟಕದ ಎರಡೂ ಮುಖಗಳಲ್ಲಿ ತಳದ ಕಡೆಗೆ ಬಾಗುತ್ತದೆ; ಆದ್ದರಿಂದ ವಿಚಲನ ಕೋನ D = i + e − A ಯಷ್ಟು ತಿರುಗಿ ಹೊರಬರುತ್ತದೆ, A ಪಟ್ಟಕ ಕೋನ. ಕಿರಣ ಸಮಮಿತಿಯಾಗಿ ಹಾದಾಗ (i = e) D ಕನಿಷ್ಠ. ಬೇರೆ ಬಣ್ಣಗಳು ಸ್ವಲ್ಪ ಬೇರೆಯಾಗಿ ಬಾಗುತ್ತವೆ, ನೇರಳೆ ಹೆಚ್ಚು, ಕೆಂಪು ಕಡಿಮೆ; ಆದ್ದರಿಂದ ಬಿಳಿ ಬೆಳಕು ರೋಹಿತವಾಗಿ ಹರಡುತ್ತದೆ."},"apparatus":[{"en":"Glass prism (60°)","hi":"काँच का प्रिज़्म (60°)","kn":"ಗಾಜಿನ ಪಟ್ಟಕ (60°)"},{"en":"Drawing board and white sheet","hi":"ड्रॉइंग बोर्ड और सफ़ेद कागज़","kn":"ಡ್ರಾಯಿಂಗ್ ಬೋರ್ಡ್ ಮತ್ತು ಬಿಳಿ ಹಾಳೆ"},{"en":"Pins","hi":"पिन","kn":"ಪಿನ್‌ಗಳು"},{"en":"Protractor and scale","hi":"चाँदा और पैमाना","kn":"ಕೋನಮಾಪಕ ಮತ್ತು ಅಳತೆಪಟ್ಟಿ"},{"en":"A narrow beam of sunlight or a torch with a slit","hi":"सूर्य के प्रकाश की पतली किरण या झिरी वाली टॉर्च","kn":"ಸೂರ್ಯನ ಬೆಳಕಿನ ಕಿರಿದಾದ ಕಿರಣ ಅಥವಾ ಸೀಳಿರುವ ಟಾರ್ಚ್"}],"steps":[{"en":"Place the prism on the sheet and trace its triangular outline.","hi":"प्रिज़्म को कागज़ पर रखकर उसकी त्रिभुजाकार रूपरेखा खींचें।","kn":"ಪಟ್ಟಕವನ್ನು ಹಾಳೆಯ ಮೇಲಿಟ್ಟು ಅದರ ತ್ರಿಭುಜಾಕಾರದ ರೂಪರೇಖೆ ಎಳೆಯಿರಿ."},{"en":"Draw a normal on one face and an incident ray at angle i (say 40°); fix two pins on it.","hi":"एक फलक पर अभिलंब और कोण i (मान लें 40°) पर आपतित किरण खींचें; उस पर दो पिन लगाएँ।","kn":"ಒಂದು ಮುಖದ ಮೇಲೆ ಲಂಬ ಮತ್ತು i ಕೋನದಲ್ಲಿ (ಉದಾ. 40°) ಪತನ ಕಿರಣ ಎಳೆದು ಅದರ ಮೇಲೆ ಎರಡು ಪಿನ್ ನೆಡಿ."},{"en":"Looking through the other face, fix two pins in line with the images of the first two.","hi":"दूसरे फलक से देखते हुए पहले दो पिनों के प्रतिबिंबों की सीध में दो पिन लगाएँ।","kn":"ಇನ್ನೊಂದು ಮುಖದ ಮೂಲಕ ನೋಡುತ್ತಾ ಮೊದಲ ಎರಡು ಪಿನ್‌ಗಳ ಪ್ರತಿಬಿಂಬಗಳ ಸಾಲಿನಲ್ಲಿ ಎರಡು ಪಿನ್ ನೆಡಿ."},{"en":"Remove the prism, draw the emergent ray and the path inside, and extend the incident and emergent rays until they meet.","hi":"प्रिज़्म हटाएँ, निर्गत किरण और अंदर का पथ खींचें, और आपतित तथा निर्गत किरणों को मिलने तक बढ़ाएँ।","kn":"ಪಟ್ಟಕ ತೆಗೆದು, ನಿರ್ಗಮನ ಕಿರಣ ಮತ್ತು ಒಳಗಿನ ಪಥ ಎಳೆದು, ಪತನ ಮತ್ತು ನಿರ್ಗಮನ ಕಿರಣಗಳು ಸಂಧಿಸುವವರೆಗೆ ವಿಸ್ತರಿಸಿ."},{"en":"Measure the angle of emergence e and the angle of deviation D.","hi":"निर्गमन कोण e और विचलन कोण D मापें।","kn":"ನಿರ್ಗಮನ ಕೋನ e ಮತ್ತು ವಿಚಲನ ಕೋನ D ಅಳೆಯಿರಿ."},{"en":"Repeat for angles of incidence from 30° to 60°, and plot D against i.","hi":"30° से 60° तक के आपतन कोणों के लिए दोहराएँ और D तथा i का ग्राफ़ बनाएँ।","kn":"30° ರಿಂದ 60° ವರೆಗಿನ ಪತನ ಕೋನಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ, D ಮತ್ತು i ನಕ್ಷೆ ಎಳೆಯಿರಿ."},{"en":"Let a narrow beam of white light fall on the prism and look at the band of colours on a white screen.","hi":"श्वेत प्रकाश की पतली किरण प्रिज़्म पर डालें और सफ़ेद पर्दे पर रंगों की पट्टी देखें।","kn":"ಬಿಳಿ ಬೆಳಕಿನ ಕಿರಿದಾದ ಕಿರಣವನ್ನು ಪಟ್ಟಕದ ಮೇಲೆ ಬೀಳಿಸಿ ಬಿಳಿ ಪರದೆಯ ಮೇಲೆ ಬಣ್ಣಗಳ ಪಟ್ಟಿ ನೋಡಿ."}],"precautions":[{"en":"Keep the prism on the same outline throughout.","hi":"पूरे प्रयोग में प्रिज़्म उसी रूपरेखा पर रखें।","kn":"ಪ್ರಯೋಗದುದ್ದಕ್ಕೂ ಪಟ್ಟಕವನ್ನು ಅದೇ ರೂಪರೇಖೆಯ ಮೇಲಿಡಿ."},{"en":"Fix the pins upright and well apart.","hi":"पिन सीधे और दूर-दूर लगाएँ।","kn":"ಪಿನ್‌ಗಳನ್ನು ನೇರವಾಗಿ, ದೂರದೂರ ನೆಡಿ."},{"en":"Never look at the Sun directly, even through a prism.","hi":"सूर्य को कभी सीधे न देखें, प्रिज़्म से भी नहीं।","kn":"ಸೂರ್ಯನನ್ನು ಎಂದೂ ನೇರವಾಗಿ ನೋಡಬೇಡಿ, ಪಟ್ಟಕದ ಮೂಲಕವೂ."}],"conclusion":{"en":"The ray bends towards the base at both faces and comes out deviated. As i increases, D first decreases, reaches a minimum when i = e, and then increases. White light splits into violet, indigo, blue, green, yellow, orange and red, with violet bent the most.","hi":"किरण दोनों फलकों पर आधार की ओर मुड़ती है और विचलित होकर निकलती है। i बढ़ने पर D पहले घटता है, i = e पर न्यूनतम होता है, फिर बढ़ता है। श्वेत प्रकाश बैंगनी, जामुनी, नीला, हरा, पीला, नारंगी और लाल में बँट जाता है; बैंगनी सबसे अधिक मुड़ता है।","kn":"ಕಿರಣ ಎರಡೂ ಮುಖಗಳಲ್ಲಿ ತಳದ ಕಡೆಗೆ ಬಾಗಿ ವಿಚಲಿತವಾಗಿ ಹೊರಬರುತ್ತದೆ. i ಹೆಚ್ಚಿದಂತೆ D ಮೊದಲು ಕಡಿಮೆಯಾಗಿ, i = e ಆದಾಗ ಕನಿಷ್ಠವಾಗಿ, ನಂತರ ಹೆಚ್ಚುತ್ತದೆ. ಬಿಳಿ ಬೆಳಕು ನೇರಳೆ, ಊದಾ, ನೀಲಿ, ಹಸಿರು, ಹಳದಿ, ಕಿತ್ತಳೆ, ಕೆಂಪು ಬಣ್ಣಗಳಾಗಿ ವಿಭಜನೆಯಾಗುತ್ತದೆ; ನೇರಳೆ ಹೆಚ್ಚು ಬಾಗುತ್ತದೆ."},"viva":[{"q":{"en":"What is the angle of deviation?","hi":"विचलन कोण क्या है?","kn":"ವಿಚಲನ ಕೋನ ಎಂದರೇನು?"},"a":{"en":"The angle between the direction of the incident ray and the direction of the emergent ray.","hi":"आपतित किरण की दिशा और निर्गत किरण की दिशा के बीच का कोण।","kn":"ಪತನ ಕಿರಣದ ದಿಕ್ಕು ಮತ್ತು ನಿರ್ಗಮನ ಕಿರಣದ ದಿಕ್ಕಿನ ನಡುವಿನ ಕೋನ."}},{"q":{"en":"What is dispersion?","hi":"विक्षेपण क्या है?","kn":"ವರ್ಣವಿಭಜನೆ ಎಂದರೇನು?"},"a":{"en":"The splitting of white light into its colours.","hi":"श्वेत प्रकाश का उसके रंगों में बँटना।","kn":"ಬಿಳಿ ಬೆಳಕು ತನ್ನ ಬಣ್ಣಗಳಾಗಿ ವಿಭಜನೆಯಾಗುವುದು."}},{"q":{"en":"Which colour deviates the most?","hi":"कौन-सा रंग सबसे अधिक विचलित होता है?","kn":"ಯಾವ ಬಣ್ಣ ಹೆಚ್ಚು ವಿಚಲಿತವಾಗುತ್ತದೆ?"},"a":{"en":"Violet.","hi":"बैंगनी।","kn":"ನೇರಳೆ."}},{"q":{"en":"How is a rainbow formed?","hi":"इंद्रधनुष कैसे बनता है?","kn":"ಕಾಮನಬಿಲ್ಲು ಹೇಗೆ ಉಂಟಾಗುತ್ತದೆ?"},"a":{"en":"Tiny raindrops refract, reflect inside and disperse sunlight, acting like small prisms.","hi":"वर्षा की छोटी बूँदें छोटे प्रिज़्मों की तरह सूर्य के प्रकाश का अपवर्तन, आंतरिक परावर्तन और विक्षेपण करती हैं।","kn":"ಮಳೆಯ ಚಿಕ್ಕ ಹನಿಗಳು ಚಿಕ್ಕ ಪಟ್ಟಕಗಳಂತೆ ಸೂರ್ಯನ ಬೆಳಕನ್ನು ವಕ್ರೀಭವನ, ಒಳಗೆ ಪ್ರತಿಫಲನ ಮತ್ತು ವರ್ಣವಿಭಜನೆ ಮಾಡುತ್ತವೆ."}},{"q":{"en":"When is the deviation smallest?","hi":"विचलन सबसे कम कब होता है?","kn":"ವಿಚಲನ ಯಾವಾಗ ಕನಿಷ್ಠ?"},"a":{"en":"When the angle of incidence equals the angle of emergence.","hi":"जब आपतन कोण निर्गमन कोण के बराबर हो।","kn":"ಪತನ ಕೋನ ನಿರ್ಗಮನ ಕೋನಕ್ಕೆ ಸಮವಾದಾಗ."}}]},{"id":"heating-curve","bench":"heating","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["6","9"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["matter in our surroundings","states of water","a journey through states of water","melting point","boiling point","states of matter","change of state","temperature","heat","particulate nature of matter","latent heat"],"title":{"en":"Melting point of ice and boiling point of water","hi":"बर्फ़ का गलनांक और पानी का क्वथनांक","kn":"ಮಂಜುಗಡ್ಡೆಯ ದ್ರವನಬಿಂದು ಮತ್ತು ನೀರಿನ ಕುದಿಬಿಂದು"},"summary":{"en":"Heat ice until it melts and the water boils, reading the thermometer every minute.","hi":"बर्फ़ को तब तक गरम करें जब तक वह पिघलकर पानी न बन जाए और पानी उबलने न लगे, हर मिनट तापमापी पढ़ते हुए।","kn":"ಮಂಜುಗಡ್ಡೆ ಕರಗಿ ನೀರಾಗಿ ಕುದಿಯುವವರೆಗೆ ಕಾಯಿಸಿ, ಪ್ರತಿ ನಿಮಿಷ ತಾಪಮಾಪಕ ಓದಿ."},"aim":{"en":"To find the melting point of ice and the boiling point of water, and to see that the temperature stays constant while the state changes.","hi":"बर्फ़ का गलनांक और पानी का क्वथनांक ज्ञात करना, और देखना कि अवस्था बदलते समय ताप स्थिर रहता है।","kn":"ಮಂಜುಗಡ್ಡೆಯ ದ್ರವನಬಿಂದು ಮತ್ತು ನೀರಿನ ಕುದಿಬಿಂದು ಕಂಡುಹಿಡಿಯುವುದು, ಸ್ಥಿತಿ ಬದಲಾಗುವಾಗ ತಾಪ ಸ್ಥಿರವಾಗಿರುತ್ತದೆ ಎಂದು ನೋಡುವುದು."},"principle":{"en":"While ice melts, the heat supplied is used to break the particles apart (latent heat), so the temperature stays at 0 °C until all the ice has melted. The same happens at 100 °C while water boils. Dissolved salt lowers the melting point and raises the boiling point a little.","hi":"बर्फ़ के पिघलते समय दी गई ऊष्मा कणों को अलग करने में लगती है (गुप्त ऊष्मा), इसलिए सारी बर्फ़ पिघलने तक ताप 0 °C पर रहता है। पानी उबलते समय 100 °C पर भी यही होता है। घुला हुआ नमक गलनांक को थोड़ा घटाता और क्वथनांक को थोड़ा बढ़ाता है।","kn":"ಮಂಜುಗಡ್ಡೆ ಕರಗುವಾಗ ನೀಡಿದ ಉಷ್ಣ ಕಣಗಳನ್ನು ಬೇರ್ಪಡಿಸಲು ಬಳಕೆಯಾಗುತ್ತದೆ (ಗುಪ್ತೋಷ್ಣ); ಆದ್ದರಿಂದ ಎಲ್ಲ ಮಂಜು ಕರಗುವವರೆಗೆ ತಾಪ 0 °C ನಲ್ಲಿರುತ್ತದೆ. ನೀರು ಕುದಿಯುವಾಗ 100 °C ನಲ್ಲೂ ಹೀಗೆಯೇ. ಕರಗಿದ ಉಪ್ಪು ದ್ರವನಬಿಂದುವನ್ನು ಸ್ವಲ್ಪ ಇಳಿಸುತ್ತದೆ, ಕುದಿಬಿಂದುವನ್ನು ಸ್ವಲ್ಪ ಏರಿಸುತ್ತದೆ."},"apparatus":[{"en":"Beaker","hi":"बीकर","kn":"ಬೀಕರ್"},{"en":"Crushed ice","hi":"कुटी हुई बर्फ़","kn":"ಪುಡಿಮಾಡಿದ ಮಂಜುಗಡ್ಡೆ"},{"en":"Laboratory thermometer","hi":"प्रयोगशाला तापमापी","kn":"ಪ್ರಯೋಗಾಲಯ ತಾಪಮಾಪಕ"},{"en":"Burner, tripod stand and wire gauze","hi":"बर्नर, तिपाई और तार की जाली","kn":"ಬರ್ನರ್, ತ್ರಿಪಾದ ಸ್ಟ್ಯಾಂಡ್ ಮತ್ತು ತಂತಿ ಜಾಲರಿ"},{"en":"Clamp stand","hi":"क्लैंप स्टैंड","kn":"ಕ್ಲ್ಯಾಂಪ್ ಸ್ಟ್ಯಾಂಡ್"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"}],"steps":[{"en":"Fill the beaker half with crushed ice and clamp the thermometer so its bulb is in the ice without touching the beaker.","hi":"बीकर को आधा कुटी बर्फ़ से भरें और तापमापी को ऐसे क्लैंप करें कि उसका बल्ब बर्फ़ में रहे और बीकर को न छुए।","kn":"ಬೀಕರನ್ನು ಅರ್ಧ ಪುಡಿ ಮಂಜುಗಡ್ಡೆಯಿಂದ ತುಂಬಿಸಿ, ತಾಪಮಾಪಕದ ಬಲ್ಬ್ ಮಂಜಿನಲ್ಲಿದ್ದು ಬೀಕರ್‌ಗೆ ತಾಗದಂತೆ ಕ್ಲ್ಯಾಂಪ್ ಮಾಡಿ."},{"en":"Note the temperature.","hi":"ताप लिखें।","kn":"ತಾಪ ಬರೆಯಿರಿ."},{"en":"Heat gently and read the thermometer every minute, stirring slowly.","hi":"धीरे-धीरे गरम करें और धीरे से हिलाते हुए हर मिनट तापमापी पढ़ें।","kn":"ನಿಧಾನವಾಗಿ ಕಾಯಿಸಿ, ನಿಧಾನವಾಗಿ ಕಲಕುತ್ತಾ ಪ್ರತಿ ನಿಮಿಷ ತಾಪಮಾಪಕ ಓದಿ."},{"en":"Note the temperature while the ice is melting; this is the melting point.","hi":"बर्फ़ के पिघलते समय का ताप लिखें; यही गलनांक है।","kn":"ಮಂಜು ಕರಗುತ್ತಿರುವಾಗಿನ ತಾಪ ಬರೆಯಿರಿ; ಇದೇ ದ್ರವನಬಿಂದು."},{"en":"Keep heating after the ice has melted until the water boils.","hi":"बर्फ़ पिघलने के बाद पानी उबलने तक गरम करते रहें।","kn":"ಮಂಜು ಕರಗಿದ ನಂತರವೂ ನೀರು ಕುದಿಯುವವರೆಗೆ ಕಾಯಿಸುತ್ತಿರಿ."},{"en":"Note the temperature while the water boils; this is the boiling point.","hi":"पानी उबलते समय का ताप लिखें; यही क्वथनांक है।","kn":"ನೀರು ಕುದಿಯುವಾಗಿನ ತಾಪ ಬರೆಯಿರಿ; ಇದೇ ಕುದಿಬಿಂದು."},{"en":"Plot temperature against time. Repeat with a spoon of salt in the ice.","hi":"ताप और समय का ग्राफ़ बनाएँ। बर्फ़ में एक चम्मच नमक डालकर दोहराएँ।","kn":"ತಾಪ ಮತ್ತು ಸಮಯದ ನಕ್ಷೆ ಎಳೆಯಿರಿ. ಮಂಜಿಗೆ ಒಂದು ಚಮಚ ಉಪ್ಪು ಹಾಕಿ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"The thermometer bulb must not touch the beaker.","hi":"तापमापी का बल्ब बीकर को न छुए।","kn":"ತಾಪಮಾಪಕದ ಬಲ್ಬ್ ಬೀಕರ್‌ಗೆ ತಾಗಬಾರದು."},{"en":"Read the thermometer with your eye level with the mercury.","hi":"तापमापी को पारे के स्तर पर आँख रखकर पढ़ें।","kn":"ಪಾದರಸದ ಮಟ್ಟಕ್ಕೆ ಕಣ್ಣಿಟ್ಟು ತಾಪಮಾಪಕ ಓದಿ."},{"en":"Take care near the flame and the boiling water; use tongs.","hi":"लौ और उबलते पानी के पास सावधान रहें; चिमटे का प्रयोग करें।","kn":"ಜ್ವಾಲೆ ಮತ್ತು ಕುದಿಯುವ ನೀರಿನ ಬಳಿ ಎಚ್ಚರ; ಇಕ್ಕಳ ಬಳಸಿ."}],"conclusion":{"en":"The temperature stays at 0 °C while the ice melts and at 100 °C while the water boils (at sea level), and rises in between. The flat parts of the graph show that heat is used to change the state, not to raise the temperature.","hi":"बर्फ़ पिघलते समय ताप 0 °C पर और पानी उबलते समय 100 °C पर (समुद्र तल पर) स्थिर रहता है, और बीच में बढ़ता है। ग्राफ़ के सपाट भाग दिखाते हैं कि ऊष्मा ताप बढ़ाने में नहीं, अवस्था बदलने में लगती है।","kn":"ಮಂಜು ಕರಗುವಾಗ ತಾಪ 0 °C ನಲ್ಲಿ, ನೀರು ಕುದಿಯುವಾಗ 100 °C ನಲ್ಲಿ (ಸಮುದ್ರಮಟ್ಟದಲ್ಲಿ) ಸ್ಥಿರವಾಗಿರುತ್ತದೆ, ನಡುವೆ ಏರುತ್ತದೆ. ನಕ್ಷೆಯ ಸಮತಟ್ಟು ಭಾಗಗಳು ಉಷ್ಣ ತಾಪ ಏರಿಸಲು ಅಲ್ಲ, ಸ್ಥಿತಿ ಬದಲಿಸಲು ಬಳಕೆಯಾಗುತ್ತದೆ ಎಂದು ತೋರಿಸುತ್ತವೆ."},"viva":[{"q":{"en":"What is the melting point of ice?","hi":"बर्फ़ का गलनांक कितना है?","kn":"ಮಂಜುಗಡ್ಡೆಯ ದ್ರವನಬಿಂದು ಎಷ್ಟು?"},"a":{"en":"0 °C (273 K).","hi":"0 °C (273 K)।","kn":"0 °C (273 K)."}},{"q":{"en":"Why does the temperature not rise while ice is melting?","hi":"बर्फ़ पिघलते समय ताप क्यों नहीं बढ़ता?","kn":"ಮಂಜು ಕರಗುವಾಗ ತಾಪ ಏಕೆ ಏರುವುದಿಲ್ಲ?"},"a":{"en":"The heat is used to change the state (latent heat of fusion).","hi":"ऊष्मा अवस्था बदलने में लगती है (संगलन की गुप्त ऊष्मा)।","kn":"ಉಷ್ಣ ಸ್ಥಿತಿ ಬದಲಿಸಲು ಬಳಕೆಯಾಗುತ್ತದೆ (ದ್ರವೀಕರಣದ ಗುಪ್ತೋಷ್ಣ)."}},{"q":{"en":"Why is the thermometer bulb kept off the bottom of the beaker?","hi":"तापमापी का बल्ब बीकर की तली से दूर क्यों रखा जाता है?","kn":"ತಾಪಮಾಪಕದ ಬಲ್ಬನ್ನು ಬೀಕರ್‌ನ ತಳದಿಂದ ದೂರ ಏಕೆ ಇಡುತ್ತಾರೆ?"},"a":{"en":"The glass is hotter than the water; touching it would give a wrong reading.","hi":"काँच पानी से अधिक गरम होता है; छूने पर गलत पाठ्यांक मिलेगा।","kn":"ಗಾಜು ನೀರಿಗಿಂತ ಬಿಸಿ; ತಾಗಿದರೆ ತಪ್ಪು ಓದು ಸಿಗುತ್ತದೆ."}},{"q":{"en":"What does adding salt do to the boiling point?","hi":"नमक डालने से क्वथनांक पर क्या असर होता है?","kn":"ಉಪ್ಪು ಹಾಕಿದರೆ ಕುದಿಬಿಂದುವಿಗೆ ಏನಾಗುತ್ತದೆ?"},"a":{"en":"It raises it a little.","hi":"यह थोड़ा बढ़ जाता है।","kn":"ಅದು ಸ್ವಲ್ಪ ಏರುತ್ತದೆ."}},{"q":{"en":"Why does water boil at a lower temperature in the hills?","hi":"पहाड़ों पर पानी कम ताप पर क्यों उबलता है?","kn":"ಬೆಟ್ಟಗಳಲ್ಲಿ ನೀರು ಕಡಿಮೆ ತಾಪದಲ್ಲಿ ಏಕೆ ಕುದಿಯುತ್ತದೆ?"},"a":{"en":"The air pressure is lower there.","hi":"वहाँ वायुदाब कम होता है।","kn":"ಅಲ್ಲಿ ವಾಯುಒತ್ತಡ ಕಡಿಮೆ."}}]},{"id":"reactions","bench":"reactions","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["7","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["chemical reactions","chemical reactions and equations","changes around us","physical and chemical","combination reaction","decomposition","double displacement","precipitate","chemical changes and reactions"],"title":{"en":"Types of chemical reactions","hi":"रासायनिक अभिक्रियाओं के प्रकार","kn":"ರಾಸಾಯನಿಕ ಕ್ರಿಯೆಗಳ ವಿಧಗಳು"},"summary":{"en":"Carry out four reactions, watch what changes, and name the type of each one.","hi":"चार अभिक्रियाएँ करें, देखें क्या बदलता है, और हर एक का प्रकार बताइए।","kn":"ನಾಲ್ಕು ಕ್ರಿಯೆಗಳನ್ನು ನಡೆಸಿ, ಏನು ಬದಲಾಗುತ್ತದೆ ನೋಡಿ, ಪ್ರತಿಯೊಂದರ ವಿಧ ಹೆಸರಿಸಿ."},"aim":{"en":"To carry out combination, decomposition, displacement and double displacement reactions, and to identify each type from what is observed.","hi":"संयोजन, वियोजन, विस्थापन और द्विविस्थापन अभिक्रियाएँ करना और प्रेक्षणों से हर प्रकार को पहचानना।","kn":"ಸಂಯೋಜನೆ, ವಿಭಜನೆ, ಸ್ಥಳಾಂತರ ಮತ್ತು ದ್ವಿಸ್ಥಳಾಂತರ ಕ್ರಿಯೆಗಳನ್ನು ನಡೆಸಿ, ವೀಕ್ಷಣೆಗಳಿಂದ ಪ್ರತಿ ವಿಧವನ್ನು ಗುರುತಿಸುವುದು."},"principle":{"en":"In a chemical reaction new substances form; we see it as a change of colour, a gas, heat, a smell or a precipitate. Combination: two substances form one. Decomposition: one substance breaks into simpler ones. Displacement: a more reactive element takes the place of a less reactive one. Double displacement: two compounds exchange ions, often forming a precipitate.","hi":"रासायनिक अभिक्रिया में नए पदार्थ बनते हैं; हम इसे रंग बदलने, गैस, ऊष्मा, गंध या अवक्षेप के रूप में देखते हैं। संयोजन: दो पदार्थ मिलकर एक बनाते हैं। वियोजन: एक पदार्थ सरल पदार्थों में टूटता है। विस्थापन: अधिक अभिक्रियाशील तत्व कम अभिक्रियाशील का स्थान लेता है। द्विविस्थापन: दो यौगिक आयनों का आदान-प्रदान करते हैं, प्रायः अवक्षेप बनता है।","kn":"ರಾಸಾಯನಿಕ ಕ್ರಿಯೆಯಲ್ಲಿ ಹೊಸ ವಸ್ತುಗಳು ಉಂಟಾಗುತ್ತವೆ; ಬಣ್ಣ ಬದಲಾವಣೆ, ಅನಿಲ, ಉಷ್ಣ, ವಾಸನೆ ಅಥವಾ ಅವಕ್ಷೇಪವಾಗಿ ಕಾಣುತ್ತೇವೆ. ಸಂಯೋಜನೆ: ಎರಡು ವಸ್ತುಗಳು ಸೇರಿ ಒಂದಾಗುತ್ತವೆ. ವಿಭಜನೆ: ಒಂದು ವಸ್ತು ಸರಳ ವಸ್ತುಗಳಾಗಿ ಒಡೆಯುತ್ತದೆ. ಸ್ಥಳಾಂತರ: ಹೆಚ್ಚು ಪ್ರತಿಕ್ರಿಯಾಶೀಲ ಧಾತು ಕಡಿಮೆ ಪ್ರತಿಕ್ರಿಯಾಶೀಲದ ಸ್ಥಾನ ಪಡೆಯುತ್ತದೆ. ದ್ವಿಸ್ಥಳಾಂತರ: ಎರಡು ಸಂಯುಕ್ತಗಳು ಅಯಾನುಗಳನ್ನು ಅದಲುಬದಲು ಮಾಡಿಕೊಳ್ಳುತ್ತವೆ, ಹೆಚ್ಚಾಗಿ ಅವಕ್ಷೇಪ ಉಂಟಾಗುತ್ತದೆ."},"apparatus":[{"en":"Beakers, test tubes and a boiling tube","hi":"बीकर, परखनलियाँ और क्वथन नली","kn":"ಬೀಕರ್‌ಗಳು, ಪರೀಕ್ಷಾನಳಿಕೆಗಳು ಮತ್ತು ಕುದಿಸುವ ನಳಿಕೆ"},{"en":"Burner and test-tube holder","hi":"बर्नर और परखनली धारक","kn":"ಬರ್ನರ್ ಮತ್ತು ಪರೀಕ್ಷಾನಳಿಕೆ ಹಿಡಿಕೆ"},{"en":"Quicklime (calcium oxide) and water","hi":"बिना बुझा चूना (कैल्शियम ऑक्साइड) और पानी","kn":"ಸುಡುಸುಣ್ಣ (ಕ್ಯಾಲ್ಸಿಯಂ ಆಕ್ಸೈಡ್) ಮತ್ತು ನೀರು"},{"en":"Iron(II) sulphate crystals","hi":"आयरन(II) सल्फेट के क्रिस्टल","kn":"ಕಬ್ಬಿಣ(II) ಸಲ್ಫೇಟ್ ಹರಳುಗಳು"},{"en":"Iron nails and copper sulphate solution","hi":"लोहे की कीलें और कॉपर सल्फेट विलयन","kn":"ಕಬ್ಬಿಣದ ಮೊಳೆಗಳು ಮತ್ತು ತಾಮ್ರದ ಸಲ್ಫೇಟ್ ದ್ರಾವಣ"},{"en":"Sodium sulphate and barium chloride solutions","hi":"सोडियम सल्फेट और बेरियम क्लोराइड विलयन","kn":"ಸೋಡಿಯಂ ಸಲ್ಫೇಟ್ ಮತ್ತು ಬೇರಿಯಂ ಕ್ಲೋರೈಡ್ ದ್ರಾವಣಗಳು"}],"steps":[{"en":"Put a small lump of quicklime in a beaker and slowly add water. Touch the outside of the beaker and listen.","hi":"बीकर में बिना बुझे चूने की छोटी डली रखकर धीरे-धीरे पानी डालें। बीकर को बाहर से छूकर देखें और सुनें।","kn":"ಬೀಕರ್‌ನಲ್ಲಿ ಸುಡುಸುಣ್ಣದ ಚಿಕ್ಕ ತುಂಡಿಟ್ಟು ನಿಧಾನವಾಗಿ ನೀರು ಹಾಕಿ. ಬೀಕರನ್ನು ಹೊರಗಿನಿಂದ ಮುಟ್ಟಿ, ಕೇಳಿಸಿಕೊಳ್ಳಿ."},{"en":"Heat a few crystals of iron(II) sulphate in a dry boiling tube. Note the colour change and the smell.","hi":"सूखी क्वथन नली में आयरन(II) सल्फेट के कुछ क्रिस्टल गरम करें। रंग परिवर्तन और गंध लिखें।","kn":"ಒಣ ಕುದಿಸುವ ನಳಿಕೆಯಲ್ಲಿ ಕೆಲವು ಕಬ್ಬಿಣ(II) ಸಲ್ಫೇಟ್ ಹರಳುಗಳನ್ನು ಕಾಯಿಸಿ. ಬಣ್ಣ ಬದಲಾವಣೆ ಮತ್ತು ವಾಸನೆ ಬರೆಯಿರಿ."},{"en":"Drop clean iron nails into copper sulphate solution and leave for 20 minutes.","hi":"साफ़ लोहे की कीलें कॉपर सल्फेट विलयन में डालकर 20 मिनट छोड़ दें।","kn":"ಸ್ವಚ್ಛ ಕಬ್ಬಿಣದ ಮೊಳೆಗಳನ್ನು ತಾಮ್ರದ ಸಲ್ಫೇಟ್ ದ್ರಾವಣಕ್ಕೆ ಹಾಕಿ 20 ನಿಮಿಷ ಬಿಡಿ."},{"en":"Mix sodium sulphate solution with barium chloride solution in a test tube.","hi":"परखनली में सोडियम सल्फेट विलयन को बेरियम क्लोराइड विलयन के साथ मिलाएँ।","kn":"ಪರೀಕ್ಷಾನಳಿಕೆಯಲ್ಲಿ ಸೋಡಿಯಂ ಸಲ್ಫೇಟ್ ದ್ರಾವಣವನ್ನು ಬೇರಿಯಂ ಕ್ಲೋರೈಡ್ ದ್ರಾವಣದೊಂದಿಗೆ ಮಿಶ್ರಮಾಡಿ."},{"en":"For each reaction, record what you saw.","hi":"हर अभिक्रिया के लिए जो देखा उसे लिखें।","kn":"ಪ್ರತಿ ಕ್ರಿಯೆಗೆ ಕಂಡದ್ದನ್ನು ದಾಖಲಿಸಿ."},{"en":"Write the balanced equation for each reaction.","hi":"हर अभिक्रिया का संतुलित समीकरण लिखें।","kn":"ಪ್ರತಿ ಕ್ರಿಯೆಯ ಸಮತೋಲಿತ ಸಮೀಕರಣ ಬರೆಯಿರಿ."},{"en":"Name the type of each reaction.","hi":"हर अभिक्रिया का प्रकार बताइए।","kn":"ಪ್ರತಿ ಕ್ರಿಯೆಯ ವಿಧ ಹೆಸರಿಸಿ."}],"precautions":[{"en":"Add water to quicklime slowly: it gets very hot and can spatter.","hi":"बिना बुझे चूने में पानी धीरे-धीरे डालें: यह बहुत गरम होता है और छिटक सकता है।","kn":"ಸುಡುಸುಣ್ಣಕ್ಕೆ ನೀರನ್ನು ನಿಧಾನವಾಗಿ ಹಾಕಿ: ಅದು ತುಂಬಾ ಬಿಸಿಯಾಗಿ ಸಿಡಿಯಬಹುದು."},{"en":"Point the heated tube away from everyone and do not smell the gases directly.","hi":"गरम नली को सबसे दूर की ओर रखें और गैसों को सीधे न सूँघें।","kn":"ಕಾಯಿಸುವ ನಳಿಕೆಯನ್ನು ಎಲ್ಲರಿಂದ ದೂರ ತಿರುಗಿಸಿ, ಅನಿಲಗಳನ್ನು ನೇರವಾಗಿ ಮೂಸಬೇಡಿ."},{"en":"Barium chloride is poisonous: do not touch your mouth and wash your hands.","hi":"बेरियम क्लोराइड विषैला है: मुँह न छुएँ और हाथ धोएँ।","kn":"ಬೇರಿಯಂ ಕ್ಲೋರೈಡ್ ವಿಷಕಾರಿ: ಬಾಯಿ ಮುಟ್ಟಬೇಡಿ, ಕೈ ತೊಳೆಯಿರಿ."}],"conclusion":{"en":"Quicklime and water combine with a hissing sound and much heat (combination, exothermic). Iron(II) sulphate turns from green to reddish-brown with a smell of burning sulphur (decomposition). Iron takes copper out of copper sulphate (displacement). Sodium sulphate and barium chloride form a white precipitate of barium sulphate (double displacement).","hi":"बिना बुझा चूना और पानी सनसनाहट और बहुत ऊष्मा के साथ मिलते हैं (संयोजन, ऊष्माक्षेपी)। आयरन(II) सल्फेट हरे से लाल-भूरा हो जाता है और जलते गंधक की गंध आती है (वियोजन)। लोहा कॉपर सल्फेट से ताँबे को निकाल देता है (विस्थापन)। सोडियम सल्फेट और बेरियम क्लोराइड बेरियम सल्फेट का सफ़ेद अवक्षेप बनाते हैं (द्विविस्थापन)।","kn":"ಸುಡುಸುಣ್ಣ ಮತ್ತು ನೀರು ಸುಂಯ್ ಶಬ್ದ ಮತ್ತು ಹೆಚ್ಚು ಉಷ್ಣದೊಂದಿಗೆ ಸೇರುತ್ತವೆ (ಸಂಯೋಜನೆ, ಉಷ್ಣವಿಮೋಚಕ). ಕಬ್ಬಿಣ(II) ಸಲ್ಫೇಟ್ ಹಸಿರಿನಿಂದ ಕೆಂಪು-ಕಂದಾಗಿ ಉರಿಯುವ ಗಂಧಕದ ವಾಸನೆ ಬರುತ್ತದೆ (ವಿಭಜನೆ). ಕಬ್ಬಿಣ ತಾಮ್ರದ ಸಲ್ಫೇಟ್‌ನಿಂದ ತಾಮ್ರ ಹೊರತೆಗೆಯುತ್ತದೆ (ಸ್ಥಳಾಂತರ). ಸೋಡಿಯಂ ಸಲ್ಫೇಟ್ ಮತ್ತು ಬೇರಿಯಂ ಕ್ಲೋರೈಡ್ ಬೇರಿಯಂ ಸಲ್ಫೇಟ್‌ನ ಬಿಳಿ ಅವಕ್ಷೇಪ ರೂಪಿಸುತ್ತವೆ (ದ್ವಿಸ್ಥಳಾಂತರ)."},"viva":[{"q":{"en":"What is a precipitate?","hi":"अवक्षेप क्या है?","kn":"ಅವಕ್ಷೇಪ ಎಂದರೇನು?"},"a":{"en":"An insoluble solid that forms in a solution during a reaction.","hi":"अभिक्रिया के दौरान विलयन में बनने वाला अविलेय ठोस।","kn":"ಕ್ರಿಯೆಯ ಸಮಯದಲ್ಲಿ ದ್ರಾವಣದಲ್ಲಿ ಉಂಟಾಗುವ ಅವಿಲೇಯ ಘನ."}},{"q":{"en":"Why is the reaction of quicklime with water called exothermic?","hi":"बिना बुझे चूने और पानी की अभिक्रिया को ऊष्माक्षेपी क्यों कहते हैं?","kn":"ಸುಡುಸುಣ್ಣ ಮತ್ತು ನೀರಿನ ಕ್ರಿಯೆಯನ್ನು ಉಷ್ಣವಿಮೋಚಕ ಎಂದು ಏಕೆ ಕರೆಯುತ್ತಾರೆ?"},"a":{"en":"It gives out heat.","hi":"इसमें ऊष्मा निकलती है।","kn":"ಅದು ಉಷ್ಣ ಬಿಡುಗಡೆ ಮಾಡುತ್ತದೆ."}},{"q":{"en":"Name the gases given off when iron(II) sulphate is heated.","hi":"आयरन(II) सल्फेट को गरम करने पर निकलने वाली गैसों के नाम बताइए।","kn":"ಕಬ್ಬಿಣ(II) ಸಲ್ಫೇಟ್ ಕಾಯಿಸಿದಾಗ ಬಿಡುಗಡೆಯಾಗುವ ಅನಿಲಗಳನ್ನು ಹೆಸರಿಸಿ."},"a":{"en":"Sulphur dioxide and sulphur trioxide.","hi":"सल्फ़र डाइऑक्साइड और सल्फ़र ट्राइऑक्साइड।","kn":"ಸಲ್ಫರ್ ಡೈಆಕ್ಸೈಡ್ ಮತ್ತು ಸಲ್ಫರ್ ಟ್ರೈಆಕ್ಸೈಡ್."}},{"q":{"en":"What is the white precipitate formed with barium chloride?","hi":"बेरियम क्लोराइड के साथ बना सफ़ेद अवक्षेप क्या है?","kn":"ಬೇರಿಯಂ ಕ್ಲೋರೈಡ್‌ನಿಂದ ಉಂಟಾದ ಬಿಳಿ ಅವಕ್ಷೇಪ ಯಾವುದು?"},"a":{"en":"Barium sulphate.","hi":"बेरियम सल्फेट।","kn":"ಬೇರಿಯಂ ಸಲ್ಫೇಟ್."}},{"q":{"en":"Is the rusting of iron a physical or a chemical change?","hi":"लोहे पर जंग लगना भौतिक परिवर्तन है या रासायनिक?","kn":"ಕಬ್ಬಿಣ ತುಕ್ಕು ಹಿಡಿಯುವುದು ಭೌತಿಕ ಬದಲಾವಣೆಯೋ ರಾಸಾಯನಿಕವೋ?"},"a":{"en":"Chemical: a new substance, iron oxide, forms.","hi":"रासायनिक: एक नया पदार्थ, आयरन ऑक्साइड, बनता है।","kn":"ರಾಸಾಯನಿಕ: ಕಬ್ಬಿಣದ ಆಕ್ಸೈಡ್ ಎಂಬ ಹೊಸ ವಸ್ತು ಉಂಟಾಗುತ್ತದೆ."}}]},{"id":"starch-test","bench":"starch","setup":{},"subject":"Biology","domain":"biology","levels":["7","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["photosynthesis","nutrition in plants","life processes","starch","chlorophyll","leaf","leaves"],"title":{"en":"Starch test: light and chlorophyll for photosynthesis","hi":"मंड परीक्षण: प्रकाश-संश्लेषण के लिए प्रकाश और क्लोरोफ़िल","kn":"ಪಿಷ್ಟ ಪರೀಕ್ಷೆ: ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆಗೆ ಬೆಳಕು ಮತ್ತು ಪತ್ರಹರಿತ್ತು"},"summary":{"en":"Take the colour out of a leaf and test it with iodine to see where it made starch.","hi":"पत्ती का रंग निकालकर उसे आयोडीन से परखें और देखें कि उसने मंड कहाँ बनाया।","kn":"ಎಲೆಯ ಬಣ್ಣ ತೆಗೆದು ಅಯೋಡಿನ್‌ನಿಂದ ಪರೀಕ್ಷಿಸಿ, ಅದು ಪಿಷ್ಟ ಎಲ್ಲಿ ತಯಾರಿಸಿದೆ ನೋಡಿ."},"aim":{"en":"To show that light and chlorophyll are needed for photosynthesis, by testing leaves for starch.","hi":"पत्तियों में मंड की जाँच करके दिखाना कि प्रकाश-संश्लेषण के लिए प्रकाश और क्लोरोफ़िल आवश्यक हैं।","kn":"ಎಲೆಗಳಲ್ಲಿ ಪಿಷ್ಟ ಪರೀಕ್ಷಿಸಿ, ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆಗೆ ಬೆಳಕು ಮತ್ತು ಪತ್ರಹರಿತ್ತು ಅಗತ್ಯ ಎಂದು ತೋರಿಸುವುದು."},"principle":{"en":"Leaves make food (glucose) by photosynthesis and store it as starch. Iodine turns starch blue-black. A plant kept in the dark for two days uses up its starch (destarching). Afterwards, only the parts of a leaf that got light and have chlorophyll make new starch.","hi":"पत्तियाँ प्रकाश-संश्लेषण से भोजन (ग्लूकोज़) बनाती हैं और उसे मंड के रूप में संचित करती हैं। आयोडीन मंड को नीला-काला कर देता है। दो दिन अँधेरे में रखा पौधा अपना मंड खर्च कर देता है (मंड-रहित करना)। इसके बाद पत्ती के केवल वही भाग नया मंड बनाते हैं जिन्हें प्रकाश मिला और जिनमें क्लोरोफ़िल है।","kn":"ಎಲೆಗಳು ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆಯಿಂದ ಆಹಾರ (ಗ್ಲೂಕೋಸ್) ತಯಾರಿಸಿ ಪಿಷ್ಟವಾಗಿ ಸಂಗ್ರಹಿಸುತ್ತವೆ. ಅಯೋಡಿನ್ ಪಿಷ್ಟವನ್ನು ನೀಲಿ-ಕಪ್ಪಾಗಿಸುತ್ತದೆ. ಎರಡು ದಿನ ಕತ್ತಲಲ್ಲಿಟ್ಟ ಸಸ್ಯ ತನ್ನ ಪಿಷ್ಟ ಬಳಸಿಬಿಡುತ್ತದೆ (ಪಿಷ್ಟರಹಿತಗೊಳಿಸುವಿಕೆ). ನಂತರ ಬೆಳಕು ಸಿಕ್ಕಿದ ಮತ್ತು ಪತ್ರಹರಿತ್ತು ಇರುವ ಎಲೆಯ ಭಾಗಗಳು ಮಾತ್ರ ಹೊಸ ಪಿಷ್ಟ ತಯಾರಿಸುತ್ತವೆ."},"apparatus":[{"en":"Potted plant with some leaves partly covered by black paper","hi":"गमले का पौधा, जिसकी कुछ पत्तियाँ आंशिक रूप से काले कागज़ से ढकी हों","kn":"ಕೆಲವು ಎಲೆಗಳನ್ನು ಭಾಗಶಃ ಕಪ್ಪು ಕಾಗದದಿಂದ ಮುಚ್ಚಿದ ಕುಂಡದ ಸಸ್ಯ"},{"en":"A variegated leaf (such as croton)","hi":"एक चितकबरी पत्ती (जैसे क्रोटन)","kn":"ಒಂದು ಬಹುವರ್ಣದ ಎಲೆ (ಉದಾ. ಕ್ರೋಟನ್)"},{"en":"Beaker of water, test tube of alcohol, burner","hi":"पानी का बीकर, एल्कोहॉल की परखनली, बर्नर","kn":"ನೀರಿನ ಬೀಕರ್, ಆಲ್ಕೋಹಾಲ್‌ನ ಪರೀಕ್ಷಾನಳಿಕೆ, ಬರ್ನರ್"},{"en":"Iodine solution and a Petri dish","hi":"आयोडीन विलयन और पेट्री डिश","kn":"ಅಯೋಡಿನ್ ದ್ರಾವಣ ಮತ್ತು ಪೆಟ್ರಿ ಡಿಶ್"}],"steps":[{"en":"Keep the plant in the dark for two days so its leaves lose their starch.","hi":"पौधे को दो दिन अँधेरे में रखें ताकि उसकी पत्तियों का मंड खत्म हो जाए।","kn":"ಸಸ್ಯವನ್ನು ಎರಡು ದಿನ ಕತ್ತಲಲ್ಲಿಡಿ, ಅದರ ಎಲೆಗಳ ಪಿಷ್ಟ ಖಾಲಿಯಾಗಲಿ."},{"en":"Cover part of one leaf with black paper on both sides, and keep the plant in sunlight for a few hours.","hi":"एक पत्ती के कुछ भाग को दोनों ओर से काले कागज़ से ढकें, और पौधे को कुछ घंटे धूप में रखें।","kn":"ಒಂದು ಎಲೆಯ ಒಂದು ಭಾಗವನ್ನು ಎರಡೂ ಕಡೆ ಕಪ್ಪು ಕಾಗದದಿಂದ ಮುಚ್ಚಿ, ಸಸ್ಯವನ್ನು ಕೆಲವು ಗಂಟೆ ಬಿಸಿಲಲ್ಲಿಡಿ."},{"en":"Pluck the leaf, remove the paper and boil the leaf in water for a few minutes to soften it.","hi":"पत्ती तोड़ें, कागज़ हटाएँ और पत्ती को नरम करने के लिए कुछ मिनट पानी में उबालें।","kn":"ಎಲೆ ಕಿತ್ತು, ಕಾಗದ ತೆಗೆದು, ಮೃದುವಾಗಲು ಕೆಲವು ನಿಮಿಷ ನೀರಿನಲ್ಲಿ ಕುದಿಸಿ."},{"en":"Put the leaf in alcohol and heat it in a water bath until the leaf turns pale: the chlorophyll dissolves out.","hi":"पत्ती को एल्कोहॉल में रखकर जल-ऊष्मक में गरम करें जब तक वह फीकी न हो जाए: क्लोरोफ़िल घुलकर निकल जाता है।","kn":"ಎಲೆಯನ್ನು ಆಲ್ಕೋಹಾಲ್‌ನಲ್ಲಿಟ್ಟು ಜಲಸ್ನಾನದಲ್ಲಿ ಎಲೆ ಮಸುಕಾಗುವವರೆಗೆ ಕಾಯಿಸಿ: ಪತ್ರಹರಿತ್ತು ಕರಗಿ ಹೊರಬರುತ್ತದೆ."},{"en":"Wash the leaf in warm water and spread it in a Petri dish.","hi":"पत्ती को गुनगुने पानी में धोकर पेट्री डिश में फैलाएँ।","kn":"ಎಲೆಯನ್ನು ಉಗುರುಬೆಚ್ಚಗಿನ ನೀರಿನಲ್ಲಿ ತೊಳೆದು ಪೆಟ್ರಿ ಡಿಶ್‌ನಲ್ಲಿ ಹರಡಿ."},{"en":"Pour a few drops of iodine over the leaf and note which parts turn blue-black.","hi":"पत्ती पर आयोडीन की कुछ बूँदें डालें और देखें कौन-से भाग नीले-काले होते हैं।","kn":"ಎಲೆಯ ಮೇಲೆ ಕೆಲವು ಹನಿ ಅಯೋಡಿನ್ ಹಾಕಿ, ಯಾವ ಭಾಗಗಳು ನೀಲಿ-ಕಪ್ಪಾಗುತ್ತವೆ ನೋಡಿ."},{"en":"Repeat with a variegated leaf and with a leaf from a plant kept in the dark.","hi":"चितकबरी पत्ती और अँधेरे में रखे पौधे की पत्ती के साथ दोहराएँ।","kn":"ಬಹುವರ್ಣದ ಎಲೆ ಮತ್ತು ಕತ್ತಲಲ್ಲಿಟ್ಟ ಸಸ್ಯದ ಎಲೆಯೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Alcohol catches fire easily: heat it only in a water bath, never over a flame.","hi":"एल्कोहॉल आसानी से आग पकड़ता है: इसे केवल जल-ऊष्मक में गरम करें, सीधे लौ पर कभी नहीं।","kn":"ಆಲ್ಕೋಹಾಲ್ ಸುಲಭವಾಗಿ ಬೆಂಕಿ ಹಿಡಿಯುತ್ತದೆ: ಜಲಸ್ನಾನದಲ್ಲಿ ಮಾತ್ರ ಕಾಯಿಸಿ, ನೇರ ಜ್ವಾಲೆಯ ಮೇಲೆ ಎಂದೂ ಬೇಡ."},{"en":"Handle the soft leaf gently so it does not tear.","hi":"नरम पत्ती को धीरे से संभालें ताकि वह फटे नहीं।","kn":"ಮೃದು ಎಲೆಯನ್ನು ಹರಿಯದಂತೆ ಮೃದುವಾಗಿ ಹಿಡಿಯಿರಿ."},{"en":"Destarch the plant fully before the experiment.","hi":"प्रयोग से पहले पौधे को पूरी तरह मंड-रहित करें।","kn":"ಪ್ರಯೋಗಕ್ಕೆ ಮೊದಲು ಸಸ್ಯವನ್ನು ಸಂಪೂರ್ಣ ಪಿಷ್ಟರಹಿತಗೊಳಿಸಿ."}],"conclusion":{"en":"Only the uncovered part of the leaf turns blue-black, so starch forms only where light falls. In a variegated leaf only the green parts turn blue-black, so chlorophyll is needed. A leaf from a plant kept in the dark shows no starch.","hi":"पत्ती का केवल खुला भाग नीला-काला होता है, इसलिए मंड वहीं बनता है जहाँ प्रकाश पड़ता है। चितकबरी पत्ती में केवल हरे भाग नीले-काले होते हैं, इसलिए क्लोरोफ़िल आवश्यक है। अँधेरे में रखे पौधे की पत्ती में मंड नहीं मिलता।","kn":"ಎಲೆಯ ತೆರೆದ ಭಾಗ ಮಾತ್ರ ನೀಲಿ-ಕಪ್ಪಾಗುತ್ತದೆ; ಬೆಳಕು ಬಿದ್ದಲ್ಲಿ ಮಾತ್ರ ಪಿಷ್ಟ ಉಂಟಾಗುತ್ತದೆ. ಬಹುವರ್ಣದ ಎಲೆಯಲ್ಲಿ ಹಸಿರು ಭಾಗಗಳು ಮಾತ್ರ ನೀಲಿ-ಕಪ್ಪಾಗುತ್ತವೆ; ಪತ್ರಹರಿತ್ತು ಅಗತ್ಯ. ಕತ್ತಲಲ್ಲಿಟ್ಟ ಸಸ್ಯದ ಎಲೆಯಲ್ಲಿ ಪಿಷ್ಟ ಇಲ್ಲ."},"viva":[{"q":{"en":"Why is the leaf boiled in alcohol?","hi":"पत्ती को एल्कोहॉल में क्यों उबाला जाता है?","kn":"ಎಲೆಯನ್ನು ಆಲ್ಕೋಹಾಲ್‌ನಲ್ಲಿ ಏಕೆ ಕುದಿಸುತ್ತಾರೆ?"},"a":{"en":"To remove the chlorophyll, so the colour of the iodine test can be seen clearly.","hi":"क्लोरोफ़िल हटाने के लिए, ताकि आयोडीन परीक्षण का रंग साफ़ दिखे।","kn":"ಪತ್ರಹರಿತ್ತು ತೆಗೆಯಲು, ಅಯೋಡಿನ್ ಪರೀಕ್ಷೆಯ ಬಣ್ಣ ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣಲು."}},{"q":{"en":"What colour does iodine give with starch?","hi":"आयोडीन मंड के साथ कौन-सा रंग देता है?","kn":"ಅಯೋಡಿನ್ ಪಿಷ್ಟದೊಂದಿಗೆ ಯಾವ ಬಣ್ಣ ಕೊಡುತ್ತದೆ?"},"a":{"en":"Blue-black.","hi":"नीला-काला।","kn":"ನೀಲಿ-ಕಪ್ಪು."}},{"q":{"en":"Why is the plant kept in the dark first?","hi":"पौधे को पहले अँधेरे में क्यों रखा जाता है?","kn":"ಸಸ್ಯವನ್ನು ಮೊದಲು ಕತ್ತಲಲ್ಲಿ ಏಕೆ ಇಡುತ್ತಾರೆ?"},"a":{"en":"To use up the starch already in the leaves, so any starch found later is new.","hi":"पत्तियों में पहले से मौजूद मंड खत्म करने के लिए, ताकि बाद में मिला मंड नया हो।","kn":"ಎಲೆಗಳಲ್ಲಿ ಮೊದಲೇ ಇರುವ ಪಿಷ್ಟ ಖಾಲಿಯಾಗಲು, ನಂತರ ಸಿಕ್ಕ ಪಿಷ್ಟ ಹೊಸದಾಗಿರಲು."}},{"q":{"en":"Write the equation for photosynthesis in words.","hi":"प्रकाश-संश्लेषण का शब्द समीकरण लिखिए।","kn":"ದ್ಯುತಿಸಂಶ್ಲೇಷಣೆಯ ಪದ ಸಮೀಕರಣ ಬರೆಯಿರಿ."},"a":{"en":"Carbon dioxide + water → glucose + oxygen (in the presence of sunlight and chlorophyll).","hi":"कार्बन डाइऑक्साइड + जल → ग्लूकोज़ + ऑक्सीजन (सूर्य के प्रकाश और क्लोरोफ़िल की उपस्थिति में)।","kn":"ಕಾರ್ಬನ್ ಡೈಆಕ್ಸೈಡ್ + ನೀರು → ಗ್ಲೂಕೋಸ್ + ಆಮ್ಲಜನಕ (ಸೂರ್ಯನ ಬೆಳಕು ಮತ್ತು ಪತ್ರಹರಿತ್ತಿನ ಉಪಸ್ಥಿತಿಯಲ್ಲಿ)."}},{"q":{"en":"Why is alcohol heated in a water bath and not directly?","hi":"एल्कोहॉल को सीधे न गरम करके जल-ऊष्मक में क्यों गरम करते हैं?","kn":"ಆಲ್ಕೋಹಾಲನ್ನು ನೇರವಾಗಿ ಅಲ್ಲ, ಜಲಸ್ನಾನದಲ್ಲಿ ಏಕೆ ಕಾಯಿಸುತ್ತಾರೆ?"},"a":{"en":"Alcohol catches fire easily.","hi":"एल्कोहॉल आसानी से आग पकड़ लेता है।","kn":"ಆಲ್ಕೋಹಾಲ್ ಸುಲಭವಾಗಿ ಬೆಂಕಿ ಹಿಡಿಯುತ್ತದೆ."}}]},{"id":"triangle-angles","bench":"triangle","setup":{},"subject":"Mathematics","domain":"maths","levels":["7","9"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["triangle","triangles","the triangle and its properties","angle sum property","exterior angle","lines and angles","angles"],"title":{"en":"Angle sum of a triangle","hi":"त्रिभुज के कोणों का योग","kn":"ತ್ರಿಭುಜದ ಕೋನಗಳ ಮೊತ್ತ"},"summary":{"en":"Change a triangle, tear off its corners and place them on a line: they always make 180°.","hi":"त्रिभुज बदलें, उसके कोने फाड़कर एक रेखा पर रखें: वे हमेशा 180° बनाते हैं।","kn":"ತ್ರಿಭುಜ ಬದಲಿಸಿ, ಅದರ ಮೂಲೆಗಳನ್ನು ಹರಿದು ಒಂದು ರೇಖೆಯ ಮೇಲಿಡಿ: ಅವು ಯಾವಾಗಲೂ 180° ಮಾಡುತ್ತವೆ."},"aim":{"en":"To verify that the three angles of any triangle add up to 180°, and that an exterior angle equals the sum of the two interior opposite angles.","hi":"यह सत्यापित करना कि किसी भी त्रिभुज के तीनों कोणों का योग 180° होता है, और बहिष्कोण दोनों अंतःसम्मुख कोणों के योग के बराबर होता है।","kn":"ಯಾವುದೇ ತ್ರಿಭುಜದ ಮೂರು ಕೋನಗಳ ಮೊತ್ತ 180° ಎಂದು, ಮತ್ತು ಬಾಹ್ಯಕೋನ ಎರಡು ಅಂತರಾಭಿಮುಖ ಕೋನಗಳ ಮೊತ್ತಕ್ಕೆ ಸಮ ಎಂದು ಪರಿಶೀಲಿಸುವುದು."},"principle":{"en":"When the three corners of a paper triangle are torn off and placed side by side at one point, they fill a straight angle (180°). Extending one side makes an exterior angle; together with the adjacent interior angle it makes 180°, so it equals the sum of the other two angles.","hi":"कागज़ के त्रिभुज के तीनों कोने फाड़कर एक बिंदु पर साथ-साथ रखने पर वे एक ऋजु कोण (180°) भरते हैं। एक भुजा बढ़ाने पर बहिष्कोण बनता है; संलग्न अंतःकोण के साथ यह 180° बनाता है, इसलिए यह बाकी दो कोणों के योग के बराबर है।","kn":"ಕಾಗದದ ತ್ರಿಭುಜದ ಮೂರು ಮೂಲೆಗಳನ್ನು ಹರಿದು ಒಂದು ಬಿಂದುವಿನಲ್ಲಿ ಪಕ್ಕಪಕ್ಕ ಇಟ್ಟಾಗ ಅವು ಒಂದು ಸರಳಕೋನ (180°) ತುಂಬುತ್ತವೆ. ಒಂದು ಬಾಹುವನ್ನು ವಿಸ್ತರಿಸಿದಾಗ ಬಾಹ್ಯಕೋನ ಉಂಟಾಗುತ್ತದೆ; ಪಕ್ಕದ ಒಳಕೋನದೊಂದಿಗೆ ಅದು 180°; ಆದ್ದರಿಂದ ಅದು ಉಳಿದ ಎರಡು ಕೋನಗಳ ಮೊತ್ತಕ್ಕೆ ಸಮ."},"apparatus":[{"en":"Coloured paper","hi":"रंगीन कागज़","kn":"ಬಣ್ಣದ ಕಾಗದ"},{"en":"Scissors","hi":"कैंची","kn":"ಕತ್ತರಿ"},{"en":"Protractor, scale and pencil","hi":"चाँदा, पैमाना और पेंसिल","kn":"ಕೋನಮಾಪಕ, ಅಳತೆಪಟ್ಟಿ ಮತ್ತು ಪೆನ್ಸಿಲ್"},{"en":"Glue","hi":"गोंद","kn":"ಅಂಟು"}],"steps":[{"en":"Draw any triangle ABC on coloured paper and cut it out.","hi":"रंगीन कागज़ पर कोई भी त्रिभुज ABC बनाकर काट लें।","kn":"ಬಣ್ಣದ ಕಾಗದದ ಮೇಲೆ ಯಾವುದೇ ತ್ರಿಭುಜ ABC ಬಿಡಿಸಿ ಕತ್ತರಿಸಿ."},{"en":"Mark the three angles and measure each with a protractor.","hi":"तीनों कोणों को चिह्नित करें और हर एक को चाँदे से मापें।","kn":"ಮೂರು ಕೋನಗಳನ್ನು ಗುರುತಿಸಿ ಪ್ರತಿಯೊಂದನ್ನು ಕೋನಮಾಪಕದಿಂದ ಅಳೆಯಿರಿ."},{"en":"Add the three angles.","hi":"तीनों कोणों को जोड़ें।","kn":"ಮೂರು ಕೋನಗಳನ್ನು ಕೂಡಿಸಿ."},{"en":"Tear off the three corners and place them side by side with their points together on a straight line.","hi":"तीनों कोने फाड़कर उनकी नोकें मिलाकर एक सीधी रेखा पर साथ-साथ रखें।","kn":"ಮೂರು ಮೂಲೆಗಳನ್ನು ಹರಿದು ಅವುಗಳ ತುದಿಗಳನ್ನು ಒಟ್ಟುಗೂಡಿಸಿ ಸರಳರೇಖೆಯ ಮೇಲೆ ಪಕ್ಕಪಕ್ಕ ಇಡಿ."},{"en":"See that they exactly fill the straight line: 180°.","hi":"देखें कि वे सीधी रेखा को ठीक-ठीक भरते हैं: 180°।","kn":"ಅವು ಸರಳರೇಖೆಯನ್ನು ನಿಖರವಾಗಿ ತುಂಬುತ್ತವೆ ನೋಡಿ: 180°."},{"en":"Extend side BC beyond C and measure the exterior angle at C. Compare it with ∠A + ∠B.","hi":"भुजा BC को C से आगे बढ़ाएँ और C पर बहिष्कोण मापें। उसकी तुलना ∠A + ∠B से करें।","kn":"BC ಬಾಹುವನ್ನು C ಯ ಆಚೆ ವಿಸ್ತರಿಸಿ, C ಯಲ್ಲಿ ಬಾಹ್ಯಕೋನ ಅಳೆಯಿರಿ. ಅದನ್ನು ∠A + ∠B ಯೊಂದಿಗೆ ಹೋಲಿಸಿ."},{"en":"Repeat with an acute, a right and an obtuse triangle.","hi":"न्यूनकोण, समकोण और अधिककोण त्रिभुज के साथ दोहराएँ।","kn":"ಲಘುಕೋನ, ಲಂಬಕೋನ ಮತ್ತು ವಿಶಾಲಕೋನ ತ್ರಿಭುಜಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Measure each angle carefully, with the protractor base on one arm.","hi":"हर कोण को सावधानी से मापें, चाँदे का आधार एक भुजा पर रखकर।","kn":"ಕೋನಮಾಪಕದ ತಳವನ್ನು ಒಂದು ಬಾಹುವಿನ ಮೇಲಿಟ್ಟು ಪ್ರತಿ ಕೋನವನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ ಅಳೆಯಿರಿ."},{"en":"Mark the corners before tearing so you know which angle is which.","hi":"फाड़ने से पहले कोनों पर निशान लगाएँ ताकि पता रहे कौन-सा कोण कौन-सा है।","kn":"ಹರಿಯುವ ಮೊದಲು ಮೂಲೆಗಳಿಗೆ ಗುರುತು ಹಾಕಿ, ಯಾವ ಕೋನ ಯಾವುದು ತಿಳಿಯಲು."}],"conclusion":{"en":"In every triangle the three angles add up to 180°, whatever its shape. The exterior angle is equal to the sum of the two interior opposite angles.","hi":"हर त्रिभुज में, उसका आकार कैसा भी हो, तीनों कोणों का योग 180° होता है। बहिष्कोण दोनों अंतःसम्मुख कोणों के योग के बराबर होता है।","kn":"ಆಕಾರ ಏನೇ ಇರಲಿ, ಪ್ರತಿ ತ್ರಿಭುಜದಲ್ಲಿ ಮೂರು ಕೋನಗಳ ಮೊತ್ತ 180°. ಬಾಹ್ಯಕೋನ ಎರಡು ಅಂತರಾಭಿಮುಖ ಕೋನಗಳ ಮೊತ್ತಕ್ಕೆ ಸಮ."},"viva":[{"q":{"en":"Can a triangle have two right angles?","hi":"क्या किसी त्रिभुज में दो समकोण हो सकते हैं?","kn":"ತ್ರಿಭುಜಕ್ಕೆ ಎರಡು ಲಂಬಕೋನಗಳಿರಬಹುದೇ?"},"a":{"en":"No: they would already make 180°, leaving nothing for the third angle.","hi":"नहीं: वे ही 180° बना देंगे, तीसरे कोण के लिए कुछ नहीं बचेगा।","kn":"ಇಲ್ಲ: ಅವೇ 180° ಆಗುತ್ತವೆ, ಮೂರನೇ ಕೋನಕ್ಕೆ ಏನೂ ಉಳಿಯದು."}},{"q":{"en":"Two angles of a triangle are 50° and 60°. Find the third.","hi":"त्रिभुज के दो कोण 50° और 60° हैं। तीसरा ज्ञात कीजिए।","kn":"ತ್ರಿಭುಜದ ಎರಡು ಕೋನಗಳು 50° ಮತ್ತು 60°. ಮೂರನೆಯದನ್ನು ಕಂಡುಹಿಡಿಯಿರಿ."},"a":{"en":"70°.","hi":"70°।","kn":"70°."}},{"q":{"en":"What is each angle of an equilateral triangle?","hi":"समबाहु त्रिभुज का हर कोण कितना होता है?","kn":"ಸಮಬಾಹು ತ್ರಿಭುಜದ ಪ್ರತಿ ಕೋನ ಎಷ್ಟು?"},"a":{"en":"60°.","hi":"60°।","kn":"60°."}},{"q":{"en":"An exterior angle is 110° and one interior opposite angle is 40°. Find the other.","hi":"एक बहिष्कोण 110° है और एक अंतःसम्मुख कोण 40° है। दूसरा ज्ञात कीजिए।","kn":"ಒಂದು ಬಾಹ್ಯಕೋನ 110°, ಒಂದು ಅಂತರಾಭಿಮುಖ ಕೋನ 40°. ಇನ್ನೊಂದನ್ನು ಕಂಡುಹಿಡಿಯಿರಿ."},"a":{"en":"70°.","hi":"70°।","kn":"70°."}},{"q":{"en":"Why do the torn corners make a straight line?","hi":"फाड़े गए कोने सीधी रेखा क्यों बनाते हैं?","kn":"ಹರಿದ ಮೂಲೆಗಳು ಸರಳರೇಖೆ ಏಕೆ ಮಾಡುತ್ತವೆ?"},"a":{"en":"Because together they measure 180°, which is a straight angle.","hi":"क्योंकि मिलकर उनका माप 180° है, जो एक ऋजु कोण है।","kn":"ಏಕೆಂದರೆ ಒಟ್ಟಾಗಿ ಅವುಗಳ ಅಳತೆ 180°, ಅದು ಸರಳಕೋನ."}}]},{"id":"separation","bench":"separation","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["6","9"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["separation","separation of substances","methods of separation","methods of separation in everyday life","is matter around us pure","mixture","mixtures","filtration","evaporation","decantation","sedimentation"],"title":{"en":"Separating mixtures","hi":"मिश्रणों का पृथक्करण","kn":"ಮಿಶ್ರಣಗಳನ್ನು ಬೇರ್ಪಡಿಸುವುದು"},"summary":{"en":"Try a magnet, settling and pouring off, filtering and evaporating on four mixtures, and find which method works for which.","hi":"चार मिश्रणों पर चुंबक, बैठाकर निथारना, छानना और वाष्पन आज़माएँ और पता करें कि कौन-सी विधि किसके लिए काम करती है।","kn":"ನಾಲ್ಕು ಮಿಶ್ರಣಗಳ ಮೇಲೆ ಕಾಂತ, ತಳಸೇರಿಸಿ ಬಸಿಯುವುದು, ಸೋಸುವುದು ಮತ್ತು ಆವೀಕರಣವನ್ನು ಪ್ರಯತ್ನಿಸಿ, ಯಾವ ವಿಧಾನ ಯಾವುದಕ್ಕೆ ಸರಿ ಎಂದು ಕಂಡುಕೊಳ್ಳಿ."},"aim":{"en":"To separate sand and water, salt and water, iron filings and sulphur, and oil and water, and to choose the right method for each.","hi":"रेत और पानी, नमक और पानी, लोहे का बुरादा और गंधक, तथा तेल और पानी को अलग करना, और हर एक के लिए सही विधि चुनना।","kn":"ಮರಳು ಮತ್ತು ನೀರು, ಉಪ್ಪು ಮತ್ತು ನೀರು, ಕಬ್ಬಿಣದ ಪುಡಿ ಮತ್ತು ಗಂಧಕ, ಎಣ್ಣೆ ಮತ್ತು ನೀರನ್ನು ಬೇರ್ಪಡಿಸಿ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ಸರಿಯಾದ ವಿಧಾನ ಆರಿಸುವುದು."},"principle":{"en":"The parts of a mixture keep their own properties, so a mixture can be separated by a method that uses a property in which the parts differ. A magnet picks out a magnetic part. Heavy, insoluble solids settle, and the liquid above can be poured off (sedimentation and decantation). Filter paper holds back insoluble solids but lets liquids and anything dissolved in them pass. Evaporation drives off a liquid and leaves a dissolved solid behind. Liquids that do not mix form layers, and the top layer can be poured off.","hi":"मिश्रण के घटक अपने गुण बनाए रखते हैं, इसलिए उसे ऐसी विधि से अलग किया जा सकता है जो उस गुण का उपयोग करे जिसमें घटक भिन्न हैं। चुंबक चुंबकीय घटक को उठा लेता है। भारी, अघुलनशील ठोस नीचे बैठ जाते हैं और ऊपर का द्रव निथारा जा सकता है (अवसादन और निस्तारण)। फ़िल्टर पेपर अघुलनशील ठोस को रोक लेता है, पर द्रव और उसमें घुली चीज़ें पार हो जाती हैं। वाष्पन द्रव को उड़ा देता है और घुला ठोस पीछे रह जाता है। न मिलने वाले द्रव परतें बनाते हैं और ऊपर की परत निथारी जा सकती है।","kn":"ಮಿಶ್ರಣದ ಘಟಕಗಳು ತಮ್ಮ ಗುಣಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳುತ್ತವೆ; ಆದ್ದರಿಂದ ಘಟಕಗಳು ಭಿನ್ನವಾಗಿರುವ ಗುಣವನ್ನು ಬಳಸುವ ವಿಧಾನದಿಂದ ಮಿಶ್ರಣವನ್ನು ಬೇರ್ಪಡಿಸಬಹುದು. ಕಾಂತವು ಕಾಂತೀಯ ಘಟಕವನ್ನು ಎತ್ತಿಕೊಳ್ಳುತ್ತದೆ. ಭಾರವಾದ, ಕರಗದ ಘನಗಳು ತಳ ಸೇರುತ್ತವೆ; ಮೇಲಿನ ದ್ರವವನ್ನು ಬಸಿಯಬಹುದು (ತಳಸೇರುವಿಕೆ ಮತ್ತು ಬಸಿಯುವಿಕೆ). ಸೋಸುವ ಕಾಗದ ಕರಗದ ಘನಗಳನ್ನು ತಡೆಯುತ್ತದೆ, ಆದರೆ ದ್ರವ ಮತ್ತು ಅದರಲ್ಲಿ ಕರಗಿದವುಗಳನ್ನು ಹಾದುಹೋಗಲು ಬಿಡುತ್ತದೆ. ಆವೀಕರಣ ದ್ರವವನ್ನು ಆವಿಯಾಗಿಸಿ ಕರಗಿದ ಘನವನ್ನು ಉಳಿಸುತ್ತದೆ. ಬೆರೆಯದ ದ್ರವಗಳು ಪದರಗಳಾಗುತ್ತವೆ; ಮೇಲಿನ ಪದರವನ್ನು ಬಸಿಯಬಹುದು."},"apparatus":[{"en":"Beakers and a glass rod","hi":"बीकर और काँच की छड़","kn":"ಬೀಕರ್‌ಗಳು ಮತ್ತು ಗಾಜಿನ ಕಡ್ಡಿ"},{"en":"Funnel, filter paper and a stand","hi":"कीप, फ़िल्टर पेपर और स्टैंड","kn":"ಆಲಿಕೆ, ಸೋಸುವ ಕಾಗದ ಮತ್ತು ಸ್ಟ್ಯಾಂಡ್"},{"en":"China dish, tripod, wire gauze and burner","hi":"चीनी मिट्टी की प्याली, तिपाई, तार की जाली और बर्नर","kn":"ಪಿಂಗಾಣಿ ಬಟ್ಟಲು, ಮುಕ್ಕಾಲಿ, ತಂತಿಜಾಲರಿ ಮತ್ತು ಬರ್ನರ್"},{"en":"A bar magnet","hi":"एक छड़ चुंबक","kn":"ಒಂದು ದಂಡಕಾಂತ"},{"en":"Sand, common salt, iron filings, sulphur powder, cooking oil, water","hi":"रेत, साधारण नमक, लोहे का बुरादा, गंधक चूर्ण, खाने का तेल, पानी","kn":"ಮರಳು, ಅಡುಗೆ ಉಪ್ಪು, ಕಬ್ಬಿಣದ ಪುಡಿ, ಗಂಧಕದ ಪುಡಿ, ಅಡುಗೆ ಎಣ್ಣೆ, ನೀರು"}],"steps":[{"en":"Make the four mixtures: sand in water, salt dissolved in water, iron filings with sulphur powder, and oil shaken with water.","hi":"चार मिश्रण बनाएँ: पानी में रेत, पानी में घुला नमक, लोहे के बुरादे के साथ गंधक चूर्ण, और पानी के साथ हिलाया तेल।","kn":"ನಾಲ್ಕು ಮಿಶ್ರಣ ತಯಾರಿಸಿ: ನೀರಿನಲ್ಲಿ ಮರಳು, ನೀರಿನಲ್ಲಿ ಕರಗಿದ ಉಪ್ಪು, ಕಬ್ಬಿಣದ ಪುಡಿ ಜೊತೆಗೆ ಗಂಧಕದ ಪುಡಿ, ನೀರಿನೊಂದಿಗೆ ಕುಲುಕಿದ ಎಣ್ಣೆ."},{"en":"Move a magnet over each mixture and see whether any part is pulled out.","hi":"हर मिश्रण के ऊपर चुंबक घुमाएँ और देखें कि कोई भाग खिंचकर निकलता है या नहीं।","kn":"ಪ್ರತಿ ಮಿಶ್ರಣದ ಮೇಲೆ ಕಾಂತ ಆಡಿಸಿ, ಯಾವುದಾದರೂ ಭಾಗ ಸೆಳೆಯಲ್ಪಡುತ್ತದೆಯೇ ನೋಡಿ."},{"en":"Let a liquid mixture stand. When a layer settles, tip the beaker and pour the top part off slowly along a glass rod.","hi":"द्रव मिश्रण को रखा रहने दें। जब परत बैठ जाए, बीकर झुकाकर ऊपर का भाग काँच की छड़ के सहारे धीरे-धीरे निथारें।","kn":"ದ್ರವ ಮಿಶ್ರಣವನ್ನು ಹಾಗೆಯೇ ಇಡಿ. ಪದರ ತಳ ಸೇರಿದಾಗ ಬೀಕರನ್ನು ಓರೆ ಮಾಡಿ ಮೇಲಿನ ಭಾಗವನ್ನು ಗಾಜಿನ ಕಡ್ಡಿಯ ಉದ್ದಕ್ಕೆ ನಿಧಾನವಾಗಿ ಬಸಿಯಿರಿ."},{"en":"Fold a filter paper into a cone, fit it in the funnel, wet it, and pour a mixture through. Look at what stays on the paper (residue) and what passes (filtrate).","hi":"फ़िल्टर पेपर को मोड़कर शंकु बनाएँ, कीप में लगाकर गीला करें और मिश्रण उसमें डालें। देखें कि कागज़ पर क्या रुकता है (अवशेष) और क्या पार होता है (निस्यंद)।","kn":"ಸೋಸುವ ಕಾಗದವನ್ನು ಶಂಕುವಾಗಿ ಮಡಿಸಿ ಆಲಿಕೆಯಲ್ಲಿಟ್ಟು ಒದ್ದೆ ಮಾಡಿ, ಮಿಶ್ರಣ ಸುರಿಯಿರಿ. ಕಾಗದದ ಮೇಲೆ ಉಳಿಯುವುದು (ಶೇಷ) ಮತ್ತು ಹಾದುಹೋಗುವುದು (ಸೋಸಿದ ದ್ರವ) ನೋಡಿ."},{"en":"Heat a little of a mixture in a china dish until the water has gone. Look at what is left.","hi":"मिश्रण का थोड़ा भाग चीनी मिट्टी की प्याली में तब तक गरम करें जब तक पानी उड़ न जाए। देखें कि क्या बचा।","kn":"ಮಿಶ್ರಣದ ಸ್ವಲ್ಪ ಭಾಗವನ್ನು ಪಿಂಗಾಣಿ ಬಟ್ಟಲಲ್ಲಿ ನೀರು ಹೋಗುವವರೆಗೆ ಕಾಯಿಸಿ. ಏನು ಉಳಿಯಿತು ನೋಡಿ."},{"en":"Record, for each mixture and method, whether it separated and what you got.","hi":"हर मिश्रण और विधि के लिए लिखें कि वह अलग हुआ या नहीं और क्या मिला।","kn":"ಪ್ರತಿ ಮಿಶ್ರಣ ಮತ್ತು ವಿಧಾನಕ್ಕೆ, ಅದು ಬೇರ್ಪಟ್ಟಿತೇ ಮತ್ತು ಏನು ದೊರಕಿತು ದಾಖಲಿಸಿ."},{"en":"For each mixture, name the best method and the property it uses.","hi":"हर मिश्रण के लिए सबसे अच्छी विधि और उसमें उपयोग होने वाला गुण बताइए।","kn":"ಪ್ರತಿ ಮಿಶ್ರಣಕ್ಕೆ ಉತ್ತಮ ವಿಧಾನ ಮತ್ತು ಅದು ಬಳಸುವ ಗುಣವನ್ನು ಹೆಸರಿಸಿ."}],"precautions":[{"en":"Heat the china dish gently and stop before it is completely dry, so the salt does not spit.","hi":"चीनी मिट्टी की प्याली को धीरे गरम करें और पूरी तरह सूखने से पहले रोकें, ताकि नमक न उछले।","kn":"ಪಿಂಗಾಣಿ ಬಟ್ಟಲನ್ನು ನಿಧಾನವಾಗಿ ಕಾಯಿಸಿ, ಪೂರ್ತಿ ಒಣಗುವ ಮೊದಲೇ ನಿಲ್ಲಿಸಿ, ಉಪ್ಪು ಸಿಡಿಯದಂತೆ."},{"en":"Do not heat the oil mixture over a flame: hot oil can catch fire.","hi":"तेल वाले मिश्रण को लौ पर गरम न करें: गरम तेल में आग लग सकती है।","kn":"ಎಣ್ಣೆಯ ಮಿಶ್ರಣವನ್ನು ಜ್ವಾಲೆಯ ಮೇಲೆ ಕಾಯಿಸಬೇಡಿ: ಬಿಸಿ ಎಣ್ಣೆಗೆ ಬೆಂಕಿ ಹತ್ತಬಹುದು."},{"en":"Wrap the magnet in paper or plastic so the filings come off easily.","hi":"चुंबक को कागज़ या प्लास्टिक में लपेटें ताकि बुरादा आसानी से छूट जाए।","kn":"ಪುಡಿ ಸುಲಭವಾಗಿ ಬಿಡಿಸಲು ಕಾಂತವನ್ನು ಕಾಗದ ಅಥವಾ ಪ್ಲಾಸ್ಟಿಕ್‌ನಲ್ಲಿ ಸುತ್ತಿ."},{"en":"Pour slowly and along a glass rod so the settled layer is not stirred up.","hi":"धीरे-धीरे और काँच की छड़ के सहारे निथारें, ताकि बैठी हुई परत न उठे।","kn":"ತಳಸೇರಿದ ಪದರ ಕಲಕದಂತೆ ನಿಧಾನವಾಗಿ, ಗಾಜಿನ ಕಡ್ಡಿಯ ಉದ್ದಕ್ಕೆ ಬಸಿಯಿರಿ."}],"conclusion":{"en":"Sand and water separate by settling and pouring off, or by filtering. Salt stays dissolved: filtering and settling do not remove it, but evaporation leaves it in the dish. A magnet picks the iron filings out of sulphur. Oil floats on water and can be poured off the top. Each method works only for a mixture whose parts differ in the property it uses.","hi":"रेत और पानी बैठाकर निथारने से या छानने से अलग होते हैं। नमक घुला रहता है: छानने और बैठाने से वह नहीं निकलता, पर वाष्पन से प्याली में बच जाता है। चुंबक गंधक में से लोहे का बुरादा निकाल लेता है। तेल पानी पर तैरता है और ऊपर से निथारा जा सकता है। हर विधि केवल उसी मिश्रण के लिए काम करती है जिसके घटक उस गुण में भिन्न हों।","kn":"ಮರಳು ಮತ್ತು ನೀರು ತಳಸೇರಿಸಿ ಬಸಿಯುವುದರಿಂದ ಅಥವಾ ಸೋಸುವುದರಿಂದ ಬೇರ್ಪಡುತ್ತವೆ. ಉಪ್ಪು ಕರಗಿಯೇ ಇರುತ್ತದೆ: ಸೋಸುವಿಕೆ ಮತ್ತು ತಳಸೇರುವಿಕೆ ಅದನ್ನು ತೆಗೆಯದು, ಆದರೆ ಆವೀಕರಣ ಅದನ್ನು ಬಟ್ಟಲಲ್ಲಿ ಉಳಿಸುತ್ತದೆ. ಕಾಂತ ಗಂಧಕದಿಂದ ಕಬ್ಬಿಣದ ಪುಡಿಯನ್ನು ಆರಿಸುತ್ತದೆ. ಎಣ್ಣೆ ನೀರಿನ ಮೇಲೆ ತೇಲುತ್ತದೆ; ಮೇಲಿನಿಂದ ಬಸಿಯಬಹುದು. ಪ್ರತಿ ವಿಧಾನ, ಘಟಕಗಳು ಅದು ಬಳಸುವ ಗುಣದಲ್ಲಿ ಭಿನ್ನವಾಗಿರುವ ಮಿಶ್ರಣಕ್ಕೆ ಮಾತ್ರ ಕೆಲಸ ಮಾಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why does filtering not separate salt from water?","hi":"छानने से नमक पानी से अलग क्यों नहीं होता?","kn":"ಸೋಸುವಿಕೆಯಿಂದ ಉಪ್ಪು ನೀರಿನಿಂದ ಏಕೆ ಬೇರ್ಪಡುವುದಿಲ್ಲ?"},"a":{"en":"The salt is dissolved; its particles are small enough to pass through the filter paper with the water.","hi":"नमक घुला हुआ है; उसके कण इतने छोटे हैं कि पानी के साथ फ़िल्टर पेपर से निकल जाते हैं।","kn":"ಉಪ್ಪು ಕರಗಿದೆ; ಅದರ ಕಣಗಳು ನೀರಿನೊಂದಿಗೆ ಸೋಸುವ ಕಾಗದದ ಮೂಲಕ ಹಾದುಹೋಗುವಷ್ಟು ಚಿಕ್ಕವು."}},{"q":{"en":"What is the liquid that passes through the filter paper called?","hi":"फ़िल्टर पेपर से पार होने वाले द्रव को क्या कहते हैं?","kn":"ಸೋಸುವ ಕಾಗದದ ಮೂಲಕ ಹಾದುಹೋಗುವ ದ್ರವವನ್ನು ಏನೆನ್ನುತ್ತಾರೆ?"},"a":{"en":"The filtrate. What stays on the paper is the residue.","hi":"निस्यंद। कागज़ पर जो बचता है वह अवशेष है।","kn":"ಸೋಸಿದ ದ್ರವ (ಫಿಲ್ಟ್ರೇಟ್). ಕಾಗದದ ಮೇಲೆ ಉಳಿಯುವುದು ಶೇಷ."}},{"q":{"en":"Which property of iron lets us separate it from sulphur?","hi":"लोहे का कौन-सा गुण उसे गंधक से अलग करने देता है?","kn":"ಕಬ್ಬಿಣದ ಯಾವ ಗುಣ ಅದನ್ನು ಗಂಧಕದಿಂದ ಬೇರ್ಪಡಿಸಲು ಬಿಡುತ್ತದೆ?"},"a":{"en":"Iron is attracted by a magnet; sulphur is not.","hi":"लोहा चुंबक से आकर्षित होता है; गंधक नहीं।","kn":"ಕಬ್ಬಿಣ ಕಾಂತದಿಂದ ಆಕರ್ಷಿಸಲ್ಪಡುತ್ತದೆ; ಗಂಧಕ ಇಲ್ಲ."}},{"q":{"en":"How is salt obtained from sea water?","hi":"समुद्र के पानी से नमक कैसे प्राप्त किया जाता है?","kn":"ಸಮುದ್ರದ ನೀರಿನಿಂದ ಉಪ್ಪನ್ನು ಹೇಗೆ ಪಡೆಯುತ್ತಾರೆ?"},"a":{"en":"By evaporation: the water is left in shallow pans in the sun and the salt remains.","hi":"वाष्पन से: पानी को धूप में उथली क्यारियों में छोड़ा जाता है और नमक बच जाता है।","kn":"ಆವೀಕರಣದಿಂದ: ನೀರನ್ನು ಬಿಸಿಲಲ್ಲಿ ಆಳವಿಲ್ಲದ ಮಡಿಗಳಲ್ಲಿ ಬಿಡುತ್ತಾರೆ; ಉಪ್ಪು ಉಳಿಯುತ್ತದೆ."}},{"q":{"en":"Which apparatus separates oil and water neatly?","hi":"कौन-सा उपकरण तेल और पानी को साफ़-साफ़ अलग करता है?","kn":"ಯಾವ ಉಪಕರಣ ಎಣ್ಣೆ ಮತ್ತು ನೀರನ್ನು ಅಚ್ಚುಕಟ್ಟಾಗಿ ಬೇರ್ಪಡಿಸುತ್ತದೆ?"},"a":{"en":"A separating funnel: the lower water layer is run out through the tap.","hi":"पृथक्कारी कीप: नीचे की पानी की परत टोंटी से निकाल ली जाती है।","kn":"ಬೇರ್ಪಡಿಸುವ ಆಲಿಕೆ: ಕೆಳಗಿನ ನೀರಿನ ಪದರವನ್ನು ನಲ್ಲಿಯ ಮೂಲಕ ಹೊರಬಿಡಲಾಗುತ್ತದೆ."}}]},{"id":"rusting","bench":"rusting","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["7","8"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["rusting","rust","corrosion","chemical changes","physical and chemical changes","changes around us physical and chemical","galvanisation","galvanization","materials metals and non metals"],"title":{"en":"Conditions for rusting","hi":"जंग लगने की दशाएँ","kn":"ತುಕ್ಕು ಹಿಡಿಯಲು ಬೇಕಾದ ಸ್ಥಿತಿಗಳು"},"summary":{"en":"Watch iron nails in four test tubes for a week and find what iron needs in order to rust.","hi":"चार परखनलियों में लोहे की कीलों को एक सप्ताह तक देखें और पता करें कि जंग लगने के लिए लोहे को क्या चाहिए।","kn":"ನಾಲ್ಕು ಪರೀಕ್ಷಾನಳಿಗಳಲ್ಲಿ ಕಬ್ಬಿಣದ ಮೊಳೆಗಳನ್ನು ಒಂದು ವಾರ ಗಮನಿಸಿ, ತುಕ್ಕು ಹಿಡಿಯಲು ಕಬ್ಬಿಣಕ್ಕೆ ಏನು ಬೇಕು ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To show that iron rusts only when both air (oxygen) and water are present, and that salt water speeds up rusting.","hi":"दिखाना कि लोहे पर जंग तभी लगता है जब हवा (ऑक्सीजन) और पानी दोनों हों, और खारा पानी जंग लगना तेज़ करता है।","kn":"ಗಾಳಿ (ಆಮ್ಲಜನಕ) ಮತ್ತು ನೀರು ಎರಡೂ ಇದ್ದಾಗ ಮಾತ್ರ ಕಬ್ಬಿಣಕ್ಕೆ ತುಕ್ಕು ಹಿಡಿಯುತ್ತದೆ ಮತ್ತು ಉಪ್ಪುನೀರು ಅದನ್ನು ಚುರುಕುಗೊಳಿಸುತ್ತದೆ ಎಂದು ತೋರಿಸುವುದು."},"principle":{"en":"Rust is a reddish-brown substance (hydrated iron oxide) that forms when iron reacts with oxygen and water together. It is a chemical change: a new substance is made. Boiling removes the air dissolved in water, and a layer of oil stops air from dissolving again. Anhydrous calcium chloride absorbs moisture and keeps the air dry. Dissolved salt helps the reaction go faster, which is why iron rusts quickly near the sea.","hi":"जंग लाल-भूरा पदार्थ (जलयुक्त आयरन ऑक्साइड) है जो तब बनता है जब लोहा ऑक्सीजन और पानी दोनों से एक साथ अभिक्रिया करता है। यह रासायनिक परिवर्तन है: नया पदार्थ बनता है। उबालने से पानी में घुली हवा निकल जाती है और तेल की परत हवा को दोबारा घुलने से रोकती है। निर्जल कैल्सियम क्लोराइड नमी सोखकर हवा को सूखा रखता है। घुला नमक अभिक्रिया को तेज़ करता है, इसीलिए समुद्र के पास लोहे पर जल्दी जंग लगता है।","kn":"ತುಕ್ಕು ಕೆಂಪು-ಕಂದು ವಸ್ತು (ಜಲಯುಕ್ತ ಕಬ್ಬಿಣದ ಆಕ್ಸೈಡ್); ಕಬ್ಬಿಣ ಆಮ್ಲಜನಕ ಮತ್ತು ನೀರಿನೊಂದಿಗೆ ಒಟ್ಟಿಗೆ ವರ್ತಿಸಿದಾಗ ಉಂಟಾಗುತ್ತದೆ. ಇದು ರಾಸಾಯನಿಕ ಬದಲಾವಣೆ: ಹೊಸ ವಸ್ತು ಉಂಟಾಗುತ್ತದೆ. ಕುದಿಸುವುದರಿಂದ ನೀರಿನಲ್ಲಿ ಕರಗಿದ ಗಾಳಿ ಹೊರಹೋಗುತ್ತದೆ; ಎಣ್ಣೆಯ ಪದರ ಗಾಳಿ ಮತ್ತೆ ಕರಗದಂತೆ ತಡೆಯುತ್ತದೆ. ನಿರ್ಜಲ ಕ್ಯಾಲ್ಸಿಯಂ ಕ್ಲೋರೈಡ್ ತೇವಾಂಶ ಹೀರಿ ಗಾಳಿಯನ್ನು ಒಣಗಿಸುತ್ತದೆ. ಕರಗಿದ ಉಪ್ಪು ಕ್ರಿಯೆಯನ್ನು ವೇಗಗೊಳಿಸುತ್ತದೆ; ಅದಕ್ಕೇ ಸಮುದ್ರದ ಬಳಿ ಕಬ್ಬಿಣಕ್ಕೆ ಬೇಗ ತುಕ್ಕು ಹಿಡಿಯುತ್ತದೆ."},"apparatus":[{"en":"Four test tubes in a stand, two corks","hi":"स्टैंड में चार परखनलियाँ, दो कॉर्क","kn":"ಸ್ಟ್ಯಾಂಡ್‌ನಲ್ಲಿ ನಾಲ್ಕು ಪರೀಕ್ಷಾನಳಿಗಳು, ಎರಡು ಬಿರಡೆಗಳು"},{"en":"Four clean iron nails (rubbed with sandpaper)","hi":"चार साफ़ लोहे की कीलें (रेगमाल से घिसी हुई)","kn":"ನಾಲ್ಕು ಸ್ವಚ್ಛ ಕಬ್ಬಿಣದ ಮೊಳೆಗಳು (ಮರಳುಕಾಗದದಿಂದ ಉಜ್ಜಿದವು)"},{"en":"Tap water, boiled water, a little oil, common salt","hi":"नल का पानी, उबला पानी, थोड़ा तेल, साधारण नमक","kn":"ನಲ್ಲಿ ನೀರು, ಕುದಿಸಿದ ನೀರು, ಸ್ವಲ್ಪ ಎಣ್ಣೆ, ಅಡುಗೆ ಉಪ್ಪು"},{"en":"Anhydrous calcium chloride and cotton wool","hi":"निर्जल कैल्सियम क्लोराइड और रुई","kn":"ನಿರ್ಜಲ ಕ್ಯಾಲ್ಸಿಯಂ ಕ್ಲೋರೈಡ್ ಮತ್ತು ಹತ್ತಿ"}],"steps":[{"en":"Rub the nails with sandpaper so they are bright and free of rust.","hi":"कीलों को रेगमाल से घिसें ताकि वे चमकदार और जंग-रहित हों।","kn":"ಮೊಳೆಗಳನ್ನು ಮರಳುಕಾಗದದಿಂದ ಉಜ್ಜಿ ಹೊಳೆಯುವಂತೆ, ತುಕ್ಕಿಲ್ಲದಂತೆ ಮಾಡಿ."},{"en":"Tube A: put a nail in and half fill with tap water, so the nail has air and water.","hi":"परखनली A: कील डालें और आधा नल का पानी भरें, ताकि कील को हवा और पानी दोनों मिलें।","kn":"ನಳಿಕೆ A: ಮೊಳೆ ಹಾಕಿ ಅರ್ಧ ನಲ್ಲಿ ನೀರು ತುಂಬಿ; ಮೊಳೆಗೆ ಗಾಳಿ ಮತ್ತು ನೀರು ಎರಡೂ ಸಿಗುತ್ತವೆ."},{"en":"Tube B: put a nail in, fill with freshly boiled water, pour a layer of oil on top and cork it: water but no air.","hi":"परखनली B: कील डालें, ताज़ा उबला पानी भरें, ऊपर तेल की परत डालें और कॉर्क लगाएँ: पानी है, हवा नहीं।","kn":"ನಳಿಕೆ B: ಮೊಳೆ ಹಾಕಿ, ಈಗ ಕುದಿಸಿದ ನೀರು ತುಂಬಿ, ಮೇಲೆ ಎಣ್ಣೆಯ ಪದರ ಹಾಕಿ ಬಿರಡೆ ಮುಚ್ಚಿ: ನೀರಿದೆ, ಗಾಳಿಯಿಲ್ಲ."},{"en":"Tube C: put anhydrous calcium chloride at the bottom, a nail above it, and cork it: air but no water.","hi":"परखनली C: तली में निर्जल कैल्सियम क्लोराइड, उसके ऊपर कील रखें और कॉर्क लगाएँ: हवा है, पानी नहीं।","kn":"ನಳಿಕೆ C: ತಳದಲ್ಲಿ ನಿರ್ಜಲ ಕ್ಯಾಲ್ಸಿಯಂ ಕ್ಲೋರೈಡ್, ಅದರ ಮೇಲೆ ಮೊಳೆ ಇಟ್ಟು ಬಿರಡೆ ಮುಚ್ಚಿ: ಗಾಳಿಯಿದೆ, ನೀರಿಲ್ಲ."},{"en":"Tube D: put a nail in salt water, half full, like tube A.","hi":"परखनली D: कील को आधे भरे खारे पानी में रखें, परखनली A की तरह।","kn":"ನಳಿಕೆ D: ನಳಿಕೆ A ಯಂತೆಯೇ, ಅರ್ಧ ತುಂಬಿದ ಉಪ್ಪುನೀರಿನಲ್ಲಿ ಮೊಳೆ ಇಡಿ."},{"en":"Leave the tubes for a week. Look at the nails every day and record how much rust has formed.","hi":"परखनलियों को एक सप्ताह के लिए छोड़ दें। हर दिन कीलों को देखें और लिखें कि कितना जंग लगा।","kn":"ನಳಿಕೆಗಳನ್ನು ಒಂದು ವಾರ ಬಿಡಿ. ಪ್ರತಿದಿನ ಮೊಳೆಗಳನ್ನು ನೋಡಿ, ಎಷ್ಟು ತುಕ್ಕು ಹಿಡಿದಿದೆ ದಾಖಲಿಸಿ."},{"en":"Compare the tubes and decide what iron needs in order to rust.","hi":"परखनलियों की तुलना करें और तय करें कि जंग लगने के लिए लोहे को क्या चाहिए।","kn":"ನಳಿಕೆಗಳನ್ನು ಹೋಲಿಸಿ, ತುಕ್ಕು ಹಿಡಿಯಲು ಕಬ್ಬಿಣಕ್ಕೆ ಏನು ಬೇಕು ನಿರ್ಧರಿಸಿ."}],"precautions":[{"en":"Use clean nails of the same kind in every tube.","hi":"हर परखनली में एक ही प्रकार की साफ़ कीलें लें।","kn":"ಪ್ರತಿ ನಳಿಕೆಯಲ್ಲೂ ಒಂದೇ ಬಗೆಯ ಸ್ವಚ್ಛ ಮೊಳೆಗಳನ್ನು ಬಳಸಿ."},{"en":"Cool the boiled water before pouring the oil, and cork tubes B and C tightly.","hi":"तेल डालने से पहले उबले पानी को ठंडा करें और परखनली B और C को कसकर बंद करें।","kn":"ಎಣ್ಣೆ ಹಾಕುವ ಮೊದಲು ಕುದಿಸಿದ ನೀರನ್ನು ತಣಿಸಿ; B ಮತ್ತು C ನಳಿಕೆಗಳನ್ನು ಬಿಗಿಯಾಗಿ ಮುಚ್ಚಿ."},{"en":"Do not touch calcium chloride with wet hands.","hi":"कैल्सियम क्लोराइड को गीले हाथों से न छुएँ।","kn":"ಕ್ಯಾಲ್ಸಿಯಂ ಕ್ಲೋರೈಡ್ ಅನ್ನು ಒದ್ದೆ ಕೈಗಳಿಂದ ಮುಟ್ಟಬೇಡಿ."}],"conclusion":{"en":"Only the nails in tubes A and D rusted. The nail in boiled water under oil (no air) and the nail over calcium chloride (no water) stayed bright. So iron needs both air and water to rust, and salt water makes it rust faster. Painting, oiling or galvanising keeps air and water away and prevents rusting.","hi":"केवल परखनली A और D की कीलों पर जंग लगा। तेल के नीचे उबले पानी वाली कील (हवा नहीं) और कैल्सियम क्लोराइड के ऊपर वाली कील (पानी नहीं) चमकदार रहीं। अतः जंग लगने के लिए लोहे को हवा और पानी दोनों चाहिए, और खारा पानी जंग जल्दी लगाता है। पेंट करना, तेल लगाना या यशदलेपन हवा और पानी को दूर रखकर जंग से बचाते हैं।","kn":"A ಮತ್ತು D ನಳಿಕೆಗಳ ಮೊಳೆಗಳಿಗೆ ಮಾತ್ರ ತುಕ್ಕು ಹಿಡಿಯಿತು. ಎಣ್ಣೆಯ ಕೆಳಗಿನ ಕುದಿಸಿದ ನೀರಿನಲ್ಲಿನ ಮೊಳೆ (ಗಾಳಿಯಿಲ್ಲ) ಮತ್ತು ಕ್ಯಾಲ್ಸಿಯಂ ಕ್ಲೋರೈಡ್ ಮೇಲಿನ ಮೊಳೆ (ನೀರಿಲ್ಲ) ಹೊಳೆಯುತ್ತಲೇ ಇದ್ದವು. ಆದ್ದರಿಂದ ತುಕ್ಕು ಹಿಡಿಯಲು ಕಬ್ಬಿಣಕ್ಕೆ ಗಾಳಿ ಮತ್ತು ನೀರು ಎರಡೂ ಬೇಕು; ಉಪ್ಪುನೀರು ಅದನ್ನು ವೇಗಗೊಳಿಸುತ್ತದೆ. ಬಣ್ಣ ಹಚ್ಚುವುದು, ಎಣ್ಣೆ ಸವರುವುದು ಅಥವಾ ಗ್ಯಾಲ್ವನೀಕರಣ ಗಾಳಿ ಮತ್ತು ನೀರನ್ನು ದೂರವಿಟ್ಟು ತುಕ್ಕು ತಡೆಯುತ್ತವೆ."},"viva":[{"q":{"en":"Is rusting a physical or a chemical change? Why?","hi":"जंग लगना भौतिक परिवर्तन है या रासायनिक? क्यों?","kn":"ತುಕ್ಕು ಹಿಡಿಯುವುದು ಭೌತಿಕ ಬದಲಾವಣೆಯೇ ರಾಸಾಯನಿಕವೇ? ಏಕೆ?"},"a":{"en":"Chemical: a new substance, rust, is formed and it cannot easily be turned back into iron.","hi":"रासायनिक: नया पदार्थ, जंग, बनता है और उसे आसानी से वापस लोहा नहीं बनाया जा सकता।","kn":"ರಾಸಾಯನಿಕ: ಹೊಸ ವಸ್ತು, ತುಕ್ಕು, ಉಂಟಾಗುತ್ತದೆ; ಅದನ್ನು ಸುಲಭವಾಗಿ ಮತ್ತೆ ಕಬ್ಬಿಣವಾಗಿಸಲಾಗದು."}},{"q":{"en":"Why is the water in tube B boiled?","hi":"परखनली B का पानी क्यों उबाला जाता है?","kn":"ನಳಿಕೆ B ಯ ನೀರನ್ನು ಏಕೆ ಕುದಿಸಲಾಗುತ್ತದೆ?"},"a":{"en":"Boiling drives out the air dissolved in the water.","hi":"उबालने से पानी में घुली हवा निकल जाती है।","kn":"ಕುದಿಸುವುದರಿಂದ ನೀರಿನಲ್ಲಿ ಕರಗಿದ ಗಾಳಿ ಹೊರಹೋಗುತ್ತದೆ."}},{"q":{"en":"What does anhydrous calcium chloride do in tube C?","hi":"परखनली C में निर्जल कैल्सियम क्लोराइड क्या करता है?","kn":"ನಳಿಕೆ C ಯಲ್ಲಿ ನಿರ್ಜಲ ಕ್ಯಾಲ್ಸಿಯಂ ಕ್ಲೋರೈಡ್ ಏನು ಮಾಡುತ್ತದೆ?"},"a":{"en":"It absorbs moisture, so the air around the nail is dry.","hi":"यह नमी सोख लेता है, इसलिए कील के आस-पास की हवा सूखी रहती है।","kn":"ಅದು ತೇವಾಂಶ ಹೀರುತ್ತದೆ; ಮೊಳೆಯ ಸುತ್ತಲಿನ ಗಾಳಿ ಒಣಗಿರುತ್ತದೆ."}},{"q":{"en":"Why do iron gates near the sea rust faster?","hi":"समुद्र के पास लोहे के फाटकों पर जंग जल्दी क्यों लगता है?","kn":"ಸಮುದ್ರದ ಬಳಿಯ ಕಬ್ಬಿಣದ ಗೇಟ್‌ಗಳಿಗೆ ಬೇಗ ತುಕ್ಕು ಏಕೆ ಹಿಡಿಯುತ್ತದೆ?"},"a":{"en":"The air is moist and carries salt, and salt speeds up rusting.","hi":"हवा नम होती है और उसमें नमक होता है, और नमक जंग लगना तेज़ करता है।","kn":"ಗಾಳಿ ತೇವವಾಗಿದ್ದು ಉಪ್ಪನ್ನು ಹೊತ್ತಿರುತ್ತದೆ; ಉಪ್ಪು ತುಕ್ಕನ್ನು ವೇಗಗೊಳಿಸುತ್ತದೆ."}},{"q":{"en":"What is galvanisation?","hi":"यशदलेपन क्या है?","kn":"ಗ್ಯಾಲ್ವನೀಕರಣ ಎಂದರೇನು?"},"a":{"en":"Coating iron with a thin layer of zinc so that it does not rust.","hi":"लोहे पर जस्ते की पतली परत चढ़ाना ताकि उस पर जंग न लगे।","kn":"ತುಕ್ಕು ಹಿಡಿಯದಂತೆ ಕಬ್ಬಿಣದ ಮೇಲೆ ಸತುವಿನ ತೆಳು ಪದರ ಲೇಪಿಸುವುದು."}}]},{"id":"germination","bench":"germination","setup":{},"subject":"Biology","domain":"biology","levels":["6","8"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["germination","seed germination","seed","seeds","sprouting","sprouts","living creatures exploring their characteristics","conditions for germination","reproduction in plants"],"title":{"en":"What seeds need to germinate","hi":"बीजों को अंकुरण के लिए क्या चाहिए","kn":"ಬೀಜಗಳು ಮೊಳಕೆಯೊಡೆಯಲು ಏನು ಬೇಕು"},"summary":{"en":"Keep moong seeds in four jars, each missing water, air or warmth (or nothing), and see which ones sprout.","hi":"मूँग के बीजों को चार जार में रखें, हर एक में पानी, हवा या गरमाहट न हो (या सब हो), और देखें कि कौन-से अंकुरित होते हैं।","kn":"ಹೆಸರುಕಾಳುಗಳನ್ನು ನಾಲ್ಕು ಜಾಡಿಗಳಲ್ಲಿಡಿ; ಪ್ರತಿಯೊಂದರಲ್ಲೂ ನೀರು, ಗಾಳಿ ಅಥವಾ ಬೆಚ್ಚನೆ ಇಲ್ಲ (ಅಥವಾ ಎಲ್ಲವೂ ಇದೆ); ಯಾವುವು ಮೊಳಕೆಯೊಡೆಯುತ್ತವೆ ನೋಡಿ."},"aim":{"en":"To show that seeds need water, air and a suitable temperature to germinate.","hi":"दिखाना कि बीजों को अंकुरण के लिए पानी, हवा और उचित तापमान चाहिए।","kn":"ಬೀಜಗಳು ಮೊಳಕೆಯೊಡೆಯಲು ನೀರು, ಗಾಳಿ ಮತ್ತು ಸೂಕ್ತ ತಾಪಮಾನ ಬೇಕು ಎಂದು ತೋರಿಸುವುದು."},"principle":{"en":"A seed holds a tiny plant (the embryo) and a store of food. When it takes in water it swells, and with oxygen from the air and a warm temperature the embryo uses its stored food to grow: the root comes out first, then the shoot. If any one of these conditions is missing, the seed does not germinate. Keeping everything the same except one condition in each jar is a fair test.","hi":"बीज में एक नन्हा पौधा (भ्रूण) और भोजन का भंडार होता है। पानी सोखने पर बीज फूलता है, और हवा की ऑक्सीजन तथा गरम तापमान मिलने पर भ्रूण संचित भोजन से बढ़ता है: पहले जड़ निकलती है, फिर तना। इनमें से कोई भी दशा न हो तो बीज अंकुरित नहीं होता। हर जार में एक दशा को छोड़ बाकी सब समान रखना एक निष्पक्ष परीक्षण है।","kn":"ಬೀಜದಲ್ಲಿ ಪುಟ್ಟ ಸಸ್ಯ (ಭ್ರೂಣ) ಮತ್ತು ಆಹಾರದ ಸಂಗ್ರಹ ಇರುತ್ತದೆ. ನೀರು ಹೀರಿದಾಗ ಬೀಜ ಉಬ್ಬುತ್ತದೆ; ಗಾಳಿಯ ಆಮ್ಲಜನಕ ಮತ್ತು ಬೆಚ್ಚನೆಯ ತಾಪಮಾನ ಸಿಕ್ಕಾಗ ಭ್ರೂಣ ಸಂಗ್ರಹಿತ ಆಹಾರ ಬಳಸಿ ಬೆಳೆಯುತ್ತದೆ: ಮೊದಲು ಬೇರು, ನಂತರ ಕಾಂಡ ಹೊರಬರುತ್ತದೆ. ಇವುಗಳಲ್ಲಿ ಯಾವುದಾದರೂ ಒಂದು ಇಲ್ಲದಿದ್ದರೆ ಬೀಜ ಮೊಳಕೆಯೊಡೆಯದು. ಪ್ರತಿ ಜಾಡಿಯಲ್ಲಿ ಒಂದು ಸ್ಥಿತಿ ಬಿಟ್ಟು ಉಳಿದೆಲ್ಲವನ್ನೂ ಒಂದೇ ರೀತಿ ಇಡುವುದು ನ್ಯಾಯಯುತ ಪರೀಕ್ಷೆ."},"apparatus":[{"en":"Four glass jars or beakers, labelled A to D","hi":"चार काँच के जार या बीकर, A से D तक अंकित","kn":"A ಯಿಂದ D ವರೆಗೆ ಗುರುತಿಸಿದ ನಾಲ್ಕು ಗಾಜಿನ ಜಾಡಿಗಳು ಅಥವಾ ಬೀಕರ್‌ಗಳು"},{"en":"Cotton wool and water","hi":"रुई और पानी","kn":"ಹತ್ತಿ ಮತ್ತು ನೀರು"},{"en":"Moong (green gram) seeds of the same size","hi":"एक ही आकार के मूँग के बीज","kn":"ಒಂದೇ ಗಾತ್ರದ ಹೆಸರುಕಾಳು ಬೀಜಗಳು"},{"en":"Boiled and cooled water, a little oil, a refrigerator","hi":"उबला और ठंडा किया पानी, थोड़ा तेल, एक रेफ़्रिजरेटर","kn":"ಕುದಿಸಿ ತಣಿಸಿದ ನೀರು, ಸ್ವಲ್ಪ ಎಣ್ಣೆ, ಒಂದು ರೆಫ್ರಿಜರೇಟರ್"}],"steps":[{"en":"Put a layer of cotton wool in each jar and place a few seeds on it.","hi":"हर जार में रुई की परत बिछाएँ और उस पर कुछ बीज रखें।","kn":"ಪ್ರತಿ ಜಾಡಿಯಲ್ಲಿ ಹತ್ತಿಯ ಪದರ ಹಾಸಿ ಅದರ ಮೇಲೆ ಕೆಲವು ಬೀಜಗಳನ್ನಿಡಿ."},{"en":"Jar A: keep the cotton dry.","hi":"जार A: रुई सूखी रखें।","kn":"ಜಾಡಿ A: ಹತ್ತಿಯನ್ನು ಒಣಗಿರಿಸಿ."},{"en":"Jar B: keep the cotton moist and the jar in the room.","hi":"जार B: रुई नम रखें और जार को कमरे में रखें।","kn":"ಜಾಡಿ B: ಹತ್ತಿಯನ್ನು ತೇವವಾಗಿರಿಸಿ, ಜಾಡಿಯನ್ನು ಕೊಠಡಿಯಲ್ಲಿಡಿ."},{"en":"Jar C: cover the seeds completely with boiled, cooled water and pour a thin layer of oil on top, so no air reaches them.","hi":"जार C: बीजों को उबले, ठंडे पानी से पूरा ढक दें और ऊपर तेल की पतली परत डालें, ताकि उन तक हवा न पहुँचे।","kn":"ಜಾಡಿ C: ಬೀಜಗಳನ್ನು ಕುದಿಸಿ ತಣಿಸಿದ ನೀರಿನಿಂದ ಪೂರ್ತಿ ಮುಚ್ಚಿ, ಮೇಲೆ ಎಣ್ಣೆಯ ತೆಳು ಪದರ ಹಾಕಿ; ಅವುಗಳಿಗೆ ಗಾಳಿ ತಲುಪದು."},{"en":"Jar D: keep the cotton moist but put the jar in a refrigerator.","hi":"जार D: रुई नम रखें पर जार को रेफ़्रिजरेटर में रखें।","kn":"ಜಾಡಿ D: ಹತ್ತಿಯನ್ನು ತೇವವಾಗಿರಿಸಿ, ಆದರೆ ಜಾಡಿಯನ್ನು ರೆಫ್ರಿಜರೇಟರ್‌ನಲ್ಲಿಡಿ."},{"en":"Look at the seeds every day for a week. Record which have germinated and measure the length of the sprouts.","hi":"एक सप्ताह तक हर दिन बीजों को देखें। लिखें कि कौन-से अंकुरित हुए और अंकुरों की लंबाई मापें।","kn":"ಒಂದು ವಾರ ಪ್ರತಿದಿನ ಬೀಜಗಳನ್ನು ನೋಡಿ. ಯಾವುವು ಮೊಳಕೆಯೊಡೆದಿವೆ ದಾಖಲಿಸಿ, ಮೊಳಕೆಯ ಉದ್ದ ಅಳೆಯಿರಿ."},{"en":"Compare the jars and decide which conditions seeds need.","hi":"जारों की तुलना करें और तय करें कि बीजों को कौन-सी दशाएँ चाहिए।","kn":"ಜಾಡಿಗಳನ್ನು ಹೋಲಿಸಿ, ಬೀಜಗಳಿಗೆ ಯಾವ ಸ್ಥಿತಿಗಳು ಬೇಕು ನಿರ್ಧರಿಸಿ."}],"precautions":[{"en":"Use the same number and kind of seeds in every jar.","hi":"हर जार में एक ही संख्या और प्रकार के बीज लें।","kn":"ಪ್ರತಿ ಜಾಡಿಯಲ್ಲೂ ಅದೇ ಸಂಖ್ಯೆ ಮತ್ತು ಬಗೆಯ ಬೀಜಗಳನ್ನು ಬಳಸಿ."},{"en":"Keep the cotton in jars B and D moist, not flooded.","hi":"जार B और D की रुई नम रखें, पानी से भरी नहीं।","kn":"B ಮತ್ತು D ಜಾಡಿಗಳ ಹತ್ತಿ ತೇವವಾಗಿರಲಿ, ನೀರಿನಲ್ಲಿ ಮುಳುಗಿರಬಾರದು."},{"en":"Do not disturb the oil layer on jar C.","hi":"जार C की तेल की परत को न हिलाएँ।","kn":"ಜಾಡಿ C ಯ ಎಣ್ಣೆಯ ಪದರವನ್ನು ಕದಡಬೇಡಿ."}],"conclusion":{"en":"Only the seeds in jar B, with water, air and warmth, germinated: the root grew down and the shoot grew up. Seeds with no water (A), no air (C) or no warmth (D) did not germinate, although seeds C and D swelled with water. Seeds need water, air and a suitable temperature together to germinate.","hi":"केवल जार B के बीज, जिन्हें पानी, हवा और गरमाहट मिली, अंकुरित हुए: जड़ नीचे और तना ऊपर बढ़ा। बिना पानी (A), बिना हवा (C) या बिना गरमाहट (D) वाले बीज अंकुरित नहीं हुए, यद्यपि C और D के बीज पानी से फूल गए। बीजों को अंकुरण के लिए पानी, हवा और उचित तापमान तीनों एक साथ चाहिए।","kn":"ನೀರು, ಗಾಳಿ ಮತ್ತು ಬೆಚ್ಚನೆ ಇದ್ದ ಜಾಡಿ B ಯ ಬೀಜಗಳು ಮಾತ್ರ ಮೊಳಕೆಯೊಡೆದವು: ಬೇರು ಕೆಳಕ್ಕೆ, ಕಾಂಡ ಮೇಲಕ್ಕೆ ಬೆಳೆಯಿತು. ನೀರಿಲ್ಲದ (A), ಗಾಳಿಯಿಲ್ಲದ (C) ಅಥವಾ ಬೆಚ್ಚನೆಯಿಲ್ಲದ (D) ಬೀಜಗಳು ಮೊಳಕೆಯೊಡೆಯಲಿಲ್ಲ; C ಮತ್ತು D ಬೀಜಗಳು ನೀರಿನಿಂದ ಉಬ್ಬಿದರೂ ಸಹ. ಮೊಳಕೆಯೊಡೆಯಲು ಬೀಜಗಳಿಗೆ ನೀರು, ಗಾಳಿ ಮತ್ತು ಸೂಕ್ತ ತಾಪಮಾನ ಮೂರೂ ಒಟ್ಟಿಗೆ ಬೇಕು."},"viva":[{"q":{"en":"Which comes out of a germinating seed first, the root or the shoot?","hi":"अंकुरित होते बीज से पहले क्या निकलता है, जड़ या तना?","kn":"ಮೊಳಕೆಯೊಡೆಯುವ ಬೀಜದಿಂದ ಮೊದಲು ಏನು ಹೊರಬರುತ್ತದೆ, ಬೇರೋ ಕಾಂಡವೋ?"},"a":{"en":"The root (radicle).","hi":"जड़ (मूलांकुर)।","kn":"ಬೇರು (ಮೂಲಾಂಕುರ)."}},{"q":{"en":"Why is the water in jar C boiled and covered with oil?","hi":"जार C का पानी क्यों उबाला और तेल से ढका जाता है?","kn":"ಜಾಡಿ C ಯ ನೀರನ್ನು ಏಕೆ ಕುದಿಸಿ ಎಣ್ಣೆಯಿಂದ ಮುಚ್ಚಲಾಗುತ್ತದೆ?"},"a":{"en":"Boiling removes the dissolved air and the oil stops air getting back in.","hi":"उबालने से घुली हवा निकल जाती है और तेल हवा को वापस आने से रोकता है।","kn":"ಕುದಿಸುವುದು ಕರಗಿದ ಗಾಳಿಯನ್ನು ತೆಗೆಯುತ್ತದೆ; ಎಣ್ಣೆ ಗಾಳಿ ಮತ್ತೆ ಸೇರದಂತೆ ತಡೆಯುತ್ತದೆ."}},{"q":{"en":"Which jar is the control, and why is it needed?","hi":"कौन-सा जार नियंत्रण है, और उसकी आवश्यकता क्यों है?","kn":"ಯಾವ ಜಾಡಿ ನಿಯಂತ್ರಣ, ಅದು ಏಕೆ ಬೇಕು?"},"a":{"en":"Jar B, which has everything. It shows the seeds are able to germinate, so the others fail only because of what they lack.","hi":"जार B, जिसमें सब कुछ है। यह दिखाता है कि बीज अंकुरित हो सकते हैं, इसलिए बाकी केवल उस कमी के कारण असफल होते हैं।","kn":"ಎಲ್ಲವೂ ಇರುವ ಜಾಡಿ B. ಬೀಜಗಳು ಮೊಳಕೆಯೊಡೆಯಬಲ್ಲವು ಎಂದು ಅದು ತೋರಿಸುತ್ತದೆ; ಉಳಿದವು ಅವುಗಳ ಕೊರತೆಯಿಂದಲೇ ವಿಫಲವಾಗುತ್ತವೆ."}},{"q":{"en":"Why do seeds need oxygen to germinate?","hi":"बीजों को अंकुरण के लिए ऑक्सीजन क्यों चाहिए?","kn":"ಬೀಜಗಳಿಗೆ ಮೊಳಕೆಯೊಡೆಯಲು ಆಮ್ಲಜನಕ ಏಕೆ ಬೇಕು?"},"a":{"en":"To respire: they break down stored food to get the energy for growth.","hi":"श्वसन के लिए: वे संचित भोजन को तोड़कर वृद्धि के लिए ऊर्जा पाते हैं।","kn":"ಉಸಿರಾಟಕ್ಕೆ: ಸಂಗ್ರಹಿತ ಆಹಾರವನ್ನು ವಿಭಜಿಸಿ ಬೆಳವಣಿಗೆಗೆ ಶಕ್ತಿ ಪಡೆಯುತ್ತವೆ."}},{"q":{"en":"Why do farmers not sow seeds in waterlogged soil?","hi":"किसान जलभराव वाली मिट्टी में बीज क्यों नहीं बोते?","kn":"ರೈತರು ನೀರು ನಿಂತ ಮಣ್ಣಿನಲ್ಲಿ ಬೀಜ ಏಕೆ ಬಿತ್ತುವುದಿಲ್ಲ?"},"a":{"en":"The water fills the air spaces in the soil, so the seeds get no air.","hi":"पानी मिट्टी के वायु-स्थानों को भर देता है, इसलिए बीजों को हवा नहीं मिलती।","kn":"ನೀರು ಮಣ್ಣಿನ ಗಾಳಿಯ ಅವಕಾಶಗಳನ್ನು ತುಂಬುತ್ತದೆ; ಬೀಜಗಳಿಗೆ ಗಾಳಿ ಸಿಗದು."}}]},{"id":"osmosis","bench":"osmosis","setup":{},"subject":"Biology","domain":"biology","levels":["9","10","11"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["osmosis","endosmosis","exosmosis","semi permeable membrane","selectively permeable","plasmolysis","diffusion","fundamental unit of life","absorption by roots"],"title":{"en":"Osmosis with raisins","hi":"किशमिश से परासरण","kn":"ಒಣದ್ರಾಕ್ಷಿಯಿಂದ ಅಭಿಸರಣೆ"},"summary":{"en":"Leave raisins in plain water and in strong sugar or salt solution, weigh them hour by hour, and see water move in and out.","hi":"किशमिश को सादे पानी और गाढ़े चीनी या नमक के घोल में रखें, हर घंटे तौलें, और पानी को अंदर-बाहर जाते देखें।","kn":"ಒಣದ್ರಾಕ್ಷಿಗಳನ್ನು ಸಾದಾ ನೀರು ಮತ್ತು ಸಾಂದ್ರ ಸಕ್ಕರೆ ಅಥವಾ ಉಪ್ಪಿನ ದ್ರಾವಣದಲ್ಲಿಟ್ಟು, ಗಂಟೆಗೊಮ್ಮೆ ತೂಗಿ, ನೀರು ಒಳ-ಹೊರಗೆ ಚಲಿಸುವುದನ್ನು ನೋಡಿ."},"aim":{"en":"To show endosmosis and exosmosis using raisins, and to find which way water moves across a membrane.","hi":"किशमिश की सहायता से अंतःपरासरण और बहिःपरासरण दिखाना, और पता करना कि झिल्ली के पार पानी किस दिशा में जाता है।","kn":"ಒಣದ್ರಾಕ್ಷಿಗಳ ಸಹಾಯದಿಂದ ಅಂತರಭಿಸರಣೆ ಮತ್ತು ಬಹಿರಭಿಸರಣೆ ತೋರಿಸಿ, ಪೊರೆಯ ಮೂಲಕ ನೀರು ಯಾವ ದಿಕ್ಕಿನಲ್ಲಿ ಚಲಿಸುತ್ತದೆ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Osmosis is the movement of water through a selectively permeable membrane from a dilute solution (more water) to a concentrated solution (less water). The skin and cells of a raisin act as such a membrane. A dry raisin is full of sugar, so in plain water, water moves in and the raisin swells (endosmosis). A swollen raisin placed in a strong sugar or salt solution loses water and shrinks (exosmosis). When inside and outside are about equally concentrated, there is little net movement.","hi":"परासरण वह प्रक्रिया है जिसमें पानी वरणात्मक पारगम्य झिल्ली से होकर तनु घोल (अधिक पानी) से सांद्र घोल (कम पानी) की ओर जाता है। किशमिश की त्वचा और कोशिकाएँ ऐसी झिल्ली का काम करती हैं। सूखी किशमिश चीनी से भरी होती है, इसलिए सादे पानी में पानी अंदर जाता है और किशमिश फूलती है (अंतःपरासरण)। फूली किशमिश को गाढ़े चीनी या नमक के घोल में रखने पर वह पानी खोकर सिकुड़ती है (बहिःपरासरण)। जब अंदर और बाहर की सांद्रता लगभग बराबर हो, तो पानी बहुत कम आता-जाता है।","kn":"ಅಭಿಸರಣೆ ಎಂದರೆ ಆಯ್ದ ಪ್ರವೇಶ್ಯ ಪೊರೆಯ ಮೂಲಕ ನೀರು ದುರ್ಬಲ ದ್ರಾವಣದಿಂದ (ಹೆಚ್ಚು ನೀರು) ಸಾಂದ್ರ ದ್ರಾವಣದ ಕಡೆಗೆ (ಕಡಿಮೆ ನೀರು) ಚಲಿಸುವುದು. ಒಣದ್ರಾಕ್ಷಿಯ ಸಿಪ್ಪೆ ಮತ್ತು ಕೋಶಗಳು ಅಂತಹ ಪೊರೆಯಂತೆ ವರ್ತಿಸುತ್ತವೆ. ಒಣ ದ್ರಾಕ್ಷಿಯಲ್ಲಿ ಸಕ್ಕರೆ ತುಂಬಿರುವುದರಿಂದ ಸಾದಾ ನೀರಿನಲ್ಲಿ ನೀರು ಒಳಸೇರಿ ಅದು ಉಬ್ಬುತ್ತದೆ (ಅಂತರಭಿಸರಣೆ). ಉಬ್ಬಿದ ದ್ರಾಕ್ಷಿಯನ್ನು ಸಾಂದ್ರ ಸಕ್ಕರೆ ಅಥವಾ ಉಪ್ಪಿನ ದ್ರಾವಣದಲ್ಲಿಟ್ಟರೆ ನೀರು ಕಳೆದುಕೊಂಡು ಕುಗ್ಗುತ್ತದೆ (ಬಹಿರಭಿಸರಣೆ). ಒಳಗೂ ಹೊರಗೂ ಸಾಂದ್ರತೆ ಸುಮಾರು ಸಮವಿದ್ದಾಗ ನೀರಿನ ಚಲನೆ ಬಹಳ ಕಡಿಮೆ."},"apparatus":[{"en":"20 raisins of about the same size","hi":"लगभग एक आकार की 20 किशमिश","kn":"ಸುಮಾರು ಒಂದೇ ಗಾತ್ರದ 20 ಒಣದ್ರಾಕ್ಷಿಗಳು"},{"en":"Three beakers: plain water, strong sugar solution, strong salt solution","hi":"तीन बीकर: सादा पानी, गाढ़ा चीनी घोल, गाढ़ा नमक घोल","kn":"ಮೂರು ಬೀಕರ್: ಸಾದಾ ನೀರು, ಸಾಂದ್ರ ಸಕ್ಕರೆ ದ್ರಾವಣ, ಸಾಂದ್ರ ಉಪ್ಪಿನ ದ್ರಾವಣ"},{"en":"A balance that reads to 0.1 g","hi":"0.1 g तक पढ़ने वाली तुला","kn":"0.1 g ವರೆಗೆ ಓದುವ ತಕ್ಕಡಿ"},{"en":"Blotting paper and a clock","hi":"सोख्ता कागज़ और घड़ी","kn":"ಒತ್ತುಕಾಗದ ಮತ್ತು ಗಡಿಯಾರ"}],"steps":[{"en":"Weigh 10 dry raisins together and record the mass.","hi":"10 सूखी किशमिश एक साथ तौलें और द्रव्यमान लिखें।","kn":"10 ಒಣದ್ರಾಕ್ಷಿಗಳನ್ನು ಒಟ್ಟಿಗೆ ತೂಗಿ ದ್ರವ್ಯರಾಶಿ ದಾಖಲಿಸಿ."},{"en":"Put them in plain water. Every hour, take them out, blot them dry, weigh them and put them back.","hi":"उन्हें सादे पानी में डालें। हर घंटे निकालें, सोख्ते से सुखाएँ, तौलें और वापस डालें।","kn":"ಅವುಗಳನ್ನು ಸಾದಾ ನೀರಿನಲ್ಲಿ ಹಾಕಿ. ಗಂಟೆಗೊಮ್ಮೆ ಹೊರತೆಗೆದು, ಒತ್ತುಕಾಗದದಿಂದ ಒಣಗಿಸಿ, ತೂಗಿ, ಮತ್ತೆ ಹಾಕಿ."},{"en":"Do the same with 10 dry raisins in strong sugar solution or strong salt solution.","hi":"यही काम 10 सूखी किशमिश को गाढ़े चीनी या नमक के घोल में रखकर करें।","kn":"ಇದೇ ರೀತಿ 10 ಒಣದ್ರಾಕ್ಷಿಗಳನ್ನು ಸಾಂದ್ರ ಸಕ್ಕರೆ ಅಥವಾ ಉಪ್ಪಿನ ದ್ರಾವಣದಲ್ಲಿಟ್ಟು ಮಾಡಿ."},{"en":"Take raisins that have swollen in water overnight, weigh them, and put them in the strong sugar or salt solution.","hi":"रात भर पानी में फूली किशमिश लें, तौलें और गाढ़े चीनी या नमक के घोल में डालें।","kn":"ರಾತ್ರಿಯಿಡೀ ನೀರಿನಲ್ಲಿ ಉಬ್ಬಿದ ದ್ರಾಕ್ಷಿಗಳನ್ನು ತೂಗಿ, ಸಾಂದ್ರ ಸಕ್ಕರೆ ಅಥವಾ ಉಪ್ಪಿನ ದ್ರಾವಣದಲ್ಲಿ ಹಾಕಿ."},{"en":"Weigh these every hour in the same way.","hi":"इन्हें भी उसी तरह हर घंटे तौलें।","kn":"ಇವನ್ನೂ ಅದೇ ರೀತಿ ಗಂಟೆಗೊಮ್ಮೆ ತೂಗಿ."},{"en":"Record the change in mass each time and say whether water went in or out.","hi":"हर बार द्रव्यमान में बदलाव लिखें और बताइए कि पानी अंदर गया या बाहर।","kn":"ಪ್ರತಿ ಬಾರಿ ದ್ರವ್ಯರಾಶಿಯ ಬದಲಾವಣೆ ದಾಖಲಿಸಿ, ನೀರು ಒಳಗೆ ಹೋಯಿತೋ ಹೊರಗೋ ಹೇಳಿ."}],"precautions":[{"en":"Blot the raisins gently but thoroughly before each weighing.","hi":"हर बार तौलने से पहले किशमिश को धीरे से पर अच्छी तरह सुखाएँ।","kn":"ಪ್ರತಿ ಬಾರಿ ತೂಗುವ ಮೊದಲು ದ್ರಾಕ್ಷಿಗಳನ್ನು ಮೃದುವಾಗಿ ಆದರೆ ಚೆನ್ನಾಗಿ ಒರೆಸಿ."},{"en":"Use the same raisins throughout and do not lose any.","hi":"पूरे प्रयोग में वही किशमिश लें और कोई न खोए।","kn":"ಪ್ರಯೋಗದುದ್ದಕ್ಕೂ ಅದೇ ದ್ರಾಕ್ಷಿಗಳನ್ನು ಬಳಸಿ, ಯಾವುದೂ ಕಳೆಯದಿರಲಿ."},{"en":"Make the sugar and salt solutions really strong (as much as dissolves).","hi":"चीनी और नमक के घोल सचमुच गाढ़े बनाएँ (जितना घुल सके)।","kn":"ಸಕ್ಕರೆ ಮತ್ತು ಉಪ್ಪಿನ ದ್ರಾವಣಗಳನ್ನು ನಿಜವಾಗಿ ಸಾಂದ್ರವಾಗಿಸಿ (ಕರಗುವಷ್ಟು)."}],"conclusion":{"en":"Dry raisins in plain water gained mass and swelled: water entered them by endosmosis. Swollen raisins in strong sugar or salt solution lost mass and shrank: water left them by exosmosis. Dry raisins changed little in the strong solutions. Water moves through a membrane from the more dilute solution to the more concentrated one.","hi":"सादे पानी में सूखी किशमिश का द्रव्यमान बढ़ा और वह फूली: अंतःपरासरण से पानी अंदर गया। गाढ़े चीनी या नमक के घोल में फूली किशमिश का द्रव्यमान घटा और वह सिकुड़ी: बहिःपरासरण से पानी बाहर निकला। गाढ़े घोलों में सूखी किशमिश में बहुत कम बदलाव हुआ। पानी झिल्ली से होकर तनु घोल से सांद्र घोल की ओर जाता है।","kn":"ಸಾದಾ ನೀರಿನಲ್ಲಿ ಒಣದ್ರಾಕ್ಷಿಗಳ ದ್ರವ್ಯರಾಶಿ ಹೆಚ್ಚಿ ಅವು ಉಬ್ಬಿದವು: ಅಂತರಭಿಸರಣೆಯಿಂದ ನೀರು ಒಳಸೇರಿತು. ಸಾಂದ್ರ ಸಕ್ಕರೆ ಅಥವಾ ಉಪ್ಪಿನ ದ್ರಾವಣದಲ್ಲಿ ಉಬ್ಬಿದ ದ್ರಾಕ್ಷಿಗಳ ದ್ರವ್ಯರಾಶಿ ಕಡಿಮೆಯಾಗಿ ಅವು ಕುಗ್ಗಿದವು: ಬಹಿರಭಿಸರಣೆಯಿಂದ ನೀರು ಹೊರಹೋಯಿತು. ಸಾಂದ್ರ ದ್ರಾವಣಗಳಲ್ಲಿ ಒಣದ್ರಾಕ್ಷಿಗಳು ಸ್ವಲ್ಪವೇ ಬದಲಾದವು. ನೀರು ಪೊರೆಯ ಮೂಲಕ ದುರ್ಬಲ ದ್ರಾವಣದಿಂದ ಸಾಂದ್ರ ದ್ರಾವಣದ ಕಡೆಗೆ ಚಲಿಸುತ್ತದೆ."},"viva":[{"q":{"en":"Define osmosis.","hi":"परासरण की परिभाषा दीजिए।","kn":"ಅಭಿಸರಣೆಯನ್ನು ವ್ಯಾಖ್ಯಾನಿಸಿ."},"a":{"en":"The movement of water through a selectively permeable membrane from a dilute to a concentrated solution.","hi":"वरणात्मक पारगम्य झिल्ली से होकर तनु से सांद्र घोल की ओर पानी का जाना।","kn":"ಆಯ್ದ ಪ್ರವೇಶ್ಯ ಪೊರೆಯ ಮೂಲಕ ದುರ್ಬಲದಿಂದ ಸಾಂದ್ರ ದ್ರಾವಣದ ಕಡೆಗೆ ನೀರಿನ ಚಲನೆ."}},{"q":{"en":"What is endosmosis?","hi":"अंतःपरासरण क्या है?","kn":"ಅಂತರಭಿಸರಣೆ ಎಂದರೇನು?"},"a":{"en":"Water entering a cell (or a raisin) placed in a more dilute solution.","hi":"अधिक तनु घोल में रखी कोशिका (या किशमिश) में पानी का प्रवेश।","kn":"ಹೆಚ್ಚು ದುರ್ಬಲ ದ್ರಾವಣದಲ್ಲಿಟ್ಟ ಕೋಶ (ಅಥವಾ ದ್ರಾಕ್ಷಿ) ಒಳಗೆ ನೀರು ಸೇರುವುದು."}},{"q":{"en":"Why do vegetables sprinkled with salt give out water?","hi":"नमक छिड़कने पर सब्ज़ियाँ पानी क्यों छोड़ती हैं?","kn":"ಉಪ್ಪು ಸಿಂಪಡಿಸಿದಾಗ ತರಕಾರಿಗಳು ನೀರು ಏಕೆ ಬಿಡುತ್ತವೆ?"},"a":{"en":"The salt makes a concentrated solution outside the cells, so water leaves them by exosmosis.","hi":"नमक कोशिकाओं के बाहर सांद्र घोल बनाता है, इसलिए बहिःपरासरण से पानी बाहर निकलता है।","kn":"ಉಪ್ಪು ಕೋಶಗಳ ಹೊರಗೆ ಸಾಂದ್ರ ದ್ರಾವಣ ಉಂಟುಮಾಡುತ್ತದೆ; ಬಹಿರಭಿಸರಣೆಯಿಂದ ನೀರು ಹೊರಬರುತ್ತದೆ."}},{"q":{"en":"How is osmosis different from diffusion?","hi":"परासरण विसरण से कैसे भिन्न है?","kn":"ಅಭಿಸರಣೆ ವಿಸರಣೆಗಿಂತ ಹೇಗೆ ಭಿನ್ನ?"},"a":{"en":"Osmosis is the movement of water only, and only through a selectively permeable membrane.","hi":"परासरण केवल पानी का, और केवल वरणात्मक पारगम्य झिल्ली से होकर होने वाला संचलन है।","kn":"ಅಭಿಸರಣೆ ನೀರಿನ ಮಾತ್ರ ಚಲನೆ, ಅದೂ ಆಯ್ದ ಪ್ರವೇಶ್ಯ ಪೊರೆಯ ಮೂಲಕ ಮಾತ್ರ."}},{"q":{"en":"How do plant roots take in water from the soil?","hi":"पौधों की जड़ें मिट्टी से पानी कैसे लेती हैं?","kn":"ಸಸ್ಯದ ಬೇರುಗಳು ಮಣ್ಣಿನಿಂದ ನೀರನ್ನು ಹೇಗೆ ಹೀರುತ್ತವೆ?"},"a":{"en":"By osmosis: the sap in the root hair cells is more concentrated than the soil water.","hi":"परासरण से: मूलरोम कोशिकाओं का रस मिट्टी के पानी से अधिक सांद्र होता है।","kn":"ಅಭಿಸರಣೆಯಿಂದ: ಮೂಲರೋಮ ಕೋಶಗಳ ರಸ ಮಣ್ಣಿನ ನೀರಿಗಿಂತ ಸಾಂದ್ರವಾಗಿರುತ್ತದೆ."}}]},{"id":"pinhole","bench":"pinhole","setup":{},"subject":"Physics","domain":"physics","levels":["6","7"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["pinhole camera","pinhole","rectilinear propagation","light travels in a straight line","light shadows and reflections","light"],"title":{"en":"The pinhole camera","hi":"पिनहोल कैमरा","kn":"ಸೂಜಿರಂಧ್ರ ಕ್ಯಾಮೆರಾ"},"summary":{"en":"Point a pinhole camera at a candle, move the candle and change the box length, and measure the upside-down image.","hi":"पिनहोल कैमरे को मोमबत्ती की ओर करें, मोमबत्ती खिसकाएँ और डिब्बे की लंबाई बदलें, और उल्टे प्रतिबिंब को मापें।","kn":"ಸೂಜಿರಂಧ್ರ ಕ್ಯಾಮೆರಾವನ್ನು ಮೇಣದಬತ್ತಿಯತ್ತ ತಿರುಗಿಸಿ, ಮೇಣದಬತ್ತಿ ಸರಿಸಿ, ಪೆಟ್ಟಿಗೆಯ ಉದ್ದ ಬದಲಿಸಿ, ತಲೆಕೆಳಗಾದ ಪ್ರತಿಬಿಂಬವನ್ನು ಅಳೆಯಿರಿ."},"aim":{"en":"To show that light travels in straight lines, and to find how the size of a pinhole image depends on the distance of the object and the length of the camera.","hi":"दिखाना कि प्रकाश सीधी रेखा में चलता है, और पता करना कि पिनहोल प्रतिबिंब का आकार वस्तु की दूरी और कैमरे की लंबाई पर कैसे निर्भर करता है।","kn":"ಬೆಳಕು ಸರಳರೇಖೆಯಲ್ಲಿ ಚಲಿಸುತ್ತದೆ ಎಂದು ತೋರಿಸಿ, ಸೂಜಿರಂಧ್ರ ಪ್ರತಿಬಿಂಬದ ಗಾತ್ರ ವಸ್ತುವಿನ ದೂರ ಮತ್ತು ಕ್ಯಾಮೆರಾದ ಉದ್ದವನ್ನು ಹೇಗೆ ಅವಲಂಬಿಸುತ್ತದೆ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Light from each point of the candle travels in a straight line through the small hole and lands on the screen at the back. Light from the top of the flame lands at the bottom and light from the foot lands at the top, so the image is upside down. By similar triangles, image height ÷ object height = v ÷ u, where u is the distance of the candle from the hole and v is the length of the box. A big hole lets many overlapping images through, so the picture is brighter but blurred; two holes give two images.","hi":"मोमबत्ती के हर बिंदु से प्रकाश सीधी रेखा में छोटे छेद से होकर पीछे के पर्दे पर पड़ता है। लौ के ऊपर का प्रकाश नीचे और आधार का प्रकाश ऊपर पड़ता है, इसलिए प्रतिबिंब उल्टा होता है। समरूप त्रिभुजों से, प्रतिबिंब की ऊँचाई ÷ वस्तु की ऊँचाई = v ÷ u, जहाँ u छेद से मोमबत्ती की दूरी और v डिब्बे की लंबाई है। बड़ा छेद कई एक-दूसरे पर चढ़े प्रतिबिंब बनाता है, इसलिए चित्र चमकीला पर धुँधला होता है; दो छेद दो प्रतिबिंब देते हैं।","kn":"ಮೇಣದಬತ್ತಿಯ ಪ್ರತಿ ಬಿಂದುವಿನಿಂದ ಬೆಳಕು ಸರಳರೇಖೆಯಲ್ಲಿ ಸಣ್ಣ ರಂಧ್ರದ ಮೂಲಕ ಹಿಂದಿನ ಪರದೆಯ ಮೇಲೆ ಬೀಳುತ್ತದೆ. ಜ್ವಾಲೆಯ ಮೇಲ್ಭಾಗದ ಬೆಳಕು ಕೆಳಗೆ, ಬುಡದ ಬೆಳಕು ಮೇಲೆ ಬೀಳುತ್ತದೆ; ಆದ್ದರಿಂದ ಪ್ರತಿಬಿಂಬ ತಲೆಕೆಳಗಾಗಿರುತ್ತದೆ. ಸಮರೂಪ ತ್ರಿಭುಜಗಳಿಂದ, ಪ್ರತಿಬಿಂಬದ ಎತ್ತರ ÷ ವಸ್ತುವಿನ ಎತ್ತರ = v ÷ u; ಇಲ್ಲಿ u ರಂಧ್ರದಿಂದ ಮೇಣದಬತ್ತಿಯ ದೂರ, v ಪೆಟ್ಟಿಗೆಯ ಉದ್ದ. ದೊಡ್ಡ ರಂಧ್ರ ಒಂದರ ಮೇಲೊಂದು ಬೀಳುವ ಹಲವು ಪ್ರತಿಬಿಂಬಗಳನ್ನು ಬಿಡುತ್ತದೆ; ಚಿತ್ರ ಪ್ರಕಾಶಮಾನ ಆದರೆ ಮಸುಕು. ಎರಡು ರಂಧ್ರಗಳು ಎರಡು ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತವೆ."},"apparatus":[{"en":"A long box (or two tubes that slide into each other), black inside","hi":"एक लंबा डिब्बा (या एक-दूसरे में खिसकने वाली दो नलियाँ), अंदर से काला","kn":"ಒಳಗೆ ಕಪ್ಪಾದ ಉದ್ದ ಪೆಟ್ಟಿಗೆ (ಅಥವಾ ಒಂದರೊಳಗೊಂದು ಜಾರುವ ಎರಡು ಕೊಳವೆಗಳು)"},{"en":"Tracing paper for the screen","hi":"पर्दे के लिए ट्रेसिंग पेपर","kn":"ಪರದೆಗಾಗಿ ಟ್ರೇಸಿಂಗ್ ಕಾಗದ"},{"en":"A pin to make the hole, black paper","hi":"छेद बनाने के लिए पिन, काला कागज़","kn":"ರಂಧ್ರ ಮಾಡಲು ಸೂಜಿ, ಕಪ್ಪು ಕಾಗದ"},{"en":"A candle, a metre scale, a darkened room","hi":"एक मोमबत्ती, मीटर पैमाना, अँधेरा कमरा","kn":"ಒಂದು ಮೇಣದಬತ್ತಿ, ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ, ಕತ್ತಲಾದ ಕೊಠಡಿ"}],"steps":[{"en":"Cover one end of the box with black paper and make a small hole in its centre with a pin. Cover the other end with tracing paper.","hi":"डिब्बे के एक सिरे को काले कागज़ से ढकें और उसके बीच में पिन से छोटा छेद करें। दूसरे सिरे को ट्रेसिंग पेपर से ढकें।","kn":"ಪೆಟ್ಟಿಗೆಯ ಒಂದು ತುದಿಯನ್ನು ಕಪ್ಪು ಕಾಗದದಿಂದ ಮುಚ್ಚಿ, ಅದರ ಮಧ್ಯದಲ್ಲಿ ಸೂಜಿಯಿಂದ ಸಣ್ಣ ರಂಧ್ರ ಮಾಡಿ. ಇನ್ನೊಂದು ತುದಿಯನ್ನು ಟ್ರೇಸಿಂಗ್ ಕಾಗದದಿಂದ ಮುಚ್ಚಿ."},{"en":"Light a candle in a dark room and point the pinhole at it.","hi":"अँधेरे कमरे में मोमबत्ती जलाएँ और पिनहोल को उसकी ओर करें।","kn":"ಕತ್ತಲಾದ ಕೊಠಡಿಯಲ್ಲಿ ಮೇಣದಬತ್ತಿ ಹಚ್ಚಿ, ಸೂಜಿರಂಧ್ರವನ್ನು ಅದರತ್ತ ತಿರುಗಿಸಿ."},{"en":"Look at the image on the tracing paper. Note which way up it is.","hi":"ट्रेसिंग पेपर पर प्रतिबिंब देखें। ध्यान दें कि वह किस ओर से सीधा है।","kn":"ಟ್ರೇಸಿಂಗ್ ಕಾಗದದ ಮೇಲಿನ ಪ್ರತಿಬಿಂಬ ನೋಡಿ. ಅದು ಯಾವ ಕಡೆ ಮೇಲಿದೆ ಗಮನಿಸಿ."},{"en":"Measure the candle height, its distance u from the hole, the box length v and the image height.","hi":"मोमबत्ती की ऊँचाई, छेद से उसकी दूरी u, डिब्बे की लंबाई v और प्रतिबिंब की ऊँचाई मापें।","kn":"ಮೇಣದಬತ್ತಿಯ ಎತ್ತರ, ರಂಧ್ರದಿಂದ ಅದರ ದೂರ u, ಪೆಟ್ಟಿಗೆಯ ಉದ್ದ v ಮತ್ತು ಪ್ರತಿಬಿಂಬದ ಎತ್ತರ ಅಳೆಯಿರಿ."},{"en":"Move the candle closer and farther, and change the box length. Record the readings each time.","hi":"मोमबत्ती को पास और दूर करें और डिब्बे की लंबाई बदलें। हर बार पाठ्यांक लिखें।","kn":"ಮೇಣದಬತ್ತಿಯನ್ನು ಹತ್ತಿರ ಮತ್ತು ದೂರ ಸರಿಸಿ, ಪೆಟ್ಟಿಗೆಯ ಉದ್ದ ಬದಲಿಸಿ. ಪ್ರತಿ ಬಾರಿ ಓದುಗಳನ್ನು ದಾಖಲಿಸಿ."},{"en":"Make the hole bigger, then make a second hole, and see what happens to the image.","hi":"छेद बड़ा करें, फिर दूसरा छेद बनाएँ, और देखें कि प्रतिबिंब को क्या होता है।","kn":"ರಂಧ್ರವನ್ನು ದೊಡ್ಡದು ಮಾಡಿ, ನಂತರ ಎರಡನೇ ರಂಧ್ರ ಮಾಡಿ, ಪ್ರತಿಬಿಂಬಕ್ಕೆ ಏನಾಗುತ್ತದೆ ನೋಡಿ."},{"en":"Compare image height ÷ candle height with v ÷ u.","hi":"प्रतिबिंब की ऊँचाई ÷ मोमबत्ती की ऊँचाई की तुलना v ÷ u से करें।","kn":"ಪ್ರತಿಬಿಂಬದ ಎತ್ತರ ÷ ಮೇಣದಬತ್ತಿಯ ಎತ್ತರವನ್ನು v ÷ u ಜೊತೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Keep the hole small and round for a sharp image.","hi":"स्पष्ट प्रतिबिंब के लिए छेद छोटा और गोल रखें।","kn":"ಸ್ಪಷ್ಟ ಪ್ರತಿಬಿಂಬಕ್ಕೆ ರಂಧ್ರ ಸಣ್ಣದಾಗಿ, ದುಂಡಾಗಿರಲಿ."},{"en":"Keep the room dark and the inside of the box black.","hi":"कमरा अँधेरा और डिब्बे का अंदर का भाग काला रखें।","kn":"ಕೊಠಡಿ ಕತ್ತಲಾಗಿರಲಿ, ಪೆಟ್ಟಿಗೆಯ ಒಳಭಾಗ ಕಪ್ಪಾಗಿರಲಿ."},{"en":"Keep the camera well away from the flame.","hi":"कैमरे को लौ से अच्छी दूरी पर रखें।","kn":"ಕ್ಯಾಮೆರಾವನ್ನು ಜ್ವಾಲೆಯಿಂದ ಸಾಕಷ್ಟು ದೂರವಿಡಿ."}],"conclusion":{"en":"The image in a pinhole camera is upside down, which shows that light travels in straight lines. Image height ÷ object height equals v ÷ u: the image is bigger when the candle is nearer or the box is longer. A bigger hole makes the image brighter but blurred, and two holes make two images.","hi":"पिनहोल कैमरे का प्रतिबिंब उल्टा होता है, जो दिखाता है कि प्रकाश सीधी रेखा में चलता है। प्रतिबिंब की ऊँचाई ÷ वस्तु की ऊँचाई = v ÷ u: मोमबत्ती पास हो या डिब्बा लंबा हो तो प्रतिबिंब बड़ा होता है। बड़ा छेद प्रतिबिंब को चमकीला पर धुँधला बनाता है, और दो छेद दो प्रतिबिंब बनाते हैं।","kn":"ಸೂಜಿರಂಧ್ರ ಕ್ಯಾಮೆರಾದ ಪ್ರತಿಬಿಂಬ ತಲೆಕೆಳಗಾಗಿರುತ್ತದೆ; ಬೆಳಕು ಸರಳರೇಖೆಯಲ್ಲಿ ಚಲಿಸುತ್ತದೆ ಎಂದು ಇದು ತೋರಿಸುತ್ತದೆ. ಪ್ರತಿಬಿಂಬದ ಎತ್ತರ ÷ ವಸ್ತುವಿನ ಎತ್ತರ = v ÷ u: ಮೇಣದಬತ್ತಿ ಹತ್ತಿರವಿದ್ದರೆ ಅಥವಾ ಪೆಟ್ಟಿಗೆ ಉದ್ದವಿದ್ದರೆ ಪ್ರತಿಬಿಂಬ ದೊಡ್ಡದು. ದೊಡ್ಡ ರಂಧ್ರ ಪ್ರತಿಬಿಂಬವನ್ನು ಪ್ರಕಾಶಮಾನ ಆದರೆ ಮಸುಕಾಗಿಸುತ್ತದೆ; ಎರಡು ರಂಧ್ರಗಳು ಎರಡು ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತವೆ."},"viva":[{"q":{"en":"Why is the image in a pinhole camera upside down?","hi":"पिनहोल कैमरे में प्रतिबिंब उल्टा क्यों होता है?","kn":"ಸೂಜಿರಂಧ್ರ ಕ್ಯಾಮೆರಾದಲ್ಲಿ ಪ್ರತಿಬಿಂಬ ಏಕೆ ತಲೆಕೆಳಗಾಗಿರುತ್ತದೆ?"},"a":{"en":"Rays from the top and bottom of the object cross at the hole, because light travels in straight lines.","hi":"वस्तु के ऊपर और नीचे की किरणें छेद पर एक-दूसरे को काटती हैं, क्योंकि प्रकाश सीधी रेखा में चलता है।","kn":"ವಸ್ತುವಿನ ಮೇಲಿನ ಮತ್ತು ಕೆಳಗಿನ ಕಿರಣಗಳು ರಂಧ್ರದಲ್ಲಿ ಅಡ್ಡಹಾಯುತ್ತವೆ, ಏಕೆಂದರೆ ಬೆಳಕು ಸರಳರೇಖೆಯಲ್ಲಿ ಚಲಿಸುತ್ತದೆ."}},{"q":{"en":"What happens to the image if the candle is moved closer?","hi":"मोमबत्ती पास लाने पर प्रतिबिंब को क्या होता है?","kn":"ಮೇಣದಬತ್ತಿಯನ್ನು ಹತ್ತಿರ ತಂದರೆ ಪ್ರತಿಬಿಂಬಕ್ಕೆ ಏನಾಗುತ್ತದೆ?"},"a":{"en":"It becomes bigger.","hi":"वह बड़ा हो जाता है।","kn":"ಅದು ದೊಡ್ಡದಾಗುತ್ತದೆ."}},{"q":{"en":"Why does a big hole give a blurred image?","hi":"बड़ा छेद धुँधला प्रतिबिंब क्यों देता है?","kn":"ದೊಡ್ಡ ರಂಧ್ರ ಮಸುಕಾದ ಪ್ರತಿಬಿಂಬ ಏಕೆ ನೀಡುತ್ತದೆ?"},"a":{"en":"Light from each point of the object passes through many parts of the hole and spreads into a patch, so the images overlap.","hi":"वस्तु के हर बिंदु का प्रकाश छेद के कई भागों से निकलकर एक धब्बा बनाता है, इसलिए प्रतिबिंब एक-दूसरे पर चढ़ जाते हैं।","kn":"ವಸ್ತುವಿನ ಪ್ರತಿ ಬಿಂದುವಿನ ಬೆಳಕು ರಂಧ್ರದ ಹಲವು ಭಾಗಗಳ ಮೂಲಕ ಹಾದು ಒಂದು ತೇಪೆಯಾಗುತ್ತದೆ; ಪ್ರತಿಬಿಂಬಗಳು ಒಂದರ ಮೇಲೊಂದು ಬೀಳುತ್ತವೆ."}},{"q":{"en":"A candle 12 cm tall is 40 cm from the pinhole of a 20 cm long box. How tall is the image?","hi":"12 cm ऊँची मोमबत्ती 20 cm लंबे डिब्बे के पिनहोल से 40 cm दूर है। प्रतिबिंब कितना ऊँचा है?","kn":"12 cm ಎತ್ತರದ ಮೇಣದಬತ್ತಿ 20 cm ಉದ್ದದ ಪೆಟ್ಟಿಗೆಯ ಸೂಜಿರಂಧ್ರದಿಂದ 40 cm ದೂರದಲ್ಲಿದೆ. ಪ್ರತಿಬಿಂಬ ಎಷ್ಟು ಎತ್ತರ?"},"a":{"en":"12 × 20 ÷ 40 = 6 cm, upside down.","hi":"12 × 20 ÷ 40 = 6 cm, उल्टा।","kn":"12 × 20 ÷ 40 = 6 cm, ತಲೆಕೆಳಗಾಗಿ."}},{"q":{"en":"What do the round patches of light under a tree on a sunny day show?","hi":"धूप वाले दिन पेड़ के नीचे प्रकाश के गोल धब्बे क्या दिखाते हैं?","kn":"ಬಿಸಿಲಿನ ದಿನ ಮರದ ಕೆಳಗೆ ಕಾಣುವ ದುಂಡು ಬೆಳಕಿನ ತೇಪೆಗಳು ಏನನ್ನು ತೋರಿಸುತ್ತವೆ?"},"a":{"en":"They are pinhole images of the Sun, made by small gaps between the leaves.","hi":"वे सूर्य के पिनहोल प्रतिबिंब हैं, जो पत्तियों के बीच के छोटे अंतरालों से बनते हैं।","kn":"ಅವು ಎಲೆಗಳ ನಡುವಿನ ಸಣ್ಣ ಸಂದುಗಳಿಂದ ಉಂಟಾದ ಸೂರ್ಯನ ಸೂಜಿರಂಧ್ರ ಪ್ರತಿಬಿಂಬಗಳು."}}]},{"id":"mirror-reflection","bench":"mirror","setup":{},"subject":"Physics","domain":"physics","levels":["7","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["reflection","reflection of light","laws of reflection","plane mirror","mirror","angle of incidence","angle of reflection","regular reflection","diffuse reflection","light"],"title":{"en":"Laws of reflection","hi":"परावर्तन के नियम","kn":"ಪ್ರತಿಫಲನದ ನಿಯಮಗಳು"},"summary":{"en":"Shine a narrow beam on a plane mirror at different angles and compare the angle of incidence with the angle of reflection.","hi":"समतल दर्पण पर अलग-अलग कोणों पर पतली किरण डालें और आपतन कोण की तुलना परावर्तन कोण से करें।","kn":"ಸಮತಲ ದರ್ಪಣದ ಮೇಲೆ ಬೇರೆ ಬೇರೆ ಕೋನಗಳಲ್ಲಿ ಕಿರಿದಾದ ಕಿರಣ ಹಾಯಿಸಿ, ಪತನ ಕೋನವನ್ನು ಪ್ರತಿಫಲನ ಕೋನದೊಂದಿಗೆ ಹೋಲಿಸಿ."},"aim":{"en":"To verify that the angle of reflection equals the angle of incidence for a plane mirror, and to compare reflection from a smooth and a rough surface.","hi":"समतल दर्पण के लिए परावर्तन कोण और आपतन कोण की समानता सत्यापित करना, और चिकनी तथा खुरदुरी सतह से परावर्तन की तुलना करना।","kn":"ಸಮತಲ ದರ್ಪಣಕ್ಕೆ ಪ್ರತಿಫಲನ ಕೋನ ಪತನ ಕೋನಕ್ಕೆ ಸಮ ಎಂದು ಪರಿಶೀಲಿಸಿ, ನಯವಾದ ಮತ್ತು ಒರಟಾದ ಮೇಲ್ಮೈಗಳ ಪ್ರತಿಫಲನವನ್ನು ಹೋಲಿಸುವುದು."},"principle":{"en":"The normal is the line at right angles to the mirror at the point where the ray strikes it. The angle of incidence (i) is between the incident ray and the normal; the angle of reflection (r) is between the reflected ray and the normal. The laws of reflection say that r = i, and that the incident ray, the normal and the reflected ray lie in the same plane. A smooth surface reflects a parallel beam as a parallel beam (regular reflection); a rough surface scatters it in many directions (diffuse reflection).","hi":"अभिलंब वह रेखा है जो किरण के दर्पण से टकराने के बिंदु पर दर्पण से समकोण बनाती है। आपतन कोण (i) आपतित किरण और अभिलंब के बीच होता है; परावर्तन कोण (r) परावर्तित किरण और अभिलंब के बीच। परावर्तन के नियम कहते हैं कि r = i, और आपतित किरण, अभिलंब तथा परावर्तित किरण एक ही तल में होते हैं। चिकनी सतह समांतर किरण-पुंज को समांतर ही लौटाती है (नियमित परावर्तन); खुरदुरी सतह उसे कई दिशाओं में बिखेर देती है (विसरित परावर्तन)।","kn":"ಕಿರಣ ದರ್ಪಣಕ್ಕೆ ತಾಗುವ ಬಿಂದುವಿನಲ್ಲಿ ದರ್ಪಣಕ್ಕೆ ಲಂಬವಾಗಿರುವ ರೇಖೆಯೇ ಲಂಬ. ಪತನ ಕೋನ (i) ಪತನ ಕಿರಣ ಮತ್ತು ಲಂಬದ ನಡುವೆ; ಪ್ರತಿಫಲನ ಕೋನ (r) ಪ್ರತಿಫಲಿತ ಕಿರಣ ಮತ್ತು ಲಂಬದ ನಡುವೆ. ಪ್ರತಿಫಲನದ ನಿಯಮಗಳ ಪ್ರಕಾರ r = i, ಮತ್ತು ಪತನ ಕಿರಣ, ಲಂಬ ಹಾಗೂ ಪ್ರತಿಫಲಿತ ಕಿರಣ ಒಂದೇ ಸಮತಲದಲ್ಲಿರುತ್ತವೆ. ನಯವಾದ ಮೇಲ್ಮೈ ಸಮಾಂತರ ಕಿರಣಪುಂಜವನ್ನು ಸಮಾಂತರವಾಗಿಯೇ ಪ್ರತಿಫಲಿಸುತ್ತದೆ (ನಿಯಮಿತ ಪ್ರತಿಫಲನ); ಒರಟು ಮೇಲ್ಮೈ ಅದನ್ನು ಹಲವು ದಿಕ್ಕುಗಳಿಗೆ ಚದುರಿಸುತ್ತದೆ (ವಿಸರಿತ ಪ್ರತಿಫಲನ)."},"apparatus":[{"en":"A plane mirror strip with a stand","hi":"स्टैंड सहित समतल दर्पण की पट्टी","kn":"ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಸಮತಲ ದರ್ಪಣದ ಪಟ್ಟಿ"},{"en":"A ray box or torch with a slit (or pins)","hi":"झिरी वाला रे-बॉक्स या टॉर्च (या पिनें)","kn":"ಸೀಳು ಇರುವ ರೇ-ಬಾಕ್ಸ್ ಅಥವಾ ಟಾರ್ಚ್ (ಅಥವಾ ಪಿನ್‌ಗಳು)"},{"en":"White paper, protractor, pencil and ruler","hi":"सफ़ेद कागज़, चाँदा, पेंसिल और पैमाना","kn":"ಬಿಳಿ ಕಾಗದ, ಕೋನಮಾಪಕ, ಪೆನ್ಸಿಲ್ ಮತ್ತು ಅಳತೆಪಟ್ಟಿ"}],"steps":[{"en":"Draw a line on the paper and stand the mirror along it. Mark a point O on the line.","hi":"कागज़ पर एक रेखा खींचें और दर्पण को उसके साथ खड़ा करें। रेखा पर एक बिंदु O अंकित करें।","kn":"ಕಾಗದದ ಮೇಲೆ ಒಂದು ರೇಖೆ ಎಳೆದು ದರ್ಪಣವನ್ನು ಅದರ ಉದ್ದಕ್ಕೆ ನಿಲ್ಲಿಸಿ. ರೇಖೆಯ ಮೇಲೆ O ಬಿಂದು ಗುರುತಿಸಿ."},{"en":"Draw the normal at O, at right angles to the mirror line.","hi":"O पर दर्पण की रेखा से समकोण पर अभिलंब खींचें।","kn":"O ನಲ್ಲಿ ದರ್ಪಣ ರೇಖೆಗೆ ಲಂಬವಾಗಿ ಲಂಬರೇಖೆ ಎಳೆಯಿರಿ."},{"en":"Draw lines from O at 20°, 30°, 40°… to the normal. Shine the beam along one of them so it strikes the mirror at O.","hi":"O से अभिलंब के साथ 20°, 30°, 40°… पर रेखाएँ खींचें। किरण को इनमें से एक के साथ डालें ताकि वह O पर दर्पण से टकराए।","kn":"O ಯಿಂದ ಲಂಬಕ್ಕೆ 20°, 30°, 40°… ಕೋನಗಳಲ್ಲಿ ರೇಖೆಗಳನ್ನು ಎಳೆಯಿರಿ. ಅವುಗಳಲ್ಲಿ ಒಂದರ ಉದ್ದಕ್ಕೆ ಕಿರಣ ಹಾಯಿಸಿ, ಅದು O ನಲ್ಲಿ ದರ್ಪಣಕ್ಕೆ ತಾಗಲಿ."},{"en":"Mark two points on the reflected beam and join them to O.","hi":"परावर्तित किरण पर दो बिंदु अंकित करें और उन्हें O से मिलाएँ।","kn":"ಪ್ರತಿಫಲಿತ ಕಿರಣದ ಮೇಲೆ ಎರಡು ಬಿಂದು ಗುರುತಿಸಿ O ಗೆ ಜೋಡಿಸಿ."},{"en":"Measure the angle of reflection with the protractor and record i and r.","hi":"चाँदे से परावर्तन कोण मापें और i तथा r लिखें।","kn":"ಕೋನಮಾಪಕದಿಂದ ಪ್ರತಿಫಲನ ಕೋನ ಅಳೆದು i ಮತ್ತು r ದಾಖಲಿಸಿ."},{"en":"Repeat for the other angles.","hi":"बाकी कोणों के लिए दोहराएँ।","kn":"ಉಳಿದ ಕೋನಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Replace the mirror with a sheet of rough paper or foil that has been crumpled and flattened, and see what happens to the beam.","hi":"दर्पण की जगह खुरदुरा कागज़ या मसलकर सीधी की गई पन्नी रखें और देखें कि किरण को क्या होता है।","kn":"ದರ್ಪಣದ ಬದಲು ಒರಟು ಕಾಗದ ಅಥವಾ ಮುದುಡಿ ಬಿಡಿಸಿದ ಹಾಳೆ ಇಟ್ಟು ಕಿರಣಕ್ಕೆ ಏನಾಗುತ್ತದೆ ನೋಡಿ."}],"precautions":[{"en":"Keep the mirror exactly upright along the line.","hi":"दर्पण को रेखा के साथ बिल्कुल सीधा खड़ा रखें।","kn":"ದರ್ಪಣವನ್ನು ರೇಖೆಯ ಉದ್ದಕ್ಕೆ ಸರಿಯಾಗಿ ನೇರವಾಗಿ ನಿಲ್ಲಿಸಿ."},{"en":"Measure angles from the normal, not from the mirror.","hi":"कोण अभिलंब से मापें, दर्पण से नहीं।","kn":"ಕೋನಗಳನ್ನು ಲಂಬದಿಂದ ಅಳೆಯಿರಿ, ದರ್ಪಣದಿಂದಲ್ಲ."},{"en":"Use a narrow beam so that its edges are sharp.","hi":"पतली किरण लें ताकि उसके किनारे स्पष्ट हों।","kn":"ಅಂಚುಗಳು ಸ್ಪಷ್ಟವಾಗಿರಲು ಕಿರಿದಾದ ಕಿರಣ ಬಳಸಿ."}],"conclusion":{"en":"For every angle of incidence the angle of reflection was the same, so r = i, and the incident ray, normal and reflected ray all lay on the paper. A smooth mirror gives regular reflection; a rough surface scatters the light in all directions, which is diffuse reflection.","hi":"हर आपतन कोण के लिए परावर्तन कोण उतना ही था, अतः r = i, और आपतित किरण, अभिलंब तथा परावर्तित किरण सभी कागज़ के तल में थे। चिकना दर्पण नियमित परावर्तन देता है; खुरदुरी सतह प्रकाश को सब दिशाओं में बिखेरती है, यह विसरित परावर्तन है।","kn":"ಪ್ರತಿ ಪತನ ಕೋನಕ್ಕೂ ಪ್ರತಿಫಲನ ಕೋನ ಅಷ್ಟೇ ಇತ್ತು; ಆದ್ದರಿಂದ r = i. ಪತನ ಕಿರಣ, ಲಂಬ ಮತ್ತು ಪ್ರತಿಫಲಿತ ಕಿರಣ ಎಲ್ಲವೂ ಕಾಗದದ ಸಮತಲದಲ್ಲಿದ್ದವು. ನಯವಾದ ದರ್ಪಣ ನಿಯಮಿತ ಪ್ರತಿಫಲನ ನೀಡುತ್ತದೆ; ಒರಟು ಮೇಲ್ಮೈ ಬೆಳಕನ್ನು ಎಲ್ಲಾ ದಿಕ್ಕುಗಳಿಗೆ ಚದುರಿಸುತ್ತದೆ, ಇದು ವಿಸರಿತ ಪ್ರತಿಫಲನ."},"viva":[{"q":{"en":"State the laws of reflection.","hi":"परावर्तन के नियम बताइए।","kn":"ಪ್ರತಿಫಲನದ ನಿಯಮಗಳನ್ನು ತಿಳಿಸಿ."},"a":{"en":"The angle of reflection equals the angle of incidence, and the incident ray, the normal and the reflected ray lie in one plane.","hi":"परावर्तन कोण आपतन कोण के बराबर होता है, और आपतित किरण, अभिलंब तथा परावर्तित किरण एक ही तल में होते हैं।","kn":"ಪ್ರತಿಫಲನ ಕೋನ ಪತನ ಕೋನಕ್ಕೆ ಸಮ; ಪತನ ಕಿರಣ, ಲಂಬ ಮತ್ತು ಪ್ರತಿಫಲಿತ ಕಿರಣ ಒಂದೇ ಸಮತಲದಲ್ಲಿರುತ್ತವೆ."}},{"q":{"en":"A ray strikes a mirror along the normal. What is the angle of reflection?","hi":"एक किरण अभिलंब के साथ दर्पण पर पड़ती है। परावर्तन कोण क्या है?","kn":"ಒಂದು ಕಿರಣ ಲಂಬದ ಉದ್ದಕ್ಕೆ ದರ್ಪಣಕ್ಕೆ ತಾಗುತ್ತದೆ. ಪ್ರತಿಫಲನ ಕೋನ ಎಷ್ಟು?"},"a":{"en":"0°: it goes straight back along the same line.","hi":"0°: वह उसी रेखा पर सीधी लौट जाती है।","kn":"0°: ಅದು ಅದೇ ರೇಖೆಯಲ್ಲಿ ನೇರವಾಗಿ ಹಿಂದಿರುಗುತ್ತದೆ."}},{"q":{"en":"The angle between the incident ray and the mirror is 30°. What is the angle of reflection?","hi":"आपतित किरण और दर्पण के बीच का कोण 30° है। परावर्तन कोण क्या है?","kn":"ಪತನ ಕಿರಣ ಮತ್ತು ದರ್ಪಣದ ನಡುವಿನ ಕೋನ 30°. ಪ್ರತಿಫಲನ ಕೋನ ಎಷ್ಟು?"},"a":{"en":"60°, because angles are measured from the normal: 90° − 30°.","hi":"60°, क्योंकि कोण अभिलंब से मापे जाते हैं: 90° − 30°।","kn":"60°, ಏಕೆಂದರೆ ಕೋನಗಳನ್ನು ಲಂಬದಿಂದ ಅಳೆಯಲಾಗುತ್ತದೆ: 90° − 30°."}},{"q":{"en":"Does diffuse reflection break the laws of reflection?","hi":"क्या विसरित परावर्तन परावर्तन के नियमों को तोड़ता है?","kn":"ವಿಸರಿತ ಪ್ರತಿಫಲನ ಪ್ರತಿಫಲನದ ನಿಯಮಗಳನ್ನು ಮುರಿಯುತ್ತದೆಯೇ?"},"a":{"en":"No. Each tiny part of the rough surface obeys r = i, but the parts face different ways.","hi":"नहीं। खुरदुरी सतह का हर छोटा भाग r = i मानता है, पर भाग अलग-अलग दिशाओं में होते हैं।","kn":"ಇಲ್ಲ. ಒರಟು ಮೇಲ್ಮೈಯ ಪ್ರತಿ ಸಣ್ಣ ಭಾಗ r = i ಪಾಲಿಸುತ್ತದೆ, ಆದರೆ ಭಾಗಗಳು ಬೇರೆ ಬೇರೆ ದಿಕ್ಕಿಗೆ ಮುಖ ಮಾಡಿರುತ್ತವೆ."}},{"q":{"en":"Why can we see a book from anywhere in the room?","hi":"हम कमरे में कहीं से भी किताब क्यों देख पाते हैं?","kn":"ಕೊಠಡಿಯಲ್ಲಿ ಎಲ್ಲಿಂದಲೂ ಪುಸ್ತಕವನ್ನು ನಾವು ಏಕೆ ನೋಡಬಲ್ಲೆವು?"},"a":{"en":"Its rough surface reflects light diffusely, in all directions.","hi":"उसकी खुरदुरी सतह प्रकाश को सब दिशाओं में विसरित रूप से परावर्तित करती है।","kn":"ಅದರ ಒರಟು ಮೇಲ್ಮೈ ಬೆಳಕನ್ನು ಎಲ್ಲಾ ದಿಕ್ಕುಗಳಿಗೆ ವಿಸರಿತವಾಗಿ ಪ್ರತಿಫಲಿಸುತ್ತದೆ."}}]},{"id":"pythagoras","bench":"pythagoras","setup":{},"subject":"Mathematics","domain":"maths","levels":["7","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["pythagoras","pythagoras theorem","pythagoras property","pythagorean triplets","pythagorean triplet","right angled triangle","right angled triangles","hypotenuse","triangles","squares and square roots"],"title":{"en":"Pythagoras' theorem","hi":"पाइथागोरस प्रमेय","kn":"ಪೈಥಾಗೊರಸ್ ಪ್ರಮೇಯ"},"summary":{"en":"Build squares on the sides of a triangle, count their unit squares, and see when a² + b² = c².","hi":"त्रिभुज की भुजाओं पर वर्ग बनाएँ, उनके इकाई वर्ग गिनें, और देखें कि a² + b² = c² कब होता है।","kn":"ತ್ರಿಭುಜದ ಬಾಹುಗಳ ಮೇಲೆ ಚೌಕಗಳನ್ನು ರಚಿಸಿ, ಅವುಗಳ ಏಕಮಾನ ಚೌಕಗಳನ್ನು ಎಣಿಸಿ, a² + b² = c² ಯಾವಾಗ ಎಂದು ನೋಡಿ."},"aim":{"en":"To verify that in a right-angled triangle the square on the hypotenuse equals the sum of the squares on the other two sides, and to see what happens when the angle is not a right angle.","hi":"सत्यापित करना कि समकोण त्रिभुज में कर्ण पर बना वर्ग बाकी दो भुजाओं पर बने वर्गों के योग के बराबर होता है, और देखना कि कोण समकोण न हो तो क्या होता है।","kn":"ಲಂಬಕೋನ ತ್ರಿಭುಜದಲ್ಲಿ ವಿಕರ್ಣದ ಮೇಲಿನ ಚೌಕ ಉಳಿದ ಎರಡು ಬಾಹುಗಳ ಮೇಲಿನ ಚೌಕಗಳ ಮೊತ್ತಕ್ಕೆ ಸಮ ಎಂದು ಪರಿಶೀಲಿಸಿ, ಕೋನ ಲಂಬಕೋನವಲ್ಲದಿದ್ದಾಗ ಏನಾಗುತ್ತದೆ ನೋಡುವುದು."},"principle":{"en":"In triangle ABC, let a and b be the sides that meet at C, and c the side opposite C. If angle C is 90°, then a² + b² = c² (Pythagoras). The area of a square on a side is the square of its length, so counting unit squares shows the relation. If angle C is less than 90°, c² is less than a² + b²; if it is more than 90°, c² is more. Whole numbers a, b, c with a² + b² = c², such as 3, 4, 5, are Pythagorean triplets.","hi":"त्रिभुज ABC में a और b वे भुजाएँ हैं जो C पर मिलती हैं, और c, C के सामने की भुजा है। यदि कोण C = 90° हो तो a² + b² = c² (पाइथागोरस)। किसी भुजा पर बने वर्ग का क्षेत्रफल उसकी लंबाई का वर्ग होता है, इसलिए इकाई वर्ग गिनकर यह संबंध दिखता है। यदि कोण C 90° से कम हो तो c², a² + b² से कम होता है; 90° से अधिक हो तो अधिक। a² + b² = c² वाली पूर्ण संख्याएँ a, b, c, जैसे 3, 4, 5, पाइथागोरस त्रिक कहलाती हैं।","kn":"ABC ತ್ರಿಭುಜದಲ್ಲಿ a ಮತ್ತು b ಗಳು C ಯಲ್ಲಿ ಸೇರುವ ಬಾಹುಗಳು, c ಯು C ಗೆ ಎದುರಿನ ಬಾಹು. C ಕೋನ 90° ಆದರೆ a² + b² = c² (ಪೈಥಾಗೊರಸ್). ಬಾಹುವಿನ ಮೇಲಿನ ಚೌಕದ ವಿಸ್ತೀರ್ಣ ಅದರ ಉದ್ದದ ವರ್ಗ; ಆದ್ದರಿಂದ ಏಕಮಾನ ಚೌಕಗಳನ್ನು ಎಣಿಸಿದರೆ ಈ ಸಂಬಂಧ ಕಾಣುತ್ತದೆ. C ಕೋನ 90° ಗಿಂತ ಕಡಿಮೆಯಿದ್ದರೆ c², a² + b² ಗಿಂತ ಕಡಿಮೆ; ಹೆಚ್ಚಿದ್ದರೆ ಹೆಚ್ಚು. a² + b² = c² ಆಗುವ ಪೂರ್ಣಸಂಖ್ಯೆಗಳು a, b, c, ಉದಾ: 3, 4, 5, ಪೈಥಾಗೊರಸ್ ತ್ರಿವಳಿಗಳು."},"apparatus":[{"en":"Squared (graph) paper","hi":"वर्गांकित (ग्राफ़) कागज़","kn":"ಚೌಕಾಕಾರದ (ಗ್ರಾಫ್) ಕಾಗದ"},{"en":"Ruler, set square and protractor","hi":"पैमाना, सेट स्क्वेयर और चाँदा","kn":"ಅಳತೆಪಟ್ಟಿ, ಸೆಟ್ ಸ್ಕ್ವೇರ್ ಮತ್ತು ಕೋನಮಾಪಕ"},{"en":"Scissors, glue and coloured pencils","hi":"कैंची, गोंद और रंगीन पेंसिलें","kn":"ಕತ್ತರಿ, ಅಂಟು ಮತ್ತು ಬಣ್ಣದ ಪೆನ್ಸಿಲ್‌ಗಳು"}],"steps":[{"en":"Draw a triangle with sides a = 3 units and b = 4 units meeting at a right angle at C.","hi":"C पर समकोण बनाती भुजाओं a = 3 इकाई और b = 4 इकाई वाला त्रिभुज बनाएँ।","kn":"C ಯಲ್ಲಿ ಲಂಬಕೋನದಲ್ಲಿ ಸೇರುವ a = 3 ಏಕಮಾನ ಮತ್ತು b = 4 ಏಕಮಾನ ಬಾಹುಗಳ ತ್ರಿಭುಜ ರಚಿಸಿ."},{"en":"Draw a square outwards on each side of the triangle.","hi":"त्रिभुज की हर भुजा पर बाहर की ओर एक वर्ग बनाएँ।","kn":"ತ್ರಿಭುಜದ ಪ್ರತಿ ಬಾಹುವಿನ ಮೇಲೆ ಹೊರಮುಖವಾಗಿ ಒಂದು ಚೌಕ ರಚಿಸಿ."},{"en":"Count the unit squares in each square: this is a², b² and c².","hi":"हर वर्ग के इकाई वर्ग गिनें: यही a², b² और c² है।","kn":"ಪ್ರತಿ ಚೌಕದ ಏಕಮಾನ ಚೌಕಗಳನ್ನು ಎಣಿಸಿ: ಇವೇ a², b² ಮತ್ತು c²."},{"en":"Compare a² + b² with c² and record them.","hi":"a² + b² की तुलना c² से करें और लिखें।","kn":"a² + b² ಅನ್ನು c² ಜೊತೆ ಹೋಲಿಸಿ ದಾಖಲಿಸಿ."},{"en":"Repeat with other right-angled triangles, such as 5 and 12, or 6 and 8.","hi":"दूसरे समकोण त्रिभुजों के साथ दोहराएँ, जैसे 5 और 12, या 6 और 8।","kn":"ಇತರ ಲಂಬಕೋನ ತ್ರಿಭುಜಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ, ಉದಾ: 5 ಮತ್ತು 12, ಅಥವಾ 6 ಮತ್ತು 8."},{"en":"Now make angle C smaller than 90°, then larger, keeping a and b the same. Compare c² with a² + b² each time.","hi":"अब a और b समान रखते हुए कोण C को 90° से छोटा, फिर बड़ा करें। हर बार c² की तुलना a² + b² से करें।","kn":"ಈಗ a ಮತ್ತು b ಅದೇ ಇರಿಸಿ C ಕೋನವನ್ನು 90° ಗಿಂತ ಚಿಕ್ಕದು, ನಂತರ ದೊಡ್ಡದು ಮಾಡಿ. ಪ್ರತಿ ಬಾರಿ c² ಅನ್ನು a² + b² ಜೊತೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Draw the right angle carefully with a set square.","hi":"सेट स्क्वेयर से समकोण ध्यान से बनाएँ।","kn":"ಸೆಟ್ ಸ್ಕ್ವೇರ್‌ನಿಂದ ಲಂಬಕೋನವನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ ರಚಿಸಿ."},{"en":"Make each square with all four sides equal to the side of the triangle.","hi":"हर वर्ग की चारों भुजाएँ त्रिभुज की भुजा के बराबर बनाएँ।","kn":"ಪ್ರತಿ ಚೌಕದ ನಾಲ್ಕೂ ಬಾಹುಗಳು ತ್ರಿಭುಜದ ಬಾಹುವಿಗೆ ಸಮವಾಗಿರಲಿ."},{"en":"Count part-squares on the slanting square carefully (or cut and fit them).","hi":"तिरछे वर्ग के आंशिक वर्गों को ध्यान से गिनें (या काटकर जोड़ें)।","kn":"ಓರೆಯಾದ ಚೌಕದ ಭಾಗಶಃ ಚೌಕಗಳನ್ನು ಎಚ್ಚರದಿಂದ ಎಣಿಸಿ (ಅಥವಾ ಕತ್ತರಿಸಿ ಜೋಡಿಸಿ)."}],"conclusion":{"en":"When angle C was 90°, the squares on a and b together had exactly as many unit squares as the square on c: a² + b² = c². When C was less than 90°, c² was smaller than a² + b², and when it was more than 90°, c² was larger. So a² + b² = c² holds exactly for right-angled triangles.","hi":"जब कोण C = 90° था, a और b पर बने वर्गों में मिलाकर ठीक उतने इकाई वर्ग थे जितने c पर बने वर्ग में: a² + b² = c²। जब C 90° से कम था, c², a² + b² से छोटा था, और 90° से अधिक होने पर बड़ा। अतः a² + b² = c² ठीक-ठीक समकोण त्रिभुजों के लिए सत्य है।","kn":"C ಕೋನ 90° ಇದ್ದಾಗ a ಮತ್ತು b ಮೇಲಿನ ಚೌಕಗಳಲ್ಲಿ ಒಟ್ಟು c ಮೇಲಿನ ಚೌಕದಷ್ಟೇ ಏಕಮಾನ ಚೌಕಗಳಿದ್ದವು: a² + b² = c². C 90° ಗಿಂತ ಕಡಿಮೆಯಿದ್ದಾಗ c², a² + b² ಗಿಂತ ಚಿಕ್ಕದು; 90° ಗಿಂತ ಹೆಚ್ಚಿದ್ದಾಗ ದೊಡ್ಡದು. ಆದ್ದರಿಂದ a² + b² = c² ನಿಖರವಾಗಿ ಲಂಬಕೋನ ತ್ರಿಭುಜಗಳಿಗೆ ಅನ್ವಯಿಸುತ್ತದೆ."},"viva":[{"q":{"en":"What is the hypotenuse?","hi":"कर्ण क्या है?","kn":"ವಿಕರ್ಣ ಎಂದರೇನು?"},"a":{"en":"The side opposite the right angle; it is the longest side.","hi":"समकोण के सामने की भुजा; यह सबसे लंबी भुजा होती है।","kn":"ಲಂಬಕೋನಕ್ಕೆ ಎದುರಿನ ಬಾಹು; ಅದು ಅತಿ ಉದ್ದದ ಬಾಹು."}},{"q":{"en":"The two shorter sides of a right-angled triangle are 6 cm and 8 cm. Find the hypotenuse.","hi":"एक समकोण त्रिभुज की दो छोटी भुजाएँ 6 cm और 8 cm हैं। कर्ण ज्ञात कीजिए।","kn":"ಲಂಬಕೋನ ತ್ರಿಭುಜದ ಎರಡು ಚಿಕ್ಕ ಬಾಹುಗಳು 6 cm ಮತ್ತು 8 cm. ವಿಕರ್ಣ ಕಂಡುಹಿಡಿಯಿರಿ."},"a":{"en":"√(36 + 64) = √100 = 10 cm.","hi":"√(36 + 64) = √100 = 10 cm।","kn":"√(36 + 64) = √100 = 10 cm."}},{"q":{"en":"Is 5, 12, 13 a Pythagorean triplet?","hi":"क्या 5, 12, 13 पाइथागोरस त्रिक है?","kn":"5, 12, 13 ಪೈಥಾಗೊರಸ್ ತ್ರಿವಳಿಯೇ?"},"a":{"en":"Yes: 25 + 144 = 169 = 13².","hi":"हाँ: 25 + 144 = 169 = 13²।","kn":"ಹೌದು: 25 + 144 = 169 = 13²."}},{"q":{"en":"Can a triangle with sides 4, 5 and 6 be right-angled?","hi":"क्या 4, 5 और 6 भुजाओं वाला त्रिभुज समकोण हो सकता है?","kn":"4, 5 ಮತ್ತು 6 ಬಾಹುಗಳ ತ್ರಿಭುಜ ಲಂಬಕೋನವಾಗಬಹುದೇ?"},"a":{"en":"No: 16 + 25 = 41, which is not 36. (41 is more than 36, so its largest angle is less than 90°.)","hi":"नहीं: 16 + 25 = 41, जो 36 नहीं है। (41, 36 से अधिक है, इसलिए इसका सबसे बड़ा कोण 90° से कम है।)","kn":"ಇಲ್ಲ: 16 + 25 = 41, ಅದು 36 ಅಲ್ಲ. (41 > 36, ಆದ್ದರಿಂದ ಅದರ ಅತಿ ದೊಡ್ಡ ಕೋನ 90° ಗಿಂತ ಕಡಿಮೆ.)"}},{"q":{"en":"How can a mason check a right angle with a rope?","hi":"राजमिस्त्री रस्सी से समकोण की जाँच कैसे कर सकता है?","kn":"ಗಾರೆ ಕೆಲಸಗಾರ ಹಗ್ಗದಿಂದ ಲಂಬಕೋನವನ್ನು ಹೇಗೆ ಪರೀಕ್ಷಿಸಬಹುದು?"},"a":{"en":"Mark 3 units along one side and 4 along the other; the corner is a right angle if the ends are exactly 5 units apart.","hi":"एक ओर 3 इकाई और दूसरी ओर 4 इकाई नापें; यदि सिरों के बीच ठीक 5 इकाई हो तो कोना समकोण है।","kn":"ಒಂದು ಕಡೆ 3 ಏಕಮಾನ, ಇನ್ನೊಂದು ಕಡೆ 4 ಏಕಮಾನ ಗುರುತಿಸಿ; ತುದಿಗಳ ನಡುವೆ ನಿಖರವಾಗಿ 5 ಏಕಮಾನ ಇದ್ದರೆ ಮೂಲೆ ಲಂಬಕೋನ."}}]},{"id":"circle-pi","bench":"circle","setup":{},"subject":"Mathematics","domain":"maths","levels":["7","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["circle","circles","circumference","circumference of a circle","pi","diameter","perimeter and area","areas related to circles","perimeter"],"title":{"en":"Circumference and π","hi":"परिधि और π","kn":"ಪರಿಧಿ ಮತ್ತು π"},"summary":{"en":"Roll round objects one full turn along a scale, measure the circumference, and find that C ÷ d is always about 3.14.","hi":"गोल वस्तुओं को पैमाने पर एक पूरा चक्कर लुढ़काएँ, परिधि मापें, और पाएँ कि C ÷ d हमेशा लगभग 3.14 होता है।","kn":"ದುಂಡು ವಸ್ತುಗಳನ್ನು ಅಳತೆಪಟ್ಟಿಯ ಮೇಲೆ ಒಂದು ಪೂರ್ಣ ಸುತ್ತು ಉರುಳಿಸಿ, ಪರಿಧಿ ಅಳೆದು, C ÷ d ಯಾವಾಗಲೂ ಸುಮಾರು 3.14 ಎಂದು ಕಂಡುಕೊಳ್ಳಿ."},"aim":{"en":"To find the ratio of the circumference of a circle to its diameter by measuring round objects.","hi":"गोल वस्तुओं को मापकर वृत्त की परिधि और व्यास का अनुपात ज्ञात करना।","kn":"ದುಂಡು ವಸ್ತುಗಳನ್ನು ಅಳೆದು ವೃತ್ತದ ಪರಿಧಿ ಮತ್ತು ವ್ಯಾಸದ ಅನುಪಾತ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"When a circle rolls one full turn without slipping, the distance it moves along a straight line equals its circumference C. For every circle, big or small, C ÷ d is the same number, called π (pi), which is about 3.14 (or 22/7). So C = πd = 2πr, and a graph of C against d is a straight line through the origin whose slope is π.","hi":"जब कोई वृत्त बिना फिसले एक पूरा चक्कर लुढ़कता है, तो सीधी रेखा पर तय की गई दूरी उसकी परिधि C के बराबर होती है। हर वृत्त के लिए, छोटा हो या बड़ा, C ÷ d एक ही संख्या होती है, जिसे π (पाई) कहते हैं और जो लगभग 3.14 (या 22/7) है। अतः C = πd = 2πr, और C तथा d का ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है जिसकी प्रवणता π है।","kn":"ವೃತ್ತವೊಂದು ಜಾರದೆ ಒಂದು ಪೂರ್ಣ ಸುತ್ತು ಉರುಳಿದಾಗ ಸರಳರೇಖೆಯಲ್ಲಿ ಅದು ಸಾಗುವ ದೂರ ಅದರ ಪರಿಧಿ C ಗೆ ಸಮ. ಪ್ರತಿ ವೃತ್ತಕ್ಕೂ, ದೊಡ್ಡದಿರಲಿ ಚಿಕ್ಕದಿರಲಿ, C ÷ d ಒಂದೇ ಸಂಖ್ಯೆ; ಅದನ್ನು π (ಪೈ) ಎನ್ನುತ್ತಾರೆ, ಅದು ಸುಮಾರು 3.14 (ಅಥವಾ 22/7). ಆದ್ದರಿಂದ C = πd = 2πr; C ಮತ್ತು d ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಹೋಗುವ ಸರಳರೇಖೆ, ಅದರ ಇಳಿಜಾರು π."},"apparatus":[{"en":"Round objects: a coin, a bottle cap, a bangle, a CD, a steel plate","hi":"गोल वस्तुएँ: सिक्का, बोतल का ढक्कन, चूड़ी, सीडी, स्टील की प्लेट","kn":"ದುಂಡು ವಸ್ತುಗಳು: ನಾಣ್ಯ, ಬಾಟಲಿಯ ಮುಚ್ಚಳ, ಬಳೆ, ಸಿಡಿ, ಉಕ್ಕಿನ ತಟ್ಟೆ"},{"en":"A long scale or measuring tape","hi":"लंबा पैमाना या मापने का फ़ीता","kn":"ಉದ್ದದ ಅಳತೆಪಟ್ಟಿ ಅಥವಾ ಅಳತೆ ಟೇಪ್"},{"en":"A marker pen and a thread","hi":"मार्कर पेन और धागा","kn":"ಮಾರ್ಕರ್ ಪೆನ್ ಮತ್ತು ದಾರ"}],"steps":[{"en":"Measure the diameter of the object across its widest part.","hi":"वस्तु का व्यास उसके सबसे चौड़े भाग के आर-पार मापें।","kn":"ವಸ್ತುವಿನ ವ್ಯಾಸವನ್ನು ಅದರ ಅತಿ ಅಗಲದ ಭಾಗದ ಅಡ್ಡಲಾಗಿ ಅಳೆಯಿರಿ."},{"en":"Put a mark on its rim and stand it on the scale with the mark at zero.","hi":"उसके किनारे पर निशान लगाएँ और उसे पैमाने पर इस तरह खड़ा करें कि निशान शून्य पर हो।","kn":"ಅದರ ಅಂಚಿನ ಮೇಲೆ ಗುರುತು ಮಾಡಿ, ಗುರುತು ಸೊನ್ನೆಯಲ್ಲಿರುವಂತೆ ಅಳತೆಪಟ್ಟಿಯ ಮೇಲೆ ನಿಲ್ಲಿಸಿ."},{"en":"Roll it slowly along the scale, without slipping, until the mark touches the scale again.","hi":"उसे पैमाने पर बिना फिसलाए धीरे-धीरे तब तक लुढ़काएँ जब तक निशान फिर पैमाने को न छुए।","kn":"ಗುರುತು ಮತ್ತೆ ಅಳತೆಪಟ್ಟಿಗೆ ತಾಗುವವರೆಗೆ ಜಾರದಂತೆ ನಿಧಾನವಾಗಿ ಉರುಳಿಸಿ."},{"en":"Read the distance: this is the circumference C.","hi":"दूरी पढ़ें: यही परिधि C है।","kn":"ದೂರವನ್ನು ಓದಿ: ಇದೇ ಪರಿಧಿ C."},{"en":"Work out C ÷ d and record it.","hi":"C ÷ d निकालें और लिखें।","kn":"C ÷ d ಲೆಕ್ಕಹಾಕಿ ದಾಖಲಿಸಿ."},{"en":"Repeat with the other objects, and plot C against d.","hi":"बाकी वस्तुओं के साथ दोहराएँ, और C तथा d का ग्राफ़ बनाएँ।","kn":"ಉಳಿದ ವಸ್ತುಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ, C ಮತ್ತು d ನಕ್ಷೆ ಬಿಡಿಸಿ."}],"precautions":[{"en":"Roll the object in a straight line and do not let it slip.","hi":"वस्तु को सीधी रेखा में लुढ़काएँ और फिसलने न दें।","kn":"ವಸ್ತುವನ್ನು ಸರಳರೇಖೆಯಲ್ಲಿ ಉರುಳಿಸಿ, ಜಾರಲು ಬಿಡಬೇಡಿ."},{"en":"Measure the diameter through the centre, at its widest.","hi":"व्यास केंद्र से होकर, सबसे चौड़े भाग पर मापें।","kn":"ವ್ಯಾಸವನ್ನು ಕೇಂದ್ರದ ಮೂಲಕ, ಅತಿ ಅಗಲದಲ್ಲಿ ಅಳೆಯಿರಿ."},{"en":"Read the scale with your eye straight above the mark.","hi":"निशान के ठीक ऊपर आँख रखकर पैमाना पढ़ें।","kn":"ಗುರುತಿನ ನೇರ ಮೇಲೆ ಕಣ್ಣಿಟ್ಟು ಅಳತೆಪಟ್ಟಿ ಓದಿ."}],"conclusion":{"en":"For every object C ÷ d came to about 3.14, whatever its size, and the graph of C against d was a straight line through the origin. This constant ratio is π, so the circumference of a circle is C = πd = 2πr.","hi":"हर वस्तु के लिए, आकार चाहे जो हो, C ÷ d लगभग 3.14 आया, और C तथा d का ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा था। यह स्थिर अनुपात π है, अतः वृत्त की परिधि C = πd = 2πr है।","kn":"ಪ್ರತಿ ವಸ್ತುವಿಗೂ, ಗಾತ್ರ ಏನೇ ಇರಲಿ, C ÷ d ಸುಮಾರು 3.14 ಬಂತು; C ಮತ್ತು d ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಹೋಗುವ ಸರಳರೇಖೆಯಾಗಿತ್ತು. ಈ ಸ್ಥಿರ ಅನುಪಾತವೇ π; ಆದ್ದರಿಂದ ವೃತ್ತದ ಪರಿಧಿ C = πd = 2πr."},"viva":[{"q":{"en":"What is π?","hi":"π क्या है?","kn":"π ಎಂದರೇನು?"},"a":{"en":"The ratio of the circumference of any circle to its diameter, about 3.14.","hi":"किसी भी वृत्त की परिधि और व्यास का अनुपात, लगभग 3.14।","kn":"ಯಾವುದೇ ವೃತ್ತದ ಪರಿಧಿ ಮತ್ತು ವ್ಯಾಸದ ಅನುಪಾತ, ಸುಮಾರು 3.14."}},{"q":{"en":"Find the circumference of a wheel of diameter 70 cm (π = 22/7).","hi":"70 cm व्यास वाले पहिये की परिधि ज्ञात कीजिए (π = 22/7)।","kn":"70 cm ವ್ಯಾಸದ ಚಕ್ರದ ಪರಿಧಿ ಕಂಡುಹಿಡಿಯಿರಿ (π = 22/7)."},"a":{"en":"22/7 × 70 = 220 cm.","hi":"22/7 × 70 = 220 cm।","kn":"22/7 × 70 = 220 cm."}},{"q":{"en":"How far does that wheel move in 10 turns?","hi":"वह पहिया 10 चक्कर में कितनी दूर जाता है?","kn":"ಆ ಚಕ್ರ 10 ಸುತ್ತುಗಳಲ್ಲಿ ಎಷ್ಟು ದೂರ ಸಾಗುತ್ತದೆ?"},"a":{"en":"10 × 220 cm = 22 m.","hi":"10 × 220 cm = 22 m।","kn":"10 × 220 cm = 22 m."}},{"q":{"en":"If the diameter is doubled, what happens to the circumference?","hi":"व्यास दोगुना करने पर परिधि को क्या होता है?","kn":"ವ್ಯಾಸ ದ್ವಿಗುಣವಾದರೆ ಪರಿಧಿಗೆ ಏನಾಗುತ್ತದೆ?"},"a":{"en":"It also doubles, because C is proportional to d.","hi":"वह भी दोगुनी हो जाती है, क्योंकि C, d के अनुक्रमानुपाती है।","kn":"ಅದೂ ದ್ವಿಗುಣವಾಗುತ್ತದೆ, ಏಕೆಂದರೆ C, d ಗೆ ಅನುಪಾತದಲ್ಲಿದೆ."}},{"q":{"en":"Why do our measurements give 3.13 or 3.16 instead of exactly π?","hi":"हमारे माप ठीक π की जगह 3.13 या 3.16 क्यों देते हैं?","kn":"ನಮ್ಮ ಅಳತೆಗಳು ನಿಖರವಾಗಿ π ಬದಲು 3.13 ಅಥವಾ 3.16 ಏಕೆ ನೀಡುತ್ತವೆ?"},"a":{"en":"A scale reads only to the nearest millimetre, and a small object makes that error count more.","hi":"पैमाना केवल निकटतम मिलीमीटर तक पढ़ता है, और छोटी वस्तु में यह त्रुटि अधिक असर डालती है।","kn":"ಅಳತೆಪಟ್ಟಿ ಹತ್ತಿರದ ಮಿಲಿಮೀಟರ್‌ವರೆಗೆ ಮಾತ್ರ ಓದುತ್ತದೆ; ಚಿಕ್ಕ ವಸ್ತುವಿನಲ್ಲಿ ಆ ದೋಷದ ಪ್ರಭಾವ ಹೆಚ್ಚು."}}]},{"id":"lever","bench":"lever","setup":{},"subject":"Physics","domain":"physics","levels":["9","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["moments","moment of force","principle of moments","turning effect","lever","levers","machines","simple machines","force moments and circular motion","equilibrium","centre of gravity"],"title":{"en":"The principle of moments","hi":"आघूर्णों का सिद्धांत","kn":"ಭ್ರಾಮಕಗಳ ತತ್ವ"},"summary":{"en":"Hang weights on both sides of a metre rule balanced at its middle, balance it, and compare the turning effects on each side.","hi":"बीच में संतुलित मीटर पैमाने के दोनों ओर भार लटकाएँ, उसे संतुलित करें और दोनों ओर के घुमाव प्रभावों की तुलना करें।","kn":"ಮಧ್ಯದಲ್ಲಿ ಸಮತೋಲನಗೊಂಡ ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿಯ ಎರಡೂ ಬದಿ ತೂಕ ತೂಗುಹಾಕಿ, ಸಮತೋಲನಗೊಳಿಸಿ, ಎರಡೂ ಬದಿಯ ತಿರುಗಿಸುವ ಪರಿಣಾಮಗಳನ್ನು ಹೋಲಿಸಿ."},"aim":{"en":"To verify the principle of moments using a metre rule balanced on a knife edge.","hi":"चाकू-धार पर संतुलित मीटर पैमाने की सहायता से आघूर्णों के सिद्धांत का सत्यापन करना।","kn":"ಚಾಕು ಅಂಚಿನ ಮೇಲೆ ಸಮತೋಲನಗೊಂಡ ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿಯಿಂದ ಭ್ರಾಮಕಗಳ ತತ್ವವನ್ನು ದೃಢಪಡಿಸುವುದು."},"principle":{"en":"The turning effect of a force about a point is its moment: force × perpendicular distance from the point. A weight hung to the left of the fulcrum turns the rule anticlockwise; one to the right turns it clockwise. When the rule stays level, it is in equilibrium, and the sum of the anticlockwise moments equals the sum of the clockwise moments. This is the principle of moments, and every lever works by it: a small force far from the fulcrum balances a large force close to it.","hi":"किसी बिंदु के परितः बल का घुमाव प्रभाव उसका आघूर्ण है: बल × उस बिंदु से लंबवत दूरी। आलंब के बाईं ओर लटका भार पैमाने को वामावर्त घुमाता है; दाईं ओर का भार दक्षिणावर्त। जब पैमाना समतल रहता है, वह संतुलन में होता है, और वामावर्त आघूर्णों का योग दक्षिणावर्त आघूर्णों के योग के बराबर होता है। यही आघूर्णों का सिद्धांत है, और हर उत्तोलक इसी से काम करता है: आलंब से दूर लगा छोटा बल उसके पास लगे बड़े बल को संतुलित कर देता है।","kn":"ಒಂದು ಬಿಂದುವಿನ ಸುತ್ತ ಬಲದ ತಿರುಗಿಸುವ ಪರಿಣಾಮವೇ ಅದರ ಭ್ರಾಮಕ: ಬಲ × ಆ ಬಿಂದುವಿನಿಂದ ಲಂಬ ದೂರ. ಆಧಾರಬಿಂದುವಿನ ಎಡಕ್ಕೆ ತೂಗಿದ ತೂಕ ಪಟ್ಟಿಯನ್ನು ಅಪ್ರದಕ್ಷಿಣವಾಗಿ ತಿರುಗಿಸುತ್ತದೆ; ಬಲಕ್ಕೆ ತೂಗಿದ್ದು ಪ್ರದಕ್ಷಿಣವಾಗಿ. ಪಟ್ಟಿ ಸಮತಲವಾಗಿ ನಿಂತಾಗ ಅದು ಸಮತೋಲನದಲ್ಲಿದೆ; ಅಪ್ರದಕ್ಷಿಣ ಭ್ರಾಮಕಗಳ ಮೊತ್ತ ಪ್ರದಕ್ಷಿಣ ಭ್ರಾಮಕಗಳ ಮೊತ್ತಕ್ಕೆ ಸಮ. ಇದೇ ಭ್ರಾಮಕಗಳ ತತ್ವ; ಪ್ರತಿ ಸನ್ನೆ ಇದರಿಂದಲೇ ಕೆಲಸ ಮಾಡುತ್ತದೆ: ಆಧಾರಬಿಂದುವಿನಿಂದ ದೂರದ ಸಣ್ಣ ಬಲ ಅದರ ಹತ್ತಿರದ ದೊಡ್ಡ ಬಲವನ್ನು ಸಮತೋಲನಗೊಳಿಸುತ್ತದೆ."},"apparatus":[{"en":"A metre rule with a hole at the 50 cm mark","hi":"50 सेमी चिह्न पर छेद वाला मीटर पैमाना","kn":"50 ಸೆಂ.ಮೀ. ಗುರುತಿನಲ್ಲಿ ರಂಧ್ರವಿರುವ ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ"},{"en":"A knife edge or a nail on a stand (the fulcrum)","hi":"स्टैंड पर चाकू-धार या कील (आलंब)","kn":"ಸ್ಟ್ಯಾಂಡ್ ಮೇಲೆ ಚಾಕು ಅಂಚು ಅಥವಾ ಮೊಳೆ (ಆಧಾರಬಿಂದು)"},{"en":"Slotted weights of 50 g, 100 g, 150 g and 200 g with hangers","hi":"हैंगर सहित 50 ग्रा, 100 ग्रा, 150 ग्रा और 200 ग्रा के स्लॉटेड भार","kn":"ಹ್ಯಾಂಗರ್ ಸಹಿತ 50 ಗ್ರಾಂ, 100 ಗ್ರಾಂ, 150 ಗ್ರಾಂ ಮತ್ತು 200 ಗ್ರಾಂ ತೂಕಗಳು"},{"en":"Thread loops to hang the weights","hi":"भार लटकाने के लिए धागे के फंदे","kn":"ತೂಕ ತೂಗಲು ದಾರದ ಕುಣಿಕೆಗಳು"}],"steps":[{"en":"Hang the metre rule on the knife edge at its 50 cm mark and check that it rests level with nothing on it.","hi":"मीटर पैमाने को उसके 50 सेमी चिह्न पर चाकू-धार पर टाँगें और जाँचें कि बिना भार के वह समतल रहता है।","kn":"ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿಯನ್ನು ಅದರ 50 ಸೆಂ.ಮೀ. ಗುರುತಿನಲ್ಲಿ ಚಾಕು ಅಂಚಿಗೆ ತೂಗಿಸಿ, ಏನೂ ಇಲ್ಲದಾಗ ಸಮತಲವಾಗಿರುವುದನ್ನು ಪರಿಶೀಲಿಸಿ."},{"en":"Hang a weight on the left side at a known distance from the fulcrum.","hi":"आलंब से ज्ञात दूरी पर बाईं ओर एक भार लटकाएँ।","kn":"ಆಧಾರಬಿಂದುವಿನಿಂದ ತಿಳಿದ ದೂರದಲ್ಲಿ ಎಡಬದಿಗೆ ಒಂದು ತೂಕ ತೂಗಿಸಿ."},{"en":"Hang another weight on the right side and slide it until the rule is level again.","hi":"दाईं ओर दूसरा भार लटकाएँ और उसे तब तक खिसकाएँ जब तक पैमाना फिर समतल न हो जाए।","kn":"ಬಲಬದಿಗೆ ಇನ್ನೊಂದು ತೂಕ ತೂಗಿಸಿ, ಪಟ್ಟಿ ಮತ್ತೆ ಸಮತಲವಾಗುವವರೆಗೆ ಸರಿಸಿ."},{"en":"Read both distances from the fulcrum and record both weights.","hi":"आलंब से दोनों दूरियाँ पढ़ें और दोनों भार लिखें।","kn":"ಆಧಾರಬಿಂದುವಿನಿಂದ ಎರಡೂ ದೂರಗಳನ್ನು ಓದಿ, ಎರಡೂ ತೂಕಗಳನ್ನು ದಾಖಲಿಸಿ."},{"en":"Work out weight × distance on each side.","hi":"हर ओर भार × दूरी निकालें।","kn":"ಪ್ರತಿ ಬದಿಗೆ ತೂಕ × ದೂರ ಲೆಕ್ಕಹಾಕಿ."},{"en":"Repeat with other weights and distances, at least four times.","hi":"दूसरे भारों और दूरियों के साथ कम-से-कम चार बार दोहराएँ।","kn":"ಬೇರೆ ತೂಕ ಮತ್ತು ದೂರಗಳೊಂದಿಗೆ ಕನಿಷ್ಠ ನಾಲ್ಕು ಬಾರಿ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"The rule must be level before any weight is hung.","hi":"कोई भार लटकाने से पहले पैमाना समतल होना चाहिए।","kn":"ಯಾವುದೇ ತೂಕ ತೂಗುವ ಮೊದಲು ಪಟ್ಟಿ ಸಮತಲವಾಗಿರಬೇಕು."},{"en":"Hang the thread loops so they hang straight down, and read the distance at the thread.","hi":"धागे के फंदे सीधे नीचे लटकें और दूरी धागे पर पढ़ें।","kn":"ದಾರದ ಕುಣಿಕೆಗಳು ನೇರವಾಗಿ ಕೆಳಗೆ ತೂಗಲಿ; ದೂರವನ್ನು ದಾರದ ಬಳಿ ಓದಿ."},{"en":"Wait for the rule to stop swinging before deciding it is level.","hi":"समतल मानने से पहले पैमाने का झूलना रुकने दें।","kn":"ಸಮತಲ ಎಂದು ತೀರ್ಮಾನಿಸುವ ಮೊದಲು ಪಟ್ಟಿಯ ತೂಗಾಟ ನಿಲ್ಲಲಿ."}],"conclusion":{"en":"Whenever the rule balances, weight × distance on the left equals weight × distance on the right: the anticlockwise moment equals the clockwise moment. The principle of moments is verified.","hi":"जब भी पैमाना संतुलित होता है, बाईं ओर भार × दूरी दाईं ओर के भार × दूरी के बराबर होता है: वामावर्त आघूर्ण दक्षिणावर्त आघूर्ण के बराबर है। आघूर्णों के सिद्धांत का सत्यापन होता है।","kn":"ಪಟ್ಟಿ ಸಮತೋಲನಗೊಂಡಾಗಲೆಲ್ಲಾ ಎಡಬದಿಯ ತೂಕ × ದೂರ ಬಲಬದಿಯ ತೂಕ × ದೂರಕ್ಕೆ ಸಮ: ಅಪ್ರದಕ್ಷಿಣ ಭ್ರಾಮಕ ಪ್ರದಕ್ಷಿಣ ಭ್ರಾಮಕಕ್ಕೆ ಸಮ. ಭ್ರಾಮಕಗಳ ತತ್ವ ದೃಢಪಟ್ಟಿತು."},"viva":[{"q":{"en":"What is the moment of a force?","hi":"बल का आघूर्ण क्या है?","kn":"ಬಲದ ಭ್ರಾಮಕ ಎಂದರೇನು?"},"a":{"en":"Its turning effect: force × perpendicular distance from the turning point.","hi":"उसका घुमाव प्रभाव: बल × घूर्णन बिंदु से लंबवत दूरी।","kn":"ಅದರ ತಿರುಗಿಸುವ ಪರಿಣಾಮ: ಬಲ × ತಿರುಗುವ ಬಿಂದುವಿನಿಂದ ಲಂಬ ದೂರ."}},{"q":{"en":"What is the SI unit of moment of force?","hi":"बल के आघूर्ण का SI मात्रक क्या है?","kn":"ಬಲದ ಭ್ರಾಮಕದ SI ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"The newton metre (N m).","hi":"न्यूटन मीटर (N m)।","kn":"ನ್ಯೂಟನ್ ಮೀಟರ್ (N m)."}},{"q":{"en":"Why is a door handle fixed far from the hinges?","hi":"दरवाज़े का हत्था कब्ज़ों से दूर क्यों लगाया जाता है?","kn":"ಬಾಗಿಲಿನ ಹಿಡಿಕೆಯನ್ನು ಕೀಲುಗಳಿಂದ ದೂರ ಏಕೆ ಅಳವಡಿಸುತ್ತಾರೆ?"},"a":{"en":"A larger distance gives a larger moment, so a small force opens the door.","hi":"अधिक दूरी से आघूर्ण अधिक होता है, इसलिए छोटा बल दरवाज़ा खोल देता है।","kn":"ಹೆಚ್ಚು ದೂರ ಹೆಚ್ಚು ಭ್ರಾಮಕ ನೀಡುತ್ತದೆ; ಆದ್ದರಿಂದ ಸಣ್ಣ ಬಲ ಬಾಗಿಲು ತೆರೆಯುತ್ತದೆ."}},{"q":{"en":"A 100 g weight at 20 cm balances a weight at 40 cm on the other side. What is that weight?","hi":"20 सेमी पर 100 ग्रा भार दूसरी ओर 40 सेमी पर रखे भार को संतुलित करता है। वह भार कितना है?","kn":"20 ಸೆಂ.ಮೀ.ನಲ್ಲಿ 100 ಗ್ರಾಂ ತೂಕ ಇನ್ನೊಂದು ಬದಿಯ 40 ಸೆಂ.ಮೀ.ನಲ್ಲಿರುವ ತೂಕವನ್ನು ಸಮತೋಲನಗೊಳಿಸುತ್ತದೆ. ಆ ತೂಕ ಎಷ್ಟು?"},"a":{"en":"50 g, because 100 × 20 = 50 × 40.","hi":"50 ग्रा, क्योंकि 100 × 20 = 50 × 40।","kn":"50 ಗ್ರಾಂ, ಏಕೆಂದರೆ 100 × 20 = 50 × 40."}},{"q":{"en":"Name the three classes of levers with an example of each.","hi":"उत्तोलक के तीन वर्ग उदाहरण सहित बताइए।","kn":"ಸನ್ನೆಗಳ ಮೂರು ವರ್ಗಗಳನ್ನು ಉದಾಹರಣೆ ಸಹಿತ ಹೆಸರಿಸಿ."},"a":{"en":"Class I: fulcrum in the middle (see-saw, scissors); class II: load in the middle (nutcracker, wheelbarrow); class III: effort in the middle (tongs, forearm).","hi":"वर्ग I: आलंब बीच में (सी-सॉ, कैंची); वर्ग II: भार बीच में (सरौता, हाथ-ठेला); वर्ग III: प्रयास बीच में (चिमटा, अग्रबाहु)।","kn":"ವರ್ಗ I: ಆಧಾರಬಿಂದು ಮಧ್ಯದಲ್ಲಿ (ಸೀಸಾ, ಕತ್ತರಿ); ವರ್ಗ II: ಭಾರ ಮಧ್ಯದಲ್ಲಿ (ಅಡಿಕೆ ಕತ್ತರಿ, ಕೈಗಾಡಿ); ವರ್ಗ III: ಪ್ರಯತ್ನ ಮಧ್ಯದಲ್ಲಿ (ಇಕ್ಕಳ, ಮುಂಗೈ)."}}]},{"id":"electromagnet","bench":"electromagnet","setup":{},"subject":"Physics","domain":"physics","levels":["7","10"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["electromagnet","electromagnets","electromagnetism","magnetic effects of electric current","magnetic effect of current","magnetic effect of electric current","solenoid","electric current and its effects","coil"],"title":{"en":"Making an electromagnet stronger","hi":"विद्युत चुंबक को अधिक शक्तिशाली बनाना","kn":"ವಿದ್ಯುತ್ಕಾಂತವನ್ನು ಬಲಪಡಿಸುವುದು"},"summary":{"en":"Wind a coil on an iron nail, pass a current, and count the pins it lifts as you change the turns, the current and the core.","hi":"लोहे की कील पर कुंडली लपेटें, धारा प्रवाहित करें, और फेरों, धारा और क्रोड को बदलते हुए उठाई गई पिनें गिनें।","kn":"ಕಬ್ಬಿಣದ ಮೊಳೆಗೆ ಸುರುಳಿ ಸುತ್ತಿ ವಿದ್ಯುತ್ ಹರಿಸಿ; ಸುತ್ತುಗಳು, ವಿದ್ಯುತ್ ಮತ್ತು ತಿರುಳನ್ನು ಬದಲಿಸುತ್ತಾ ಎತ್ತಿದ ಗುಂಡುಸೂಜಿಗಳನ್ನು ಎಣಿಸಿ."},"aim":{"en":"To study how the strength of an electromagnet depends on the number of turns, the current and the core.","hi":"यह अध्ययन करना कि विद्युत चुंबक की शक्ति फेरों की संख्या, धारा और क्रोड पर कैसे निर्भर करती है।","kn":"ವಿದ್ಯುತ್ಕಾಂತದ ಶಕ್ತಿ ಸುತ್ತುಗಳ ಸಂಖ್ಯೆ, ವಿದ್ಯುತ್ ಮತ್ತು ತಿರುಳಿನ ಮೇಲೆ ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ ಎಂದು ಅಧ್ಯಯನ ಮಾಡುವುದು."},"principle":{"en":"A current in a wire makes a magnetic field around it. Wound into a coil, the fields of the turns add up, so more turns and a larger current give a stronger field. A soft iron core inside the coil becomes a magnet itself and makes the field hundreds of times stronger. The magnet works only while the current flows, which is why electromagnets are used in cranes, electric bells, relays and motors.","hi":"तार में धारा उसके चारों ओर चुंबकीय क्षेत्र बनाती है। कुंडली बनाने पर फेरों के क्षेत्र जुड़ जाते हैं, इसलिए अधिक फेरे और अधिक धारा से क्षेत्र प्रबल होता है। कुंडली के भीतर नरम लोहे का क्रोड स्वयं चुंबक बन जाता है और क्षेत्र को सैकड़ों गुना प्रबल कर देता है। यह चुंबक केवल धारा बहने तक काम करता है, इसीलिए विद्युत चुंबक क्रेन, बिजली की घंटी, रिले और मोटर में उपयोग होते हैं।","kn":"ತಂತಿಯಲ್ಲಿನ ವಿದ್ಯುತ್ ಅದರ ಸುತ್ತ ಕಾಂತಕ್ಷೇತ್ರವನ್ನು ಉಂಟುಮಾಡುತ್ತದೆ. ಸುರುಳಿಯಾಗಿ ಸುತ್ತಿದಾಗ ಸುತ್ತುಗಳ ಕ್ಷೇತ್ರಗಳು ಕೂಡುತ್ತವೆ; ಹೆಚ್ಚು ಸುತ್ತುಗಳು ಮತ್ತು ಹೆಚ್ಚು ವಿದ್ಯುತ್ ಬಲವಾದ ಕ್ಷೇತ್ರ ನೀಡುತ್ತವೆ. ಸುರುಳಿಯೊಳಗಿನ ಮೃದು ಕಬ್ಬಿಣದ ತಿರುಳು ತಾನೇ ಕಾಂತವಾಗಿ ಕ್ಷೇತ್ರವನ್ನು ನೂರಾರು ಪಟ್ಟು ಬಲಪಡಿಸುತ್ತದೆ. ವಿದ್ಯುತ್ ಹರಿಯುವವರೆಗೆ ಮಾತ್ರ ಈ ಕಾಂತ ಕೆಲಸ ಮಾಡುತ್ತದೆ; ಆದ್ದರಿಂದ ವಿದ್ಯುತ್ಕಾಂತಗಳನ್ನು ಕ್ರೇನ್, ವಿದ್ಯುತ್ ಗಂಟೆ, ರಿಲೇ ಮತ್ತು ಮೋಟಾರ್‌ಗಳಲ್ಲಿ ಬಳಸುತ್ತಾರೆ."},"apparatus":[{"en":"A large iron nail (and a wooden rod of the same size)","hi":"एक बड़ी लोहे की कील (और उतनी ही बड़ी लकड़ी की छड़)","kn":"ಒಂದು ದೊಡ್ಡ ಕಬ್ಬಿಣದ ಮೊಳೆ (ಮತ್ತು ಅದೇ ಗಾತ್ರದ ಮರದ ಕಡ್ಡಿ)"},{"en":"Insulated copper wire","hi":"विद्युतरोधी ताँबे का तार","kn":"ನಿರೋಧಕ ಹೊದಿಕೆಯ ತಾಮ್ರದ ತಂತಿ"},{"en":"A battery, a rheostat, an ammeter and a switch","hi":"बैटरी, धारा नियंत्रक, ऐमीटर और स्विच","kn":"ಬ್ಯಾಟರಿ, ರಿಯೋಸ್ಟಾಟ್, ಅಮ್ಮೀಟರ್ ಮತ್ತು ಸ್ವಿಚ್"},{"en":"A box of steel pins","hi":"स्टील की पिनों का डिब्बा","kn":"ಉಕ್ಕಿನ ಗುಂಡುಸೂಜಿಗಳ ಪೆಟ್ಟಿಗೆ"}],"steps":[{"en":"Wind 20 turns of wire closely on the nail and connect the coil in series with the battery, rheostat, ammeter and switch.","hi":"कील पर तार के 20 फेरे पास-पास लपेटें और कुंडली को बैटरी, धारा नियंत्रक, ऐमीटर और स्विच के साथ श्रेणी में जोड़ें।","kn":"ಮೊಳೆಗೆ 20 ಸುತ್ತು ತಂತಿಯನ್ನು ಹತ್ತಿರ ಹತ್ತಿರವಾಗಿ ಸುತ್ತಿ, ಸುರುಳಿಯನ್ನು ಬ್ಯಾಟರಿ, ರಿಯೋಸ್ಟಾಟ್, ಅಮ್ಮೀಟರ್ ಮತ್ತು ಸ್ವಿಚ್‌ನೊಂದಿಗೆ ಶ್ರೇಣಿಯಲ್ಲಿ ಜೋಡಿಸಿ."},{"en":"Close the switch, set a current with the rheostat, and dip the tip of the nail into the pins.","hi":"स्विच बंद करें, धारा नियंत्रक से धारा निर्धारित करें और कील की नोक को पिनों में डुबोएँ।","kn":"ಸ್ವಿಚ್ ಮುಚ್ಚಿ, ರಿಯೋಸ್ಟಾಟ್‌ನಿಂದ ವಿದ್ಯುತ್ ನಿಗದಿಪಡಿಸಿ, ಮೊಳೆಯ ತುದಿಯನ್ನು ಗುಂಡುಸೂಜಿಗಳಲ್ಲಿ ಅದ್ದಿ."},{"en":"Lift it and count the pins that hang on. Open the switch and see them drop.","hi":"उसे उठाएँ और लटकी पिनें गिनें। स्विच खोलें और पिनों को गिरते देखें।","kn":"ಅದನ್ನು ಎತ್ತಿ ನೇತಾಡುವ ಸೂಜಿಗಳನ್ನು ಎಣಿಸಿ. ಸ್ವಿಚ್ ತೆರೆದು ಅವು ಬೀಳುವುದನ್ನು ನೋಡಿ."},{"en":"Increase the current and count again; then add turns and count again.","hi":"धारा बढ़ाकर फिर गिनें; फिर फेरे बढ़ाकर फिर गिनें।","kn":"ವಿದ್ಯುತ್ ಹೆಚ್ಚಿಸಿ ಮತ್ತೆ ಎಣಿಸಿ; ನಂತರ ಸುತ್ತುಗಳನ್ನು ಹೆಚ್ಚಿಸಿ ಮತ್ತೆ ಎಣಿಸಿ."},{"en":"Replace the nail by the wooden rod with the same coil and count again.","hi":"उसी कुंडली के साथ कील के स्थान पर लकड़ी की छड़ रखें और फिर गिनें।","kn":"ಅದೇ ಸುರುಳಿಯೊಂದಿಗೆ ಮೊಳೆಯ ಬದಲು ಮರದ ಕಡ್ಡಿ ಇಟ್ಟು ಮತ್ತೆ ಎಣಿಸಿ."},{"en":"Record turns, current, core and pins for every trial.","hi":"हर प्रयास के लिए फेरे, धारा, क्रोड और पिनें लिखें।","kn":"ಪ್ರತಿ ಪ್ರಯತ್ನಕ್ಕೆ ಸುತ್ತು, ವಿದ್ಯುತ್, ತಿರುಳು ಮತ್ತು ಸೂಜಿಗಳನ್ನು ದಾಖಲಿಸಿ."}],"precautions":[{"en":"Keep the current on only while counting: the coil warms up and the battery runs down.","hi":"धारा केवल गिनते समय चालू रखें: कुंडली गरम होती है और बैटरी खत्म होती है।","kn":"ಎಣಿಸುವಾಗ ಮಾತ್ರ ವಿದ್ಯುತ್ ಹರಿಯಲಿ: ಸುರುಳಿ ಬಿಸಿಯಾಗುತ್ತದೆ, ಬ್ಯಾಟರಿ ಖಾಲಿಯಾಗುತ್ತದೆ."},{"en":"Wind all turns in the same direction.","hi":"सभी फेरे एक ही दिशा में लपेटें।","kn":"ಎಲ್ಲ ಸುತ್ತುಗಳನ್ನು ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಸುತ್ತಿ."},{"en":"Use insulated wire and scrape the ends only where they are connected.","hi":"विद्युतरोधी तार का उपयोग करें और केवल जोड़ के सिरों को खुरचें।","kn":"ನಿರೋಧಕ ತಂತಿ ಬಳಸಿ; ಜೋಡಿಸುವ ತುದಿಗಳನ್ನು ಮಾತ್ರ ಕೆರೆಯಿರಿ."}],"conclusion":{"en":"The electromagnet lifts more pins when the current is larger and when the coil has more turns. With the iron core it lifts many pins; with a wooden core almost none. It lets go of the pins when the current stops.","hi":"धारा अधिक होने और कुंडली में फेरे अधिक होने पर विद्युत चुंबक अधिक पिनें उठाता है। लोहे के क्रोड के साथ वह बहुत पिनें उठाता है; लकड़ी के क्रोड के साथ लगभग कोई नहीं। धारा रुकते ही वह पिनें छोड़ देता है।","kn":"ವಿದ್ಯುತ್ ಹೆಚ್ಚಿದ್ದಾಗ ಮತ್ತು ಸುರುಳಿಗೆ ಹೆಚ್ಚು ಸುತ್ತುಗಳಿದ್ದಾಗ ವಿದ್ಯುತ್ಕಾಂತ ಹೆಚ್ಚು ಸೂಜಿಗಳನ್ನು ಎತ್ತುತ್ತದೆ. ಕಬ್ಬಿಣದ ತಿರುಳಿನೊಂದಿಗೆ ಅನೇಕ ಸೂಜಿಗಳನ್ನು ಎತ್ತುತ್ತದೆ; ಮರದ ತಿರುಳಿನೊಂದಿಗೆ ಬಹುತೇಕ ಇಲ್ಲ. ವಿದ್ಯುತ್ ನಿಂತಾಗ ಸೂಜಿಗಳನ್ನು ಬಿಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why is soft iron used as the core?","hi":"क्रोड के रूप में नरम लोहा क्यों उपयोग होता है?","kn":"ತಿರುಳಾಗಿ ಮೃದು ಕಬ್ಬಿಣವನ್ನು ಏಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"It becomes strongly magnetic when the current flows and loses its magnetism when the current stops.","hi":"धारा बहने पर यह प्रबल चुंबक बन जाता है और धारा रुकने पर चुंबकत्व खो देता है।","kn":"ವಿದ್ಯುತ್ ಹರಿದಾಗ ಬಲವಾದ ಕಾಂತವಾಗುತ್ತದೆ, ವಿದ್ಯುತ್ ನಿಂತಾಗ ಕಾಂತತ್ವ ಕಳೆದುಕೊಳ್ಳುತ್ತದೆ."}},{"q":{"en":"Give two ways to make an electromagnet stronger.","hi":"विद्युत चुंबक को प्रबल बनाने के दो उपाय बताइए।","kn":"ವಿದ್ಯುತ್ಕಾಂತವನ್ನು ಬಲಪಡಿಸುವ ಎರಡು ವಿಧಾನ ತಿಳಿಸಿ."},"a":{"en":"Increase the current; increase the number of turns (and use a soft iron core).","hi":"धारा बढ़ाएँ; फेरों की संख्या बढ़ाएँ (और नरम लोहे का क्रोड लगाएँ)।","kn":"ವಿದ್ಯುತ್ ಹೆಚ್ಚಿಸಿ; ಸುತ್ತುಗಳ ಸಂಖ್ಯೆ ಹೆಚ್ಚಿಸಿ (ಮತ್ತು ಮೃದು ಕಬ್ಬಿಣದ ತಿರುಳು ಬಳಸಿ)."}},{"q":{"en":"How is an electromagnet different from a bar magnet?","hi":"विद्युत चुंबक छड़ चुंबक से कैसे भिन्न है?","kn":"ವಿದ್ಯುತ್ಕಾಂತ ದಂಡಕಾಂತಕ್ಕಿಂತ ಹೇಗೆ ಭಿನ್ನ?"},"a":{"en":"It is a magnet only while the current flows, its strength can be changed, and its poles swap when the current is reversed.","hi":"यह केवल धारा बहने तक चुंबक रहता है, इसकी शक्ति बदली जा सकती है और धारा उलटने पर ध्रुव बदल जाते हैं।","kn":"ವಿದ್ಯುತ್ ಹರಿಯುವವರೆಗೆ ಮಾತ್ರ ಕಾಂತ; ಅದರ ಶಕ್ತಿ ಬದಲಿಸಬಹುದು; ವಿದ್ಯುತ್ ತಿರುಗಿಸಿದಾಗ ಧ್ರುವಗಳು ಅದಲು ಬದಲಾಗುತ್ತವೆ."}},{"q":{"en":"Name two devices that use electromagnets.","hi":"विद्युत चुंबक का उपयोग करने वाले दो उपकरण बताइए।","kn":"ವಿದ್ಯುತ್ಕಾಂತ ಬಳಸುವ ಎರಡು ಸಾಧನಗಳನ್ನು ಹೆಸರಿಸಿ."},"a":{"en":"An electric bell and a crane that lifts scrap iron (also relays, motors, loudspeakers).","hi":"बिजली की घंटी और लोहे का कबाड़ उठाने वाली क्रेन (रिले, मोटर, लाउडस्पीकर भी)।","kn":"ವಿದ್ಯುತ್ ಗಂಟೆ ಮತ್ತು ಕಬ್ಬಿಣದ ಗುಜರಿ ಎತ್ತುವ ಕ್ರೇನ್ (ರಿಲೇ, ಮೋಟಾರ್, ಧ್ವನಿವರ್ಧಕ ಕೂಡ)."}},{"q":{"en":"How can you find which end of the coil is the north pole?","hi":"कुंडली का कौन-सा सिरा उत्तरी ध्रुव है, यह कैसे पता करेंगे?","kn":"ಸುರುಳಿಯ ಯಾವ ತುದಿ ಉತ್ತರ ಧ್ರುವ ಎಂದು ಹೇಗೆ ತಿಳಿಯುವಿರಿ?"},"a":{"en":"Bring a compass near it (or use the right-hand rule: fingers along the current, thumb points to north).","hi":"पास में दिक्सूचक लाएँ (या दाएँ हाथ का नियम: उँगलियाँ धारा की दिशा में, अँगूठा उत्तर की ओर)।","kn":"ಹತ್ತಿರ ದಿಕ್ಸೂಚಿ ತನ್ನಿ (ಅಥವಾ ಬಲಗೈ ನಿಯಮ: ಬೆರಳುಗಳು ವಿದ್ಯುತ್ ದಿಕ್ಕಿನಲ್ಲಿ, ಹೆಬ್ಬೆರಳು ಉತ್ತರದ ಕಡೆ)."}}]},{"id":"calorimetry","bench":"calorimetry","setup":{},"subject":"Physics","domain":"physics","levels":["9","10","11"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["calorimetry","specific heat","specific heat capacity","method of mixtures","heat capacity","calorimeter","heat and temperature"],"title":{"en":"Specific heat by the method of mixtures","hi":"मिश्रण विधि से विशिष्ट ऊष्मा","kn":"ಮಿಶ್ರಣ ವಿಧಾನದಿಂದ ವಿಶಿಷ್ಟ ಉಷ್ಣ"},"summary":{"en":"Drop a hot metal block into cold water, read the final temperature, and work out the specific heat capacity of the metal.","hi":"गरम धातु का टुकड़ा ठंडे पानी में डालें, अंतिम तापमान पढ़ें और धातु की विशिष्ट ऊष्मा धारिता निकालें।","kn":"ಬಿಸಿ ಲೋಹದ ತುಂಡನ್ನು ತಣ್ಣೀರಿಗೆ ಹಾಕಿ, ಅಂತಿಮ ತಾಪ ಓದಿ, ಲೋಹದ ವಿಶಿಷ್ಟ ಉಷ್ಣ ಧಾರಕತೆಯನ್ನು ಲೆಕ್ಕಹಾಕಿ."},"aim":{"en":"To find the specific heat capacity of a metal by the method of mixtures.","hi":"मिश्रण विधि से किसी धातु की विशिष्ट ऊष्मा धारिता ज्ञात करना।","kn":"ಮಿಶ್ರಣ ವಿಧಾನದಿಂದ ಒಂದು ಲೋಹದ ವಿಶಿಷ್ಟ ಉಷ್ಣ ಧಾರಕತೆಯನ್ನು ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"When a hot body and a cold body are mixed and no heat escapes, the heat lost by the hot body equals the heat gained by the cold body, until both reach the same final temperature. Heat = mass × specific heat capacity × change in temperature. With the metal (mass m, heated to 100 °C) and the water (mass M, specific heat 4.2 J/g °C, starting at t °C) reaching θ °C: m × c × (100 − θ) = M × 4.2 × (θ − t), so c = M × 4.2 × (θ − t) ÷ (m × (100 − θ)).","hi":"जब गरम और ठंडी वस्तु मिलाई जाती हैं और कोई ऊष्मा बाहर नहीं जाती, तो गरम वस्तु द्वारा दी गई ऊष्मा ठंडी वस्तु द्वारा ली गई ऊष्मा के बराबर होती है, जब तक दोनों एक ही अंतिम तापमान पर न पहुँच जाएँ। ऊष्मा = द्रव्यमान × विशिष्ट ऊष्मा धारिता × तापमान में परिवर्तन। धातु (द्रव्यमान m, 100 °C तक गरम) और पानी (द्रव्यमान M, विशिष्ट ऊष्मा 4.2 J/g °C, आरंभ t °C) के θ °C पर पहुँचने पर: m × c × (100 − θ) = M × 4.2 × (θ − t), अतः c = M × 4.2 × (θ − t) ÷ (m × (100 − θ))।","kn":"ಬಿಸಿ ಮತ್ತು ತಣ್ಣನೆಯ ವಸ್ತುಗಳನ್ನು ಬೆರೆಸಿ ಉಷ್ಣ ಹೊರಹೋಗದಿದ್ದಾಗ, ಎರಡೂ ಒಂದೇ ಅಂತಿಮ ತಾಪ ತಲುಪುವವರೆಗೆ ಬಿಸಿ ವಸ್ತು ಕಳೆದುಕೊಂಡ ಉಷ್ಣ ತಣ್ಣನೆಯ ವಸ್ತು ಪಡೆದ ಉಷ್ಣಕ್ಕೆ ಸಮ. ಉಷ್ಣ = ದ್ರವ್ಯರಾಶಿ × ವಿಶಿಷ್ಟ ಉಷ್ಣ ಧಾರಕತೆ × ತಾಪ ಬದಲಾವಣೆ. ಲೋಹ (ದ್ರವ್ಯರಾಶಿ m, 100 °C ವರೆಗೆ ಕಾಯಿಸಿದ್ದು) ಮತ್ತು ನೀರು (ದ್ರವ್ಯರಾಶಿ M, ವಿಶಿಷ್ಟ ಉಷ್ಣ 4.2 J/g °C, ಆರಂಭ t °C) θ °C ತಲುಪಿದಾಗ: m × c × (100 − θ) = M × 4.2 × (θ − t); ಆದ್ದರಿಂದ c = M × 4.2 × (θ − t) ÷ (m × (100 − θ))."},"apparatus":[{"en":"Blocks of copper, aluminium and iron with a thread","hi":"धागे सहित ताँबे, ऐलुमिनियम और लोहे के टुकड़े","kn":"ದಾರ ಸಹಿತ ತಾಮ್ರ, ಅಲ್ಯೂಮಿನಿಯಂ ಮತ್ತು ಕಬ್ಬಿಣದ ತುಂಡುಗಳು"},{"en":"A beaker of boiling water on a burner","hi":"बर्नर पर उबलते पानी का बीकर","kn":"ಬರ್ನರ್ ಮೇಲೆ ಕುದಿಯುವ ನೀರಿನ ಬೀಕರ್"},{"en":"A calorimeter with a lid and stirrer, in an insulating jacket","hi":"ढक्कन और विलोडक सहित ऊष्मारोधी आवरण में कैलोरीमीटर","kn":"ಮುಚ್ಚಳ ಮತ್ತು ಕಲಕುವ ಕಡ್ಡಿ ಸಹಿತ ನಿರೋಧಕ ಹೊದಿಕೆಯಲ್ಲಿ ಕ್ಯಾಲೊರಿಮೀಟರ್"},{"en":"A thermometer (0–110 °C) and a balance","hi":"तापमापी (0–110 °C) और तुला","kn":"ಉಷ್ಣಮಾಪಕ (0–110 °C) ಮತ್ತು ತಕ್ಕಡಿ"}],"steps":[{"en":"Weigh the metal block, then hang it in boiling water for a few minutes so it reaches 100 °C.","hi":"धातु के टुकड़े को तौलें, फिर उसे कुछ मिनट उबलते पानी में लटकाएँ ताकि वह 100 °C पर पहुँच जाए।","kn":"ಲೋಹದ ತುಂಡನ್ನು ತೂಗಿ, ನಂತರ 100 °C ತಲುಪಲು ಕೆಲವು ನಿಮಿಷ ಕುದಿಯುವ ನೀರಿನಲ್ಲಿ ತೂಗಿಸಿ."},{"en":"Pour a weighed amount of cold water into the calorimeter and read its temperature.","hi":"कैलोरीमीटर में तौला हुआ ठंडा पानी डालें और उसका तापमान पढ़ें।","kn":"ಕ್ಯಾಲೊರಿಮೀಟರ್‌ಗೆ ತೂಗಿದ ತಣ್ಣೀರು ಹಾಕಿ ಅದರ ತಾಪ ಓದಿ."},{"en":"Move the hot block quickly into the water, close the lid and stir gently.","hi":"गरम टुकड़े को जल्दी से पानी में डालें, ढक्कन बंद करें और धीरे-धीरे हिलाएँ।","kn":"ಬಿಸಿ ತುಂಡನ್ನು ಬೇಗನೆ ನೀರಿಗೆ ಹಾಕಿ, ಮುಚ್ಚಳ ಮುಚ್ಚಿ ನಿಧಾನವಾಗಿ ಕಲಕಿ."},{"en":"Watch the thermometer and note the highest steady temperature reached.","hi":"तापमापी देखते रहें और पहुँचा हुआ सबसे अधिक स्थिर तापमान लिखें।","kn":"ಉಷ್ಣಮಾಪಕ ಗಮನಿಸಿ, ತಲುಪಿದ ಅತಿ ಹೆಚ್ಚಿನ ಸ್ಥಿರ ತಾಪವನ್ನು ಬರೆಯಿರಿ."},{"en":"Work out the specific heat capacity of the metal from heat lost = heat gained.","hi":"दी गई ऊष्मा = ली गई ऊष्मा से धातु की विशिष्ट ऊष्मा धारिता निकालें।","kn":"ಕಳೆದ ಉಷ್ಣ = ಪಡೆದ ಉಷ್ಣದಿಂದ ಲೋಹದ ವಿಶಿಷ್ಟ ಉಷ್ಣ ಧಾರಕತೆ ಲೆಕ್ಕಹಾಕಿ."},{"en":"Repeat with other masses of water and with the other metals.","hi":"पानी के अन्य द्रव्यमानों और अन्य धातुओं के साथ दोहराएँ।","kn":"ಬೇರೆ ನೀರಿನ ದ್ರವ್ಯರಾಶಿ ಮತ್ತು ಬೇರೆ ಲೋಹಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Transfer the hot block quickly, without splashing water, so little heat is lost.","hi":"गरम टुकड़े को बिना पानी छलकाए जल्दी डालें, ताकि कम ऊष्मा नष्ट हो।","kn":"ಉಷ್ಣ ಕಡಿಮೆ ನಷ್ಟವಾಗಲು ಬಿಸಿ ತುಂಡನ್ನು ನೀರು ಚಿಮ್ಮದೆ ಬೇಗನೆ ಹಾಕಿ."},{"en":"Handle the hot block by its thread and keep your hands away from the boiling water.","hi":"गरम टुकड़े को धागे से पकड़ें और हाथ उबलते पानी से दूर रखें।","kn":"ಬಿಸಿ ತುಂಡನ್ನು ದಾರದಿಂದ ಹಿಡಿಯಿರಿ; ಕೈಗಳನ್ನು ಕುದಿಯುವ ನೀರಿನಿಂದ ದೂರವಿಡಿ."},{"en":"Stir gently and read the thermometer at eye level.","hi":"धीरे हिलाएँ और तापमापी आँख के स्तर पर पढ़ें।","kn":"ನಿಧಾನವಾಗಿ ಕಲಕಿ, ಉಷ್ಣಮಾಪಕವನ್ನು ಕಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ಓದಿ."}],"conclusion":{"en":"Heat lost by the metal equals heat gained by the water. The specific heat capacity worked out is about 0.39 J/g °C for copper, 0.45 J/g °C for iron and 0.90 J/g °C for aluminium — all much smaller than water's 4.2 J/g °C, which is why water is used to store and carry heat.","hi":"धातु द्वारा दी गई ऊष्मा पानी द्वारा ली गई ऊष्मा के बराबर है। निकाली गई विशिष्ट ऊष्मा धारिता ताँबे के लिए लगभग 0.39 J/g °C, लोहे के लिए 0.45 J/g °C और ऐलुमिनियम के लिए 0.90 J/g °C है — सभी पानी के 4.2 J/g °C से बहुत कम, इसीलिए पानी का उपयोग ऊष्मा संचित करने और ले जाने में होता है।","kn":"ಲೋಹ ಕಳೆದುಕೊಂಡ ಉಷ್ಣ ನೀರು ಪಡೆದ ಉಷ್ಣಕ್ಕೆ ಸಮ. ಲೆಕ್ಕಹಾಕಿದ ವಿಶಿಷ್ಟ ಉಷ್ಣ ಧಾರಕತೆ ತಾಮ್ರಕ್ಕೆ ಸುಮಾರು 0.39 J/g °C, ಕಬ್ಬಿಣಕ್ಕೆ 0.45 J/g °C, ಅಲ್ಯೂಮಿನಿಯಂಗೆ 0.90 J/g °C — ಎಲ್ಲವೂ ನೀರಿನ 4.2 J/g °C ಗಿಂತ ಬಹಳ ಕಡಿಮೆ; ಅದಕ್ಕೇ ಉಷ್ಣವನ್ನು ಸಂಗ್ರಹಿಸಲು ಮತ್ತು ಸಾಗಿಸಲು ನೀರನ್ನು ಬಳಸುತ್ತಾರೆ."},"viva":[{"q":{"en":"What is the specific heat capacity of a substance?","hi":"किसी पदार्थ की विशिष्ट ऊष्मा धारिता क्या है?","kn":"ಒಂದು ವಸ್ತುವಿನ ವಿಶಿಷ್ಟ ಉಷ್ಣ ಧಾರಕತೆ ಎಂದರೇನು?"},"a":{"en":"The heat needed to raise the temperature of 1 g (or 1 kg) of it by 1 °C.","hi":"उसके 1 ग्रा (या 1 किग्रा) का तापमान 1 °C बढ़ाने के लिए आवश्यक ऊष्मा।","kn":"ಅದರ 1 ಗ್ರಾಂ (ಅಥವಾ 1 ಕಿ.ಗ್ರಾಂ) ತಾಪವನ್ನು 1 °C ಹೆಚ್ಚಿಸಲು ಬೇಕಾದ ಉಷ್ಣ."}},{"q":{"en":"State the principle of the method of mixtures.","hi":"मिश्रण विधि का सिद्धांत बताइए।","kn":"ಮಿಶ್ರಣ ವಿಧಾನದ ತತ್ವ ತಿಳಿಸಿ."},"a":{"en":"Heat lost by the hot body = heat gained by the cold body, if no heat escapes.","hi":"यदि कोई ऊष्मा बाहर न जाए, तो गरम वस्तु द्वारा दी गई ऊष्मा = ठंडी वस्तु द्वारा ली गई ऊष्मा।","kn":"ಉಷ್ಣ ಹೊರಹೋಗದಿದ್ದರೆ, ಬಿಸಿ ವಸ್ತು ಕಳೆದ ಉಷ್ಣ = ತಣ್ಣನೆಯ ವಸ್ತು ಪಡೆದ ಉಷ್ಣ."}},{"q":{"en":"Why is the calorimeter kept in an insulating jacket?","hi":"कैलोरीमीटर को ऊष्मारोधी आवरण में क्यों रखा जाता है?","kn":"ಕ್ಯಾಲೊರಿಮೀಟರನ್ನು ನಿರೋಧಕ ಹೊದಿಕೆಯಲ್ಲಿ ಏಕೆ ಇಡುತ್ತಾರೆ?"},"a":{"en":"To stop heat escaping to or entering from the surroundings.","hi":"ताकि ऊष्मा परिवेश में न जाए और परिवेश से न आए।","kn":"ಸುತ್ತಮುತ್ತಲಿಗೆ ಉಷ್ಣ ಹೋಗದಂತೆ ಮತ್ತು ಅಲ್ಲಿಂದ ಬಾರದಂತೆ ತಡೆಯಲು."}},{"q":{"en":"Why is water used in hot-water bottles and car radiators?","hi":"गरम पानी की थैलियों और कार के रेडिएटर में पानी क्यों उपयोग होता है?","kn":"ಬಿಸಿನೀರಿನ ಚೀಲ ಮತ್ತು ಕಾರಿನ ರೇಡಿಯೇಟರ್‌ಗಳಲ್ಲಿ ನೀರನ್ನು ಏಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"Its specific heat capacity is high, so it holds and carries a lot of heat for a small change in temperature.","hi":"इसकी विशिष्ट ऊष्मा धारिता अधिक है, इसलिए तापमान में थोड़े परिवर्तन पर यह बहुत ऊष्मा रखता और ले जाता है।","kn":"ಅದರ ವಿಶಿಷ್ಟ ಉಷ್ಣ ಧಾರಕತೆ ಹೆಚ್ಚು; ಸ್ವಲ್ಪ ತಾಪ ಬದಲಾವಣೆಗೆ ಬಹಳ ಉಷ್ಣ ಹಿಡಿದು ಸಾಗಿಸುತ್ತದೆ."}},{"q":{"en":"100 g of a metal at 100 °C raises 100 g of water from 20 °C to 27 °C. Find its specific heat.","hi":"100 °C पर 100 ग्रा धातु 100 ग्रा पानी को 20 °C से 27 °C तक गरम करती है। उसकी विशिष्ट ऊष्मा ज्ञात कीजिए।","kn":"100 °C ನಲ್ಲಿರುವ 100 ಗ್ರಾಂ ಲೋಹ 100 ಗ್ರಾಂ ನೀರನ್ನು 20 °C ನಿಂದ 27 °C ಗೆ ಏರಿಸುತ್ತದೆ. ಅದರ ವಿಶಿಷ್ಟ ಉಷ್ಣ ಕಂಡುಹಿಡಿಯಿರಿ."},"a":{"en":"c = 100 × 4.2 × 7 ÷ (100 × 73) ≈ 0.40 J/g °C (close to copper).","hi":"c = 100 × 4.2 × 7 ÷ (100 × 73) ≈ 0.40 J/g °C (ताँबे के निकट)।","kn":"c = 100 × 4.2 × 7 ÷ (100 × 73) ≈ 0.40 J/g °C (ತಾಮ್ರಕ್ಕೆ ಹತ್ತಿರ)."}}]},{"id":"sonometer","bench":"sonometer","setup":{},"subject":"Physics","domain":"physics","levels":["8","9","11"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["sound","sound waves","propagation of sound waves","pitch","frequency of sound","vibration","vibrations","sonometer","natural vibrations","resonance","musical instruments","loudness"],"title":{"en":"Pitch of a stretched string","hi":"तनी हुई डोरी का तारत्व","kn":"ಬಿಗಿದ ತಂತಿಯ ಸ್ವರಮಟ್ಟ"},"summary":{"en":"Pluck the wire of a sonometer and see how the frequency (pitch) changes with the length, the tension and the thickness of the wire.","hi":"सोनोमीटर का तार छेड़ें और देखें कि आवृत्ति (तारत्व) तार की लंबाई, तनाव और मोटाई के साथ कैसे बदलती है।","kn":"ಸೊನೊಮೀಟರ್ ತಂತಿಯನ್ನು ಮೀಟಿ, ತಂತಿಯ ಉದ್ದ, ಸೆಳೆತ ಮತ್ತು ದಪ್ಪದೊಂದಿಗೆ ಆವೃತ್ತಿ (ಸ್ವರಮಟ್ಟ) ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ನೋಡಿ."},"aim":{"en":"To study how the frequency of a vibrating string depends on its length, tension and thickness.","hi":"यह अध्ययन करना कि कंपित डोरी की आवृत्ति उसकी लंबाई, तनाव और मोटाई पर कैसे निर्भर करती है।","kn":"ಕಂಪಿಸುವ ತಂತಿಯ ಆವೃತ್ತಿ ಅದರ ಉದ್ದ, ಸೆಳೆತ ಮತ್ತು ದಪ್ಪದ ಮೇಲೆ ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ ಎಂದು ಅಧ್ಯಯನ ಮಾಡುವುದು."},"principle":{"en":"Sound is made by vibrating objects. A plucked string vibrates, and the number of vibrations per second is its frequency, heard as pitch. A shorter string vibrates faster and gives a higher note: frequency × length stays the same (f is inversely proportional to L). Pulling the string tighter raises the pitch (f grows as the square root of the tension), and a thicker, heavier wire gives a lower pitch. Sitar and guitar players use all three.","hi":"ध्वनि कंपित वस्तुओं से उत्पन्न होती है। छेड़ी गई डोरी कंपन करती है, और प्रति सेकंड कंपनों की संख्या उसकी आवृत्ति है, जिसे तारत्व के रूप में सुनते हैं। छोटी डोरी तेज़ी से कंपन करती है और ऊँचा स्वर देती है: आवृत्ति × लंबाई समान रहती है (f, L के व्युत्क्रमानुपाती है)। डोरी को अधिक कसने से तारत्व बढ़ता है (f तनाव के वर्गमूल के अनुसार बढ़ता है), और मोटा, भारी तार नीचा तारत्व देता है। सितार और गिटार बजाने वाले तीनों का उपयोग करते हैं।","kn":"ಕಂಪಿಸುವ ವಸ್ತುಗಳಿಂದ ಶಬ್ದ ಉಂಟಾಗುತ್ತದೆ. ಮೀಟಿದ ತಂತಿ ಕಂಪಿಸುತ್ತದೆ; ಸೆಕೆಂಡಿಗೆ ಕಂಪನಗಳ ಸಂಖ್ಯೆಯೇ ಅದರ ಆವೃತ್ತಿ, ಅದನ್ನು ಸ್ವರಮಟ್ಟವಾಗಿ ಕೇಳುತ್ತೇವೆ. ಚಿಕ್ಕ ತಂತಿ ವೇಗವಾಗಿ ಕಂಪಿಸಿ ಎತ್ತರದ ಸ್ವರ ನೀಡುತ್ತದೆ: ಆವೃತ್ತಿ × ಉದ್ದ ಸ್ಥಿರ (f, L ಗೆ ವಿಲೋಮಾನುಪಾತ). ತಂತಿಯನ್ನು ಹೆಚ್ಚು ಬಿಗಿದರೆ ಸ್ವರಮಟ್ಟ ಏರುತ್ತದೆ (f ಸೆಳೆತದ ವರ್ಗಮೂಲದಂತೆ ಹೆಚ್ಚುತ್ತದೆ); ದಪ್ಪ, ಭಾರವಾದ ತಂತಿ ತಗ್ಗಿದ ಸ್ವರ ನೀಡುತ್ತದೆ. ಸಿತಾರ್ ಮತ್ತು ಗಿಟಾರ್ ವಾದಕರು ಮೂರನ್ನೂ ಬಳಸುತ್ತಾರೆ."},"apparatus":[{"en":"A sonometer: a hollow box with a wire stretched over two movable bridges","hi":"सोनोमीटर: खोखला बक्सा जिस पर दो खिसकने वाले सेतुओं पर तार तना है","kn":"ಸೊನೊಮೀಟರ್: ಎರಡು ಸರಿಸಬಹುದಾದ ಸೇತುವೆಗಳ ಮೇಲೆ ತಂತಿ ಬಿಗಿದ ಟೊಳ್ಳು ಪೆಟ್ಟಿಗೆ"},{"en":"A hanger with slotted weights to pull the wire tight","hi":"तार को कसने के लिए स्लॉटेड भार सहित हैंगर","kn":"ತಂತಿಯನ್ನು ಬಿಗಿಯಲು ತೂಕಗಳ ಸಹಿತ ಹ್ಯಾಂಗರ್"},{"en":"Two wires of different thickness","hi":"भिन्न मोटाई के दो तार","kn":"ಬೇರೆ ಬೇರೆ ದಪ್ಪದ ಎರಡು ತಂತಿಗಳು"},{"en":"A metre scale (and tuning forks or a tuner app to match notes)","hi":"मीटर पैमाना (और स्वर मिलाने के लिए स्वरित्र या ट्यूनर ऐप)","kn":"ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ (ಮತ್ತು ಸ್ವರ ಹೊಂದಿಸಲು ಶ್ರುತಿಕವೆ ಅಥವಾ ಟ್ಯೂನರ್ ಆ್ಯಪ್)"}],"steps":[{"en":"Hang a weight from the wire and set the bridges a known length apart.","hi":"तार से भार लटकाएँ और सेतुओं को ज्ञात दूरी पर रखें।","kn":"ತಂತಿಗೆ ತೂಕ ತೂಗಿಸಿ, ಸೇತುವೆಗಳನ್ನು ತಿಳಿದ ದೂರದಲ್ಲಿಡಿ."},{"en":"Pluck the wire in the middle and listen to the note; find its frequency.","hi":"तार को बीच में छेड़ें और स्वर सुनें; उसकी आवृत्ति ज्ञात करें।","kn":"ತಂತಿಯನ್ನು ಮಧ್ಯದಲ್ಲಿ ಮೀಟಿ ಸ್ವರ ಕೇಳಿ; ಅದರ ಆವೃತ್ತಿ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Move the bridges closer and pluck again. Record length and frequency.","hi":"सेतुओं को पास लाएँ और फिर छेड़ें। लंबाई और आवृत्ति लिखें।","kn":"ಸೇತುವೆಗಳನ್ನು ಹತ್ತಿರ ತಂದು ಮತ್ತೆ ಮೀಟಿ. ಉದ್ದ ಮತ್ತು ಆವೃತ್ತಿ ದಾಖಲಿಸಿ."},{"en":"Keep the length fixed and add weights; note how the pitch changes.","hi":"लंबाई स्थिर रखकर भार बढ़ाएँ; देखें कि तारत्व कैसे बदलता है।","kn":"ಉದ್ದ ಸ್ಥಿರವಾಗಿಟ್ಟು ತೂಕ ಹೆಚ್ಚಿಸಿ; ಸ್ವರಮಟ್ಟ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ಗಮನಿಸಿ."},{"en":"Change to the thicker wire and compare.","hi":"मोटे तार पर बदलें और तुलना करें।","kn":"ದಪ್ಪ ತಂತಿಗೆ ಬದಲಿಸಿ ಹೋಲಿಸಿ."},{"en":"Work out frequency × length for each reading with the same wire and tension.","hi":"एक ही तार और तनाव वाली हर रीडिंग के लिए आवृत्ति × लंबाई निकालें।","kn":"ಒಂದೇ ತಂತಿ ಮತ್ತು ಸೆಳೆತದ ಪ್ರತಿ ಅಳತೆಗೆ ಆವೃತ್ತಿ × ಉದ್ದ ಲೆಕ್ಕಹಾಕಿ."}],"precautions":[{"en":"Pluck gently in the middle of the vibrating length.","hi":"कंपन वाली लंबाई के बीच में धीरे से छेड़ें।","kn":"ಕಂಪಿಸುವ ಉದ್ದದ ಮಧ್ಯದಲ್ಲಿ ನಿಧಾನವಾಗಿ ಮೀಟಿ."},{"en":"Add weights slowly: too much tension can snap the wire.","hi":"भार धीरे-धीरे बढ़ाएँ: अधिक तनाव से तार टूट सकता है।","kn":"ತೂಕಗಳನ್ನು ನಿಧಾನವಾಗಿ ಸೇರಿಸಿ: ಅತಿಯಾದ ಸೆಳೆತ ತಂತಿಯನ್ನು ತುಂಡರಿಸಬಹುದು."},{"en":"Measure the length between the edges of the bridges.","hi":"लंबाई सेतुओं के किनारों के बीच मापें।","kn":"ಉದ್ದವನ್ನು ಸೇತುವೆಗಳ ಅಂಚುಗಳ ನಡುವೆ ಅಳೆಯಿರಿ."}],"conclusion":{"en":"A shorter wire gives a higher pitch, and frequency × length stays nearly the same, so the frequency is inversely proportional to the length. More tension raises the pitch, and a thicker wire lowers it.","hi":"छोटा तार ऊँचा तारत्व देता है, और आवृत्ति × लंबाई लगभग समान रहती है, अतः आवृत्ति लंबाई के व्युत्क्रमानुपाती है। अधिक तनाव तारत्व बढ़ाता है, और मोटा तार उसे घटाता है।","kn":"ಚಿಕ್ಕ ತಂತಿ ಎತ್ತರದ ಸ್ವರ ನೀಡುತ್ತದೆ; ಆವೃತ್ತಿ × ಉದ್ದ ಬಹುತೇಕ ಸ್ಥಿರ, ಆದ್ದರಿಂದ ಆವೃತ್ತಿ ಉದ್ದಕ್ಕೆ ವಿಲೋಮಾನುಪಾತ. ಹೆಚ್ಚು ಸೆಳೆತ ಸ್ವರಮಟ್ಟ ಏರಿಸುತ್ತದೆ; ದಪ್ಪ ತಂತಿ ಇಳಿಸುತ್ತದೆ."},"viva":[{"q":{"en":"What is frequency? What is its unit?","hi":"आवृत्ति क्या है? इसका मात्रक क्या है?","kn":"ಆವೃತ್ತಿ ಎಂದರೇನು? ಅದರ ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"The number of vibrations per second; hertz (Hz).","hi":"प्रति सेकंड कंपनों की संख्या; हर्ट्ज़ (Hz)।","kn":"ಸೆಕೆಂಡಿಗೆ ಕಂಪನಗಳ ಸಂಖ್ಯೆ; ಹರ್ಟ್ಜ್ (Hz)."}},{"q":{"en":"How is pitch related to frequency?","hi":"तारत्व आवृत्ति से कैसे संबंधित है?","kn":"ಸ್ವರಮಟ್ಟ ಆವೃತ್ತಿಗೆ ಹೇಗೆ ಸಂಬಂಧಿಸಿದೆ?"},"a":{"en":"Higher frequency sounds higher in pitch (shriller).","hi":"अधिक आवृत्ति का तारत्व ऊँचा (तीक्ष्ण) सुनाई देता है।","kn":"ಹೆಚ್ಚಿನ ಆವೃತ್ತಿ ಎತ್ತರದ (ತೀಕ್ಷ್ಣ) ಸ್ವರವಾಗಿ ಕೇಳುತ್ತದೆ."}},{"q":{"en":"Why does a sitar player press the string against the frets?","hi":"सितार वादक डोरी को परदों पर क्यों दबाता है?","kn":"ಸಿತಾರ್ ವಾದಕ ತಂತಿಯನ್ನು ಮೆಟ್ಟಿಲುಗಳಿಗೆ ಏಕೆ ಒತ್ತುತ್ತಾನೆ?"},"a":{"en":"To shorten the vibrating length, which raises the pitch.","hi":"कंपन वाली लंबाई घटाने के लिए, जिससे तारत्व बढ़ता है।","kn":"ಕಂಪಿಸುವ ಉದ್ದ ಕಡಿಮೆಮಾಡಲು; ಅದರಿಂದ ಸ್ವರಮಟ್ಟ ಏರುತ್ತದೆ."}},{"q":{"en":"Why is the sonometer box hollow?","hi":"सोनोमीटर का बक्सा खोखला क्यों होता है?","kn":"ಸೊನೊಮೀಟರ್ ಪೆಟ್ಟಿಗೆ ಏಕೆ ಟೊಳ್ಳು?"},"a":{"en":"The air inside vibrates with the wire and makes the sound louder.","hi":"भीतर की हवा तार के साथ कंपन करती है और ध्वनि को तेज़ करती है।","kn":"ಒಳಗಿನ ಗಾಳಿ ತಂತಿಯೊಂದಿಗೆ ಕಂಪಿಸಿ ಶಬ್ದವನ್ನು ಜೋರಾಗಿಸುತ್ತದೆ."}},{"q":{"en":"A 60 cm string gives 200 Hz. What does a 30 cm length of it give, at the same tension?","hi":"60 सेमी की डोरी 200 Hz देती है। उसी तनाव पर उसकी 30 सेमी लंबाई कितनी आवृत्ति देगी?","kn":"60 ಸೆಂ.ಮೀ. ತಂತಿ 200 Hz ನೀಡುತ್ತದೆ. ಅದೇ ಸೆಳೆತದಲ್ಲಿ ಅದರ 30 ಸೆಂ.ಮೀ. ಉದ್ದ ಎಷ್ಟು ನೀಡುತ್ತದೆ?"},"a":{"en":"400 Hz: half the length, double the frequency.","hi":"400 Hz: आधी लंबाई, दुगुनी आवृत्ति।","kn":"400 Hz: ಅರ್ಧ ಉದ್ದ, ದ್ವಿಗುಣ ಆವೃತ್ತಿ."}}]},{"id":"transpiration","bench":"transpiration","setup":{},"subject":"Biology","domain":"biology","levels":["7","10","11"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["transpiration","transport in plants","water transport","potometer","xylem","stomata and transpiration","water in plants"],"title":{"en":"How fast does a shoot lose water?","hi":"टहनी कितनी तेज़ी से पानी खोती है?","kn":"ಕೊಂಬೆ ಎಷ್ಟು ವೇಗವಾಗಿ ನೀರು ಕಳೆದುಕೊಳ್ಳುತ್ತದೆ?"},"summary":{"en":"Use a potometer: watch an air bubble move along a tube as a leafy shoot takes up water, in still air, wind, dark and damp air.","hi":"पोटोमीटर का उपयोग करें: पत्तेदार टहनी के पानी लेने पर नली में हवा के बुलबुले को खिसकते देखें, शांत हवा, तेज़ हवा, अँधेरे और नम हवा में।","kn":"ಪೊಟೊಮೀಟರ್ ಬಳಸಿ: ಎಲೆಗಳ ಕೊಂಬೆ ನೀರು ಹೀರುವಾಗ ನಳಿಕೆಯಲ್ಲಿ ಗಾಳಿಯ ಗುಳ್ಳೆ ಸರಿಯುವುದನ್ನು ಶಾಂತ ಗಾಳಿ, ಗಾಳಿ, ಕತ್ತಲೆ ಮತ್ತು ತೇವ ಗಾಳಿಯಲ್ಲಿ ನೋಡಿ."},"aim":{"en":"To compare the rate of transpiration of a leafy shoot under different conditions using a potometer.","hi":"पोटोमीटर की सहायता से विभिन्न परिस्थितियों में पत्तेदार टहनी की वाष्पोत्सर्जन दर की तुलना करना।","kn":"ಪೊಟೊಮೀಟರ್ ಬಳಸಿ ಬೇರೆ ಬೇರೆ ಪರಿಸ್ಥಿತಿಗಳಲ್ಲಿ ಎಲೆಗಳ ಕೊಂಬೆಯ ಬಾಷ್ಪವಿಸರ್ಜನೆಯ ದರವನ್ನು ಹೋಲಿಸುವುದು."},"principle":{"en":"Plants lose water as vapour, mostly through the stomata of their leaves: this is transpiration. The water lost is replaced by water pulled up the xylem from the cut stem, so the rate of water uptake shows the rate of transpiration. A potometer turns it into movement of an air bubble along a narrow tube. Wind, light and warmth speed transpiration up (moving air carries vapour away; light opens the stomata); damp air and darkness slow it down. Fewer leaves mean less transpiration.","hi":"पौधे जल को वाष्प के रूप में, अधिकतर पत्तियों के रंध्रों से खोते हैं: यह वाष्पोत्सर्जन है। खोया हुआ पानी कटे तने से जाइलम द्वारा ऊपर खींचे गए पानी से पूरा होता है, इसलिए पानी लेने की दर वाष्पोत्सर्जन की दर बताती है। पोटोमीटर इसे पतली नली में हवा के बुलबुले की गति में बदल देता है। हवा, प्रकाश और गर्मी वाष्पोत्सर्जन तेज़ करते हैं (चलती हवा वाष्प को दूर ले जाती है; प्रकाश रंध्र खोलता है); नम हवा और अँधेरा उसे धीमा करते हैं। कम पत्तियों का अर्थ है कम वाष्पोत्सर्जन।","kn":"ಸಸ್ಯಗಳು ನೀರನ್ನು ಆವಿಯಾಗಿ, ಹೆಚ್ಚಾಗಿ ಎಲೆಗಳ ಪತ್ರರಂಧ್ರಗಳ ಮೂಲಕ ಕಳೆದುಕೊಳ್ಳುತ್ತವೆ: ಇದೇ ಬಾಷ್ಪವಿಸರ್ಜನೆ. ಕಳೆದುಹೋದ ನೀರನ್ನು ಕತ್ತರಿಸಿದ ಕಾಂಡದಿಂದ ಕ್ಸೈಲಂ ಮೂಲಕ ಮೇಲೆಳೆದ ನೀರು ತುಂಬುತ್ತದೆ; ಆದ್ದರಿಂದ ನೀರು ಹೀರುವ ದರ ಬಾಷ್ಪವಿಸರ್ಜನೆಯ ದರವನ್ನು ತೋರಿಸುತ್ತದೆ. ಪೊಟೊಮೀಟರ್ ಇದನ್ನು ಕಿರಿದಾದ ನಳಿಕೆಯಲ್ಲಿ ಗಾಳಿಯ ಗುಳ್ಳೆಯ ಚಲನೆಯಾಗಿ ತೋರಿಸುತ್ತದೆ. ಗಾಳಿ, ಬೆಳಕು ಮತ್ತು ಬಿಸಿ ಬಾಷ್ಪವಿಸರ್ಜನೆಯನ್ನು ವೇಗಗೊಳಿಸುತ್ತವೆ (ಚಲಿಸುವ ಗಾಳಿ ಆವಿಯನ್ನು ಒಯ್ಯುತ್ತದೆ; ಬೆಳಕು ಪತ್ರರಂಧ್ರ ತೆರೆಯುತ್ತದೆ); ತೇವ ಗಾಳಿ ಮತ್ತು ಕತ್ತಲೆ ನಿಧಾನಗೊಳಿಸುತ್ತವೆ. ಕಡಿಮೆ ಎಲೆಗಳು ಎಂದರೆ ಕಡಿಮೆ ಬಾಷ್ಪವಿಸರ್ಜನೆ."},"apparatus":[{"en":"A potometer (a narrow glass tube with a scale, joined to the cut stem)","hi":"पोटोमीटर (पैमाने वाली पतली काँच की नली, कटे तने से जुड़ी)","kn":"ಪೊಟೊಮೀಟರ್ (ಕತ್ತರಿಸಿದ ಕಾಂಡಕ್ಕೆ ಜೋಡಿಸಿದ, ಅಳತೆಯಿರುವ ಕಿರಿದಾದ ಗಾಜಿನ ನಳಿಕೆ)"},{"en":"A freshly cut leafy shoot (cut under water)","hi":"ताज़ी कटी पत्तेदार टहनी (पानी के नीचे काटी गई)","kn":"ಹೊಸದಾಗಿ ಕತ್ತರಿಸಿದ ಎಲೆಗಳ ಕೊಂಬೆ (ನೀರಿನೊಳಗೆ ಕತ್ತರಿಸಿದ್ದು)"},{"en":"A table fan, a lamp, a clear plastic bag, a stopwatch","hi":"मेज़ का पंखा, लैम्प, पारदर्शी प्लास्टिक थैली, विराम घड़ी","kn":"ಮೇಜಿನ ಫ್ಯಾನ್, ದೀಪ, ಪಾರದರ್ಶಕ ಪ್ಲಾಸ್ಟಿಕ್ ಚೀಲ, ನಿಲುಗಡಿಯಾರ"},{"en":"Vaseline to seal the joints","hi":"जोड़ों को बंद करने के लिए वैसलीन","kn":"ಜೋಡಣೆಗಳನ್ನು ಮುಚ್ಚಲು ವ್ಯಾಸಲಿನ್"}],"steps":[{"en":"Cut the shoot under water and fit it into the potometer without letting air in; seal the joint.","hi":"टहनी को पानी के नीचे काटें और बिना हवा घुसे पोटोमीटर में लगाएँ; जोड़ बंद करें।","kn":"ಕೊಂಬೆಯನ್ನು ನೀರಿನೊಳಗೆ ಕತ್ತರಿಸಿ, ಗಾಳಿ ಸೇರದಂತೆ ಪೊಟೊಮೀಟರ್‌ಗೆ ಅಳವಡಿಸಿ; ಜೋಡಣೆ ಮುಚ್ಚಿ."},{"en":"Let one air bubble into the end of the tube.","hi":"नली के सिरे में एक हवा का बुलबुला आने दें।","kn":"ನಳಿಕೆಯ ತುದಿಗೆ ಒಂದು ಗಾಳಿಯ ಗುಳ್ಳೆ ಬರಲಿ."},{"en":"In still air and normal light, note how far the bubble moves in 5 minutes.","hi":"शांत हवा और सामान्य प्रकाश में देखें कि बुलबुला 5 मिनट में कितना खिसकता है।","kn":"ಶಾಂತ ಗಾಳಿ ಮತ್ತು ಸಾಮಾನ್ಯ ಬೆಳಕಿನಲ್ಲಿ ಗುಳ್ಳೆ 5 ನಿಮಿಷದಲ್ಲಿ ಎಷ್ಟು ಸರಿಯುತ್ತದೆ ಗಮನಿಸಿ."},{"en":"Reset the bubble, then repeat with the fan on, in the dark, and with the shoot covered by a plastic bag.","hi":"बुलबुले को वापस लाएँ, फिर पंखा चलाकर, अँधेरे में, और टहनी को प्लास्टिक थैली से ढककर दोहराएँ।","kn":"ಗುಳ್ಳೆಯನ್ನು ಹಿಂದಕ್ಕೆ ತಂದು, ಫ್ಯಾನ್ ಹಾಕಿ, ಕತ್ತಲೆಯಲ್ಲಿ ಮತ್ತು ಕೊಂಬೆಯನ್ನು ಪ್ಲಾಸ್ಟಿಕ್ ಚೀಲದಿಂದ ಮುಚ್ಚಿ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Remove half the leaves and repeat in still air.","hi":"आधी पत्तियाँ हटाकर शांत हवा में दोहराएँ।","kn":"ಅರ್ಧ ಎಲೆಗಳನ್ನು ತೆಗೆದು ಶಾಂತ ಗಾಳಿಯಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Work out the rate (mm per minute) for each condition and compare.","hi":"हर परिस्थिति के लिए दर (मिमी प्रति मिनट) निकालें और तुलना करें।","kn":"ಪ್ರತಿ ಪರಿಸ್ಥಿತಿಗೆ ದರ (ಮಿ.ಮೀ. ಪ್ರತಿ ನಿಮಿಷ) ಲೆಕ್ಕಹಾಕಿ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Cut the stem under water so no air enters the xylem.","hi":"तने को पानी के नीचे काटें ताकि जाइलम में हवा न जाए।","kn":"ಕ್ಸೈಲಂಗೆ ಗಾಳಿ ಸೇರದಂತೆ ಕಾಂಡವನ್ನು ನೀರಿನೊಳಗೆ ಕತ್ತರಿಸಿ."},{"en":"All joints must be airtight.","hi":"सभी जोड़ वायुरोधी होने चाहिए।","kn":"ಎಲ್ಲ ಜೋಡಣೆಗಳು ಗಾಳಿಬಿಗಿಯಾಗಿರಬೇಕು."},{"en":"Let the shoot settle for a few minutes in each new condition before timing.","hi":"हर नई परिस्थिति में समय मापने से पहले टहनी को कुछ मिनट स्थिर होने दें।","kn":"ಪ್ರತಿ ಹೊಸ ಪರಿಸ್ಥಿತಿಯಲ್ಲಿ ಸಮಯ ಅಳೆಯುವ ಮೊದಲು ಕೊಂಬೆ ಕೆಲವು ನಿಮಿಷ ಹೊಂದಿಕೊಳ್ಳಲಿ."}],"conclusion":{"en":"The bubble moves fastest with the fan on and slowest in the dark or inside the plastic bag. Wind and light increase transpiration; darkness and damp air reduce it; fewer leaves mean less water lost. The water taken up replaces the water lost through the leaves.","hi":"पंखा चलने पर बुलबुला सबसे तेज़ और अँधेरे में या प्लास्टिक थैली के भीतर सबसे धीमे खिसकता है। हवा और प्रकाश वाष्पोत्सर्जन बढ़ाते हैं; अँधेरा और नम हवा उसे घटाते हैं; कम पत्तियों से कम पानी खोता है। लिया गया पानी पत्तियों से खोए पानी की पूर्ति करता है।","kn":"ಫ್ಯಾನ್ ಹಾಕಿದಾಗ ಗುಳ್ಳೆ ಅತಿ ವೇಗವಾಗಿ, ಕತ್ತಲೆಯಲ್ಲಿ ಅಥವಾ ಪ್ಲಾಸ್ಟಿಕ್ ಚೀಲದೊಳಗೆ ಅತಿ ನಿಧಾನವಾಗಿ ಸರಿಯುತ್ತದೆ. ಗಾಳಿ ಮತ್ತು ಬೆಳಕು ಬಾಷ್ಪವಿಸರ್ಜನೆ ಹೆಚ್ಚಿಸುತ್ತವೆ; ಕತ್ತಲೆ ಮತ್ತು ತೇವ ಗಾಳಿ ಕಡಿಮೆಮಾಡುತ್ತವೆ; ಕಡಿಮೆ ಎಲೆಗಳು ಕಡಿಮೆ ನೀರು ಕಳೆಯುತ್ತವೆ. ಹೀರಿದ ನೀರು ಎಲೆಗಳ ಮೂಲಕ ಕಳೆದ ನೀರನ್ನು ತುಂಬುತ್ತದೆ."},"viva":[{"q":{"en":"What is transpiration?","hi":"वाष्पोत्सर्जन क्या है?","kn":"ಬಾಷ್ಪವಿಸರ್ಜನೆ ಎಂದರೇನು?"},"a":{"en":"The loss of water as vapour from the aerial parts of a plant, mostly through the stomata.","hi":"पौधे के वायवीय भागों से, अधिकतर रंध्रों द्वारा, जल का वाष्प के रूप में निकलना।","kn":"ಸಸ್ಯದ ವಾಯವ ಭಾಗಗಳಿಂದ, ಹೆಚ್ಚಾಗಿ ಪತ್ರರಂಧ್ರಗಳ ಮೂಲಕ, ನೀರು ಆವಿಯಾಗಿ ಹೊರಹೋಗುವುದು."}},{"q":{"en":"What does a potometer actually measure?","hi":"पोटोमीटर वास्तव में क्या मापता है?","kn":"ಪೊಟೊಮೀಟರ್ ನಿಜವಾಗಿ ಏನನ್ನು ಅಳೆಯುತ್ತದೆ?"},"a":{"en":"The rate of water uptake by the shoot, which is nearly equal to the rate of transpiration.","hi":"टहनी द्वारा पानी लेने की दर, जो लगभग वाष्पोत्सर्जन की दर के बराबर होती है।","kn":"ಕೊಂಬೆ ನೀರು ಹೀರುವ ದರ; ಅದು ಬಹುತೇಕ ಬಾಷ್ಪವಿಸರ್ಜನೆಯ ದರಕ್ಕೆ ಸಮ."}},{"q":{"en":"Why does transpiration slow down inside a plastic bag?","hi":"प्लास्टिक थैली के भीतर वाष्पोत्सर्जन धीमा क्यों होता है?","kn":"ಪ್ಲಾಸ್ಟಿಕ್ ಚೀಲದೊಳಗೆ ಬಾಷ್ಪವಿಸರ್ಜನೆ ಏಕೆ ನಿಧಾನವಾಗುತ್ತದೆ?"},"a":{"en":"The air in the bag becomes damp, so less water vapour leaves the leaves.","hi":"थैली की हवा नम हो जाती है, इसलिए पत्तियों से कम वाष्प निकलती है।","kn":"ಚೀಲದೊಳಗಿನ ಗಾಳಿ ತೇವವಾಗುತ್ತದೆ; ಎಲೆಗಳಿಂದ ಕಡಿಮೆ ಆವಿ ಹೊರಹೋಗುತ್ತದೆ."}},{"q":{"en":"Give two uses of transpiration to the plant.","hi":"पौधे के लिए वाष्पोत्सर्जन के दो लाभ बताइए।","kn":"ಸಸ್ಯಕ್ಕೆ ಬಾಷ್ಪವಿಸರ್ಜನೆಯ ಎರಡು ಉಪಯೋಗ ತಿಳಿಸಿ."},"a":{"en":"It pulls water and minerals up from the roots, and it cools the leaves.","hi":"यह जड़ों से पानी और खनिज ऊपर खींचता है, और पत्तियों को ठंडा करता है।","kn":"ಅದು ಬೇರುಗಳಿಂದ ನೀರು ಮತ್ತು ಖನಿಜಗಳನ್ನು ಮೇಲೆಳೆಯುತ್ತದೆ, ಮತ್ತು ಎಲೆಗಳನ್ನು ತಂಪಾಗಿಸುತ್ತದೆ."}},{"q":{"en":"Why is the shoot cut under water?","hi":"टहनी को पानी के नीचे क्यों काटा जाता है?","kn":"ಕೊಂಬೆಯನ್ನು ನೀರಿನೊಳಗೆ ಏಕೆ ಕತ್ತರಿಸುತ್ತಾರೆ?"},"a":{"en":"So that air does not enter the xylem and block the flow of water.","hi":"ताकि जाइलम में हवा न जाए और पानी का प्रवाह न रुके।","kn":"ಕ್ಸೈಲಂಗೆ ಗಾಳಿ ಸೇರಿ ನೀರಿನ ಹರಿವು ತಡೆಯದಂತೆ."}}]},{"id":"lab.ohms-law","bench":"sim","setup":{},"subject":"Physics","domain":"physics","levels":["10","12"],"mode":"explore","curricula":["cbse","ncert","ka-sslc"],"reviewed":false,"keywords":["electricity","ohm's law","series","parallel","equivalent resistance","circuit"],"title":{"en":"Ohm's law and resistances","hi":"ओम का नियम और प्रतिरोध","kn":"ಓಮ್‌ನ ನಿಯಮ ಮತ್ತು ರೋಧಗಳು"},"summary":{"en":"Build a circuit with one to three resistors in series or parallel and watch the V–I graph grow.","hi":"एक से तीन प्रतिरोधकों को श्रेणी या पार्श्व में जोड़कर परिपथ बनाएँ और V–I ग्राफ़ बनते देखें।","kn":"ಒಂದರಿಂದ ಮೂರು ರೋಧಕಗಳನ್ನು ಸರಣಿ ಅಥವಾ ಸಮಾಂತರದಲ್ಲಿ ಜೋಡಿಸಿ ಮಂಡಲ ರಚಿಸಿ, V–I ನಕ್ಷೆ ಬೆಳೆಯುವುದನ್ನು ನೋಡಿ."},"aim":{"en":"To explore how current depends on voltage, and how resistors combine in series and in parallel.","hi":"यह खोजना कि धारा वोल्टता पर कैसे निर्भर करती है, और प्रतिरोधक श्रेणी और पार्श्व में कैसे जुड़ते हैं।","kn":"ಪ್ರವಾಹವು ವೋಲ್ಟೇಜ್ ಮೇಲೆ ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ ಮತ್ತು ರೋಧಕಗಳು ಸರಣಿ ಹಾಗೂ ಸಮಾಂತರದಲ್ಲಿ ಹೇಗೆ ಸೇರುತ್ತವೆ ಎಂದು ಅನ್ವೇಷಿಸುವುದು."},"principle":{"en":"Ohm's law: V = IR. In series the resistances add (R = R₁ + R₂ + …); in parallel the reciprocals add (1/R = 1/R₁ + 1/R₂ + …), so the total is less than the smallest.","hi":"ओम का नियम: V = IR. श्रेणी में प्रतिरोध जुड़ते हैं (R = R₁ + R₂ + …); पार्श्व में उनके व्युत्क्रम जुड़ते हैं (1/R = 1/R₁ + 1/R₂ + …), इसलिए कुल प्रतिरोध सबसे छोटे से भी कम होता है।","kn":"ಓಮ್‌ನ ನಿಯಮ: V = IR. ಸರಣಿಯಲ್ಲಿ ರೋಧಗಳು ಕೂಡುತ್ತವೆ (R = R₁ + R₂ + …); ಸಮಾಂತರದಲ್ಲಿ ಅವುಗಳ ವಿಲೋಮಗಳು ಕೂಡುತ್ತವೆ (1/R = 1/R₁ + 1/R₂ + …), ಆದ್ದರಿಂದ ಒಟ್ಟು ರೋಧ ಅತಿ ಚಿಕ್ಕದಕ್ಕಿಂತಲೂ ಕಡಿಮೆ."},"apparatus":[{"en":"Battery with adjustable voltage","hi":"बदलने योग्य वोल्टता वाली बैटरी","kn":"ಬದಲಿಸಬಹುದಾದ ವೋಲ್ಟೇಜ್‌ನ ಬ್ಯಾಟರಿ"},{"en":"Up to three resistors","hi":"तीन तक प्रतिरोधक","kn":"ಮೂರುವರೆಗೆ ರೋಧಕಗಳು"},{"en":"Ammeter and voltmeter","hi":"ऐमीटर और वोल्टमीटर","kn":"ಅಮ್ಮೀಟರ್ ಮತ್ತು ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"Plug key and wires","hi":"प्लग कुंजी और तार","kn":"ಪ್ಲಗ್ ಕೀ ಮತ್ತು ತಂತಿಗಳು"}],"steps":[{"en":"Choose series or parallel and the number of resistors.","hi":"श्रेणी या पार्श्व और प्रतिरोधकों की संख्या चुनें।","kn":"ಸರಣಿ ಅಥವಾ ಸಮಾಂತರ ಮತ್ತು ರೋಧಕಗಳ ಸಂಖ್ಯೆ ಆರಿಸಿ."},{"en":"Set each resistance with its slider.","hi":"हर प्रतिरोध उसके स्लाइडर से तय करें।","kn":"ಪ್ರತಿ ರೋಧವನ್ನು ಅದರ ಸ್ಲೈಡರ್‌ನಿಂದ ಹೊಂದಿಸಿ."},{"en":"Raise the voltage step by step and watch the ammeter and the V–I graph.","hi":"वोल्टता धीरे-धीरे बढ़ाएँ और ऐमीटर तथा V–I ग्राफ़ देखें।","kn":"ವೋಲ್ಟೇಜ್ ಹಂತ ಹಂತವಾಗಿ ಹೆಚ್ಚಿಸಿ, ಅಮ್ಮೀಟರ್ ಮತ್ತು V–I ನಕ್ಷೆ ಗಮನಿಸಿ."},{"en":"Compare the equivalent resistance shown with your own calculation.","hi":"दिखाए गए तुल्य प्रतिरोध की तुलना अपनी गणना से करें।","kn":"ತೋರಿಸಿದ ಸಮಾನ ರೋಧವನ್ನು ನಿಮ್ಮ ಲೆಕ್ಕದೊಂದಿಗೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"In a real circuit, keep the key out between readings so the wires do not heat up.","hi":"असली परिपथ में पाठ्यांकों के बीच कुंजी निकाल दें ताकि तार गरम न हों।","kn":"ನಿಜವಾದ ಮಂಡಲದಲ್ಲಿ ತಂತಿಗಳು ಬಿಸಿಯಾಗದಂತೆ ಓದುಗಳ ನಡುವೆ ಕೀ ತೆಗೆಯಿರಿ."},{"en":"Connect the ammeter in series and the voltmeter in parallel.","hi":"ऐमीटर श्रेणी में और वोल्टमीटर पार्श्व में जोड़ें।","kn":"ಅಮ್ಮೀಟರ್ ಸರಣಿಯಲ್ಲಿ, ವೋಲ್ಟ್‌ಮೀಟರ್ ಸಮಾಂತರದಲ್ಲಿ ಜೋಡಿಸಿ."}],"conclusion":{"en":"The V–I graph is a straight line through the origin whose slope is the resistance. Series resistances add; parallel combinations give less than the smallest resistor.","hi":"V–I ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है जिसकी प्रवणता प्रतिरोध है। श्रेणी के प्रतिरोध जुड़ते हैं; पार्श्व संयोजन सबसे छोटे प्रतिरोधक से भी कम देता है।","kn":"V–I ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಹೋಗುವ ಸರಳರೇಖೆ; ಅದರ ಇಳಿಜಾರೇ ರೋಧ. ಸರಣಿ ರೋಧಗಳು ಕೂಡುತ್ತವೆ; ಸಮಾಂತರ ಜೋಡಣೆ ಅತಿ ಚಿಕ್ಕ ರೋಧಕಕ್ಕಿಂತಲೂ ಕಡಿಮೆ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"What is the equivalent of 6 Ω and 3 Ω in parallel?","hi":"6 Ω और 3 Ω पार्श्व में हों तो तुल्य प्रतिरोध क्या है?","kn":"6 Ω ಮತ್ತು 3 Ω ಸಮಾಂತರದಲ್ಲಿದ್ದರೆ ಸಮಾನ ರೋಧ ಎಷ್ಟು?"},"a":{"en":"2 Ω, because 1/R = 1/6 + 1/3 = 1/2.","hi":"2 Ω, क्योंकि 1/R = 1/6 + 1/3 = 1/2.","kn":"2 Ω, ಏಕೆಂದರೆ 1/R = 1/6 + 1/3 = 1/2."}},{"q":{"en":"Why are household appliances connected in parallel?","hi":"घरेलू उपकरण पार्श्व में क्यों जोड़े जाते हैं?","kn":"ಮನೆಯ ಉಪಕರಣಗಳನ್ನು ಸಮಾಂತರದಲ್ಲಿ ಏಕೆ ಜೋಡಿಸುತ್ತಾರೆ?"},"a":{"en":"Each gets the full mains voltage and can be switched on or off by itself.","hi":"हर उपकरण को पूरी वोल्टता मिलती है और उसे अलग से चालू या बंद किया जा सकता है।","kn":"ಪ್ರತಿಯೊಂದಕ್ಕೂ ಪೂರ್ಣ ವೋಲ್ಟೇಜ್ ಸಿಗುತ್ತದೆ ಮತ್ತು ಅದನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಆನ್/ಆಫ್ ಮಾಡಬಹುದು."}},{"q":{"en":"What does the slope of a V–I graph give?","hi":"V–I ग्राफ़ की प्रवणता क्या देती है?","kn":"V–I ನಕ್ಷೆಯ ಇಳಿಜಾರು ಏನನ್ನು ನೀಡುತ್ತದೆ?"},"a":{"en":"The resistance R.","hi":"प्रतिरोध R.","kn":"ರೋಧ R."}}]},{"id":"lab.lens-mirror","bench":"sim","setup":{},"subject":"Physics","domain":"physics","levels":["10","12"],"mode":"explore","curricula":["cbse","ncert","ka-sslc"],"reviewed":false,"keywords":["ray diagram","lens","mirror","image formation","magnification","mirror formula","lens formula"],"title":{"en":"Lens and mirror ray diagrams","hi":"लेंस और दर्पण के किरण आरेख","kn":"ಮಸೂರ ಮತ್ತು ದರ್ಪಣದ ಕಿರಣ ಚಿತ್ರಗಳು"},"summary":{"en":"Drag the object along the axis and watch the principal rays form the image.","hi":"वस्तु को अक्ष पर खिसकाएँ और देखें कि मुख्य किरणें प्रतिबिंब कैसे बनाती हैं।","kn":"ವಸ್ತುವನ್ನು ಅಕ್ಷದ ಮೇಲೆ ಎಳೆಯಿರಿ, ಮುಖ್ಯ ಕಿರಣಗಳು ಪ್ರತಿಬಿಂಬವನ್ನು ಹೇಗೆ ರೂಪಿಸುತ್ತವೆ ನೋಡಿ."},"aim":{"en":"To explore the position, nature and size of images formed by convex and concave lenses and mirrors.","hi":"उत्तल और अवतल लेंसों तथा दर्पणों से बने प्रतिबिंबों की स्थिति, प्रकृति और आकार की खोज करना।","kn":"ಪೀನ ಮತ್ತು ನಿಮ್ನ ಮಸೂರ ಹಾಗೂ ದರ್ಪಣಗಳು ರೂಪಿಸುವ ಪ್ರತಿಬಿಂಬಗಳ ಸ್ಥಾನ, ಸ್ವರೂಪ ಮತ್ತು ಗಾತ್ರವನ್ನು ಅನ್ವೇಷಿಸುವುದು."},"principle":{"en":"With the New Cartesian sign convention, a mirror obeys 1/v + 1/u = 1/f and a lens obeys 1/v − 1/u = 1/f. Magnification is m = −v/u for a mirror and m = v/u for a lens.","hi":"नई कार्तीय चिह्न परिपाटी में दर्पण के लिए 1/v + 1/u = 1/f और लेंस के लिए 1/v − 1/u = 1/f. आवर्धन दर्पण के लिए m = −v/u और लेंस के लिए m = v/u है।","kn":"ಹೊಸ ಕಾರ್ಟೀಸಿಯನ್ ಚಿಹ್ನೆ ಸಂಪ್ರದಾಯದಲ್ಲಿ ದರ್ಪಣಕ್ಕೆ 1/v + 1/u = 1/f ಮತ್ತು ಮಸೂರಕ್ಕೆ 1/v − 1/u = 1/f. ವರ್ಧನೆ ದರ್ಪಣಕ್ಕೆ m = −v/u, ಮಸೂರಕ್ಕೆ m = v/u."},"apparatus":[{"en":"Convex and concave lenses","hi":"उत्तल और अवतल लेंस","kn":"ಪೀನ ಮತ್ತು ನಿಮ್ನ ಮಸೂರಗಳು"},{"en":"Concave and convex mirrors","hi":"अवतल और उत्तल दर्पण","kn":"ನಿಮ್ನ ಮತ್ತು ಪೀನ ದರ್ಪಣಗಳು"},{"en":"An object (arrow) on the principal axis","hi":"मुख्य अक्ष पर एक वस्तु (तीर)","kn":"ಮುಖ್ಯ ಅಕ್ಷದ ಮೇಲೆ ಒಂದು ವಸ್ತು (ಬಾಣ)"}],"steps":[{"en":"Choose a lens or a mirror.","hi":"लेंस या दर्पण चुनें।","kn":"ಮಸೂರ ಅಥವಾ ದರ್ಪಣ ಆರಿಸಿ."},{"en":"Place the object beyond 2F (or C) and note the image.","hi":"वस्तु को 2F (या C) से परे रखें और प्रतिबिंब देखें।","kn":"ವಸ್ತುವನ್ನು 2F (ಅಥವಾ C) ಆಚೆ ಇಟ್ಟು ಪ್ರತಿಬಿಂಬ ಗಮನಿಸಿ."},{"en":"Move it to 2F, between F and 2F, at F and inside F, noting each image.","hi":"उसे 2F पर, F और 2F के बीच, F पर और F के भीतर ले जाएँ और हर प्रतिबिंब लिखें।","kn":"ಅದನ್ನು 2F ನಲ್ಲಿ, F ಮತ್ತು 2F ನಡುವೆ, F ನಲ್ಲಿ ಮತ್ತು F ಒಳಗೆ ಇಟ್ಟು ಪ್ರತಿ ಪ್ರತಿಬಿಂಬ ಬರೆಯಿರಿ."},{"en":"Check v and m against the formula for one position.","hi":"एक स्थिति के लिए v और m को सूत्र से जाँचें।","kn":"ಒಂದು ಸ್ಥಾನಕ್ಕೆ v ಮತ್ತು m ಅನ್ನು ಸೂತ್ರದಿಂದ ಪರೀಕ್ಷಿಸಿ."}],"precautions":[{"en":"Measure every distance from the pole or optical centre.","hi":"हर दूरी ध्रुव या प्रकाशिक केंद्र से मापें।","kn":"ಪ್ರತಿ ದೂರವನ್ನು ಧ್ರುವ ಅಥವಾ ದ್ಯುತಿ ಕೇಂದ್ರದಿಂದ ಅಳೆಯಿರಿ."},{"en":"Use the sign convention consistently.","hi":"चिह्न परिपाटी का हर जगह एक-सा प्रयोग करें।","kn":"ಚಿಹ್ನೆ ಸಂಪ್ರದಾಯವನ್ನು ಎಲ್ಲೆಡೆ ಒಂದೇ ರೀತಿ ಬಳಸಿ."}],"conclusion":{"en":"Convex lenses and concave mirrors give real, inverted images when the object is beyond F and virtual, erect, magnified images inside F; concave lenses and convex mirrors always give virtual, erect, diminished images.","hi":"वस्तु F से परे हो तो उत्तल लेंस और अवतल दर्पण वास्तविक, उल्टे प्रतिबिंब देते हैं और F के भीतर हो तो आभासी, सीधे, बड़े; अवतल लेंस और उत्तल दर्पण सदा आभासी, सीधे, छोटे प्रतिबिंब देते हैं।","kn":"ವಸ್ತು F ಆಚೆ ಇದ್ದರೆ ಪೀನ ಮಸೂರ ಮತ್ತು ನಿಮ್ನ ದರ್ಪಣ ನೈಜ, ತಲೆಕೆಳಗಾದ ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತವೆ; F ಒಳಗಿದ್ದರೆ ಮಿಥ್ಯ, ನೇರ, ದೊಡ್ಡ ಪ್ರತಿಬಿಂಬ. ನಿಮ್ನ ಮಸೂರ ಮತ್ತು ಪೀನ ದರ್ಪಣ ಯಾವಾಗಲೂ ಮಿಥ್ಯ, ನೇರ, ಚಿಕ್ಕ ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತವೆ."},"viva":[{"q":{"en":"Where must the object be for a convex lens to give a same-size image?","hi":"उत्तल लेंस से समान आकार का प्रतिबिंब पाने के लिए वस्तु कहाँ हो?","kn":"ಪೀನ ಮಸೂರದಿಂದ ಸಮಾನ ಗಾತ್ರದ ಪ್ರತಿಬಿಂಬಕ್ಕೆ ವಸ್ತು ಎಲ್ಲಿರಬೇಕು?"},"a":{"en":"At 2F₁; the image forms at 2F₂.","hi":"2F₁ पर; प्रतिबिंब 2F₂ पर बनता है।","kn":"2F₁ ನಲ್ಲಿ; ಪ್ರತಿಬಿಂಬ 2F₂ ನಲ್ಲಿ ಮೂಡುತ್ತದೆ."}},{"q":{"en":"Which mirror is used as a rear-view mirror, and why?","hi":"पीछे देखने के लिए कौन-सा दर्पण लगाते हैं, और क्यों?","kn":"ಹಿಂಬದಿ ನೋಟಕ್ಕೆ ಯಾವ ದರ್ಪಣ ಬಳಸುತ್ತಾರೆ, ಏಕೆ?"},"a":{"en":"A convex mirror: it always gives an erect image and a wide field of view.","hi":"उत्तल दर्पण: यह सदा सीधा प्रतिबिंब और चौड़ा दृश्य क्षेत्र देता है।","kn":"ಪೀನ ದರ್ಪಣ: ಅದು ಯಾವಾಗಲೂ ನೇರ ಪ್ರತಿಬಿಂಬ ಮತ್ತು ವಿಶಾಲ ನೋಟ ಕ್ಷೇತ್ರ ನೀಡುತ್ತದೆ."}},{"q":{"en":"What does a negative magnification mean?","hi":"ऋणात्मक आवर्धन का क्या अर्थ है?","kn":"ಋಣ ವರ್ಧನೆಯ ಅರ್ಥವೇನು?"},"a":{"en":"The image is inverted (and real).","hi":"प्रतिबिंब उल्टा (और वास्तविक) है।","kn":"ಪ್ರತಿಬಿಂಬ ತಲೆಕೆಳಗಾಗಿದೆ (ಮತ್ತು ನೈಜ)."}}]},{"id":"lab.pendulum","bench":"sim","setup":{},"subject":"Physics","domain":"physics","levels":["9","11"],"mode":"explore","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["oscillations","simple harmonic motion","time period","pendulum","gravity"],"title":{"en":"Simple pendulum explorer","hi":"सरल लोलक अन्वेषक","kn":"ಸರಳ ಲೋಲಕ ಅನ್ವೇಷಕ"},"summary":{"en":"Change the length, the planet and the amplitude, and time ten swings with the stopwatch.","hi":"लंबाई, ग्रह और आयाम बदलें और विराम घड़ी से दस दोलन मापें।","kn":"ಉದ್ದ, ಗ್ರಹ ಮತ್ತು ವಿಸ್ತಾರ ಬದಲಿಸಿ, ನಿಲುಗಡಿಯಾರದಿಂದ ಹತ್ತು ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆಯಿರಿ."},"aim":{"en":"To explore how the period of a pendulum depends on its length, on g and on the amplitude.","hi":"यह खोजना कि लोलक का आवर्तकाल उसकी लंबाई, g और आयाम पर कैसे निर्भर करता है।","kn":"ಲೋಲಕದ ಆವರ್ತಕಾಲವು ಉದ್ದ, g ಮತ್ತು ವಿಸ್ತಾರದ ಮೇಲೆ ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ ಎಂದು ಅನ್ವೇಷಿಸುವುದು."},"principle":{"en":"For small swings T = 2π√(L/g): the period grows with the square root of the length, falls on a planet with larger g, and does not depend on the mass. Large swings take slightly longer.","hi":"छोटे दोलनों के लिए T = 2π√(L/g): आवर्तकाल लंबाई के वर्गमूल के साथ बढ़ता है, अधिक g वाले ग्रह पर घटता है और द्रव्यमान पर निर्भर नहीं करता। बड़े दोलन थोड़ा अधिक समय लेते हैं।","kn":"ಸಣ್ಣ ಆಂದೋಲನಗಳಿಗೆ T = 2π√(L/g): ಆವರ್ತಕಾಲ ಉದ್ದದ ವರ್ಗಮೂಲದೊಂದಿಗೆ ಹೆಚ್ಚುತ್ತದೆ, ಹೆಚ್ಚು g ಇರುವ ಗ್ರಹದಲ್ಲಿ ಕಡಿಮೆಯಾಗುತ್ತದೆ, ದ್ರವ್ಯರಾಶಿಯನ್ನು ಅವಲಂಬಿಸುವುದಿಲ್ಲ. ದೊಡ್ಡ ಆಂದೋಲನಗಳಿಗೆ ಸ್ವಲ್ಪ ಹೆಚ್ಚು ಸಮಯ."},"apparatus":[{"en":"Bob on a thread","hi":"धागे पर गोलक","kn":"ದಾರಕ್ಕೆ ಕಟ್ಟಿದ ಗುಂಡು"},{"en":"Stand and clamp","hi":"स्टैंड और क्लैंप","kn":"ಸ್ಟ್ಯಾಂಡ್ ಮತ್ತು ಕ್ಲ್ಯಾಂಪ್"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"},{"en":"Metre scale","hi":"मीटर पैमाना","kn":"ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ"}],"steps":[{"en":"Set a length and a small amplitude.","hi":"एक लंबाई और छोटा आयाम तय करें।","kn":"ಒಂದು ಉದ್ದ ಮತ್ತು ಸಣ್ಣ ವಿಸ್ತಾರ ಹೊಂದಿಸಿ."},{"en":"Start the stopwatch as the bob passes the mean position and time 10 oscillations.","hi":"गोलक के माध्य स्थिति से गुजरते ही विराम घड़ी चालू करें और 10 दोलनों का समय लें।","kn":"ಗುಂಡು ಮಧ್ಯಸ್ಥಾನ ದಾಟುವಾಗ ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ 10 ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆಯಿರಿ."},{"en":"Change the length, then the planet, and compare the periods.","hi":"लंबाई, फिर ग्रह बदलें और आवर्तकालों की तुलना करें।","kn":"ಉದ್ದ, ನಂತರ ಗ್ರಹ ಬದಲಿಸಿ, ಆವರ್ತಕಾಲಗಳನ್ನು ಹೋಲಿಸಿ."},{"en":"Try a large amplitude and compare with the formula.","hi":"बड़ा आयाम आज़माएँ और सूत्र से तुलना करें।","kn":"ದೊಡ್ಡ ವಿಸ್ತಾರ ಪ್ರಯತ್ನಿಸಿ, ಸೂತ್ರದೊಂದಿಗೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Keep the amplitude small (under about 10°).","hi":"आयाम छोटा रखें (लगभग 10° से कम)।","kn":"ವಿಸ್ತಾರ ಸಣ್ಣದಾಗಿರಲಿ (ಸುಮಾರು 10° ಕ್ಕಿಂತ ಕಡಿಮೆ)."},{"en":"Time many oscillations, not one.","hi":"एक नहीं, कई दोलनों का समय लें।","kn":"ಒಂದಲ್ಲ, ಹಲವು ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆಯಿರಿ."}],"conclusion":{"en":"The period depends on length and g but not on the mass; for small swings it matches T = 2π√(L/g).","hi":"आवर्तकाल लंबाई और g पर निर्भर करता है, द्रव्यमान पर नहीं; छोटे दोलनों के लिए यह T = 2π√(L/g) से मेल खाता है।","kn":"ಆವರ್ತಕಾಲ ಉದ್ದ ಮತ್ತು g ಮೇಲೆ ಅವಲಂಬಿಸಿದೆ, ದ್ರವ್ಯರಾಶಿಯ ಮೇಲಲ್ಲ; ಸಣ್ಣ ಆಂದೋಲನಗಳಿಗೆ ಅದು T = 2π√(L/g) ಗೆ ಹೊಂದುತ್ತದೆ."},"viva":[{"q":{"en":"Would a pendulum clock run fast or slow on the Moon?","hi":"चंद्रमा पर लोलक घड़ी तेज़ चलेगी या धीमी?","kn":"ಚಂದ್ರನ ಮೇಲೆ ಲೋಲಕ ಗಡಿಯಾರ ವೇಗವಾಗಿ ಓಡುತ್ತದೆಯೇ ನಿಧಾನವಾಗಿಯೇ?"},"a":{"en":"Slow: g is smaller, so each swing takes longer.","hi":"धीमी: g कम है, इसलिए हर दोलन अधिक समय लेता है।","kn":"ನಿಧಾನ: g ಕಡಿಮೆ, ಆದ್ದರಿಂದ ಪ್ರತಿ ಆಂದೋಲನಕ್ಕೆ ಹೆಚ್ಚು ಸಮಯ."}},{"q":{"en":"If the length is made four times, what happens to T?","hi":"लंबाई चार गुनी करने पर T का क्या होगा?","kn":"ಉದ್ದವನ್ನು ನಾಲ್ಕು ಪಟ್ಟು ಮಾಡಿದರೆ T ಏನಾಗುತ್ತದೆ?"},"a":{"en":"It doubles.","hi":"यह दोगुना हो जाता है।","kn":"ಅದು ಎರಡು ಪಟ್ಟಾಗುತ್ತದೆ."}},{"q":{"en":"Why start timing at the mean position?","hi":"समय मापन माध्य स्थिति से क्यों शुरू करते हैं?","kn":"ಸಮಯ ಅಳತೆಯನ್ನು ಮಧ್ಯಸ್ಥಾನದಿಂದ ಏಕೆ ಆರಂಭಿಸುತ್ತೇವೆ?"},"a":{"en":"The bob moves fastest there, so the moment it passes is easiest to judge.","hi":"वहाँ गोलक सबसे तेज़ चलता है, इसलिए उसके गुजरने का क्षण पहचानना सबसे आसान है।","kn":"ಅಲ್ಲಿ ಗುಂಡು ಅತಿ ವೇಗವಾಗಿ ಚಲಿಸುತ್ತದೆ, ಆದ್ದರಿಂದ ಅದು ದಾಟುವ ಕ್ಷಣ ಗುರುತಿಸುವುದು ಸುಲಭ."}}]},{"id":"lab.break-even","bench":"sim","setup":{},"subject":"Mathematics","domain":"maths","levels":["ug"],"mode":"explore","curricula":["bu-bcom"],"reviewed":false,"keywords":["break-even","marginal costing","cost accounting","contribution","margin of safety","p/v ratio"],"title":{"en":"Break-even analysis","hi":"सम-विच्छेद विश्लेषण","kn":"ಲಾಭ-ನಷ್ಟ ಸಮತೋಲನ ವಿಶ್ಲೇಷಣೆ"},"summary":{"en":"Change fixed cost, variable cost, price and sales and watch the break-even point move.","hi":"स्थायी लागत, परिवर्ती लागत, मूल्य और बिक्री बदलें और सम-विच्छेद बिंदु खिसकते देखें।","kn":"ಸ್ಥಿರ ವೆಚ್ಚ, ಬದಲಾಗುವ ವೆಚ್ಚ, ಬೆಲೆ ಮತ್ತು ಮಾರಾಟ ಬದಲಿಸಿ, ಸಮತೋಲನ ಬಿಂದು ಸರಿಯುವುದನ್ನು ನೋಡಿ."},"aim":{"en":"To find the break-even point, P/V ratio and margin of safety from a break-even chart.","hi":"सम-विच्छेद चार्ट से सम-विच्छेद बिंदु, P/V अनुपात और सुरक्षा सीमा ज्ञात करना।","kn":"ಸಮತೋಲನ ಚಾರ್ಟ್‌ನಿಂದ ಸಮತೋಲನ ಬಿಂದು, P/V ಅನುಪಾತ ಮತ್ತು ಸುರಕ್ಷತಾ ಅಂಚು ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Contribution per unit = price − variable cost. Break-even units = fixed cost ÷ contribution per unit. P/V ratio = contribution ÷ sales. Margin of safety = actual sales − break-even sales.","hi":"प्रति इकाई अंशदान = मूल्य − परिवर्ती लागत. सम-विच्छेद इकाइयाँ = स्थायी लागत ÷ प्रति इकाई अंशदान. P/V अनुपात = अंशदान ÷ बिक्री. सुरक्षा सीमा = वास्तविक बिक्री − सम-विच्छेद बिक्री.","kn":"ಪ್ರತಿ ಘಟಕದ ಕೊಡುಗೆ = ಬೆಲೆ − ಬದಲಾಗುವ ವೆಚ್ಚ. ಸಮತೋಲನ ಘಟಕಗಳು = ಸ್ಥಿರ ವೆಚ್ಚ ÷ ಪ್ರತಿ ಘಟಕದ ಕೊಡುಗೆ. P/V ಅನುಪಾತ = ಕೊಡುಗೆ ÷ ಮಾರಾಟ. ಸುರಕ್ಷತಾ ಅಂಚು = ನಿಜ ಮಾರಾಟ − ಸಮತೋಲನ ಮಾರಾಟ."},"apparatus":[{"en":"Cost and price data","hi":"लागत और मूल्य के आँकड़े","kn":"ವೆಚ್ಚ ಮತ್ತು ಬೆಲೆಯ ದತ್ತಾಂಶ"},{"en":"Break-even chart","hi":"सम-विच्छेद चार्ट","kn":"ಸಮತೋಲನ ಚಾರ್ಟ್"},{"en":"Calculator","hi":"कैलकुलेटर","kn":"ಕ್ಯಾಲ್ಕುಲೇಟರ್"}],"steps":[{"en":"Enter the fixed cost.","hi":"स्थायी लागत डालें।","kn":"ಸ್ಥಿರ ವೆಚ್ಚ ನಮೂದಿಸಿ."},{"en":"Enter the variable cost per unit and the selling price.","hi":"प्रति इकाई परिवर्ती लागत और विक्रय मूल्य डालें।","kn":"ಪ್ರತಿ ಘಟಕದ ಬದಲಾಗುವ ವೆಚ್ಚ ಮತ್ತು ಮಾರಾಟ ಬೆಲೆ ನಮೂದಿಸಿ."},{"en":"Read the break-even point where the sales and total cost lines cross.","hi":"जहाँ बिक्री और कुल लागत रेखाएँ कटती हैं वहाँ सम-विच्छेद बिंदु पढ़ें।","kn":"ಮಾರಾಟ ಮತ್ತು ಒಟ್ಟು ವೆಚ್ಚದ ರೇಖೆಗಳು ಛೇದಿಸುವಲ್ಲಿ ಸಮತೋಲನ ಬಿಂದು ಓದಿ."},{"en":"Change the sales volume and read the profit or loss and the margin of safety.","hi":"बिक्री की मात्रा बदलें और लाभ या हानि तथा सुरक्षा सीमा पढ़ें।","kn":"ಮಾರಾಟದ ಪ್ರಮಾಣ ಬದಲಿಸಿ, ಲಾಭ ಅಥವಾ ನಷ್ಟ ಮತ್ತು ಸುರಕ್ಷತಾ ಅಂಚು ಓದಿ."}],"precautions":[{"en":"Keep the price above the variable cost, or there is no break-even point.","hi":"मूल्य परिवर्ती लागत से अधिक रखें, नहीं तो सम-विच्छेद बिंदु नहीं होगा।","kn":"ಬೆಲೆ ಬದಲಾಗುವ ವೆಚ್ಚಕ್ಕಿಂತ ಹೆಚ್ಚಿರಲಿ, ಇಲ್ಲದಿದ್ದರೆ ಸಮತೋಲನ ಬಿಂದು ಇರದು."},{"en":"Use the same units (₹, units) throughout.","hi":"सब जगह एक-सी इकाइयाँ (₹, इकाइयाँ) लें।","kn":"ಎಲ್ಲೆಡೆ ಒಂದೇ ಏಕಮಾನಗಳನ್ನು (₹, ಘಟಕಗಳು) ಬಳಸಿ."}],"conclusion":{"en":"Below the break-even point the firm makes a loss and above it a profit; a higher fixed cost moves the break-even point up, a higher contribution moves it down.","hi":"सम-विच्छेद बिंदु से नीचे फ़र्म को हानि और ऊपर लाभ होता है; अधिक स्थायी लागत बिंदु को ऊपर और अधिक अंशदान उसे नीचे ले जाता है।","kn":"ಸಮತೋಲನ ಬಿಂದುವಿನ ಕೆಳಗೆ ಸಂಸ್ಥೆಗೆ ನಷ್ಟ, ಮೇಲೆ ಲಾಭ; ಹೆಚ್ಚಿನ ಸ್ಥಿರ ವೆಚ್ಚ ಬಿಂದುವನ್ನು ಮೇಲೆ, ಹೆಚ್ಚಿನ ಕೊಡುಗೆ ಅದನ್ನು ಕೆಳಗೆ ಸರಿಸುತ್ತದೆ."},"viva":[{"q":{"en":"What is contribution?","hi":"अंशदान क्या है?","kn":"ಕೊಡುಗೆ ಎಂದರೇನು?"},"a":{"en":"Sales minus variable cost.","hi":"बिक्री घटा परिवर्ती लागत।","kn":"ಮಾರಾಟ ಕಳೆ ಬದಲಾಗುವ ವೆಚ್ಚ."}},{"q":{"en":"Fixed cost ₹40,000, contribution ₹20 per unit: find the BEP.","hi":"स्थायी लागत ₹40,000, अंशदान ₹20 प्रति इकाई: सम-विच्छेद बिंदु ज्ञात करें।","kn":"ಸ್ಥಿರ ವೆಚ್ಚ ₹40,000, ಪ್ರತಿ ಘಟಕದ ಕೊಡುಗೆ ₹20: ಸಮತೋಲನ ಬಿಂದು ಕಂಡುಹಿಡಿಯಿರಿ."},"a":{"en":"2,000 units.","hi":"2,000 इकाइयाँ।","kn":"2,000 ಘಟಕಗಳು."}},{"q":{"en":"What does a large margin of safety show?","hi":"बड़ी सुरक्षा सीमा क्या दर्शाती है?","kn":"ದೊಡ್ಡ ಸುರಕ್ಷತಾ ಅಂಚು ಏನನ್ನು ತೋರಿಸುತ್ತದೆ?"},"a":{"en":"Sales can fall a lot before the firm makes a loss.","hi":"हानि होने से पहले बिक्री काफ़ी घट सकती है।","kn":"ನಷ್ಟವಾಗುವ ಮೊದಲು ಮಾರಾಟ ಸಾಕಷ್ಟು ಕುಸಿಯಬಹುದು."}}]},{"id":"lab.graph-plotter","bench":"sim","setup":{},"subject":"Mathematics","domain":"maths","levels":["9","10","11"],"mode":"explore","curricula":["cbse","ncert"],"reviewed":false,"keywords":["graph","polynomials","quadratic equations","linear equations","trigonometry","roots"],"title":{"en":"Graph plotter","hi":"ग्राफ़ प्लॉटर","kn":"ನಕ್ಷೆ ರಚಕ"},"summary":{"en":"Plot lines, parabolas and sine curves, move the coefficients and watch roots and vertex change.","hi":"रेखाएँ, परवलय और ज्या वक्र बनाएँ, गुणांक बदलें और मूल तथा शीर्ष बदलते देखें।","kn":"ರೇಖೆಗಳು, ಪರವಲಯಗಳು ಮತ್ತು ಸೈನ್ ವಕ್ರಗಳನ್ನು ರಚಿಸಿ, ಗುಣಾಂಕ ಬದಲಿಸಿ ಮೂಲಗಳು ಮತ್ತು ಶೃಂಗ ಬದಲಾಗುವುದನ್ನು ನೋಡಿ."},"aim":{"en":"To explore how the coefficients of a function change its graph, its roots and its vertex.","hi":"यह खोजना कि फलन के गुणांक उसके ग्राफ़, मूलों और शीर्ष को कैसे बदलते हैं।","kn":"ಫಲನದ ಗುಣಾಂಕಗಳು ಅದರ ನಕ್ಷೆ, ಮೂಲಗಳು ಮತ್ತು ಶೃಂಗವನ್ನು ಹೇಗೆ ಬದಲಿಸುತ್ತವೆ ಎಂದು ಅನ್ವೇಷಿಸುವುದು."},"principle":{"en":"The zeros of a polynomial are where its graph meets the x-axis. For y = ax² + bx + c the discriminant b² − 4ac decides whether there are two, one or no real roots, and the vertex is at x = −b/2a.","hi":"बहुपद के शून्यक वहाँ हैं जहाँ उसका ग्राफ़ x-अक्ष से मिलता है। y = ax² + bx + c के लिए विविक्तकर b² − 4ac तय करता है कि दो, एक या कोई वास्तविक मूल नहीं है, और शीर्ष x = −b/2a पर है।","kn":"ಬಹುಪದದ ಶೂನ್ಯಗಳು ಅದರ ನಕ್ಷೆ x-ಅಕ್ಷವನ್ನು ಸಂಧಿಸುವಲ್ಲಿವೆ. y = ax² + bx + c ಗೆ ವಿವೇಚಕ b² − 4ac ಎರಡು, ಒಂದು ಅಥವಾ ಯಾವುದೇ ನೈಜ ಮೂಲ ಇಲ್ಲವೇ ಎಂದು ನಿರ್ಧರಿಸುತ್ತದೆ; ಶೃಂಗ x = −b/2a ನಲ್ಲಿದೆ."},"apparatus":[{"en":"Graph plotter on the board","hi":"बोर्ड पर ग्राफ़ प्लॉटर","kn":"ಬೋರ್ಡ್‌ನಲ್ಲಿ ನಕ್ಷೆ ರಚಕ"},{"en":"Coefficient sliders","hi":"गुणांक स्लाइडर","kn":"ಗುಣಾಂಕ ಸ್ಲೈಡರ್‌ಗಳು"},{"en":"Typed expression box","hi":"व्यंजक लिखने का बॉक्स","kn":"ಅಭಿವ್ಯಕ್ತಿ ಬರೆಯುವ ಪೆಟ್ಟಿಗೆ"}],"steps":[{"en":"Choose linear, quadratic, sine or cosine.","hi":"रैखिक, द्विघात, ज्या या कोज्या चुनें।","kn":"ರೇಖೀಯ, ವರ್ಗ, ಸೈನ್ ಅಥವಾ ಕೊಸೈನ್ ಆರಿಸಿ."},{"en":"Move one coefficient at a time and describe what changes.","hi":"एक समय में एक गुणांक बदलें और बताएँ कि क्या बदलता है।","kn":"ಒಮ್ಮೆಗೆ ಒಂದು ಗುಣಾಂಕ ಸರಿಸಿ, ಏನು ಬದಲಾಗುತ್ತದೆ ಹೇಳಿ."},{"en":"Read the roots and the vertex and check them with the formula.","hi":"मूल और शीर्ष पढ़ें और सूत्र से जाँचें।","kn":"ಮೂಲಗಳು ಮತ್ತು ಶೃಂಗ ಓದಿ, ಸೂತ್ರದಿಂದ ಪರೀಕ್ಷಿಸಿ."},{"en":"Type your own expression and plot it.","hi":"अपना व्यंजक लिखकर उसका ग्राफ़ बनाएँ।","kn":"ನಿಮ್ಮದೇ ಅಭಿವ್ಯಕ್ತಿ ಬರೆದು ನಕ್ಷೆ ರಚಿಸಿ."}],"precautions":[{"en":"Zoom out before deciding a graph has no roots.","hi":"यह तय करने से पहले कि ग्राफ़ का कोई मूल नहीं, ज़ूम आउट करें।","kn":"ನಕ್ಷೆಗೆ ಮೂಲವಿಲ್ಲ ಎನ್ನುವ ಮೊದಲು ಝೂಮ್ ಔಟ್ ಮಾಡಿ."},{"en":"Angles for sine and cosine are in degrees.","hi":"ज्या और कोज्या के कोण अंशों में हैं।","kn":"ಸೈನ್ ಮತ್ತು ಕೊಸೈನ್ ಕೋನಗಳು ಡಿಗ್ರಿಗಳಲ್ಲಿವೆ."}],"conclusion":{"en":"The sign of a opens the parabola up or down, c is the y-intercept, and the discriminant decides the number of real roots.","hi":"a का चिह्न परवलय को ऊपर या नीचे खोलता है, c y-अंतःखंड है, और विविक्तकर वास्तविक मूलों की संख्या तय करता है।","kn":"a ಯ ಚಿಹ್ನೆ ಪರವಲಯವನ್ನು ಮೇಲೆ ಅಥವಾ ಕೆಳಗೆ ತೆರೆಯುತ್ತದೆ, c y-ಅಂತಃಖಂಡ, ವಿವೇಚಕ ನೈಜ ಮೂಲಗಳ ಸಂಖ್ಯೆ ನಿರ್ಧರಿಸುತ್ತದೆ."},"viva":[{"q":{"en":"How many zeros does y = x² + 1 have?","hi":"y = x² + 1 के कितने शून्यक हैं?","kn":"y = x² + 1 ಗೆ ಎಷ್ಟು ಶೂನ್ಯಗಳಿವೆ?"},"a":{"en":"None (real): the graph never meets the x-axis.","hi":"कोई (वास्तविक) नहीं: ग्राफ़ x-अक्ष से नहीं मिलता।","kn":"ಯಾವುದೂ (ನೈಜ) ಇಲ್ಲ: ನಕ್ಷೆ x-ಅಕ್ಷವನ್ನು ಸಂಧಿಸುವುದಿಲ್ಲ."}},{"q":{"en":"What does the slope m of y = mx + c tell you?","hi":"y = mx + c में प्रवणता m क्या बताती है?","kn":"y = mx + c ಯಲ್ಲಿ ಇಳಿಜಾರು m ಏನನ್ನು ತಿಳಿಸುತ್ತದೆ?"},"a":{"en":"How steep the line is: y rises by m for each unit of x.","hi":"रेखा कितनी खड़ी है: x की हर इकाई पर y, m बढ़ता है।","kn":"ರೇಖೆ ಎಷ್ಟು ಕಡಿದಾಗಿದೆ: x ನ ಪ್ರತಿ ಘಟಕಕ್ಕೆ y, m ಹೆಚ್ಚುತ್ತದೆ."}},{"q":{"en":"Where is the vertex of y = x² − 4x + 3?","hi":"y = x² − 4x + 3 का शीर्ष कहाँ है?","kn":"y = x² − 4x + 3 ರ ಶೃಂಗ ಎಲ್ಲಿದೆ?"},"a":{"en":"At (2, −1).","hi":"(2, −1) पर।","kn":"(2, −1) ನಲ್ಲಿ."}}]},{"id":"pn-junction-diode","bench":"diode","setup":{"device":"si"},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["semiconductor","semiconductor electronics","p-n junction","pn junction","diode","forward bias","reverse bias","knee voltage","characteristics"],"title":{"en":"I–V characteristics of a p-n junction diode","hi":"p-n संधि डायोड के I–V अभिलक्षण","kn":"p-n ಸಂಧಿ ಡಯೋಡ್‌ನ I–V ಲಕ್ಷಣಗಳು"},"summary":{"en":"Forward- and reverse-bias a silicon diode, record V and I, and find its knee voltage.","hi":"सिलिकॉन डायोड को अग्र और पश्च अभिनति दें, V और I लिखें और उसकी घुटना वोल्टता ज्ञात करें।","kn":"ಸಿಲಿಕಾನ್ ಡಯೋಡ್‌ಗೆ ಮುಮ್ಮುಖ ಮತ್ತು ಹಿಮ್ಮುಖ ಬಯಾಸ್ ನೀಡಿ, V ಮತ್ತು I ದಾಖಲಿಸಿ, ಅದರ ನೀ (ಮೊಣಕಾಲು) ವೋಲ್ಟೇಜ್ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To draw the I–V characteristic curves of a p-n junction diode in forward and reverse bias.","hi":"अग्र और पश्च अभिनति में p-n संधि डायोड के I–V अभिलक्षण वक्र खींचना।","kn":"ಮುಮ್ಮುಖ ಮತ್ತು ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ p-n ಸಂಧಿ ಡಯೋಡ್‌ನ I–V ಲಕ್ಷಣ ವಕ್ರಗಳನ್ನು ಎಳೆಯುವುದು."},"principle":{"en":"A p-n junction has a depletion layer with a barrier potential (about 0.7 V for silicon). In forward bias the barrier is lowered: almost no current flows until the applied voltage nears the barrier (the knee voltage), then the current rises steeply. In reverse bias the barrier grows and only a tiny current of minority carriers (microamperes) flows.","hi":"p-n संधि में एक ह्रासी परत होती है जिसका रोधिका विभव (सिलिकॉन के लिए लगभग 0.7 V) होता है। अग्र अभिनति में रोधिका घटती है: लगाई गई वोल्टता रोधिका के निकट (घुटना वोल्टता) आने तक लगभग कोई धारा नहीं बहती, फिर धारा तेज़ी से बढ़ती है। पश्च अभिनति में रोधिका बढ़ती है और केवल अल्पसंख्यक वाहकों की बहुत छोटी धारा (माइक्रोऐम्पियर) बहती है।","kn":"p-n ಸಂಧಿಯಲ್ಲಿ ಕ್ಷೀಣಿಸಿದ ಪದರವಿದ್ದು ಅದಕ್ಕೆ ತಡೆ ವಿಭವ (ಸಿಲಿಕಾನ್‌ಗೆ ಸುಮಾರು 0.7 V) ಇರುತ್ತದೆ. ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ತಡೆ ಕಡಿಮೆಯಾಗುತ್ತದೆ: ಅನ್ವಯಿಸಿದ ವೋಲ್ಟೇಜ್ ತಡೆಯ ಹತ್ತಿರ (ನೀ ವೋಲ್ಟೇಜ್) ಬರುವವರೆಗೆ ಬಹುತೇಕ ಪ್ರವಾಹವಿಲ್ಲ, ನಂತರ ಪ್ರವಾಹ ವೇಗವಾಗಿ ಏರುತ್ತದೆ. ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ತಡೆ ಹೆಚ್ಚುತ್ತದೆ; ಅಲ್ಪಸಂಖ್ಯಾತ ವಾಹಕಗಳ ಅತಿ ಸಣ್ಣ ಪ್ರವಾಹ (ಮೈಕ್ರೋಆಂಪಿಯರ್) ಮಾತ್ರ ಹರಿಯುತ್ತದೆ."},"apparatus":[{"en":"Silicon p-n junction diode","hi":"सिलिकॉन p-n संधि डायोड","kn":"ಸಿಲಿಕಾನ್ p-n ಸಂಧಿ ಡಯೋಡ್"},{"en":"Variable DC power supply (0–10 V)","hi":"परिवर्ती DC विद्युत आपूर्ति (0–10 V)","kn":"ಬದಲಾಯಿಸಬಹುದಾದ DC ವಿದ್ಯುತ್ ಪೂರೈಕೆ (0–10 V)"},{"en":"Series resistor (100 Ω) to limit the current","hi":"धारा सीमित करने के लिए श्रेणी प्रतिरोधक (100 Ω)","kn":"ಪ್ರವಾಹ ಮಿತಿಗೊಳಿಸಲು ಸರಣಿ ರೋಧಕ (100 Ω)"},{"en":"Milliammeter (and microammeter)","hi":"मिलीऐमीटर (और माइक्रोऐमीटर)","kn":"ಮಿಲಿಅಮ್ಮೀಟರ್ (ಮತ್ತು ಮೈಕ್ರೋಅಮ್ಮೀಟರ್)"},{"en":"Voltmeter","hi":"वोल्टमीटर","kn":"ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect the diode in forward bias: p side (anode) to the + of the supply through the resistor and milliammeter; voltmeter across the diode.","hi":"डायोड को अग्र अभिनति में जोड़ें: p सिरा (ऐनोड) प्रतिरोधक और मिलीऐमीटर से होते हुए आपूर्ति के + से; वोल्टमीटर डायोड के सिरों पर।","kn":"ಡಯೋಡನ್ನು ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಜೋಡಿಸಿ: p ಭಾಗ (ಆನೋಡ್) ರೋಧಕ ಮತ್ತು ಮಿಲಿಅಮ್ಮೀಟರ್ ಮೂಲಕ ಪೂರೈಕೆಯ + ಗೆ; ವೋಲ್ಟ್‌ಮೀಟರ್ ಡಯೋಡ್‌ಗೆ ಅಡ್ಡಲಾಗಿ."},{"en":"Raise the supply in small steps and record V and I each time. Take closer readings around 0.5–0.8 V.","hi":"आपूर्ति को छोटे चरणों में बढ़ाएँ और हर बार V और I लिखें। 0.5–0.8 V के आसपास पाठ्यांक पास-पास लें।","kn":"ಪೂರೈಕೆಯನ್ನು ಸಣ್ಣ ಹಂತಗಳಲ್ಲಿ ಹೆಚ್ಚಿಸಿ ಪ್ರತಿ ಬಾರಿ V ಮತ್ತು I ದಾಖಲಿಸಿ. 0.5–0.8 V ಸುತ್ತ ಹತ್ತಿರ ಹತ್ತಿರ ಓದುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಿ."},{"en":"Switch to reverse bias (and a microammeter). Raise the voltage and record V and I.","hi":"पश्च अभिनति पर बदलें (और माइक्रोऐमीटर लगाएँ)। वोल्टता बढ़ाकर V और I लिखें।","kn":"ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ಗೆ ಬದಲಿಸಿ (ಮೈಕ್ರೋಅಮ್ಮೀಟರ್ ಬಳಸಿ). ವೋಲ್ಟೇಜ್ ಹೆಚ್ಚಿಸಿ V ಮತ್ತು I ದಾಖಲಿಸಿ."},{"en":"Plot I against V for both biases on one graph (reverse values negative).","hi":"दोनों अभिनतियों के लिए I और V का ग्राफ़ एक ही कागज़ पर बनाएँ (पश्च मान ऋणात्मक)।","kn":"ಎರಡೂ ಬಯಾಸ್‌ಗಳಿಗೆ I ಮತ್ತು V ನಕ್ಷೆಯನ್ನು ಒಂದೇ ಹಾಳೆಯಲ್ಲಿ ಎಳೆಯಿರಿ (ಹಿಮ್ಮುಖ ಮೌಲ್ಯಗಳು ಋಣ)."},{"en":"Extend the straight, steep part of the forward curve down to the V axis: that is the knee voltage.","hi":"अग्र वक्र के सीधे, खड़े भाग को V अक्ष तक बढ़ाएँ: वही घुटना वोल्टता है।","kn":"ಮುಮ್ಮುಖ ವಕ್ರದ ನೇರ, ಕಡಿದಾದ ಭಾಗವನ್ನು V ಅಕ್ಷದವರೆಗೆ ವಿಸ್ತರಿಸಿ: ಅದೇ ನೀ ವೋಲ್ಟೇಜ್."}],"precautions":[{"en":"Never let the current exceed the rated value of the device; always keep the series resistor in the circuit.","hi":"धारा कभी भी युक्ति के निर्धारित मान से अधिक न होने दें; श्रेणी प्रतिरोधक सदा परिपथ में रखें।","kn":"ಪ್ರವಾಹ ಸಾಧನದ ನಿಗದಿತ ಮೌಲ್ಯವನ್ನು ಎಂದೂ ಮೀರಬಾರದು; ಸರಣಿ ರೋಧಕವನ್ನು ಯಾವಾಗಲೂ ಮಂಡಲದಲ್ಲಿಡಿ."},{"en":"Connect meters with + to + and choose a range larger than the expected reading.","hi":"मीटर + से + जोड़ें और अपेक्षित पाठ्यांक से बड़ी परास चुनें।","kn":"ಮೀಟರ್‌ಗಳನ್ನು + ರಿಂದ + ಗೆ ಜೋಡಿಸಿ, ನಿರೀಕ್ಷಿತ ಓದಿಗಿಂತ ದೊಡ್ಡ ವ್ಯಾಪ್ತಿ ಆರಿಸಿ."},{"en":"Use a microammeter in reverse bias: the current is very small.","hi":"पश्च अभिनति में माइक्रोऐमीटर लें: धारा बहुत छोटी होती है।","kn":"ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಮೈಕ್ರೋಅಮ್ಮೀಟರ್ ಬಳಸಿ: ಪ್ರವಾಹ ಅತಿ ಸಣ್ಣದು."}],"conclusion":{"en":"The diode conducts well only in forward bias, after the knee voltage (about 0.7 V for silicon); in reverse bias only microamperes flow. The diode is a one-way valve for current.","hi":"डायोड केवल अग्र अभिनति में, घुटना वोल्टता (सिलिकॉन के लिए लगभग 0.7 V) के बाद अच्छी तरह चालन करता है; पश्च अभिनति में केवल माइक्रोऐम्पियर बहते हैं। डायोड धारा के लिए एकदिशीय वाल्व है।","kn":"ಡಯೋಡ್ ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಮಾತ್ರ, ನೀ ವೋಲ್ಟೇಜ್ (ಸಿಲಿಕಾನ್‌ಗೆ ಸುಮಾರು 0.7 V) ನಂತರ ಚೆನ್ನಾಗಿ ವಾಹಕವಾಗುತ್ತದೆ; ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಮೈಕ್ರೋಆಂಪಿಯರ್ ಮಾತ್ರ. ಡಯೋಡ್ ಪ್ರವಾಹಕ್ಕೆ ಏಕಮುಖ ಕವಾಟ."},"viva":[{"q":{"en":"What is the knee voltage of a germanium diode?","hi":"जर्मेनियम डायोड की घुटना वोल्टता कितनी होती है?","kn":"ಜರ್ಮೇನಿಯಂ ಡಯೋಡ್‌ನ ನೀ ವೋಲ್ಟೇಜ್ ಎಷ್ಟು?"},"a":{"en":"About 0.3 V.","hi":"लगभग 0.3 V.","kn":"ಸುಮಾರು 0.3 V."}},{"q":{"en":"Why does a small current flow in reverse bias?","hi":"पश्च अभिनति में छोटी धारा क्यों बहती है?","kn":"ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಸಣ್ಣ ಪ್ರವಾಹ ಏಕೆ ಹರಿಯುತ್ತದೆ?"},"a":{"en":"Minority carriers (electrons in p, holes in n) are swept across the junction by the field.","hi":"अल्पसंख्यक वाहक (p में इलेक्ट्रॉन, n में होल) क्षेत्र द्वारा संधि के पार धकेले जाते हैं।","kn":"ಅಲ್ಪಸಂಖ್ಯಾತ ವಾಹಕಗಳು (p ಯಲ್ಲಿ ಎಲೆಕ್ಟ್ರಾನ್, n ನಲ್ಲಿ ರಂಧ್ರ) ಕ್ಷೇತ್ರದಿಂದ ಸಂಧಿಯ ಆಚೆ ತಳ್ಳಲ್ಪಡುತ್ತವೆ."}},{"q":{"en":"What is the dynamic resistance of a diode?","hi":"डायोड का गतिक प्रतिरोध क्या है?","kn":"ಡಯೋಡ್‌ನ ಚಲನಶೀಲ ರೋಧ ಎಂದರೇನು?"},"a":{"en":"ΔV ÷ ΔI at a point on the curve: small in forward bias above the knee.","hi":"वक्र के किसी बिंदु पर ΔV ÷ ΔI: घुटने के ऊपर अग्र अभिनति में यह छोटा होता है।","kn":"ವಕ್ರದ ಒಂದು ಬಿಂದುವಿನಲ್ಲಿ ΔV ÷ ΔI: ನೀ ಮೇಲೆ ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಇದು ಸಣ್ಣದು."}},{"q":{"en":"Which side of the diode is marked by the band?","hi":"डायोड पर पट्टी किस सिरे को दर्शाती है?","kn":"ಡಯೋಡ್ ಮೇಲಿನ ಪಟ್ಟಿ ಯಾವ ತುದಿಯನ್ನು ಸೂಚಿಸುತ್ತದೆ?"},"a":{"en":"The cathode (n side).","hi":"कैथोड (n सिरा)।","kn":"ಕ್ಯಾಥೋಡ್ (n ಭಾಗ)."}}]},{"id":"zener-diode","bench":"diode","setup":{"device":"zener","bias":"rev"},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["zener","zener diode","breakdown","voltage regulator","reverse breakdown","semiconductor electronics"],"title":{"en":"Characteristics of a Zener diode","hi":"ज़ेनर डायोड के अभिलक्षण","kn":"ಜೀನರ್ ಡಯೋಡ್‌ನ ಲಕ್ಷಣಗಳು"},"summary":{"en":"Reverse-bias a Zener diode and find the voltage at which it breaks down and holds steady.","hi":"ज़ेनर डायोड को पश्च अभिनति दें और वह वोल्टता ज्ञात करें जिस पर यह भंजित होकर स्थिर रहता है।","kn":"ಜೀನರ್ ಡಯೋಡ್‌ಗೆ ಹಿಮ್ಮುಖ ಬಯಾಸ್ ನೀಡಿ, ಅದು ಭಂಜನಗೊಂಡು ಸ್ಥಿರವಾಗುವ ವೋಲ್ಟೇಜ್ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To draw the reverse characteristic of a Zener diode and find its breakdown voltage.","hi":"ज़ेनर डायोड का पश्च अभिलक्षण खींचना और उसकी भंजन वोल्टता ज्ञात करना।","kn":"ಜೀನರ್ ಡಯೋಡ್‌ನ ಹಿಮ್ಮುಖ ಲಕ್ಷಣ ಎಳೆದು ಅದರ ಭಂಜನ ವೋಲ್ಟೇಜ್ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"A Zener diode is heavily doped, so its depletion layer is thin. At a definite reverse voltage Vz the field breaks covalent bonds and the reverse current rises sharply while the voltage stays almost constant. This is why a Zener is used as a voltage regulator.","hi":"ज़ेनर डायोड भारी मादित होता है, इसलिए उसकी ह्रासी परत पतली होती है। एक निश्चित पश्च वोल्टता Vz पर क्षेत्र सहसंयोजी बंधों को तोड़ देता है और पश्च धारा तेज़ी से बढ़ती है जबकि वोल्टता लगभग स्थिर रहती है। इसीलिए ज़ेनर को वोल्टता नियंत्रक के रूप में प्रयोग करते हैं।","kn":"ಜೀನರ್ ಡಯೋಡ್ ಹೆಚ್ಚು ಡೋಪ್ ಮಾಡಿದ್ದು, ಅದರ ಕ್ಷೀಣ ಪದರ ತೆಳು. ಒಂದು ನಿರ್ದಿಷ್ಟ ಹಿಮ್ಮುಖ ವೋಲ್ಟೇಜ್ Vz ನಲ್ಲಿ ಕ್ಷೇತ್ರವು ಸಹವೇಲೆನ್ಸೀಯ ಬಂಧಗಳನ್ನು ಮುರಿಯುತ್ತದೆ; ಹಿಮ್ಮುಖ ಪ್ರವಾಹ ವೇಗವಾಗಿ ಏರುತ್ತದೆ, ವೋಲ್ಟೇಜ್ ಬಹುತೇಕ ಸ್ಥಿರ. ಆದ್ದರಿಂದ ಜೀನರನ್ನು ವೋಲ್ಟೇಜ್ ನಿಯಂತ್ರಕವಾಗಿ ಬಳಸುತ್ತಾರೆ."},"apparatus":[{"en":"Zener diode (3.3, 5.1 or 6.2 V)","hi":"ज़ेनर डायोड (3.3, 5.1 या 6.2 V)","kn":"ಜೀನರ್ ಡಯೋಡ್ (3.3, 5.1 ಅಥವಾ 6.2 V)"},{"en":"Variable DC power supply (0–10 V)","hi":"परिवर्ती DC विद्युत आपूर्ति (0–10 V)","kn":"ಬದಲಾಯಿಸಬಹುದಾದ DC ವಿದ್ಯುತ್ ಪೂರೈಕೆ (0–10 V)"},{"en":"Series resistor (100 Ω) to limit the current","hi":"धारा सीमित करने के लिए श्रेणी प्रतिरोधक (100 Ω)","kn":"ಪ್ರವಾಹ ಮಿತಿಗೊಳಿಸಲು ಸರಣಿ ರೋಧಕ (100 Ω)"},{"en":"Milliammeter (and microammeter)","hi":"मिलीऐमीटर (और माइक्रोऐमीटर)","kn":"ಮಿಲಿಅಮ್ಮೀಟರ್ (ಮತ್ತು ಮೈಕ್ರೋಅಮ್ಮೀಟರ್)"},{"en":"Voltmeter","hi":"वोल्टमीटर","kn":"ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect the Zener in reverse bias: its cathode (band) towards the + of the supply, through the resistor and milliammeter.","hi":"ज़ेनर को पश्च अभिनति में जोड़ें: उसका कैथोड (पट्टी) प्रतिरोधक और मिलीऐमीटर से होते हुए आपूर्ति के + की ओर।","kn":"ಜೀನರನ್ನು ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಜೋಡಿಸಿ: ಅದರ ಕ್ಯಾಥೋಡ್ (ಪಟ್ಟಿ) ರೋಧಕ ಮತ್ತು ಮಿಲಿಅಮ್ಮೀಟರ್ ಮೂಲಕ ಪೂರೈಕೆಯ + ಕಡೆಗೆ."},{"en":"Raise the supply slowly from zero and record the voltage across the Zener and the current.","hi":"आपूर्ति को शून्य से धीरे-धीरे बढ़ाएँ और ज़ेनर के सिरों की वोल्टता तथा धारा लिखें।","kn":"ಪೂರೈಕೆಯನ್ನು ಶೂನ್ಯದಿಂದ ನಿಧಾನವಾಗಿ ಹೆಚ್ಚಿಸಿ, ಜೀನರ್‌ಗೆ ಅಡ್ಡ ವೋಲ್ಟೇಜ್ ಮತ್ತು ಪ್ರವಾಹ ದಾಖಲಿಸಿ."},{"en":"Near breakdown take readings in small steps; above it, note how little the voltage changes while the current grows.","hi":"भंजन के पास छोटे चरणों में पाठ्यांक लें; उसके ऊपर देखें कि धारा बढ़ने पर वोल्टता कितनी कम बदलती है।","kn":"ಭಂಜನದ ಹತ್ತಿರ ಸಣ್ಣ ಹಂತಗಳಲ್ಲಿ ಓದು ತೆಗೆದುಕೊಳ್ಳಿ; ಅದರ ಮೇಲೆ ಪ್ರವಾಹ ಹೆಚ್ಚಿದರೂ ವೋಲ್ಟೇಜ್ ಎಷ್ಟು ಕಡಿಮೆ ಬದಲಾಗುತ್ತದೆ ಗಮನಿಸಿ."},{"en":"Also take a few forward-bias readings.","hi":"कुछ अग्र अभिनति पाठ्यांक भी लें।","kn":"ಕೆಲವು ಮುಮ್ಮುಖ ಬಯಾಸ್ ಓದುಗಳನ್ನೂ ತೆಗೆದುಕೊಳ್ಳಿ."},{"en":"Plot I against V and read the breakdown voltage Vz where the reverse curve turns steeply down.","hi":"I और V का ग्राफ़ बनाएँ और भंजन वोल्टता Vz वहाँ पढ़ें जहाँ पश्च वक्र तेज़ी से नीचे मुड़ता है।","kn":"I ಮತ್ತು V ನಕ್ಷೆ ಎಳೆದು, ಹಿಮ್ಮುಖ ವಕ್ರ ಕಡಿದಾಗಿ ಕೆಳಗೆ ತಿರುಗುವಲ್ಲಿ ಭಂಜನ ವೋಲ್ಟೇಜ್ Vz ಓದಿ."}],"precautions":[{"en":"Never let the current exceed the rated value of the device; always keep the series resistor in the circuit.","hi":"धारा कभी भी युक्ति के निर्धारित मान से अधिक न होने दें; श्रेणी प्रतिरोधक सदा परिपथ में रखें।","kn":"ಪ್ರವಾಹ ಸಾಧನದ ನಿಗದಿತ ಮೌಲ್ಯವನ್ನು ಎಂದೂ ಮೀರಬಾರದು; ಸರಣಿ ರೋಧಕವನ್ನು ಯಾವಾಗಲೂ ಮಂಡಲದಲ್ಲಿಡಿ."},{"en":"Keep the Zener current below its rated maximum (power = Vz × I).","hi":"ज़ेनर धारा को उसकी अधिकतम सीमा से नीचे रखें (शक्ति = Vz × I)।","kn":"ಜೀನರ್ ಪ್ರವಾಹವನ್ನು ಅದರ ಗರಿಷ್ಠ ಮಿತಿಗಿಂತ ಕಡಿಮೆ ಇಡಿ (ಶಕ್ತಿ = Vz × I)."},{"en":"Connect meters with + to + and choose a range larger than the expected reading.","hi":"मीटर + से + जोड़ें और अपेक्षित पाठ्यांक से बड़ी परास चुनें।","kn":"ಮೀಟರ್‌ಗಳನ್ನು + ರಿಂದ + ಗೆ ಜೋಡಿಸಿ, ನಿರೀಕ್ಷಿತ ಓದಿಗಿಂತ ದೊಡ್ಡ ವ್ಯಾಪ್ತಿ ಆರಿಸಿ."}],"conclusion":{"en":"In reverse bias the Zener current stays tiny up to Vz; beyond it the current rises sharply at an almost constant voltage, so the Zener can hold a load voltage steady.","hi":"पश्च अभिनति में Vz तक ज़ेनर धारा बहुत छोटी रहती है; उसके बाद लगभग स्थिर वोल्टता पर धारा तेज़ी से बढ़ती है, इसलिए ज़ेनर लोड वोल्टता को स्थिर रख सकता है।","kn":"ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ Vz ವರೆಗೆ ಜೀನರ್ ಪ್ರವಾಹ ಅತಿ ಸಣ್ಣ; ಅದರ ಆಚೆ ಬಹುತೇಕ ಸ್ಥಿರ ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ ಪ್ರವಾಹ ವೇಗವಾಗಿ ಏರುತ್ತದೆ, ಆದ್ದರಿಂದ ಜೀನರ್ ಲೋಡ್ ವೋಲ್ಟೇಜನ್ನು ಸ್ಥಿರವಾಗಿಡಬಲ್ಲದು."},"viva":[{"q":{"en":"How is a Zener diode different from an ordinary diode?","hi":"ज़ेनर डायोड साधारण डायोड से कैसे भिन्न है?","kn":"ಜೀನರ್ ಡಯೋಡ್ ಸಾಮಾನ್ಯ ಡಯೋಡ್‌ಗಿಂತ ಹೇಗೆ ಭಿನ್ನ?"},"a":{"en":"It is heavily doped and designed to work safely in reverse breakdown.","hi":"यह भारी मादित होता है और पश्च भंजन में सुरक्षित काम करने के लिए बना है।","kn":"ಅದು ಹೆಚ್ಚು ಡೋಪ್ ಮಾಡಲ್ಪಟ್ಟಿದ್ದು ಹಿಮ್ಮುಖ ಭಂಜನದಲ್ಲಿ ಸುರಕ್ಷಿತವಾಗಿ ಕೆಲಸ ಮಾಡಲು ವಿನ್ಯಾಸಗೊಂಡಿದೆ."}},{"q":{"en":"How is a Zener connected as a voltage regulator?","hi":"वोल्टता नियंत्रक के रूप में ज़ेनर कैसे जोड़ा जाता है?","kn":"ವೋಲ್ಟೇಜ್ ನಿಯಂತ್ರಕವಾಗಿ ಜೀನರನ್ನು ಹೇಗೆ ಜೋಡಿಸುತ್ತಾರೆ?"},"a":{"en":"In reverse bias, in parallel with the load, with a series resistor from the supply.","hi":"पश्च अभिनति में, लोड के समानांतर, आपूर्ति से एक श्रेणी प्रतिरोधक के साथ।","kn":"ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ, ಲೋಡ್‌ಗೆ ಸಮಾಂತರವಾಗಿ, ಪೂರೈಕೆಯಿಂದ ಸರಣಿ ರೋಧಕದೊಂದಿಗೆ."}},{"q":{"en":"What is the dynamic resistance of a Zener after breakdown?","hi":"भंजन के बाद ज़ेनर का गतिक प्रतिरोध कैसा होता है?","kn":"ಭಂಜನದ ನಂತರ ಜೀನರ್‌ನ ಚಲನಶೀಲ ರೋಧ ಹೇಗಿರುತ್ತದೆ?"},"a":{"en":"Very small: a large change of current makes only a small change of voltage.","hi":"बहुत छोटा: धारा के बड़े परिवर्तन से वोल्टता में बहुत कम परिवर्तन होता है।","kn":"ಅತಿ ಸಣ್ಣ: ಪ್ರವಾಹದ ದೊಡ್ಡ ಬದಲಾವಣೆ ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ ಸ್ವಲ್ಪವೇ ಬದಲಾವಣೆ ತರುತ್ತದೆ."}}]},{"id":"led-characteristics","bench":"diode","setup":{"device":"led"},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ka-puc"],"reviewed":false,"keywords":["led","light emitting diode","optoelectronic devices","band gap","semiconductor electronics"],"title":{"en":"I–V characteristics of LEDs","hi":"LED के I–V अभिलक्षण","kn":"LED ಗಳ I–V ಲಕ್ಷಣಗಳು"},"summary":{"en":"Compare red, yellow, green and blue LEDs: each switches on at a different voltage.","hi":"लाल, पीले, हरे और नीले LED की तुलना करें: हर एक अलग वोल्टता पर जलता है।","kn":"ಕೆಂಪು, ಹಳದಿ, ಹಸಿರು ಮತ್ತು ನೀಲಿ LED ಗಳನ್ನು ಹೋಲಿಸಿ: ಪ್ರತಿಯೊಂದೂ ಬೇರೆ ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ ಬೆಳಗುತ್ತದೆ."},"aim":{"en":"To draw the forward I–V characteristics of LEDs of different colours and relate the turn-on voltage to the colour.","hi":"विभिन्न रंगों के LED के अग्र I–V अभिलक्षण खींचना और चालू होने की वोल्टता का रंग से संबंध देखना।","kn":"ಬೇರೆ ಬೇರೆ ಬಣ್ಣಗಳ LED ಗಳ ಮುಮ್ಮುಖ I–V ಲಕ್ಷಣಗಳನ್ನು ಎಳೆದು, ಆರಂಭ ವೋಲ್ಟೇಜನ್ನು ಬಣ್ಣದೊಂದಿಗೆ ಸಂಬಂಧಿಸುವುದು."},"principle":{"en":"In an LED, electrons and holes recombine at the junction and give out photons of energy close to the band gap, E = hc/λ. Light of shorter wavelength (blue) needs a larger band gap, so a blue LED switches on at a higher voltage (about 2.6 V) than a red one (about 1.9 V).","hi":"LED में इलेक्ट्रॉन और होल संधि पर पुनर्संयोजित होकर बैंड अंतराल के निकट ऊर्जा के फ़ोटॉन देते हैं, E = hc/λ. छोटी तरंगदैर्घ्य (नीला) के प्रकाश के लिए बड़ा बैंड अंतराल चाहिए, इसलिए नीला LED लाल (लगभग 1.9 V) से अधिक वोल्टता (लगभग 2.6 V) पर जलता है।","kn":"LED ಯಲ್ಲಿ ಎಲೆಕ್ಟ್ರಾನ್ ಮತ್ತು ರಂಧ್ರಗಳು ಸಂಧಿಯಲ್ಲಿ ಮರುಸಂಯೋಗಗೊಂಡು ಬ್ಯಾಂಡ್ ಅಂತರದ ಹತ್ತಿರದ ಶಕ್ತಿಯ ಫೋಟಾನ್‌ಗಳನ್ನು ನೀಡುತ್ತವೆ, E = hc/λ. ಕಡಿಮೆ ತರಂಗಾಂತರದ (ನೀಲಿ) ಬೆಳಕಿಗೆ ದೊಡ್ಡ ಬ್ಯಾಂಡ್ ಅಂತರ ಬೇಕು; ಆದ್ದರಿಂದ ನೀಲಿ LED ಕೆಂಪಿಗಿಂತ (ಸುಮಾರು 1.9 V) ಹೆಚ್ಚು ವೋಲ್ಟೇಜ್‌ನಲ್ಲಿ (ಸುಮಾರು 2.6 V) ಬೆಳಗುತ್ತದೆ."},"apparatus":[{"en":"Red, yellow, green and blue LEDs","hi":"लाल, पीले, हरे और नीले LED","kn":"ಕೆಂಪು, ಹಳದಿ, ಹಸಿರು ಮತ್ತು ನೀಲಿ LED ಗಳು"},{"en":"Variable DC power supply (0–10 V)","hi":"परिवर्ती DC विद्युत आपूर्ति (0–10 V)","kn":"ಬದಲಾಯಿಸಬಹುದಾದ DC ವಿದ್ಯುತ್ ಪೂರೈಕೆ (0–10 V)"},{"en":"Series resistor (100 Ω) to limit the current","hi":"धारा सीमित करने के लिए श्रेणी प्रतिरोधक (100 Ω)","kn":"ಪ್ರವಾಹ ಮಿತಿಗೊಳಿಸಲು ಸರಣಿ ರೋಧಕ (100 Ω)"},{"en":"Milliammeter (and microammeter)","hi":"मिलीऐमीटर (और माइक्रोऐमीटर)","kn":"ಮಿಲಿಅಮ್ಮೀಟರ್ (ಮತ್ತು ಮೈಕ್ರೋಅಮ್ಮೀಟರ್)"},{"en":"Voltmeter","hi":"वोल्टमीटर","kn":"ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect the red LED in forward bias (long leg to +) with the resistor and milliammeter; voltmeter across the LED.","hi":"लाल LED को अग्र अभिनति में (लंबी टाँग + से) प्रतिरोधक और मिलीऐमीटर के साथ जोड़ें; वोल्टमीटर LED के सिरों पर।","kn":"ಕೆಂಪು LED ಯನ್ನು ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ (ಉದ್ದ ಕಾಲು + ಗೆ) ರೋಧಕ ಮತ್ತು ಮಿಲಿಅಮ್ಮೀಟರ್ ಜೊತೆ ಜೋಡಿಸಿ; ವೋಲ್ಟ್‌ಮೀಟರ್ LED ಗೆ ಅಡ್ಡಲಾಗಿ."},{"en":"Raise the supply in steps and record V and I; note when the LED starts to glow.","hi":"आपूर्ति चरणों में बढ़ाएँ और V तथा I लिखें; देखें कि LED कब चमकने लगता है।","kn":"ಪೂರೈಕೆಯನ್ನು ಹಂತಗಳಲ್ಲಿ ಹೆಚ್ಚಿಸಿ V ಮತ್ತು I ದಾಖಲಿಸಿ; LED ಯಾವಾಗ ಹೊಳೆಯಲು ಆರಂಭಿಸುತ್ತದೆ ಗಮನಿಸಿ."},{"en":"Repeat for the yellow, green and blue LEDs.","hi":"पीले, हरे और नीले LED के लिए दोहराएँ।","kn":"ಹಳದಿ, ಹಸಿರು ಮತ್ತು ನೀಲಿ LED ಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Plot all four curves and compare their knee voltages with hc/λe.","hi":"चारों वक्र बनाएँ और उनकी घुटना वोल्टताओं की तुलना hc/λe से करें।","kn":"ನಾಲ್ಕೂ ವಕ್ರಗಳನ್ನು ಎಳೆದು ಅವುಗಳ ನೀ ವೋಲ್ಟೇಜ್‌ಗಳನ್ನು hc/λe ಯೊಂದಿಗೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Never let the current exceed the rated value of the device; always keep the series resistor in the circuit.","hi":"धारा कभी भी युक्ति के निर्धारित मान से अधिक न होने दें; श्रेणी प्रतिरोधक सदा परिपथ में रखें।","kn":"ಪ್ರವಾಹ ಸಾಧನದ ನಿಗದಿತ ಮೌಲ್ಯವನ್ನು ಎಂದೂ ಮೀರಬಾರದು; ಸರಣಿ ರೋಧಕವನ್ನು ಯಾವಾಗಲೂ ಮಂಡಲದಲ್ಲಿಡಿ."},{"en":"Do not look straight into a bright LED for long.","hi":"तेज़ चमकते LED में देर तक सीधे न देखें।","kn":"ಪ್ರಕಾಶಮಾನ LED ಯೊಳಗೆ ಹೆಚ್ಚು ಹೊತ್ತು ನೇರವಾಗಿ ನೋಡಬೇಡಿ."},{"en":"An LED breaks down at a small reverse voltage (about 5 V): do not reverse-bias it far.","hi":"LED छोटी पश्च वोल्टता (लगभग 5 V) पर ही भंजित हो जाता है: उसे अधिक पश्च अभिनति न दें।","kn":"LED ಸಣ್ಣ ಹಿಮ್ಮುಖ ವೋಲ್ಟೇಜ್‌ನಲ್ಲೇ (ಸುಮಾರು 5 V) ಭಂಜನಗೊಳ್ಳುತ್ತದೆ: ಹೆಚ್ಚು ಹಿಮ್ಮುಖ ಬಯಾಸ್ ನೀಡಬೇಡಿ."}],"conclusion":{"en":"Each LED conducts and glows only above its knee voltage, and the knee voltage increases from red to blue as the photon energy hc/λ increases.","hi":"हर LED अपनी घुटना वोल्टता के ऊपर ही चालन करता और चमकता है, और फ़ोटॉन ऊर्जा hc/λ बढ़ने के साथ घुटना वोल्टता लाल से नीले की ओर बढ़ती है।","kn":"ಪ್ರತಿ LED ತನ್ನ ನೀ ವೋಲ್ಟೇಜ್ ಮೇಲೆ ಮಾತ್ರ ವಾಹಕವಾಗಿ ಹೊಳೆಯುತ್ತದೆ; ಫೋಟಾನ್ ಶಕ್ತಿ hc/λ ಹೆಚ್ಚಿದಂತೆ ನೀ ವೋಲ್ಟೇಜ್ ಕೆಂಪಿನಿಂದ ನೀಲಿಯತ್ತ ಹೆಚ್ಚುತ್ತದೆ."},"viva":[{"q":{"en":"Why does a blue LED need more voltage than a red one?","hi":"नीले LED को लाल से अधिक वोल्टता क्यों चाहिए?","kn":"ನೀಲಿ LED ಗೆ ಕೆಂಪಿಗಿಂತ ಹೆಚ್ಚು ವೋಲ್ಟೇಜ್ ಏಕೆ ಬೇಕು?"},"a":{"en":"Blue photons have more energy (shorter wavelength), so the band gap is larger.","hi":"नीले फ़ोटॉन की ऊर्जा अधिक (तरंगदैर्घ्य छोटी) है, इसलिए बैंड अंतराल बड़ा है।","kn":"ನೀಲಿ ಫೋಟಾನ್‌ಗಳಿಗೆ ಹೆಚ್ಚು ಶಕ್ತಿ (ಕಡಿಮೆ ತರಂಗಾಂತರ), ಆದ್ದರಿಂದ ಬ್ಯಾಂಡ್ ಅಂತರ ದೊಡ್ಡದು."}},{"q":{"en":"Why are LEDs not made of silicon?","hi":"LED सिलिकॉन से क्यों नहीं बनाए जाते?","kn":"LED ಗಳನ್ನು ಸಿಲಿಕಾನ್‌ನಿಂದ ಏಕೆ ಮಾಡುವುದಿಲ್ಲ?"},"a":{"en":"Silicon has an indirect band gap and gives out heat rather than light; compounds like GaAsP and InGaN are used.","hi":"सिलिकॉन का बैंड अंतराल अप्रत्यक्ष है और यह प्रकाश की जगह ऊष्मा देता है; GaAsP और InGaN जैसे यौगिक प्रयोग होते हैं।","kn":"ಸಿಲಿಕಾನ್‌ನ ಬ್ಯಾಂಡ್ ಅಂತರ ಪರೋಕ್ಷ; ಅದು ಬೆಳಕಿಗಿಂತ ಉಷ್ಣ ನೀಡುತ್ತದೆ; GaAsP, InGaN ನಂತಹ ಸಂಯುಕ್ತಗಳನ್ನು ಬಳಸುತ್ತಾರೆ."}},{"q":{"en":"Why is a resistor always used with an LED?","hi":"LED के साथ सदा प्रतिरोधक क्यों लगाया जाता है?","kn":"LED ಜೊತೆ ಯಾವಾಗಲೂ ರೋಧಕ ಏಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"Above the knee the current rises very steeply; the resistor limits it.","hi":"घुटने के ऊपर धारा बहुत तेज़ी से बढ़ती है; प्रतिरोधक उसे सीमित करता है।","kn":"ನೀ ಮೇಲೆ ಪ್ರವಾಹ ಅತಿ ವೇಗವಾಗಿ ಏರುತ್ತದೆ; ರೋಧಕ ಅದನ್ನು ಮಿತಿಗೊಳಿಸುತ್ತದೆ."}}]},{"id":"planck-constant-led","bench":"planck","setup":{},"subject":"Physics","domain":"physics","levels":["ug"],"mode":"guided","curricula":["ug-physics"],"reviewed":false,"keywords":["planck's constant","planck constant","led","photon energy","quantum","modern physics"],"title":{"en":"Planck's constant using LEDs","hi":"LED से प्लांक नियतांक","kn":"LED ಗಳಿಂದ ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕ"},"summary":{"en":"Find the voltage at which LEDs of four colours just glow, and get h from the slope of V against 1/λ.","hi":"चार रंगों के LED जिस वोल्टता पर बस चमकने लगते हैं वह ज्ञात करें, और V तथा 1/λ के ग्राफ़ की प्रवणता से h निकालें।","kn":"ನಾಲ್ಕು ಬಣ್ಣಗಳ LED ಗಳು ಕೇವಲ ಹೊಳೆಯಲಾರಂಭಿಸುವ ವೋಲ್ಟೇಜ್ ಕಂಡುಹಿಡಿದು, V ಮತ್ತು 1/λ ನಕ್ಷೆಯ ಇಳಿಜಾರಿನಿಂದ h ಪಡೆಯಿರಿ."},"aim":{"en":"To determine Planck's constant from the threshold voltages of LEDs of known wavelengths.","hi":"ज्ञात तरंगदैर्घ्य वाले LED की देहली वोल्टताओं से प्लांक नियतांक ज्ञात करना।","kn":"ತಿಳಿದ ತರಂಗಾಂತರದ LED ಗಳ ಹೊಸ್ತಿಲು ವೋಲ್ಟೇಜ್‌ಗಳಿಂದ ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕ ನಿರ್ಧರಿಸುವುದು."},"principle":{"en":"An LED starts to emit when the energy eV given to each electron equals the photon energy: eV = hc/λ. So V = (hc/e)(1/λ): a graph of the threshold voltage against 1/λ is a straight line of slope hc/e, and h = e × slope ÷ c. A small constant offset (the \"just glowing\" judgement) shifts the intercept but not the slope.","hi":"LED उत्सर्जन तब शुरू करता है जब हर इलेक्ट्रॉन को दी गई ऊर्जा eV फ़ोटॉन ऊर्जा के बराबर हो: eV = hc/λ. इसलिए V = (hc/e)(1/λ): देहली वोल्टता और 1/λ का ग्राफ़ hc/e प्रवणता की सीधी रेखा है, और h = e × प्रवणता ÷ c. एक छोटा स्थिर अंतर (\"बस चमकना\" का अनुमान) अंतःखंड बदलता है, प्रवणता नहीं।","kn":"ಪ್ರತಿ ಎಲೆಕ್ಟ್ರಾನ್‌ಗೆ ನೀಡಿದ ಶಕ್ತಿ eV ಫೋಟಾನ್ ಶಕ್ತಿಗೆ ಸಮವಾದಾಗ LED ಹೊರಸೂಸಲು ಆರಂಭಿಸುತ್ತದೆ: eV = hc/λ. ಆದ್ದರಿಂದ V = (hc/e)(1/λ): ಹೊಸ್ತಿಲು ವೋಲ್ಟೇಜ್ ಮತ್ತು 1/λ ನಕ್ಷೆ hc/e ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ; h = e × ಇಳಿಜಾರು ÷ c. ಸಣ್ಣ ಸ್ಥಿರ ವ್ಯತ್ಯಾಸ (\"ಕೇವಲ ಹೊಳೆಯುವಿಕೆ\" ಅಂದಾಜು) ಅಂತಃಖಂಡವನ್ನು ಬದಲಿಸುತ್ತದೆ, ಇಳಿಜಾರನ್ನಲ್ಲ."},"apparatus":[{"en":"LEDs of known wavelength (625, 590, 525, 470 nm)","hi":"ज्ञात तरंगदैर्घ्य वाले LED (625, 590, 525, 470 nm)","kn":"ತಿಳಿದ ತರಂಗಾಂತರದ LED ಗಳು (625, 590, 525, 470 nm)"},{"en":"DC supply with fine control (0–3.5 V)","hi":"सूक्ष्म नियंत्रण वाली DC आपूर्ति (0–3.5 V)","kn":"ಸೂಕ್ಷ್ಮ ನಿಯಂತ್ರಣದ DC ಪೂರೈಕೆ (0–3.5 V)"},{"en":"Series resistor (100 Ω) to limit the current","hi":"धारा सीमित करने के लिए श्रेणी प्रतिरोधक (100 Ω)","kn":"ಪ್ರವಾಹ ಮಿತಿಗೊಳಿಸಲು ಸರಣಿ ರೋಧಕ (100 Ω)"},{"en":"Milliammeter (and microammeter)","hi":"मिलीऐमीटर (और माइक्रोऐमीटर)","kn":"ಮಿಲಿಅಮ್ಮೀಟರ್ (ಮತ್ತು ಮೈಕ್ರೋಅಮ್ಮೀಟರ್)"},{"en":"Digital voltmeter","hi":"अंकीय वोल्टमीटर","kn":"ಡಿಜಿಟಲ್ ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"A dark box or tube to view the LED","hi":"LED देखने के लिए अँधेरा बॉक्स या नली","kn":"LED ನೋಡಲು ಕತ್ತಲ ಪೆಟ್ಟಿಗೆ ಅಥವಾ ಕೊಳವೆ"}],"steps":[{"en":"Connect the first LED in forward bias through the resistor; put the voltmeter across the LED.","hi":"पहले LED को प्रतिरोधक के साथ अग्र अभिनति में जोड़ें; वोल्टमीटर LED के सिरों पर लगाएँ।","kn":"ಮೊದಲ LED ಯನ್ನು ರೋಧಕದ ಜೊತೆ ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಜೋಡಿಸಿ; ವೋಲ್ಟ್‌ಮೀಟರ್ LED ಗೆ ಅಡ್ಡಲಾಗಿ."},{"en":"Looking into the dark box, raise the voltage very slowly until the LED just begins to glow. Record that voltage.","hi":"अँधेरे बॉक्स में देखते हुए वोल्टता बहुत धीरे बढ़ाएँ जब तक LED बस चमकने न लगे। वह वोल्टता लिखें।","kn":"ಕತ್ತಲ ಪೆಟ್ಟಿಗೆಯೊಳಗೆ ನೋಡುತ್ತಾ LED ಕೇವಲ ಹೊಳೆಯಲಾರಂಭಿಸುವವರೆಗೆ ವೋಲ್ಟೇಜನ್ನು ತುಂಬ ನಿಧಾನವಾಗಿ ಹೆಚ್ಚಿಸಿ. ಆ ವೋಲ್ಟೇಜ್ ದಾಖಲಿಸಿ."},{"en":"Repeat two or three times for each colour and take the mean.","hi":"हर रंग के लिए दो-तीन बार दोहराएँ और माध्य लें।","kn":"ಪ್ರತಿ ಬಣ್ಣಕ್ಕೆ ಎರಡು-ಮೂರು ಬಾರಿ ಪುನರಾವರ್ತಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ."},{"en":"Plot the threshold voltage against 1/λ and draw the best straight line.","hi":"देहली वोल्टता और 1/λ का ग्राफ़ बनाकर सर्वोत्तम सीधी रेखा खींचें।","kn":"ಹೊಸ್ತಿಲು ವೋಲ್ಟೇಜ್ ಮತ್ತು 1/λ ನಕ್ಷೆ ಎಳೆದು ಉತ್ತಮ ಸರಳರೇಖೆ ಎಳೆಯಿರಿ."},{"en":"Find the slope and its uncertainty, then h = e × slope ÷ c.","hi":"प्रवणता और उसकी अनिश्चितता ज्ञात करें, फिर h = e × प्रवणता ÷ c.","kn":"ಇಳಿಜಾರು ಮತ್ತು ಅದರ ಅನಿಶ್ಚಿತತೆ ಕಂಡುಹಿಡಿದು, h = e × ಇಳಿಜಾರು ÷ c."},{"en":"Export the readings as CSV for your record book.","hi":"अपनी रिकॉर्ड पुस्तिका के लिए पाठ्यांक CSV में निर्यात करें।","kn":"ನಿಮ್ಮ ದಾಖಲೆ ಪುಸ್ತಕಕ್ಕಾಗಿ ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ."}],"precautions":[{"en":"Judge \"just glowing\" the same way for every LED, in the dark.","hi":"\"बस चमकना\" हर LED के लिए अँधेरे में एक ही तरह आँकें।","kn":"\"ಕೇವಲ ಹೊಳೆಯುವಿಕೆ\"ಯನ್ನು ಪ್ರತಿ LED ಗೆ ಕತ್ತಲಲ್ಲಿ ಒಂದೇ ರೀತಿ ನಿರ್ಣಯಿಸಿ."},{"en":"Never let the current exceed the rated value of the device; always keep the series resistor in the circuit.","hi":"धारा कभी भी युक्ति के निर्धारित मान से अधिक न होने दें; श्रेणी प्रतिरोधक सदा परिपथ में रखें।","kn":"ಪ್ರವಾಹ ಸಾಧನದ ನಿಗದಿತ ಮೌಲ್ಯವನ್ನು ಎಂದೂ ಮೀರಬಾರದು; ಸರಣಿ ರೋಧಕವನ್ನು ಯಾವಾಗಲೂ ಮಂಡಲದಲ್ಲಿಡಿ."},{"en":"Use the manufacturer's peak wavelength for each LED.","hi":"हर LED के लिए निर्माता द्वारा दी गई शिखर तरंगदैर्घ्य लें।","kn":"ಪ್ರತಿ LED ಗೆ ತಯಾರಕರ ಶಿಖರ ತರಂಗಾಂತರ ಬಳಸಿ."}],"conclusion":{"en":"The threshold voltage is proportional to 1/λ, and the slope gives Planck’s constant close to 6.63 × 10⁻³⁴ J s, within the uncertainty of the fit.","hi":"देहली वोल्टता 1/λ के अनुक्रमानुपाती है, और प्रवणता से प्लांक नियतांक 6.63 × 10⁻³⁴ J s के निकट, फ़िट की अनिश्चितता के भीतर, मिलता है।","kn":"ಹೊಸ್ತಿಲು ವೋಲ್ಟೇಜ್ 1/λ ಗೆ ಅನುಪಾತೀಯ; ಇಳಿಜಾರು ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕವನ್ನು 6.63 × 10⁻³⁴ J s ಹತ್ತಿರ, ಹೊಂದಿಕೆಯ ಅನಿಶ್ಚಿತತೆಯೊಳಗೆ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"What are the units of Planck’s constant?","hi":"प्लांक नियतांक की इकाई क्या है?","kn":"ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕದ ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"Joule second (J s).","hi":"जूल सेकंड (J s).","kn":"ಜೂಲ್ ಸೆಕೆಂಡ್ (J s)."}},{"q":{"en":"Why do we use the slope and not one LED’s voltage?","hi":"हम एक LED की वोल्टता के बजाय प्रवणता क्यों लेते हैं?","kn":"ಒಂದು LED ಯ ವೋಲ್ಟೇಜ್ ಬದಲು ಇಳಿಜಾರನ್ನು ಏಕೆ ಬಳಸುತ್ತೇವೆ?"},"a":{"en":"A constant error in judging the threshold cancels out of the slope.","hi":"देहली के अनुमान में स्थिर त्रुटि प्रवणता में से कट जाती है।","kn":"ಹೊಸ್ತಿಲು ಅಂದಾಜಿನ ಸ್ಥಿರ ದೋಷ ಇಳಿಜಾರಿನಲ್ಲಿ ರದ್ದಾಗುತ್ತದೆ."}},{"q":{"en":"What is the energy of a 500 nm photon in eV?","hi":"500 nm फ़ोटॉन की ऊर्जा eV में कितनी है?","kn":"500 nm ಫೋಟಾನ್‌ನ ಶಕ್ತಿ eV ಯಲ್ಲಿ ಎಷ್ಟು?"},"a":{"en":"About 2.48 eV (1240 ÷ 500).","hi":"लगभग 2.48 eV (1240 ÷ 500).","kn":"ಸುಮಾರು 2.48 eV (1240 ÷ 500)."}}]},{"id":"half-wave-rectifier","bench":"rectifier","setup":{"type":"half"},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["rectifier","half-wave rectifier","half wave rectifier","diode as a rectifier","ripple factor","filter"],"title":{"en":"Half-wave rectifier","hi":"अर्ध-तरंग दिष्टकारी","kn":"ಅರ್ಧ-ತರಂಗ ಸರಿಪಡಿಸುವ ಸಾಧನ"},"summary":{"en":"One diode passes only the positive half-cycles of AC; see the output on a CRO and smooth it with a capacitor.","hi":"एक डायोड AC के केवल धनात्मक अर्ध-चक्र जाने देता है; CRO पर निर्गत देखें और संधारित्र से उसे समतल करें।","kn":"ಒಂದು ಡಯೋಡ್ AC ಯ ಧನಾತ್ಮಕ ಅರ್ಧ-ಚಕ್ರಗಳನ್ನು ಮಾತ್ರ ಬಿಡುತ್ತದೆ; CRO ನಲ್ಲಿ ಹೊರಹರಿವು ನೋಡಿ, ಧಾರಕದಿಂದ ಅದನ್ನು ನಯಗೊಳಿಸಿ."},"aim":{"en":"To study a half-wave rectifier, find its DC output and ripple factor with and without a capacitor filter.","hi":"अर्ध-तरंग दिष्टकारी का अध्ययन करना, संधारित्र फ़िल्टर के साथ और बिना उसका DC निर्गत और ऊर्मिका गुणांक ज्ञात करना।","kn":"ಅರ್ಧ-ತರಂಗ ಸರಿಪಡಿಸುವ ಸಾಧನವನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ, ಧಾರಕ ಫಿಲ್ಟರ್ ಸಹಿತ ಮತ್ತು ರಹಿತ ಅದರ DC ಹೊರಹರಿವು ಮತ್ತು ತರಂಗ ಅಂಶ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"A diode conducts only when forward-biased, so it passes the positive half-cycles and blocks the negative ones. The output is pulsating DC with Vdc = Vm/π and ripple factor γ = 1.21. A capacitor across the load reduces the ripple to about 1/(2√3 f RL C).","hi":"डायोड केवल अग्र अभिनति में चालन करता है, इसलिए धनात्मक अर्ध-चक्र जाने देता है और ऋणात्मक रोक देता है। निर्गत स्पंदित DC है जिसमें Vdc = Vm/π और ऊर्मिका गुणांक γ = 1.21. लोड के सिरों पर संधारित्र ऊर्मिका को लगभग 1/(2√3 f RL C) तक घटा देता है।","kn":"ಡಯೋಡ್ ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿ ಮಾತ್ರ ವಾಹಕ; ಆದ್ದರಿಂದ ಧನಾತ್ಮಕ ಅರ್ಧ-ಚಕ್ರಗಳನ್ನು ಬಿಟ್ಟು ಋಣಾತ್ಮಕವನ್ನು ತಡೆಯುತ್ತದೆ. ಹೊರಹರಿವು ಸ್ಪಂದಿಸುವ DC: Vdc = Vm/π, ತರಂಗ ಅಂಶ γ = 1.21. ಲೋಡ್‌ಗೆ ಅಡ್ಡ ಧಾರಕ ತರಂಗವನ್ನು ಸುಮಾರು 1/(2√3 f RL C) ಗೆ ಇಳಿಸುತ್ತದೆ."},"apparatus":[{"en":"Silicon diode (1N4007)","hi":"सिलिकॉन डायोड (1N4007)","kn":"ಸಿಲಿಕಾನ್ ಡಯೋಡ್ (1N4007)"},{"en":"Step-down transformer (230 V to 6/9/12 V)","hi":"अपचायी ट्रांसफ़ॉर्मर (230 V से 6/9/12 V)","kn":"ಇಳಿಕೆ ಪರಿವರ್ತಕ (230 V ನಿಂದ 6/9/12 V)"},{"en":"Load resistors (470 Ω, 1 kΩ, 2.2 kΩ)","hi":"लोड प्रतिरोधक (470 Ω, 1 kΩ, 2.2 kΩ)","kn":"ಲೋಡ್ ರೋಧಕಗಳು (470 Ω, 1 kΩ, 2.2 kΩ)"},{"en":"Electrolytic capacitors (100, 470, 1000 µF)","hi":"विद्युत-अपघटनी संधारित्र (100, 470, 1000 µF)","kn":"ವಿದ್ಯುದ್ವಿಭಜಕ ಧಾರಕಗಳು (100, 470, 1000 µF)"},{"en":"Multimeter (AC and DC)","hi":"मल्टीमीटर (AC और DC)","kn":"ಮಲ್ಟಿಮೀಟರ್ (AC ಮತ್ತು DC)"},{"en":"Cathode-ray oscilloscope (CRO)","hi":"कैथोड किरण दोलनदर्शी (CRO)","kn":"ಕ್ಯಾಥೋಡ್ ಕಿರಣ ಆಂದೋಲನದರ್ಶಕ (CRO)"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect the transformer secondary, the diode and the load resistor in series.","hi":"ट्रांसफ़ॉर्मर की द्वितीयक कुंडली, डायोड और लोड प्रतिरोधक को श्रेणी में जोड़ें।","kn":"ಪರಿವರ್ತಕದ ದ್ವಿತೀಯಕ ಸುರುಳಿ, ಡಯೋಡ್ ಮತ್ತು ಲೋಡ್ ರೋಧಕವನ್ನು ಸರಣಿಯಲ್ಲಿ ಜೋಡಿಸಿ."},{"en":"Show the input and the output together on the two channels of the CRO.","hi":"CRO के दो चैनलों पर निवेश और निर्गत साथ-साथ दिखाएँ।","kn":"CRO ಯ ಎರಡು ಚಾನಲ್‌ಗಳಲ್ಲಿ ಒಳಹರಿವು ಮತ್ತು ಹೊರಹರಿವನ್ನು ಜೊತೆಯಾಗಿ ತೋರಿಸಿ."},{"en":"Read the DC voltage across the load and look at the output on the CRO.","hi":"लोड के सिरों की DC वोल्टता पढ़ें और CRO पर निर्गत देखें।","kn":"ಲೋಡ್‌ಗೆ ಅಡ್ಡ DC ವೋಲ್ಟೇಜ್ ಓದಿ, CRO ನಲ್ಲಿ ಹೊರಹರಿವನ್ನು ನೋಡಿ."},{"en":"Measure the AC ripple voltage across the load and work out the ripple factor γ = Vac ÷ Vdc.","hi":"लोड के सिरों पर AC ऊर्मिका वोल्टता मापें और ऊर्मिका गुणांक γ = Vac ÷ Vdc निकालें।","kn":"ಲೋಡ್‌ಗೆ ಅಡ್ಡ AC ತರಂಗ ವೋಲ್ಟೇಜ್ ಅಳೆಯಿರಿ, ತರಂಗ ಅಂಶ γ = Vac ÷ Vdc ಲೆಕ್ಕಿಸಿ."},{"en":"Connect filter capacitors of 100, 470 and 1000 µF across the load in turn and repeat.","hi":"बारी-बारी से 100, 470 और 1000 µF के फ़िल्टर संधारित्र लोड के सिरों पर जोड़कर दोहराएँ।","kn":"ಸರದಿಯಾಗಿ 100, 470 ಮತ್ತು 1000 µF ಫಿಲ್ಟರ್ ಧಾರಕಗಳನ್ನು ಲೋಡ್‌ಗೆ ಅಡ್ಡಲಾಗಿ ಜೋಡಿಸಿ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Change the load resistance and see how the ripple changes.","hi":"लोड प्रतिरोध बदलें और देखें कि ऊर्मिका कैसे बदलती है।","kn":"ಲೋಡ್ ರೋಧ ಬದಲಿಸಿ ತರಂಗ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ನೋಡಿ."}],"precautions":[{"en":"Never touch the 230 V mains side of the transformer.","hi":"ट्रांसफ़ॉर्मर के 230 V मुख्य सिरे को कभी न छुएँ।","kn":"ಪರಿವರ್ತಕದ 230 V ಮುಖ್ಯ ಭಾಗವನ್ನು ಎಂದೂ ಮುಟ್ಟಬೇಡಿ."},{"en":"Connect electrolytic capacitors the right way round (+ to the diode side).","hi":"विद्युत-अपघटनी संधारित्र सही दिशा में जोड़ें (+ डायोड वाले सिरे की ओर)।","kn":"ವಿದ್ಯುದ್ವಿಭಜಕ ಧಾರಕಗಳನ್ನು ಸರಿಯಾದ ದಿಕ್ಕಿನಲ್ಲಿ ಜೋಡಿಸಿ (+ ಡಯೋಡ್ ಕಡೆ)."},{"en":"Use the AC range of the meter for the ripple and the DC range for Vdc.","hi":"ऊर्मिका के लिए मीटर की AC परास और Vdc के लिए DC परास लें।","kn":"ತರಂಗಕ್ಕೆ ಮೀಟರ್‌ನ AC ವ್ಯಾಪ್ತಿ, Vdc ಗೆ DC ವ್ಯಾಪ್ತಿ ಬಳಸಿ."}],"conclusion":{"en":"The half-wave rectifier passes only alternate half-cycles; without a filter the ripple factor is about 1.21, and a capacitor makes the output much smoother and raises Vdc towards the peak.","hi":"अर्ध-तरंग दिष्टकारी केवल एकांतर अर्ध-चक्र जाने देता है; बिना फ़िल्टर ऊर्मिका गुणांक लगभग 1.21 है, और संधारित्र निर्गत को बहुत समतल कर Vdc को शिखर की ओर बढ़ाता है।","kn":"ಅರ್ಧ-ತರಂಗ ಸಾಧನ ಪರ್ಯಾಯ ಅರ್ಧ-ಚಕ್ರಗಳನ್ನು ಮಾತ್ರ ಬಿಡುತ್ತದೆ; ಫಿಲ್ಟರ್ ಇಲ್ಲದೆ ತರಂಗ ಅಂಶ ಸುಮಾರು 1.21; ಧಾರಕ ಹೊರಹರಿವನ್ನು ಬಹಳ ನಯಗೊಳಿಸಿ Vdc ಯನ್ನು ಶಿಖರದತ್ತ ಏರಿಸುತ್ತದೆ."},"viva":[{"q":{"en":"What is ripple?","hi":"ऊर्मिका क्या है?","kn":"ತರಂಗ (ರಿಪಲ್) ಎಂದರೇನು?"},"a":{"en":"The AC part left in the output of a rectifier.","hi":"दिष्टकारी के निर्गत में बचा AC भाग।","kn":"ಸರಿಪಡಿಸುವ ಸಾಧನದ ಹೊರಹರಿವಿನಲ್ಲಿ ಉಳಿದ AC ಭಾಗ."}},{"q":{"en":"How does a capacitor filter work?","hi":"संधारित्र फ़िल्टर कैसे काम करता है?","kn":"ಧಾರಕ ಫಿಲ್ಟರ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?"},"a":{"en":"It charges to the peak and supplies the load between peaks, discharging slowly through RL.","hi":"यह शिखर तक आवेशित होकर शिखरों के बीच लोड को धारा देता है और RL से धीरे-धीरे निरावेशित होता है।","kn":"ಅದು ಶಿಖರದವರೆಗೆ ಆವೇಶಗೊಂಡು ಶಿಖರಗಳ ನಡುವೆ ಲೋಡ್‌ಗೆ ಪ್ರವಾಹ ಒದಗಿಸುತ್ತದೆ; RL ಮೂಲಕ ನಿಧಾನವಾಗಿ ವಿಸರ್ಜನೆಯಾಗುತ್ತದೆ."}},{"q":{"en":"What is the efficiency of a half-wave rectifier at most?","hi":"अर्ध-तरंग दिष्टकारी की अधिकतम दक्षता कितनी है?","kn":"ಅರ್ಧ-ತರಂಗ ಸಾಧನದ ಗರಿಷ್ಠ ದಕ್ಷತೆ ಎಷ್ಟು?"},"a":{"en":"40.6 %.","hi":"40.6 %.","kn":"40.6 %."}}]},{"id":"full-wave-rectifier","bench":"rectifier","setup":{"type":"centre"},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["rectifier","full-wave rectifier","full wave rectifier","centre-tap","center tap","ripple factor","diode as a rectifier"],"title":{"en":"Full-wave rectifier (centre-tap)","hi":"पूर्ण-तरंग दिष्टकारी (मध्य-निष्कासित)","kn":"ಪೂರ್ಣ-ತರಂಗ ಸರಿಪಡಿಸುವ ಸಾಧನ (ಮಧ್ಯ-ಟ್ಯಾಪ್)"},"summary":{"en":"Two diodes and a centre-tapped transformer use both half-cycles; compare the ripple with the half-wave rectifier.","hi":"दो डायोड और मध्य-निष्कासित ट्रांसफ़ॉर्मर दोनों अर्ध-चक्रों का उपयोग करते हैं; ऊर्मिका की तुलना अर्ध-तरंग दिष्टकारी से करें।","kn":"ಎರಡು ಡಯೋಡ್‌ಗಳು ಮತ್ತು ಮಧ್ಯ-ಟ್ಯಾಪ್ ಪರಿವರ್ತಕ ಎರಡೂ ಅರ್ಧ-ಚಕ್ರಗಳನ್ನು ಬಳಸುತ್ತವೆ; ತರಂಗವನ್ನು ಅರ್ಧ-ತರಂಗ ಸಾಧನದೊಂದಿಗೆ ಹೋಲಿಸಿ."},"aim":{"en":"To study a centre-tap full-wave rectifier and find its DC output and ripple factor with and without a filter.","hi":"मध्य-निष्कासित पूर्ण-तरंग दिष्टकारी का अध्ययन करना और फ़िल्टर के साथ तथा बिना उसका DC निर्गत और ऊर्मिका गुणांक ज्ञात करना।","kn":"ಮಧ್ಯ-ಟ್ಯಾಪ್ ಪೂರ್ಣ-ತರಂಗ ಸಾಧನವನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ, ಫಿಲ್ಟರ್ ಸಹಿತ ಮತ್ತು ರಹಿತ ಅದರ DC ಹೊರಹರಿವು ಮತ್ತು ತರಂಗ ಅಂಶ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"The two ends of the secondary are in opposite phase. In one half-cycle D1 conducts, in the other D2, and both send current through the load in the same direction. Vdc = 2Vm/π and γ = 0.48; the ripple is at 100 Hz, so a capacitor smooths it twice as well as in the half-wave case.","hi":"द्वितीयक के दोनों सिरे विपरीत कला में होते हैं। एक अर्ध-चक्र में D1 और दूसरे में D2 चालन करता है, और दोनों लोड में एक ही दिशा में धारा भेजते हैं। Vdc = 2Vm/π और γ = 0.48; ऊर्मिका 100 Hz की होती है, इसलिए संधारित्र उसे अर्ध-तरंग की तुलना में दोगुना अच्छा समतल करता है।","kn":"ದ್ವಿತೀಯಕದ ಎರಡು ತುದಿಗಳು ವಿರುದ್ಧ ಹಂತದಲ್ಲಿರುತ್ತವೆ. ಒಂದು ಅರ್ಧ-ಚಕ್ರದಲ್ಲಿ D1, ಇನ್ನೊಂದರಲ್ಲಿ D2 ವಾಹಕ; ಎರಡೂ ಲೋಡ್‌ನಲ್ಲಿ ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಪ್ರವಾಹ ಕಳುಹಿಸುತ್ತವೆ. Vdc = 2Vm/π, γ = 0.48; ತರಂಗ 100 Hz ನದು, ಆದ್ದರಿಂದ ಧಾರಕ ಅರ್ಧ-ತರಂಗಕ್ಕಿಂತ ಎರಡು ಪಟ್ಟು ಚೆನ್ನಾಗಿ ನಯಗೊಳಿಸುತ್ತದೆ."},"apparatus":[{"en":"Two silicon diodes","hi":"दो सिलिकॉन डायोड","kn":"ಎರಡು ಸಿಲಿಕಾನ್ ಡಯೋಡ್‌ಗಳು"},{"en":"Centre-tapped transformer (6-0-6, 9-0-9 or 12-0-12 V)","hi":"मध्य-निष्कासित ट्रांसफ़ॉर्मर (6-0-6, 9-0-9 या 12-0-12 V)","kn":"ಮಧ್ಯ-ಟ್ಯಾಪ್ ಪರಿವರ್ತಕ (6-0-6, 9-0-9 ಅಥವಾ 12-0-12 V)"},{"en":"Load resistors (470 Ω, 1 kΩ, 2.2 kΩ)","hi":"लोड प्रतिरोधक (470 Ω, 1 kΩ, 2.2 kΩ)","kn":"ಲೋಡ್ ರೋಧಕಗಳು (470 Ω, 1 kΩ, 2.2 kΩ)"},{"en":"Electrolytic capacitors (100, 470, 1000 µF)","hi":"विद्युत-अपघटनी संधारित्र (100, 470, 1000 µF)","kn":"ವಿದ್ಯುದ್ವಿಭಜಕ ಧಾರಕಗಳು (100, 470, 1000 µF)"},{"en":"Multimeter (AC and DC)","hi":"मल्टीमीटर (AC और DC)","kn":"ಮಲ್ಟಿಮೀಟರ್ (AC ಮತ್ತು DC)"},{"en":"Cathode-ray oscilloscope (CRO)","hi":"कैथोड किरण दोलनदर्शी (CRO)","kn":"ಕ್ಯಾಥೋಡ್ ಕಿರಣ ಆಂದೋಲನದರ್ಶಕ (CRO)"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect each end of the secondary to the anode of a diode; join the cathodes to one end of the load; the other end of the load goes to the centre tap.","hi":"द्वितीयक के हर सिरे को एक डायोड के ऐनोड से जोड़ें; कैथोडों को लोड के एक सिरे से जोड़ें; लोड का दूसरा सिरा मध्य-निष्कास से।","kn":"ದ್ವಿತೀಯಕದ ಪ್ರತಿ ತುದಿಯನ್ನು ಒಂದು ಡಯೋಡ್‌ನ ಆನೋಡ್‌ಗೆ ಜೋಡಿಸಿ; ಕ್ಯಾಥೋಡ್‌ಗಳನ್ನು ಲೋಡ್‌ನ ಒಂದು ತುದಿಗೆ ಸೇರಿಸಿ; ಲೋಡ್‌ನ ಇನ್ನೊಂದು ತುದಿ ಮಧ್ಯ-ಟ್ಯಾಪ್‌ಗೆ."},{"en":"Show one half of the secondary and the output on the CRO.","hi":"CRO पर द्वितीयक का एक भाग और निर्गत दिखाएँ।","kn":"CRO ನಲ್ಲಿ ದ್ವಿತೀಯಕದ ಒಂದು ಅರ್ಧ ಮತ್ತು ಹೊರಹರಿವು ತೋರಿಸಿ."},{"en":"Read the DC voltage across the load and look at the output on the CRO.","hi":"लोड के सिरों की DC वोल्टता पढ़ें और CRO पर निर्गत देखें।","kn":"ಲೋಡ್‌ಗೆ ಅಡ್ಡ DC ವೋಲ್ಟೇಜ್ ಓದಿ, CRO ನಲ್ಲಿ ಹೊರಹರಿವನ್ನು ನೋಡಿ."},{"en":"Measure the AC ripple voltage across the load and work out the ripple factor γ = Vac ÷ Vdc.","hi":"लोड के सिरों पर AC ऊर्मिका वोल्टता मापें और ऊर्मिका गुणांक γ = Vac ÷ Vdc निकालें।","kn":"ಲೋಡ್‌ಗೆ ಅಡ್ಡ AC ತರಂಗ ವೋಲ್ಟೇಜ್ ಅಳೆಯಿರಿ, ತರಂಗ ಅಂಶ γ = Vac ÷ Vdc ಲೆಕ್ಕಿಸಿ."},{"en":"Connect filter capacitors of 100, 470 and 1000 µF across the load in turn and repeat.","hi":"बारी-बारी से 100, 470 और 1000 µF के फ़िल्टर संधारित्र लोड के सिरों पर जोड़कर दोहराएँ।","kn":"ಸರದಿಯಾಗಿ 100, 470 ಮತ್ತು 1000 µF ಫಿಲ್ಟರ್ ಧಾರಕಗಳನ್ನು ಲೋಡ್‌ಗೆ ಅಡ್ಡಲಾಗಿ ಜೋಡಿಸಿ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Change the load resistance and see how the ripple changes.","hi":"लोड प्रतिरोध बदलें और देखें कि ऊर्मिका कैसे बदलती है।","kn":"ಲೋಡ್ ರೋಧ ಬದಲಿಸಿ ತರಂಗ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ನೋಡಿ."}],"precautions":[{"en":"Never touch the 230 V mains side of the transformer.","hi":"ट्रांसफ़ॉर्मर के 230 V मुख्य सिरे को कभी न छुएँ।","kn":"ಪರಿವರ್ತಕದ 230 V ಮುಖ್ಯ ಭಾಗವನ್ನು ಎಂದೂ ಮುಟ್ಟಬೇಡಿ."},{"en":"Connect electrolytic capacitors the right way round (+ to the diode side).","hi":"विद्युत-अपघटनी संधारित्र सही दिशा में जोड़ें (+ डायोड वाले सिरे की ओर)।","kn":"ವಿದ್ಯುದ್ವಿಭಜಕ ಧಾರಕಗಳನ್ನು ಸರಿಯಾದ ದಿಕ್ಕಿನಲ್ಲಿ ಜೋಡಿಸಿ (+ ಡಯೋಡ್ ಕಡೆ)."},{"en":"Use the AC range of the meter for the ripple and the DC range for Vdc.","hi":"ऊर्मिका के लिए मीटर की AC परास और Vdc के लिए DC परास लें।","kn":"ತರಂಗಕ್ಕೆ ಮೀಟರ್‌ನ AC ವ್ಯಾಪ್ತಿ, Vdc ಗೆ DC ವ್ಯಾಪ್ತಿ ಬಳಸಿ."}],"conclusion":{"en":"Both half-cycles reach the load, so the DC output is about twice that of a half-wave rectifier and the ripple factor falls to about 0.48; with a capacitor the output is nearly steady DC.","hi":"दोनों अर्ध-चक्र लोड तक पहुँचते हैं, इसलिए DC निर्गत अर्ध-तरंग का लगभग दोगुना होता है और ऊर्मिका गुणांक लगभग 0.48 रह जाता है; संधारित्र के साथ निर्गत लगभग स्थिर DC है।","kn":"ಎರಡೂ ಅರ್ಧ-ಚಕ್ರಗಳು ಲೋಡ್ ತಲುಪುತ್ತವೆ; DC ಹೊರಹರಿವು ಅರ್ಧ-ತರಂಗದ ಸುಮಾರು ಎರಡು ಪಟ್ಟು, ತರಂಗ ಅಂಶ ಸುಮಾರು 0.48; ಧಾರಕದೊಂದಿಗೆ ಹೊರಹರಿವು ಬಹುತೇಕ ಸ್ಥಿರ DC."},"viva":[{"q":{"en":"What is ripple?","hi":"ऊर्मिका क्या है?","kn":"ತರಂಗ (ರಿಪಲ್) ಎಂದರೇನು?"},"a":{"en":"The AC part left in the output of a rectifier.","hi":"दिष्टकारी के निर्गत में बचा AC भाग।","kn":"ಸರಿಪಡಿಸುವ ಸಾಧನದ ಹೊರಹರಿವಿನಲ್ಲಿ ಉಳಿದ AC ಭಾಗ."}},{"q":{"en":"How does a capacitor filter work?","hi":"संधारित्र फ़िल्टर कैसे काम करता है?","kn":"ಧಾರಕ ಫಿಲ್ಟರ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?"},"a":{"en":"It charges to the peak and supplies the load between peaks, discharging slowly through RL.","hi":"यह शिखर तक आवेशित होकर शिखरों के बीच लोड को धारा देता है और RL से धीरे-धीरे निरावेशित होता है।","kn":"ಅದು ಶಿಖರದವರೆಗೆ ಆವೇಶಗೊಂಡು ಶಿಖರಗಳ ನಡುವೆ ಲೋಡ್‌ಗೆ ಪ್ರವಾಹ ಒದಗಿಸುತ್ತದೆ; RL ಮೂಲಕ ನಿಧಾನವಾಗಿ ವಿಸರ್ಜನೆಯಾಗುತ್ತದೆ."}},{"q":{"en":"What is the ripple frequency of a full-wave rectifier on 50 Hz mains?","hi":"50 Hz मुख्य आपूर्ति पर पूर्ण-तरंग दिष्टकारी की ऊर्मिका आवृत्ति कितनी है?","kn":"50 Hz ಮುಖ್ಯ ಪೂರೈಕೆಯಲ್ಲಿ ಪೂರ್ಣ-ತರಂಗ ಸಾಧನದ ತರಂಗ ಆವರ್ತನ ಎಷ್ಟು?"},"a":{"en":"100 Hz.","hi":"100 Hz.","kn":"100 Hz."}}]},{"id":"bridge-rectifier","bench":"rectifier","setup":{"type":"bridge","cap":470.0},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["rectifier","bridge rectifier","full-wave rectifier","filter","capacitor filter","ripple factor","power supply"],"title":{"en":"Bridge rectifier with a capacitor filter","hi":"संधारित्र फ़िल्टर सहित सेतु दिष्टकारी","kn":"ಧಾರಕ ಫಿಲ್ಟರ್ ಸಹಿತ ಸೇತು ಸರಿಪಡಿಸುವ ಸಾಧನ"},"summary":{"en":"Four diodes in a bridge make full-wave DC without a centre tap; see how the filter capacitor fills the gaps.","hi":"सेतु में चार डायोड बिना मध्य-निष्कास के पूर्ण-तरंग DC बनाते हैं; देखें कि फ़िल्टर संधारित्र अंतराल कैसे भरता है।","kn":"ಸೇತುವಿನಲ್ಲಿ ನಾಲ್ಕು ಡಯೋಡ್‌ಗಳು ಮಧ್ಯ-ಟ್ಯಾಪ್ ಇಲ್ಲದೆ ಪೂರ್ಣ-ತರಂಗ DC ನೀಡುತ್ತವೆ; ಫಿಲ್ಟರ್ ಧಾರಕ ಅಂತರಗಳನ್ನು ಹೇಗೆ ತುಂಬುತ್ತದೆ ನೋಡಿ."},"aim":{"en":"To study a bridge rectifier and the effect of a capacitor filter and the load on its ripple.","hi":"सेतु दिष्टकारी का तथा उसकी ऊर्मिका पर संधारित्र फ़िल्टर और लोड के प्रभाव का अध्ययन करना।","kn":"ಸೇತು ಸರಿಪಡಿಸುವ ಸಾಧನ ಮತ್ತು ಅದರ ತರಂಗದ ಮೇಲೆ ಧಾರಕ ಫಿಲ್ಟರ್ ಹಾಗೂ ಲೋಡ್‌ನ ಪರಿಣಾಮವನ್ನು ಅಧ್ಯಯನ ಮಾಡುವುದು."},"principle":{"en":"In each half-cycle two opposite diodes of the bridge conduct in series and send current the same way through the load. Two diode drops (about 1.4 V) are lost. With a capacitor C across RL, the ripple factor is about 1/(4√3 f RL C): larger C or larger RL give smoother DC.","hi":"हर अर्ध-चक्र में सेतु के दो सामने वाले डायोड श्रेणी में चालन करते हैं और लोड में एक ही दिशा में धारा भेजते हैं। दो डायोड पात (लगभग 1.4 V) खो जाते हैं। RL के सिरों पर संधारित्र C होने पर ऊर्मिका गुणांक लगभग 1/(4√3 f RL C) है: बड़ा C या बड़ा RL अधिक समतल DC देता है।","kn":"ಪ್ರತಿ ಅರ್ಧ-ಚಕ್ರದಲ್ಲಿ ಸೇತುವಿನ ಎರಡು ಎದುರು ಡಯೋಡ್‌ಗಳು ಸರಣಿಯಲ್ಲಿ ವಾಹಕವಾಗಿ ಲೋಡ್‌ನಲ್ಲಿ ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಪ್ರವಾಹ ಕಳುಹಿಸುತ್ತವೆ. ಎರಡು ಡಯೋಡ್ ಇಳಿತಗಳು (ಸುಮಾರು 1.4 V) ನಷ್ಟ. RL ಗೆ ಅಡ್ಡ ಧಾರಕ C ಇದ್ದರೆ ತರಂಗ ಅಂಶ ಸುಮಾರು 1/(4√3 f RL C): ದೊಡ್ಡ C ಅಥವಾ ದೊಡ್ಡ RL ಹೆಚ್ಚು ನಯವಾದ DC ನೀಡುತ್ತದೆ."},"apparatus":[{"en":"Four silicon diodes (or a bridge module)","hi":"चार सिलिकॉन डायोड (या सेतु मॉड्यूल)","kn":"ನಾಲ್ಕು ಸಿಲಿಕಾನ್ ಡಯೋಡ್‌ಗಳು (ಅಥವಾ ಸೇತು ಮಾಡ್ಯೂಲ್)"},{"en":"Step-down transformer (230 V to 6/9/12 V)","hi":"अपचायी ट्रांसफ़ॉर्मर (230 V से 6/9/12 V)","kn":"ಇಳಿಕೆ ಪರಿವರ್ತಕ (230 V ನಿಂದ 6/9/12 V)"},{"en":"Load resistors (470 Ω, 1 kΩ, 2.2 kΩ)","hi":"लोड प्रतिरोधक (470 Ω, 1 kΩ, 2.2 kΩ)","kn":"ಲೋಡ್ ರೋಧಕಗಳು (470 Ω, 1 kΩ, 2.2 kΩ)"},{"en":"Electrolytic capacitors (100, 470, 1000 µF)","hi":"विद्युत-अपघटनी संधारित्र (100, 470, 1000 µF)","kn":"ವಿದ್ಯುದ್ವಿಭಜಕ ಧಾರಕಗಳು (100, 470, 1000 µF)"},{"en":"Multimeter (AC and DC)","hi":"मल्टीमीटर (AC और DC)","kn":"ಮಲ್ಟಿಮೀಟರ್ (AC ಮತ್ತು DC)"},{"en":"Cathode-ray oscilloscope (CRO)","hi":"कैथोड किरण दोलनदर्शी (CRO)","kn":"ಕ್ಯಾಥೋಡ್ ಕಿರಣ ಆಂದೋಲನದರ್ಶಕ (CRO)"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Arrange the four diodes in a bridge: AC to the two junctions where an anode meets a cathode; take DC from the cathode-cathode (+) and anode-anode (−) junctions.","hi":"चार डायोडों को सेतु में लगाएँ: AC उन दो संधियों पर जहाँ ऐनोड कैथोड से मिलता है; DC कैथोड-कैथोड (+) और ऐनोड-ऐनोड (−) संधियों से लें।","kn":"ನಾಲ್ಕು ಡಯೋಡ್‌ಗಳನ್ನು ಸೇತುವಾಗಿ ಜೋಡಿಸಿ: ಆನೋಡ್ ಕ್ಯಾಥೋಡನ್ನು ಸೇರುವ ಎರಡು ಸಂಧಿಗಳಿಗೆ AC; ಕ್ಯಾಥೋಡ್-ಕ್ಯಾಥೋಡ್ (+) ಮತ್ತು ಆನೋಡ್-ಆನೋಡ್ (−) ಸಂಧಿಗಳಿಂದ DC."},{"en":"Start without the capacitor and compare input and output on the CRO.","hi":"संधारित्र के बिना शुरू करें और CRO पर निवेश तथा निर्गत की तुलना करें।","kn":"ಧಾರಕವಿಲ್ಲದೆ ಆರಂಭಿಸಿ CRO ನಲ್ಲಿ ಒಳಹರಿವು-ಹೊರಹರಿವು ಹೋಲಿಸಿ."},{"en":"Read the DC voltage across the load and look at the output on the CRO.","hi":"लोड के सिरों की DC वोल्टता पढ़ें और CRO पर निर्गत देखें।","kn":"ಲೋಡ್‌ಗೆ ಅಡ್ಡ DC ವೋಲ್ಟೇಜ್ ಓದಿ, CRO ನಲ್ಲಿ ಹೊರಹರಿವನ್ನು ನೋಡಿ."},{"en":"Measure the AC ripple voltage across the load and work out the ripple factor γ = Vac ÷ Vdc.","hi":"लोड के सिरों पर AC ऊर्मिका वोल्टता मापें और ऊर्मिका गुणांक γ = Vac ÷ Vdc निकालें।","kn":"ಲೋಡ್‌ಗೆ ಅಡ್ಡ AC ತರಂಗ ವೋಲ್ಟೇಜ್ ಅಳೆಯಿರಿ, ತರಂಗ ಅಂಶ γ = Vac ÷ Vdc ಲೆಕ್ಕಿಸಿ."},{"en":"Connect filter capacitors of 100, 470 and 1000 µF across the load in turn and repeat.","hi":"बारी-बारी से 100, 470 और 1000 µF के फ़िल्टर संधारित्र लोड के सिरों पर जोड़कर दोहराएँ।","kn":"ಸರದಿಯಾಗಿ 100, 470 ಮತ್ತು 1000 µF ಫಿಲ್ಟರ್ ಧಾರಕಗಳನ್ನು ಲೋಡ್‌ಗೆ ಅಡ್ಡಲಾಗಿ ಜೋಡಿಸಿ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Change the load resistance and see how the ripple changes.","hi":"लोड प्रतिरोध बदलें और देखें कि ऊर्मिका कैसे बदलती है।","kn":"ಲೋಡ್ ರೋಧ ಬದಲಿಸಿ ತರಂಗ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ನೋಡಿ."}],"precautions":[{"en":"Never touch the 230 V mains side of the transformer.","hi":"ट्रांसफ़ॉर्मर के 230 V मुख्य सिरे को कभी न छुएँ।","kn":"ಪರಿವರ್ತಕದ 230 V ಮುಖ್ಯ ಭಾಗವನ್ನು ಎಂದೂ ಮುಟ್ಟಬೇಡಿ."},{"en":"Connect electrolytic capacitors the right way round (+ to the diode side).","hi":"विद्युत-अपघटनी संधारित्र सही दिशा में जोड़ें (+ डायोड वाले सिरे की ओर)।","kn":"ವಿದ್ಯುದ್ವಿಭಜಕ ಧಾರಕಗಳನ್ನು ಸರಿಯಾದ ದಿಕ್ಕಿನಲ್ಲಿ ಜೋಡಿಸಿ (+ ಡಯೋಡ್ ಕಡೆ)."},{"en":"Use the AC range of the meter for the ripple and the DC range for Vdc.","hi":"ऊर्मिका के लिए मीटर की AC परास और Vdc के लिए DC परास लें।","kn":"ತರಂಗಕ್ಕೆ ಮೀಟರ್‌ನ AC ವ್ಯಾಪ್ತಿ, Vdc ಗೆ DC ವ್ಯಾಪ್ತಿ ಬಳಸಿ."}],"conclusion":{"en":"The bridge gives full-wave rectification from an ordinary secondary at the cost of two diode drops; the filter capacitor cuts the ripple factor to a few per cent, and less ripple comes with a larger C or a lighter load.","hi":"सेतु दो डायोड पात की क़ीमत पर साधारण द्वितीयक से पूर्ण-तरंग दिष्टकरण देता है; फ़िल्टर संधारित्र ऊर्मिका गुणांक को कुछ प्रतिशत तक घटा देता है, और बड़े C या हल्के लोड से ऊर्मिका कम होती है।","kn":"ಸೇತು ಎರಡು ಡಯೋಡ್ ಇಳಿತಗಳ ವೆಚ್ಚದಲ್ಲಿ ಸಾಮಾನ್ಯ ದ್ವಿತೀಯಕದಿಂದ ಪೂರ್ಣ-ತರಂಗ ಸರಿಪಡಿಸುವಿಕೆ ನೀಡುತ್ತದೆ; ಫಿಲ್ಟರ್ ಧಾರಕ ತರಂಗ ಅಂಶವನ್ನು ಕೆಲವು ಶೇಕಡಕ್ಕೆ ಇಳಿಸುತ್ತದೆ; ದೊಡ್ಡ C ಅಥವಾ ಹಗುರ ಲೋಡ್ ತರಂಗ ಕಡಿಮೆ ಮಾಡುತ್ತದೆ."},"viva":[{"q":{"en":"What is ripple?","hi":"ऊर्मिका क्या है?","kn":"ತರಂಗ (ರಿಪಲ್) ಎಂದರೇನು?"},"a":{"en":"The AC part left in the output of a rectifier.","hi":"दिष्टकारी के निर्गत में बचा AC भाग।","kn":"ಸರಿಪಡಿಸುವ ಸಾಧನದ ಹೊರಹರಿವಿನಲ್ಲಿ ಉಳಿದ AC ಭಾಗ."}},{"q":{"en":"How does a capacitor filter work?","hi":"संधारित्र फ़िल्टर कैसे काम करता है?","kn":"ಧಾರಕ ಫಿಲ್ಟರ್ ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?"},"a":{"en":"It charges to the peak and supplies the load between peaks, discharging slowly through RL.","hi":"यह शिखर तक आवेशित होकर शिखरों के बीच लोड को धारा देता है और RL से धीरे-धीरे निरावेशित होता है।","kn":"ಅದು ಶಿಖರದವರೆಗೆ ಆವೇಶಗೊಂಡು ಶಿಖರಗಳ ನಡುವೆ ಲೋಡ್‌ಗೆ ಪ್ರವಾಹ ಒದಗಿಸುತ್ತದೆ; RL ಮೂಲಕ ನಿಧಾನವಾಗಿ ವಿಸರ್ಜನೆಯಾಗುತ್ತದೆ."}},{"q":{"en":"Why is the peak output of a bridge about 1.4 V less than the input peak?","hi":"सेतु का शिखर निर्गत निवेश शिखर से लगभग 1.4 V कम क्यों होता है?","kn":"ಸೇತುವಿನ ಶಿಖರ ಹೊರಹರಿವು ಒಳಹರಿವಿನ ಶಿಖರಕ್ಕಿಂತ ಸುಮಾರು 1.4 V ಕಡಿಮೆ ಏಕೆ?"},"a":{"en":"Current passes through two diodes in series in each half-cycle.","hi":"हर अर्ध-चक्र में धारा श्रेणी में दो डायोडों से होकर जाती है।","kn":"ಪ್ರತಿ ಅರ್ಧ-ಚಕ್ರದಲ್ಲಿ ಪ್ರವಾಹ ಸರಣಿಯ ಎರಡು ಡಯೋಡ್‌ಗಳ ಮೂಲಕ ಹೋಗುತ್ತದೆ."}}]},{"id":"transistor-ce","bench":"transistor","setup":{},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["transistor","npn transistor","common emitter","characteristics","current gain","amplifier","semiconductor electronics"],"title":{"en":"Characteristics of an NPN transistor (CE)","hi":"NPN ट्रांज़िस्टर के अभिलक्षण (उभयनिष्ठ उत्सर्जक)","kn":"NPN ಟ್ರಾನ್ಸಿಸ್ಟರ್‌ನ ಲಕ್ಷಣಗಳು (ಸಾಮಾನ್ಯ ಉತ್ಸರ್ಜಕ)"},"summary":{"en":"Plot the input and output characteristics of a transistor in common-emitter mode and find its current gain β.","hi":"उभयनिष्ठ उत्सर्जक विन्यास में ट्रांज़िस्टर के निवेश और निर्गत अभिलक्षण बनाएँ और उसकी धारा लब्धि β ज्ञात करें।","kn":"ಸಾಮಾನ್ಯ ಉತ್ಸರ್ಜಕ ವಿನ್ಯಾಸದಲ್ಲಿ ಟ್ರಾನ್ಸಿಸ್ಟರ್‌ನ ಒಳಹರಿವು ಮತ್ತು ಹೊರಹರಿವು ಲಕ್ಷಣಗಳನ್ನು ಎಳೆದು ಅದರ ಪ್ರವಾಹ ಲಾಭ β ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To draw the input and output characteristics of an NPN transistor in CE configuration and find its current gain.","hi":"उभयनिष्ठ उत्सर्जक विन्यास में NPN ट्रांज़िस्टर के निवेश और निर्गत अभिलक्षण खींचना और उसकी धारा लब्धि ज्ञात करना।","kn":"ಸಾಮಾನ್ಯ ಉತ್ಸರ್ಜಕ ವಿನ್ಯಾಸದಲ್ಲಿ NPN ಟ್ರಾನ್ಸಿಸ್ಟರ್‌ನ ಒಳಹರಿವು ಮತ್ತು ಹೊರಹರಿವು ಲಕ್ಷಣಗಳನ್ನು ಎಳೆದು ಅದರ ಪ್ರವಾಹ ಲಾಭ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"The base-emitter junction is forward-biased and behaves like a diode (input characteristic: Ib against Vbe). With the collector-base junction reverse-biased, the collector current is about β times the base current and hardly changes with Vce (output characteristic: Ic against Vce at fixed Ib). β = Ic ÷ Ib (dc) or ΔIc ÷ ΔIb (ac).","hi":"आधार-उत्सर्जक संधि अग्र अभिनत होती है और डायोड जैसा व्यवहार करती है (निवेश अभिलक्षण: Ib और Vbe)। संग्राहक-आधार संधि पश्च अभिनत होने पर संग्राहक धारा आधार धारा की लगभग β गुनी होती है और Vce के साथ बहुत कम बदलती है (निर्गत अभिलक्षण: नियत Ib पर Ic और Vce)। β = Ic ÷ Ib (dc) या ΔIc ÷ ΔIb (ac).","kn":"ಆಧಾರ-ಉತ್ಸರ್ಜಕ ಸಂಧಿ ಮುಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿದ್ದು ಡಯೋಡ್‌ನಂತೆ ವರ್ತಿಸುತ್ತದೆ (ಒಳಹರಿವು ಲಕ್ಷಣ: Ib ಮತ್ತು Vbe). ಸಂಗ್ರಾಹಕ-ಆಧಾರ ಸಂಧಿ ಹಿಮ್ಮುಖ ಬಯಾಸ್‌ನಲ್ಲಿದ್ದಾಗ ಸಂಗ್ರಾಹಕ ಪ್ರವಾಹ ಆಧಾರ ಪ್ರವಾಹದ ಸುಮಾರು β ಪಟ್ಟು, Vce ಯೊಂದಿಗೆ ಬಹಳ ಕಡಿಮೆ ಬದಲಾಗುತ್ತದೆ (ಹೊರಹರಿವು ಲಕ್ಷಣ: ಸ್ಥಿರ Ib ನಲ್ಲಿ Ic ಮತ್ತು Vce). β = Ic ÷ Ib (dc) ಅಥವಾ ΔIc ÷ ΔIb (ac)."},"apparatus":[{"en":"NPN transistor (BC547)","hi":"NPN ट्रांज़िस्टर (BC547)","kn":"NPN ಟ್ರಾನ್ಸಿಸ್ಟರ್ (BC547)"},{"en":"Two variable DC supplies (Vbb and Vcc)","hi":"दो परिवर्ती DC आपूर्तियाँ (Vbb और Vcc)","kn":"ಎರಡು ಬದಲಾಯಿಸಬಹುದಾದ DC ಪೂರೈಕೆಗಳು (Vbb ಮತ್ತು Vcc)"},{"en":"Microammeter and milliammeter","hi":"माइक्रोऐमीटर और मिलीऐमीटर","kn":"ಮೈಕ್ರೋಅಮ್ಮೀಟರ್ ಮತ್ತು ಮಿಲಿಅಮ್ಮೀಟರ್"},{"en":"Two voltmeters","hi":"दो वोल्टमीटर","kn":"ಎರಡು ವೋಲ್ಟ್‌ಮೀಟರ್‌ಗಳು"},{"en":"Base and collector resistors","hi":"आधार और संग्राहक प्रतिरोधक","kn":"ಆಧಾರ ಮತ್ತು ಸಂಗ್ರಾಹಕ ರೋಧಕಗಳು"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Identify the emitter, base and collector. Connect the circuit with the emitter common to the input and output.","hi":"उत्सर्जक, आधार और संग्राहक पहचानें। परिपथ ऐसे जोड़ें कि उत्सर्जक निवेश और निर्गत दोनों में उभयनिष्ठ हो।","kn":"ಉತ್ಸರ್ಜಕ, ಆಧಾರ ಮತ್ತು ಸಂಗ್ರಾಹಕ ಗುರುತಿಸಿ. ಉತ್ಸರ್ಜಕ ಒಳಹರಿವು ಮತ್ತು ಹೊರಹರಿವಿಗೆ ಸಾಮಾನ್ಯವಾಗಿರುವಂತೆ ಮಂಡಲ ಜೋಡಿಸಿ."},{"en":"Input characteristic: keep Vce fixed (1 V or 5 V); raise Vbb and record Ib and Vbe.","hi":"निवेश अभिलक्षण: Vce नियत (1 V या 5 V) रखें; Vbb बढ़ाएँ और Ib तथा Vbe लिखें।","kn":"ಒಳಹರಿವು ಲಕ್ಷಣ: Vce ಸ್ಥಿರ (1 V ಅಥವಾ 5 V); Vbb ಹೆಚ್ಚಿಸಿ Ib ಮತ್ತು Vbe ದಾಖಲಿಸಿ."},{"en":"Output characteristic: set a base current (say 20 µA); raise Vcc and record Vce and Ic.","hi":"निर्गत अभिलक्षण: एक आधार धारा (मान लें 20 µA) तय करें; Vcc बढ़ाएँ और Vce तथा Ic लिखें।","kn":"ಹೊರಹರಿವು ಲಕ್ಷಣ: ಒಂದು ಆಧಾರ ಪ್ರವಾಹ (ಉದಾ. 20 µA) ಹೊಂದಿಸಿ; Vcc ಹೆಚ್ಚಿಸಿ Vce ಮತ್ತು Ic ದಾಖಲಿಸಿ."},{"en":"Repeat the output readings for 10, 30 and 40 µA.","hi":"10, 30 और 40 µA के लिए निर्गत पाठ्यांक दोहराएँ।","kn":"10, 30 ಮತ್ತು 40 µA ಗೆ ಹೊರಹರಿವು ಓದುಗಳನ್ನು ಪುನರಾವರ್ತಿಸಿ."},{"en":"Plot both families of curves and find β = ΔIc ÷ ΔIb at a fixed Vce in the active region.","hi":"वक्रों के दोनों समूह बनाएँ और सक्रिय क्षेत्र में नियत Vce पर β = ΔIc ÷ ΔIb ज्ञात करें।","kn":"ಎರಡೂ ವಕ್ರ ಕುಟುಂಬಗಳನ್ನು ಎಳೆದು, ಸಕ್ರಿಯ ಪ್ರದೇಶದಲ್ಲಿ ಸ್ಥಿರ Vce ಯಲ್ಲಿ β = ΔIc ÷ ΔIb ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Keep Ic and Vce within the transistor’s ratings.","hi":"Ic और Vce को ट्रांज़िस्टर की सीमाओं के भीतर रखें।","kn":"Ic ಮತ್ತು Vce ಯನ್ನು ಟ್ರಾನ್ಸಿಸ್ಟರ್‌ನ ಮಿತಿಯೊಳಗಿಡಿ."},{"en":"Connect meters with + to + and choose a range larger than the expected reading.","hi":"मीटर + से + जोड़ें और अपेक्षित पाठ्यांक से बड़ी परास चुनें।","kn":"ಮೀಟರ್‌ಗಳನ್ನು + ರಿಂದ + ಗೆ ಜೋಡಿಸಿ, ನಿರೀಕ್ಷಿತ ಓದಿಗಿಂತ ದೊಡ್ಡ ವ್ಯಾಪ್ತಿ ಆರಿಸಿ."},{"en":"Hold the base current constant while taking each output curve.","hi":"हर निर्गत वक्र लेते समय आधार धारा नियत रखें।","kn":"ಪ್ರತಿ ಹೊರಹರಿವು ವಕ್ರ ತೆಗೆಯುವಾಗ ಆಧಾರ ಪ್ರವಾಹ ಸ್ಥಿರವಾಗಿರಲಿ."}],"conclusion":{"en":"The input characteristic is like a forward-biased diode; in the output characteristic Ic rises quickly at very small Vce (saturation) and then stays nearly flat (active region), with Ic about β times Ib.","hi":"निवेश अभिलक्षण अग्र अभिनत डायोड जैसा है; निर्गत अभिलक्षण में बहुत छोटे Vce पर Ic तेज़ी से बढ़ता है (संतृप्ति) और फिर लगभग समतल रहता है (सक्रिय क्षेत्र), जहाँ Ic लगभग Ib का β गुना है।","kn":"ಒಳಹರಿವು ಲಕ್ಷಣ ಮುಮ್ಮುಖ ಬಯಾಸ್ ಡಯೋಡ್‌ನಂತೆ; ಹೊರಹರಿವು ಲಕ್ಷಣದಲ್ಲಿ ಅತಿ ಸಣ್ಣ Vce ಯಲ್ಲಿ Ic ವೇಗವಾಗಿ ಏರುತ್ತದೆ (ಸಂತೃಪ್ತಿ), ನಂತರ ಬಹುತೇಕ ಸಮತಟ್ಟು (ಸಕ್ರಿಯ ಪ್ರದೇಶ); ಅಲ್ಲಿ Ic ಸುಮಾರು Ib ಯ β ಪಟ್ಟು."},"viva":[{"q":{"en":"Why is the base made thin and lightly doped?","hi":"आधार पतला और हल्का मादित क्यों बनाया जाता है?","kn":"ಆಧಾರವನ್ನು ತೆಳುವಾಗಿ, ಕಡಿಮೆ ಡೋಪ್ ಮಾಡಿ ಏಕೆ ಮಾಡುತ್ತಾರೆ?"},"a":{"en":"So that most electrons from the emitter cross it to the collector instead of recombining.","hi":"ताकि उत्सर्जक के अधिकांश इलेक्ट्रॉन पुनर्संयोजित हुए बिना उसे पार करके संग्राहक तक पहुँचें।","kn":"ಉತ್ಸರ್ಜಕದ ಹೆಚ್ಚಿನ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳು ಮರುಸಂಯೋಗವಾಗದೆ ಅದನ್ನು ದಾಟಿ ಸಂಗ್ರಾಹಕ ತಲುಪಲು."}},{"q":{"en":"Name the three regions of the output characteristic.","hi":"निर्गत अभिलक्षण के तीन क्षेत्रों के नाम बताइए।","kn":"ಹೊರಹರಿವು ಲಕ್ಷಣದ ಮೂರು ಪ್ರದೇಶಗಳನ್ನು ಹೆಸರಿಸಿ."},"a":{"en":"Cut-off, active and saturation.","hi":"अंतक (कट-ऑफ़), सक्रिय और संतृप्ति।","kn":"ಕಟ್-ಆಫ್, ಸಕ್ರಿಯ ಮತ್ತು ಸಂತೃಪ್ತಿ."}},{"q":{"en":"In which region is a transistor used as an amplifier, and as a switch?","hi":"प्रवर्धक के रूप में और स्विच के रूप में ट्रांज़िस्टर किस क्षेत्र में प्रयोग होता है?","kn":"ವರ್ಧಕವಾಗಿ ಮತ್ತು ಸ್ವಿಚ್ ಆಗಿ ಟ್ರಾನ್ಸಿಸ್ಟರ್ ಯಾವ ಪ್ರದೇಶದಲ್ಲಿ ಬಳಕೆಯಾಗುತ್ತದೆ?"},"a":{"en":"Amplifier: active region. Switch: cut-off (off) and saturation (on).","hi":"प्रवर्धक: सक्रिय क्षेत्र। स्विच: अंतक (बंद) और संतृप्ति (चालू)।","kn":"ವರ್ಧಕ: ಸಕ್ರಿಯ ಪ್ರದೇಶ. ಸ್ವಿಚ್: ಕಟ್-ಆಫ್ (ಆಫ್) ಮತ್ತು ಸಂತೃಪ್ತಿ (ಆನ್)."}}]},{"id":"logic-gates","bench":"logic","setup":{},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"explore","curricula":["cbse","ka-puc"],"reviewed":false,"keywords":["logic gates","logic gate","truth table","and gate","or gate","not gate","nand","nor","xor","digital electronics","boolean"],"title":{"en":"Logic gates and truth tables","hi":"लॉजिक गेट और सत्यता सारणी","kn":"ತರ್ಕ ದ್ವಾರಗಳು ಮತ್ತು ಸತ್ಯ ಕೋಷ್ಟಕಗಳು"},"summary":{"en":"Switch the inputs of AND, OR, NOT, NAND, NOR, XOR and XNOR gates and build each truth table.","hi":"AND, OR, NOT, NAND, NOR, XOR और XNOR गेटों के निवेश बदलें और हर एक की सत्यता सारणी बनाएँ।","kn":"AND, OR, NOT, NAND, NOR, XOR ಮತ್ತು XNOR ದ್ವಾರಗಳ ಒಳಹರಿವುಗಳನ್ನು ಬದಲಿಸಿ ಪ್ರತಿಯೊಂದರ ಸತ್ಯ ಕೋಷ್ಟಕ ರಚಿಸಿ."},"aim":{"en":"To verify the truth tables of the basic and universal logic gates.","hi":"मूल और सार्वत्रिक लॉजिक गेटों की सत्यता सारणियों का सत्यापन करना।","kn":"ಮೂಲ ಮತ್ತು ಸಾರ್ವತ್ರಿಕ ತರ್ಕ ದ್ವಾರಗಳ ಸತ್ಯ ಕೋಷ್ಟಕಗಳನ್ನು ಪರಿಶೀಲಿಸುವುದು."},"principle":{"en":"A logic gate gives a high (1) or low (0) output that depends only on its inputs. AND: Y = A·B; OR: Y = A + B; NOT: Y = Ā. NAND and NOR are AND and OR followed by NOT; each can be combined to make every other gate, so they are called universal gates. XOR is 1 when the inputs differ.","hi":"लॉजिक गेट उच्च (1) या निम्न (0) निर्गत देता है जो केवल उसके निवेशों पर निर्भर करता है। AND: Y = A·B; OR: Y = A + B; NOT: Y = Ā. NAND और NOR, AND और OR के बाद NOT हैं; इनमें से प्रत्येक से हर दूसरा गेट बनाया जा सकता है, इसलिए इन्हें सार्वत्रिक गेट कहते हैं। XOR तब 1 होता है जब निवेश भिन्न हों।","kn":"ತರ್ಕ ದ್ವಾರವು ಅದರ ಒಳಹರಿವುಗಳನ್ನು ಮಾತ್ರ ಅವಲಂಬಿಸಿ ಉನ್ನತ (1) ಅಥವಾ ನಿಮ್ನ (0) ಹೊರಹರಿವು ನೀಡುತ್ತದೆ. AND: Y = A·B; OR: Y = A + B; NOT: Y = Ā. NAND ಮತ್ತು NOR ಎಂದರೆ AND ಮತ್ತು OR ನಂತರ NOT; ಇವುಗಳಲ್ಲಿ ಪ್ರತಿಯೊಂದರಿಂದಲೂ ಉಳಿದೆಲ್ಲ ದ್ವಾರಗಳನ್ನು ರಚಿಸಬಹುದು, ಆದ್ದರಿಂದ ಸಾರ್ವತ್ರಿಕ ದ್ವಾರಗಳು. ಒಳಹರಿವುಗಳು ಭಿನ್ನವಾಗಿದ್ದಾಗ XOR = 1."},"apparatus":[{"en":"Digital trainer kit with gate ICs (7408, 7432, 7404, 7400, 7402, 7486)","hi":"गेट IC सहित डिजिटल प्रशिक्षण किट (7408, 7432, 7404, 7400, 7402, 7486)","kn":"ದ್ವಾರ IC ಗಳ ಡಿಜಿಟಲ್ ತರಬೇತಿ ಕಿಟ್ (7408, 7432, 7404, 7400, 7402, 7486)"},{"en":"5 V DC supply","hi":"5 V DC आपूर्ति","kn":"5 V DC ಪೂರೈಕೆ"},{"en":"Input switches and an LED indicator","hi":"निवेश स्विच और LED सूचक","kn":"ಒಳಹರಿವು ಸ್ವಿಚ್‌ಗಳು ಮತ್ತು LED ಸೂಚಕ"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Choose a gate. Set both inputs to 0 and note whether the output LED is on (1) or off (0).","hi":"एक गेट चुनें। दोनों निवेश 0 रखें और देखें कि निर्गत LED जल रहा है (1) या बुझा है (0)।","kn":"ಒಂದು ದ್ವಾರ ಆರಿಸಿ. ಎರಡೂ ಒಳಹರಿವು 0 ಇಟ್ಟು ಹೊರಹರಿವು LED ಆನ್ (1) ಅಥವಾ ಆಫ್ (0) ಗಮನಿಸಿ."},{"en":"Record the row, then try 0 1, 1 0 and 1 1.","hi":"पंक्ति लिखें, फिर 0 1, 1 0 और 1 1 आज़माएँ।","kn":"ಸಾಲು ದಾಖಲಿಸಿ, ನಂತರ 0 1, 1 0 ಮತ್ತು 1 1 ಪ್ರಯತ್ನಿಸಿ."},{"en":"Compare your table with the gate’s Boolean expression.","hi":"अपनी सारणी की तुलना गेट के बूलीय व्यंजक से करें।","kn":"ನಿಮ್ಮ ಕೋಷ್ಟಕವನ್ನು ದ್ವಾರದ ಬೂಲಿಯನ್ ಅಭಿವ್ಯಕ್ತಿಯೊಂದಿಗೆ ಹೋಲಿಸಿ."},{"en":"Repeat for every gate.","hi":"हर गेट के लिए दोहराएँ।","kn":"ಪ್ರತಿ ದ್ವಾರಕ್ಕೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Use exactly 5 V for TTL ICs and connect Vcc and ground pins before switching on.","hi":"TTL IC के लिए ठीक 5 V लें और चालू करने से पहले Vcc और भू पिन जोड़ें।","kn":"TTL IC ಗಳಿಗೆ ನಿಖರವಾಗಿ 5 V ಬಳಸಿ; ಆನ್ ಮಾಡುವ ಮೊದಲು Vcc ಮತ್ತು ನೆಲ ಪಿನ್‌ಗಳನ್ನು ಜೋಡಿಸಿ."},{"en":"Do not leave TTL inputs floating: tie unused inputs to 0 or 1.","hi":"TTL निवेश खुले न छोड़ें: अप्रयुक्त निवेश 0 या 1 से जोड़ें।","kn":"TTL ಒಳಹರಿವುಗಳನ್ನು ತೇಲಲು ಬಿಡಬೇಡಿ: ಬಳಸದವನ್ನು 0 ಅಥವಾ 1 ಕ್ಕೆ ಜೋಡಿಸಿ."}],"conclusion":{"en":"Every gate followed its Boolean expression for all input combinations; NAND and NOR give the opposite of AND and OR.","hi":"हर गेट ने सभी निवेश संयोजनों के लिए अपने बूलीय व्यंजक का पालन किया; NAND और NOR, AND और OR का उलटा देते हैं।","kn":"ಪ್ರತಿ ದ್ವಾರವೂ ಎಲ್ಲ ಒಳಹರಿವು ಸಂಯೋಜನೆಗಳಿಗೆ ತನ್ನ ಬೂಲಿಯನ್ ಅಭಿವ್ಯಕ್ತಿಯನ್ನು ಅನುಸರಿಸಿತು; NAND ಮತ್ತು NOR, AND ಮತ್ತು OR ನ ವಿರುದ್ಧ ನೀಡುತ್ತವೆ."},"viva":[{"q":{"en":"Why are NAND and NOR called universal gates?","hi":"NAND और NOR को सार्वत्रिक गेट क्यों कहते हैं?","kn":"NAND ಮತ್ತು NOR ಅನ್ನು ಸಾರ್ವತ್ರಿಕ ದ್ವಾರಗಳೆಂದು ಏಕೆ ಕರೆಯುತ್ತಾರೆ?"},"a":{"en":"Any logic gate can be built from NAND gates alone (or NOR gates alone).","hi":"कोई भी लॉजिक गेट केवल NAND गेटों से (या केवल NOR गेटों से) बनाया जा सकता है।","kn":"ಯಾವುದೇ ತರ್ಕ ದ್ವಾರವನ್ನು ಕೇವಲ NAND (ಅಥವಾ ಕೇವಲ NOR) ದ್ವಾರಗಳಿಂದ ರಚಿಸಬಹುದು."}},{"q":{"en":"How do you make a NOT gate from a NAND gate?","hi":"NAND गेट से NOT गेट कैसे बनाते हैं?","kn":"NAND ದ್ವಾರದಿಂದ NOT ದ್ವಾರ ಹೇಗೆ ಮಾಡುತ್ತೀರಿ?"},"a":{"en":"Join its two inputs together.","hi":"उसके दोनों निवेश आपस में जोड़ दें।","kn":"ಅದರ ಎರಡು ಒಳಹರಿವುಗಳನ್ನು ಒಟ್ಟಿಗೆ ಜೋಡಿಸಿ."}},{"q":{"en":"When is the output of an XOR gate 1?","hi":"XOR गेट का निर्गत कब 1 होता है?","kn":"XOR ದ್ವಾರದ ಹೊರಹರಿವು ಯಾವಾಗ 1?"},"a":{"en":"When exactly one input is 1 (the inputs differ).","hi":"जब ठीक एक निवेश 1 हो (निवेश भिन्न हों)।","kn":"ನಿಖರವಾಗಿ ಒಂದು ಒಳಹರಿವು 1 ಆಗಿದ್ದಾಗ (ಒಳಹರಿವುಗಳು ಭಿನ್ನ)."}}]},{"id":"rc-time-constant","bench":"rc","setup":{},"subject":"Electronics","domain":"electronics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ka-puc","ug-physics"],"reviewed":false,"keywords":["capacitor","capacitance","rc circuit","time constant","charging","discharging","exponential"],"title":{"en":"Charging and discharging a capacitor (RC time constant)","hi":"संधारित्र का आवेशन और निरावेशन (RC समय नियतांक)","kn":"ಧಾರಕದ ಆವೇಶ ಮತ್ತು ವಿಸರ್ಜನೆ (RC ಕಾಲ ಸ್ಥಿರಾಂಕ)"},"summary":{"en":"Time how the capacitor voltage rises and falls, and find the time constant τ = RC from a log graph.","hi":"संधारित्र की वोल्टता के बढ़ने और घटने का समय मापें और लघुगणक ग्राफ़ से समय नियतांक τ = RC ज्ञात करें।","kn":"ಧಾರಕ ವೋಲ್ಟೇಜ್ ಏರುವ ಮತ್ತು ಇಳಿಯುವ ಸಮಯ ಅಳೆಯಿರಿ, ಲಾಗ್ ನಕ್ಷೆಯಿಂದ ಕಾಲ ಸ್ಥಿರಾಂಕ τ = RC ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To study the charging and discharging of a capacitor through a resistor and determine the time constant.","hi":"प्रतिरोधक द्वारा संधारित्र के आवेशन और निरावेशन का अध्ययन कर समय नियतांक ज्ञात करना।","kn":"ರೋಧಕದ ಮೂಲಕ ಧಾರಕದ ಆವೇಶ ಮತ್ತು ವಿಸರ್ಜನೆ ಅಧ್ಯಯನ ಮಾಡಿ ಕಾಲ ಸ್ಥಿರಾಂಕ ನಿರ್ಧರಿಸುವುದು."},"principle":{"en":"While charging, Vc = E(1 − e^(−t/RC)); while discharging, Vc = E e^(−t/RC). So ln(1 − Vc/E) or ln(Vc/E) falls in a straight line with t, of slope −1/τ, where τ = RC. In one time constant the capacitor goes 63 % of the way.","hi":"आवेशन के समय Vc = E(1 − e^(−t/RC)); निरावेशन के समय Vc = E e^(−t/RC). इसलिए ln(1 − Vc/E) या ln(Vc/E), t के साथ −1/τ प्रवणता की सीधी रेखा में घटता है, जहाँ τ = RC. एक समय नियतांक में संधारित्र 63 % रास्ता तय कर लेता है।","kn":"ಆವೇಶದಲ್ಲಿ Vc = E(1 − e^(−t/RC)); ವಿಸರ್ಜನೆಯಲ್ಲಿ Vc = E e^(−t/RC). ಆದ್ದರಿಂದ ln(1 − Vc/E) ಅಥವಾ ln(Vc/E), t ಯೊಂದಿಗೆ −1/τ ಇಳಿಜಾರಿನ ಸರಳರೇಖೆಯಲ್ಲಿ ಇಳಿಯುತ್ತದೆ, τ = RC. ಒಂದು ಕಾಲ ಸ್ಥಿರಾಂಕದಲ್ಲಿ ಧಾರಕ 63 % ದಾರಿ ಕ್ರಮಿಸುತ್ತದೆ."},"apparatus":[{"en":"Electrolytic capacitors (100, 220, 470 µF)","hi":"विद्युत-अपघटनी संधारित्र (100, 220, 470 µF)","kn":"ವಿದ್ಯುದ್ವಿಭಜಕ ಧಾರಕಗಳು (100, 220, 470 µF)"},{"en":"Resistors (10, 47, 100 kΩ)","hi":"प्रतिरोधक (10, 47, 100 kΩ)","kn":"ರೋಧಕಗಳು (10, 47, 100 kΩ)"},{"en":"9 V battery","hi":"9 V बैटरी","kn":"9 V ಬ್ಯಾಟರಿ"},{"en":"Two-way switch","hi":"द्विमार्गी स्विच","kn":"ಎರಡು-ದಾರಿ ಸ್ವಿಚ್"},{"en":"High-resistance digital voltmeter","hi":"उच्च प्रतिरोध वाला अंकीय वोल्टमीटर","kn":"ಹೆಚ್ಚಿನ ರೋಧದ ಡಿಜಿಟಲ್ ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"}],"steps":[{"en":"Discharge the capacitor fully. Connect the battery, switch, resistor and capacitor in series, with the voltmeter across the capacitor.","hi":"संधारित्र को पूरा निरावेशित करें। बैटरी, स्विच, प्रतिरोधक और संधारित्र श्रेणी में जोड़ें, वोल्टमीटर संधारित्र के सिरों पर।","kn":"ಧಾರಕವನ್ನು ಸಂಪೂರ್ಣ ವಿಸರ್ಜಿಸಿ. ಬ್ಯಾಟರಿ, ಸ್ವಿಚ್, ರೋಧಕ ಮತ್ತು ಧಾರಕವನ್ನು ಸರಣಿಯಲ್ಲಿ ಜೋಡಿಸಿ; ವೋಲ್ಟ್‌ಮೀಟರ್ ಧಾರಕಕ್ಕೆ ಅಡ್ಡಲಾಗಿ."},{"en":"Close the switch and start the stopwatch together. Record Vc every 5 s.","hi":"स्विच बंद करें और साथ ही विराम घड़ी चालू करें। हर 5 s पर Vc लिखें।","kn":"ಸ್ವಿಚ್ ಮುಚ್ಚಿ ಜೊತೆಗೇ ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ. ಪ್ರತಿ 5 s ಗೆ Vc ದಾಖಲಿಸಿ."},{"en":"When it is fully charged, switch to discharge through the same resistor and record Vc again.","hi":"पूरा आवेशित होने पर उसी प्रतिरोधक से निरावेशन पर स्विच करें और फिर Vc लिखें।","kn":"ಪೂರ್ಣ ಆವೇಶವಾದಾಗ ಅದೇ ರೋಧಕದ ಮೂಲಕ ವಿಸರ್ಜನೆಗೆ ಬದಲಿಸಿ ಮತ್ತೆ Vc ದಾಖಲಿಸಿ."},{"en":"Plot Vc against t, and ln(1 − Vc/E) (or ln(Vc/E)) against t.","hi":"Vc और t, तथा ln(1 − Vc/E) (या ln(Vc/E)) और t के ग्राफ़ बनाएँ।","kn":"Vc ಮತ್ತು t, ಹಾಗೂ ln(1 − Vc/E) (ಅಥವಾ ln(Vc/E)) ಮತ್ತು t ನಕ್ಷೆಗಳನ್ನು ಎಳೆಯಿರಿ."},{"en":"Find τ from the slope and compare it with R × C.","hi":"प्रवणता से τ ज्ञात करें और R × C से तुलना करें।","kn":"ಇಳಿಜಾರಿನಿಂದ τ ಕಂಡುಹಿಡಿದು R × C ಯೊಂದಿಗೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Connect the electrolytic capacitor the right way round.","hi":"विद्युत-अपघटनी संधारित्र सही दिशा में जोड़ें।","kn":"ವಿದ್ಯುದ್ವಿಭಜಕ ಧಾರಕವನ್ನು ಸರಿಯಾದ ದಿಕ್ಕಿನಲ್ಲಿ ಜೋಡಿಸಿ."},{"en":"Use a voltmeter of much higher resistance than R, or it will discharge the capacitor.","hi":"R से बहुत अधिक प्रतिरोध वाला वोल्टमीटर लें, नहीं तो वह संधारित्र को निरावेशित कर देगा।","kn":"R ಗಿಂತ ಬಹಳ ಹೆಚ್ಚು ರೋಧದ ವೋಲ್ಟ್‌ಮೀಟರ್ ಬಳಸಿ, ಇಲ್ಲದಿದ್ದರೆ ಅದು ಧಾರಕವನ್ನು ವಿಸರ್ಜಿಸುತ್ತದೆ."},{"en":"Start the stopwatch exactly when the switch is closed.","hi":"स्विच बंद करते ही ठीक उसी क्षण विराम घड़ी चालू करें।","kn":"ಸ್ವಿಚ್ ಮುಚ್ಚಿದ ಕ್ಷಣದಲ್ಲೇ ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ."}],"conclusion":{"en":"The capacitor charges and discharges exponentially; the log graph is a straight line and the measured time constant agrees with RC.","hi":"संधारित्र चरघातांकी रूप से आवेशित और निरावेशित होता है; लघुगणक ग्राफ़ सीधी रेखा है और मापा गया समय नियतांक RC से मेल खाता है।","kn":"ಧಾರಕ ಘಾತೀಯವಾಗಿ ಆವೇಶ ಮತ್ತು ವಿಸರ್ಜನೆಯಾಗುತ್ತದೆ; ಲಾಗ್ ನಕ್ಷೆ ಸರಳರೇಖೆ, ಅಳೆದ ಕಾಲ ಸ್ಥಿರಾಂಕ RC ಗೆ ಹೊಂದುತ್ತದೆ."},"viva":[{"q":{"en":"What fraction of E is reached after one time constant while charging?","hi":"आवेशन में एक समय नियतांक के बाद E का कितना भाग पहुँचता है?","kn":"ಆವೇಶದಲ್ಲಿ ಒಂದು ಕಾಲ ಸ್ಥಿರಾಂಕದ ನಂತರ E ಯ ಎಷ್ಟು ಭಾಗ ತಲುಪುತ್ತದೆ?"},"a":{"en":"About 63 % (1 − 1/e).","hi":"लगभग 63 % (1 − 1/e).","kn":"ಸುಮಾರು 63 % (1 − 1/e)."}},{"q":{"en":"Show that RC has the unit of time.","hi":"दिखाइए कि RC की इकाई समय की है।","kn":"RC ಯ ಏಕಮಾನ ಸಮಯವೆಂದು ತೋರಿಸಿ."},"a":{"en":"Ω × F = (V/A) × (C/V) = C/A = s.","hi":"Ω × F = (V/A) × (C/V) = C/A = s.","kn":"Ω × F = (V/A) × (C/V) = C/A = s."}},{"q":{"en":"Where are RC circuits used?","hi":"RC परिपथ कहाँ प्रयोग होते हैं?","kn":"RC ಮಂಡಲಗಳು ಎಲ್ಲಿ ಬಳಕೆಯಾಗುತ್ತವೆ?"},"a":{"en":"In timers, filters, camera flashes and to smooth rectified DC.","hi":"टाइमर, फ़िल्टर, कैमरा फ़्लैश और दिष्टकृत DC को समतल करने में।","kn":"ಟೈಮರ್, ಫಿಲ್ಟರ್, ಕ್ಯಾಮೆರಾ ಫ್ಲ್ಯಾಶ್ ಮತ್ತು ಸರಿಪಡಿಸಿದ DC ನಯಗೊಳಿಸಲು."}}]},{"id":"lcr-resonance","bench":"rlc","setup":{},"subject":"Physics","domain":"physics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ka-puc","ug-physics"],"reviewed":false,"keywords":["alternating current","lcr","series resonance","resonance","resonant frequency","quality factor","ac circuit"],"title":{"en":"Series LCR resonance","hi":"श्रेणी LCR अनुनाद","kn":"ಸರಣಿ LCR ಅನುನಾದ"},"summary":{"en":"Sweep the frequency of an AC supply across an LCR circuit and find the resonant frequency and Q factor.","hi":"LCR परिपथ में AC आपूर्ति की आवृत्ति बदलें और अनुनादी आवृत्ति तथा Q गुणांक ज्ञात करें।","kn":"LCR ಮಂಡಲದಲ್ಲಿ AC ಪೂರೈಕೆಯ ಆವರ್ತನವನ್ನು ಬದಲಿಸಿ ಅನುನಾದ ಆವರ್ತನ ಮತ್ತು Q ಅಂಶ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To draw the resonance curve of a series LCR circuit and find its resonant frequency and quality factor.","hi":"श्रेणी LCR परिपथ का अनुनाद वक्र खींचना और उसकी अनुनादी आवृत्ति तथा गुणता गुणांक ज्ञात करना।","kn":"ಸರಣಿ LCR ಮಂಡಲದ ಅನುನಾದ ವಕ್ರ ಎಳೆದು ಅದರ ಅನುನಾದ ಆವರ್ತನ ಮತ್ತು ಗುಣಮಟ್ಟ ಅಂಶ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"The impedance is Z = √(R² + (ωL − 1/ωC)²). At f₀ = 1/(2π√LC) the inductive and capacitive reactances cancel, Z = R and the current is largest, I = V/R. The sharpness is the quality factor Q = f₀ ÷ (f₂ − f₁) = (1/R)√(L/C), where f₁ and f₂ are the half-power frequencies (I = Imax/√2).","hi":"प्रतिबाधा Z = √(R² + (ωL − 1/ωC)²) है। f₀ = 1/(2π√LC) पर प्रेरकीय और धारितीय प्रतिघात एक-दूसरे को निरस्त करते हैं, Z = R और धारा सबसे अधिक, I = V/R होती है। तीक्ष्णता गुणता गुणांक Q = f₀ ÷ (f₂ − f₁) = (1/R)√(L/C) है, जहाँ f₁ और f₂ अर्ध-शक्ति आवृत्तियाँ (I = Imax/√2) हैं।","kn":"ಪ್ರತಿರೋಧ Z = √(R² + (ωL − 1/ωC)²). f₀ = 1/(2π√LC) ನಲ್ಲಿ ಪ್ರೇರಕ ಮತ್ತು ಧಾರಕ ಪ್ರತಿಘಾತಗಳು ರದ್ದಾಗುತ್ತವೆ, Z = R, ಪ್ರವಾಹ ಗರಿಷ್ಠ, I = V/R. ತೀಕ್ಷ್ಣತೆ ಗುಣಮಟ್ಟ ಅಂಶ Q = f₀ ÷ (f₂ − f₁) = (1/R)√(L/C); f₁, f₂ ಅರ್ಧ-ಶಕ್ತಿ ಆವರ್ತನಗಳು (I = Imax/√2)."},"apparatus":[{"en":"Audio-frequency signal generator","hi":"श्रव्य आवृत्ति संकेत जनित्र","kn":"ಶ್ರವ್ಯ ಆವರ್ತನ ಸಂಕೇತ ಜನಕ"},{"en":"Inductor (50–200 mH)","hi":"प्रेरक (50–200 mH)","kn":"ಪ್ರೇರಕ (50–200 mH)"},{"en":"Capacitor (0.47–2.2 µF)","hi":"संधारित्र (0.47–2.2 µF)","kn":"ಧಾರಕ (0.47–2.2 µF)"},{"en":"Resistor (10–100 Ω)","hi":"प्रतिरोधक (10–100 Ω)","kn":"ರೋಧಕ (10–100 Ω)"},{"en":"AC milliammeter","hi":"AC मिलीऐमीटर","kn":"AC ಮಿಲಿಅಮ್ಮೀಟರ್"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect the signal generator, R, L, C and the AC milliammeter in series. Keep the generator voltage fixed (2 V).","hi":"संकेत जनित्र, R, L, C और AC मिलीऐमीटर श्रेणी में जोड़ें। जनित्र की वोल्टता नियत (2 V) रखें।","kn":"ಸಂಕೇತ ಜನಕ, R, L, C ಮತ್ತು AC ಮಿಲಿಅಮ್ಮೀಟರನ್ನು ಸರಣಿಯಲ್ಲಿ ಜೋಡಿಸಿ. ಜನಕದ ವೋಲ್ಟೇಜ್ ಸ್ಥಿರ (2 V)."},{"en":"Start at a low frequency and raise it in steps, recording the current each time.","hi":"कम आवृत्ति से शुरू कर चरणों में बढ़ाएँ और हर बार धारा लिखें।","kn":"ಕಡಿಮೆ ಆವರ್ತನದಿಂದ ಆರಂಭಿಸಿ ಹಂತಗಳಲ್ಲಿ ಹೆಚ್ಚಿಸಿ, ಪ್ರತಿ ಬಾರಿ ಪ್ರವಾಹ ದಾಖಲಿಸಿ."},{"en":"Take close readings near the maximum current.","hi":"अधिकतम धारा के पास पाठ्यांक पास-पास लें।","kn":"ಗರಿಷ್ಠ ಪ್ರವಾಹದ ಹತ್ತಿರ ಹತ್ತಿರ ಹತ್ತಿರ ಓದುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಿ."},{"en":"Plot I against f; read f₀ and the half-power points and work out Q.","hi":"I और f का ग्राफ़ बनाएँ; f₀ और अर्ध-शक्ति बिंदु पढ़ें और Q निकालें।","kn":"I ಮತ್ತು f ನಕ್ಷೆ ಎಳೆಯಿರಿ; f₀ ಮತ್ತು ಅರ್ಧ-ಶಕ್ತಿ ಬಿಂದುಗಳನ್ನು ಓದಿ Q ಲೆಕ್ಕಿಸಿ."},{"en":"Repeat with a larger R and compare the sharpness.","hi":"बड़े R के साथ दोहराएँ और तीक्ष्णता की तुलना करें।","kn":"ದೊಡ್ಡ R ನೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ತೀಕ್ಷ್ಣತೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Keep the generator output voltage the same at every frequency.","hi":"हर आवृत्ति पर जनित्र की निर्गत वोल्टता समान रखें।","kn":"ಪ್ರತಿ ಆವರ್ತನದಲ್ಲೂ ಜನಕದ ಹೊರಹರಿವು ವೋಲ್ಟೇಜ್ ಒಂದೇ ಇರಲಿ."},{"en":"Near resonance the voltages across L and C can be much larger than the supply: do not touch them.","hi":"अनुनाद के पास L और C के सिरों की वोल्टता आपूर्ति से बहुत अधिक हो सकती है: उन्हें न छुएँ।","kn":"ಅನುನಾದದ ಹತ್ತಿರ L ಮತ್ತು C ಗೆ ಅಡ್ಡ ವೋಲ್ಟೇಜ್ ಪೂರೈಕೆಗಿಂತ ಬಹಳ ಹೆಚ್ಚಿರಬಹುದು: ಅವುಗಳನ್ನು ಮುಟ್ಟಬೇಡಿ."}],"conclusion":{"en":"The current peaks at f₀ = 1/(2π√LC) where it equals V/R; a smaller resistance gives a sharper peak (higher Q).","hi":"धारा f₀ = 1/(2π√LC) पर शिखर पर होती है जहाँ वह V/R के बराबर है; छोटा प्रतिरोध अधिक तीक्ष्ण शिखर (अधिक Q) देता है।","kn":"ಪ್ರವಾಹ f₀ = 1/(2π√LC) ನಲ್ಲಿ ಶಿಖರ ತಲುಪುತ್ತದೆ, ಅಲ್ಲಿ ಅದು V/R; ಕಡಿಮೆ ರೋಧ ಹೆಚ್ಚು ತೀಕ್ಷ್ಣ ಶಿಖರ (ಹೆಚ್ಚು Q) ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"What is the phase difference between V and I at resonance?","hi":"अनुनाद पर V और I के बीच कलांतर कितना है?","kn":"ಅನುನಾದದಲ್ಲಿ V ಮತ್ತು I ನಡುವಿನ ಹಂತ ವ್ಯತ್ಯಾಸ ಎಷ್ಟು?"},"a":{"en":"Zero: the circuit is purely resistive.","hi":"शून्य: परिपथ शुद्ध प्रतिरोधी है।","kn":"ಶೂನ್ಯ: ಮಂಡಲ ಸಂಪೂರ್ಣ ರೋಧಕ."}},{"q":{"en":"Where is series resonance used?","hi":"श्रेणी अनुनाद कहाँ प्रयोग होता है?","kn":"ಸರಣಿ ಅನುನಾದ ಎಲ್ಲಿ ಬಳಕೆಯಾಗುತ್ತದೆ?"},"a":{"en":"In tuning a radio to one station.","hi":"रेडियो को किसी एक स्टेशन पर समस्वरित करने में।","kn":"ರೇಡಿಯೊವನ್ನು ಒಂದು ಕೇಂದ್ರಕ್ಕೆ ಶ್ರುತಿಗೊಳಿಸಲು."}},{"q":{"en":"How does f₀ change if C is made four times larger?","hi":"C चार गुना करने पर f₀ कैसे बदलेगी?","kn":"C ಯನ್ನು ನಾಲ್ಕು ಪಟ್ಟು ಮಾಡಿದರೆ f₀ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?"},"a":{"en":"It halves.","hi":"वह आधी हो जाती है।","kn":"ಅದು ಅರ್ಧವಾಗುತ್ತದೆ."}}]},{"id":"opamp-inverting","bench":"opamp","setup":{"config":"inverting"},"subject":"Electronics","domain":"electronics","levels":["ug"],"mode":"guided","curricula":["ug-electronics"],"reviewed":false,"keywords":["operational amplifier","op-amp","op amp","inverting amplifier","gain","negative feedback","741"],"title":{"en":"Op-amp inverting amplifier","hi":"ऑप-ऐम्प प्रतिलोमी प्रवर्धक","kn":"ಆಪ್-ಆಂಪ್ ವಿಲೋಮ ವರ್ಧಕ"},"summary":{"en":"Measure the output of an inverting amplifier against its input and check the gain −Rf/Rin.","hi":"प्रतिलोमी प्रवर्धक का निर्गत उसके निवेश के सापेक्ष मापें और लब्धि −Rf/Rin जाँचें।","kn":"ವಿಲೋಮ ವರ್ಧಕದ ಹೊರಹರಿವನ್ನು ಒಳಹರಿವಿನ ವಿರುದ್ಧ ಅಳೆದು ಲಾಭ −Rf/Rin ಪರಿಶೀಲಿಸಿ."},"aim":{"en":"To study an op-amp inverting amplifier and verify that its gain is −Rf/Rin.","hi":"ऑप-ऐम्प प्रतिलोमी प्रवर्धक का अध्ययन करना और सत्यापित करना कि उसकी लब्धि −Rf/Rin है।","kn":"ಆಪ್-ಆಂಪ್ ವಿಲೋಮ ವರ್ಧಕವನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ ಅದರ ಲಾಭ −Rf/Rin ಎಂದು ಪರಿಶೀಲಿಸುವುದು."},"principle":{"en":"The + input is grounded, so the − input is held at 0 V (virtual ground). The input current Vin/Rin all flows through Rf, so Vout = −(Rf/Rin) Vin: the output is inverted and amplified, until it reaches the supply rails.","hi":"+ निवेश भू से जुड़ा है, इसलिए − निवेश 0 V (आभासी भू) पर रहता है। निवेश धारा Vin/Rin पूरी Rf से बहती है, इसलिए Vout = −(Rf/Rin) Vin: निर्गत उलटा और प्रवर्धित होता है, जब तक वह आपूर्ति सीमा तक न पहुँचे।","kn":"+ ಒಳಹರಿವು ನೆಲಕ್ಕೆ ಜೋಡಿಸಿದೆ; ಆದ್ದರಿಂದ − ಒಳಹರಿವು 0 V (ಮಿಥ್ಯ ನೆಲ) ನಲ್ಲಿರುತ್ತದೆ. ಒಳಹರಿವು ಪ್ರವಾಹ Vin/Rin ಸಂಪೂರ್ಣ Rf ಮೂಲಕ ಹರಿಯುತ್ತದೆ; ಆದ್ದರಿಂದ Vout = −(Rf/Rin) Vin: ಹೊರಹರಿವು ಪೂರೈಕೆ ಮಿತಿ ತಲುಪುವವರೆಗೆ ವಿಲೋಮ ಮತ್ತು ವರ್ಧಿತ."},"apparatus":[{"en":"Op-amp IC 741","hi":"ऑप-ऐम्प IC 741","kn":"ಆಪ್-ಆಂಪ್ IC 741"},{"en":"Dual supply ±15 V","hi":"द्वि-आपूर्ति ±15 V","kn":"ದ್ವಿ ಪೂರೈಕೆ ±15 V"},{"en":"Resistors for Rf and Rin","hi":"Rf और Rin के लिए प्रतिरोधक","kn":"Rf ಮತ್ತು Rin ಗಾಗಿ ರೋಧಕಗಳು"},{"en":"Variable DC input (−2 to +2 V)","hi":"परिवर्ती DC निवेश (−2 से +2 V)","kn":"ಬದಲಾಯಿಸಬಹುದಾದ DC ಒಳಹರಿವು (−2 ರಿಂದ +2 V)"},{"en":"Digital multimeters","hi":"अंकीय मल्टीमीटर","kn":"ಡಿಜಿಟಲ್ ಮಲ್ಟಿಮೀಟರ್‌ಗಳು"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect Rin from the input to the − terminal, Rf from the output back to −, and ground the + terminal.","hi":"Rin को निवेश से − सिरे तक, Rf को निर्गत से वापस − तक जोड़ें और + सिरे को भू से जोड़ें।","kn":"Rin ಅನ್ನು ಒಳಹರಿವಿನಿಂದ − ತುದಿಗೆ, Rf ಅನ್ನು ಹೊರಹರಿವಿನಿಂದ − ಗೆ ಜೋಡಿಸಿ, + ತುದಿಯನ್ನು ನೆಲಕ್ಕೆ ಜೋಡಿಸಿ."},{"en":"Set Rf = 10 kΩ, Rin = 1 kΩ. Apply inputs from −2 V to +2 V and record Vout.","hi":"Rf = 10 kΩ, Rin = 1 kΩ रखें। −2 V से +2 V तक निवेश देकर Vout लिखें।","kn":"Rf = 10 kΩ, Rin = 1 kΩ. −2 V ರಿಂದ +2 V ವರೆಗೆ ಒಳಹರಿವು ನೀಡಿ Vout ದಾಖಲಿಸಿ."},{"en":"Plot Vout against Vin; find the slope in the straight part.","hi":"Vout और Vin का ग्राफ़ बनाएँ; सीधे भाग की प्रवणता ज्ञात करें।","kn":"Vout ಮತ್ತು Vin ನಕ್ಷೆ ಎಳೆದು ನೇರ ಭಾಗದ ಇಳಿಜಾರು ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Change Rf and Rin and check the gain each time.","hi":"Rf और Rin बदलें और हर बार लब्धि जाँचें।","kn":"Rf ಮತ್ತು Rin ಬದಲಿಸಿ ಪ್ರತಿ ಬಾರಿ ಲಾಭ ಪರಿಶೀಲಿಸಿ."}],"precautions":[{"en":"Connect the ±15 V supply to pins 7 and 4 before applying the input.","hi":"निवेश देने से पहले ±15 V आपूर्ति पिन 7 और 4 से जोड़ें।","kn":"ಒಳಹರಿವು ನೀಡುವ ಮೊದಲು ±15 V ಪೂರೈಕೆಯನ್ನು ಪಿನ್ 7 ಮತ್ತು 4 ಕ್ಕೆ ಜೋಡಿಸಿ."},{"en":"Keep the input small enough that the output does not saturate (about ±13.5 V).","hi":"निवेश इतना छोटा रखें कि निर्गत संतृप्त न हो (लगभग ±13.5 V)।","kn":"ಹೊರಹರಿವು ಸಂತೃಪ್ತವಾಗದಷ್ಟು (ಸುಮಾರು ±13.5 V) ಒಳಹರಿವನ್ನು ಸಣ್ಣದಾಗಿಡಿ."},{"en":"Switch off the supply when changing connections.","hi":"संयोजन बदलते समय आपूर्ति बंद कर दें।","kn":"ಸಂಪರ್ಕ ಬದಲಿಸುವಾಗ ಪೂರೈಕೆ ಆಫ್ ಮಾಡಿ."}],"conclusion":{"en":"In the linear range Vout = −(Rf/Rin) Vin; beyond it the output saturates at the rails.","hi":"रैखिक परास में Vout = −(Rf/Rin) Vin; उससे आगे निर्गत सीमाओं पर संतृप्त हो जाता है।","kn":"ರೇಖೀಯ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ Vout = −(Rf/Rin) Vin; ಅದರ ಆಚೆ ಹೊರಹರಿವು ಮಿತಿಗಳಲ್ಲಿ ಸಂತೃಪ್ತ."},"viva":[{"q":{"en":"What are the two golden rules of an ideal op-amp with negative feedback?","hi":"ऋणात्मक पुनर्निवेश वाले आदर्श ऑप-ऐम्प के दो स्वर्णिम नियम क्या हैं?","kn":"ಋಣ ಪ್ರತಿಪೋಷಣೆಯ ಆದರ್ಶ ಆಪ್-ಆಂಪ್‌ನ ಎರಡು ಸುವರ್ಣ ನಿಯಮಗಳು ಯಾವುವು?"},"a":{"en":"No current flows into the inputs, and the output makes the two inputs equal in voltage.","hi":"निवेशों में कोई धारा नहीं जाती, और निर्गत दोनों निवेशों की वोल्टता बराबर कर देता है।","kn":"ಒಳಹರಿವುಗಳಿಗೆ ಪ್ರವಾಹ ಹರಿಯುವುದಿಲ್ಲ; ಹೊರಹರಿವು ಎರಡು ಒಳಹರಿವುಗಳ ವೋಲ್ಟೇಜನ್ನು ಸಮಗೊಳಿಸುತ್ತದೆ."}},{"q":{"en":"Why does the output saturate near ±13.5 V?","hi":"निर्गत ±13.5 V के पास संतृप्त क्यों होता है?","kn":"ಹೊರಹರಿವು ±13.5 V ಹತ್ತಿರ ಏಕೆ ಸಂತೃಪ್ತವಾಗುತ್ತದೆ?"},"a":{"en":"It cannot exceed the supply rails (±15 V) less a small internal drop.","hi":"यह आपूर्ति सीमाओं (±15 V) से थोड़ा कम से अधिक नहीं जा सकता।","kn":"ಅದು ಪೂರೈಕೆ ಮಿತಿಗಳಿಗಿಂತ (±15 V) ಸ್ವಲ್ಪ ಕಡಿಮೆಗಿಂತ ಹೆಚ್ಚು ಹೋಗಲಾರದು."}},{"q":{"en":"What is a virtual ground?","hi":"आभासी भू क्या है?","kn":"ಮಿಥ್ಯ ನೆಲ ಎಂದರೇನು?"},"a":{"en":"A point held at 0 V by feedback though not connected to ground.","hi":"ऐसा बिंदु जो भू से जुड़ा न होते हुए भी पुनर्निवेश से 0 V पर रहता है।","kn":"ನೆಲಕ್ಕೆ ಜೋಡಿಸದಿದ್ದರೂ ಪ್ರತಿಪೋಷಣೆಯಿಂದ 0 V ನಲ್ಲಿರುವ ಬಿಂದು."}}]},{"id":"opamp-non-inverting","bench":"opamp","setup":{"config":"non-inverting"},"subject":"Electronics","domain":"electronics","levels":["ug"],"mode":"guided","curricula":["ug-electronics"],"reviewed":false,"keywords":["operational amplifier","op-amp","op amp","non-inverting amplifier","gain","voltage follower","741"],"title":{"en":"Op-amp non-inverting amplifier","hi":"ऑप-ऐम्प अप्रतिलोमी प्रवर्धक","kn":"ಆಪ್-ಆಂಪ್ ಅವಿಲೋಮ ವರ್ಧಕ"},"summary":{"en":"Feed the signal to the + input and verify the gain 1 + Rf/R1.","hi":"संकेत + निवेश पर दें और लब्धि 1 + Rf/R1 सत्यापित करें।","kn":"ಸಂಕೇತವನ್ನು + ಒಳಹರಿವಿಗೆ ನೀಡಿ ಲಾಭ 1 + Rf/R1 ಪರಿಶೀಲಿಸಿ."},"aim":{"en":"To study an op-amp non-inverting amplifier and verify that its gain is 1 + Rf/R1.","hi":"ऑप-ऐम्प अप्रतिलोमी प्रवर्धक का अध्ययन करना और सत्यापित करना कि उसकी लब्धि 1 + Rf/R1 है।","kn":"ಆಪ್-ಆಂಪ್ ಅವಿಲೋಮ ವರ್ಧಕವನ್ನು ಅಧ್ಯಯನ ಮಾಡಿ ಅದರ ಲಾಭ 1 + Rf/R1 ಎಂದು ಪರಿಶೀಲಿಸುವುದು."},"principle":{"en":"The signal goes to the + input. Rf and R1 divide the output so the − input gets Vout·R1/(R1 + Rf); the op-amp makes this equal to Vin, so Vout = (1 + Rf/R1) Vin, in phase with the input. With Rf = 0 it becomes a voltage follower (gain 1).","hi":"संकेत + निवेश पर जाता है। Rf और R1 निर्गत को विभाजित करते हैं जिससे − निवेश को Vout·R1/(R1 + Rf) मिलता है; ऑप-ऐम्प इसे Vin के बराबर कर देता है, इसलिए Vout = (1 + Rf/R1) Vin, निवेश के साथ समान कला में। Rf = 0 होने पर यह वोल्टता अनुगामी (लब्धि 1) बन जाता है।","kn":"ಸಂಕೇತ + ಒಳಹರಿವಿಗೆ ಹೋಗುತ್ತದೆ. Rf ಮತ್ತು R1 ಹೊರಹರಿವನ್ನು ವಿಭಜಿಸಿ − ಒಳಹರಿವಿಗೆ Vout·R1/(R1 + Rf) ನೀಡುತ್ತವೆ; ಆಪ್-ಆಂಪ್ ಇದನ್ನು Vin ಗೆ ಸಮಗೊಳಿಸುತ್ತದೆ; ಆದ್ದರಿಂದ Vout = (1 + Rf/R1) Vin, ಒಳಹರಿವಿನ ಹಂತದಲ್ಲೇ. Rf = 0 ಆದರೆ ಅದು ವೋಲ್ಟೇಜ್ ಅನುಸರಕ (ಲಾಭ 1)."},"apparatus":[{"en":"Op-amp IC 741","hi":"ऑप-ऐम्प IC 741","kn":"ಆಪ್-ಆಂಪ್ IC 741"},{"en":"Dual supply ±15 V","hi":"द्वि-आपूर्ति ±15 V","kn":"ದ್ವಿ ಪೂರೈಕೆ ±15 V"},{"en":"Resistors for Rf and Rin","hi":"Rf और Rin के लिए प्रतिरोधक","kn":"Rf ಮತ್ತು Rin ಗಾಗಿ ರೋಧಕಗಳು"},{"en":"Variable DC input (−2 to +2 V)","hi":"परिवर्ती DC निवेश (−2 से +2 V)","kn":"ಬದಲಾಯಿಸಬಹುದಾದ DC ಒಳಹರಿವು (−2 ರಿಂದ +2 V)"},{"en":"Digital multimeters","hi":"अंकीय मल्टीमीटर","kn":"ಡಿಜಿಟಲ್ ಮಲ್ಟಿಮೀಟರ್‌ಗಳು"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect the input to the + terminal; R1 from − to ground; Rf from the output to −.","hi":"निवेश को + सिरे से; R1 को − से भू तक; Rf को निर्गत से − तक जोड़ें।","kn":"ಒಳಹರಿವನ್ನು + ತುದಿಗೆ; R1 ಅನ್ನು − ಇಂದ ನೆಲಕ್ಕೆ; Rf ಅನ್ನು ಹೊರಹರಿವಿನಿಂದ − ಗೆ ಜೋಡಿಸಿ."},{"en":"Apply inputs from −2 V to +2 V and record Vout.","hi":"−2 V से +2 V तक निवेश देकर Vout लिखें।","kn":"−2 V ರಿಂದ +2 V ವರೆಗೆ ಒಳಹರಿವು ನೀಡಿ Vout ದಾಖಲಿಸಿ."},{"en":"Plot Vout against Vin and find the slope.","hi":"Vout और Vin का ग्राफ़ बनाकर प्रवणता ज्ञात करें।","kn":"Vout ಮತ್ತು Vin ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರು ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Compare the slope with 1 + Rf/R1 for two pairs of resistors.","hi":"प्रतिरोधकों के दो युग्मों के लिए प्रवणता की तुलना 1 + Rf/R1 से करें।","kn":"ಎರಡು ರೋಧಕ ಜೋಡಿಗಳಿಗೆ ಇಳಿಜಾರನ್ನು 1 + Rf/R1 ಯೊಂದಿಗೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Connect the ±15 V supply to pins 7 and 4 before applying the input.","hi":"निवेश देने से पहले ±15 V आपूर्ति पिन 7 और 4 से जोड़ें।","kn":"ಒಳಹರಿವು ನೀಡುವ ಮೊದಲು ±15 V ಪೂರೈಕೆಯನ್ನು ಪಿನ್ 7 ಮತ್ತು 4 ಕ್ಕೆ ಜೋಡಿಸಿ."},{"en":"Keep the input small enough that the output does not saturate (about ±13.5 V).","hi":"निवेश इतना छोटा रखें कि निर्गत संतृप्त न हो (लगभग ±13.5 V)।","kn":"ಹೊರಹರಿವು ಸಂತೃಪ್ತವಾಗದಷ್ಟು (ಸುಮಾರು ±13.5 V) ಒಳಹರಿವನ್ನು ಸಣ್ಣದಾಗಿಡಿ."},{"en":"Switch off the supply when changing connections.","hi":"संयोजन बदलते समय आपूर्ति बंद कर दें।","kn":"ಸಂಪರ್ಕ ಬದಲಿಸುವಾಗ ಪೂರೈಕೆ ಆಫ್ ಮಾಡಿ."}],"conclusion":{"en":"The output is in phase with the input and Vout = (1 + Rf/R1) Vin in the linear range; the gain is never less than 1.","hi":"निर्गत निवेश के साथ समान कला में है और रैखिक परास में Vout = (1 + Rf/R1) Vin; लब्धि कभी 1 से कम नहीं होती।","kn":"ಹೊರಹರಿವು ಒಳಹರಿವಿನ ಹಂತದಲ್ಲೇ; ರೇಖೀಯ ವ್ಯಾಪ್ತಿಯಲ್ಲಿ Vout = (1 + Rf/R1) Vin; ಲಾಭ ಎಂದೂ 1 ಕ್ಕಿಂತ ಕಡಿಮೆಯಿಲ್ಲ."},"viva":[{"q":{"en":"What are the two golden rules of an ideal op-amp with negative feedback?","hi":"ऋणात्मक पुनर्निवेश वाले आदर्श ऑप-ऐम्प के दो स्वर्णिम नियम क्या हैं?","kn":"ಋಣ ಪ್ರತಿಪೋಷಣೆಯ ಆದರ್ಶ ಆಪ್-ಆಂಪ್‌ನ ಎರಡು ಸುವರ್ಣ ನಿಯಮಗಳು ಯಾವುವು?"},"a":{"en":"No current flows into the inputs, and the output makes the two inputs equal in voltage.","hi":"निवेशों में कोई धारा नहीं जाती, और निर्गत दोनों निवेशों की वोल्टता बराबर कर देता है।","kn":"ಒಳಹರಿವುಗಳಿಗೆ ಪ್ರವಾಹ ಹರಿಯುವುದಿಲ್ಲ; ಹೊರಹರಿವು ಎರಡು ಒಳಹರಿವುಗಳ ವೋಲ್ಟೇಜನ್ನು ಸಮಗೊಳಿಸುತ್ತದೆ."}},{"q":{"en":"Why does the output saturate near ±13.5 V?","hi":"निर्गत ±13.5 V के पास संतृप्त क्यों होता है?","kn":"ಹೊರಹರಿವು ±13.5 V ಹತ್ತಿರ ಏಕೆ ಸಂತೃಪ್ತವಾಗುತ್ತದೆ?"},"a":{"en":"It cannot exceed the supply rails (±15 V) less a small internal drop.","hi":"यह आपूर्ति सीमाओं (±15 V) से थोड़ा कम से अधिक नहीं जा सकता।","kn":"ಅದು ಪೂರೈಕೆ ಮಿತಿಗಳಿಗಿಂತ (±15 V) ಸ್ವಲ್ಪ ಕಡಿಮೆಗಿಂತ ಹೆಚ್ಚು ಹೋಗಲಾರದು."}},{"q":{"en":"What is a voltage follower used for?","hi":"वोल्टता अनुगामी किसके लिए प्रयोग होता है?","kn":"ವೋಲ್ಟೇಜ್ ಅನುಸರಕವನ್ನು ಯಾವುದಕ್ಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"As a buffer: very high input resistance and low output resistance with gain 1.","hi":"बफ़र के रूप में: लब्धि 1 के साथ बहुत उच्च निवेश प्रतिरोध और कम निर्गत प्रतिरोध।","kn":"ಬಫರ್ ಆಗಿ: ಲಾಭ 1 ಜೊತೆಗೆ ಅತಿ ಹೆಚ್ಚು ಒಳಹರಿವು ರೋಧ ಮತ್ತು ಕಡಿಮೆ ಹೊರಹರಿವು ರೋಧ."}}]},{"id":"astable-555","bench":"astable","setup":{},"subject":"Electronics","domain":"electronics","levels":["ug"],"mode":"explore","curricula":["ug-electronics"],"reviewed":false,"keywords":["555 timer","555","astable multivibrator","multivibrator","oscillator","square wave","duty cycle"],"title":{"en":"555 timer as an astable multivibrator","hi":"555 टाइमर अस्थिर बहुकंपित्र के रूप में","kn":"555 ಟೈಮರ್ ಅಸ್ಥಿರ ಬಹುಕಂಪಕವಾಗಿ"},"summary":{"en":"Watch the 555 charge and discharge its capacitor between ⅓ and ⅔ Vcc and blink an LED; check the frequency formula.","hi":"देखें कि 555 अपने संधारित्र को ⅓ और ⅔ Vcc के बीच कैसे आवेशित-निरावेशित करता है और LED झपकाता है; आवृत्ति सूत्र जाँचें।","kn":"555 ತನ್ನ ಧಾರಕವನ್ನು ⅓ ಮತ್ತು ⅔ Vcc ನಡುವೆ ಆವೇಶ-ವಿಸರ್ಜನೆ ಮಾಡಿ LED ಮಿನುಗಿಸುವುದನ್ನು ನೋಡಿ; ಆವರ್ತನ ಸೂತ್ರ ಪರಿಶೀಲಿಸಿ."},"aim":{"en":"To build an astable multivibrator with a 555 timer and compare its frequency and duty cycle with the formula.","hi":"555 टाइमर से अस्थिर बहुकंपित्र बनाना और उसकी आवृत्ति तथा कार्य चक्र की तुलना सूत्र से करना।","kn":"555 ಟೈಮರ್‌ನಿಂದ ಅಸ್ಥಿರ ಬಹುಕಂಪಕ ರಚಿಸಿ ಅದರ ಆವರ್ತನ ಮತ್ತು ಕಾರ್ಯ ಚಕ್ರವನ್ನು ಸೂತ್ರದೊಂದಿಗೆ ಹೋಲಿಸುವುದು."},"principle":{"en":"The capacitor charges through RA + RB until it reaches ⅔ Vcc; then the output goes low and the capacitor discharges through RB to ⅓ Vcc, and the cycle repeats. High time = 0.693(RA + RB)C, low time = 0.693 RB C, so f = 1.44 ÷ ((RA + 2RB)C) and the duty cycle is (RA + RB) ÷ (RA + 2RB).","hi":"संधारित्र RA + RB से आवेशित होकर ⅔ Vcc तक पहुँचता है; तब निर्गत निम्न हो जाता है और संधारित्र RB से ⅓ Vcc तक निरावेशित होता है, और चक्र दोहराता है। उच्च समय = 0.693(RA + RB)C, निम्न समय = 0.693 RB C, इसलिए f = 1.44 ÷ ((RA + 2RB)C) और कार्य चक्र (RA + RB) ÷ (RA + 2RB) है।","kn":"ಧಾರಕ RA + RB ಮೂಲಕ ಆವೇಶಗೊಂಡು ⅔ Vcc ತಲುಪುತ್ತದೆ; ಆಗ ಹೊರಹರಿವು ನಿಮ್ನವಾಗಿ ಧಾರಕ RB ಮೂಲಕ ⅓ Vcc ವರೆಗೆ ವಿಸರ್ಜನೆಯಾಗುತ್ತದೆ; ಚಕ್ರ ಪುನರಾವರ್ತಿಸುತ್ತದೆ. ಉನ್ನತ ಸಮಯ = 0.693(RA + RB)C, ನಿಮ್ನ ಸಮಯ = 0.693 RB C; ಆದ್ದರಿಂದ f = 1.44 ÷ ((RA + 2RB)C), ಕಾರ್ಯ ಚಕ್ರ (RA + RB) ÷ (RA + 2RB)."},"apparatus":[{"en":"555 timer IC","hi":"555 टाइमर IC","kn":"555 ಟೈಮರ್ IC"},{"en":"Resistors RA and RB","hi":"प्रतिरोधक RA और RB","kn":"ರೋಧಕಗಳು RA ಮತ್ತು RB"},{"en":"Capacitors (1 µF, 10 µF) and 0.01 µF for pin 5","hi":"संधारित्र (1 µF, 10 µF) और पिन 5 के लिए 0.01 µF","kn":"ಧಾರಕಗಳು (1 µF, 10 µF) ಮತ್ತು ಪಿನ್ 5 ಗೆ 0.01 µF"},{"en":"9 V supply","hi":"9 V आपूर्ति","kn":"9 V ಪೂರೈಕೆ"},{"en":"LED with resistor","hi":"प्रतिरोधक सहित LED","kn":"ರೋಧಕ ಸಹಿತ LED"},{"en":"Cathode-ray oscilloscope (CRO)","hi":"कैथोड किरण दोलनदर्शी (CRO)","kn":"ಕ್ಯಾಥೋಡ್ ಕಿರಣ ಆಂದೋಲನದರ್ಶಕ (CRO)"}],"steps":[{"en":"Wire the 555 as an astable: pins 4 and 8 to Vcc, 1 to ground, RA from Vcc to 7, RB from 7 to 6 and 2, C from 2 to ground, output at 3.","hi":"555 को अस्थिर रूप में जोड़ें: पिन 4 और 8 को Vcc, 1 को भू, RA को Vcc से 7, RB को 7 से 6 और 2, C को 2 से भू, निर्गत 3 पर।","kn":"555 ಅನ್ನು ಅಸ್ಥಿರವಾಗಿ ಜೋಡಿಸಿ: ಪಿನ್ 4 ಮತ್ತು 8 Vcc ಗೆ, 1 ನೆಲಕ್ಕೆ, RA Vcc ಇಂದ 7 ಕ್ಕೆ, RB 7 ರಿಂದ 6 ಮತ್ತು 2 ಕ್ಕೆ, C 2 ರಿಂದ ನೆಲಕ್ಕೆ, ಹೊರಹರಿವು 3 ರಲ್ಲಿ."},{"en":"Watch the output and the capacitor voltage on the CRO.","hi":"CRO पर निर्गत और संधारित्र वोल्टता देखें।","kn":"CRO ನಲ್ಲಿ ಹೊರಹರಿವು ಮತ್ತು ಧಾರಕ ವೋಲ್ಟೇಜ್ ನೋಡಿ."},{"en":"Measure the period and the high time; work out f and the duty cycle.","hi":"आवर्तकाल और उच्च समय मापें; f और कार्य चक्र निकालें।","kn":"ಆವರ್ತಕಾಲ ಮತ್ತು ಉನ್ನತ ಸಮಯ ಅಳೆದು f ಮತ್ತು ಕಾರ್ಯ ಚಕ್ರ ಲೆಕ್ಕಿಸಿ."},{"en":"Change RA, RB and C and compare each time with the formula.","hi":"RA, RB और C बदलें और हर बार सूत्र से तुलना करें।","kn":"RA, RB ಮತ್ತು C ಬದಲಿಸಿ ಪ್ರತಿ ಬಾರಿ ಸೂತ್ರದೊಂದಿಗೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Do not exceed the 555 supply limit (4.5–16 V).","hi":"555 की आपूर्ति सीमा (4.5–16 V) से अधिक न दें।","kn":"555 ರ ಪೂರೈಕೆ ಮಿತಿ (4.5–16 V) ಮೀರಬೇಡಿ."},{"en":"Keep RA at least 1 kΩ so the discharge transistor is not overloaded.","hi":"RA कम से कम 1 kΩ रखें ताकि निरावेशन ट्रांज़िस्टर पर अधिक भार न पड़े।","kn":"ವಿಸರ್ಜನೆ ಟ್ರಾನ್ಸಿಸ್ಟರ್ ಅತಿಭಾರವಾಗದಂತೆ RA ಕನಿಷ್ಠ 1 kΩ ಇರಲಿ."}],"conclusion":{"en":"The 555 produces a square wave whose frequency matches 1.44 ÷ ((RA + 2RB)C); the duty cycle is above 50 % and approaches 50 % when RB is much larger than RA.","hi":"555 एक वर्ग तरंग देता है जिसकी आवृत्ति 1.44 ÷ ((RA + 2RB)C) से मेल खाती है; कार्य चक्र 50 % से अधिक है और RB के RA से बहुत बड़ा होने पर 50 % के निकट पहुँचता है।","kn":"555 ಚೌಕ ತರಂಗ ನೀಡುತ್ತದೆ; ಅದರ ಆವರ್ತನ 1.44 ÷ ((RA + 2RB)C) ಗೆ ಹೊಂದುತ್ತದೆ; ಕಾರ್ಯ ಚಕ್ರ 50 % ಕ್ಕಿಂತ ಹೆಚ್ಚು; RB, RA ಗಿಂತ ಬಹಳ ದೊಡ್ಡದಾದಾಗ 50 % ಸಮೀಪಿಸುತ್ತದೆ."},"viva":[{"q":{"en":"Why is it called astable?","hi":"इसे अस्थिर क्यों कहते हैं?","kn":"ಇದನ್ನು ಅಸ್ಥಿರ ಎಂದು ಏಕೆ ಕರೆಯುತ್ತಾರೆ?"},"a":{"en":"It has no stable state: it keeps switching between high and low by itself.","hi":"इसकी कोई स्थिर अवस्था नहीं: यह स्वयं उच्च और निम्न के बीच बदलता रहता है।","kn":"ಅದಕ್ಕೆ ಸ್ಥಿರ ಸ್ಥಿತಿಯಿಲ್ಲ: ಅದು ತಾನಾಗಿಯೇ ಉನ್ನತ-ನಿಮ್ನ ನಡುವೆ ಬದಲಾಗುತ್ತಿರುತ್ತದೆ."}},{"q":{"en":"Between which voltages does the capacitor swing?","hi":"संधारित्र किन वोल्टताओं के बीच दोलन करता है?","kn":"ಧಾರಕ ಯಾವ ವೋಲ್ಟೇಜ್‌ಗಳ ನಡುವೆ ತೂಗಾಡುತ್ತದೆ?"},"a":{"en":"⅓ Vcc and ⅔ Vcc.","hi":"⅓ Vcc और ⅔ Vcc.","kn":"⅓ Vcc ಮತ್ತು ⅔ Vcc."}},{"q":{"en":"Give one use of an astable multivibrator.","hi":"अस्थिर बहुकंपित्र का एक उपयोग बताइए।","kn":"ಅಸ್ಥಿರ ಬಹುಕಂಪಕದ ಒಂದು ಉಪಯೋಗ ತಿಳಿಸಿ."},"a":{"en":"Clock pulses, LED flashers, tone generators.","hi":"घड़ी स्पंद, LED फ़्लैशर, स्वर जनित्र।","kn":"ಗಡಿಯಾರ ಸ್ಪಂದನಗಳು, LED ಮಿನುಗುಕಗಳು, ಸ್ವರ ಜನಕಗಳು."}}]},{"id":"kirchhoff-laws","bench":"kirchhoff","setup":{},"subject":"Physics","domain":"physics","levels":["12","ug"],"mode":"guided","curricula":["cbse","ka-puc","ug-physics"],"reviewed":false,"keywords":["kirchhoff's laws","kirchhoff","current electricity","junction rule","loop rule","network"],"title":{"en":"Verification of Kirchhoff's laws","hi":"किरखॉफ़ के नियमों का सत्यापन","kn":"ಕಿರ್ಚಾಫ್ ನಿಯಮಗಳ ಪರಿಶೀಲನೆ"},"summary":{"en":"Measure the currents in a two-source network and check the junction and loop rules.","hi":"दो स्रोतों वाले जाल की धाराएँ मापें और संधि तथा पाश नियम जाँचें।","kn":"ಎರಡು ಮೂಲಗಳ ಜಾಲದ ಪ್ರವಾಹಗಳನ್ನು ಅಳೆದು ಸಂಧಿ ಮತ್ತು ಕುಣಿಕೆ ನಿಯಮಗಳನ್ನು ಪರಿಶೀಲಿಸಿ."},"aim":{"en":"To verify Kirchhoff's current law and voltage law in a network with two sources.","hi":"दो स्रोतों वाले जाल में किरखॉफ़ के धारा नियम और वोल्टता नियम का सत्यापन करना।","kn":"ಎರಡು ಮೂಲಗಳ ಜಾಲದಲ್ಲಿ ಕಿರ್ಚಾಫ್‌ನ ಪ್ರವಾಹ ನಿಯಮ ಮತ್ತು ವೋಲ್ಟೇಜ್ ನಿಯಮ ಪರಿಶೀಲಿಸುವುದು."},"principle":{"en":"Junction rule (KCL): the currents entering a junction add up to the currents leaving it (charge is conserved). Loop rule (KVL): round any closed loop the EMFs equal the sum of the IR drops (energy is conserved).","hi":"संधि नियम (KCL): किसी संधि में आने वाली धाराओं का योग उससे जाने वाली धाराओं के योग के बराबर है (आवेश संरक्षण)। पाश नियम (KVL): किसी भी बंद पाश में EMF का योग IR पातों के योग के बराबर है (ऊर्जा संरक्षण)।","kn":"ಸಂಧಿ ನಿಯಮ (KCL): ಸಂಧಿಗೆ ಬರುವ ಪ್ರವಾಹಗಳ ಮೊತ್ತ ಹೊರಹೋಗುವ ಪ್ರವಾಹಗಳ ಮೊತ್ತಕ್ಕೆ ಸಮ (ಆವೇಶ ಸಂರಕ್ಷಣೆ). ಕುಣಿಕೆ ನಿಯಮ (KVL): ಯಾವುದೇ ಮುಚ್ಚಿದ ಕುಣಿಕೆಯಲ್ಲಿ EMF ಗಳ ಮೊತ್ತ IR ಇಳಿತಗಳ ಮೊತ್ತಕ್ಕೆ ಸಮ (ಶಕ್ತಿ ಸಂರಕ್ಷಣೆ)."},"apparatus":[{"en":"Two DC supplies (or batteries)","hi":"दो DC आपूर्तियाँ (या बैटरियाँ)","kn":"ಎರಡು DC ಪೂರೈಕೆಗಳು (ಅಥವಾ ಬ್ಯಾಟರಿಗಳು)"},{"en":"Three resistors","hi":"तीन प्रतिरोधक","kn":"ಮೂರು ರೋಧಕಗಳು"},{"en":"Three milliammeters","hi":"तीन मिलीऐमीटर","kn":"ಮೂರು ಮಿಲಿಅಮ್ಮೀಟರ್‌ಗಳು"},{"en":"Voltmeter","hi":"वोल्टमीटर","kn":"ವೋಲ್ಟ್‌ಮೀಟರ್"},{"en":"Connecting wires and a breadboard","hi":"संयोजक तार और ब्रेडबोर्ड","kn":"ಸಂಪರ್ಕ ತಂತಿಗಳು ಮತ್ತು ಬ್ರೆಡ್‌ಬೋರ್ಡ್"}],"steps":[{"en":"Connect E1 with R1 and E2 with R2 so both feed a common junction; R3 goes from the junction back to the common return.","hi":"E1 को R1 के साथ और E2 को R2 के साथ ऐसे जोड़ें कि दोनों एक उभयनिष्ठ संधि को धारा दें; R3 संधि से उभयनिष्ठ वापसी तार तक।","kn":"E1 ಅನ್ನು R1 ಜೊತೆ, E2 ಅನ್ನು R2 ಜೊತೆ ಎರಡೂ ಸಾಮಾನ್ಯ ಸಂಧಿಗೆ ಪ್ರವಾಹ ನೀಡುವಂತೆ ಜೋಡಿಸಿ; R3 ಸಂಧಿಯಿಂದ ಸಾಮಾನ್ಯ ಹಿಂದಿರುಗುವ ತಂತಿಗೆ."},{"en":"Put a milliammeter in each branch and read I1, I2 and I3.","hi":"हर शाखा में मिलीऐमीटर लगाकर I1, I2 और I3 पढ़ें।","kn":"ಪ್ರತಿ ಶಾಖೆಯಲ್ಲಿ ಮಿಲಿಅಮ್ಮೀಟರ್ ಇಟ್ಟು I1, I2 ಮತ್ತು I3 ಓದಿ."},{"en":"Check I1 + I2 = I3 at the junction.","hi":"संधि पर I1 + I2 = I3 जाँचें।","kn":"ಸಂಧಿಯಲ್ಲಿ I1 + I2 = I3 ಪರಿಶೀಲಿಸಿ."},{"en":"Measure the voltage across each resistor and check E1 = I1R1 + I3R3 round loop 1 (and similarly loop 2).","hi":"हर प्रतिरोधक की वोल्टता मापें और पाश 1 में E1 = I1R1 + I3R3 जाँचें (और इसी तरह पाश 2)।","kn":"ಪ್ರತಿ ರೋಧಕಕ್ಕೆ ಅಡ್ಡ ವೋಲ್ಟೇಜ್ ಅಳೆದು ಕುಣಿಕೆ 1 ರಲ್ಲಿ E1 = I1R1 + I3R3 ಪರಿಶೀಲಿಸಿ (ಹಾಗೆಯೇ ಕುಣಿಕೆ 2)."},{"en":"Repeat with other EMFs and resistors.","hi":"दूसरे EMF और प्रतिरोधकों के साथ दोहराएँ।","kn":"ಬೇರೆ EMF ಮತ್ತು ರೋಧಕಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Connect meters with + to + and choose a range larger than the expected reading.","hi":"मीटर + से + जोड़ें और अपेक्षित पाठ्यांक से बड़ी परास चुनें।","kn":"ಮೀಟರ್‌ಗಳನ್ನು + ರಿಂದ + ಗೆ ಜೋಡಿಸಿ, ನಿರೀಕ್ಷಿತ ಓದಿಗಿಂತ ದೊಡ್ಡ ವ್ಯಾಪ್ತಿ ಆರಿಸಿ."},{"en":"Use sources of low internal resistance, or include it in the loop sum.","hi":"कम आंतरिक प्रतिरोध वाले स्रोत लें, या उसे पाश योग में शामिल करें।","kn":"ಕಡಿಮೆ ಆಂತರಿಕ ರೋಧದ ಮೂಲಗಳನ್ನು ಬಳಸಿ, ಅಥವಾ ಅದನ್ನು ಕುಣಿಕೆ ಮೊತ್ತದಲ್ಲಿ ಸೇರಿಸಿ."},{"en":"Switch off the supply when changing connections.","hi":"संयोजन बदलते समय आपूर्ति बंद कर दें।","kn":"ಸಂಪರ್ಕ ಬದಲಿಸುವಾಗ ಪೂರೈಕೆ ಆಫ್ ಮಾಡಿ."}],"conclusion":{"en":"Within meter accuracy the currents at the junction balance and the voltages round each loop add to zero: Kirchhoff's laws hold.","hi":"मीटर की परिशुद्धता के भीतर संधि पर धाराएँ संतुलित होती हैं और हर पाश में वोल्टताओं का योग शून्य होता है: किरखॉफ़ के नियम सत्य हैं।","kn":"ಮೀಟರ್ ನಿಖರತೆಯೊಳಗೆ ಸಂಧಿಯಲ್ಲಿ ಪ್ರವಾಹಗಳು ಸಮತೋಲಿತ, ಪ್ರತಿ ಕುಣಿಕೆಯಲ್ಲಿ ವೋಲ್ಟೇಜ್‌ಗಳ ಮೊತ್ತ ಶೂನ್ಯ: ಕಿರ್ಚಾಫ್ ನಿಯಮಗಳು ಸತ್ಯ."},"viva":[{"q":{"en":"Which conservation law is behind KCL?","hi":"KCL के पीछे कौन-सा संरक्षण नियम है?","kn":"KCL ಹಿಂದಿರುವ ಸಂರಕ್ಷಣಾ ನಿಯಮ ಯಾವುದು?"},"a":{"en":"Conservation of charge.","hi":"आवेश संरक्षण।","kn":"ಆವೇಶ ಸಂರಕ್ಷಣೆ."}},{"q":{"en":"Which conservation law is behind KVL?","hi":"KVL के पीछे कौन-सा संरक्षण नियम है?","kn":"KVL ಹಿಂದಿರುವ ಸಂರಕ್ಷಣಾ ನಿಯಮ ಯಾವುದು?"},"a":{"en":"Conservation of energy.","hi":"ऊर्जा संरक्षण।","kn":"ಶಕ್ತಿ ಸಂರಕ್ಷಣೆ."}},{"q":{"en":"What does a negative current in your answer mean?","hi":"उत्तर में ऋणात्मक धारा का क्या अर्थ है?","kn":"ಉತ್ತರದಲ್ಲಿ ಋಣ ಪ್ರವಾಹದ ಅರ್ಥವೇನು?"},"a":{"en":"The current flows opposite to the direction assumed.","hi":"धारा मानी गई दिशा के विपरीत बहती है।","kn":"ಪ್ರವಾಹ ಊಹಿಸಿದ ದಿಕ್ಕಿಗೆ ವಿರುದ್ಧವಾಗಿ ಹರಿಯುತ್ತದೆ."}}]},{"id":"meter-bridge","bench":"meter-bridge","setup":{},"subject":"Physics","domain":"physics","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["meter bridge","metre bridge","wheatstone bridge","resistivity","specific resistance","current electricity","null point"],"title":{"en":"Resistivity of a wire with a metre bridge","hi":"मीटर सेतु से तार की प्रतिरोधकता","kn":"ಮೀಟರ್ ಸೇತುವೆಯಿಂದ ತಂತಿಯ ರೋಧಕತೆ"},"summary":{"en":"Find the null point of a metre bridge for several known resistances, then the unknown resistance and the resistivity of its wire.","hi":"कई ज्ञात प्रतिरोधों के लिए मीटर सेतु का शून्य विक्षेप बिंदु ज्ञात करें, फिर अज्ञात प्रतिरोध और उसके तार की प्रतिरोधकता।","kn":"ಹಲವು ತಿಳಿದ ರೋಧಗಳಿಗೆ ಮೀಟರ್ ಸೇತುವೆಯ ಶೂನ್ಯ ಬಿಂದು ಕಂಡುಹಿಡಿದು, ಅಜ್ಞಾತ ರೋಧ ಮತ್ತು ಅದರ ತಂತಿಯ ರೋಧಕತೆ ಪಡೆಯಿರಿ."},"aim":{"en":"To find the resistance of a given wire using a metre bridge and hence the resistivity of its material.","hi":"मीटर सेतु से दिए गए तार का प्रतिरोध और उससे उसके पदार्थ की प्रतिरोधकता ज्ञात करना।","kn":"ಮೀಟರ್ ಸೇತುವೆಯಿಂದ ಕೊಟ್ಟ ತಂತಿಯ ರೋಧ ಮತ್ತು ಆ ಮೂಲಕ ಅದರ ವಸ್ತುವಿನ ರೋಧಕತೆ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"A metre bridge is a Wheatstone bridge whose ratio arms are the two parts of a uniform 1 m wire. At the null point (no galvanometer current) R ÷ X = l ÷ (100 − l), so X = R(100 − l) ÷ l. The resistivity is ρ = Xπr² ÷ L for a wire of length L and radius r.","hi":"मीटर सेतु एक व्हीटस्टोन सेतु है जिसकी अनुपात भुजाएँ 1 m के एकसमान तार के दो भाग हैं। शून्य विक्षेप बिंदु पर (गैल्वेनोमीटर में धारा नहीं) R ÷ X = l ÷ (100 − l), इसलिए X = R(100 − l) ÷ l. लंबाई L और त्रिज्या r के तार की प्रतिरोधकता ρ = Xπr² ÷ L है।","kn":"ಮೀಟರ್ ಸೇತುವೆ ಒಂದು ವೀಟ್‌ಸ್ಟೋನ್ ಸೇತುವೆ; ಅದರ ಅನುಪಾತ ಭುಜಗಳು 1 m ಏಕರೂಪ ತಂತಿಯ ಎರಡು ಭಾಗಗಳು. ಶೂನ್ಯ ಬಿಂದುವಿನಲ್ಲಿ (ಗ್ಯಾಲ್ವನೋಮೀಟರ್‌ನಲ್ಲಿ ಪ್ರವಾಹವಿಲ್ಲ) R ÷ X = l ÷ (100 − l); ಆದ್ದರಿಂದ X = R(100 − l) ÷ l. ಉದ್ದ L ಮತ್ತು ತ್ರಿಜ್ಯ r ಇರುವ ತಂತಿಯ ರೋಧಕತೆ ρ = Xπr² ÷ L."},"apparatus":[{"en":"Metre bridge","hi":"मीटर सेतु","kn":"ಮೀಟರ್ ಸೇತುವೆ"},{"en":"Wire of unknown resistance","hi":"अज्ञात प्रतिरोध का तार","kn":"ಅಜ್ಞಾತ ರೋಧದ ತಂತಿ"},{"en":"Resistance box","hi":"प्रतिरोध बॉक्स","kn":"ರೋಧ ಪೆಟ್ಟಿಗೆ"},{"en":"Galvanometer","hi":"गैल्वेनोमीटर","kn":"ಗ್ಯಾಲ್ವನೋಮೀಟರ್"},{"en":"Jockey","hi":"जॉकी (सर्पी संपर्क)","kn":"ಜಾಕಿ (ಸರಿಯುವ ಸಂಪರ್ಕ)"},{"en":"Leclanché cell and plug key","hi":"लेक्लांशे सेल और प्लग कुंजी","kn":"ಲೆಕ್ಲಾಂಶೆ ಕೋಶ ಮತ್ತು ಪ್ಲಗ್ ಕೀ"},{"en":"Screw gauge and metre scale","hi":"पेंच गेज और मीटर पैमाना","kn":"ಸ್ಕ್ರೂ ಗೇಜ್ ಮತ್ತು ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ"}],"steps":[{"en":"Put the resistance box in the left gap and the wire in the right gap. Connect the cell and key across the ends of the bridge wire.","hi":"प्रतिरोध बॉक्स बाएँ अंतराल में और तार दाएँ अंतराल में लगाएँ। सेल और कुंजी को सेतु तार के सिरों पर जोड़ें।","kn":"ರೋಧ ಪೆಟ್ಟಿಗೆಯನ್ನು ಎಡ ಅಂತರದಲ್ಲಿ, ತಂತಿಯನ್ನು ಬಲ ಅಂತರದಲ್ಲಿ ಇಡಿ. ಕೋಶ ಮತ್ತು ಕೀಯನ್ನು ಸೇತು ತಂತಿಯ ತುದಿಗಳಿಗೆ ಜೋಡಿಸಿ."},{"en":"Connect the galvanometer between the middle strip and the jockey.","hi":"गैल्वेनोमीटर को बीच की पट्टी और जॉकी के बीच जोड़ें।","kn":"ಗ್ಯಾಲ್ವನೋಮೀಟರನ್ನು ಮಧ್ಯದ ಪಟ್ಟಿ ಮತ್ತು ಜಾಕಿಯ ನಡುವೆ ಜೋಡಿಸಿ."},{"en":"Take out a resistance R, put the key in, and touch the jockey along the wire until the galvanometer shows no deflection. Read l.","hi":"एक प्रतिरोध R निकालें, कुंजी लगाएँ, और जॉकी को तार पर छुआते चलें जब तक गैल्वेनोमीटर में विक्षेप न रहे। l पढ़ें।","kn":"ಒಂದು ರೋಧ R ತೆಗೆದು, ಕೀ ಹಾಕಿ, ಗ್ಯಾಲ್ವನೋಮೀಟರ್ ವಿಚಲನೆ ತೋರದವರೆಗೆ ಜಾಕಿಯನ್ನು ತಂತಿಯ ಮೇಲೆ ಮುಟ್ಟಿಸುತ್ತಾ ಹೋಗಿ. l ಓದಿ."},{"en":"Repeat for four or five values of R, keeping the null point between 30 and 70 cm.","hi":"R के चार-पाँच मानों के लिए दोहराएँ, शून्य बिंदु 30 और 70 cm के बीच रखें।","kn":"R ನ ನಾಲ್ಕು-ಐದು ಮೌಲ್ಯಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ; ಶೂನ್ಯ ಬಿಂದು 30 ರಿಂದ 70 cm ನಡುವೆ ಇರಲಿ."},{"en":"Measure the length and diameter of the wire and work out its resistivity.","hi":"तार की लंबाई और व्यास मापें और उसकी प्रतिरोधकता निकालें।","kn":"ತಂತಿಯ ಉದ್ದ ಮತ್ತು ವ್ಯಾಸ ಅಳೆದು ಅದರ ರೋಧಕತೆ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Touch the jockey gently; do not slide it along the wire.","hi":"जॉकी को हल्के से छुआएँ; उसे तार पर घसीटें नहीं।","kn":"ಜಾಕಿಯನ್ನು ಮೃದುವಾಗಿ ಮುಟ್ಟಿಸಿ; ತಂತಿಯ ಮೇಲೆ ಎಳೆಯಬೇಡಿ."},{"en":"Take the key out between readings so the wire does not heat.","hi":"पाठ्यांकों के बीच कुंजी निकाल दें ताकि तार गरम न हो।","kn":"ತಂತಿ ಬಿಸಿಯಾಗದಂತೆ ಓದುಗಳ ನಡುವೆ ಕೀ ತೆಗೆಯಿರಿ."},{"en":"Keep the null point near the middle of the wire to reduce end errors.","hi":"सिरे की त्रुटियाँ घटाने के लिए शून्य बिंदु तार के बीच के पास रखें।","kn":"ಅಂಚಿನ ದೋಷ ಕಡಿಮೆಗೊಳಿಸಲು ಶೂನ್ಯ ಬಿಂದುವನ್ನು ತಂತಿಯ ಮಧ್ಯದ ಹತ್ತಿರ ಇಡಿ."}],"conclusion":{"en":"The unknown resistance comes out the same for every R (within error), and its resistivity agrees with the table value for the material.","hi":"हर R के लिए अज्ञात प्रतिरोध (त्रुटि के भीतर) समान आता है, और उसकी प्रतिरोधकता पदार्थ के सारणी मान से मेल खाती है।","kn":"ಪ್ರತಿ R ಗೂ ಅಜ್ಞಾತ ರೋಧ (ದೋಷದೊಳಗೆ) ಒಂದೇ ಬರುತ್ತದೆ; ಅದರ ರೋಧಕತೆ ವಸ್ತುವಿನ ಕೋಷ್ಟಕ ಮೌಲ್ಯಕ್ಕೆ ಹೊಂದುತ್ತದೆ."},"viva":[{"q":{"en":"Why is the bridge most sensitive when the null point is near the middle?","hi":"शून्य बिंदु बीच के पास होने पर सेतु सबसे सुग्राही क्यों होता है?","kn":"ಶೂನ್ಯ ಬಿಂದು ಮಧ್ಯದ ಹತ್ತಿರ ಇದ್ದಾಗ ಸೇತುವೆ ಅತಿ ಸಂವೇದಿ ಏಕೆ?"},"a":{"en":"All four arms are then of similar resistance, and end resistances matter least.","hi":"तब चारों भुजाओं का प्रतिरोध लगभग समान होता है, और सिरों के प्रतिरोध का प्रभाव सबसे कम होता है।","kn":"ಆಗ ನಾಲ್ಕೂ ಭುಜಗಳ ರೋಧ ಸುಮಾರು ಸಮ; ಅಂಚಿನ ರೋಧಗಳ ಪ್ರಭಾವ ಕನಿಷ್ಠ."}},{"q":{"en":"Why is the bridge wire made of manganin or constantan?","hi":"सेतु तार मैंगनिन या कॉन्सटैंटन का क्यों बनाते हैं?","kn":"ಸೇತು ತಂತಿಯನ್ನು ಮ್ಯಾಂಗನಿನ್ ಅಥವಾ ಕಾನ್‌ಸ್ಟಂಟನ್‌ನಿಂದ ಏಕೆ ಮಾಡುತ್ತಾರೆ?"},"a":{"en":"High resistivity and very small change of resistance with temperature.","hi":"उच्च प्रतिरोधकता और ताप के साथ प्रतिरोध में बहुत कम परिवर्तन।","kn":"ಹೆಚ್ಚು ರೋಧಕತೆ ಮತ್ತು ತಾಪದೊಂದಿಗೆ ರೋಧದಲ್ಲಿ ಅತಿ ಕಡಿಮೆ ಬದಲಾವಣೆ."}},{"q":{"en":"Does resistivity depend on the length of the wire?","hi":"क्या प्रतिरोधकता तार की लंबाई पर निर्भर करती है?","kn":"ರೋಧಕತೆ ತಂತಿಯ ಉದ್ದವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?"},"a":{"en":"No; it depends only on the material and temperature.","hi":"नहीं; यह केवल पदार्थ और ताप पर निर्भर करती है।","kn":"ಇಲ್ಲ; ಅದು ವಸ್ತು ಮತ್ತು ತಾಪವನ್ನು ಮಾತ್ರ ಅವಲಂಬಿಸುತ್ತದೆ."}}]},{"id":"potentiometer-emf","bench":"potentiometer","setup":{"task":"compare"},"subject":"Physics","domain":"physics","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["potentiometer","emf","compare emf","electromotive force","current electricity","null point","potential gradient"],"title":{"en":"Comparing the EMFs of two cells (potentiometer)","hi":"दो सेलों के EMF की तुलना (विभवमापी)","kn":"ಎರಡು ಕೋಶಗಳ EMF ಹೋಲಿಕೆ (ವಿಭವಮಾಪಕ)"},"summary":{"en":"Balance a Leclanché cell and a Daniell cell on a potentiometer wire and compare their EMFs from the balancing lengths.","hi":"लेक्लांशे और डेनियल सेल को विभवमापी तार पर संतुलित करें और संतुलन लंबाइयों से उनके EMF की तुलना करें।","kn":"ಲೆಕ್ಲಾಂಶೆ ಮತ್ತು ಡೇನಿಯಲ್ ಕೋಶಗಳನ್ನು ವಿಭವಮಾಪಕ ತಂತಿಯಲ್ಲಿ ಸಮತೋಲಿಸಿ, ಸಮತೋಲನ ಉದ್ದಗಳಿಂದ ಅವುಗಳ EMF ಹೋಲಿಸಿ."},"aim":{"en":"To compare the EMFs of two primary cells using a potentiometer.","hi":"विभवमापी से दो प्राथमिक सेलों के EMF की तुलना करना।","kn":"ವಿಭವಮಾಪಕದಿಂದ ಎರಡು ಪ್ರಾಥಮಿಕ ಕೋಶಗಳ EMF ಹೋಲಿಸುವುದು."},"principle":{"en":"A steady current in a uniform wire makes the potential fall evenly along it: V = kl. At the balance point no current is drawn from the cell, so its full EMF is measured: E = kl. For two cells E₁ ÷ E₂ = l₁ ÷ l₂.","hi":"एकसमान तार में स्थिर धारा से उसके साथ विभव समान रूप से गिरता है: V = kl. संतुलन बिंदु पर सेल से कोई धारा नहीं ली जाती, इसलिए उसका पूरा EMF मापा जाता है: E = kl. दो सेलों के लिए E₁ ÷ E₂ = l₁ ÷ l₂.","kn":"ಏಕರೂಪ ತಂತಿಯಲ್ಲಿ ಸ್ಥಿರ ಪ್ರವಾಹವಿದ್ದರೆ ಅದರ ಉದ್ದಕ್ಕೂ ವಿಭವ ಸಮವಾಗಿ ಇಳಿಯುತ್ತದೆ: V = kl. ಸಮತೋಲನ ಬಿಂದುವಿನಲ್ಲಿ ಕೋಶದಿಂದ ಪ್ರವಾಹ ತೆಗೆಯುವುದಿಲ್ಲ; ಆದ್ದರಿಂದ ಅದರ ಪೂರ್ಣ EMF ಅಳೆಯಲ್ಪಡುತ್ತದೆ: E = kl. ಎರಡು ಕೋಶಗಳಿಗೆ E₁ ÷ E₂ = l₁ ÷ l₂."},"apparatus":[{"en":"Potentiometer (4 wires of 1 m)","hi":"विभवमापी (1 m के 4 तार)","kn":"ವಿಭವಮಾಪಕ (1 m ನ 4 ತಂತಿಗಳು)"},{"en":"Battery of two accumulators (4 V)","hi":"दो संचायकों की बैटरी (4 V)","kn":"ಎರಡು ಸಂಚಯಕಗಳ ಬ್ಯಾಟರಿ (4 V)"},{"en":"Rheostat","hi":"धारा नियंत्रक (रिओस्टेट)","kn":"ರಿಯೋಸ್ಟಾಟ್"},{"en":"Galvanometer","hi":"गैल्वेनोमीटर","kn":"ಗ್ಯಾಲ್ವನೋಮೀಟರ್"},{"en":"Jockey","hi":"जॉकी (सर्पी संपर्क)","kn":"ಜಾಕಿ (ಸರಿಯುವ ಸಂಪರ್ಕ)"},{"en":"Plug key","hi":"प्लग कुंजी","kn":"ಪ್ಲಗ್ ಕೀ"},{"en":"Leclanché cell and Daniell cell with a two-way key","hi":"द्विमार्गी कुंजी सहित लेक्लांशे और डेनियल सेल","kn":"ಎರಡು-ದಾರಿ ಕೀ ಸಹಿತ ಲೆಕ್ಲಾಂಶೆ ಮತ್ತು ಡೇನಿಯಲ್ ಕೋಶಗಳು"}],"steps":[{"en":"Connect the driver battery, key and rheostat across the ends of the potentiometer wire (+ to end A).","hi":"चालक बैटरी, कुंजी और रिओस्टेट को विभवमापी तार के सिरों पर जोड़ें (+ सिरा A पर)।","kn":"ಚಾಲಕ ಬ್ಯಾಟರಿ, ಕೀ ಮತ್ತು ರಿಯೋಸ್ಟಾಟನ್ನು ವಿಭವಮಾಪಕ ತಂತಿಯ ತುದಿಗಳಿಗೆ ಜೋಡಿಸಿ (+ ತುದಿ A ಗೆ)."},{"en":"Join the + terminals of both cells to A; their − terminals go through the two-way key and galvanometer to the jockey.","hi":"दोनों सेलों के + सिरे A से जोड़ें; उनके − सिरे द्विमार्गी कुंजी और गैल्वेनोमीटर से होते हुए जॉकी तक।","kn":"ಎರಡೂ ಕೋಶಗಳ + ತುದಿಗಳನ್ನು A ಗೆ ಜೋಡಿಸಿ; ಅವುಗಳ − ತುದಿಗಳು ಎರಡು-ದಾರಿ ಕೀ ಮತ್ತು ಗ್ಯಾಲ್ವನೋಮೀಟರ್ ಮೂಲಕ ಜಾಕಿಗೆ."},{"en":"With cell 1 in circuit, find the balancing length l₁.","hi":"सेल 1 को परिपथ में रखकर संतुलन लंबाई l₁ ज्ञात करें।","kn":"ಕೋಶ 1 ಮಂಡಲದಲ್ಲಿದ್ದಾಗ ಸಮತೋಲನ ಉದ್ದ l₁ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Switch to cell 2 without touching the rheostat and find l₂.","hi":"रिओस्टेट को छुए बिना सेल 2 पर बदलें और l₂ ज्ञात करें।","kn":"ರಿಯೋಸ್ಟಾಟ್ ಮುಟ್ಟದೆ ಕೋಶ 2 ಕ್ಕೆ ಬದಲಿಸಿ l₂ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Repeat for two more rheostat settings and find E₁ ÷ E₂ each time.","hi":"रिओस्टेट की दो और स्थितियों के लिए दोहराएँ और हर बार E₁ ÷ E₂ ज्ञात करें।","kn":"ರಿಯೋಸ್ಟಾಟ್‌ನ ಇನ್ನೆರಡು ಸ್ಥಾನಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಪ್ರತಿ ಬಾರಿ E₁ ÷ E₂ ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"The EMF of the driver battery must be greater than that of the cell, and + terminals must be joined to the same end of the wire.","hi":"चालक बैटरी का EMF सेल से अधिक हो, और + सिरे तार के एक ही छोर से जुड़े हों।","kn":"ಚಾಲಕ ಬ್ಯಾಟರಿಯ EMF ಕೋಶಕ್ಕಿಂತ ಹೆಚ್ಚಿರಬೇಕು; + ತುದಿಗಳು ತಂತಿಯ ಒಂದೇ ತುದಿಗೆ ಜೋಡಿಸಿರಬೇಕು."},{"en":"Do not change the rheostat between the readings that are to be compared.","hi":"जिन पाठ्यांकों की तुलना करनी है उनके बीच रिओस्टेट न बदलें।","kn":"ಹೋಲಿಸಬೇಕಾದ ಓದುಗಳ ನಡುವೆ ರಿಯೋಸ್ಟಾಟ್ ಬದಲಿಸಬೇಡಿ."},{"en":"Touch the jockey gently and only for a moment.","hi":"जॉकी को हल्के से और केवल क्षण भर छुआएँ।","kn":"ಜಾಕಿಯನ್ನು ಮೃದುವಾಗಿ, ಕ್ಷಣಮಾತ್ರ ಮುಟ್ಟಿಸಿ."}],"conclusion":{"en":"The ratio l₁ ÷ l₂ stays the same for every rheostat setting and gives E₁ ÷ E₂ ≈ 1.39 for a Leclanché and a Daniell cell.","hi":"अनुपात l₁ ÷ l₂ रिओस्टेट की हर स्थिति में समान रहता है और लेक्लांशे तथा डेनियल सेल के लिए E₁ ÷ E₂ ≈ 1.39 देता है।","kn":"ಅನುಪಾತ l₁ ÷ l₂ ರಿಯೋಸ್ಟಾಟ್‌ನ ಪ್ರತಿ ಸ್ಥಾನದಲ್ಲೂ ಒಂದೇ; ಲೆಕ್ಲಾಂಶೆ ಮತ್ತು ಡೇನಿಯಲ್ ಕೋಶಗಳಿಗೆ E₁ ÷ E₂ ≈ 1.39 ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why is a potentiometer better than a voltmeter for measuring EMF?","hi":"EMF मापने के लिए विभवमापी वोल्टमीटर से अच्छा क्यों है?","kn":"EMF ಅಳೆಯಲು ವಿಭವಮಾಪಕ ವೋಲ್ಟ್‌ಮೀಟರ್‌ಗಿಂತ ಉತ್ತಮ ಏಕೆ?"},"a":{"en":"At balance it draws no current from the cell, so it measures the EMF and not the terminal voltage.","hi":"संतुलन पर यह सेल से कोई धारा नहीं लेता, इसलिए टर्मिनल वोल्टता नहीं, EMF मापता है।","kn":"ಸಮತೋಲನದಲ್ಲಿ ಅದು ಕೋಶದಿಂದ ಪ್ರವಾಹ ತೆಗೆಯುವುದಿಲ್ಲ; ಆದ್ದರಿಂದ ತುದಿ ವೋಲ್ಟೇಜ್ ಅಲ್ಲ, EMF ಅಳೆಯುತ್ತದೆ."}},{"q":{"en":"What is the potential gradient?","hi":"विभव प्रवणता क्या है?","kn":"ವಿಭವ ಪ್ರವಣತೆ ಎಂದರೇನು?"},"a":{"en":"The fall of potential per unit length of the wire, k.","hi":"तार की प्रति इकाई लंबाई में विभव का पतन, k.","kn":"ತಂತಿಯ ಪ್ರತಿ ಏಕಮಾನ ಉದ್ದಕ್ಕೆ ವಿಭವದ ಇಳಿತ, k."}},{"q":{"en":"Why might you find no null point at all?","hi":"हो सकता है कोई शून्य बिंदु न मिले, क्यों?","kn":"ಶೂನ್ಯ ಬಿಂದು ಸಿಗದೇ ಇರಬಹುದು, ಏಕೆ?"},"a":{"en":"The potential across the whole wire is less than the cell’s EMF, or the + terminals are not joined to the same end.","hi":"पूरे तार का विभव सेल के EMF से कम है, या + सिरे एक ही छोर से नहीं जुड़े।","kn":"ಇಡೀ ತಂತಿಯ ವಿಭವ ಕೋಶದ EMF ಗಿಂತ ಕಡಿಮೆ, ಅಥವಾ + ತುದಿಗಳು ಒಂದೇ ತುದಿಗೆ ಜೋಡಿಸಿಲ್ಲ."}}]},{"id":"potentiometer-internal-resistance","bench":"potentiometer","setup":{"task":"internal"},"subject":"Physics","domain":"physics","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["potentiometer","internal resistance","cell","emf","terminal voltage","current electricity"],"title":{"en":"Internal resistance of a cell (potentiometer)","hi":"सेल का आंतरिक प्रतिरोध (विभवमापी)","kn":"ಕೋಶದ ಆಂತರಿಕ ರೋಧ (ವಿಭವಮಾಪಕ)"},"summary":{"en":"Balance a cell on open circuit and then while it drives a known resistance; the two lengths give its internal resistance.","hi":"सेल को खुले परिपथ में और फिर ज्ञात प्रतिरोध को धारा देते हुए संतुलित करें; दोनों लंबाइयों से उसका आंतरिक प्रतिरोध मिलता है।","kn":"ಕೋಶವನ್ನು ತೆರೆದ ಮಂಡಲದಲ್ಲಿ ಮತ್ತು ನಂತರ ತಿಳಿದ ರೋಧಕ್ಕೆ ಪ್ರವಾಹ ನೀಡುವಾಗ ಸಮತೋಲಿಸಿ; ಎರಡು ಉದ್ದಗಳು ಅದರ ಆಂತರಿಕ ರೋಧ ನೀಡುತ್ತವೆ."},"aim":{"en":"To find the internal resistance of a primary cell using a potentiometer.","hi":"विभवमापी से प्राथमिक सेल का आंतरिक प्रतिरोध ज्ञात करना।","kn":"ವಿಭವಮಾಪಕದಿಂದ ಪ್ರಾಥಮಿಕ ಕೋಶದ ಆಂತರಿಕ ರೋಧ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"With K₂ open the balancing length l₁ measures the EMF: E = kl₁. With a resistance R across the cell, it delivers current and the terminal voltage V = kl₂ is less. Since E ÷ V = (R + r) ÷ R, the internal resistance is r = R(l₁ − l₂) ÷ l₂.","hi":"K₂ खुली होने पर संतुलन लंबाई l₁ EMF मापती है: E = kl₁. सेल के सिरों पर प्रतिरोध R लगाने पर वह धारा देता है और टर्मिनल वोल्टता V = kl₂ कम हो जाती है। क्योंकि E ÷ V = (R + r) ÷ R, आंतरिक प्रतिरोध r = R(l₁ − l₂) ÷ l₂ है।","kn":"K₂ ತೆರೆದಿದ್ದಾಗ ಸಮತೋಲನ ಉದ್ದ l₁ EMF ಅಳೆಯುತ್ತದೆ: E = kl₁. ಕೋಶಕ್ಕೆ ಅಡ್ಡ ರೋಧ R ಇದ್ದಾಗ ಅದು ಪ್ರವಾಹ ನೀಡುತ್ತದೆ; ತುದಿ ವೋಲ್ಟೇಜ್ V = kl₂ ಕಡಿಮೆ. E ÷ V = (R + r) ÷ R ಆದ್ದರಿಂದ ಆಂತರಿಕ ರೋಧ r = R(l₁ − l₂) ÷ l₂."},"apparatus":[{"en":"Potentiometer (4 wires of 1 m)","hi":"विभवमापी (1 m के 4 तार)","kn":"ವಿಭವಮಾಪಕ (1 m ನ 4 ತಂತಿಗಳು)"},{"en":"Battery of two accumulators (4 V)","hi":"दो संचायकों की बैटरी (4 V)","kn":"ಎರಡು ಸಂಚಯಕಗಳ ಬ್ಯಾಟರಿ (4 V)"},{"en":"Rheostat","hi":"धारा नियंत्रक (रिओस्टेट)","kn":"ರಿಯೋಸ್ಟಾಟ್"},{"en":"Galvanometer","hi":"गैल्वेनोमीटर","kn":"ಗ್ಯಾಲ್ವನೋಮೀಟರ್"},{"en":"Jockey","hi":"जॉकी (सर्पी संपर्क)","kn":"ಜಾಕಿ (ಸರಿಯುವ ಸಂಪರ್ಕ)"},{"en":"Plug key","hi":"प्लग कुंजी","kn":"ಪ್ಲಗ್ ಕೀ"},{"en":"Leclanché cell","hi":"लेक्लांशे सेल","kn":"ಲೆಕ್ಲಾಂಶೆ ಕೋಶ"},{"en":"Resistance box","hi":"प्रतिरोध बॉक्स","kn":"ರೋಧ ಪೆಟ್ಟಿಗೆ"},{"en":"Second plug key K₂","hi":"दूसरी प्लग कुंजी K₂","kn":"ಎರಡನೇ ಪ್ಲಗ್ ಕೀ K₂"}],"steps":[{"en":"Set up the driver circuit across the wire. Connect the cell (+ to A) through the galvanometer to the jockey, with the resistance box and K₂ across the cell.","hi":"तार पर चालक परिपथ लगाएँ। सेल (+ को A से) गैल्वेनोमीटर से होते हुए जॉकी तक जोड़ें, प्रतिरोध बॉक्स और K₂ सेल के सिरों पर।","kn":"ತಂತಿಗೆ ಅಡ್ಡ ಚಾಲಕ ಮಂಡಲ ಜೋಡಿಸಿ. ಕೋಶವನ್ನು (+ A ಗೆ) ಗ್ಯಾಲ್ವನೋಮೀಟರ್ ಮೂಲಕ ಜಾಕಿಗೆ ಜೋಡಿಸಿ; ರೋಧ ಪೆಟ್ಟಿಗೆ ಮತ್ತು K₂ ಕೋಶಕ್ಕೆ ಅಡ್ಡಲಾಗಿ."},{"en":"With K₂ open, find the balancing length l₁.","hi":"K₂ खुली रखकर संतुलन लंबाई l₁ ज्ञात करें।","kn":"K₂ ತೆರೆದಿಟ್ಟು ಸಮತೋಲನ ಉದ್ದ l₁ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Take out R = 2 Ω from the box, close K₂ and find l₂ at once.","hi":"बॉक्स से R = 2 Ω निकालें, K₂ बंद करें और तुरंत l₂ ज्ञात करें।","kn":"ಪೆಟ್ಟಿಗೆಯಿಂದ R = 2 Ω ತೆಗೆದು, K₂ ಮುಚ್ಚಿ ತಕ್ಷಣ l₂ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Repeat for R = 5 Ω and 10 Ω, checking l₁ again each time.","hi":"R = 5 Ω और 10 Ω के लिए दोहराएँ, हर बार l₁ फिर जाँचें।","kn":"R = 5 Ω ಮತ್ತು 10 Ω ಗೆ ಪುನರಾವರ್ತಿಸಿ, ಪ್ರತಿ ಬಾರಿ l₁ ಮತ್ತೆ ಪರಿಶೀಲಿಸಿ."},{"en":"Work out r = R(l₁ − l₂) ÷ l₂ for each R and take the mean.","hi":"हर R के लिए r = R(l₁ − l₂) ÷ l₂ निकालें और माध्य लें।","kn":"ಪ್ರತಿ R ಗೆ r = R(l₁ − l₂) ÷ l₂ ಲೆಕ್ಕಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ."}],"precautions":[{"en":"The EMF of the driver battery must be greater than that of the cell, and + terminals must be joined to the same end of the wire.","hi":"चालक बैटरी का EMF सेल से अधिक हो, और + सिरे तार के एक ही छोर से जुड़े हों।","kn":"ಚಾಲಕ ಬ್ಯಾಟರಿಯ EMF ಕೋಶಕ್ಕಿಂತ ಹೆಚ್ಚಿರಬೇಕು; + ತುದಿಗಳು ತಂತಿಯ ಒಂದೇ ತುದಿಗೆ ಜೋಡಿಸಿರಬೇಕು."},{"en":"Do not change the rheostat between the readings that are to be compared.","hi":"जिन पाठ्यांकों की तुलना करनी है उनके बीच रिओस्टेट न बदलें।","kn":"ಹೋಲಿಸಬೇಕಾದ ಓದುಗಳ ನಡುವೆ ರಿಯೋಸ್ಟಾಟ್ ಬದಲಿಸಬೇಡಿ."},{"en":"Touch the jockey gently and only for a moment.","hi":"जॉकी को हल्के से और केवल क्षण भर छुआएँ।","kn":"ಜಾಕಿಯನ್ನು ಮೃದುವಾಗಿ, ಕ್ಷಣಮಾತ್ರ ಮುಟ್ಟಿಸಿ."},{"en":"Close K₂ only while finding l₂: the cell runs down while it supplies current.","hi":"K₂ केवल l₂ ज्ञात करते समय बंद करें: धारा देते समय सेल क्षीण होता है।","kn":"l₂ ಕಂಡುಹಿಡಿಯುವಾಗ ಮಾತ್ರ K₂ ಮುಚ್ಚಿ: ಪ್ರವಾಹ ನೀಡುವಾಗ ಕೋಶ ಕ್ಷೀಣಿಸುತ್ತದೆ."}],"conclusion":{"en":"The balancing length is shorter when the cell supplies current; r = R(l₁ − l₂) ÷ l₂ comes out about the same for each R, about 1 Ω for a Leclanché cell.","hi":"सेल के धारा देने पर संतुलन लंबाई छोटी होती है; r = R(l₁ − l₂) ÷ l₂ हर R के लिए लगभग समान, लेक्लांशे सेल के लिए लगभग 1 Ω आता है।","kn":"ಕೋಶ ಪ್ರವಾಹ ನೀಡುವಾಗ ಸಮತೋಲನ ಉದ್ದ ಕಡಿಮೆ; r = R(l₁ − l₂) ÷ l₂ ಪ್ರತಿ R ಗೂ ಸುಮಾರು ಒಂದೇ, ಲೆಕ್ಲಾಂಶೆ ಕೋಶಕ್ಕೆ ಸುಮಾರು 1 Ω."},"viva":[{"q":{"en":"Why is l₂ less than l₁?","hi":"l₂, l₁ से कम क्यों है?","kn":"l₂, l₁ ಗಿಂತ ಕಡಿಮೆ ಏಕೆ?"},"a":{"en":"Some EMF is lost as Ir inside the cell, so the terminal voltage is less than the EMF.","hi":"सेल के भीतर कुछ EMF, Ir के रूप में खो जाता है, इसलिए टर्मिनल वोल्टता EMF से कम है।","kn":"ಕೋಶದೊಳಗೆ ಸ್ವಲ್ಪ EMF, Ir ಆಗಿ ನಷ್ಟವಾಗುತ್ತದೆ; ಆದ್ದರಿಂದ ತುದಿ ವೋಲ್ಟೇಜ್ EMF ಗಿಂತ ಕಡಿಮೆ."}},{"q":{"en":"On what does the internal resistance of a cell depend?","hi":"सेल का आंतरिक प्रतिरोध किन पर निर्भर करता है?","kn":"ಕೋಶದ ಆಂತರಿಕ ರೋಧ ಯಾವುದನ್ನು ಅವಲಂಬಿಸುತ್ತದೆ?"},"a":{"en":"The electrolyte and its concentration, the distance between and area of the electrodes, and temperature.","hi":"विद्युत-अपघट्य और उसकी सांद्रता, इलेक्ट्रोडों के बीच की दूरी तथा क्षेत्रफल, और ताप।","kn":"ವಿದ್ಯುದ್ವಿಭಾಜ್ಯ ಮತ್ತು ಅದರ ಸಾಂದ್ರತೆ, ವಿದ್ಯುದ್ವಾರಗಳ ನಡುವಿನ ದೂರ ಮತ್ತು ವಿಸ್ತೀರ್ಣ, ಹಾಗೂ ತಾಪ."}},{"q":{"en":"Why should a car battery have a very small internal resistance?","hi":"कार की बैटरी का आंतरिक प्रतिरोध बहुत कम क्यों होना चाहिए?","kn":"ಕಾರಿನ ಬ್ಯಾಟರಿಯ ಆಂತರಿಕ ರೋಧ ಅತಿ ಕಡಿಮೆ ಏಕೆ ಇರಬೇಕು?"},"a":{"en":"To give the very large current the starter motor needs without a big voltage drop.","hi":"बड़ी वोल्टता गिरावट के बिना स्टार्टर मोटर को चाहिए बहुत बड़ी धारा देने के लिए।","kn":"ದೊಡ್ಡ ವೋಲ್ಟೇಜ್ ಇಳಿತವಿಲ್ಲದೆ ಸ್ಟಾರ್ಟರ್ ಮೋಟಾರ್‌ಗೆ ಬೇಕಾದ ಅತಿ ದೊಡ್ಡ ಪ್ರವಾಹ ನೀಡಲು."}}]},{"id":"convex-lens-uv","bench":"optical-bench","setup":{"task":"lens-uv"},"subject":"Physics","domain":"physics","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["ray optics","convex lens","focal length","u-v method","lens formula","optical instruments"],"title":{"en":"Focal length of a convex lens (u–v method)","hi":"उत्तल लेंस की फ़ोकस दूरी (u–v विधि)","kn":"ಪೀನ ಮಸೂರದ ನಾಭಿದೂರ (u–v ವಿಧಾನ)"},"summary":{"en":"Find v for several u by removing parallax, then f from uv/(u + v) and from the 1/v–1/u graph.","hi":"कई u के लिए लंबन हटाकर v ज्ञात करें, फिर uv/(u + v) से और 1/v–1/u ग्राफ़ से f निकालें।","kn":"ಹಲವು u ಗೆ ಭ್ರಂಶ ತೆಗೆದು v ಕಂಡುಹಿಡಿಯಿರಿ, ನಂತರ uv/(u + v) ಮತ್ತು 1/v–1/u ನಕ್ಷೆಯಿಂದ f ಪಡೆಯಿರಿ."},"aim":{"en":"To find the focal length of a convex lens by plotting graphs between u and v and between 1/u and 1/v.","hi":"u और v के बीच तथा 1/u और 1/v के बीच ग्राफ़ बनाकर उत्तल लेंस की फ़ोकस दूरी ज्ञात करना।","kn":"u ಮತ್ತು v ನಡುವೆ ಹಾಗೂ 1/u ಮತ್ತು 1/v ನಡುವೆ ನಕ್ಷೆ ಎಳೆದು ಪೀನ ಮಸೂರದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"For a convex lens 1/v + 1/u = 1/f, taking the distances of the real object and real image as positive. So f = uv/(u + v), and the graph of 1/v against 1/u is a straight line cutting both axes at 1/f.","hi":"उत्तल लेंस के लिए, वास्तविक वस्तु और वास्तविक प्रतिबिंब की दूरियाँ धनात्मक लेने पर, 1/v + 1/u = 1/f. अतः f = uv/(u + v), और 1/v तथा 1/u का ग्राफ़ एक सीधी रेखा है जो दोनों अक्षों को 1/f पर काटती है।","kn":"ನೈಜ ವಸ್ತು ಮತ್ತು ನೈಜ ಪ್ರತಿಬಿಂಬದ ದೂರಗಳನ್ನು ಧನಾತ್ಮಕವಾಗಿ ತೆಗೆದುಕೊಂಡರೆ ಪೀನ ಮಸೂರಕ್ಕೆ 1/v + 1/u = 1/f. ಆದ್ದರಿಂದ f = uv/(u + v); 1/v ಮತ್ತು 1/u ನಕ್ಷೆ ಎರಡೂ ಅಕ್ಷಗಳನ್ನು 1/f ನಲ್ಲಿ ಛೇದಿಸುವ ಸರಳರೇಖೆ."},"apparatus":[{"en":"Optical bench with uprights","hi":"उपस्तंभों सहित प्रकाशिक बेंच","kn":"ಆಧಾರ ಕಂಬಗಳ ಸಹಿತ ದೃಕ್ ಪೀಠ"},{"en":"Convex lens with holder","hi":"धारक सहित उत्तल लेंस","kn":"ಹಿಡಿಕೆ ಸಹಿತ ಪೀನ ಮಸೂರ"},{"en":"Two optical needles (object and image)","hi":"दो प्रकाशिक सुइयाँ (वस्तु और प्रतिबिंब)","kn":"ಎರಡು ದೃಕ್ ಸೂಜಿಗಳು (ವಸ್ತು ಮತ್ತು ಪ್ರತಿಬಿಂಬ)"},{"en":"Index needle","hi":"सूचक सुई","kn":"ಸೂಚ್ಯಂಕ ಸೂಜಿ"}],"steps":[{"en":"Find the rough focal length by focusing a distant object on a wall.","hi":"दूर की वस्तु को दीवार पर फ़ोकस करके मोटी फ़ोकस दूरी ज्ञात करें।","kn":"ದೂರದ ವಸ್ತುವನ್ನು ಗೋಡೆಯ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ ಸುಮಾರು ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Fix the lens. Put the object needle at a distance u between f and 2f, or beyond 2f.","hi":"लेंस स्थिर करें। वस्तु सुई को f और 2f के बीच, या 2f से परे, दूरी u पर रखें।","kn":"ಮಸೂರ ಸ್ಥಿರಗೊಳಿಸಿ. ವಸ್ತು ಸೂಜಿಯನ್ನು f ಮತ್ತು 2f ನಡುವೆ ಅಥವಾ 2f ಆಚೆ u ದೂರದಲ್ಲಿಡಿ."},{"en":"Look through the lens from the other side and move the image needle until its tip and the inverted image have no parallax. Record v.","hi":"दूसरी ओर से लेंस में देखें और प्रतिबिंब सुई को तब तक खिसकाएँ जब तक उसकी नोक और उल्टे प्रतिबिंब में लंबन न रहे। v लिखें।","kn":"ಇನ್ನೊಂದು ಕಡೆಯಿಂದ ಮಸೂರದಲ್ಲಿ ನೋಡಿ, ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯ ತುದಿ ಮತ್ತು ತಲೆಕೆಳಗಾದ ಪ್ರತಿಬಿಂಬದ ನಡುವೆ ಭ್ರಂಶ ಇಲ್ಲದವರೆಗೆ ಅದನ್ನು ಸರಿಸಿ. v ದಾಖಲಿಸಿ."},{"en":"Repeat for five or six values of u.","hi":"u के पाँच-छह मानों के लिए दोहराएँ।","kn":"u ನ ಐದು-ಆರು ಮೌಲ್ಯಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Work out f for each pair, and plot 1/v against 1/u.","hi":"हर युग्म के लिए f निकालें, और 1/v तथा 1/u का ग्राफ़ बनाएँ।","kn":"ಪ್ರತಿ ಜೋಡಿಗೆ f ಲೆಕ್ಕಿಸಿ, 1/v ಮತ್ತು 1/u ನಕ್ಷೆ ಎಳೆಯಿರಿ."}],"precautions":[{"en":"Keep the tips of the needles and the centre of the lens or mirror at the same height.","hi":"सुइयों की नोकें और लेंस या दर्पण का केंद्र एक ही ऊँचाई पर रखें।","kn":"ಸೂಜಿಗಳ ತುದಿಗಳು ಮತ್ತು ಮಸೂರ ಅಥವಾ ದರ್ಪಣದ ಕೇಂದ್ರ ಒಂದೇ ಎತ್ತರದಲ್ಲಿರಲಿ."},{"en":"Remove parallax tip to tip, keeping the eye at least 25 cm from the needle.","hi":"आँख को सुई से कम से कम 25 cm दूर रखकर नोक से नोक का लंबन हटाएँ।","kn":"ಕಣ್ಣನ್ನು ಸೂಜಿಯಿಂದ ಕನಿಷ್ಠ 25 cm ದೂರವಿಟ್ಟು ತುದಿಯಿಂದ ತುದಿಗೆ ಭ್ರಂಶ ತೆಗೆಯಿರಿ."},{"en":"Apply the index correction between the bench scale and the actual distance.","hi":"बेंच पैमाने और वास्तविक दूरी के बीच सूचकांक संशोधन लगाएँ।","kn":"ಪೀಠದ ಅಳತೆ ಮತ್ತು ನಿಜ ದೂರದ ನಡುವಿನ ಸೂಚ್ಯಂಕ ತಿದ್ದುಪಡಿ ಅನ್ವಯಿಸಿ."}],"conclusion":{"en":"The values of uv/(u + v) agree, and the 1/v–1/u graph is a straight line with equal intercepts 1/f on both axes, giving the focal length of the lens.","hi":"uv/(u + v) के मान मेल खाते हैं, और 1/v–1/u ग्राफ़ दोनों अक्षों पर समान अंतःखंड 1/f वाली सीधी रेखा है, जिससे लेंस की फ़ोकस दूरी मिलती है।","kn":"uv/(u + v) ಮೌಲ್ಯಗಳು ಹೊಂದುತ್ತವೆ; 1/v–1/u ನಕ್ಷೆ ಎರಡೂ ಅಕ್ಷಗಳಲ್ಲಿ ಸಮ ಅಂತಃಖಂಡ 1/f ಇರುವ ಸರಳರೇಖೆ; ಅದರಿಂದ ಮಸೂರದ ನಾಭಿದೂರ ಸಿಗುತ್ತದೆ."},"viva":[{"q":{"en":"What is parallax?","hi":"लंबन क्या है?","kn":"ಭ್ರಂಶ ಎಂದರೇನು?"},"a":{"en":"The apparent shift of one object against another when the eye moves sideways.","hi":"आँख को बगल में हिलाने पर एक वस्तु का दूसरी के सापेक्ष आभासी खिसकाव।","kn":"ಕಣ್ಣನ್ನು ಪಕ್ಕಕ್ಕೆ ಸರಿಸಿದಾಗ ಒಂದು ವಸ್ತು ಇನ್ನೊಂದರ ಸಾಪೇಕ್ಷವಾಗಿ ಸರಿದಂತೆ ಕಾಣುವುದು."}},{"q":{"en":"Where is the object when u = v?","hi":"u = v होने पर वस्तु कहाँ है?","kn":"u = v ಆದಾಗ ವಸ್ತು ಎಲ್ಲಿದೆ?"},"a":{"en":"At 2F: both are 2f.","hi":"2F पर: दोनों 2f हैं।","kn":"2F ನಲ್ಲಿ: ಎರಡೂ 2f."}},{"q":{"en":"What is the power of a lens of focal length 20 cm?","hi":"20 cm फ़ोकस दूरी वाले लेंस की क्षमता कितनी है?","kn":"20 cm ನಾಭಿದೂರದ ಮಸೂರದ ಸಾಮರ್ಥ್ಯ ಎಷ್ಟು?"},"a":{"en":"+5 dioptre.","hi":"+5 डायोप्टर।","kn":"+5 ಡಯಾಪ್ಟರ್."}}]},{"id":"concave-mirror-uv","bench":"optical-bench","setup":{"task":"mirror-uv"},"subject":"Physics","domain":"physics","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["ray optics","concave mirror","focal length","u-v method","mirror formula","reflection"],"title":{"en":"Focal length of a concave mirror (u–v method)","hi":"अवतल दर्पण की फ़ोकस दूरी (u–v विधि)","kn":"ನಿಮ್ನ ದರ್ಪಣದ ನಾಭಿದೂರ (u–v ವಿಧಾನ)"},"summary":{"en":"Locate the real image of a needle in a concave mirror for several u and find f.","hi":"कई u के लिए अवतल दर्पण में सुई का वास्तविक प्रतिबिंब ढूँढें और f ज्ञात करें।","kn":"ಹಲವು u ಗೆ ನಿಮ್ನ ದರ್ಪಣದಲ್ಲಿ ಸೂಜಿಯ ನೈಜ ಪ್ರತಿಬಿಂಬ ಹುಡುಕಿ f ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To find the focal length of a concave mirror by plotting graphs between u and v and between 1/u and 1/v.","hi":"u और v के बीच तथा 1/u और 1/v के बीच ग्राफ़ बनाकर अवतल दर्पण की फ़ोकस दूरी ज्ञात करना।","kn":"u ಮತ್ತು v ನಡುವೆ ಹಾಗೂ 1/u ಮತ್ತು 1/v ನಡುವೆ ನಕ್ಷೆ ಎಳೆದು ನಿಮ್ನ ದರ್ಪಣದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"For a concave mirror forming a real image, 1/u + 1/v = 1/f with u and v measured in front of the mirror. When the object is at C (u = 2f) the image coincides with it.","hi":"वास्तविक प्रतिबिंब बनाते अवतल दर्पण के लिए, दर्पण के सामने मापे गए u और v से 1/u + 1/v = 1/f. वस्तु C पर (u = 2f) हो तो प्रतिबिंब उसी पर बनता है।","kn":"ನೈಜ ಪ್ರತಿಬಿಂಬ ರೂಪಿಸುವ ನಿಮ್ನ ದರ್ಪಣಕ್ಕೆ, ದರ್ಪಣದ ಮುಂದೆ ಅಳೆದ u ಮತ್ತು v ಯಿಂದ 1/u + 1/v = 1/f. ವಸ್ತು C ನಲ್ಲಿದ್ದರೆ (u = 2f) ಪ್ರತಿಬಿಂಬ ಅದರ ಮೇಲೆಯೇ ಮೂಡುತ್ತದೆ."},"apparatus":[{"en":"Optical bench with uprights","hi":"उपस्तंभों सहित प्रकाशिक बेंच","kn":"ಆಧಾರ ಕಂಬಗಳ ಸಹಿತ ದೃಕ್ ಪೀಠ"},{"en":"Concave mirror with holder","hi":"धारक सहित अवतल दर्पण","kn":"ಹಿಡಿಕೆ ಸಹಿತ ನಿಮ್ನ ದರ್ಪಣ"},{"en":"Two optical needles (object and image)","hi":"दो प्रकाशिक सुइयाँ (वस्तु और प्रतिबिंब)","kn":"ಎರಡು ದೃಕ್ ಸೂಜಿಗಳು (ವಸ್ತು ಮತ್ತು ಪ್ರತಿಬಿಂಬ)"},{"en":"Index needle","hi":"सूचक सुई","kn":"ಸೂಚ್ಯಂಕ ಸೂಜಿ"}],"steps":[{"en":"Find the rough focal length by focusing a distant object.","hi":"दूर की वस्तु फ़ोकस करके मोटी फ़ोकस दूरी ज्ञात करें।","kn":"ದೂರದ ವಸ್ತುವನ್ನು ಕೇಂದ್ರೀಕರಿಸಿ ಸುಮಾರು ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Place the object needle beyond F in front of the mirror.","hi":"वस्तु सुई को दर्पण के सामने F से परे रखें।","kn":"ವಸ್ತು ಸೂಜಿಯನ್ನು ದರ್ಪಣದ ಮುಂದೆ F ಆಚೆ ಇಡಿ."},{"en":"Move the image needle until it has no parallax with the inverted image. Record u and v.","hi":"प्रतिबिंब सुई को तब तक खिसकाएँ जब तक उल्टे प्रतिबिंब से लंबन न रहे। u और v लिखें।","kn":"ತಲೆಕೆಳಗಾದ ಪ್ರತಿಬಿಂಬದೊಂದಿಗೆ ಭ್ರಂಶ ಇಲ್ಲದವರೆಗೆ ಪ್ರತಿಬಿಂಬ ಸೂಜಿ ಸರಿಸಿ. u ಮತ್ತು v ದಾಖಲಿಸಿ."},{"en":"Repeat for five or six positions of the object.","hi":"वस्तु की पाँच-छह स्थितियों के लिए दोहराएँ।","kn":"ವಸ್ತುವಿನ ಐದು-ಆರು ಸ್ಥಾನಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Find f from each pair and from the 1/v–1/u graph.","hi":"हर युग्म से और 1/v–1/u ग्राफ़ से f ज्ञात करें।","kn":"ಪ್ರತಿ ಜೋಡಿಯಿಂದ ಮತ್ತು 1/v–1/u ನಕ್ಷೆಯಿಂದ f ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Keep the tips of the needles and the centre of the lens or mirror at the same height.","hi":"सुइयों की नोकें और लेंस या दर्पण का केंद्र एक ही ऊँचाई पर रखें।","kn":"ಸೂಜಿಗಳ ತುದಿಗಳು ಮತ್ತು ಮಸೂರ ಅಥವಾ ದರ್ಪಣದ ಕೇಂದ್ರ ಒಂದೇ ಎತ್ತರದಲ್ಲಿರಲಿ."},{"en":"Remove parallax tip to tip, keeping the eye at least 25 cm from the needle.","hi":"आँख को सुई से कम से कम 25 cm दूर रखकर नोक से नोक का लंबन हटाएँ।","kn":"ಕಣ್ಣನ್ನು ಸೂಜಿಯಿಂದ ಕನಿಷ್ಠ 25 cm ದೂರವಿಟ್ಟು ತುದಿಯಿಂದ ತುದಿಗೆ ಭ್ರಂಶ ತೆಗೆಯಿರಿ."},{"en":"Keep the mirror clean and fixed at the end of the bench.","hi":"दर्पण साफ़ रखें और बेंच के सिरे पर स्थिर रखें।","kn":"ದರ್ಪಣವನ್ನು ಸ್ವಚ್ಛವಾಗಿ, ಪೀಠದ ತುದಿಯಲ್ಲಿ ಸ್ಥಿರವಾಗಿಡಿ."}],"conclusion":{"en":"uv/(u + v) is the same for every position and the 1/v–1/u graph gives the same f: the mirror formula holds.","hi":"हर स्थिति के लिए uv/(u + v) समान है और 1/v–1/u ग्राफ़ वही f देता है: दर्पण सूत्र सत्य है।","kn":"ಪ್ರತಿ ಸ್ಥಾನಕ್ಕೂ uv/(u + v) ಒಂದೇ; 1/v–1/u ನಕ್ಷೆ ಅದೇ f ನೀಡುತ್ತದೆ: ದರ್ಪಣ ಸೂತ್ರ ಸತ್ಯ."},"viva":[{"q":{"en":"How are f and R related for a spherical mirror?","hi":"गोलीय दर्पण के लिए f और R में क्या संबंध है?","kn":"ಗೋಳೀಯ ದರ್ಪಣಕ್ಕೆ f ಮತ್ತು R ನಡುವಿನ ಸಂಬಂಧ ಏನು?"},"a":{"en":"f = R/2.","hi":"f = R/2.","kn":"f = R/2."}},{"q":{"en":"Can a concave mirror form a virtual image?","hi":"क्या अवतल दर्पण आभासी प्रतिबिंब बना सकता है?","kn":"ನಿಮ್ನ ದರ್ಪಣ ಮಿಥ್ಯ ಪ್ರತಿಬಿಂಬ ರೂಪಿಸಬಲ್ಲದೇ?"},"a":{"en":"Yes, when the object is between F and the pole.","hi":"हाँ, जब वस्तु F और ध्रुव के बीच हो।","kn":"ಹೌದು, ವಸ್ತು F ಮತ್ತು ಧ್ರುವದ ನಡುವೆ ಇದ್ದಾಗ."}},{"q":{"en":"Why do dentists use concave mirrors?","hi":"दंत चिकित्सक अवतल दर्पण क्यों प्रयोग करते हैं?","kn":"ದಂತವೈದ್ಯರು ನಿಮ್ನ ದರ್ಪಣ ಏಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"Held close to the tooth, it gives an erect, magnified image.","hi":"दाँत के पास रखने पर यह सीधा, बड़ा प्रतिबिंब देता है।","kn":"ಹಲ್ಲಿನ ಹತ್ತಿರ ಹಿಡಿದಾಗ ಅದು ನೇರ, ದೊಡ್ಡ ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತದೆ."}}]},{"id":"concave-lens-focal","bench":"optical-bench","setup":{"task":"concave-lens","item":"A","u":50.0},"subject":"Physics","domain":"physics","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["ray optics","concave lens","focal length","combination of lenses","lenses in contact"],"title":{"en":"Focal length of a concave lens (with a convex lens)","hi":"अवतल लेंस की फ़ोकस दूरी (उत्तल लेंस की सहायता से)","kn":"ನಿಮ್ನ ಮಸೂರದ ನಾಭಿದೂರ (ಪೀನ ಮಸೂರದ ಸಹಾಯದಿಂದ)"},"summary":{"en":"A concave lens alone gives no real image; put it in contact with a stronger convex lens and use the combination.","hi":"अकेला अवतल लेंस वास्तविक प्रतिबिंब नहीं देता; उसे अधिक प्रबल उत्तल लेंस के संपर्क में रखकर संयोजन का प्रयोग करें।","kn":"ನಿಮ್ನ ಮಸೂರ ಒಂದೇ ನೈಜ ಪ್ರತಿಬಿಂಬ ನೀಡುವುದಿಲ್ಲ; ಹೆಚ್ಚು ಪ್ರಬಲ ಪೀನ ಮಸೂರದ ಸಂಪರ್ಕದಲ್ಲಿಟ್ಟು ಸಂಯೋಜನೆಯನ್ನು ಬಳಸಿ."},"aim":{"en":"To find the focal length of a concave lens using a convex lens in contact with it.","hi":"संपर्क में रखे उत्तल लेंस की सहायता से अवतल लेंस की फ़ोकस दूरी ज्ञात करना।","kn":"ಸಂಪರ್ಕದಲ್ಲಿರುವ ಪೀನ ಮಸೂರದ ಸಹಾಯದಿಂದ ನಿಮ್ನ ಮಸೂರದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Lenses in contact add their powers: 1/F = 1/f₁ + 1/f₂. If the convex lens (f₁ = 10 cm here) is stronger, the pair is converging and its F can be found by the u–v method; then 1/f₂ = 1/F − 1/f₁, which comes out negative for the concave lens.","hi":"संपर्क में रखे लेंसों की क्षमताएँ जुड़ती हैं: 1/F = 1/f₁ + 1/f₂. यदि उत्तल लेंस (यहाँ f₁ = 10 cm) अधिक प्रबल हो तो युग्म अभिसारी होता है और u–v विधि से उसकी F ज्ञात की जा सकती है; तब 1/f₂ = 1/F − 1/f₁, जो अवतल लेंस के लिए ऋणात्मक आती है।","kn":"ಸಂಪರ್ಕದಲ್ಲಿರುವ ಮಸೂರಗಳ ಸಾಮರ್ಥ್ಯಗಳು ಕೂಡುತ್ತವೆ: 1/F = 1/f₁ + 1/f₂. ಪೀನ ಮಸೂರ (ಇಲ್ಲಿ f₁ = 10 cm) ಹೆಚ್ಚು ಪ್ರಬಲವಾಗಿದ್ದರೆ ಜೋಡಿ ಅಭಿಸರಣ; u–v ವಿಧಾನದಿಂದ ಅದರ F ಕಂಡುಹಿಡಿಯಬಹುದು; ನಂತರ 1/f₂ = 1/F − 1/f₁, ನಿಮ್ನ ಮಸೂರಕ್ಕೆ ಇದು ಋಣ."},"apparatus":[{"en":"Optical bench with uprights","hi":"उपस्तंभों सहित प्रकाशिक बेंच","kn":"ಆಧಾರ ಕಂಬಗಳ ಸಹಿತ ದೃಕ್ ಪೀಠ"},{"en":"Convex lens of known focal length (10 cm)","hi":"ज्ञात फ़ोकस दूरी (10 cm) का उत्तल लेंस","kn":"ತಿಳಿದ ನಾಭಿದೂರದ (10 cm) ಪೀನ ಮಸೂರ"},{"en":"Concave lens","hi":"अवतल लेंस","kn":"ನಿಮ್ನ ಮಸೂರ"},{"en":"Two optical needles (object and image)","hi":"दो प्रकाशिक सुइयाँ (वस्तु और प्रतिबिंब)","kn":"ಎರಡು ದೃಕ್ ಸೂಜಿಗಳು (ವಸ್ತು ಮತ್ತು ಪ್ರತಿಬಿಂಬ)"}],"steps":[{"en":"Put the concave lens in close contact with the convex lens in one holder.","hi":"अवतल लेंस को एक ही धारक में उत्तल लेंस के निकट संपर्क में रखें।","kn":"ನಿಮ್ನ ಮಸೂರವನ್ನು ಒಂದೇ ಹಿಡಿಕೆಯಲ್ಲಿ ಪೀನ ಮಸೂರದೊಂದಿಗೆ ನಿಕಟ ಸಂಪರ್ಕದಲ್ಲಿಡಿ."},{"en":"Place the object needle at a distance u from the combination.","hi":"वस्तु सुई को संयोजन से दूरी u पर रखें।","kn":"ವಸ್ತು ಸೂಜಿಯನ್ನು ಸಂಯೋಜನೆಯಿಂದ u ದೂರದಲ್ಲಿಡಿ."},{"en":"Find the real image with the image needle by removing parallax; record v.","hi":"लंबन हटाकर प्रतिबिंब सुई से वास्तविक प्रतिबिंब ढूँढें; v लिखें।","kn":"ಭ್ರಂಶ ತೆಗೆದು ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯಿಂದ ನೈಜ ಪ್ರತಿಬಿಂಬ ಹುಡುಕಿ; v ದಾಖಲಿಸಿ."},{"en":"Repeat for several u and find F = uv/(u + v).","hi":"कई u के लिए दोहराएँ और F = uv/(u + v) ज्ञात करें।","kn":"ಹಲವು u ಗೆ ಪುನರಾವರ್ತಿಸಿ F = uv/(u + v) ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Work out f₂ = F f₁ ÷ (f₁ − F).","hi":"f₂ = F f₁ ÷ (f₁ − F) निकालें।","kn":"f₂ = F f₁ ÷ (f₁ − F) ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Keep the tips of the needles and the centre of the lens or mirror at the same height.","hi":"सुइयों की नोकें और लेंस या दर्पण का केंद्र एक ही ऊँचाई पर रखें।","kn":"ಸೂಜಿಗಳ ತುದಿಗಳು ಮತ್ತು ಮಸೂರ ಅಥವಾ ದರ್ಪಣದ ಕೇಂದ್ರ ಒಂದೇ ಎತ್ತರದಲ್ಲಿರಲಿ."},{"en":"Remove parallax tip to tip, keeping the eye at least 25 cm from the needle.","hi":"आँख को सुई से कम से कम 25 cm दूर रखकर नोक से नोक का लंबन हटाएँ।","kn":"ಕಣ್ಣನ್ನು ಸೂಜಿಯಿಂದ ಕನಿಷ್ಠ 25 cm ದೂರವಿಟ್ಟು ತುದಿಯಿಂದ ತುದಿಗೆ ಭ್ರಂಶ ತೆಗೆಯಿರಿ."},{"en":"The convex lens must be stronger (shorter focal length) than the concave lens.","hi":"उत्तल लेंस अवतल लेंस से अधिक प्रबल (कम फ़ोकस दूरी वाला) होना चाहिए।","kn":"ಪೀನ ಮಸೂರ ನಿಮ್ನ ಮಸೂರಕ್ಕಿಂತ ಹೆಚ್ಚು ಪ್ರಬಲ (ಕಡಿಮೆ ನಾಭಿದೂರ) ಆಗಿರಬೇಕು."}],"conclusion":{"en":"The combination behaves as one converging lens of focal length F; from it the concave lens has a negative focal length f₂ = F f₁ ÷ (f₁ − F).","hi":"संयोजन फ़ोकस दूरी F वाले एक अभिसारी लेंस की तरह व्यवहार करता है; उससे अवतल लेंस की फ़ोकस दूरी ऋणात्मक f₂ = F f₁ ÷ (f₁ − F) मिलती है।","kn":"ಸಂಯೋಜನೆ F ನಾಭಿದೂರದ ಒಂದು ಅಭಿಸರಣ ಮಸೂರದಂತೆ ವರ್ತಿಸುತ್ತದೆ; ಅದರಿಂದ ನಿಮ್ನ ಮಸೂರದ ನಾಭಿದೂರ ಋಣ f₂ = F f₁ ÷ (f₁ − F)."},"viva":[{"q":{"en":"Why can’t we find a concave lens’s focal length directly by the u–v method?","hi":"u–v विधि से सीधे अवतल लेंस की फ़ोकस दूरी क्यों नहीं निकलती?","kn":"u–v ವಿಧಾನದಿಂದ ನೇರವಾಗಿ ನಿಮ್ನ ಮಸೂರದ ನಾಭಿದೂರ ಏಕೆ ಸಿಗುವುದಿಲ್ಲ?"},"a":{"en":"It always forms a virtual image of a real object, which cannot be caught with a needle on the far side.","hi":"यह वास्तविक वस्तु का सदा आभासी प्रतिबिंब बनाता है, जिसे दूसरी ओर सुई से पकड़ा नहीं जा सकता।","kn":"ನೈಜ ವಸ್ತುವಿಗೆ ಅದು ಯಾವಾಗಲೂ ಮಿಥ್ಯ ಪ್ರತಿಬಿಂಬ ನೀಡುತ್ತದೆ; ಅದನ್ನು ಆಚೆ ಸೂಜಿಯಿಂದ ಹಿಡಿಯಲಾಗದು."}},{"q":{"en":"What is the power of the combination of +10 D and −4 D lenses?","hi":"+10 D और −4 D लेंसों के संयोजन की क्षमता क्या है?","kn":"+10 D ಮತ್ತು −4 D ಮಸೂರಗಳ ಸಂಯೋಜನೆಯ ಸಾಮರ್ಥ್ಯ ಎಷ್ಟು?"},"a":{"en":"+6 D.","hi":"+6 D.","kn":"+6 D."}},{"q":{"en":"Which lens corrects short sight (myopia)?","hi":"निकट दृष्टि दोष कौन-सा लेंस ठीक करता है?","kn":"ಸಮೀಪದೃಷ್ಟಿ ದೋಷವನ್ನು ಯಾವ ಮಸೂರ ಸರಿಪಡಿಸುತ್ತದೆ?"},"a":{"en":"A concave lens.","hi":"अवतल लेंस।","kn":"ನಿಮ್ನ ಮಸೂರ."}}]},{"id":"convex-mirror-focal","bench":"convex-mirror","setup":{},"subject":"Physics","domain":"physics","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["ray optics","convex mirror","focal length","radius of curvature"],"title":{"en":"Focal length of a convex mirror (with a convex lens)","hi":"उत्तल दर्पण की फ़ोकस दूरी (उत्तल लेंस की सहायता से)","kn":"ಪೀನ ದರ್ಪಣದ ನಾಭಿದೂರ (ಪೀನ ಮಸೂರದ ಸಹಾಯದಿಂದ)"},"summary":{"en":"Use a convex lens to send converging light to the mirror; when the light returns on itself the mirror’s centre of curvature is found.","hi":"उत्तल लेंस से अभिसारी प्रकाश दर्पण पर भेजें; जब प्रकाश उसी रास्ते लौटे तब दर्पण का वक्रता केंद्र मिल जाता है।","kn":"ಪೀನ ಮಸೂರದಿಂದ ಅಭಿಸರಣ ಬೆಳಕನ್ನು ದರ್ಪಣಕ್ಕೆ ಕಳುಹಿಸಿ; ಬೆಳಕು ಅದೇ ದಾರಿಯಲ್ಲಿ ಹಿಂತಿರುಗಿದಾಗ ದರ್ಪಣದ ವಕ್ರತಾ ಕೇಂದ್ರ ಸಿಗುತ್ತದೆ."},"aim":{"en":"To find the focal length of a convex mirror using a convex lens.","hi":"उत्तल लेंस की सहायता से उत्तल दर्पण की फ़ोकस दूरी ज्ञात करना।","kn":"ಪೀನ ಮಸೂರದ ಸಹಾಯದಿಂದ ಪೀನ ದರ್ಪಣದ ನಾಭಿದೂರ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"The lens forms a real image of the needle at P. If the convex mirror is placed so that P is at its centre of curvature, the rays meet the mirror normally, retrace their path, and the image coincides with the needle. Then R = P − M (M is the mirror position) and f = R/2.","hi":"लेंस सुई का वास्तविक प्रतिबिंब P पर बनाता है। यदि उत्तल दर्पण ऐसे रखा जाए कि P उसका वक्रता केंद्र हो, तो किरणें दर्पण पर अभिलंबवत पड़कर उसी रास्ते लौटती हैं और प्रतिबिंब सुई पर बनता है। तब R = P − M (M दर्पण की स्थिति) और f = R/2.","kn":"ಮಸೂರ ಸೂಜಿಯ ನೈಜ ಪ್ರತಿಬಿಂಬವನ್ನು P ನಲ್ಲಿ ರೂಪಿಸುತ್ತದೆ. P ಪೀನ ದರ್ಪಣದ ವಕ್ರತಾ ಕೇಂದ್ರವಾಗುವಂತೆ ದರ್ಪಣವನ್ನಿಟ್ಟರೆ ಕಿರಣಗಳು ಲಂಬವಾಗಿ ಬಿದ್ದು ಅದೇ ದಾರಿಯಲ್ಲಿ ಹಿಂತಿರುಗುತ್ತವೆ; ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯ ಮೇಲೆಯೇ ಮೂಡುತ್ತದೆ. ಆಗ R = P − M (M ದರ್ಪಣದ ಸ್ಥಾನ), f = R/2."},"apparatus":[{"en":"Optical bench with uprights","hi":"उपस्तंभों सहित प्रकाशिक बेंच","kn":"ಆಧಾರ ಕಂಬಗಳ ಸಹಿತ ದೃಕ್ ಪೀಠ"},{"en":"Convex lens (15 cm)","hi":"उत्तल लेंस (15 cm)","kn":"ಪೀನ ಮಸೂರ (15 cm)"},{"en":"Convex mirror","hi":"उत्तल दर्पण","kn":"ಪೀನ ದರ್ಪಣ"},{"en":"Two optical needles (object and image)","hi":"दो प्रकाशिक सुइयाँ (वस्तु और प्रतिबिंब)","kn":"ಎರಡು ದೃಕ್ ಸೂಜಿಗಳು (ವಸ್ತು ಮತ್ತು ಪ್ರತಿಬಿಂಬ)"}],"steps":[{"en":"Set the object needle and the convex lens so that the lens forms a real image far from it. Find that image point P with the image needle.","hi":"वस्तु सुई और उत्तल लेंस ऐसे रखें कि लेंस उससे दूर वास्तविक प्रतिबिंब बनाए। प्रतिबिंब सुई से वह बिंदु P ढूँढें।","kn":"ವಸ್ತು ಸೂಜಿ ಮತ್ತು ಪೀನ ಮಸೂರವನ್ನು ಮಸೂರ ದೂರದಲ್ಲಿ ನೈಜ ಪ್ರತಿಬಿಂಬ ರೂಪಿಸುವಂತೆ ಇಡಿ. ಪ್ರತಿಬಿಂಬ ಸೂಜಿಯಿಂದ ಆ ಬಿಂದು P ಹುಡುಕಿ."},{"en":"Remove the image needle and put the convex mirror between the lens and P, facing the lens.","hi":"प्रतिबिंब सुई हटाकर उत्तल दर्पण को लेंस और P के बीच, लेंस की ओर मुँह करके रखें।","kn":"ಪ್ರತಿಬಿಂಬ ಸೂಜಿ ತೆಗೆದು ಪೀನ ದರ್ಪಣವನ್ನು ಮಸೂರ ಮತ್ತು P ನಡುವೆ ಮಸೂರದತ್ತ ಮುಖಮಾಡಿ ಇಡಿ."},{"en":"Move the mirror until the image seen through the lens coincides with the object needle (no parallax). Record its position M.","hi":"दर्पण तब तक खिसकाएँ जब तक लेंस से दिखता प्रतिबिंब वस्तु सुई से मिल न जाए (लंबन न रहे)। उसकी स्थिति M लिखें।","kn":"ಮಸೂರದ ಮೂಲಕ ಕಾಣುವ ಪ್ರತಿಬಿಂಬ ವಸ್ತು ಸೂಜಿಯೊಂದಿಗೆ ಸೇರುವವರೆಗೆ (ಭ್ರಂಶ ಇಲ್ಲದೆ) ದರ್ಪಣ ಸರಿಸಿ. ಅದರ ಸ್ಥಾನ M ದಾಖಲಿಸಿ."},{"en":"R = P − M and f = R/2. Repeat with other object distances.","hi":"R = P − M और f = R/2. दूसरी वस्तु दूरियों के साथ दोहराएँ।","kn":"R = P − M ಮತ್ತು f = R/2. ಬೇರೆ ವಸ್ತು ದೂರಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Keep the tips of the needles and the centre of the lens or mirror at the same height.","hi":"सुइयों की नोकें और लेंस या दर्पण का केंद्र एक ही ऊँचाई पर रखें।","kn":"ಸೂಜಿಗಳ ತುದಿಗಳು ಮತ್ತು ಮಸೂರ ಅಥವಾ ದರ್ಪಣದ ಕೇಂದ್ರ ಒಂದೇ ಎತ್ತರದಲ್ಲಿರಲಿ."},{"en":"Remove parallax tip to tip, keeping the eye at least 25 cm from the needle.","hi":"आँख को सुई से कम से कम 25 cm दूर रखकर नोक से नोक का लंबन हटाएँ।","kn":"ಕಣ್ಣನ್ನು ಸೂಜಿಯಿಂದ ಕನಿಷ್ಠ 25 cm ದೂರವಿಟ್ಟು ತುದಿಯಿಂದ ತುದಿಗೆ ಭ್ರಂಶ ತೆಗೆಯಿರಿ."},{"en":"The real image P must form well beyond the mirror’s focal length from the lens.","hi":"वास्तविक प्रतिबिंब P लेंस से दर्पण की फ़ोकस दूरी से काफ़ी आगे बनना चाहिए।","kn":"ನೈಜ ಪ್ರತಿಬಿಂಬ P ಮಸೂರದಿಂದ ದರ್ಪಣದ ನಾಭಿದೂರಕ್ಕಿಂತ ಸಾಕಷ್ಟು ಆಚೆ ಮೂಡಬೇಕು."}],"conclusion":{"en":"When the mirror is a distance R in front of the lens’s image point the light retraces its path; the convex mirror’s focal length is R/2.","hi":"जब दर्पण लेंस के प्रतिबिंब बिंदु से R दूरी पहले होता है तो प्रकाश उसी रास्ते लौटता है; उत्तल दर्पण की फ़ोकस दूरी R/2 है।","kn":"ದರ್ಪಣ ಮಸೂರದ ಪ್ರತಿಬಿಂಬ ಬಿಂದುವಿಗಿಂತ R ದೂರ ಮುಂದೆ ಇದ್ದಾಗ ಬೆಳಕು ಅದೇ ದಾರಿಯಲ್ಲಿ ಹಿಂತಿರುಗುತ್ತದೆ; ಪೀನ ದರ್ಪಣದ ನಾಭಿದೂರ R/2."},"viva":[{"q":{"en":"Why does a convex mirror alone not give a real image?","hi":"अकेला उत्तल दर्पण वास्तविक प्रतिबिंब क्यों नहीं देता?","kn":"ಪೀನ ದರ್ಪಣ ಒಂದೇ ನೈಜ ಪ್ರತಿಬಿಂಬ ಏಕೆ ನೀಡುವುದಿಲ್ಲ?"},"a":{"en":"It always diverges the light from a real object.","hi":"यह वास्तविक वस्तु के प्रकाश को सदा अपसारित करता है।","kn":"ನೈಜ ವಸ್ತುವಿನ ಬೆಳಕನ್ನು ಅದು ಯಾವಾಗಲೂ ಅಪಸರಿಸುತ್ತದೆ."}},{"q":{"en":"When does a ray retrace its path after reflection?","hi":"परावर्तन के बाद किरण कब उसी रास्ते लौटती है?","kn":"ಪ್ರತಿಫಲನದ ನಂತರ ಕಿರಣ ಯಾವಾಗ ಅದೇ ದಾರಿಯಲ್ಲಿ ಹಿಂತಿರುಗುತ್ತದೆ?"},"a":{"en":"When it falls normally on the mirror, along a radius.","hi":"जब वह दर्पण पर अभिलंबवत, त्रिज्या के अनुदिश पड़ती है।","kn":"ಅದು ದರ್ಪಣದ ಮೇಲೆ ಲಂಬವಾಗಿ, ತ್ರಿಜ್ಯದ ಉದ್ದಕ್ಕೂ ಬಿದ್ದಾಗ."}},{"q":{"en":"Give a use of a convex mirror.","hi":"उत्तल दर्पण का एक उपयोग बताइए।","kn":"ಪೀನ ದರ್ಪಣದ ಒಂದು ಉಪಯೋಗ ತಿಳಿಸಿ."},"a":{"en":"Rear-view mirrors and shop security mirrors.","hi":"पीछे देखने वाले दर्पण और दुकानों के सुरक्षा दर्पण।","kn":"ಹಿಂಬದಿ ನೋಟದ ದರ್ಪಣಗಳು ಮತ್ತು ಅಂಗಡಿ ಭದ್ರತಾ ದರ್ಪಣಗಳು."}}]},{"id":"refractive-index-microscope","bench":"travelling-microscope","setup":{},"subject":"Physics","domain":"physics","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["refractive index","travelling microscope","real depth","apparent depth","glass slab","refraction"],"title":{"en":"Refractive index of a glass slab (travelling microscope)","hi":"काँच के गुटके का अपवर्तनांक (चल सूक्ष्मदर्शी)","kn":"ಗಾಜಿನ ಚಪ್ಪಡಿಯ ವಕ್ರೀಭವನಾಂಕ (ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕ)"},"summary":{"en":"Focus a microscope on a mark, on the mark seen through a slab, and on the top of the slab; real ÷ apparent depth gives n.","hi":"सूक्ष्मदर्शी को एक निशान पर, गुटके से दिखते निशान पर और गुटके के ऊपरी तल पर फ़ोकस करें; वास्तविक ÷ आभासी गहराई से n मिलता है।","kn":"ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಗುರುತಿನ ಮೇಲೆ, ಚಪ್ಪಡಿಯ ಮೂಲಕ ಕಾಣುವ ಗುರುತಿನ ಮೇಲೆ ಮತ್ತು ಚಪ್ಪಡಿಯ ಮೇಲ್ಮೈ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ; ನೈಜ ÷ ತೋರಿಕೆಯ ಆಳ n ನೀಡುತ್ತದೆ."},"aim":{"en":"To find the refractive index of a glass slab using a travelling microscope.","hi":"चल सूक्ष्मदर्शी से काँच के गुटके का अपवर्तनांक ज्ञात करना।","kn":"ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕದಿಂದ ಗಾಜಿನ ಚಪ್ಪಡಿಯ ವಕ್ರೀಭವನಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Light from a mark under a slab bends away from the normal as it leaves the glass, so the mark seems raised. For near-normal viewing, n = real depth ÷ apparent depth = (R₃ − R₁) ÷ (R₃ − R₂), where R₁, R₂, R₃ are the microscope readings for the mark, the mark through the slab and the top of the slab.","hi":"गुटके के नीचे के निशान का प्रकाश काँच से निकलते समय अभिलंब से दूर मुड़ता है, इसलिए निशान ऊपर उठा दिखता है। लगभग अभिलंब दिशा से देखने पर n = वास्तविक गहराई ÷ आभासी गहराई = (R₃ − R₁) ÷ (R₃ − R₂), जहाँ R₁, R₂, R₃ निशान, गुटके से दिखते निशान और गुटके के ऊपरी तल के सूक्ष्मदर्शी पाठ्यांक हैं।","kn":"ಚಪ್ಪಡಿಯ ಕೆಳಗಿನ ಗುರುತಿನ ಬೆಳಕು ಗಾಜಿನಿಂದ ಹೊರಬರುವಾಗ ಲಂಬದಿಂದ ದೂರ ಬಾಗುತ್ತದೆ; ಆದ್ದರಿಂದ ಗುರುತು ಮೇಲೆದ್ದಂತೆ ಕಾಣುತ್ತದೆ. ಸುಮಾರು ಲಂಬವಾಗಿ ನೋಡಿದಾಗ n = ನೈಜ ಆಳ ÷ ತೋರಿಕೆಯ ಆಳ = (R₃ − R₁) ÷ (R₃ − R₂); R₁, R₂, R₃ ಗುರುತು, ಚಪ್ಪಡಿಯ ಮೂಲಕ ಗುರುತು ಮತ್ತು ಚಪ್ಪಡಿಯ ಮೇಲ್ಮೈಗೆ ಸೂಕ್ಷ್ಮದರ್ಶಕದ ಓದುಗಳು."},"apparatus":[{"en":"Travelling microscope (least count 0.001 cm)","hi":"चल सूक्ष्मदर्शी (अल्पतमांक 0.001 cm)","kn":"ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕ (ಕನಿಷ್ಠ ಎಣಿಕೆ 0.001 cm)"},{"en":"Glass slab","hi":"काँच का गुटका","kn":"ಗಾಜಿನ ಚಪ್ಪಡಿ"},{"en":"Paper with an ink cross","hi":"स्याही के क्रॉस वाला कागज़","kn":"ಶಾಯಿ ಅಡ್ಡಗುರುತಿನ ಕಾಗದ"},{"en":"Lycopodium powder","hi":"लाइकोपोडियम चूर्ण","kn":"ಲೈಕೋಪೋಡಿಯಂ ಪುಡಿ"}],"steps":[{"en":"Focus the microscope on the ink cross and note the reading R₁.","hi":"सूक्ष्मदर्शी को स्याही के क्रॉस पर फ़ोकस करें और पाठ्यांक R₁ लिखें।","kn":"ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಶಾಯಿ ಅಡ್ಡಗುರುತಿನ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ R₁ ಓದನ್ನು ಬರೆಯಿರಿ."},{"en":"Place the slab over the cross. Raise the microscope until the cross is sharp again: reading R₂.","hi":"क्रॉस पर गुटका रखें। सूक्ष्मदर्शी को तब तक ऊपर उठाएँ जब तक क्रॉस फिर स्पष्ट न हो: पाठ्यांक R₂.","kn":"ಅಡ್ಡಗುರುತಿನ ಮೇಲೆ ಚಪ್ಪಡಿ ಇಡಿ. ಅಡ್ಡಗುರುತು ಮತ್ತೆ ಸ್ಪಷ್ಟವಾಗುವವರೆಗೆ ಸೂಕ್ಷ್ಮದರ್ಶಕ ಮೇಲೆತ್ತಿ: ಓದು R₂."},{"en":"Sprinkle a little powder on top of the slab and focus on it: reading R₃.","hi":"गुटके के ऊपर थोड़ा चूर्ण छिड़ककर उस पर फ़ोकस करें: पाठ्यांक R₃.","kn":"ಚಪ್ಪಡಿಯ ಮೇಲೆ ಸ್ವಲ್ಪ ಪುಡಿ ಚಿಮುಕಿಸಿ ಅದರ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ: ಓದು R₃."},{"en":"Work out n = (R₃ − R₁) ÷ (R₃ − R₂).","hi":"n = (R₃ − R₁) ÷ (R₃ − R₂) निकालें।","kn":"n = (R₃ − R₁) ÷ (R₃ − R₂) ಲೆಕ್ಕಿಸಿ."},{"en":"Repeat with slabs of other thickness or glass.","hi":"दूसरी मोटाई या काँच के गुटकों के साथ दोहराएँ।","kn":"ಬೇರೆ ದಪ್ಪ ಅಥವಾ ಗಾಜಿನ ಚಪ್ಪಡಿಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."}],"precautions":[{"en":"Move the microscope in one direction only, to avoid backlash error.","hi":"पश्च-गति त्रुटि से बचने के लिए सूक्ष्मदर्शी को केवल एक दिशा में चलाएँ।","kn":"ಹಿಂಚಲನೆ ದೋಷ ತಪ್ಪಿಸಲು ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಸರಿಸಿ."},{"en":"Check the zero error of every instrument before you start.","hi":"शुरू करने से पहले हर उपकरण की शून्य त्रुटि जाँचें।","kn":"ಆರಂಭಿಸುವ ಮೊದಲು ಪ್ರತಿ ಉಪಕರಣದ ಶೂನ್ಯ ದೋಷ ಪರಿಶೀಲಿಸಿ."},{"en":"Use only a thin layer of powder.","hi":"चूर्ण की केवल पतली परत लें।","kn":"ಪುಡಿಯ ತೆಳು ಪದರ ಮಾತ್ರ ಬಳಸಿ."}],"conclusion":{"en":"The mark appears raised by t(1 − 1/n), and real ÷ apparent depth gives the refractive index of the glass (about 1.5).","hi":"निशान t(1 − 1/n) ऊपर उठा दिखता है, और वास्तविक ÷ आभासी गहराई से काँच का अपवर्तनांक (लगभग 1.5) मिलता है।","kn":"ಗುರುತು t(1 − 1/n) ಮೇಲೆದ್ದಂತೆ ಕಾಣುತ್ತದೆ; ನೈಜ ÷ ತೋರಿಕೆಯ ಆಳ ಗಾಜಿನ ವಕ್ರೀಭವನಾಂಕ (ಸುಮಾರು 1.5) ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why does a pond look shallower than it is?","hi":"तालाब वास्तविकता से उथला क्यों दिखता है?","kn":"ಕೊಳ ನಿಜಕ್ಕಿಂತ ಆಳ ಕಡಿಮೆ ಏಕೆ ಕಾಣುತ್ತದೆ?"},"a":{"en":"Refraction at the water surface: the apparent depth is the real depth ÷ n.","hi":"पानी की सतह पर अपवर्तन: आभासी गहराई = वास्तविक गहराई ÷ n.","kn":"ನೀರಿನ ಮೇಲ್ಮೈಯಲ್ಲಿ ವಕ್ರೀಭವನ: ತೋರಿಕೆಯ ಆಳ = ನೈಜ ಆಳ ÷ n."}},{"q":{"en":"What is the least count of a travelling microscope?","hi":"चल सूक्ष्मदर्शी का अल्पतमांक क्या है?","kn":"ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕದ ಕನಿಷ್ಠ ಎಣಿಕೆ ಎಷ್ಟು?"},"a":{"en":"Usually 0.001 cm (one main-scale division ÷ number of vernier divisions).","hi":"प्रायः 0.001 cm (मुख्य पैमाने का एक भाग ÷ वर्नियर भागों की संख्या)।","kn":"ಸಾಮಾನ್ಯವಾಗಿ 0.001 cm (ಮುಖ್ಯ ಅಳತೆಯ ಒಂದು ಭಾಗ ÷ ವರ್ನಿಯರ್ ಭಾಗಗಳ ಸಂಖ್ಯೆ)."}},{"q":{"en":"Does n depend on the colour of light?","hi":"क्या n प्रकाश के रंग पर निर्भर करता है?","kn":"n ಬೆಳಕಿನ ಬಣ್ಣವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?"},"a":{"en":"Yes: it is larger for violet than for red (dispersion).","hi":"हाँ: बैंगनी के लिए लाल से अधिक होता है (वर्ण विक्षेपण)।","kn":"ಹೌದು: ನೇರಳೆಗೆ ಕೆಂಪಿಗಿಂತ ಹೆಚ್ಚು (ವರ್ಣ ವಿಕ್ಷೇಪಣ)."}}]},{"id":"diffraction-grating","bench":"grating","setup":{},"subject":"Physics","domain":"physics","levels":["ug"],"mode":"guided","curricula":["ug-physics"],"reviewed":false,"keywords":["diffraction grating","grating","spectrometer","wavelength","mercury spectrum","diffraction","wave optics"],"title":{"en":"Wavelengths of spectral lines with a diffraction grating","hi":"विवर्तन ग्रेटिंग से स्पेक्ट्रमी रेखाओं की तरंगदैर्घ्य","kn":"ವಿವರ್ತನ ಗ್ರೇಟಿಂಗ್‌ನಿಂದ ರೋಹಿತ ರೇಖೆಗಳ ತರಂಗಾಂತರ"},"summary":{"en":"Measure the diffraction angles of mercury lines with a spectrometer and compute λ = d sin θ / n.","hi":"स्पेक्ट्रोमीटर से पारे की रेखाओं के विवर्तन कोण मापें और λ = d sin θ / n निकालें।","kn":"ರೋಹಿತಮಾಪಕದಿಂದ ಪಾದರಸ ರೇಖೆಗಳ ವಿವರ್ತನ ಕೋನಗಳನ್ನು ಅಳೆದು λ = d sin θ / n ಲೆಕ್ಕಿಸಿ."},"aim":{"en":"To find the wavelengths of the prominent lines of mercury using a plane transmission grating.","hi":"समतल पारगमन ग्रेटिंग से पारे की प्रमुख रेखाओं की तरंगदैर्घ्य ज्ञात करना।","kn":"ಸಮತಲ ಪ್ರಸರಣ ಗ್ರೇಟಿಂಗ್ ಬಳಸಿ ಪಾದರಸದ ಪ್ರಮುಖ ರೇಖೆಗಳ ತರಂಗಾಂತರ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"A grating with N lines per metre has spacing d = 1/N. Light from the slits reinforces where the path difference is a whole number of wavelengths: d sin θ = nλ. Measuring θ for each line and order gives λ.","hi":"प्रति मीटर N रेखाओं वाली ग्रेटिंग का अंतराल d = 1/N है। झिरियों का प्रकाश वहाँ प्रबल होता है जहाँ पथांतर तरंगदैर्घ्य का पूर्ण गुणज हो: d sin θ = nλ. हर रेखा और कोटि के लिए θ मापकर λ मिलती है।","kn":"ಪ್ರತಿ ಮೀಟರ್‌ಗೆ N ರೇಖೆಗಳ ಗ್ರೇಟಿಂಗ್‌ನ ಅಂತರ d = 1/N. ಪಥಾಂತರ ತರಂಗಾಂತರದ ಪೂರ್ಣ ಗುಣಕವಾದಲ್ಲಿ ಸೀಳುಗಳ ಬೆಳಕು ಬಲಗೊಳ್ಳುತ್ತದೆ: d sin θ = nλ. ಪ್ರತಿ ರೇಖೆ ಮತ್ತು ಕ್ರಮಕ್ಕೆ θ ಅಳೆದು λ ಪಡೆಯಬಹುದು."},"apparatus":[{"en":"Spectrometer","hi":"स्पेक्ट्रोमीटर","kn":"ರೋಹಿತಮಾಪಕ"},{"en":"Plane transmission grating (300–600 lines/mm)","hi":"समतल पारगमन ग्रेटिंग (300–600 रेखाएँ/mm)","kn":"ಸಮತಲ ಪ್ರಸರಣ ಗ್ರೇಟಿಂಗ್ (300–600 ರೇಖೆ/mm)"},{"en":"Mercury vapour lamp","hi":"पारद वाष्प लैंप","kn":"ಪಾದರಸ ಆವಿ ದೀಪ"},{"en":"Spirit level and reading lens","hi":"स्पिरिट लेवल और पठन लेंस","kn":"ಸ್ಪಿರಿಟ್ ಲೆವೆಲ್ ಮತ್ತು ಓದುವ ಮಸೂರ"}],"steps":[{"en":"Level the spectrometer and focus the telescope and collimator for parallel light (Schuster’s method).","hi":"स्पेक्ट्रोमीटर को समतल करें और समांतर प्रकाश के लिए दूरदर्शी तथा समांतरित्र फ़ोकस करें (शुस्टर विधि)।","kn":"ರೋಹಿತಮಾಪಕವನ್ನು ಸಮತಲಗೊಳಿಸಿ, ಸಮಾಂತರ ಬೆಳಕಿಗಾಗಿ ದೂರದರ್ಶಕ ಮತ್ತು ಸಮಾಂತರಕವನ್ನು ಕೇಂದ್ರೀಕರಿಸಿ (ಶುಸ್ಟರ್ ವಿಧಾನ)."},{"en":"Set the grating normal to the incident light.","hi":"ग्रेटिंग को आपतित प्रकाश के अभिलंब रखें।","kn":"ಗ್ರೇಟಿಂಗನ್ನು ಆಪಾತ ಬೆಳಕಿಗೆ ಲಂಬವಾಗಿಡಿ."},{"en":"Turn the telescope to each coloured line of the first order on one side and set the cross-wire on it; read the angle.","hi":"दूरदर्शी को एक ओर प्रथम कोटि की हर रंगीन रेखा पर घुमाकर क्रॉस-तार उस पर रखें; कोण पढ़ें।","kn":"ದೂರದರ್ಶಕವನ್ನು ಒಂದು ಕಡೆ ಮೊದಲ ಕ್ರಮದ ಪ್ರತಿ ಬಣ್ಣದ ರೇಖೆಗೆ ತಿರುಗಿಸಿ ಅಡ್ಡತಂತಿಯನ್ನು ಅದರ ಮೇಲಿಡಿ; ಕೋನ ಓದಿ."},{"en":"Repeat on the other side and for the second order; take θ as half the angle between the two sides.","hi":"दूसरी ओर और द्वितीय कोटि के लिए दोहराएँ; θ को दोनों ओर के कोणों के अंतर का आधा लें।","kn":"ಇನ್ನೊಂದು ಕಡೆ ಮತ್ತು ಎರಡನೇ ಕ್ರಮಕ್ಕೆ ಪುನರಾವರ್ತಿಸಿ; θ ಅನ್ನು ಎರಡು ಕಡೆಗಳ ಕೋನ ವ್ಯತ್ಯಾಸದ ಅರ್ಧವಾಗಿ ತೆಗೆದುಕೊಳ್ಳಿ."},{"en":"Work out λ = d sin θ / n for each line and its uncertainty.","hi":"हर रेखा के लिए λ = d sin θ / n और उसकी अनिश्चितता निकालें।","kn":"ಪ್ರತಿ ರೇಖೆಗೆ λ = d sin θ / n ಮತ್ತು ಅದರ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ."},{"en":"Export the readings as CSV and work out the uncertainty from the fit.","hi":"पाठ्यांक CSV में निर्यात करें और फ़िट से अनिश्चितता निकालें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Never touch the ruled surface of the grating.","hi":"ग्रेटिंग की रेखित सतह को कभी न छुएँ।","kn":"ಗ್ರೇಟಿಂಗ್‌ನ ಗೆರೆಹಾಕಿದ ಮೇಲ್ಮೈಯನ್ನು ಎಂದೂ ಮುಟ್ಟಬೇಡಿ."},{"en":"Read both verniers to cancel eccentricity error.","hi":"उत्केंद्रता त्रुटि मिटाने के लिए दोनों वर्नियर पढ़ें।","kn":"ಉತ್ಕೇಂದ್ರತೆ ದೋಷ ರದ್ದುಗೊಳಿಸಲು ಎರಡೂ ವರ್ನಿಯರ್ ಓದಿ."},{"en":"Do not look at the mercury lamp directly; it gives out ultraviolet light.","hi":"पारद लैंप को सीधे न देखें; यह पराबैंगनी प्रकाश देता है।","kn":"ಪಾದರಸ ದೀಪವನ್ನು ನೇರವಾಗಿ ನೋಡಬೇಡಿ; ಅದು ಅತಿನೇರಳೆ ಬೆಳಕು ನೀಡುತ್ತದೆ."}],"conclusion":{"en":"The wavelengths of the violet, blue, green and yellow mercury lines agree with the standard values (404.7, 435.8, 546.1 and about 578 nm) within the uncertainty.","hi":"पारे की बैंगनी, नीली, हरी और पीली रेखाओं की तरंगदैर्घ्य अनिश्चितता के भीतर मानक मानों (404.7, 435.8, 546.1 और लगभग 578 nm) से मेल खाती हैं।","kn":"ಪಾದರಸದ ನೇರಳೆ, ನೀಲಿ, ಹಸಿರು ಮತ್ತು ಹಳದಿ ರೇಖೆಗಳ ತರಂಗಾಂತರಗಳು ಅನಿಶ್ಚಿತತೆಯೊಳಗೆ ಪ್ರಮಾಣಿತ ಮೌಲ್ಯಗಳಿಗೆ (404.7, 435.8, 546.1 ಮತ್ತು ಸುಮಾರು 578 nm) ಹೊಂದುತ್ತವೆ."},"viva":[{"q":{"en":"Why do higher orders spread the spectrum more?","hi":"उच्च कोटियाँ स्पेक्ट्रम को अधिक क्यों फैलाती हैं?","kn":"ಹೆಚ್ಚಿನ ಕ್ರಮಗಳು ರೋಹಿತವನ್ನು ಹೆಚ್ಚು ಏಕೆ ಹರಡುತ್ತವೆ?"},"a":{"en":"Dispersion dθ/dλ = n/(d cos θ) grows with the order n.","hi":"वर्ण विक्षेपण dθ/dλ = n/(d cos θ) कोटि n के साथ बढ़ता है।","kn":"ವಿಕ್ಷೇಪಣ dθ/dλ = n/(d cos θ) ಕ್ರಮ n ನೊಂದಿಗೆ ಹೆಚ್ಚುತ್ತದೆ."}},{"q":{"en":"What limits the highest order you can see?","hi":"दिखने वाली सबसे ऊँची कोटि किससे सीमित होती है?","kn":"ಕಾಣುವ ಗರಿಷ್ಠ ಕ್ರಮವನ್ನು ಯಾವುದು ಮಿತಿಗೊಳಿಸುತ್ತದೆ?"},"a":{"en":"sin θ cannot exceed 1, so n ≤ d/λ.","hi":"sin θ, 1 से अधिक नहीं हो सकता, इसलिए n ≤ d/λ.","kn":"sin θ 1 ಮೀರಲಾರದು, ಆದ್ದರಿಂದ n ≤ d/λ."}},{"q":{"en":"How is a grating spectrum different from a prism spectrum?","hi":"ग्रेटिंग स्पेक्ट्रम प्रिज़्म स्पेक्ट्रम से कैसे भिन्न है?","kn":"ಗ್ರೇಟಿಂಗ್ ರೋಹಿತ ಪಟ್ಟಕ ರೋಹಿತಕ್ಕಿಂತ ಹೇಗೆ ಭಿನ್ನ?"},"a":{"en":"Red is deviated most in a grating, least in a prism; the grating spectrum is nearly linear in λ.","hi":"ग्रेटिंग में लाल सबसे अधिक, प्रिज़्म में सबसे कम विचलित होता है; ग्रेटिंग स्पेक्ट्रम λ में लगभग रैखिक है।","kn":"ಗ್ರೇಟಿಂಗ್‌ನಲ್ಲಿ ಕೆಂಪು ಅತಿ ಹೆಚ್ಚು, ಪಟ್ಟಕದಲ್ಲಿ ಅತಿ ಕಡಿಮೆ ವಿಚಲಿಸುತ್ತದೆ; ಗ್ರೇಟಿಂಗ್ ರೋಹಿತ λ ಯಲ್ಲಿ ಬಹುತೇಕ ರೇಖೀಯ."}}]},{"id":"newtons-rings","bench":"newton-rings","setup":{},"subject":"Physics","domain":"physics","levels":["ug"],"mode":"guided","curricula":["ug-physics"],"reviewed":false,"keywords":["newton's rings","interference","thin film","wavelength","sodium light","wave optics"],"title":{"en":"Wavelength of sodium light by Newton's rings","hi":"न्यूटन के वलयों से सोडियम प्रकाश की तरंगदैर्घ्य","kn":"ನ್ಯೂಟನ್ ಉಂಗುರಗಳಿಂದ ಸೋಡಿಯಂ ಬೆಳಕಿನ ತರಂಗಾಂತರ"},"summary":{"en":"Measure the diameters of dark rings under a lens; the slope of D² against n gives λ.","hi":"लेंस के नीचे काले वलयों के व्यास मापें; D² और n के ग्राफ़ की प्रवणता से λ मिलती है।","kn":"ಮಸೂರದ ಕೆಳಗಿನ ಕಪ್ಪು ಉಂಗುರಗಳ ವ್ಯಾಸ ಅಳೆಯಿರಿ; D² ಮತ್ತು n ನಕ್ಷೆಯ ಇಳಿಜಾರು λ ನೀಡುತ್ತದೆ."},"aim":{"en":"To find the wavelength of sodium light using Newton's rings.","hi":"न्यूटन के वलयों से सोडियम प्रकाश की तरंगदैर्घ्य ज्ञात करना।","kn":"ನ್ಯೂಟನ್ ಉಂಗುರಗಳಿಂದ ಸೋಡಿಯಂ ಬೆಳಕಿನ ತರಂಗಾಂತರ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"A thin air film between a plano-convex lens and a glass plate gets thicker away from the centre. Light reflected from its two surfaces interferes; with the extra half-wave on reflection the centre is dark and the nth dark ring has Dₙ² = 4nλR. So the slope of D² against n is 4λR.","hi":"समतल-उत्तल लेंस और काँच की प्लेट के बीच वायु की पतली परत केंद्र से दूर मोटी होती जाती है। उसकी दोनों सतहों से परावर्तित प्रकाश व्यतिकरण करता है; परावर्तन पर अतिरिक्त अर्ध-तरंग के कारण केंद्र काला होता है और n वें काले वलय के लिए Dₙ² = 4nλR. अतः D² और n की प्रवणता 4λR है।","kn":"ಸಮತಲ-ಪೀನ ಮಸೂರ ಮತ್ತು ಗಾಜಿನ ತಟ್ಟೆಯ ನಡುವಿನ ತೆಳು ಗಾಳಿ ಪದರ ಕೇಂದ್ರದಿಂದ ದೂರ ಹೋದಂತೆ ದಪ್ಪವಾಗುತ್ತದೆ. ಅದರ ಎರಡು ಮೇಲ್ಮೈಗಳಿಂದ ಪ್ರತಿಫಲಿಸಿದ ಬೆಳಕು ವ್ಯತಿಕರಣಗೊಳ್ಳುತ್ತದೆ; ಪ್ರತಿಫಲನದ ಹೆಚ್ಚುವರಿ ಅರ್ಧ-ತರಂಗದಿಂದ ಕೇಂದ್ರ ಕಪ್ಪು; n ನೇ ಕಪ್ಪು ಉಂಗುರಕ್ಕೆ Dₙ² = 4nλR. ಆದ್ದರಿಂದ D² ಮತ್ತು n ಇಳಿಜಾರು 4λR."},"apparatus":[{"en":"Newton's rings apparatus (plano-convex lens on a glass plate)","hi":"न्यूटन वलय उपकरण (काँच की प्लेट पर समतल-उत्तल लेंस)","kn":"ನ್ಯೂಟನ್ ಉಂಗುರ ಉಪಕರಣ (ಗಾಜಿನ ತಟ್ಟೆಯ ಮೇಲೆ ಸಮತಲ-ಪೀನ ಮಸೂರ)"},{"en":"Sodium vapour lamp","hi":"सोडियम वाष्प लैंप","kn":"ಸೋಡಿಯಂ ಆವಿ ದೀಪ"},{"en":"Travelling microscope","hi":"चल सूक्ष्मदर्शी","kn":"ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕ"},{"en":"Glass plate at 45°","hi":"45° पर काँच की प्लेट","kn":"45° ನಲ್ಲಿ ಗಾಜಿನ ತಟ್ಟೆ"}],"steps":[{"en":"Send sodium light down onto the lens with the 45° glass plate and focus the microscope on the rings.","hi":"45° काँच की प्लेट से सोडियम प्रकाश लेंस पर नीचे भेजें और सूक्ष्मदर्शी को वलयों पर फ़ोकस करें।","kn":"45° ಗಾಜಿನ ತಟ್ಟೆಯಿಂದ ಸೋಡಿಯಂ ಬೆಳಕನ್ನು ಮಸೂರದ ಮೇಲೆ ಕೆಳಗೆ ಕಳುಹಿಸಿ, ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಉಂಗುರಗಳ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ."},{"en":"Set the cross-wire at the dark centre, then move out to the 20th dark ring.","hi":"क्रॉस-तार को काले केंद्र पर रखें, फिर 20वें काले वलय तक बाहर जाएँ।","kn":"ಅಡ್ಡತಂತಿಯನ್ನು ಕಪ್ಪು ಕೇಂದ್ರದಲ್ಲಿಟ್ಟು, ನಂತರ 20ನೇ ಕಪ್ಪು ಉಂಗುರದವರೆಗೆ ಹೊರಗೆ ಸರಿಯಿರಿ."},{"en":"Come back, reading the microscope at every fourth dark ring on one side, then across the centre on the other side.","hi":"वापस आते हुए एक ओर हर चौथे काले वलय पर, फिर केंद्र पार दूसरी ओर, सूक्ष्मदर्शी पढ़ें।","kn":"ಹಿಂತಿರುಗುವಾಗ ಒಂದು ಕಡೆ ಪ್ರತಿ ನಾಲ್ಕನೇ ಕಪ್ಪು ಉಂಗುರದಲ್ಲಿ, ನಂತರ ಕೇಂದ್ರದ ಆಚೆ ಇನ್ನೊಂದು ಕಡೆ ಸೂಕ್ಷ್ಮದರ್ಶಕ ಓದಿ."},{"en":"Find each diameter Dₙ and plot Dₙ² against n.","hi":"हर व्यास Dₙ ज्ञात करके Dₙ² और n का ग्राफ़ बनाएँ।","kn":"ಪ್ರತಿ ವ್ಯಾಸ Dₙ ಕಂಡುಹಿಡಿದು Dₙ² ಮತ್ತು n ನಕ್ಷೆ ಎಳೆಯಿರಿ."},{"en":"Find R with a spherometer and work out λ = slope ÷ 4R with its uncertainty.","hi":"गोलाईमापी से R ज्ञात करें और λ = प्रवणता ÷ 4R उसकी अनिश्चितता सहित निकालें।","kn":"ಗೋಳಮಾಪಕದಿಂದ R ಕಂಡುಹಿಡಿದು λ = ಇಳಿಜಾರು ÷ 4R ಅನಿಶ್ಚಿತತೆ ಸಹಿತ ಲೆಕ್ಕಿಸಿ."},{"en":"Export the readings as CSV and work out the uncertainty from the fit.","hi":"पाठ्यांक CSV में निर्यात करें और फ़िट से अनिश्चितता निकालें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Move the microscope in one direction only (no backlash).","hi":"सूक्ष्मदर्शी को केवल एक दिशा में चलाएँ (पश्च-गति नहीं)।","kn":"ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಸರಿಸಿ (ಹಿಂಚಲನೆ ಇಲ್ಲ)."},{"en":"Count the rings carefully; do not skip one.","hi":"वलय ध्यान से गिनें; कोई न छोड़ें।","kn":"ಉಂಗುರಗಳನ್ನು ಎಚ್ಚರದಿಂದ ಎಣಿಸಿ; ಯಾವುದನ್ನೂ ಬಿಡಬೇಡಿ."},{"en":"Clean the lens and plate so the centre is dark.","hi":"लेंस और प्लेट साफ़ करें ताकि केंद्र काला रहे।","kn":"ಕೇಂದ್ರ ಕಪ್ಪಾಗಿರುವಂತೆ ಮಸೂರ ಮತ್ತು ತಟ್ಟೆ ಸ್ವಚ್ಛಗೊಳಿಸಿ."}],"conclusion":{"en":"Dₙ² rises in a straight line with n, and the slope gives the wavelength of sodium light close to 589 nm.","hi":"Dₙ², n के साथ सीधी रेखा में बढ़ता है, और प्रवणता से सोडियम प्रकाश की तरंगदैर्घ्य 589 nm के निकट मिलती है।","kn":"Dₙ², n ಯೊಂದಿಗೆ ಸರಳರೇಖೆಯಲ್ಲಿ ಏರುತ್ತದೆ; ಇಳಿಜಾರು ಸೋಡಿಯಂ ಬೆಳಕಿನ ತರಂಗಾಂತರವನ್ನು 589 nm ಹತ್ತಿರ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why is the centre dark in reflected light?","hi":"परावर्तित प्रकाश में केंद्र काला क्यों होता है?","kn":"ಪ್ರತಿಫಲಿತ ಬೆಳಕಿನಲ್ಲಿ ಕೇಂದ್ರ ಏಕೆ ಕಪ್ಪು?"},"a":{"en":"The film thickness is zero there, and reflection at the denser glass adds a phase change of π.","hi":"वहाँ परत की मोटाई शून्य है, और सघन काँच पर परावर्तन से π का कलांतर जुड़ता है।","kn":"ಅಲ್ಲಿ ಪದರದ ದಪ್ಪ ಶೂನ್ಯ; ಸಾಂದ್ರ ಗಾಜಿನ ಮೇಲಿನ ಪ್ರತಿಫಲನ π ಹಂತ ಬದಲಾವಣೆ ಸೇರಿಸುತ್ತದೆ."}},{"q":{"en":"Why do the rings get closer together further out?","hi":"बाहर की ओर वलय पास-पास क्यों हो जाते हैं?","kn":"ಹೊರಗೆ ಹೋದಂತೆ ಉಂಗುರಗಳು ಏಕೆ ಹತ್ತಿರವಾಗುತ್ತವೆ?"},"a":{"en":"The radius goes as √n, so successive rings differ less in radius.","hi":"त्रिज्या √n के अनुसार बढ़ती है, इसलिए क्रमागत वलयों की त्रिज्या में अंतर घटता है।","kn":"ತ್ರಿಜ್ಯ √n ನಂತೆ ಬೆಳೆಯುತ್ತದೆ; ಆದ್ದರಿಂದ ಅನುಕ್ರಮ ಉಂಗುರಗಳ ತ್ರಿಜ್ಯ ವ್ಯತ್ಯಾಸ ಕಡಿಮೆ."}},{"q":{"en":"What happens if water fills the gap?","hi":"यदि अंतराल में पानी भर दें तो क्या होगा?","kn":"ಅಂತರದಲ್ಲಿ ನೀರು ತುಂಬಿದರೆ ಏನಾಗುತ್ತದೆ?"},"a":{"en":"The rings shrink: D² is divided by the refractive index of water.","hi":"वलय छोटे हो जाते हैं: D² पानी के अपवर्तनांक से विभाजित हो जाता है।","kn":"ಉಂಗುರಗಳು ಕುಗ್ಗುತ್ತವೆ: D², ನೀರಿನ ವಕ್ರೀಭವನಾಂಕದಿಂದ ಭಾಗಿಸಲ್ಪಡುತ್ತದೆ."}}]},{"id":"hookes-law","bench":"spring","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["hooke's law","spring","spring constant","elasticity","mechanical properties of solids","extension"],"title":{"en":"Hooke's law with a helical spring","hi":"कुंडलित स्प्रिंग से हुक का नियम","kn":"ಸುರುಳಿ ಸ್ಪ್ರಿಂಗ್‌ನಿಂದ ಹುಕ್‌ನ ನಿಯಮ"},"summary":{"en":"Hang weights on a spring, read the pointer, and find the spring constant from the load–extension graph.","hi":"स्प्रिंग पर बाट लटकाएँ, सूचक पढ़ें, और भार–विस्तार ग्राफ़ से स्प्रिंग नियतांक ज्ञात करें।","kn":"ಸ್ಪ್ರಿಂಗ್‌ಗೆ ತೂಕಗಳನ್ನು ತೂಗುಹಾಕಿ, ಸೂಚಕ ಓದಿ, ಭಾರ–ವಿಸ್ತರಣೆ ನಕ್ಷೆಯಿಂದ ಸ್ಪ್ರಿಂಗ್ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To find the force constant of a helical spring by plotting a graph between load and extension.","hi":"भार और विस्तार के बीच ग्राफ़ बनाकर कुंडलित स्प्रिंग का बल नियतांक ज्ञात करना।","kn":"ಭಾರ ಮತ್ತು ವಿಸ್ತರಣೆಯ ನಡುವೆ ನಕ್ಷೆ ಎಳೆದು ಸುರುಳಿ ಸ್ಪ್ರಿಂಗ್‌ನ ಬಲ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Within the elastic limit the extension of a spring is proportional to the stretching force: F = kx (Hooke's law). The graph of extension against force is a straight line through the origin of slope 1/k.","hi":"प्रत्यास्थता सीमा के भीतर स्प्रिंग का विस्तार खींचने वाले बल के अनुक्रमानुपाती है: F = kx (हुक का नियम)। विस्तार और बल का ग्राफ़ मूल बिंदु से जाने वाली 1/k प्रवणता की सीधी रेखा है।","kn":"ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿಯೊಳಗೆ ಸ್ಪ್ರಿಂಗ್‌ನ ವಿಸ್ತರಣೆ ಎಳೆಯುವ ಬಲಕ್ಕೆ ಅನುಪಾತೀಯ: F = kx (ಹುಕ್ ನಿಯಮ). ವಿಸ್ತರಣೆ ಮತ್ತು ಬಲದ ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ 1/k ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ."},"apparatus":[{"en":"Helical spring with pointer","hi":"सूचक सहित कुंडलित स्प्रिंग","kn":"ಸೂಚಕ ಸಹಿತ ಸುರುಳಿ ಸ್ಪ್ರಿಂಗ್"},{"en":"Rigid stand with clamp","hi":"क्लैंप सहित दृढ़ स्टैंड","kn":"ಕ್ಲ್ಯಾಂಪ್ ಸಹಿತ ದೃಢ ಸ್ಟ್ಯಾಂಡ್"},{"en":"Slotted weights (50 g each) with hanger","hi":"हैंगर सहित खाँचेदार बाट (हर एक 50 g)","kn":"ಹ್ಯಾಂಗರ್ ಸಹಿತ ಸೀಳು ತೂಕಗಳು (ಪ್ರತಿ 50 g)"},{"en":"Metre scale","hi":"मीटर पैमाना","kn":"ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ"}],"steps":[{"en":"Hang the spring from the stand with the hanger and note the pointer reading with no extra load.","hi":"स्टैंड से स्प्रिंग और हैंगर लटकाएँ और बिना अतिरिक्त भार के सूचक का पाठ्यांक लिखें।","kn":"ಸ್ಟ್ಯಾಂಡ್‌ನಿಂದ ಸ್ಪ್ರಿಂಗ್ ಮತ್ತು ಹ್ಯಾಂಗರ್ ತೂಗುಹಾಕಿ, ಹೆಚ್ಚುವರಿ ಭಾರವಿಲ್ಲದೆ ಸೂಚಕದ ಓದನ್ನು ಬರೆಯಿರಿ."},{"en":"Add 50 g at a time, waiting for the pointer to settle, and record each reading.","hi":"एक बार में 50 g जोड़ें, सूचक के स्थिर होने की प्रतीक्षा करें, और हर पाठ्यांक लिखें।","kn":"ಒಮ್ಮೆಗೆ 50 g ಸೇರಿಸಿ, ಸೂಚಕ ಸ್ಥಿರವಾಗುವವರೆಗೆ ಕಾದು, ಪ್ರತಿ ಓದು ದಾಖಲಿಸಿ."},{"en":"Remove the loads one by one and read again (loading and unloading should agree).","hi":"भार एक-एक करके हटाएँ और फिर पढ़ें (भार बढ़ाते और घटाते समय पाठ्यांक मेल खाने चाहिए)।","kn":"ಭಾರಗಳನ್ನು ಒಂದೊಂದಾಗಿ ತೆಗೆದು ಮತ್ತೆ ಓದಿ (ಹೆಚ್ಚಿಸುವ ಮತ್ತು ಇಳಿಸುವ ಓದುಗಳು ಹೊಂದಬೇಕು)."},{"en":"Plot extension against force (F = mg) and find k from the slope.","hi":"विस्तार और बल (F = mg) का ग्राफ़ बनाएँ और प्रवणता से k ज्ञात करें।","kn":"ವಿಸ್ತರಣೆ ಮತ್ತು ಬಲ (F = mg) ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರಿನಿಂದ k ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Do not load the spring beyond its elastic limit.","hi":"स्प्रिंग पर प्रत्यास्थता सीमा से अधिक भार न डालें।","kn":"ಸ್ಪ್ರಿಂಗ್‌ಗೆ ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿ ಮೀರಿ ಭಾರ ಹಾಕಬೇಡಿ."},{"en":"Read the pointer with your eye level with it.","hi":"सूचक को आँख उसकी सीध में रखकर पढ़ें।","kn":"ಸೂಚಕವನ್ನು ಕಣ್ಣು ಅದರ ಮಟ್ಟದಲ್ಲಿಟ್ಟು ಓದಿ."},{"en":"Add the weights gently so the spring does not swing.","hi":"बाट धीरे से जोड़ें ताकि स्प्रिंग न झूले।","kn":"ಸ್ಪ್ರಿಂಗ್ ತೂಗಾಡದಂತೆ ತೂಕಗಳನ್ನು ನಿಧಾನವಾಗಿ ಸೇರಿಸಿ."}],"conclusion":{"en":"Extension is proportional to load within the elastic limit (Hooke's law), and the slope gives the spring constant.","hi":"प्रत्यास्थता सीमा के भीतर विस्तार भार के अनुक्रमानुपाती है (हुक का नियम), और प्रवणता से स्प्रिंग नियतांक मिलता है।","kn":"ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿಯೊಳಗೆ ವಿಸ್ತರಣೆ ಭಾರಕ್ಕೆ ಅನುಪಾತೀಯ (ಹುಕ್ ನಿಯಮ); ಇಳಿಜಾರು ಸ್ಪ್ರಿಂಗ್ ಸ್ಥಿರಾಂಕ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"What is the unit of the spring constant?","hi":"स्प्रिंग नियतांक की इकाई क्या है?","kn":"ಸ್ಪ್ರಿಂಗ್ ಸ್ಥಿರಾಂಕದ ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"N/m.","hi":"N/m.","kn":"N/m."}},{"q":{"en":"What is the elastic limit?","hi":"प्रत्यास्थता सीमा क्या है?","kn":"ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿ ಎಂದರೇನು?"},"a":{"en":"The largest load after which the spring still returns to its original length.","hi":"वह अधिकतम भार जिसके बाद भी स्प्रिंग अपनी मूल लंबाई पर लौट आती है।","kn":"ಸ್ಪ್ರಿಂಗ್ ತನ್ನ ಮೂಲ ಉದ್ದಕ್ಕೆ ಮರಳುವ ಗರಿಷ್ಠ ಭಾರ."}},{"q":{"en":"Two equal springs in series: what is the spring constant?","hi":"दो समान स्प्रिंग श्रेणी में हों तो स्प्रिंग नियतांक क्या होगा?","kn":"ಎರಡು ಸಮಾನ ಸ್ಪ್ರಿಂಗ್‌ಗಳು ಸರಣಿಯಲ್ಲಿದ್ದರೆ ಸ್ಥಿರಾಂಕ ಎಷ್ಟು?"},"a":{"en":"k/2: the pair stretches twice as much.","hi":"k/2: युग्म दोगुना खिंचता है।","kn":"k/2: ಜೋಡಿ ಎರಡು ಪಟ್ಟು ಹಿಗ್ಗುತ್ತದೆ."}}]},{"id":"spring-mass-oscillation","bench":"spring-mass","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["oscillations","spring","simple harmonic motion","time period","spring constant","shm"],"title":{"en":"Time period of a loaded spring","hi":"भारित स्प्रिंग का आवर्तकाल","kn":"ಭಾರಿತ ಸ್ಪ್ರಿಂಗ್‌ನ ಆವರ್ತಕಾಲ"},"summary":{"en":"Time 20 oscillations for different masses and find k from the graph of T² against m.","hi":"विभिन्न द्रव्यमानों के लिए 20 दोलनों का समय लें और T² तथा m के ग्राफ़ से k ज्ञात करें।","kn":"ಬೇರೆ ಬೇರೆ ದ್ರವ್ಯರಾಶಿಗಳಿಗೆ 20 ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆದು T² ಮತ್ತು m ನಕ್ಷೆಯಿಂದ k ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To find the force constant of a spring from the time period of a mass oscillating on it.","hi":"स्प्रिंग पर दोलन करते द्रव्यमान के आवर्तकाल से स्प्रिंग का बल नियतांक ज्ञात करना।","kn":"ಸ್ಪ್ರಿಂಗ್ ಮೇಲೆ ಆಂದೋಲಿಸುವ ದ್ರವ್ಯರಾಶಿಯ ಆವರ್ತಕಾಲದಿಂದ ಸ್ಪ್ರಿಂಗ್‌ನ ಬಲ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"A mass on a spring performs simple harmonic motion with T = 2π√(m/k). So T² = (4π²/k) m: a straight line whose slope gives k. A part of the spring’s own mass also moves, so the line meets the m-axis slightly below zero.","hi":"स्प्रिंग पर द्रव्यमान सरल आवर्त गति करता है जिसका T = 2π√(m/k). अतः T² = (4π²/k) m: एक सीधी रेखा जिसकी प्रवणता से k मिलता है। स्प्रिंग के अपने द्रव्यमान का कुछ भाग भी चलता है, इसलिए रेखा m-अक्ष को शून्य से थोड़ा पीछे काटती है।","kn":"ಸ್ಪ್ರಿಂಗ್ ಮೇಲಿನ ದ್ರವ್ಯರಾಶಿ T = 2π√(m/k) ಇರುವ ಸರಳ ಆವರ್ತ ಚಲನೆ ಮಾಡುತ್ತದೆ. ಆದ್ದರಿಂದ T² = (4π²/k) m: ಇಳಿಜಾರು k ನೀಡುವ ಸರಳರೇಖೆ. ಸ್ಪ್ರಿಂಗ್‌ನ ಸ್ವಂತ ದ್ರವ್ಯರಾಶಿಯ ಭಾಗವೂ ಚಲಿಸುವುದರಿಂದ ರೇಖೆ m-ಅಕ್ಷವನ್ನು ಶೂನ್ಯಕ್ಕಿಂತ ಸ್ವಲ್ಪ ಹಿಂದೆ ಛೇದಿಸುತ್ತದೆ."},"apparatus":[{"en":"Helical spring","hi":"कुंडलित स्प्रिंग","kn":"ಸುರುಳಿ ಸ್ಪ್ರಿಂಗ್"},{"en":"Rigid stand with clamp","hi":"क्लैंप सहित दृढ़ स्टैंड","kn":"ಕ್ಲ್ಯಾಂಪ್ ಸಹಿತ ದೃಢ ಸ್ಟ್ಯಾಂಡ್"},{"en":"Slotted weights (50 g each) with hanger","hi":"हैंगर सहित खाँचेदार बाट (हर एक 50 g)","kn":"ಹ್ಯಾಂಗರ್ ಸಹಿತ ಸೀಳು ತೂಕಗಳು (ಪ್ರತಿ 50 g)"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"}],"steps":[{"en":"Hang a 50 g load and pull it down a little; release it.","hi":"50 g भार लटकाकर थोड़ा नीचे खींचें; छोड़ दें।","kn":"50 g ಭಾರ ತೂಗುಹಾಕಿ ಸ್ವಲ್ಪ ಕೆಳಗೆ ಎಳೆದು ಬಿಡಿ."},{"en":"Time 20 complete oscillations, starting as the load passes the mean position.","hi":"भार के माध्य स्थिति से गुजरते ही शुरू करके 20 पूर्ण दोलनों का समय लें।","kn":"ಭಾರ ಮಧ್ಯಸ್ಥಾನ ದಾಟುವಾಗ ಆರಂಭಿಸಿ 20 ಪೂರ್ಣ ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆಯಿರಿ."},{"en":"Repeat for loads up to 400 g.","hi":"400 g तक के भारों के लिए दोहराएँ।","kn":"400 g ವರೆಗಿನ ಭಾರಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Plot T² against m and find k = 4π² ÷ slope.","hi":"T² और m का ग्राफ़ बनाएँ और k = 4π² ÷ प्रवणता ज्ञात करें।","kn":"T² ಮತ್ತು m ನಕ್ಷೆ ಎಳೆದು k = 4π² ÷ ಇಳಿಜಾರು ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Keep the amplitude small and the motion vertical.","hi":"आयाम छोटा और गति ऊर्ध्वाधर रखें।","kn":"ವಿಸ್ತಾರ ಸಣ್ಣದಾಗಿ, ಚಲನೆ ಲಂಬವಾಗಿರಲಿ."},{"en":"Time many oscillations, not one.","hi":"एक नहीं, कई दोलनों का समय लें।","kn":"ಒಂದಲ್ಲ, ಹಲವು ಆಂದೋಲನಗಳ ಸಮಯ ಅಳೆಯಿರಿ."},{"en":"Repeat each reading and take the mean.","hi":"हर पाठ्यांक दोहराएँ और माध्य लें।","kn":"ಪ್ರತಿ ಓದನ್ನು ಪುನರಾವರ್ತಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ."}],"conclusion":{"en":"T² increases linearly with the mass, and the slope gives the same spring constant as the static method.","hi":"T² द्रव्यमान के साथ रैखिक रूप से बढ़ता है, और प्रवणता से वही स्प्रिंग नियतांक मिलता है जो स्थैतिक विधि से।","kn":"T² ದ್ರವ್ಯರಾಶಿಯೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಹೆಚ್ಚುತ್ತದೆ; ಇಳಿಜಾರು ಸ್ಥಿರ ವಿಧಾನದಷ್ಟೇ ಸ್ಪ್ರಿಂಗ್ ಸ್ಥಿರಾಂಕ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Does T depend on the amplitude?","hi":"क्या T आयाम पर निर्भर करता है?","kn":"T ವಿಸ್ತಾರವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?"},"a":{"en":"No, not for simple harmonic motion.","hi":"नहीं, सरल आवर्त गति में नहीं।","kn":"ಇಲ್ಲ, ಸರಳ ಆವರ್ತ ಚಲನೆಯಲ್ಲಿ ಇಲ್ಲ."}},{"q":{"en":"How would T change on the Moon?","hi":"चंद्रमा पर T कैसे बदलेगा?","kn":"ಚಂದ್ರನ ಮೇಲೆ T ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?"},"a":{"en":"Not at all: T = 2π√(m/k) has no g in it.","hi":"बिल्कुल नहीं: T = 2π√(m/k) में g नहीं है।","kn":"ಒಂದಿಷ್ಟೂ ಇಲ್ಲ: T = 2π√(m/k) ಯಲ್ಲಿ g ಇಲ್ಲ."}},{"q":{"en":"If the mass is made four times, what happens to T?","hi":"द्रव्यमान चार गुना करने पर T का क्या होगा?","kn":"ದ್ರವ್ಯರಾಶಿಯನ್ನು ನಾಲ್ಕು ಪಟ್ಟು ಮಾಡಿದರೆ T ಏನಾಗುತ್ತದೆ?"},"a":{"en":"It doubles.","hi":"यह दोगुना हो जाता है।","kn":"ಅದು ಎರಡು ಪಟ್ಟಾಗುತ್ತದೆ."}}]},{"id":"inclined-plane","bench":"incline","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["inclined plane","laws of motion","force","component of weight","gravity"],"title":{"en":"Force along an inclined plane","hi":"आनत तल के अनुदिश बल","kn":"ಓರೆ ಸಮತಲದ ಉದ್ದಕ್ಕೂ ಬಲ"},"summary":{"en":"Hold a roller on a slope with a spring balance and see how the force changes with the angle.","hi":"ढलान पर एक रोलर को कमानीदार तुला से रोकें और देखें कि कोण के साथ बल कैसे बदलता है।","kn":"ಇಳಿಜಾರಿನ ಮೇಲೆ ರೋಲರನ್ನು ಸ್ಪ್ರಿಂಗ್ ತುಲಾ ಹಿಡಿದಿಡಿ, ಕೋನದೊಂದಿಗೆ ಬಲ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ ನೋಡಿ."},"aim":{"en":"To find the downward force along an inclined plane on a roller due to gravity and study its relation with the angle of inclination.","hi":"गुरुत्व के कारण आनत तल पर रोलर पर नीचे की ओर लगने वाला बल ज्ञात करना और झुकाव कोण से उसका संबंध देखना।","kn":"ಗುರುತ್ವದಿಂದ ಓರೆ ಸಮತಲದ ಮೇಲೆ ರೋಲರ್ ಮೇಲೆ ಇಳಿಜಾರಿನ ಉದ್ದಕ್ಕೂ ಕೆಳಮುಖ ಬಲ ಕಂಡುಹಿಡಿದು ಓರೆ ಕೋನದೊಂದಿಗೆ ಅದರ ಸಂಬಂಧ ಅಧ್ಯಯನ ಮಾಡುವುದು."},"principle":{"en":"The weight W of the roller has a component W sin θ along the plane and W cos θ into it. On a smooth plane the spring balance must pull up the slope with F = W sin θ, so F against sin θ is a straight line through the origin of slope W.","hi":"रोलर के भार W का एक घटक तल के अनुदिश W sin θ और तल में W cos θ होता है। चिकने तल पर कमानीदार तुला को ढलान पर ऊपर F = W sin θ से खींचना पड़ता है, इसलिए F और sin θ का ग्राफ़ मूल बिंदु से जाने वाली W प्रवणता की सीधी रेखा है।","kn":"ರೋಲರ್‌ನ ತೂಕ W ಗೆ ಸಮತಲದ ಉದ್ದಕ್ಕೂ W sin θ ಮತ್ತು ಒಳಗೆ W cos θ ಘಟಕಗಳಿವೆ. ನಯ ಸಮತಲದಲ್ಲಿ ಸ್ಪ್ರಿಂಗ್ ತುಲಾ ಇಳಿಜಾರಿನ ಮೇಲೆ F = W sin θ ದಿಂದ ಎಳೆಯಬೇಕು; ಆದ್ದರಿಂದ F ಮತ್ತು sin θ ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ W ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ."},"apparatus":[{"en":"Inclined plane with a protractor","hi":"चाँदा सहित आनत तल","kn":"ಕೋನಮಾಪಕ ಸಹಿತ ಓರೆ ಸಮತಲ"},{"en":"Roller (500 g)","hi":"रोलर (500 g)","kn":"ರೋಲರ್ (500 g)"},{"en":"Spring balance","hi":"कमानीदार तुला","kn":"ಸ್ಪ್ರಿಂಗ್ ತುಲಾ"},{"en":"Thread","hi":"धागा","kn":"ದಾರ"}],"steps":[{"en":"Weigh the roller with the spring balance.","hi":"कमानीदार तुला से रोलर का भार लें।","kn":"ಸ್ಪ್ರಿಂಗ್ ತುಲಾದಿಂದ ರೋಲರ್ ತೂಕ ಮಾಡಿ."},{"en":"Set the plane at 10° and hold the roller still with the balance parallel to the plane. Read F.","hi":"तल को 10° पर रखें और तुला को तल के समांतर रखकर रोलर को स्थिर रोकें। F पढ़ें।","kn":"ಸಮತಲವನ್ನು 10° ನಲ್ಲಿಡಿ, ತುಲಾವನ್ನು ಸಮತಲಕ್ಕೆ ಸಮಾಂತರವಾಗಿ ಹಿಡಿದು ರೋಲರನ್ನು ನಿಲ್ಲಿಸಿ. F ಓದಿ."},{"en":"Repeat for 20°, 30°, 40° and 50°.","hi":"20°, 30°, 40° और 50° के लिए दोहराएँ।","kn":"20°, 30°, 40° ಮತ್ತು 50° ಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Plot F against sin θ and compare the slope with the weight.","hi":"F और sin θ का ग्राफ़ बनाएँ और प्रवणता की तुलना भार से करें।","kn":"F ಮತ್ತು sin θ ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರನ್ನು ತೂಕದೊಂದಿಗೆ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Keep the thread and balance parallel to the plane.","hi":"धागा और तुला तल के समांतर रखें।","kn":"ದಾರ ಮತ್ತು ತುಲಾ ಸಮತಲಕ್ಕೆ ಸಮಾಂತರವಾಗಿರಲಿ."},{"en":"Use a roller with little friction.","hi":"कम घर्षण वाला रोलर लें।","kn":"ಕಡಿಮೆ ಘರ್ಷಣೆಯ ರೋಲರ್ ಬಳಸಿ."},{"en":"Check the zero error of every instrument before you start.","hi":"शुरू करने से पहले हर उपकरण की शून्य त्रुटि जाँचें।","kn":"ಆರಂಭಿಸುವ ಮೊದಲು ಪ್ರತಿ ಉಪಕರಣದ ಶೂನ್ಯ ದೋಷ ಪರಿಶೀಲಿಸಿ."}],"conclusion":{"en":"The force along the plane is W sin θ: it grows with the angle and the F–sin θ graph is a straight line through the origin.","hi":"तल के अनुदिश बल W sin θ है: यह कोण के साथ बढ़ता है और F–sin θ ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है।","kn":"ಸಮತಲದ ಉದ್ದಕ್ಕೂ ಬಲ W sin θ: ಕೋನದೊಂದಿಗೆ ಹೆಚ್ಚುತ್ತದೆ; F–sin θ ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ."},"viva":[{"q":{"en":"What is the force along the plane at 90°?","hi":"90° पर तल के अनुदिश बल कितना है?","kn":"90° ನಲ್ಲಿ ಸಮತಲದ ಉದ್ದಕ್ಕೂ ಬಲ ಎಷ್ಟು?"},"a":{"en":"The full weight W.","hi":"पूरा भार W.","kn":"ಪೂರ್ಣ ತೂಕ W."}},{"q":{"en":"Why are mountain roads made winding?","hi":"पहाड़ी सड़कें घुमावदार क्यों बनाई जाती हैं?","kn":"ಬೆಟ್ಟದ ರಸ್ತೆಗಳನ್ನು ಏಕೆ ಸುತ್ತುಬಳಸಿ ಮಾಡುತ್ತಾರೆ?"},"a":{"en":"A smaller slope means a smaller W sin θ to overcome.","hi":"कम ढलान का अर्थ है कम W sin θ पार करना।","kn":"ಕಡಿಮೆ ಇಳಿಜಾರು ಎಂದರೆ ಎದುರಿಸಬೇಕಾದ W sin θ ಕಡಿಮೆ."}},{"q":{"en":"What is the normal reaction on the plane?","hi":"तल पर अभिलंब प्रतिक्रिया कितनी है?","kn":"ಸಮತಲದ ಮೇಲಿನ ಲಂಬ ಪ್ರತಿಕ್ರಿಯೆ ಎಷ್ಟು?"},"a":{"en":"W cos θ, where θ is the angle of the incline.","hi":"W cos θ, जहाँ θ आनत तल का कोण है।","kn":"W cos θ, ಇಲ್ಲಿ θ ಓರೆ ಸಮತಲದ ಕೋನ."}}]},{"id":"limiting-friction","bench":"friction","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["friction","limiting friction","coefficient of friction","normal reaction","laws of motion"],"title":{"en":"Limiting friction and the coefficient of friction","hi":"सीमांत घर्षण और घर्षण गुणांक","kn":"ಮಿತಿ ಘರ್ಷಣೆ ಮತ್ತು ಘರ್ಷಣ ಗುಣಾಂಕ"},"summary":{"en":"Find the least pull that starts a block sliding for several normal forces; the slope is μ.","hi":"कई अभिलंब बलों के लिए वह न्यूनतम खिंचाव ज्ञात करें जिससे गुटका खिसकने लगे; प्रवणता μ है।","kn":"ಹಲವು ಲಂಬ ಬಲಗಳಿಗೆ ಬ್ಲಾಕ್ ಜಾರಲು ಆರಂಭಿಸುವ ಕನಿಷ್ಠ ಎಳೆತ ಕಂಡುಹಿಡಿಯಿರಿ; ಇಳಿಜಾರು μ."},"aim":{"en":"To study the relationship between the force of limiting friction and the normal reaction and to find the coefficient of friction between a block and a horizontal surface.","hi":"सीमांत घर्षण बल और अभिलंब प्रतिक्रिया के संबंध का अध्ययन करना और गुटके तथा क्षैतिज सतह के बीच घर्षण गुणांक ज्ञात करना।","kn":"ಮಿತಿ ಘರ್ಷಣ ಬಲ ಮತ್ತು ಲಂಬ ಪ್ರತಿಕ್ರಿಯೆಯ ಸಂಬಂಧ ಅಧ್ಯಯನ ಮಾಡಿ, ಬ್ಲಾಕ್ ಮತ್ತು ಸಮತಲ ಮೇಲ್ಮೈ ನಡುವಿನ ಘರ್ಷಣ ಗುಣಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Friction opposes the start of sliding up to a maximum, the limiting friction F, which is proportional to the normal reaction N: F = μN. The slope of F against N is the coefficient of static friction μ, which depends on the two surfaces.","hi":"घर्षण खिसकने की शुरुआत का एक अधिकतम मान तक विरोध करता है, यह सीमांत घर्षण F है, जो अभिलंब प्रतिक्रिया N के अनुक्रमानुपाती है: F = μN. F और N की प्रवणता स्थैतिक घर्षण गुणांक μ है, जो दोनों सतहों पर निर्भर करता है।","kn":"ಘರ್ಷಣೆ ಜಾರುವಿಕೆಯ ಆರಂಭವನ್ನು ಒಂದು ಗರಿಷ್ಠದವರೆಗೆ ವಿರೋಧಿಸುತ್ತದೆ; ಅದು ಮಿತಿ ಘರ್ಷಣೆ F, ಲಂಬ ಪ್ರತಿಕ್ರಿಯೆ N ಗೆ ಅನುಪಾತೀಯ: F = μN. F ಮತ್ತು N ಇಳಿಜಾರು ಸ್ಥಿರ ಘರ್ಷಣ ಗುಣಾಂಕ μ; ಅದು ಎರಡು ಮೇಲ್ಮೈಗಳನ್ನು ಅವಲಂಬಿಸಿದೆ."},"apparatus":[{"en":"Wooden block with a hook","hi":"हुक सहित लकड़ी का गुटका","kn":"ಕೊಕ್ಕೆ ಸಹಿತ ಮರದ ಬ್ಲಾಕ್"},{"en":"Horizontal board with a pulley","hi":"घिरनी सहित क्षैतिज तख़्ता","kn":"ರಾಟೆ ಸಹಿತ ಸಮತಲ ಹಲಗೆ"},{"en":"Scale pan and weights","hi":"पलड़ा और बाट","kn":"ತಟ್ಟೆ ಮತ್ತು ತೂಕಗಳು"},{"en":"Spirit level and thread","hi":"स्पिरिट लेवल और धागा","kn":"ಸ್ಪಿರಿಟ್ ಲೆವೆಲ್ ಮತ್ತು ದಾರ"}],"steps":[{"en":"Level the board. Tie the block to the pan over the pulley.","hi":"तख़्ते को समतल करें। गुटके को घिरनी के ऊपर से पलड़े से बाँधें।","kn":"ಹಲಗೆಯನ್ನು ಸಮತಲಗೊಳಿಸಿ. ಬ್ಲಾಕನ್ನು ರಾಟೆಯ ಮೇಲಿಂದ ತಟ್ಟೆಗೆ ಕಟ್ಟಿ."},{"en":"Add small weights to the pan until the block just starts to slide when tapped. Pan + weights gives F.","hi":"पलड़े में छोटे बाट तब तक डालें जब तक थपथपाने पर गुटका बस खिसकने न लगे। पलड़ा + बाट से F मिलता है।","kn":"ತಟ್ಟಿದಾಗ ಬ್ಲಾಕ್ ಕೇವಲ ಜಾರಲು ಆರಂಭಿಸುವವರೆಗೆ ತಟ್ಟೆಗೆ ಸಣ್ಣ ತೂಕ ಸೇರಿಸಿ. ತಟ್ಟೆ + ತೂಕ F ನೀಡುತ್ತದೆ."},{"en":"Put masses on the block to change N and repeat.","hi":"N बदलने के लिए गुटके पर द्रव्यमान रखें और दोहराएँ।","kn":"N ಬದಲಿಸಲು ಬ್ಲಾಕ್ ಮೇಲೆ ದ್ರವ್ಯರಾಶಿ ಇಟ್ಟು ಪುನರಾವರ್ತಿಸಿ."},{"en":"Plot F against N and find μ from the slope; compare different surfaces.","hi":"F और N का ग्राफ़ बनाकर प्रवणता से μ ज्ञात करें; विभिन्न सतहों की तुलना करें।","kn":"F ಮತ್ತು N ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರಿನಿಂದ μ ಕಂಡುಹಿಡಿಯಿರಿ; ಬೇರೆ ಮೇಲ್ಮೈಗಳನ್ನು ಹೋಲಿಸಿ."}],"precautions":[{"en":"Keep the thread horizontal and the pulley frictionless.","hi":"धागा क्षैतिज और घिरनी घर्षणरहित रखें।","kn":"ದಾರ ಸಮತಲ, ರಾಟೆ ಘರ್ಷಣೆರಹಿತವಾಗಿರಲಿ."},{"en":"Add weights in small steps near the point of sliding.","hi":"खिसकने के बिंदु के पास छोटे चरणों में बाट डालें।","kn":"ಜಾರುವ ಬಿಂದುವಿನ ಹತ್ತಿರ ಸಣ್ಣ ಹಂತಗಳಲ್ಲಿ ತೂಕ ಸೇರಿಸಿ."},{"en":"Keep the surfaces clean and dry.","hi":"सतहें साफ़ और सूखी रखें।","kn":"ಮೇಲ್ಮೈಗಳು ಸ್ವಚ್ಛ ಮತ್ತು ಒಣಗಿರಲಿ."}],"conclusion":{"en":"Limiting friction is directly proportional to the normal reaction; the coefficient of friction is constant for a pair of surfaces and differs between surfaces.","hi":"सीमांत घर्षण अभिलंब प्रतिक्रिया के अनुक्रमानुपाती है; घर्षण गुणांक दो सतहों के युग्म के लिए नियत है और अलग सतहों के लिए भिन्न।","kn":"ಮಿತಿ ಘರ್ಷಣೆ ಲಂಬ ಪ್ರತಿಕ್ರಿಯೆಗೆ ನೇರ ಅನುಪಾತೀಯ; ಘರ್ಷಣ ಗುಣಾಂಕ ಒಂದು ಮೇಲ್ಮೈ ಜೋಡಿಗೆ ಸ್ಥಿರ, ಬೇರೆ ಮೇಲ್ಮೈಗಳಿಗೆ ಭಿನ್ನ."},"viva":[{"q":{"en":"Does limiting friction depend on the area of contact?","hi":"क्या सीमांत घर्षण संपर्क क्षेत्रफल पर निर्भर करता है?","kn":"ಮಿತಿ ಘರ್ಷಣೆ ಸಂಪರ್ಕ ವಿಸ್ತೀರ್ಣವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?"},"a":{"en":"No (to a good approximation).","hi":"नहीं (अच्छे सन्निकटन तक)।","kn":"ಇಲ್ಲ (ಉತ್ತಮ ಅಂದಾಜಿಗೆ)."}},{"q":{"en":"Which is larger, static or kinetic friction?","hi":"स्थैतिक या गतिज घर्षण, कौन बड़ा है?","kn":"ಸ್ಥಿರ ಅಥವಾ ಚಲನ ಘರ್ಷಣೆ, ಯಾವುದು ದೊಡ್ಡದು?"},"a":{"en":"Limiting static friction is slightly larger.","hi":"सीमांत स्थैतिक घर्षण थोड़ा बड़ा है।","kn":"ಮಿತಿ ಸ್ಥಿರ ಘರ್ಷಣೆ ಸ್ವಲ್ಪ ದೊಡ್ಡದು."}},{"q":{"en":"Why is the block tapped gently?","hi":"गुटके को हल्के से क्यों थपथपाते हैं?","kn":"ಬ್ಲಾಕನ್ನು ಏಕೆ ಮೃದುವಾಗಿ ತಟ್ಟುತ್ತಾರೆ?"},"a":{"en":"To start it when the pull just equals limiting friction, so the reading is not too high.","hi":"ताकि खिंचाव सीमांत घर्षण के बराबर होते ही वह चल पड़े, और पाठ्यांक अधिक न आए।","kn":"ಎಳೆತ ಮಿತಿ ಘರ್ಷಣೆಗೆ ಸಮವಾದಾಗಲೇ ಅದು ಚಲಿಸಲು, ಓದು ಹೆಚ್ಚು ಬರದಂತೆ."}}]},{"id":"projectile-motion","bench":"projectile","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"explore","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["projectile","projectile motion","motion in a plane","range","trajectory"],"title":{"en":"Projectile motion","hi":"प्रक्षेप्य गति","kn":"ಉತ್ಕ್ಷೇಪಕ ಚಲನೆ"},"summary":{"en":"Launch a ball at different speeds and angles and find which angle goes farthest.","hi":"गेंद को अलग-अलग चाल और कोणों पर फेंकें और पता लगाएँ कि कौन-सा कोण सबसे दूर जाता है।","kn":"ಚೆಂಡನ್ನು ಬೇರೆ ಬೇರೆ ವೇಗ ಮತ್ತು ಕೋನಗಳಲ್ಲಿ ಎಸೆದು ಯಾವ ಕೋನ ಅತಿ ದೂರ ಹೋಗುತ್ತದೆ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To study how the range, height and time of flight of a projectile depend on its speed and angle of launch.","hi":"यह अध्ययन करना कि प्रक्षेप्य की परास, ऊँचाई और उड़ान काल उसकी चाल और प्रक्षेपण कोण पर कैसे निर्भर करते हैं।","kn":"ಉತ್ಕ್ಷೇಪಕದ ವ್ಯಾಪ್ತಿ, ಎತ್ತರ ಮತ್ತು ಹಾರಾಟ ಸಮಯ ಅದರ ವೇಗ ಮತ್ತು ಉಡಾವಣಾ ಕೋನವನ್ನು ಹೇಗೆ ಅವಲಂಬಿಸಿವೆ ಎಂದು ಅಧ್ಯಯನ ಮಾಡುವುದು."},"principle":{"en":"Without air resistance the horizontal velocity stays constant and the vertical motion has acceleration g. From the ground: time T = 2u sin θ / g, greatest height H = u² sin² θ / 2g, range R = u² sin 2θ / g, largest at 45°; complementary angles give the same range.","hi":"वायु प्रतिरोध के बिना क्षैतिज वेग नियत रहता है और ऊर्ध्वाधर गति में त्वरण g होता है। भूमि से: समय T = 2u sin θ / g, अधिकतम ऊँचाई H = u² sin² θ / 2g, परास R = u² sin 2θ / g, जो 45° पर सबसे अधिक है; पूरक कोण समान परास देते हैं।","kn":"ಗಾಳಿಯ ಪ್ರತಿರೋಧವಿಲ್ಲದಿದ್ದರೆ ಸಮತಲ ವೇಗ ಸ್ಥಿರ, ಲಂಬ ಚಲನೆಗೆ ವೇಗೋತ್ಕರ್ಷ g. ನೆಲದಿಂದ: ಸಮಯ T = 2u sin θ / g, ಗರಿಷ್ಠ ಎತ್ತರ H = u² sin² θ / 2g, ವ್ಯಾಪ್ತಿ R = u² sin 2θ / g, 45° ನಲ್ಲಿ ಗರಿಷ್ಠ; ಪೂರಕ ಕೋನಗಳು ಒಂದೇ ವ್ಯಾಪ್ತಿ ನೀಡುತ್ತವೆ."},"apparatus":[{"en":"Projectile launcher with angle scale","hi":"कोण पैमाने सहित प्रक्षेप्य प्रक्षेपक","kn":"ಕೋನ ಅಳತೆ ಸಹಿತ ಉತ್ಕ್ಷೇಪಕ ಉಡಾವಕ"},{"en":"Ball","hi":"गेंद","kn":"ಚೆಂಡು"},{"en":"Measuring tape","hi":"मापक फ़ीता","kn":"ಅಳತೆ ಪಟ್ಟಿ"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"}],"steps":[{"en":"Set a speed and launch at 30°; note the range, height and time.","hi":"एक चाल तय करके 30° पर प्रक्षेपित करें; परास, ऊँचाई और समय लिखें।","kn":"ಒಂದು ವೇಗ ಹೊಂದಿಸಿ 30° ಯಲ್ಲಿ ಉಡಾಯಿಸಿ; ವ್ಯಾಪ್ತಿ, ಎತ್ತರ ಮತ್ತು ಸಮಯ ಬರೆಯಿರಿ."},{"en":"Repeat at 45° and 60° with the same speed.","hi":"उसी चाल से 45° और 60° पर दोहराएँ।","kn":"ಅದೇ ವೇಗದಲ್ಲಿ 45° ಮತ್ತು 60° ಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Try other angles and find the one with the largest range.","hi":"दूसरे कोण आज़माएँ और सबसे अधिक परास वाला कोण ढूँढें।","kn":"ಬೇರೆ ಕೋನಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ ಗರಿಷ್ಠ ವ್ಯಾಪ್ತಿಯ ಕೋನ ಹುಡುಕಿ."},{"en":"Launch from a height and on the Moon, and explain the differences.","hi":"ऊँचाई से और चंद्रमा पर प्रक्षेपित करें, और अंतर समझाएँ।","kn":"ಎತ್ತರದಿಂದ ಮತ್ತು ಚಂದ್ರನ ಮೇಲೆ ಉಡಾಯಿಸಿ, ವ್ಯತ್ಯಾಸ ವಿವರಿಸಿ."}],"precautions":[{"en":"Change one thing at a time.","hi":"एक बार में एक ही चीज़ बदलें।","kn":"ಒಮ್ಮೆಗೆ ಒಂದೇ ಅಂಶ ಬದಲಿಸಿ."},{"en":"In a real launcher, never aim at people.","hi":"असली प्रक्षेपक में कभी लोगों की ओर निशाना न लगाएँ।","kn":"ನಿಜವಾದ ಉಡಾವಕದಲ್ಲಿ ಎಂದೂ ಜನರತ್ತ ಗುರಿ ಇಡಬೇಡಿ."}],"conclusion":{"en":"From level ground the range is largest at 45°, complementary angles give equal ranges, and the path is a parabola.","hi":"समतल भूमि से परास 45° पर सबसे अधिक होती है, पूरक कोण समान परास देते हैं, और पथ परवलय है।","kn":"ಸಮ ನೆಲದಿಂದ ವ್ಯಾಪ್ತಿ 45° ನಲ್ಲಿ ಗರಿಷ್ಠ; ಪೂರಕ ಕೋನಗಳು ಸಮ ವ್ಯಾಪ್ತಿ ನೀಡುತ್ತವೆ; ಪಥ ಪರವಲಯ."},"viva":[{"q":{"en":"What is the velocity at the top of the path?","hi":"पथ के शीर्ष पर वेग कितना होता है?","kn":"ಪಥದ ತುದಿಯಲ್ಲಿ ವೇಗ ಎಷ್ಟು?"},"a":{"en":"Only the horizontal part, u cos θ.","hi":"केवल क्षैतिज भाग, u cos θ.","kn":"ಸಮತಲ ಭಾಗ ಮಾತ್ರ, u cos θ."}},{"q":{"en":"How does air resistance change the best angle?","hi":"वायु प्रतिरोध सर्वोत्तम कोण को कैसे बदलता है?","kn":"ಗಾಳಿಯ ಪ್ರತಿರೋಧ ಉತ್ತಮ ಕೋನವನ್ನು ಹೇಗೆ ಬದಲಿಸುತ್ತದೆ?"},"a":{"en":"It makes it a little less than 45°.","hi":"यह उसे 45° से थोड़ा कम कर देता है।","kn":"ಅದು 45° ಗಿಂತ ಸ್ವಲ್ಪ ಕಡಿಮೆಯಾಗುತ್ತದೆ."}},{"q":{"en":"Which two angles give the same range as 20°?","hi":"20° जितनी परास और कौन-सा कोण देता है?","kn":"20° ಯಷ್ಟೇ ವ್ಯಾಪ್ತಿಯನ್ನು ಇನ್ನಾವ ಕೋನ ನೀಡುತ್ತದೆ?"},"a":{"en":"70°.","hi":"70°.","kn":"70°."}}]},{"id":"collisions-momentum","bench":"collision","setup":{},"subject":"Physics","domain":"physics","levels":["11","ug"],"mode":"explore","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["collision","collisions","momentum","conservation of momentum","elastic collision","inelastic collision","work energy and power"],"title":{"en":"Collisions and conservation of momentum","hi":"संघट्ट और संवेग संरक्षण","kn":"ಘರ್ಷಣೆಗಳು ಮತ್ತು ಸಂವೇಗ ಸಂರಕ್ಷಣೆ"},"summary":{"en":"Crash two carts on an air track and compare momentum and kinetic energy before and after.","hi":"वायु पथ पर दो गाड़ियों को टकराएँ और पहले तथा बाद के संवेग और गतिज ऊर्जा की तुलना करें।","kn":"ಗಾಳಿ ಹಾದಿಯಲ್ಲಿ ಎರಡು ಗಾಡಿಗಳನ್ನು ಢಿಕ್ಕಿಪಡಿಸಿ, ಮೊದಲು ಮತ್ತು ನಂತರದ ಸಂವೇಗ ಮತ್ತು ಚಲನ ಶಕ್ತಿಯನ್ನು ಹೋಲಿಸಿ."},"aim":{"en":"To verify the conservation of momentum in elastic and inelastic collisions and compare the kinetic energy before and after.","hi":"प्रत्यास्थ और अप्रत्यास्थ संघट्टों में संवेग संरक्षण का सत्यापन करना और पहले तथा बाद की गतिज ऊर्जा की तुलना करना।","kn":"ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮತ್ತು ಅಸ್ಥಿತಿಸ್ಥಾಪಕ ಘರ್ಷಣೆಗಳಲ್ಲಿ ಸಂವೇಗ ಸಂರಕ್ಷಣೆ ಪರಿಶೀಲಿಸಿ ಮೊದಲು ಮತ್ತು ನಂತರದ ಚಲನ ಶಕ್ತಿಯನ್ನು ಹೋಲಿಸುವುದು."},"principle":{"en":"With no outside force, total momentum m₁u₁ + m₂u₂ stays the same in every collision. Kinetic energy is also conserved only in an elastic collision (e = 1); when the carts stick (e = 0) the most energy turns into heat and sound.","hi":"बाहरी बल न होने पर कुल संवेग m₁u₁ + m₂u₂ हर संघट्ट में वही रहता है। गतिज ऊर्जा केवल प्रत्यास्थ संघट्ट (e = 1) में संरक्षित रहती है; गाड़ियाँ चिपक जाएँ (e = 0) तो सबसे अधिक ऊर्जा ऊष्मा और ध्वनि बन जाती है।","kn":"ಹೊರಗಿನ ಬಲವಿಲ್ಲದಿದ್ದರೆ ಒಟ್ಟು ಸಂವೇಗ m₁u₁ + m₂u₂ ಪ್ರತಿ ಘರ್ಷಣೆಯಲ್ಲೂ ಒಂದೇ. ಚಲನ ಶಕ್ತಿ ಸ್ಥಿತಿಸ್ಥಾಪಕ ಘರ್ಷಣೆಯಲ್ಲಿ (e = 1) ಮಾತ್ರ ಸಂರಕ್ಷಿತ; ಗಾಡಿಗಳು ಅಂಟಿಕೊಂಡರೆ (e = 0) ಅತಿ ಹೆಚ್ಚು ಶಕ್ತಿ ಉಷ್ಣ ಮತ್ತು ಧ್ವನಿಯಾಗುತ್ತದೆ."},"apparatus":[{"en":"Air track with blower","hi":"ब्लोअर सहित वायु पथ","kn":"ಊದುಕ ಸಹಿತ ಗಾಳಿ ಹಾದಿ"},{"en":"Two gliders with spring or putty bumpers","hi":"स्प्रिंग या पुट्टी बंपर वाली दो गाड़ियाँ","kn":"ಸ್ಪ್ರಿಂಗ್ ಅಥವಾ ಪುಟ್ಟಿ ಬಂಪರ್‌ಗಳ ಎರಡು ಗಾಡಿಗಳು"},{"en":"Photogates and timer","hi":"फ़ोटोगेट और टाइमर","kn":"ಫೋಟೋಗೇಟ್ ಮತ್ತು ಟೈಮರ್"},{"en":"Extra masses","hi":"अतिरिक्त द्रव्यमान","kn":"ಹೆಚ್ಚುವರಿ ದ್ರವ್ಯರಾಶಿಗಳು"}],"steps":[{"en":"Choose the masses and set cart 2 at rest in the middle.","hi":"द्रव्यमान चुनें और गाड़ी 2 को बीच में स्थिर रखें।","kn":"ದ್ರವ್ಯರಾಶಿಗಳನ್ನು ಆರಿಸಿ ಗಾಡಿ 2 ಅನ್ನು ಮಧ್ಯದಲ್ಲಿ ನಿಶ್ಚಲವಾಗಿಡಿ."},{"en":"Push cart 1 into it with spring bumpers (elastic); record the velocities before and after.","hi":"स्प्रिंग बंपर (प्रत्यास्थ) के साथ गाड़ी 1 को उससे टकराएँ; पहले और बाद के वेग लिखें।","kn":"ಸ್ಪ್ರಿಂಗ್ ಬಂಪರ್‌ಗಳೊಂದಿಗೆ (ಸ್ಥಿತಿಸ್ಥಾಪಕ) ಗಾಡಿ 1 ಅನ್ನು ಅದಕ್ಕೆ ಢಿಕ್ಕಿಹೊಡೆಸಿ; ಮೊದಲು ಮತ್ತು ನಂತರದ ವೇಗಗಳನ್ನು ದಾಖಲಿಸಿ."},{"en":"Repeat with putty (the carts stick) and with partly elastic bumpers.","hi":"पुट्टी (गाड़ियाँ चिपकती हैं) और आंशिक प्रत्यास्थ बंपरों के साथ दोहराएँ।","kn":"ಪುಟ್ಟಿ (ಗಾಡಿಗಳು ಅಂಟುತ್ತವೆ) ಮತ್ತು ಭಾಗಶಃ ಸ್ಥಿತಿಸ್ಥಾಪಕ ಬಂಪರ್‌ಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Compare total momentum and kinetic energy before and after each collision.","hi":"हर संघट्ट से पहले और बाद के कुल संवेग तथा गतिज ऊर्जा की तुलना करें।","kn":"ಪ್ರತಿ ಘರ್ಷಣೆಯ ಮೊದಲು ಮತ್ತು ನಂತರದ ಒಟ್ಟು ಸಂವೇಗ ಮತ್ತು ಚಲನ ಶಕ್ತಿ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Level the air track so the carts move at steady speed.","hi":"वायु पथ समतल करें ताकि गाड़ियाँ स्थिर चाल से चलें।","kn":"ಗಾಡಿಗಳು ಸ್ಥಿರ ವೇಗದಲ್ಲಿ ಚಲಿಸುವಂತೆ ಗಾಳಿ ಹಾದಿ ಸಮತಲಗೊಳಿಸಿ."},{"en":"Take velocities just before and just after the collision.","hi":"वेग संघट्ट से ठीक पहले और ठीक बाद लें।","kn":"ವೇಗಗಳನ್ನು ಘರ್ಷಣೆಯ ಸ್ವಲ್ಪ ಮೊದಲು ಮತ್ತು ಸ್ವಲ್ಪ ನಂತರ ತೆಗೆದುಕೊಳ್ಳಿ."}],"conclusion":{"en":"Momentum is conserved in every collision; kinetic energy is conserved only in the elastic one and the most is lost when the carts stick together.","hi":"संवेग हर संघट्ट में संरक्षित है; गतिज ऊर्जा केवल प्रत्यास्थ में संरक्षित है और गाड़ियाँ चिपकने पर सबसे अधिक नष्ट होती है।","kn":"ಸಂವೇಗ ಪ್ರತಿ ಘರ್ಷಣೆಯಲ್ಲೂ ಸಂರಕ್ಷಿತ; ಚಲನ ಶಕ್ತಿ ಸ್ಥಿತಿಸ್ಥಾಪಕದಲ್ಲಿ ಮಾತ್ರ; ಗಾಡಿಗಳು ಅಂಟಿದಾಗ ಅತಿ ಹೆಚ್ಚು ನಷ್ಟ."},"viva":[{"q":{"en":"What happens when equal masses collide elastically and one is at rest?","hi":"समान द्रव्यमान प्रत्यास्थ रूप से टकराएँ और एक स्थिर हो तो क्या होता है?","kn":"ಸಮ ದ್ರವ್ಯರಾಶಿಗಳು ಸ್ಥಿತಿಸ್ಥಾಪಕವಾಗಿ ಢಿಕ್ಕಿಯಾಗಿ ಒಂದು ನಿಶ್ಚಲವಾಗಿದ್ದರೆ ಏನಾಗುತ್ತದೆ?"},"a":{"en":"They exchange velocities: the first stops, the second moves off.","hi":"वे वेग बदल लेते हैं: पहली रुक जाती है, दूसरी चल पड़ती है।","kn":"ಅವು ವೇಗ ವಿನಿಮಯ ಮಾಡಿಕೊಳ್ಳುತ್ತವೆ: ಮೊದಲನೆಯದು ನಿಲ್ಲುತ್ತದೆ, ಎರಡನೆಯದು ಚಲಿಸುತ್ತದೆ."}},{"q":{"en":"What is the coefficient of restitution?","hi":"प्रत्यावस्थान गुणांक क्या है?","kn":"ಪುನಃಸ್ಥಾಪನ ಗುಣಾಂಕ ಎಂದರೇನು?"},"a":{"en":"Speed of separation ÷ speed of approach.","hi":"पृथक्करण चाल ÷ उपगमन चाल।","kn":"ಬೇರ್ಪಡುವ ವೇಗ ÷ ಸಮೀಪಿಸುವ ವೇಗ."}},{"q":{"en":"Where does the lost kinetic energy go?","hi":"नष्ट गतिज ऊर्जा कहाँ जाती है?","kn":"ನಷ್ಟವಾದ ಚಲನ ಶಕ್ತಿ ಎಲ್ಲಿಗೆ ಹೋಗುತ್ತದೆ?"},"a":{"en":"Into heat, sound and deformation.","hi":"ऊष्मा, ध्वनि और विरूपण में।","kn":"ಉಷ್ಣ, ಧ್ವನಿ ಮತ್ತು ವಿರೂಪಣೆಗೆ."}}]},{"id":"youngs-modulus","bench":"searle","setup":{},"subject":"Physics","domain":"physics","levels":["11","ug"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["young's modulus","elasticity","searle","stress","strain","mechanical properties of solids"],"title":{"en":"Young's modulus of a wire (Searle's method)","hi":"तार का यंग प्रत्यास्थता गुणांक (सर्ल विधि)","kn":"ತಂತಿಯ ಯಂಗ್ ಗುಣಾಂಕ (ಸರ್ಲ್ ವಿಧಾನ)"},"summary":{"en":"Load a long wire, read the extension with a micrometer, and get Y from the load–extension slope.","hi":"लंबे तार पर भार डालें, माइक्रोमीटर से विस्तार पढ़ें, और भार–विस्तार प्रवणता से Y निकालें।","kn":"ಉದ್ದ ತಂತಿಗೆ ಭಾರ ಹಾಕಿ, ಮೈಕ್ರೋಮೀಟರ್‌ನಿಂದ ವಿಸ್ತರಣೆ ಓದಿ, ಭಾರ–ವಿಸ್ತರಣೆ ಇಳಿಜಾರಿನಿಂದ Y ಪಡೆಯಿರಿ."},"aim":{"en":"To find Young's modulus of the material of a wire by Searle's method.","hi":"सर्ल विधि से तार के पदार्थ का यंग प्रत्यास्थता गुणांक ज्ञात करना।","kn":"ಸರ್ಲ್ ವಿಧಾನದಿಂದ ತಂತಿಯ ವಸ್ತುವಿನ ಯಂಗ್ ಗುಣಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Young’s modulus Y = stress ÷ strain = (F/A) ÷ (ΔL/L), so ΔL = FL/(AY). A reference wire beside the test wire cancels sagging of the support and changes of temperature. The slope of ΔL against the load m gives Y = gL ÷ (πr² × slope).","hi":"यंग गुणांक Y = प्रतिबल ÷ विकृति = (F/A) ÷ (ΔL/L), अतः ΔL = FL/(AY). परीक्षण तार के पास का संदर्भ तार आधार के झुकने और ताप के बदलाव का प्रभाव मिटा देता है। ΔL और भार m की प्रवणता से Y = gL ÷ (πr² × प्रवणता) मिलता है।","kn":"ಯಂಗ್ ಗುಣಾಂಕ Y = ಒತ್ತಡ ÷ ವಿಕಾರ = (F/A) ÷ (ΔL/L), ಆದ್ದರಿಂದ ΔL = FL/(AY). ಪರೀಕ್ಷಾ ತಂತಿಯ ಪಕ್ಕದ ಉಲ್ಲೇಖ ತಂತಿ ಆಧಾರದ ಬಾಗುವಿಕೆ ಮತ್ತು ತಾಪ ಬದಲಾವಣೆಯ ಪರಿಣಾಮ ರದ್ದುಗೊಳಿಸುತ್ತದೆ. ΔL ಮತ್ತು ಭಾರ m ಇಳಿಜಾರಿನಿಂದ Y = gL ÷ (πr² × ಇಳಿಜಾರು)."},"apparatus":[{"en":"Searle's apparatus with two identical wires","hi":"दो समान तारों सहित सर्ल उपकरण","kn":"ಎರಡು ಸಮಾನ ತಂತಿಗಳ ಸರ್ಲ್ ಉಪಕರಣ"},{"en":"Micrometer screw and spirit level","hi":"माइक्रोमीटर पेंच और स्पिरिट लेवल","kn":"ಮೈಕ್ರೋಮೀಟರ್ ತಿರುಪು ಮತ್ತು ಸ್ಪಿರಿಟ್ ಲೆವೆಲ್"},{"en":"Slotted 0.5 kg weights","hi":"खाँचेदार 0.5 kg बाट","kn":"ಸೀಳು 0.5 kg ತೂಕಗಳು"},{"en":"Screw gauge and metre scale","hi":"पेंच गेज और मीटर पैमाना","kn":"ಸ್ಕ್ರೂ ಗೇಜ್ ಮತ್ತು ಮೀಟರ್ ಅಳತೆಪಟ್ಟಿ"}],"steps":[{"en":"Measure the length L and the diameter of the wire (in several places with the screw gauge).","hi":"तार की लंबाई L और व्यास मापें (पेंच गेज से कई स्थानों पर)।","kn":"ತಂತಿಯ ಉದ್ದ L ಮತ್ತು ವ್ಯಾಸ ಅಳೆಯಿರಿ (ಸ್ಕ್ರೂ ಗೇಜ್‌ನಿಂದ ಹಲವು ಸ್ಥಳಗಳಲ್ಲಿ)."},{"en":"With a dead load on both wires, level the spirit level with the micrometer and read it.","hi":"दोनों तारों पर आरंभिक भार रखकर माइक्रोमीटर से स्पिरिट लेवल समतल करें और पढ़ें।","kn":"ಎರಡೂ ತಂತಿಗಳ ಮೇಲೆ ಆರಂಭಿಕ ಭಾರವಿಟ್ಟು ಮೈಕ್ರೋಮೀಟರ್‌ನಿಂದ ಸ್ಪಿರಿಟ್ ಲೆವೆಲ್ ಸಮತಲಗೊಳಿಸಿ ಓದಿ."},{"en":"Add 0.5 kg to the test wire, wait a minute, relevel and read. Continue up to 5 kg, then unload in steps.","hi":"परीक्षण तार पर 0.5 kg जोड़ें, एक मिनट रुकें, फिर समतल करके पढ़ें। 5 kg तक जारी रखें, फिर चरणों में भार हटाएँ।","kn":"ಪರೀಕ್ಷಾ ತಂತಿಗೆ 0.5 kg ಸೇರಿಸಿ, ಒಂದು ನಿಮಿಷ ಕಾದು, ಮತ್ತೆ ಸಮತಲಗೊಳಿಸಿ ಓದಿ. 5 kg ವರೆಗೆ ಮುಂದುವರಿಸಿ, ನಂತರ ಹಂತಗಳಲ್ಲಿ ಭಾರ ಇಳಿಸಿ."},{"en":"Plot extension against load and find the slope.","hi":"विस्तार और भार का ग्राफ़ बनाकर प्रवणता ज्ञात करें।","kn":"ವಿಸ್ತರಣೆ ಮತ್ತು ಭಾರ ನಕ್ಷೆ ಎಳೆದು ಇಳಿಜಾರು ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Work out Y = gL ÷ (πr² × slope) with its uncertainty.","hi":"Y = gL ÷ (πr² × प्रवणता) उसकी अनिश्चितता सहित निकालें।","kn":"Y = gL ÷ (πr² × ಇಳಿಜಾರು) ಅನಿಶ್ಚಿತತೆ ಸಹಿತ ಲೆಕ್ಕಿಸಿ."},{"en":"Export the readings as CSV and work out the uncertainty from the fit.","hi":"पाठ्यांक CSV में निर्यात करें और फ़िट से अनिश्चितता निकालें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Keep the load well within the elastic limit.","hi":"भार प्रत्यास्थता सीमा के काफ़ी भीतर रखें।","kn":"ಭಾರ ಸ್ಥಿತಿಸ್ಥಾಪಕ ಮಿತಿಯೊಳಗೆ ಚೆನ್ನಾಗಿ ಇರಲಿ."},{"en":"Wait after each load change so the wire settles.","hi":"हर भार परिवर्तन के बाद प्रतीक्षा करें ताकि तार स्थिर हो जाए।","kn":"ಪ್ರತಿ ಭಾರ ಬದಲಾವಣೆಯ ನಂತರ ತಂತಿ ಸ್ಥಿರವಾಗುವವರೆಗೆ ಕಾಯಿರಿ."},{"en":"Measure the diameter carefully: it enters squared.","hi":"व्यास ध्यान से मापें: यह वर्ग के रूप में आता है।","kn":"ವ್ಯಾಸವನ್ನು ಎಚ್ಚರದಿಂದ ಅಳೆಯಿರಿ: ಅದು ವರ್ಗವಾಗಿ ಬರುತ್ತದೆ."}],"conclusion":{"en":"Extension is proportional to load, and the slope gives Young's modulus of the wire close to the table value (about 2 × 10¹¹ Pa for steel).","hi":"विस्तार भार के अनुक्रमानुपाती है, और प्रवणता से तार का यंग गुणांक सारणी मान (स्टील के लिए लगभग 2 × 10¹¹ Pa) के निकट मिलता है।","kn":"ವಿಸ್ತರಣೆ ಭಾರಕ್ಕೆ ಅನುಪಾತೀಯ; ಇಳಿಜಾರು ತಂತಿಯ ಯಂಗ್ ಗುಣಾಂಕವನ್ನು ಕೋಷ್ಟಕ ಮೌಲ್ಯದ ಹತ್ತಿರ (ಉಕ್ಕಿಗೆ ಸುಮಾರು 2 × 10¹¹ Pa) ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why is a reference wire used?","hi":"संदर्भ तार क्यों प्रयोग होता है?","kn":"ಉಲ್ಲೇಖ ತಂತಿಯನ್ನು ಏಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"It cancels the yielding of the support and expansion with temperature.","hi":"यह आधार के झुकने और ताप से प्रसार के प्रभाव को निरस्त करता है।","kn":"ಅದು ಆಧಾರದ ಬಾಗುವಿಕೆ ಮತ್ತು ತಾಪದಿಂದ ವಿಸ್ತರಣೆಯ ಪರಿಣಾಮವನ್ನು ರದ್ದುಗೊಳಿಸುತ್ತದೆ."}},{"q":{"en":"Does Y depend on the length of the wire?","hi":"क्या Y तार की लंबाई पर निर्भर करता है?","kn":"Y ತಂತಿಯ ಉದ್ದವನ್ನು ಅವಲಂಬಿಸುತ್ತದೆಯೇ?"},"a":{"en":"No; it is a property of the material.","hi":"नहीं; यह पदार्थ का गुण है।","kn":"ಇಲ್ಲ; ಅದು ವಸ್ತುವಿನ ಗುಣ."}},{"q":{"en":"Which is more elastic, rubber or steel?","hi":"रबर और स्टील में कौन अधिक प्रत्यास्थ है?","kn":"ರಬ್ಬರ್ ಮತ್ತು ಉಕ್ಕಿನಲ್ಲಿ ಯಾವುದು ಹೆಚ್ಚು ಸ್ಥಿತಿಸ್ಥಾಪಕ?"},"a":{"en":"Steel: it has the larger Young’s modulus.","hi":"स्टील: इसका यंग गुणांक अधिक है।","kn":"ಉಕ್ಕು: ಅದರ ಯಂಗ್ ಗುಣಾಂಕ ಹೆಚ್ಚು."}}]},{"id":"stokes-viscosity","bench":"stokes","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["viscosity","stokes' law","terminal velocity","mechanical properties of fluids","glycerine"],"title":{"en":"Viscosity of glycerine by Stokes' law","hi":"स्टोक्स नियम से ग्लिसरीन की श्यानता","kn":"ಸ್ಟೋಕ್ಸ್ ನಿಯಮದಿಂದ ಗ್ಲಿಸರಿನ್‌ನ ಸ್ನಿಗ್ಧತೆ"},"summary":{"en":"Time steel balls of different sizes falling through glycerine; terminal velocity grows as r².","hi":"विभिन्न आकार की स्टील की गोलियों का ग्लिसरीन में गिरने का समय लें; सीमांत वेग r² के अनुसार बढ़ता है।","kn":"ಬೇರೆ ಗಾತ್ರದ ಉಕ್ಕಿನ ಗುಂಡುಗಳು ಗ್ಲಿಸರಿನ್‌ನಲ್ಲಿ ಬೀಳುವ ಸಮಯ ಅಳೆಯಿರಿ; ಅಂತಿಮ ವೇಗ r² ನಂತೆ ಹೆಚ್ಚುತ್ತದೆ."},"aim":{"en":"To find the coefficient of viscosity of glycerine by measuring the terminal velocity of small spheres.","hi":"छोटे गोलों का सीमांत वेग मापकर ग्लिसरीन का श्यानता गुणांक ज्ञात करना।","kn":"ಸಣ್ಣ ಗೋಳಗಳ ಅಂತಿಮ ವೇಗ ಅಳೆದು ಗ್ಲಿಸರಿನ್‌ನ ಸ್ನಿಗ್ಧತಾ ಗುಣಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"A small sphere falling through a viscous liquid soon moves at a steady terminal velocity, when its weight equals buoyancy plus viscous drag 6πηrv. Then v = 2r²(ρ − σ)g ÷ 9η: v against r² is a straight line through the origin, and η = 2(ρ − σ)g ÷ (9 × slope).","hi":"श्यान द्रव में गिरता छोटा गोला जल्दी ही स्थिर सीमांत वेग से चलने लगता है, जब उसका भार उत्प्लावन और श्यान कर्षण 6πηrv के योग के बराबर हो जाता है। तब v = 2r²(ρ − σ)g ÷ 9η: v और r² का ग्राफ़ मूल बिंदु से जाने वाली सीधी रेखा है, और η = 2(ρ − σ)g ÷ (9 × प्रवणता).","kn":"ಸ್ನಿಗ್ಧ ದ್ರವದಲ್ಲಿ ಬೀಳುವ ಸಣ್ಣ ಗೋಳ ಬೇಗ ಸ್ಥಿರ ಅಂತಿಮ ವೇಗ ಪಡೆಯುತ್ತದೆ; ಆಗ ಅದರ ತೂಕ ಪ್ಲವನ ಮತ್ತು ಸ್ನಿಗ್ಧ ಎಳೆತ 6πηrv ಮೊತ್ತಕ್ಕೆ ಸಮ. ಆಗ v = 2r²(ρ − σ)g ÷ 9η: v ಮತ್ತು r² ನಕ್ಷೆ ಮೂಲಬಿಂದುವಿನ ಮೂಲಕ ಸರಳರೇಖೆ; η = 2(ρ − σ)g ÷ (9 × ಇಳಿಜಾರು)."},"apparatus":[{"en":"Tall glass jar of glycerine with two marks 20 cm apart","hi":"20 cm दूरी पर दो निशानों वाला ग्लिसरीन का लंबा जार","kn":"20 cm ಅಂತರದ ಎರಡು ಗುರುತುಗಳಿರುವ ಗ್ಲಿಸರಿನ್ ತುಂಬಿದ ಎತ್ತರದ ಜಾಡಿ"},{"en":"Steel balls of different radii","hi":"विभिन्न त्रिज्याओं की स्टील गोलियाँ","kn":"ಬೇರೆ ತ್ರಿಜ್ಯಗಳ ಉಕ್ಕಿನ ಗುಂಡುಗಳು"},{"en":"Screw gauge","hi":"पेंच गेज","kn":"ಸ್ಕ್ರೂ ಗೇಜ್"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"}],"steps":[{"en":"Measure the radius of each ball with the screw gauge.","hi":"हर गोली की त्रिज्या पेंच गेज से मापें।","kn":"ಪ್ರತಿ ಗುಂಡಿನ ತ್ರಿಜ್ಯವನ್ನು ಸ್ಕ್ರೂ ಗೇಜ್‌ನಿಂದ ಅಳೆಯಿರಿ."},{"en":"Wet a ball with glycerine and drop it gently at the centre of the jar.","hi":"गोली को ग्लिसरीन से गीला करके जार के बीच में धीरे से गिराएँ।","kn":"ಗುಂಡನ್ನು ಗ್ಲಿಸರಿನ್‌ನಿಂದ ಒದ್ದೆ ಮಾಡಿ ಜಾಡಿಯ ಮಧ್ಯದಲ್ಲಿ ನಿಧಾನವಾಗಿ ಬೀಳಿಸಿ."},{"en":"Time its fall between the two marks (it has reached terminal velocity by the first mark).","hi":"दोनों निशानों के बीच गिरने का समय लें (पहले निशान तक यह सीमांत वेग पा चुकी होती है)।","kn":"ಎರಡು ಗುರುತುಗಳ ನಡುವೆ ಬೀಳುವ ಸಮಯ ಅಳೆಯಿರಿ (ಮೊದಲ ಗುರುತಿನ ಹೊತ್ತಿಗೆ ಅದು ಅಂತಿಮ ವೇಗ ಪಡೆದಿರುತ್ತದೆ)."},{"en":"Repeat for each size; plot v against r² and work out η.","hi":"हर आकार के लिए दोहराएँ; v और r² का ग्राफ़ बनाकर η निकालें।","kn":"ಪ್ರತಿ ಗಾತ್ರಕ್ಕೆ ಪುನರಾವರ್ತಿಸಿ; v ಮತ್ತು r² ನಕ್ಷೆ ಎಳೆದು η ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Drop the balls along the axis, away from the walls.","hi":"गोलियाँ अक्ष के अनुदिश, दीवारों से दूर गिराएँ।","kn":"ಗುಂಡುಗಳನ್ನು ಅಕ್ಷದ ಉದ್ದಕ್ಕೂ, ಗೋಡೆಗಳಿಂದ ದೂರ ಬೀಳಿಸಿ."},{"en":"Look at the marks at eye level to avoid parallax.","hi":"लंबन से बचने के लिए निशानों को आँख के स्तर पर देखें।","kn":"ಭ್ರಂಶ ತಪ್ಪಿಸಲು ಗುರುತುಗಳನ್ನು ಕಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ನೋಡಿ."},{"en":"Note the temperature: viscosity falls quickly as it rises.","hi":"ताप लिखें: ताप बढ़ने पर श्यानता तेज़ी से घटती है।","kn":"ತಾಪ ಬರೆಯಿರಿ: ತಾಪ ಏರಿದಂತೆ ಸ್ನಿಗ್ಧತೆ ವೇಗವಾಗಿ ಇಳಿಯುತ್ತದೆ."}],"conclusion":{"en":"Terminal velocity is proportional to r², as Stokes’ law predicts, and the slope gives the viscosity of glycerine (about 1.4 Pa s at room temperature).","hi":"सीमांत वेग r² के अनुक्रमानुपाती है, जैसा स्टोक्स नियम बताता है, और प्रवणता से ग्लिसरीन की श्यानता (कमरे के ताप पर लगभग 1.4 Pa s) मिलती है।","kn":"ಸ್ಟೋಕ್ಸ್ ನಿಯಮ ಹೇಳುವಂತೆ ಅಂತಿಮ ವೇಗ r² ಗೆ ಅನುಪಾತೀಯ; ಇಳಿಜಾರು ಗ್ಲಿಸರಿನ್‌ನ ಸ್ನಿಗ್ಧತೆ (ಕೋಣೆಯ ತಾಪದಲ್ಲಿ ಸುಮಾರು 1.4 Pa s) ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"What is terminal velocity?","hi":"सीमांत वेग क्या है?","kn":"ಅಂತಿಮ ವೇಗ ಎಂದರೇನು?"},"a":{"en":"The steady velocity reached when the net force on the falling body is zero.","hi":"गिरती वस्तु पर कुल बल शून्य होने पर प्राप्त स्थिर वेग।","kn":"ಬೀಳುವ ವಸ್ತುವಿನ ಮೇಲಿನ ನಿವ್ವಳ ಬಲ ಶೂನ್ಯವಾದಾಗ ಸಿಗುವ ಸ್ಥಿರ ವೇಗ."}},{"q":{"en":"Why do raindrops not hurt us?","hi":"बारिश की बूँदें हमें चोट क्यों नहीं पहुँचातीं?","kn":"ಮಳೆಹನಿಗಳು ನಮಗೆ ಏಕೆ ನೋವು ಮಾಡುವುದಿಲ್ಲ?"},"a":{"en":"Air resistance limits them to a small terminal velocity.","hi":"वायु प्रतिरोध उन्हें छोटे सीमांत वेग तक सीमित रखता है।","kn":"ಗಾಳಿಯ ಪ್ರತಿರೋಧ ಅವುಗಳನ್ನು ಸಣ್ಣ ಅಂತಿಮ ವೇಗಕ್ಕೆ ಮಿತಿಗೊಳಿಸುತ್ತದೆ."}},{"q":{"en":"What is the SI unit of viscosity?","hi":"श्यानता का SI मात्रक क्या है?","kn":"ಸ್ನಿಗ್ಧತೆಯ SI ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"Pascal second (Pa s).","hi":"पास्कल सेकंड (Pa s).","kn":"ಪ್ಯಾಸ್ಕಲ್ ಸೆಕೆಂಡ್ (Pa s)."}}]},{"id":"surface-tension-capillary","bench":"capillary","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["surface tension","capillary rise","capillarity","mechanical properties of fluids"],"title":{"en":"Surface tension of water by capillary rise","hi":"केशिका उन्नयन से पानी का पृष्ठ तनाव","kn":"ಲೋಮನಾಳ ಏರಿಕೆಯಿಂದ ನೀರಿನ ಮೇಲ್ಮೈ ಒತ್ತಡ"},"summary":{"en":"Measure how high water climbs in tubes of different bore; h × r is constant and gives the surface tension.","hi":"विभिन्न छिद्र वाली नलियों में पानी कितना ऊपर चढ़ता है मापें; h × r नियत है और पृष्ठ तनाव देता है।","kn":"ಬೇರೆ ಬೇರೆ ರಂಧ್ರದ ನಳಿಕೆಗಳಲ್ಲಿ ನೀರು ಎಷ್ಟು ಏರುತ್ತದೆ ಅಳೆಯಿರಿ; h × r ಸ್ಥಿರ, ಅದು ಮೇಲ್ಮೈ ಒತ್ತಡ ನೀಡುತ್ತದೆ."},"aim":{"en":"To find the surface tension of water by the capillary rise method.","hi":"केशिका उन्नयन विधि से पानी का पृष्ठ तनाव ज्ञात करना।","kn":"ಲೋಮನಾಳ ಏರಿಕೆ ವಿಧಾನದಿಂದ ನೀರಿನ ಮೇಲ್ಮೈ ಒತ್ತಡ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Water wets glass, and surface tension pulls a column up a narrow tube until its weight balances the upward pull: h = 2T cos θ ÷ (rρg). For clean glass θ ≈ 0, so T = hrρg ÷ 2 and h × r is the same for every tube.","hi":"पानी काँच को भिगोता है, और पृष्ठ तनाव संकरी नली में स्तंभ को तब तक ऊपर खींचता है जब तक उसका भार ऊपर के खिंचाव को संतुलित न कर दे: h = 2T cos θ ÷ (rρg). साफ़ काँच के लिए θ ≈ 0, अतः T = hrρg ÷ 2 और h × r हर नली के लिए समान है।","kn":"ನೀರು ಗಾಜನ್ನು ತೇವಗೊಳಿಸುತ್ತದೆ; ಮೇಲ್ಮೈ ಒತ್ತಡ ಕಿರಿದಾದ ನಳಿಕೆಯಲ್ಲಿ ಸ್ತಂಭವನ್ನು ಅದರ ತೂಕ ಮೇಲ್ಮುಖ ಎಳೆತವನ್ನು ಸಮತೋಲಿಸುವವರೆಗೆ ಏರಿಸುತ್ತದೆ: h = 2T cos θ ÷ (rρg). ಸ್ವಚ್ಛ ಗಾಜಿಗೆ θ ≈ 0; ಆದ್ದರಿಂದ T = hrρg ÷ 2, h × r ಪ್ರತಿ ನಳಿಕೆಗೂ ಒಂದೇ."},"apparatus":[{"en":"Capillary tubes of different bores","hi":"विभिन्न छिद्रों की केशिका नलियाँ","kn":"ಬೇರೆ ರಂಧ್ರಗಳ ಲೋಮನಾಳಗಳು"},{"en":"Beaker of clean water","hi":"साफ़ पानी का बीकर","kn":"ಸ್ವಚ್ಛ ನೀರಿನ ಬೀಕರ್"},{"en":"Travelling microscope","hi":"चल सूक्ष्मदर्शी","kn":"ಚಲಿಸುವ ಸೂಕ್ಷ್ಮದರ್ಶಕ"},{"en":"Clamp stand and pointer","hi":"क्लैंप स्टैंड और सूचक","kn":"ಕ್ಲ್ಯಾಂಪ್ ಸ್ಟ್ಯಾಂಡ್ ಮತ್ತು ಸೂಚಕ"}],"steps":[{"en":"Clean the tube and clamp it vertically with its end in the water.","hi":"नली साफ़ करें और उसका सिरा पानी में रखकर उसे ऊर्ध्वाधर क्लैंप करें।","kn":"ನಳಿಕೆ ಸ್ವಚ್ಛಗೊಳಿಸಿ, ಅದರ ತುದಿ ನೀರಿನಲ್ಲಿರುವಂತೆ ಲಂಬವಾಗಿ ಕ್ಲ್ಯಾಂಪ್ ಮಾಡಿ."},{"en":"Focus the microscope on the bottom of the meniscus in the tube; then on the tip of a pointer just touching the water surface.","hi":"सूक्ष्मदर्शी को नली में मेनिस्कस के तल पर; फिर पानी की सतह को छूते सूचक की नोक पर फ़ोकस करें।","kn":"ಸೂಕ್ಷ್ಮದರ್ಶಕವನ್ನು ನಳಿಕೆಯ ಮೆನಿಸ್ಕಸ್‌ನ ತಳದ ಮೇಲೆ; ನಂತರ ನೀರಿನ ಮೇಲ್ಮೈ ಮುಟ್ಟುವ ಸೂಚಕದ ತುದಿಯ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿ."},{"en":"The difference of the readings is h. Measure the inner radius r of the tube.","hi":"पाठ्यांकों का अंतर h है। नली की भीतरी त्रिज्या r मापें।","kn":"ಓದುಗಳ ವ್ಯತ್ಯಾಸ h. ನಳಿಕೆಯ ಒಳ ತ್ರಿಜ್ಯ r ಅಳೆಯಿರಿ."},{"en":"Repeat with other tubes and work out T = hrρg ÷ 2.","hi":"दूसरी नलियों के साथ दोहराएँ और T = hrρg ÷ 2 निकालें।","kn":"ಬೇರೆ ನಳಿಕೆಗಳೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ T = hrρg ÷ 2 ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"The tube and water must be perfectly clean (grease lowers T).","hi":"नली और पानी पूरी तरह साफ़ हों (चिकनाई T को घटाती है)।","kn":"ನಳಿಕೆ ಮತ್ತು ನೀರು ಸಂಪೂರ್ಣ ಸ್ವಚ್ಛವಾಗಿರಲಿ (ಜಿಡ್ಡು T ಕಡಿಮೆ ಮಾಡುತ್ತದೆ)."},{"en":"Keep the tube vertical.","hi":"नली ऊर्ध्वाधर रखें।","kn":"ನಳಿಕೆ ಲಂಬವಾಗಿರಲಿ."},{"en":"Note the temperature: T falls as it rises.","hi":"ताप लिखें: ताप बढ़ने पर T घटता है।","kn":"ತಾಪ ಬರೆಯಿರಿ: ತಾಪ ಏರಿದಂತೆ T ಇಳಿಯುತ್ತದೆ."}],"conclusion":{"en":"The narrower the tube the higher the water rises, with h × r constant; the surface tension of water is about 0.072 N/m.","hi":"नली जितनी संकरी उतना अधिक पानी चढ़ता है, h × r नियत रहता है; पानी का पृष्ठ तनाव लगभग 0.072 N/m है।","kn":"ನಳಿಕೆ ಎಷ್ಟು ಕಿರಿದೋ ನೀರು ಅಷ್ಟು ಹೆಚ್ಚು ಏರುತ್ತದೆ, h × r ಸ್ಥಿರ; ನೀರಿನ ಮೇಲ್ಮೈ ಒತ್ತಡ ಸುಮಾರು 0.072 N/m."},"viva":[{"q":{"en":"Why does mercury fall in a glass capillary?","hi":"काँच की केशिका में पारा नीचे क्यों जाता है?","kn":"ಗಾಜಿನ ಲೋಮನಾಳದಲ್ಲಿ ಪಾದರಸ ಏಕೆ ಇಳಿಯುತ್ತದೆ?"},"a":{"en":"It does not wet glass: its angle of contact is more than 90°.","hi":"यह काँच को नहीं भिगोता: इसका संपर्क कोण 90° से अधिक है।","kn":"ಅದು ಗಾಜನ್ನು ತೇವಗೊಳಿಸುವುದಿಲ್ಲ: ಅದರ ಸಂಪರ್ಕ ಕೋನ 90° ಗಿಂತ ಹೆಚ್ಚು."}},{"q":{"en":"Give an example of capillary action in daily life.","hi":"दैनिक जीवन में केशिका क्रिया का एक उदाहरण दें।","kn":"ದೈನಂದಿನ ಜೀವನದಲ್ಲಿ ಲೋಮನಾಳ ಕ್ರಿಯೆಯ ಒಂದು ಉದಾಹರಣೆ ಕೊಡಿ."},"a":{"en":"Oil rising in a lamp wick; ink in blotting paper.","hi":"दीये की बत्ती में तेल का चढ़ना; सोख्ते में स्याही।","kn":"ದೀಪದ ಬತ್ತಿಯಲ್ಲಿ ಎಣ್ಣೆ ಏರುವುದು; ಒತ್ತುಕಾಗದದಲ್ಲಿ ಶಾಯಿ."}},{"q":{"en":"What is the unit of surface tension?","hi":"पृष्ठ तनाव का मात्रक क्या है?","kn":"ಮೇಲ್ಮೈ ಒತ್ತಡದ ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"N/m (or J/m²).","hi":"N/m (या J/m²).","kn":"N/m (ಅಥವಾ J/m²)."}}]},{"id":"newtons-law-cooling","bench":"cooling","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["newton's law of cooling","cooling","thermal properties of matter","heat","temperature"],"title":{"en":"Newton's law of cooling","hi":"न्यूटन का शीतलन नियम","kn":"ನ್ಯೂಟನ್‌ನ ತಂಪಾಗುವ ನಿಯಮ"},"summary":{"en":"Record the temperature of hot water as it cools and show that the rate of cooling depends on the excess temperature.","hi":"ठंडे होते गरम पानी का ताप लिखें और दिखाएँ कि शीतलन की दर अधिक ताप पर निर्भर करती है।","kn":"ತಣ್ಣಗಾಗುತ್ತಿರುವ ಬಿಸಿ ನೀರಿನ ತಾಪ ದಾಖಲಿಸಿ, ತಂಪಾಗುವ ದರ ಹೆಚ್ಚುವರಿ ತಾಪವನ್ನು ಅವಲಂಬಿಸಿದೆ ಎಂದು ತೋರಿಸಿ."},"aim":{"en":"To study the relationship between the temperature of a hot body and time by plotting a cooling curve.","hi":"शीतलन वक्र बनाकर गरम वस्तु के ताप और समय के बीच संबंध का अध्ययन करना।","kn":"ತಂಪಾಗುವ ವಕ್ರ ಎಳೆದು ಬಿಸಿ ವಸ್ತುವಿನ ತಾಪ ಮತ್ತು ಸಮಯದ ಸಂಬಂಧ ಅಧ್ಯಯನ ಮಾಡುವುದು."},"principle":{"en":"For small temperature differences the rate of loss of heat is proportional to the excess temperature over the surroundings: dT/dt = −k(T − T₀). So T − T₀ falls exponentially and ln(T − T₀) against t is a straight line of slope −k.","hi":"छोटे ताप अंतर के लिए ऊष्मा हानि की दर परिवेश से अधिक ताप के अनुक्रमानुपाती है: dT/dt = −k(T − T₀). इसलिए T − T₀ चरघातांकी रूप से घटता है और ln(T − T₀) तथा t का ग्राफ़ −k प्रवणता की सीधी रेखा है।","kn":"ಸಣ್ಣ ತಾಪ ವ್ಯತ್ಯಾಸಗಳಿಗೆ ಉಷ್ಣ ನಷ್ಟದ ದರ ಪರಿಸರಕ್ಕಿಂತ ಹೆಚ್ಚುವರಿ ತಾಪಕ್ಕೆ ಅನುಪಾತೀಯ: dT/dt = −k(T − T₀). ಆದ್ದರಿಂದ T − T₀ ಘಾತೀಯವಾಗಿ ಇಳಿಯುತ್ತದೆ; ln(T − T₀) ಮತ್ತು t ನಕ್ಷೆ −k ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ."},"apparatus":[{"en":"Copper calorimeter with stirrer","hi":"विलोडक सहित ताँबे का कैलोरीमीटर","kn":"ಕಲಕಿ ಸಹಿತ ತಾಮ್ರದ ಕ್ಯಾಲೊರಿಮೀಟರ್"},{"en":"Two thermometers (0.5 °C)","hi":"दो तापमापी (0.5 °C)","kn":"ಎರಡು ತಾಪಮಾಪಕಗಳು (0.5 °C)"},{"en":"Hot water","hi":"गरम पानी","kn":"ಬಿಸಿ ನೀರು"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"}],"steps":[{"en":"Note the room temperature T₀.","hi":"कमरे का ताप T₀ लिखें।","kn":"ಕೋಣೆಯ ತಾಪ T₀ ಬರೆಯಿರಿ."},{"en":"Fill the calorimeter with water at about 80 °C and start the stopwatch.","hi":"कैलोरीमीटर में लगभग 80 °C का पानी भरकर विराम घड़ी चालू करें।","kn":"ಕ್ಯಾಲೊರಿಮೀಟರ್‌ಗೆ ಸುಮಾರು 80 °C ನೀರು ತುಂಬಿ ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ."},{"en":"Stir gently and record the temperature every minute for 20–30 minutes.","hi":"धीरे-धीरे हिलाते हुए 20–30 मिनट तक हर मिनट ताप लिखें।","kn":"ನಿಧಾನವಾಗಿ ಕಲಕುತ್ತಾ 20–30 ನಿಮಿಷ ಪ್ರತಿ ನಿಮಿಷ ತಾಪ ದಾಖಲಿಸಿ."},{"en":"Plot T against t (the cooling curve) and ln(T − T₀) against t.","hi":"T और t (शीतलन वक्र) तथा ln(T − T₀) और t के ग्राफ़ बनाएँ।","kn":"T ಮತ್ತು t (ತಂಪಾಗುವ ವಕ್ರ) ಹಾಗೂ ln(T − T₀) ಮತ್ತು t ನಕ್ಷೆಗಳನ್ನು ಎಳೆಯಿರಿ."},{"en":"Repeat with the calorimeter lagged and compare the slopes.","hi":"आवरणयुक्त कैलोरीमीटर के साथ दोहराएँ और प्रवणताओं की तुलना करें।","kn":"ಹೊದಿಕೆಯುಳ್ಳ ಕ್ಯಾಲೊರಿಮೀಟರ್‌ನೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಇಳಿಜಾರುಗಳನ್ನು ಹೋಲಿಸಿ."}],"precautions":[{"en":"Keep the calorimeter away from draughts and the sun.","hi":"कैलोरीमीटर को हवा के झोंकों और धूप से दूर रखें।","kn":"ಕ್ಯಾಲೊರಿಮೀಟರನ್ನು ಗಾಳಿ ಬೀಸು ಮತ್ತು ಬಿಸಿಲಿನಿಂದ ದೂರವಿಡಿ."},{"en":"Stir before each reading.","hi":"हर पाठ्यांक से पहले हिलाएँ।","kn":"ಪ್ರತಿ ಓದಿನ ಮೊದಲು ಕಲಕಿ."},{"en":"Do not let the thermometer touch the bottom.","hi":"तापमापी को तली से न छूने दें।","kn":"ತಾಪಮಾಪಕ ತಳ ಮುಟ್ಟದಿರಲಿ."}],"conclusion":{"en":"The water cools fast at first and slower as it nears room temperature; ln(T − T₀) falls linearly with time, as Newton’s law of cooling predicts. Lagging lowers k.","hi":"पानी पहले तेज़ी से और कमरे के ताप के पास आते हुए धीरे ठंडा होता है; ln(T − T₀) समय के साथ रैखिक रूप से घटता है, जैसा न्यूटन का शीतलन नियम बताता है। आवरण k को घटाता है।","kn":"ನೀರು ಮೊದಲು ವೇಗವಾಗಿ, ಕೋಣೆಯ ತಾಪ ಸಮೀಪಿಸಿದಂತೆ ನಿಧಾನವಾಗಿ ತಣ್ಣಗಾಗುತ್ತದೆ; ನ್ಯೂಟನ್ ನಿಯಮ ಹೇಳುವಂತೆ ln(T − T₀) ಸಮಯದೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಇಳಿಯುತ್ತದೆ. ಹೊದಿಕೆ k ಕಡಿಮೆ ಮಾಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why does hot tea cool quickly at first?","hi":"गरम चाय पहले जल्दी क्यों ठंडी होती है?","kn":"ಬಿಸಿ ಚಹಾ ಮೊದಲು ಬೇಗ ಏಕೆ ತಣ್ಣಗಾಗುತ್ತದೆ?"},"a":{"en":"Its excess temperature, and so its rate of heat loss, is largest then.","hi":"तब उसका अधिक ताप, और इसलिए ऊष्मा हानि की दर, सबसे अधिक होती है।","kn":"ಆಗ ಅದರ ಹೆಚ್ಚುವರಿ ತಾಪ, ಆದ್ದರಿಂದ ಉಷ್ಣ ನಷ್ಟದ ದರ, ಗರಿಷ್ಠ."}},{"q":{"en":"When does Newton’s law of cooling fail?","hi":"न्यूटन का शीतलन नियम कब लागू नहीं होता?","kn":"ನ್ಯೂಟನ್‌ನ ತಂಪಾಗುವ ನಿಯಮ ಯಾವಾಗ ವಿಫಲ?"},"a":{"en":"For large temperature differences, or when convection is forced.","hi":"बड़े ताप अंतर पर, या जब संवहन बलपूर्वक हो।","kn":"ದೊಡ್ಡ ತಾಪ ವ್ಯತ್ಯಾಸಗಳಲ್ಲಿ, ಅಥವಾ ಬಲವಂತದ ಸಂವಹನದಲ್ಲಿ."}},{"q":{"en":"How does the cooling rate depend on the surface?","hi":"शीतलन दर सतह पर कैसे निर्भर करती है?","kn":"ತಂಪಾಗುವ ದರ ಮೇಲ್ಮೈಯನ್ನು ಹೇಗೆ ಅವಲಂಬಿಸಿದೆ?"},"a":{"en":"It grows with surface area and is larger for a dull, black surface.","hi":"यह सतह क्षेत्रफल के साथ बढ़ती है और खुरदरी, काली सतह के लिए अधिक है।","kn":"ಅದು ಮೇಲ್ಮೈ ವಿಸ್ತೀರ್ಣದೊಂದಿಗೆ ಹೆಚ್ಚುತ್ತದೆ; ಮಸುಕಾದ, ಕಪ್ಪು ಮೇಲ್ಮೈಗೆ ಹೆಚ್ಚು."}}]},{"id":"resonance-tube","bench":"resonance-tube","setup":{},"subject":"Physics","domain":"physics","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["resonance tube","speed of sound","waves","resonance","end correction","tuning fork","sound"],"title":{"en":"Speed of sound with a resonance tube","hi":"अनुनाद नली से ध्वनि की चाल","kn":"ಅನುನಾದ ನಳಿಕೆಯಿಂದ ಧ್ವನಿಯ ವೇಗ"},"summary":{"en":"Lower the water in a tube under a tuning fork and find the two lengths where the sound is loudest.","hi":"स्वरित्र के नीचे नली में पानी घटाएँ और वे दो लंबाइयाँ ढूँढें जहाँ ध्वनि सबसे तेज़ हो।","kn":"ಶ್ರುತಿಕವೆಯ ಕೆಳಗೆ ನಳಿಕೆಯಲ್ಲಿ ನೀರನ್ನು ಇಳಿಸಿ, ಧ್ವನಿ ಅತಿ ಜೋರಾಗುವ ಎರಡು ಉದ್ದಗಳನ್ನು ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To find the speed of sound in air at room temperature using a resonance tube with two resonance positions, and the end correction.","hi":"दो अनुनाद स्थितियों द्वारा अनुनाद नली से कमरे के ताप पर वायु में ध्वनि की चाल और सिरा संशोधन ज्ञात करना।","kn":"ಎರಡು ಅನುನಾದ ಸ್ಥಾನಗಳ ಮೂಲಕ ಅನುನಾದ ನಳಿಕೆಯಿಂದ ಕೋಣೆಯ ತಾಪದಲ್ಲಿ ಗಾಳಿಯಲ್ಲಿ ಧ್ವನಿಯ ವೇಗ ಮತ್ತು ತುದಿ ತಿದ್ದುಪಡಿ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"An air column closed at one end resonates when its length plus the end correction is λ/4, 3λ/4, …: L₁ + e = λ/4 and L₂ + e = 3λ/4. Subtracting, λ = 2(L₂ − L₁) and v = fλ = 2f(L₂ − L₁); the end correction is e = (L₂ − 3L₁) ÷ 2 (about 0.3 × the diameter).","hi":"एक सिरे पर बंद वायु स्तंभ तब अनुनाद करता है जब उसकी लंबाई और सिरा संशोधन का योग λ/4, 3λ/4, … हो: L₁ + e = λ/4 और L₂ + e = 3λ/4. घटाने पर λ = 2(L₂ − L₁) और v = fλ = 2f(L₂ − L₁); सिरा संशोधन e = (L₂ − 3L₁) ÷ 2 (व्यास का लगभग 0.3 गुना)।","kn":"ಒಂದು ತುದಿ ಮುಚ್ಚಿದ ಗಾಳಿ ಸ್ತಂಭ ಅದರ ಉದ್ದ ಮತ್ತು ತುದಿ ತಿದ್ದುಪಡಿಯ ಮೊತ್ತ λ/4, 3λ/4, … ಆದಾಗ ಅನುನಾದಿಸುತ್ತದೆ: L₁ + e = λ/4, L₂ + e = 3λ/4. ಕಳೆದಾಗ λ = 2(L₂ − L₁), v = fλ = 2f(L₂ − L₁); ತುದಿ ತಿದ್ದುಪಡಿ e = (L₂ − 3L₁) ÷ 2 (ವ್ಯಾಸದ ಸುಮಾರು 0.3 ಪಟ್ಟು)."},"apparatus":[{"en":"Resonance tube with water reservoir","hi":"जल भंडार सहित अनुनाद नली","kn":"ನೀರಿನ ತೊಟ್ಟಿ ಸಹಿತ ಅನುನಾದ ನಳಿಕೆ"},{"en":"Tuning forks of known frequency","hi":"ज्ञात आवृत्ति के स्वरित्र","kn":"ತಿಳಿದ ಆವರ್ತನದ ಶ್ರುತಿಕವೆಗಳು"},{"en":"Rubber pad","hi":"रबर पैड","kn":"ರಬ್ಬರ್ ಪ್ಯಾಡ್"},{"en":"Thermometer","hi":"तापमापी","kn":"ತಾಪಮಾಪಕ"}],"steps":[{"en":"Fill the tube nearly to the top. Strike the fork on the rubber pad and hold it over the mouth.","hi":"नली को लगभग ऊपर तक भरें। स्वरित्र को रबर पैड पर मारकर मुँह के ऊपर पकड़ें।","kn":"ನಳಿಕೆಯನ್ನು ಬಹುತೇಕ ಮೇಲಿನವರೆಗೆ ತುಂಬಿ. ಶ್ರುತಿಕವೆಯನ್ನು ರಬ್ಬರ್ ಪ್ಯಾಡ್‌ಗೆ ಹೊಡೆದು ಬಾಯಿಯ ಮೇಲೆ ಹಿಡಿಯಿರಿ."},{"en":"Lower the water slowly until the sound is loudest; record the air column length L₁.","hi":"पानी धीरे-धीरे घटाएँ जब तक ध्वनि सबसे तेज़ न हो; वायु स्तंभ की लंबाई L₁ लिखें।","kn":"ಧ್ವನಿ ಅತಿ ಜೋರಾಗುವವರೆಗೆ ನೀರನ್ನು ನಿಧಾನವಾಗಿ ಇಳಿಸಿ; ಗಾಳಿ ಸ್ತಂಭದ ಉದ್ದ L₁ ದಾಖಲಿಸಿ."},{"en":"Lower it further to the second loud position, about three times as long: L₂.","hi":"उसे और नीचे लगभग तिगुनी लंबाई वाली दूसरी तेज़ स्थिति तक ले जाएँ: L₂.","kn":"ಸುಮಾರು ಮೂರು ಪಟ್ಟು ಉದ್ದದ ಎರಡನೇ ಜೋರು ಸ್ಥಾನಕ್ಕೆ ಇನ್ನೂ ಇಳಿಸಿ: L₂."},{"en":"Approach each position from above and below and take the mean.","hi":"हर स्थिति तक ऊपर और नीचे दोनों ओर से पहुँचकर माध्य लें।","kn":"ಪ್ರತಿ ಸ್ಥಾನವನ್ನು ಮೇಲಿನಿಂದ ಮತ್ತು ಕೆಳಗಿನಿಂದ ತಲುಪಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ."},{"en":"Work out v = 2f(L₂ − L₁) and e for each fork.","hi":"हर स्वरित्र के लिए v = 2f(L₂ − L₁) और e निकालें।","kn":"ಪ್ರತಿ ಶ್ರುತಿಕವೆಗೆ v = 2f(L₂ − L₁) ಮತ್ತು e ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Do not let the vibrating fork touch the tube.","hi":"कंपित स्वरित्र को नली से न छूने दें।","kn":"ಕಂಪಿಸುವ ಶ್ರುತಿಕವೆ ನಳಿಕೆಯನ್ನು ಮುಟ್ಟದಿರಲಿ."},{"en":"Strike the fork on rubber, never on a hard surface.","hi":"स्वरित्र को रबर पर मारें, कठोर सतह पर कभी नहीं।","kn":"ಶ್ರುತಿಕವೆಯನ್ನು ರಬ್ಬರ್ ಮೇಲೆ ಹೊಡೆಯಿರಿ, ಗಟ್ಟಿ ಮೇಲ್ಮೈ ಮೇಲೆ ಎಂದೂ ಅಲ್ಲ."},{"en":"Read the bottom of the water meniscus.","hi":"पानी के मेनिस्कस का निचला तल पढ़ें।","kn":"ನೀರಿನ ಮೆನಿಸ್ಕಸ್‌ನ ತಳವನ್ನು ಓದಿ."}],"conclusion":{"en":"L₂ is about three times L₁, and v = 2f(L₂ − L₁) gives the speed of sound close to 346 m/s at 25 °C, independent of the fork used.","hi":"L₂ लगभग L₁ का तिगुना है, और v = 2f(L₂ − L₁) से 25 °C पर ध्वनि की चाल लगभग 346 m/s मिलती है, जो प्रयुक्त स्वरित्र पर निर्भर नहीं करती।","kn":"L₂ ಸುಮಾರು L₁ ನ ಮೂರು ಪಟ್ಟು; v = 2f(L₂ − L₁) 25 °C ನಲ್ಲಿ ಧ್ವನಿಯ ವೇಗವನ್ನು ಸುಮಾರು 346 m/s ಆಗಿ ನೀಡುತ್ತದೆ, ಬಳಸಿದ ಶ್ರುತಿಕವೆಯನ್ನು ಅವಲಂಬಿಸದೆ."},"viva":[{"q":{"en":"Why is the second resonance length not exactly 3L₁?","hi":"दूसरी अनुनाद लंबाई ठीक 3L₁ क्यों नहीं होती?","kn":"ಎರಡನೇ ಅನುನಾದ ಉದ್ದ ನಿಖರವಾಗಿ 3L₁ ಏಕೆ ಅಲ್ಲ?"},"a":{"en":"Because of the end correction: the antinode forms a little above the open end.","hi":"सिरा संशोधन के कारण: प्रस्पंद खुले सिरे से थोड़ा ऊपर बनता है।","kn":"ತುದಿ ತಿದ್ದುಪಡಿಯಿಂದ: ಪ್ರಸ್ಪಂದ ತೆರೆದ ತುದಿಯ ಸ್ವಲ್ಪ ಮೇಲೆ ಮೂಡುತ್ತದೆ."}},{"q":{"en":"How does the speed of sound change with temperature?","hi":"ताप के साथ ध्वनि की चाल कैसे बदलती है?","kn":"ತಾಪದೊಂದಿಗೆ ಧ್ವನಿಯ ವೇಗ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?"},"a":{"en":"It increases, by about 0.6 m/s per °C.","hi":"यह बढ़ती है, लगभग 0.6 m/s प्रति °C.","kn":"ಅದು ಹೆಚ್ಚುತ್ತದೆ, ಪ್ರತಿ °C ಗೆ ಸುಮಾರು 0.6 m/s."}},{"q":{"en":"What is at the water surface: a node or an antinode?","hi":"पानी की सतह पर निस्पंद है या प्रस्पंद?","kn":"ನೀರಿನ ಮೇಲ್ಮೈಯಲ್ಲಿ ನಿಸ್ಪಂದವೇ ಪ್ರಸ್ಪಂದವೇ?"},"a":{"en":"A displacement node (the air cannot move there).","hi":"एक विस्थापन निस्पंद (वहाँ वायु हिल नहीं सकती)।","kn":"ಸ್ಥಳಾಂತರ ನಿಸ್ಪಂದ (ಅಲ್ಲಿ ಗಾಳಿ ಚಲಿಸಲಾರದು)."}}]},{"id":"e-by-m","bench":"e-by-m","setup":{},"subject":"Physics","domain":"physics","levels":["ug"],"mode":"guided","curricula":["ug-physics"],"reviewed":false,"keywords":["e/m","specific charge","electron","helmholtz coils","fine beam tube","magnetic field","modern physics"],"title":{"en":"e/m of the electron (fine-beam tube)","hi":"इलेक्ट्रॉन का e/m (सूक्ष्म-किरण नली)","kn":"ಎಲೆಕ್ಟ್ರಾನ್‌ನ e/m (ಸೂಕ್ಷ್ಮ-ಕಿರಣ ನಳಿಕೆ)"},"summary":{"en":"Bend an electron beam into a circle with Helmholtz coils and work out e/m from V, B and r.","hi":"हेल्महोल्ट्ज़ कुंडलियों से इलेक्ट्रॉन किरण को वृत्त में मोड़ें और V, B और r से e/m निकालें।","kn":"ಹೆಲ್ಮ್‌ಹೋಲ್ಟ್ಸ್ ಸುರುಳಿಗಳಿಂದ ಎಲೆಕ್ಟ್ರಾನ್ ಕಿರಣವನ್ನು ವೃತ್ತವಾಗಿ ಬಾಗಿಸಿ V, B ಮತ್ತು r ನಿಂದ e/m ಲೆಕ್ಕಿಸಿ."},"aim":{"en":"To find the specific charge e/m of the electron.","hi":"इलेक्ट्रॉन का विशिष्ट आवेश e/m ज्ञात करना।","kn":"ಎಲೆಕ್ಟ್ರಾನ್‌ನ ವಿಶಿಷ್ಟ ಆವೇಶ e/m ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Electrons accelerated through V gain ½mv² = eV. In a uniform field B at right angles they move in a circle with evB = mv²/r. Eliminating v, e/m = 2V ÷ (B²r²). The Helmholtz coils give B = (4/5)^(3/2) μ₀NI ÷ R.","hi":"V से त्वरित इलेक्ट्रॉन ½mv² = eV पाते हैं। समकोण पर एकसमान क्षेत्र B में वे evB = mv²/r के साथ वृत्त में चलते हैं। v हटाने पर e/m = 2V ÷ (B²r²). हेल्महोल्ट्ज़ कुंडलियाँ B = (4/5)^(3/2) μ₀NI ÷ R देती हैं।","kn":"V ಮೂಲಕ ವೇಗವರ್ಧಿತ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳು ½mv² = eV ಪಡೆಯುತ್ತವೆ. ಲಂಬವಾದ ಏಕರೂಪ ಕ್ಷೇತ್ರ B ಯಲ್ಲಿ ಅವು evB = mv²/r ನೊಂದಿಗೆ ವೃತ್ತದಲ್ಲಿ ಚಲಿಸುತ್ತವೆ. v ತೆಗೆದರೆ e/m = 2V ÷ (B²r²). ಹೆಲ್ಮ್‌ಹೋಲ್ಟ್ಸ್ ಸುರುಳಿಗಳು B = (4/5)^(3/2) μ₀NI ÷ R ನೀಡುತ್ತವೆ."},"apparatus":[{"en":"Fine-beam tube with a radius scale","hi":"त्रिज्या पैमाने सहित सूक्ष्म-किरण नली","kn":"ತ್ರಿಜ್ಯ ಅಳತೆ ಸಹಿತ ಸೂಕ್ಷ್ಮ-ಕಿರಣ ನಳಿಕೆ"},{"en":"Helmholtz coils (130 turns, R = 15 cm)","hi":"हेल्महोल्ट्ज़ कुंडलियाँ (130 फेरे, R = 15 cm)","kn":"ಹೆಲ್ಮ್‌ಹೋಲ್ಟ್ಸ್ ಸುರುಳಿಗಳು (130 ಸುತ್ತು, R = 15 cm)"},{"en":"High-voltage supply (0–300 V) and coil supply","hi":"उच्च वोल्टता आपूर्ति (0–300 V) और कुंडली आपूर्ति","kn":"ಹೆಚ್ಚಿನ ವೋಲ್ಟೇಜ್ ಪೂರೈಕೆ (0–300 V) ಮತ್ತು ಸುರುಳಿ ಪೂರೈಕೆ"},{"en":"Ammeter and voltmeter","hi":"ऐमीटर और वोल्टमीटर","kn":"ಅಮ್ಮೀಟರ್ ಮತ್ತು ವೋಲ್ಟ್‌ಮೀಟರ್"}],"steps":[{"en":"Darken the room, warm the filament and set an accelerating voltage.","hi":"कमरे में अँधेरा करें, तंतु गरम करें और त्वरक वोल्टता तय करें।","kn":"ಕೋಣೆಯನ್ನು ಕತ್ತಲಾಗಿಸಿ, ತಂತು ಬಿಸಿಮಾಡಿ ವೇಗವರ್ಧಕ ವೋಲ್ಟೇಜ್ ಹೊಂದಿಸಿ."},{"en":"Raise the coil current until the beam closes into a circle; read its radius on the scale.","hi":"कुंडली धारा बढ़ाएँ जब तक किरण वृत्त में बंद न हो जाए; पैमाने पर उसकी त्रिज्या पढ़ें।","kn":"ಕಿರಣ ವೃತ್ತವಾಗಿ ಮುಚ್ಚುವವರೆಗೆ ಸುರುಳಿ ಪ್ರವಾಹ ಹೆಚ್ಚಿಸಿ; ಅಳತೆಯ ಮೇಲೆ ಅದರ ತ್ರಿಜ್ಯ ಓದಿ."},{"en":"Record V, I and r; compute B and e/m.","hi":"V, I और r लिखें; B और e/m निकालें।","kn":"V, I ಮತ್ತು r ದಾಖಲಿಸಿ; B ಮತ್ತು e/m ಲೆಕ್ಕಿಸಿ."},{"en":"Repeat for several voltages and currents and find the mean with its standard error.","hi":"कई वोल्टताओं और धाराओं के लिए दोहराएँ और मानक त्रुटि सहित माध्य निकालें।","kn":"ಹಲವು ವೋಲ್ಟೇಜ್ ಮತ್ತು ಪ್ರವಾಹಗಳಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಪ್ರಮಾಣಿತ ದೋಷ ಸಹಿತ ಸರಾಸರಿ ಪಡೆಯಿರಿ."},{"en":"Export the readings as CSV and work out the uncertainty from the fit.","hi":"पाठ्यांक CSV में निर्यात करें और फ़िट से अनिश्चितता निकालें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"High voltage: switch off before touching any connection.","hi":"उच्च वोल्टता: किसी भी संयोजन को छूने से पहले बंद करें।","kn":"ಹೆಚ್ಚಿನ ವೋಲ್ಟೇಜ್: ಯಾವುದೇ ಸಂಪರ್ಕ ಮುಟ್ಟುವ ಮೊದಲು ಆಫ್ ಮಾಡಿ."},{"en":"Read the radius without parallax, using the scale inside the tube.","hi":"नली के भीतर के पैमाने से बिना लंबन के त्रिज्या पढ़ें।","kn":"ನಳಿಕೆಯೊಳಗಿನ ಅಳತೆಯಿಂದ ಭ್ರಂಶವಿಲ್ಲದೆ ತ್ರಿಜ್ಯ ಓದಿ."},{"en":"Keep magnetic objects away; the Earth’s field adds a small error.","hi":"चुंबकीय वस्तुएँ दूर रखें; पृथ्वी का क्षेत्र छोटी त्रुटि जोड़ता है।","kn":"ಕಾಂತೀಯ ವಸ್ತುಗಳನ್ನು ದೂರವಿಡಿ; ಭೂಮಿಯ ಕ್ಷೇತ್ರ ಸಣ್ಣ ದೋಷ ಸೇರಿಸುತ್ತದೆ."}],"conclusion":{"en":"The specific charge of the electron comes out close to 1.76 × 10¹¹ C/kg, independent of V and B.","hi":"इलेक्ट्रॉन का विशिष्ट आवेश V और B से स्वतंत्र, 1.76 × 10¹¹ C/kg के निकट आता है।","kn":"ಎಲೆಕ್ಟ್ರಾನ್‌ನ ವಿಶಿಷ್ಟ ಆವೇಶ V ಮತ್ತು B ಯನ್ನು ಅವಲಂಬಿಸದೆ 1.76 × 10¹¹ C/kg ಹತ್ತಿರ ಬರುತ್ತದೆ."},"viva":[{"q":{"en":"Why does the beam glow?","hi":"किरण क्यों चमकती है?","kn":"ಕಿರಣ ಏಕೆ ಹೊಳೆಯುತ್ತದೆ?"},"a":{"en":"Electrons excite the low-pressure gas, which gives out light.","hi":"इलेक्ट्रॉन निम्न दाब की गैस को उत्तेजित करते हैं, जो प्रकाश देती है।","kn":"ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳು ಕಡಿಮೆ ಒತ್ತಡದ ಅನಿಲವನ್ನು ಉದ್ರೇಕಿಸುತ್ತವೆ, ಅದು ಬೆಳಕು ನೀಡುತ್ತದೆ."}},{"q":{"en":"Does the magnetic force change the electrons’ speed?","hi":"क्या चुंबकीय बल इलेक्ट्रॉनों की चाल बदलता है?","kn":"ಕಾಂತೀಯ ಬಲ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳ ವೇಗ ಬದಲಿಸುತ್ತದೆಯೇ?"},"a":{"en":"No; it is always at right angles to the velocity and only changes direction.","hi":"नहीं; यह सदा वेग के लंबवत होता है और केवल दिशा बदलता है।","kn":"ಇಲ್ಲ; ಅದು ಯಾವಾಗಲೂ ವೇಗಕ್ಕೆ ಲಂಬವಾಗಿದ್ದು ದಿಕ್ಕನ್ನು ಮಾತ್ರ ಬದಲಿಸುತ್ತದೆ."}},{"q":{"en":"Who first measured e/m?","hi":"e/m सबसे पहले किसने मापा?","kn":"e/m ಅನ್ನು ಮೊದಲು ಯಾರು ಅಳೆದರು?"},"a":{"en":"J. J. Thomson, in 1897.","hi":"जे. जे. टॉमसन ने, 1897 में।","kn":"ಜೆ. ಜೆ. ಥಾಮ್ಸನ್, 1897 ರಲ್ಲಿ."}}]},{"id":"photoelectric-effect","bench":"photoelectric","setup":{},"subject":"Physics","domain":"physics","levels":["12","ug"],"mode":"guided","curricula":["ug-physics","cbse"],"reviewed":false,"keywords":["photoelectric effect","stopping potential","work function","planck's constant","dual nature of radiation and matter","threshold frequency"],"title":{"en":"Photoelectric effect: Planck's constant and work function","hi":"प्रकाश-विद्युत प्रभाव: प्लांक नियतांक और कार्य फलन","kn":"ದ್ಯುತಿವಿದ್ಯುತ್ ಪರಿಣಾಮ: ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕ ಮತ್ತು ಕಾರ್ಯ ಫಲನ"},"summary":{"en":"Find the stopping potential for light of several colours; its slope against frequency gives h, its intercept the work function.","hi":"कई रंगों के प्रकाश के लिए निरोधी विभव ज्ञात करें; आवृत्ति के सापेक्ष उसकी प्रवणता h और अंतःखंड कार्य फलन देता है।","kn":"ಹಲವು ಬಣ್ಣಗಳ ಬೆಳಕಿಗೆ ನಿಲುಗಡೆ ವಿಭವ ಕಂಡುಹಿಡಿಯಿರಿ; ಆವರ್ತನದ ವಿರುದ್ಧ ಅದರ ಇಳಿಜಾರು h, ಅಂತಃಖಂಡ ಕಾರ್ಯ ಫಲನ ನೀಡುತ್ತದೆ."},"aim":{"en":"To study the photoelectric effect and find Planck's constant and the work function of the cathode.","hi":"प्रकाश-विद्युत प्रभाव का अध्ययन कर प्लांक नियतांक और कैथोड का कार्य फलन ज्ञात करना।","kn":"ದ್ಯುತಿವಿದ್ಯುತ್ ಪರಿಣಾಮ ಅಧ್ಯಯನ ಮಾಡಿ ಪ್ಲಾಂಕ್ ಸ್ಥಿರಾಂಕ ಮತ್ತು ಕ್ಯಾಥೋಡ್‌ನ ಕಾರ್ಯ ಫಲನ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Light comes in photons of energy hν. An electron that absorbs one leaves the metal with at most hν − φ of kinetic energy, and a retarding potential V₀ = (h/e)ν − φ/e just stops it (Einstein’s equation). Brighter light gives more electrons, not faster ones.","hi":"प्रकाश hν ऊर्जा के फ़ोटॉनों में आता है। एक फ़ोटॉन सोखने वाला इलेक्ट्रॉन अधिकतम hν − φ गतिज ऊर्जा से धातु छोड़ता है, और निरोधी विभव V₀ = (h/e)ν − φ/e उसे ठीक रोक देता है (आइंस्टीन समीकरण)। तेज़ प्रकाश अधिक इलेक्ट्रॉन देता है, तेज़ नहीं।","kn":"ಬೆಳಕು hν ಶಕ್ತಿಯ ಫೋಟಾನ್‌ಗಳಾಗಿ ಬರುತ್ತದೆ. ಒಂದನ್ನು ಹೀರಿದ ಎಲೆಕ್ಟ್ರಾನ್ ಗರಿಷ್ಠ hν − φ ಚಲನ ಶಕ್ತಿಯೊಂದಿಗೆ ಲೋಹ ಬಿಡುತ್ತದೆ; ನಿಲುಗಡೆ ವಿಭವ V₀ = (h/e)ν − φ/e ಅದನ್ನು ನಿಲ್ಲಿಸುತ್ತದೆ (ಐನ್‌ಸ್ಟೈನ್ ಸಮೀಕರಣ). ಪ್ರಕಾಶಮಾನ ಬೆಳಕು ಹೆಚ್ಚು ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳನ್ನು ನೀಡುತ್ತದೆ, ವೇಗದವಲ್ಲ."},"apparatus":[{"en":"Vacuum photocell","hi":"निर्वात प्रकाश-सेल","kn":"ನಿರ್ವಾತ ದ್ಯುತಿಕೋಶ"},{"en":"Mercury lamp with colour filters","hi":"रंग फ़िल्टरों सहित पारद लैंप","kn":"ಬಣ್ಣದ ಫಿಲ್ಟರ್‌ಗಳ ಸಹಿತ ಪಾದರಸ ದೀಪ"},{"en":"Variable retarding/accelerating voltage supply","hi":"परिवर्ती निरोधी/त्वरक वोल्टता आपूर्ति","kn":"ಬದಲಾಯಿಸಬಹುದಾದ ನಿಲುಗಡೆ/ವೇಗವರ್ಧಕ ವೋಲ್ಟೇಜ್ ಪೂರೈಕೆ"},{"en":"Nanoammeter and voltmeter","hi":"नैनोऐमीटर और वोल्टमीटर","kn":"ನ್ಯಾನೋಅಮ್ಮೀಟರ್ ಮತ್ತು ವೋಲ್ಟ್‌ಮೀಟರ್"}],"steps":[{"en":"Put a filter in front of the photocell and switch on the lamp.","hi":"प्रकाश-सेल के सामने एक फ़िल्टर लगाएँ और लैंप चालू करें।","kn":"ದ್ಯುತಿಕೋಶದ ಮುಂದೆ ಒಂದು ಫಿಲ್ಟರ್ ಇಟ್ಟು ದೀಪ ಆನ್ ಮಾಡಿ."},{"en":"Record the photocurrent as you make the anode more and more negative.","hi":"ऐनोड को अधिकाधिक ऋणात्मक करते हुए प्रकाश-धारा लिखें।","kn":"ಆನೋಡನ್ನು ಹೆಚ್ಚು ಹೆಚ್ಚು ಋಣಗೊಳಿಸುತ್ತಾ ದ್ಯುತಿ ಪ್ರವಾಹ ದಾಖಲಿಸಿ."},{"en":"Note the stopping potential V₀ where the current just becomes zero.","hi":"वह निरोधी विभव V₀ लिखें जहाँ धारा ठीक शून्य हो जाती है।","kn":"ಪ್ರವಾಹ ಕೇವಲ ಶೂನ್ಯವಾಗುವ ನಿಲುಗಡೆ ವಿಭವ V₀ ಬರೆಯಿರಿ."},{"en":"Repeat for each filter, and for one filter at half intensity.","hi":"हर फ़िल्टर के लिए, और एक फ़िल्टर के लिए आधी तीव्रता पर, दोहराएँ।","kn":"ಪ್ರತಿ ಫಿಲ್ಟರ್‌ಗೆ, ಮತ್ತು ಒಂದು ಫಿಲ್ಟರ್‌ಗೆ ಅರ್ಧ ತೀವ್ರತೆಯಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Plot V₀ against ν: h = e × slope, φ = −e × intercept.","hi":"V₀ और ν का ग्राफ़ बनाएँ: h = e × प्रवणता, φ = −e × अंतःखंड।","kn":"V₀ ಮತ್ತು ν ನಕ್ಷೆ ಎಳೆಯಿರಿ: h = e × ಇಳಿಜಾರು, φ = −e × ಅಂತಃಖಂಡ."},{"en":"Export the readings as CSV and work out the uncertainty from the fit.","hi":"पाठ्यांक CSV में निर्यात करें और फ़िट से अनिश्चितता निकालें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Shield the photocell from room light.","hi":"प्रकाश-सेल को कमरे के प्रकाश से बचाएँ।","kn":"ದ್ಯುತಿಕೋಶವನ್ನು ಕೋಣೆಯ ಬೆಳಕಿನಿಂದ ರಕ್ಷಿಸಿ."},{"en":"Do not look at the mercury lamp: it emits ultraviolet.","hi":"पारद लैंप की ओर न देखें: यह पराबैंगनी उत्सर्जित करता है।","kn":"ಪಾದರಸ ದೀಪದತ್ತ ನೋಡಬೇಡಿ: ಅದು ಅತಿನೇರಳೆ ಹೊರಸೂಸುತ್ತದೆ."},{"en":"Approach the stopping potential slowly.","hi":"निरोधी विभव तक धीरे-धीरे पहुँचें।","kn":"ನಿಲುಗಡೆ ವಿಭವವನ್ನು ನಿಧಾನವಾಗಿ ಸಮೀಪಿಸಿ."}],"conclusion":{"en":"The stopping potential rises linearly with frequency and does not depend on intensity; the slope gives h ≈ 6.6 × 10⁻³⁴ J s and the intercept the work function of the cathode.","hi":"निरोधी विभव आवृत्ति के साथ रैखिक रूप से बढ़ता है और तीव्रता पर निर्भर नहीं करता; प्रवणता h ≈ 6.6 × 10⁻³⁴ J s और अंतःखंड कैथोड का कार्य फलन देता है।","kn":"ನಿಲುಗಡೆ ವಿಭವ ಆವರ್ತನದೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಏರುತ್ತದೆ, ತೀವ್ರತೆಯನ್ನು ಅವಲಂಬಿಸುವುದಿಲ್ಲ; ಇಳಿಜಾರು h ≈ 6.6 × 10⁻³⁴ J s, ಅಂತಃಖಂಡ ಕ್ಯಾಥೋಡ್‌ನ ಕಾರ್ಯ ಫಲನ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"What is the threshold frequency?","hi":"देहली आवृत्ति क्या है?","kn":"ಹೊಸ್ತಿಲು ಆವರ್ತನ ಎಂದರೇನು?"},"a":{"en":"The least frequency that can eject electrons: ν₀ = φ/h.","hi":"इलेक्ट्रॉन निकाल सकने वाली न्यूनतम आवृत्ति: ν₀ = φ/h.","kn":"ಎಲೆಕ್ಟ್ರಾನ್ ಹೊರಹಾಕಬಲ್ಲ ಕನಿಷ್ಠ ಆವರ್ತನ: ν₀ = φ/h."}},{"q":{"en":"Why does red light not eject electrons from zinc however bright it is?","hi":"लाल प्रकाश कितना भी तेज़ हो, जस्ते से इलेक्ट्रॉन क्यों नहीं निकालता?","kn":"ಕೆಂಪು ಬೆಳಕು ಎಷ್ಟೇ ಪ್ರಕಾಶಮಾನವಾಗಿದ್ದರೂ ಸತುವಿನಿಂದ ಎಲೆಕ್ಟ್ರಾನ್ ಏಕೆ ಹೊರಹಾಕುವುದಿಲ್ಲ?"},"a":{"en":"Each photon has less energy than the work function.","hi":"हर फ़ोटॉन की ऊर्जा कार्य फलन से कम है।","kn":"ಪ್ರತಿ ಫೋಟಾನ್‌ನ ಶಕ್ತಿ ಕಾರ್ಯ ಫಲನಕ್ಕಿಂತ ಕಡಿಮೆ."}},{"q":{"en":"What does the saturation current depend on?","hi":"संतृप्त धारा किस पर निर्भर करती है?","kn":"ಸಂತೃಪ್ತ ಪ್ರವಾಹ ಯಾವುದನ್ನು ಅವಲಂಬಿಸುತ್ತದೆ?"},"a":{"en":"The intensity of the light (number of photons per second).","hi":"प्रकाश की तीव्रता (प्रति सेकंड फ़ोटॉनों की संख्या) पर।","kn":"ಬೆಳಕಿನ ತೀವ್ರತೆ (ಪ್ರತಿ ಸೆಕೆಂಡಿಗೆ ಫೋಟಾನ್‌ಗಳ ಸಂಖ್ಯೆ)."}}]},{"id":"hall-effect","bench":"hall","setup":{},"subject":"Physics","domain":"physics","levels":["ug"],"mode":"guided","curricula":["ug-physics"],"reviewed":false,"keywords":["hall effect","hall coefficient","carrier concentration","semiconductor","magnetic field","solid state physics"],"title":{"en":"Hall effect in a semiconductor","hi":"अर्धचालक में हॉल प्रभाव","kn":"ಅರೆವಾಹಕದಲ್ಲಿ ಹಾಲ್ ಪರಿಣಾಮ"},"summary":{"en":"Measure the Hall voltage across a slab in a magnetic field; get the carrier type and density.","hi":"चुंबकीय क्षेत्र में एक पट्टी के आर-पार हॉल वोल्टता मापें; वाहक का प्रकार और घनत्व ज्ञात करें।","kn":"ಕಾಂತ ಕ್ಷೇತ್ರದಲ್ಲಿ ಚಪ್ಪಡಿಯ ಅಡ್ಡಲಾಗಿ ಹಾಲ್ ವೋಲ್ಟೇಜ್ ಅಳೆಯಿರಿ; ವಾಹಕದ ಪ್ರಕಾರ ಮತ್ತು ಸಾಂದ್ರತೆ ಪಡೆಯಿರಿ."},"aim":{"en":"To find the Hall coefficient, the type of charge carriers and their density in a semiconductor.","hi":"अर्धचालक का हॉल गुणांक, आवेश वाहकों का प्रकार और उनका घनत्व ज्ञात करना।","kn":"ಅರೆವಾಹಕದ ಹಾಲ್ ಗುಣಾಂಕ, ಆವೇಶ ವಾಹಕಗಳ ಪ್ರಕಾರ ಮತ್ತು ಅವುಗಳ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Charges moving through a slab in a perpendicular field B are pushed to one face until the electric field of the Hall voltage balances the magnetic force. V_H = IB ÷ (nqt), so R_H = V_H t ÷ (IB) = 1/(nq). Its sign tells whether the carriers are electrons or holes.","hi":"लंबवत क्षेत्र B में पट्टी से गुजरते आवेश एक सतह की ओर धकेले जाते हैं जब तक हॉल वोल्टता का विद्युत क्षेत्र चुंबकीय बल को संतुलित न कर दे। V_H = IB ÷ (nqt), अतः R_H = V_H t ÷ (IB) = 1/(nq). इसका चिह्न बताता है कि वाहक इलेक्ट्रॉन हैं या होल।","kn":"ಲಂಬ ಕ್ಷೇತ್ರ B ಯಲ್ಲಿ ಚಪ್ಪಡಿಯ ಮೂಲಕ ಚಲಿಸುವ ಆವೇಶಗಳು ಹಾಲ್ ವೋಲ್ಟೇಜ್‌ನ ವಿದ್ಯುತ್ ಕ್ಷೇತ್ರ ಕಾಂತೀಯ ಬಲವನ್ನು ಸಮತೋಲಿಸುವವರೆಗೆ ಒಂದು ಮುಖಕ್ಕೆ ತಳ್ಳಲ್ಪಡುತ್ತವೆ. V_H = IB ÷ (nqt); ಆದ್ದರಿಂದ R_H = V_H t ÷ (IB) = 1/(nq). ಅದರ ಚಿಹ್ನೆ ವಾಹಕಗಳು ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳೇ ರಂಧ್ರಗಳೇ ಎಂದು ತಿಳಿಸುತ್ತದೆ."},"apparatus":[{"en":"Hall probe (germanium slab, 0.5 mm thick)","hi":"हॉल प्रोब (जर्मेनियम पट्टी, 0.5 mm मोटी)","kn":"ಹಾಲ್ ಪ್ರೋಬ್ (ಜರ್ಮೇನಿಯಂ ಚಪ್ಪಡಿ, 0.5 mm ದಪ್ಪ)"},{"en":"Electromagnet with power supply","hi":"विद्युत आपूर्ति सहित विद्युत-चुंबक","kn":"ವಿದ್ಯುತ್ ಪೂರೈಕೆ ಸಹಿತ ವಿದ್ಯುತ್ಕಾಂತ"},{"en":"Gaussmeter","hi":"गॉसमीटर","kn":"ಗಾಸ್‌ಮೀಟರ್"},{"en":"Constant-current source and millivoltmeter","hi":"स्थिर-धारा स्रोत और मिलीवोल्टमीटर","kn":"ಸ್ಥಿರ-ಪ್ರವಾಹ ಮೂಲ ಮತ್ತು ಮಿಲಿವೋಲ್ಟ್‌ಮೀಟರ್"}],"steps":[{"en":"Place the probe between the pole pieces with its face perpendicular to B. Measure B with the gaussmeter.","hi":"प्रोब को ध्रुव खंडों के बीच, उसकी सतह B के लंबवत रखें। गॉसमीटर से B मापें।","kn":"ಪ್ರೋಬನ್ನು ಧ್ರುವ ತುಂಡುಗಳ ನಡುವೆ, ಅದರ ಮುಖ B ಗೆ ಲಂಬವಾಗಿರುವಂತೆ ಇಡಿ. ಗಾಸ್‌ಮೀಟರ್‌ನಿಂದ B ಅಳೆಯಿರಿ."},{"en":"Pass a current through the slab and read the Hall voltage.","hi":"पट्टी से धारा प्रवाहित करें और हॉल वोल्टता पढ़ें।","kn":"ಚಪ್ಪಡಿಯ ಮೂಲಕ ಪ್ರವಾಹ ಹರಿಸಿ ಹಾಲ್ ವೋಲ್ಟೇಜ್ ಓದಿ."},{"en":"Vary the current at fixed B, then B at fixed current.","hi":"नियत B पर धारा बदलें, फिर नियत धारा पर B बदलें।","kn":"ಸ್ಥಿರ B ಯಲ್ಲಿ ಪ್ರವಾಹ ಬದಲಿಸಿ, ನಂತರ ಸ್ಥಿರ ಪ್ರವಾಹದಲ್ಲಿ B ಬದಲಿಸಿ."},{"en":"Plot V_H against I; find R_H, the sign of the carriers and n.","hi":"V_H और I का ग्राफ़ बनाएँ; R_H, वाहकों का चिह्न और n ज्ञात करें।","kn":"V_H ಮತ್ತು I ನಕ್ಷೆ ಎಳೆಯಿರಿ; R_H, ವಾಹಕಗಳ ಚಿಹ್ನೆ ಮತ್ತು n ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Export the readings as CSV and work out the uncertainty from the fit.","hi":"पाठ्यांक CSV में निर्यात करें और फ़िट से अनिश्चितता निकालें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Do not exceed the rated probe current (it heats the slab).","hi":"प्रोब की निर्धारित धारा से अधिक न दें (पट्टी गरम होती है)।","kn":"ಪ್ರೋಬ್‌ನ ನಿಗದಿತ ಪ್ರವಾಹ ಮೀರಬೇಡಿ (ಚಪ್ಪಡಿ ಬಿಸಿಯಾಗುತ್ತದೆ)."},{"en":"Reverse B and I to cancel the offset voltage.","hi":"ऑफ़सेट वोल्टता मिटाने के लिए B और I उलटें।","kn":"ಆಫ್‌ಸೆಟ್ ವೋಲ್ಟೇಜ್ ರದ್ದುಗೊಳಿಸಲು B ಮತ್ತು I ಹಿಮ್ಮುಖಗೊಳಿಸಿ."},{"en":"The probe is fragile: handle it gently.","hi":"प्रोब नाज़ुक है: उसे धीरे से संभालें।","kn":"ಪ್ರೋಬ್ ನಾಜೂಕು: ಮೃದುವಾಗಿ ನಿರ್ವಹಿಸಿ."}],"conclusion":{"en":"V_H is proportional to both I and B; the Hall coefficient gives the sign and density of the carriers (about 10²¹ m⁻³ in doped germanium).","hi":"V_H, I और B दोनों के अनुक्रमानुपाती है; हॉल गुणांक वाहकों का चिह्न और घनत्व (मादित जर्मेनियम में लगभग 10²¹ m⁻³) देता है।","kn":"V_H, I ಮತ್ತು B ಎರಡಕ್ಕೂ ಅನುಪಾತೀಯ; ಹಾಲ್ ಗುಣಾಂಕ ವಾಹಕಗಳ ಚಿಹ್ನೆ ಮತ್ತು ಸಾಂದ್ರತೆ (ಡೋಪ್ ಮಾಡಿದ ಜರ್ಮೇನಿಯಂನಲ್ಲಿ ಸುಮಾರು 10²¹ m⁻³) ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why is the Hall voltage much larger in a semiconductor than in a metal?","hi":"अर्धचालक में हॉल वोल्टता धातु से बहुत अधिक क्यों होती है?","kn":"ಅರೆವಾಹಕದಲ್ಲಿ ಹಾಲ್ ವೋಲ್ಟೇಜ್ ಲೋಹಕ್ಕಿಂತ ಬಹಳ ಹೆಚ್ಚು ಏಕೆ?"},"a":{"en":"It has far fewer carriers, so they must drift faster to carry the same current.","hi":"उसमें वाहक बहुत कम होते हैं, इसलिए समान धारा के लिए उन्हें तेज़ बहना पड़ता है।","kn":"ಅದರಲ್ಲಿ ವಾಹಕಗಳು ಬಹಳ ಕಡಿಮೆ; ಅದೇ ಪ್ರವಾಹಕ್ಕೆ ಅವು ವೇಗವಾಗಿ ಹರಿಯಬೇಕು."}},{"q":{"en":"What is a Hall probe used for?","hi":"हॉल प्रोब किसके लिए प्रयोग होता है?","kn":"ಹಾಲ್ ಪ್ರೋಬನ್ನು ಯಾವುದಕ್ಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"To measure magnetic fields.","hi":"चुंबकीय क्षेत्र मापने के लिए।","kn":"ಕಾಂತ ಕ್ಷೇತ್ರಗಳನ್ನು ಅಳೆಯಲು."}},{"q":{"en":"What does a positive Hall coefficient mean?","hi":"धनात्मक हॉल गुणांक का क्या अर्थ है?","kn":"ಧನ ಹಾಲ್ ಗುಣಾಂಕದ ಅರ್ಥವೇನು?"},"a":{"en":"The majority carriers are holes (p-type).","hi":"बहुसंख्यक वाहक होल हैं (p-प्रकार)।","kn":"ಬಹುಸಂಖ್ಯಾತ ವಾಹಕಗಳು ರಂಧ್ರಗಳು (p-ಪ್ರಕಾರ)."}}]},{"id":"bh-curve","bench":"bh-curve","setup":{},"subject":"Physics","domain":"physics","levels":["ug"],"mode":"guided","curricula":["ug-physics"],"reviewed":false,"keywords":["hysteresis","b-h curve","retentivity","coercivity","ferromagnetism","magnetism and matter"],"title":{"en":"B–H curve (hysteresis) of soft iron","hi":"नरम लोहे का B–H वक्र (शैथिल्य)","kn":"ಮೃದು ಕಬ್ಬಿಣದ B–H ವಕ್ರ (ಹಿಸ್ಟರಿಸಿಸ್)"},"summary":{"en":"Take the magnetising field up and down and trace the hysteresis loop; read retentivity and coercivity.","hi":"चुंबकन क्षेत्र को ऊपर-नीचे करके शैथिल्य पाश बनाएँ; धारणशीलता और निग्राहिता पढ़ें।","kn":"ಕಾಂತೀಕರಣ ಕ್ಷೇತ್ರವನ್ನು ಏರಿಸಿ-ಇಳಿಸಿ ಹಿಸ್ಟರಿಸಿಸ್ ಕುಣಿಕೆ ಎಳೆಯಿರಿ; ಧಾರಣಶೀಲತೆ ಮತ್ತು ನಿಗ್ರಾಹಕತೆ ಓದಿ."},"aim":{"en":"To trace the B–H curve of a ferromagnetic material and find its retentivity and coercivity (a simplified model).","hi":"एक लौहचुंबकीय पदार्थ का B–H वक्र बनाना और उसकी धारणशीलता तथा निग्राहिता ज्ञात करना (सरलीकृत मॉडल)।","kn":"ಒಂದು ಫೆರೋಕಾಂತೀಯ ವಸ್ತುವಿನ B–H ವಕ್ರ ಎಳೆದು ಅದರ ಧಾರಣಶೀಲತೆ ಮತ್ತು ನಿಗ್ರಾಹಕತೆ ಕಂಡುಹಿಡಿಯುವುದು (ಸರಳೀಕೃತ ಮಾದರಿ)."},"principle":{"en":"In a ferromagnet B lags behind H: when H is brought back to zero some magnetism remains (retentivity), and a reverse field (coercivity) is needed to remove it. The loop’s area is the energy lost as heat per cycle. Soft iron has a narrow loop, steel a wide one. Here B = μ₀(H + Ms tanh((H ∓ Hc)/a)) stands in for the real material.","hi":"लौहचुंबक में B, H से पीछे रहता है: H को शून्य पर लाने पर कुछ चुंबकत्व बचा रहता है (धारणशीलता), और उसे हटाने के लिए उल्टा क्षेत्र (निग्राहिता) चाहिए। पाश का क्षेत्रफल प्रति चक्र ऊष्मा के रूप में खोई ऊर्जा है। नरम लोहे का पाश संकरा, स्टील का चौड़ा होता है। यहाँ B = μ₀(H + Ms tanh((H ∓ Hc)/a)) वास्तविक पदार्थ का स्थान लेता है।","kn":"ಫೆರೋಕಾಂತದಲ್ಲಿ B, H ಗಿಂತ ಹಿಂದುಳಿಯುತ್ತದೆ: H ಶೂನ್ಯಕ್ಕೆ ಬಂದಾಗ ಸ್ವಲ್ಪ ಕಾಂತತ್ವ ಉಳಿಯುತ್ತದೆ (ಧಾರಣಶೀಲತೆ); ಅದನ್ನು ತೆಗೆಯಲು ವಿರುದ್ಧ ಕ್ಷೇತ್ರ (ನಿಗ್ರಾಹಕತೆ) ಬೇಕು. ಕುಣಿಕೆಯ ವಿಸ್ತೀರ್ಣ ಪ್ರತಿ ಚಕ್ರಕ್ಕೆ ಉಷ್ಣವಾಗಿ ನಷ್ಟವಾದ ಶಕ್ತಿ. ಮೃದು ಕಬ್ಬಿಣದ ಕುಣಿಕೆ ಕಿರಿದು, ಉಕ್ಕಿನದು ಅಗಲ. ಇಲ್ಲಿ B = μ₀(H + Ms tanh((H ∓ Hc)/a)) ನಿಜ ವಸ್ತುವಿನ ಸ್ಥಾನದಲ್ಲಿದೆ."},"apparatus":[{"en":"Soft-iron ring (toroid) with primary and secondary windings","hi":"प्राथमिक और द्वितीयक कुंडलन सहित नरम लोहे का वलय (टोरॉइड)","kn":"ಪ್ರಾಥಮಿಕ ಮತ್ತು ದ್ವಿತೀಯಕ ಸುರುಳಿಗಳ ಸಹಿತ ಮೃದು ಕಬ್ಬಿಣದ ಉಂಗುರ (ಟೊರಾಯ್ಡ್)"},{"en":"Reversible DC supply and ammeter","hi":"प्रतिवर्ती DC आपूर्ति और ऐमीटर","kn":"ಹಿಮ್ಮುಖಗೊಳಿಸಬಹುದಾದ DC ಪೂರೈಕೆ ಮತ್ತು ಅಮ್ಮೀಟರ್"},{"en":"Fluxmeter (or ballistic galvanometer)","hi":"फ़्लक्समीटर (या प्रक्षेप्य गैल्वेनोमीटर)","kn":"ಫ್ಲಕ್ಸ್‌ಮೀಟರ್ (ಅಥವಾ ಬ್ಯಾಲಿಸ್ಟಿಕ್ ಗ್ಯಾಲ್ವನೋಮೀಟರ್)"},{"en":"Rheostat","hi":"धारा नियंत्रक (रिओस्टेट)","kn":"ರಿಯೋಸ್ಟಾಟ್"}],"steps":[{"en":"Demagnetise the ring, then raise H to its largest value (saturation).","hi":"वलय को विचुंबकित करें, फिर H को उसके सबसे बड़े मान (संतृप्ति) तक बढ़ाएँ।","kn":"ಉಂಗುರವನ್ನು ಕಾಂತರಹಿತಗೊಳಿಸಿ, ನಂತರ H ಅನ್ನು ಗರಿಷ್ಠ ಮೌಲ್ಯಕ್ಕೆ (ಸಂತೃಪ್ತಿ) ಏರಿಸಿ."},{"en":"Lower H in steps through zero to the largest negative value, recording B at each step.","hi":"H को चरणों में शून्य से होते हुए सबसे बड़े ऋणात्मक मान तक घटाएँ, हर चरण पर B लिखें।","kn":"H ಅನ್ನು ಹಂತಗಳಲ್ಲಿ ಶೂನ್ಯದ ಮೂಲಕ ಗರಿಷ್ಠ ಋಣ ಮೌಲ್ಯಕ್ಕೆ ಇಳಿಸಿ, ಪ್ರತಿ ಹಂತದಲ್ಲಿ B ದಾಖಲಿಸಿ."},{"en":"Raise H back to the positive maximum to close the loop.","hi":"पाश बंद करने के लिए H को फिर धनात्मक अधिकतम तक बढ़ाएँ।","kn":"ಕುಣಿಕೆ ಮುಚ್ಚಲು H ಅನ್ನು ಮತ್ತೆ ಧನ ಗರಿಷ್ಠಕ್ಕೆ ಏರಿಸಿ."},{"en":"Read the retentivity (B at H = 0) and the coercivity (H at B = 0).","hi":"धारणशीलता (H = 0 पर B) और निग्राहिता (B = 0 पर H) पढ़ें।","kn":"ಧಾರಣಶೀಲತೆ (H = 0 ನಲ್ಲಿ B) ಮತ್ತು ನಿಗ್ರಾಹಕತೆ (B = 0 ನಲ್ಲಿ H) ಓದಿ."},{"en":"Export the readings as CSV and work out the uncertainty from the fit.","hi":"पाठ्यांक CSV में निर्यात करें और फ़िट से अनिश्चितता निकालें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಹೊಂದಿಕೆಯಿಂದ ಅನಿಶ್ಚಿತತೆ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Change H in one direction at a time; never jump back and forth.","hi":"H को एक समय में एक ही दिशा में बदलें; आगे-पीछे न करें।","kn":"H ಅನ್ನು ಒಮ್ಮೆಗೆ ಒಂದೇ ದಿಕ್ಕಿನಲ್ಲಿ ಬದಲಿಸಿ; ಹಿಂದೆ-ಮುಂದೆ ಮಾಡಬೇಡಿ."},{"en":"Demagnetise the sample before starting.","hi":"शुरू करने से पहले नमूने को विचुंबकित करें।","kn":"ಆರಂಭಿಸುವ ಮೊದಲು ಮಾದರಿಯನ್ನು ಕಾಂತರಹಿತಗೊಳಿಸಿ."}],"conclusion":{"en":"B follows a closed loop that lags behind H; the ring keeps a large B at H = 0 (retentivity) but needs only a small reverse H to lose it (low coercivity), as for soft iron.","hi":"B एक बंद पाश पर चलता है जो H से पीछे रहता है; वलय H = 0 पर बड़ा B रखता है (धारणशीलता) पर उसे खोने के लिए छोटा उल्टा H काफ़ी है (कम निग्राहिता), जैसा नरम लोहे में होता है।","kn":"B, H ಗಿಂತ ಹಿಂದುಳಿಯುವ ಮುಚ್ಚಿದ ಕುಣಿಕೆಯನ್ನು ಅನುಸರಿಸುತ್ತದೆ; ಉಂಗುರ H = 0 ನಲ್ಲಿ ದೊಡ್ಡ B ಉಳಿಸಿಕೊಳ್ಳುತ್ತದೆ (ಧಾರಣಶೀಲತೆ), ಆದರೆ ಅದನ್ನು ಕಳೆಯಲು ಸಣ್ಣ ವಿರುದ್ಧ H ಸಾಕು (ಕಡಿಮೆ ನಿಗ್ರಾಹಕತೆ), ಮೃದು ಕಬ್ಬಿಣದಂತೆ."},"viva":[{"q":{"en":"Why is soft iron used for transformer cores?","hi":"ट्रांसफ़ॉर्मर के क्रोड में नरम लोहा क्यों प्रयोग होता है?","kn":"ಪರಿವರ್ತಕದ ತಿರುಳಿಗೆ ಮೃದು ಕಬ್ಬಿಣ ಏಕೆ?"},"a":{"en":"Its narrow loop means little energy is lost each cycle.","hi":"इसका संकरा पाश प्रति चक्र कम ऊर्जा हानि दर्शाता है।","kn":"ಅದರ ಕಿರಿದಾದ ಕುಣಿಕೆ ಪ್ರತಿ ಚಕ್ರದಲ್ಲಿ ಕಡಿಮೆ ಶಕ್ತಿ ನಷ್ಟ ಸೂಚಿಸುತ್ತದೆ."}},{"q":{"en":"Which material makes a good permanent magnet?","hi":"स्थायी चुंबक के लिए कौन-सा पदार्थ अच्छा है?","kn":"ಶಾಶ್ವತ ಕಾಂತಕ್ಕೆ ಯಾವ ವಸ್ತು ಉತ್ತಮ?"},"a":{"en":"One with high retentivity and high coercivity, like hard steel or alnico.","hi":"उच्च धारणशीलता और उच्च निग्राहिता वाला, जैसे कठोर स्टील या ऐल्निको।","kn":"ಹೆಚ್ಚು ಧಾರಣಶೀಲತೆ ಮತ್ತು ಹೆಚ್ಚು ನಿಗ್ರಾಹಕತೆಯದು, ಗಟ್ಟಿ ಉಕ್ಕು ಅಥವಾ ಆಲ್ನಿಕೋ ಹಾಗೆ."}},{"q":{"en":"What does the area of the loop represent?","hi":"पाश का क्षेत्रफल क्या दर्शाता है?","kn":"ಕುಣಿಕೆಯ ವಿಸ್ತೀರ್ಣ ಏನನ್ನು ಸೂಚಿಸುತ್ತದೆ?"},"a":{"en":"Energy lost as heat per unit volume per cycle.","hi":"प्रति चक्र प्रति इकाई आयतन ऊष्मा के रूप में खोई ऊर्जा।","kn":"ಪ್ರತಿ ಚಕ್ರಕ್ಕೆ ಪ್ರತಿ ಏಕಮಾನ ಘನಫಲಕ್ಕೆ ಉಷ್ಣವಾಗಿ ನಷ್ಟವಾದ ಶಕ್ತಿ."}}]},{"id":"titration-oxalic-naoh","bench":"titration","setup":{"pair":"oxalic-naoh"},"subject":"Chemistry","domain":"chemistry","levels":["11"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["titration","volumetric analysis","oxalic acid","sodium hydroxide","phenolphthalein","molarity","acid base titration"],"title":{"en":"Standardising NaOH with oxalic acid","hi":"ऑक्ज़ैलिक अम्ल से NaOH का मानकीकरण","kn":"ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದಿಂದ NaOH ಪ್ರಮಾಣೀಕರಣ"},"summary":{"en":"Titrate sodium hydroxide against standard oxalic acid with phenolphthalein and find its molarity.","hi":"फ़िनॉल्फ़्थेलिन के साथ सोडियम हाइड्रॉक्साइड का मानक ऑक्ज़ैलिक अम्ल से अनुमापन करें और उसकी मोलरता ज्ञात करें।","kn":"ಫೀನಾಲ್ಫ್ತಲೀನ್ ಬಳಸಿ ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡನ್ನು ಪ್ರಮಾಣಿತ ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ ಅದರ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To find the molarity of a given sodium hydroxide solution by titrating it against 0.05 M oxalic acid.","hi":"0.05 M ऑक्ज़ैलिक अम्ल से अनुमापन करके दिए गए सोडियम हाइड्रॉक्साइड विलयन की मोलरता ज्ञात करना।","kn":"0.05 M ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ ಕೊಟ್ಟ ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್ ದ್ರಾವಣದ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Oxalic acid is a dibasic acid: (COOH)₂ + 2NaOH → (COONa)₂ + 2H₂O. At the end point phenolphthalein turns from colourless to light pink. Moles of NaOH = 2 × moles of oxalic acid, so M(NaOH) = 2 × 0.05 × 10 ÷ titre.","hi":"ऑक्ज़ैलिक अम्ल द्विक्षारकी अम्ल है: (COOH)₂ + 2NaOH → (COONa)₂ + 2H₂O. अंतिम बिंदु पर फ़िनॉल्फ़्थेलिन रंगहीन से हल्का गुलाबी हो जाता है। NaOH के मोल = 2 × ऑक्ज़ैलिक अम्ल के मोल, अतः M(NaOH) = 2 × 0.05 × 10 ÷ अनुमापांक।","kn":"ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲ ದ್ವಿಕ್ಷಾರಕ ಆಮ್ಲ: (COOH)₂ + 2NaOH → (COONa)₂ + 2H₂O. ಅಂತ್ಯ ಬಿಂದುವಿನಲ್ಲಿ ಫೀನಾಲ್ಫ್ತಲೀನ್ ಬಣ್ಣರಹಿತದಿಂದ ತಿಳಿ ಗುಲಾಬಿಯಾಗುತ್ತದೆ. NaOH ಮೋಲ್ = 2 × ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ಮೋಲ್; ಆದ್ದರಿಂದ M(NaOH) = 2 × 0.05 × 10 ÷ ಅನುಮಾಪನಾಂಕ."},"apparatus":[{"en":"Burette (50 mL) with stand","hi":"स्टैंड सहित ब्यूरेट (50 mL)","kn":"ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)"},{"en":"Pipette (10 mL) and conical flask","hi":"पिपेट (10 mL) और शंक्वाकार फ्लास्क","kn":"ಪಿಪೆಟ್ (10 mL) ಮತ್ತು ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್"},{"en":"White tile and funnel","hi":"सफ़ेद टाइल और कीप","kn":"ಬಿಳಿ ಟೈಲ್ ಮತ್ತು ಆಲಿಕೆ"},{"en":"0.05 M oxalic acid and phenolphthalein","hi":"0.05 M ऑक्ज़ैलिक अम्ल और फ़िनॉल्फ़्थेलिन","kn":"0.05 M ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲ ಮತ್ತು ಫೀನಾಲ್ಫ್ತಲೀನ್"},{"en":"Sodium hydroxide solution (unknown)","hi":"सोडियम हाइड्रॉक्साइड विलयन (अज्ञात)","kn":"ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್ ದ್ರಾವಣ (ಅಜ್ಞಾತ)"}],"steps":[{"en":"Rinse and fill the burette; note the initial reading.","hi":"ब्यूरेट धोकर भरें; प्रारंभिक पाठ्यांक लिखें।","kn":"ಬ್ಯೂರೆಟ್ ತೊಳೆದು ತುಂಬಿ; ಆರಂಭಿಕ ಓದು ಬರೆಯಿರಿ."},{"en":"Pipette 10 mL of the solution into the conical flask (add the indicator or acid as needed).","hi":"शंक्वाकार फ्लास्क में 10 mL विलयन पिपेट से लें (आवश्यक हो तो सूचक या अम्ल मिलाएँ)।","kn":"ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್‌ಗೆ ಪಿಪೆಟ್‌ನಿಂದ 10 mL ದ್ರಾವಣ ಹಾಕಿ (ಬೇಕಾದರೆ ಸೂಚಕ ಅಥವಾ ಆಮ್ಲ ಸೇರಿಸಿ)."},{"en":"Run in the titrant, swirling, until one drop gives a permanent colour change. Record the final reading.","hi":"घुमाते हुए अनुमापक डालें जब तक एक बूँद से स्थायी रंग परिवर्तन न हो। अंतिम पाठ्यांक लिखें।","kn":"ತಿರುಗಿಸುತ್ತಾ ಅನುಮಾಪಕ ಸೇರಿಸಿ, ಒಂದು ಹನಿ ಶಾಶ್ವತ ಬಣ್ಣ ಬದಲಾವಣೆ ತರುವವರೆಗೆ. ಅಂತಿಮ ಓದು ದಾಖಲಿಸಿ."},{"en":"Repeat until three readings agree within 0.1 mL.","hi":"तीन पाठ्यांक 0.1 mL के भीतर मेल खाने तक दोहराएँ।","kn":"ಮೂರು ಓದುಗಳು 0.1 mL ಒಳಗೆ ಹೊಂದುವವರೆಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Use the mean titre and the mole ratio to find the unknown molarity.","hi":"माध्य अनुमापांक और मोल अनुपात से अज्ञात मोलरता ज्ञात करें।","kn":"ಸರಾಸರಿ ಅನುಮಾಪನಾಂಕ ಮತ್ತು ಮೋಲ್ ಅನುಪಾತದಿಂದ ಅಜ್ಞಾತ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Rinse the burette with the solution it will hold, and the pipette with the solution it will measure.","hi":"ब्यूरेट को उसी विलयन से धोएँ जो उसमें भरना है, और पिपेट को उसी से जिसे वह मापेगी।","kn":"ಬ್ಯೂರೆಟನ್ನು ಅದರಲ್ಲಿ ತುಂಬುವ ದ್ರಾವಣದಿಂದ, ಪಿಪೆಟನ್ನು ಅದು ಅಳೆಯುವ ದ್ರಾವಣದಿಂದ ತೊಳೆಯಿರಿ."},{"en":"Remove air bubbles from the burette nozzle and read the lower meniscus at eye level.","hi":"ब्यूरेट की नोक से वायु बुलबुले निकालें और निचला नवचंद्रक आँख के स्तर पर पढ़ें।","kn":"ಬ್ಯೂರೆಟ್ ನಳಿಕೆಯಿಂದ ಗಾಳಿ ಗುಳ್ಳೆ ತೆಗೆದು ಕೆಳಗಿನ ಮೆನಿಸ್ಕಸನ್ನು ಕಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ಓದಿ."},{"en":"Near the end point add the titrant drop by drop, swirling the flask.","hi":"अंतिम बिंदु के पास अनुमापक बूँद-बूँद डालें और फ्लास्क घुमाते रहें।","kn":"ಅಂತ್ಯ ಬಿಂದುವಿನ ಹತ್ತಿರ ಅನುಮಾಪಕವನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ, ಫ್ಲಾಸ್ಕ್ ತಿರುಗಿಸುತ್ತಿರಿ."},{"en":"Take at least three concordant readings (within 0.1 mL).","hi":"कम से कम तीन सहमत पाठ्यांक लें (0.1 mL के भीतर)।","kn":"ಕನಿಷ್ಠ ಮೂರು ಹೊಂದಿಕೆಯ ಓದುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಿ (0.1 mL ಒಳಗೆ)."}],"conclusion":{"en":"Concordant titres give the molarity of the sodium hydroxide; the end point is the first permanent light pink.","hi":"सहमत अनुमापांक सोडियम हाइड्रॉक्साइड की मोलरता देते हैं; अंतिम बिंदु पहला स्थायी हल्का गुलाबी रंग है।","kn":"ಹೊಂದಿಕೆಯ ಅನುಮಾಪನಾಂಕಗಳು ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್‌ನ ಮೋಲಾರಿಟಿ ನೀಡುತ್ತವೆ; ಅಂತ್ಯ ಬಿಂದು ಮೊದಲ ಶಾಶ್ವತ ತಿಳಿ ಗುಲಾಬಿ."},"viva":[{"q":{"en":"Why is NaOH not a primary standard?","hi":"NaOH प्राथमिक मानक क्यों नहीं है?","kn":"NaOH ಪ್ರಾಥಮಿಕ ಮಾನಕ ಏಕೆ ಅಲ್ಲ?"},"a":{"en":"It absorbs moisture and carbon dioxide from the air, so its mass is not exact.","hi":"यह वायु से नमी और कार्बन डाइऑक्साइड सोखता है, इसलिए उसका द्रव्यमान सटीक नहीं रहता।","kn":"ಅದು ಗಾಳಿಯಿಂದ ತೇವಾಂಶ ಮತ್ತು ಕಾರ್ಬನ್ ಡೈಆಕ್ಸೈಡ್ ಹೀರುತ್ತದೆ; ಆದ್ದರಿಂದ ಅದರ ದ್ರವ್ಯರಾಶಿ ನಿಖರವಲ್ಲ."}},{"q":{"en":"Why is phenolphthalein used and not methyl orange?","hi":"मेथिल ऑरेंज के स्थान पर फ़िनॉल्फ़्थेलिन क्यों?","kn":"ಮೀಥೈಲ್ ಆರೆಂಜ್ ಬದಲು ಫೀನಾಲ್ಫ್ತಲೀನ್ ಏಕೆ?"},"a":{"en":"Oxalic acid is weak: the pH jump at the end point lies in the basic range where phenolphthalein changes.","hi":"ऑक्ज़ैलिक अम्ल दुर्बल है: अंतिम बिंदु पर pH उछाल क्षारीय परास में है जहाँ फ़िनॉल्फ़्थेलिन बदलता है।","kn":"ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲ ದುರ್ಬಲ: ಅಂತ್ಯ ಬಿಂದುವಿನ pH ಜಿಗಿತ ಕ್ಷಾರೀಯ ವ್ಯಾಪ್ತಿಯಲ್ಲಿದೆ, ಅಲ್ಲಿ ಫೀನಾಲ್ಫ್ತಲೀನ್ ಬದಲಾಗುತ್ತದೆ."}},{"q":{"en":"What is the molar mass of hydrated oxalic acid?","hi":"जलयोजित ऑक्ज़ैलिक अम्ल का मोलर द्रव्यमान क्या है?","kn":"ಜಲಯುಕ್ತ ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ಮೋಲಾರ್ ದ್ರವ್ಯರಾಶಿ ಎಷ್ಟು?"},"a":{"en":"126 g/mol ((COOH)₂·2H₂O).","hi":"126 g/mol ((COOH)₂·2H₂O, जल के दो अणुओं सहित)।","kn":"126 g/mol ((COOH)₂·2H₂O, ಎರಡು ನೀರಿನ ಅಣುಗಳೊಂದಿಗೆ)."}}]},{"id":"titration-hcl-naoh","bench":"titration","setup":{"pair":"hcl-naoh"},"subject":"Chemistry","domain":"chemistry","levels":["10","11"],"mode":"guided","curricula":["cbse","ncert","ka-sslc"],"reviewed":false,"keywords":["titration","neutralisation","neutralization","hydrochloric acid","sodium hydroxide","acids bases and salts","indicator"],"title":{"en":"Strength of hydrochloric acid by titration","hi":"अनुमापन द्वारा हाइड्रोक्लोरिक अम्ल की प्रबलता","kn":"ಅನುಮಾಪನದಿಂದ ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಪ್ರಬಲತೆ"},"summary":{"en":"Neutralise samples of hydrochloric acid with 0.1 M NaOH; try both indicators and find each sample’s molarity.","hi":"हाइड्रोक्लोरिक अम्ल के नमूनों को 0.1 M NaOH से उदासीन करें; दोनों सूचक आज़माएँ और हर नमूने की मोलरता ज्ञात करें।","kn":"ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಮಾದರಿಗಳನ್ನು 0.1 M NaOH ನಿಂದ ತಟಸ್ಥಗೊಳಿಸಿ; ಎರಡೂ ಸೂಚಕಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ ಪ್ರತಿ ಮಾದರಿಯ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To find the molarity of hydrochloric acid by titrating it with 0.1 M sodium hydroxide.","hi":"0.1 M सोडियम हाइड्रॉक्साइड से अनुमापन करके हाइड्रोक्लोरिक अम्ल की मोलरता ज्ञात करना।","kn":"0.1 M ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್‌ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"HCl + NaOH → NaCl + H₂O, one mole to one. For a strong acid and strong base the pH jumps from about 4 to 10 at the end point, so phenolphthalein and methyl orange both work. M₁V₁ = M₂V₂.","hi":"HCl + NaOH → NaCl + H₂O, एक मोल से एक मोल। प्रबल अम्ल और प्रबल क्षार के लिए अंतिम बिंदु पर pH लगभग 4 से 10 तक उछलता है, इसलिए फ़िनॉल्फ़्थेलिन और मेथिल ऑरेंज दोनों काम करते हैं। M₁V₁ = M₂V₂.","kn":"HCl + NaOH → NaCl + H₂O, ಒಂದು ಮೋಲ್‌ಗೆ ಒಂದು. ಪ್ರಬಲ ಆಮ್ಲ ಮತ್ತು ಪ್ರಬಲ ಕ್ಷಾರಕ್ಕೆ ಅಂತ್ಯ ಬಿಂದುವಿನಲ್ಲಿ pH ಸುಮಾರು 4 ರಿಂದ 10 ಕ್ಕೆ ಜಿಗಿಯುತ್ತದೆ; ಆದ್ದರಿಂದ ಫೀನಾಲ್ಫ್ತಲೀನ್ ಮತ್ತು ಮೀಥೈಲ್ ಆರೆಂಜ್ ಎರಡೂ ಕೆಲಸ ಮಾಡುತ್ತವೆ. M₁V₁ = M₂V₂."},"apparatus":[{"en":"Burette (50 mL) with stand","hi":"स्टैंड सहित ब्यूरेट (50 mL)","kn":"ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)"},{"en":"Pipette (10 mL) and conical flask","hi":"पिपेट (10 mL) और शंक्वाकार फ्लास्क","kn":"ಪಿಪೆಟ್ (10 mL) ಮತ್ತು ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್"},{"en":"White tile and funnel","hi":"सफ़ेद टाइल और कीप","kn":"ಬಿಳಿ ಟೈಲ್ ಮತ್ತು ಆಲಿಕೆ"},{"en":"0.1 M NaOH; phenolphthalein and methyl orange","hi":"0.1 M NaOH; फ़िनॉल्फ़्थेलिन और मेथिल ऑरेंज","kn":"0.1 M NaOH; ಫೀನಾಲ್ಫ್ತಲೀನ್ ಮತ್ತು ಮೀಥೈಲ್ ಆರೆಂಜ್"},{"en":"Hydrochloric acid samples A, B, C","hi":"हाइड्रोक्लोरिक अम्ल के नमूने A, B, C","kn":"ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲ ಮಾದರಿಗಳು A, B, C"}],"steps":[{"en":"Rinse and fill the burette; note the initial reading.","hi":"ब्यूरेट धोकर भरें; प्रारंभिक पाठ्यांक लिखें।","kn":"ಬ್ಯೂರೆಟ್ ತೊಳೆದು ತುಂಬಿ; ಆರಂಭಿಕ ಓದು ಬರೆಯಿರಿ."},{"en":"Pipette 10 mL of the solution into the conical flask (add the indicator or acid as needed).","hi":"शंक्वाकार फ्लास्क में 10 mL विलयन पिपेट से लें (आवश्यक हो तो सूचक या अम्ल मिलाएँ)।","kn":"ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್‌ಗೆ ಪಿಪೆಟ್‌ನಿಂದ 10 mL ದ್ರಾವಣ ಹಾಕಿ (ಬೇಕಾದರೆ ಸೂಚಕ ಅಥವಾ ಆಮ್ಲ ಸೇರಿಸಿ)."},{"en":"Run in the titrant, swirling, until one drop gives a permanent colour change. Record the final reading.","hi":"घुमाते हुए अनुमापक डालें जब तक एक बूँद से स्थायी रंग परिवर्तन न हो। अंतिम पाठ्यांक लिखें।","kn":"ತಿರುಗಿಸುತ್ತಾ ಅನುಮಾಪಕ ಸೇರಿಸಿ, ಒಂದು ಹನಿ ಶಾಶ್ವತ ಬಣ್ಣ ಬದಲಾವಣೆ ತರುವವರೆಗೆ. ಅಂತಿಮ ಓದು ದಾಖಲಿಸಿ."},{"en":"Repeat until three readings agree within 0.1 mL.","hi":"तीन पाठ्यांक 0.1 mL के भीतर मेल खाने तक दोहराएँ।","kn":"ಮೂರು ಓದುಗಳು 0.1 mL ಒಳಗೆ ಹೊಂದುವವರೆಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Use the mean titre and the mole ratio to find the unknown molarity.","hi":"माध्य अनुमापांक और मोल अनुपात से अज्ञात मोलरता ज्ञात करें।","kn":"ಸರಾಸರಿ ಅನುಮಾಪನಾಂಕ ಮತ್ತು ಮೋಲ್ ಅನುಪಾತದಿಂದ ಅಜ್ಞಾತ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Rinse the burette with the solution it will hold, and the pipette with the solution it will measure.","hi":"ब्यूरेट को उसी विलयन से धोएँ जो उसमें भरना है, और पिपेट को उसी से जिसे वह मापेगी।","kn":"ಬ್ಯೂರೆಟನ್ನು ಅದರಲ್ಲಿ ತುಂಬುವ ದ್ರಾವಣದಿಂದ, ಪಿಪೆಟನ್ನು ಅದು ಅಳೆಯುವ ದ್ರಾವಣದಿಂದ ತೊಳೆಯಿರಿ."},{"en":"Remove air bubbles from the burette nozzle and read the lower meniscus at eye level.","hi":"ब्यूरेट की नोक से वायु बुलबुले निकालें और निचला नवचंद्रक आँख के स्तर पर पढ़ें।","kn":"ಬ್ಯೂರೆಟ್ ನಳಿಕೆಯಿಂದ ಗಾಳಿ ಗುಳ್ಳೆ ತೆಗೆದು ಕೆಳಗಿನ ಮೆನಿಸ್ಕಸನ್ನು ಕಣ್ಣಿನ ಮಟ್ಟದಲ್ಲಿ ಓದಿ."},{"en":"Near the end point add the titrant drop by drop, swirling the flask.","hi":"अंतिम बिंदु के पास अनुमापक बूँद-बूँद डालें और फ्लास्क घुमाते रहें।","kn":"ಅಂತ್ಯ ಬಿಂದುವಿನ ಹತ್ತಿರ ಅನುಮಾಪಕವನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ, ಫ್ಲಾಸ್ಕ್ ತಿರುಗಿಸುತ್ತಿರಿ."},{"en":"Wear safety goggles; acids and alkalis harm the eyes.","hi":"सुरक्षा चश्मा पहनें; अम्ल और क्षार आँखों को हानि पहुँचाते हैं।","kn":"ಸುರಕ್ಷಾ ಕನ್ನಡಕ ಧರಿಸಿ; ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರಗಳು ಕಣ್ಣಿಗೆ ಹಾನಿ ಮಾಡುತ್ತವೆ."}],"conclusion":{"en":"Each sample’s molarity follows from M₁V₁ = M₂V₂; both indicators give the same end point for a strong acid and strong base.","hi":"हर नमूने की मोलरता M₁V₁ = M₂V₂ से मिलती है; प्रबल अम्ल-प्रबल क्षार के लिए दोनों सूचक एक ही अंतिम बिंदु देते हैं।","kn":"ಪ್ರತಿ ಮಾದರಿಯ ಮೋಲಾರಿಟಿ M₁V₁ = M₂V₂ ನಿಂದ ಸಿಗುತ್ತದೆ; ಪ್ರಬಲ ಆಮ್ಲ-ಪ್ರಬಲ ಕ್ಷಾರಕ್ಕೆ ಎರಡೂ ಸೂಚಕಗಳು ಒಂದೇ ಅಂತ್ಯ ಬಿಂದು ನೀಡುತ್ತವೆ."},"viva":[{"q":{"en":"What is neutralisation?","hi":"उदासीनीकरण क्या है?","kn":"ತಟಸ್ಥೀಕರಣ ಎಂದರೇನು?"},"a":{"en":"The reaction of an acid and a base to form a salt and water.","hi":"अम्ल और क्षार की अभिक्रिया जिसमें लवण और जल बनते हैं।","kn":"ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರ ಪ್ರತಿಕ್ರಿಯಿಸಿ ಲವಣ ಮತ್ತು ನೀರು ಉಂಟಾಗುವುದು."}},{"q":{"en":"What is the pH at the end point here?","hi":"यहाँ अंतिम बिंदु पर pH कितना है?","kn":"ಇಲ್ಲಿ ಅಂತ್ಯ ಬಿಂದುವಿನ pH ಎಷ್ಟು?"},"a":{"en":"7: NaCl solution is neutral.","hi":"7: NaCl विलयन उदासीन है।","kn":"7: NaCl ದ್ರಾವಣ ತಟಸ್ಥ."}},{"q":{"en":"Why is a white tile placed under the flask?","hi":"फ्लास्क के नीचे सफ़ेद टाइल क्यों रखते हैं?","kn":"ಫ್ಲಾಸ್ಕ್ ಕೆಳಗೆ ಬಿಳಿ ಟೈಲ್ ಏಕೆ ಇಡುತ್ತಾರೆ?"},"a":{"en":"To see the first faint colour change clearly.","hi":"पहला हल्का रंग परिवर्तन साफ़ देखने के लिए।","kn":"ಮೊದಲ ಮಸುಕಾದ ಬಣ್ಣ ಬದಲಾವಣೆ ಸ್ಪಷ್ಟವಾಗಿ ಕಾಣಲು."}}]},{"id":"kmno4-oxalic","bench":"titration","setup":{"pair":"kmno4-oxalic"},"subject":"Chemistry","domain":"chemistry","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["redox titration","potassium permanganate","kmno4","oxalic acid","volumetric analysis","self indicator"],"title":{"en":"KMnO₄ against oxalic acid (redox titration)","hi":"ऑक्ज़ैलिक अम्ल से KMnO₄ का अनुमापन (रेडॉक्स)","kn":"ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ವಿರುದ್ಧ KMnO₄ (ರೆಡಾಕ್ಸ್ ಅನುಮಾಪನ)"},"summary":{"en":"Titrate hot acidified oxalic acid with potassium permanganate until a permanent pink appears.","hi":"गरम अम्लीकृत ऑक्ज़ैलिक अम्ल का पोटैशियम परमैंगनेट से तब तक अनुमापन करें जब तक स्थायी गुलाबी रंग न आए।","kn":"ಬಿಸಿ ಆಮ್ಲೀಕೃತ ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲವನ್ನು ಶಾಶ್ವತ ಗುಲಾಬಿ ಬರುವವರೆಗೆ ಪೊಟ್ಯಾಸಿಯಂ ಪರ್ಮ್ಯಾಂಗನೇಟ್‌ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ."},"aim":{"en":"To find the molarity of a KMnO₄ solution by titrating it against 0.05 M oxalic acid.","hi":"0.05 M ऑक्ज़ैलिक अम्ल से अनुमापन करके KMnO₄ विलयन की मोलरता ज्ञात करना।","kn":"0.05 M ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲದ ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ KMnO₄ ದ್ರಾವಣದ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"In acid, 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O. The flask is warmed to 60–70 °C to speed the reaction. So M(KMnO₄) = (2/5) × 0.05 × 10 ÷ titre.","hi":"अम्ल में 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O. अभिक्रिया तेज़ करने के लिए फ्लास्क 60–70 °C तक गरम किया जाता है। अतः M(KMnO₄) = (2/5) × 0.05 × 10 ÷ अनुमापांक।","kn":"ಆಮ್ಲದಲ್ಲಿ 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O. ಪ್ರತಿಕ್ರಿಯೆ ವೇಗಗೊಳಿಸಲು ಫ್ಲಾಸ್ಕನ್ನು 60–70 °C ಗೆ ಬಿಸಿಮಾಡುತ್ತಾರೆ. ಆದ್ದರಿಂದ M(KMnO₄) = (2/5) × 0.05 × 10 ÷ ಅನುಮಾಪನಾಂಕ."},"apparatus":[{"en":"Burette (50 mL) with stand","hi":"स्टैंड सहित ब्यूरेट (50 mL)","kn":"ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)"},{"en":"Pipette (10 mL) and conical flask","hi":"पिपेट (10 mL) और शंक्वाकार फ्लास्क","kn":"ಪಿಪೆಟ್ (10 mL) ಮತ್ತು ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್"},{"en":"0.05 M oxalic acid and dilute H₂SO₄","hi":"0.05 M ऑक्ज़ैलिक अम्ल और तनु H₂SO₄","kn":"0.05 M ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲ ಮತ್ತು ವಿರಳ H₂SO₄"},{"en":"KMnO₄ solution (unknown)","hi":"KMnO₄ विलयन (अज्ञात)","kn":"KMnO₄ ದ್ರಾವಣ (ಅಜ್ಞಾತ)"},{"en":"Burner, wire gauze and thermometer","hi":"बर्नर, तार की जाली और तापमापी","kn":"ಬರ್ನರ್, ತಂತಿ ಜಾಲರಿ ಮತ್ತು ತಾಪಮಾಪಕ"}],"steps":[{"en":"Rinse and fill the burette; note the initial reading.","hi":"ब्यूरेट धोकर भरें; प्रारंभिक पाठ्यांक लिखें।","kn":"ಬ್ಯೂರೆಟ್ ತೊಳೆದು ತುಂಬಿ; ಆರಂಭಿಕ ಓದು ಬರೆಯಿರಿ."},{"en":"Pipette 10 mL of the solution into the conical flask (add the indicator or acid as needed).","hi":"शंक्वाकार फ्लास्क में 10 mL विलयन पिपेट से लें (आवश्यक हो तो सूचक या अम्ल मिलाएँ)।","kn":"ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್‌ಗೆ ಪಿಪೆಟ್‌ನಿಂದ 10 mL ದ್ರಾವಣ ಹಾಕಿ (ಬೇಕಾದರೆ ಸೂಚಕ ಅಥವಾ ಆಮ್ಲ ಸೇರಿಸಿ)."},{"en":"Run in the titrant, swirling, until one drop gives a permanent colour change. Record the final reading.","hi":"घुमाते हुए अनुमापक डालें जब तक एक बूँद से स्थायी रंग परिवर्तन न हो। अंतिम पाठ्यांक लिखें।","kn":"ತಿರುಗಿಸುತ್ತಾ ಅನುಮಾಪಕ ಸೇರಿಸಿ, ಒಂದು ಹನಿ ಶಾಶ್ವತ ಬಣ್ಣ ಬದಲಾವಣೆ ತರುವವರೆಗೆ. ಅಂತಿಮ ಓದು ದಾಖಲಿಸಿ."},{"en":"Repeat until three readings agree within 0.1 mL.","hi":"तीन पाठ्यांक 0.1 mL के भीतर मेल खाने तक दोहराएँ।","kn":"ಮೂರು ಓದುಗಳು 0.1 mL ಒಳಗೆ ಹೊಂದುವವರೆಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Use the mean titre and the mole ratio to find the unknown molarity.","hi":"माध्य अनुमापांक और मोल अनुपात से अज्ञात मोलरता ज्ञात करें।","kn":"ಸರಾಸರಿ ಅನುಮಾಪನಾಂಕ ಮತ್ತು ಮೋಲ್ ಅನುಪಾತದಿಂದ ಅಜ್ಞಾತ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Rinse the burette with the solution it will hold, and the pipette with the solution it will measure.","hi":"ब्यूरेट को उसी विलयन से धोएँ जो उसमें भरना है, और पिपेट को उसी से जिसे वह मापेगी।","kn":"ಬ್ಯೂರೆಟನ್ನು ಅದರಲ್ಲಿ ತುಂಬುವ ದ್ರಾವಣದಿಂದ, ಪಿಪೆಟನ್ನು ಅದು ಅಳೆಯುವ ದ್ರಾವಣದಿಂದ ತೊಳೆಯಿರಿ."},{"en":"Read the upper meniscus of KMnO₄: it is too dark to see the lower one.","hi":"KMnO₄ का ऊपरी नवचंद्रक पढ़ें: निचला देखने के लिए यह बहुत गहरा है।","kn":"KMnO₄ ನ ಮೇಲಿನ ಮೆನಿಸ್ಕಸ್ ಓದಿ: ಕೆಳಗಿನದು ಕಾಣಲು ಅದು ತುಂಬ ಗಾಢ."},{"en":"Near the end point add the titrant drop by drop, swirling the flask.","hi":"अंतिम बिंदु के पास अनुमापक बूँद-बूँद डालें और फ्लास्क घुमाते रहें।","kn":"ಅಂತ್ಯ ಬಿಂದುವಿನ ಹತ್ತಿರ ಅನುಮಾಪಕವನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ, ಫ್ಲಾಸ್ಕ್ ತಿರುಗಿಸುತ್ತಿರಿ."},{"en":"Add enough dilute H₂SO₄; never use HCl or HNO₃ to acidify.","hi":"पर्याप्त तनु H₂SO₄ डालें; अम्लीकरण के लिए HCl या HNO₃ कभी न लें।","kn":"ಸಾಕಷ್ಟು ವಿರಳ H₂SO₄ ಸೇರಿಸಿ; ಆಮ್ಲೀಕರಣಕ್ಕೆ HCl ಅಥವಾ HNO₃ ಎಂದೂ ಬಳಸಬೇಡಿ."}],"conclusion":{"en":"The first permanent pink marks the end point; the mean titre gives the molarity of KMnO₄ through the 2 : 5 mole ratio.","hi":"पहला स्थायी गुलाबी रंग अंतिम बिंदु है; माध्य अनुमापांक 2 : 5 मोल अनुपात से KMnO₄ की मोलरता देता है।","kn":"ಮೊದಲ ಶಾಶ್ವತ ಗುಲಾಬಿ ಅಂತ್ಯ ಬಿಂದು; ಸರಾಸರಿ ಅನುಮಾಪನಾಂಕ 2 : 5 ಮೋಲ್ ಅನುಪಾತದ ಮೂಲಕ KMnO₄ ನ ಮೋಲಾರಿಟಿ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why is no indicator needed?","hi":"सूचक की आवश्यकता क्यों नहीं?","kn":"ಸೂಚಕ ಏಕೆ ಬೇಕಿಲ್ಲ?"},"a":{"en":"KMnO₄ is its own indicator: the first excess drop turns the solution pink.","hi":"KMnO₄ स्वयं सूचक है: पहली अतिरिक्त बूँद विलयन को गुलाबी कर देती है।","kn":"KMnO₄ ತಾನೇ ಸೂಚಕ: ಮೊದಲ ಹೆಚ್ಚುವರಿ ಹನಿ ದ್ರಾವಣವನ್ನು ಗುಲಾಬಿಯಾಗಿಸುತ್ತದೆ."}},{"q":{"en":"Why is HCl not used to acidify?","hi":"अम्लीकरण के लिए HCl क्यों नहीं?","kn":"ಆಮ್ಲೀಕರಣಕ್ಕೆ HCl ಏಕೆ ಅಲ್ಲ?"},"a":{"en":"KMnO₄ would oxidise chloride ions to chlorine, using up extra titrant.","hi":"KMnO₄ क्लोराइड आयनों को क्लोरीन में ऑक्सीकृत कर अतिरिक्त अनुमापक खपा देगा।","kn":"KMnO₄ ಕ್ಲೋರೈಡ್ ಅಯಾನುಗಳನ್ನು ಕ್ಲೋರಿನ್ ಆಗಿ ಉತ್ಕರ್ಷಿಸಿ ಹೆಚ್ಚುವರಿ ಅನುಮಾಪಕ ಬಳಸುತ್ತದೆ."}},{"q":{"en":"What is the oxidation state of Mn in KMnO₄, and after the reaction?","hi":"KMnO₄ में और अभिक्रिया के बाद Mn की ऑक्सीकरण अवस्था क्या है?","kn":"KMnO₄ ನಲ್ಲಿ ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆಯ ನಂತರ Mn ನ ಉತ್ಕರ್ಷಣ ಸ್ಥಿತಿ ಏನು?"},"a":{"en":"+7, reduced to +2 (Mn²⁺) in acid.","hi":"+7, अम्ल में +2 (Mn²⁺) तक अपचयित।","kn":"+7, ಆಮ್ಲದಲ್ಲಿ +2 (Mn²⁺) ಗೆ ಅಪಕರ್ಷಿತ."}},{"q":{"en":"Why is the oxalic acid heated?","hi":"ऑक्ज़ैलिक अम्ल को गरम क्यों करते हैं?","kn":"ಆಕ್ಸಾಲಿಕ್ ಆಮ್ಲವನ್ನು ಏಕೆ ಬಿಸಿಮಾಡುತ್ತಾರೆ?"},"a":{"en":"The reaction is slow at room temperature; Mn²⁺ formed later catalyses it.","hi":"कमरे के ताप पर अभिक्रिया धीमी है; बाद में बना Mn²⁺ उसे उत्प्रेरित करता है।","kn":"ಕೋಣೆಯ ತಾಪದಲ್ಲಿ ಪ್ರತಿಕ್ರಿಯೆ ನಿಧಾನ; ನಂತರ ಉಂಟಾದ Mn²⁺ ಅದನ್ನು ವೇಗವರ್ಧಿಸುತ್ತದೆ."}}]},{"id":"kmno4-mohr","bench":"titration","setup":{"pair":"kmno4-mohr"},"subject":"Chemistry","domain":"chemistry","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["redox titration","potassium permanganate","mohr's salt","ferrous ammonium sulphate","volumetric analysis"],"title":{"en":"KMnO₄ against Mohr's salt (redox titration)","hi":"मोर लवण से KMnO₄ का अनुमापन (रेडॉक्स)","kn":"ಮೋರ್ ಲವಣದ ವಿರುದ್ಧ KMnO₄ (ರೆಡಾಕ್ಸ್ ಅನುಮಾಪನ)"},"summary":{"en":"Titrate acidified Mohr's salt with potassium permanganate at room temperature.","hi":"कमरे के ताप पर अम्लीकृत मोर लवण का पोटैशियम परमैंगनेट से अनुमापन करें।","kn":"ಕೋಣೆಯ ತಾಪದಲ್ಲಿ ಆಮ್ಲೀಕೃತ ಮೋರ್ ಲವಣವನ್ನು ಪೊಟ್ಯಾಸಿಯಂ ಪರ್ಮ್ಯಾಂಗನೇಟ್‌ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ."},"aim":{"en":"To find the molarity of KMnO₄ by titrating it against 0.1 M Mohr's salt (ferrous ammonium sulphate).","hi":"0.1 M मोर लवण (फ़ेरस अमोनियम सल्फ़ेट) से अनुमापन करके KMnO₄ की मोलरता ज्ञात करना।","kn":"0.1 M ಮೋರ್ ಲವಣದ (ಫೆರಸ್ ಅಮೋನಿಯಂ ಸಲ್ಫೇಟ್) ವಿರುದ್ಧ ಅನುಮಾಪನ ಮಾಡಿ KMnO₄ ನ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O. One permanganate oxidises five iron(II) ions, so M(KMnO₄) = 0.1 × 10 ÷ (5 × titre). Heating is not needed: it would oxidise Fe²⁺ in air.","hi":"MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O. एक परमैंगनेट पाँच आयरन(II) आयनों को ऑक्सीकृत करता है, अतः M(KMnO₄) = 0.1 × 10 ÷ (5 × अनुमापांक)। गरम करना नहीं चाहिए: इससे Fe²⁺ वायु में ऑक्सीकृत हो जाएगा।","kn":"MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O. ಒಂದು ಪರ್ಮ್ಯಾಂಗನೇಟ್ ಐದು ಕಬ್ಬಿಣ(II) ಅಯಾನುಗಳನ್ನು ಉತ್ಕರ್ಷಿಸುತ್ತದೆ; ಆದ್ದರಿಂದ M(KMnO₄) = 0.1 × 10 ÷ (5 × ಅನುಮಾಪನಾಂಕ). ಬಿಸಿಮಾಡಬಾರದು: ಅದು ಗಾಳಿಯಲ್ಲಿ Fe²⁺ ಅನ್ನು ಉತ್ಕರ್ಷಿಸುತ್ತದೆ."},"apparatus":[{"en":"Burette (50 mL) with stand","hi":"स्टैंड सहित ब्यूरेट (50 mL)","kn":"ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)"},{"en":"Pipette (10 mL) and conical flask","hi":"पिपेट (10 mL) और शंक्वाकार फ्लास्क","kn":"ಪಿಪೆಟ್ (10 mL) ಮತ್ತು ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್"},{"en":"0.1 M Mohr's salt and dilute H₂SO₄","hi":"0.1 M मोर लवण और तनु H₂SO₄","kn":"0.1 M ಮೋರ್ ಲವಣ ಮತ್ತು ವಿರಳ H₂SO₄"},{"en":"KMnO₄ solution (unknown)","hi":"KMnO₄ विलयन (अज्ञात)","kn":"KMnO₄ ದ್ರಾವಣ (ಅಜ್ಞಾತ)"},{"en":"White tile and funnel","hi":"सफ़ेद टाइल और कीप","kn":"ಬಿಳಿ ಟೈಲ್ ಮತ್ತು ಆಲಿಕೆ"}],"steps":[{"en":"Rinse and fill the burette; note the initial reading.","hi":"ब्यूरेट धोकर भरें; प्रारंभिक पाठ्यांक लिखें।","kn":"ಬ್ಯೂರೆಟ್ ತೊಳೆದು ತುಂಬಿ; ಆರಂಭಿಕ ಓದು ಬರೆಯಿರಿ."},{"en":"Pipette 10 mL of the solution into the conical flask (add the indicator or acid as needed).","hi":"शंक्वाकार फ्लास्क में 10 mL विलयन पिपेट से लें (आवश्यक हो तो सूचक या अम्ल मिलाएँ)।","kn":"ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್‌ಗೆ ಪಿಪೆಟ್‌ನಿಂದ 10 mL ದ್ರಾವಣ ಹಾಕಿ (ಬೇಕಾದರೆ ಸೂಚಕ ಅಥವಾ ಆಮ್ಲ ಸೇರಿಸಿ)."},{"en":"Run in the titrant, swirling, until one drop gives a permanent colour change. Record the final reading.","hi":"घुमाते हुए अनुमापक डालें जब तक एक बूँद से स्थायी रंग परिवर्तन न हो। अंतिम पाठ्यांक लिखें।","kn":"ತಿರುಗಿಸುತ್ತಾ ಅನುಮಾಪಕ ಸೇರಿಸಿ, ಒಂದು ಹನಿ ಶಾಶ್ವತ ಬಣ್ಣ ಬದಲಾವಣೆ ತರುವವರೆಗೆ. ಅಂತಿಮ ಓದು ದಾಖಲಿಸಿ."},{"en":"Repeat until three readings agree within 0.1 mL.","hi":"तीन पाठ्यांक 0.1 mL के भीतर मेल खाने तक दोहराएँ।","kn":"ಮೂರು ಓದುಗಳು 0.1 mL ಒಳಗೆ ಹೊಂದುವವರೆಗೆ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Use the mean titre and the mole ratio to find the unknown molarity.","hi":"माध्य अनुमापांक और मोल अनुपात से अज्ञात मोलरता ज्ञात करें।","kn":"ಸರಾಸರಿ ಅನುಮಾಪನಾಂಕ ಮತ್ತು ಮೋಲ್ ಅನುಪಾತದಿಂದ ಅಜ್ಞಾತ ಮೋಲಾರಿಟಿ ಕಂಡುಹಿಡಿಯಿರಿ."}],"precautions":[{"en":"Rinse the burette with the solution it will hold, and the pipette with the solution it will measure.","hi":"ब्यूरेट को उसी विलयन से धोएँ जो उसमें भरना है, और पिपेट को उसी से जिसे वह मापेगी।","kn":"ಬ್ಯೂರೆಟನ್ನು ಅದರಲ್ಲಿ ತುಂಬುವ ದ್ರಾವಣದಿಂದ, ಪಿಪೆಟನ್ನು ಅದು ಅಳೆಯುವ ದ್ರಾವಣದಿಂದ ತೊಳೆಯಿರಿ."},{"en":"Read the upper meniscus of KMnO₄: it is too dark to see the lower one.","hi":"KMnO₄ का ऊपरी नवचंद्रक पढ़ें: निचला देखने के लिए यह बहुत गहरा है।","kn":"KMnO₄ ನ ಮೇಲಿನ ಮೆನಿಸ್ಕಸ್ ಓದಿ: ಕೆಳಗಿನದು ಕಾಣಲು ಅದು ತುಂಬ ಗಾಢ."},{"en":"Near the end point add the titrant drop by drop, swirling the flask.","hi":"अंतिम बिंदु के पास अनुमापक बूँद-बूँद डालें और फ्लास्क घुमाते रहें।","kn":"ಅಂತ್ಯ ಬಿಂದುವಿನ ಹತ್ತಿರ ಅನುಮಾಪಕವನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ, ಫ್ಲಾಸ್ಕ್ ತಿರುಗಿಸುತ್ತಿರಿ."},{"en":"Add enough dilute H₂SO₄; never use HCl or HNO₃ to acidify.","hi":"पर्याप्त तनु H₂SO₄ डालें; अम्लीकरण के लिए HCl या HNO₃ कभी न लें।","kn":"ಸಾಕಷ್ಟು ವಿರಳ H₂SO₄ ಸೇರಿಸಿ; ಆಮ್ಲೀಕರಣಕ್ಕೆ HCl ಅಥವಾ HNO₃ ಎಂದೂ ಬಳಸಬೇಡಿ."}],"conclusion":{"en":"Five Fe²⁺ react with each MnO₄⁻; the concordant titre gives the molarity of the permanganate.","hi":"हर MnO₄⁻ से पाँच Fe²⁺ अभिक्रिया करते हैं; सहमत अनुमापांक परमैंगनेट की मोलरता देता है।","kn":"ಪ್ರತಿ MnO₄⁻ ಗೆ ಐದು Fe²⁺ ಪ್ರತಿಕ್ರಿಯಿಸುತ್ತವೆ; ಹೊಂದಿಕೆಯ ಅನುಮಾಪನಾಂಕ ಪರ್ಮ್ಯಾಂಗನೇಟ್‌ನ ಮೋಲಾರಿಟಿ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why is no indicator needed?","hi":"सूचक की आवश्यकता क्यों नहीं?","kn":"ಸೂಚಕ ಏಕೆ ಬೇಕಿಲ್ಲ?"},"a":{"en":"KMnO₄ is its own indicator: the first excess drop turns the solution pink.","hi":"KMnO₄ स्वयं सूचक है: पहली अतिरिक्त बूँद विलयन को गुलाबी कर देती है।","kn":"KMnO₄ ತಾನೇ ಸೂಚಕ: ಮೊದಲ ಹೆಚ್ಚುವರಿ ಹನಿ ದ್ರಾವಣವನ್ನು ಗುಲಾಬಿಯಾಗಿಸುತ್ತದೆ."}},{"q":{"en":"Why is HCl not used to acidify?","hi":"अम्लीकरण के लिए HCl क्यों नहीं?","kn":"ಆಮ್ಲೀಕರಣಕ್ಕೆ HCl ಏಕೆ ಅಲ್ಲ?"},"a":{"en":"KMnO₄ would oxidise chloride ions to chlorine, using up extra titrant.","hi":"KMnO₄ क्लोराइड आयनों को क्लोरीन में ऑक्सीकृत कर अतिरिक्त अनुमापक खपा देगा।","kn":"KMnO₄ ಕ್ಲೋರೈಡ್ ಅಯಾನುಗಳನ್ನು ಕ್ಲೋರಿನ್ ಆಗಿ ಉತ್ಕರ್ಷಿಸಿ ಹೆಚ್ಚುವರಿ ಅನುಮಾಪಕ ಬಳಸುತ್ತದೆ."}},{"q":{"en":"What is the oxidation state of Mn in KMnO₄, and after the reaction?","hi":"KMnO₄ में और अभिक्रिया के बाद Mn की ऑक्सीकरण अवस्था क्या है?","kn":"KMnO₄ ನಲ್ಲಿ ಮತ್ತು ಪ್ರತಿಕ್ರಿಯೆಯ ನಂತರ Mn ನ ಉತ್ಕರ್ಷಣ ಸ್ಥಿತಿ ಏನು?"},"a":{"en":"+7, reduced to +2 (Mn²⁺) in acid.","hi":"+7, अम्ल में +2 (Mn²⁺) तक अपचयित।","kn":"+7, ಆಮ್ಲದಲ್ಲಿ +2 (Mn²⁺) ಗೆ ಅಪಕರ್ಷಿತ."}},{"q":{"en":"Why is Mohr's salt preferred to ferrous sulphate?","hi":"फ़ेरस सल्फ़ेट की तुलना में मोर लवण क्यों अच्छा है?","kn":"ಫೆರಸ್ ಸಲ್ಫೇಟ್‌ಗಿಂತ ಮೋರ್ ಲವಣ ಏಕೆ ಉತ್ತಮ?"},"a":{"en":"It is a stable double salt that is not readily oxidised by air, so it can be weighed as a standard.","hi":"यह स्थिर द्विक लवण है जो वायु से जल्दी ऑक्सीकृत नहीं होता, इसलिए मानक के रूप में तौला जा सकता है।","kn":"ಅದು ಗಾಳಿಯಿಂದ ಬೇಗ ಉತ್ಕರ್ಷಣಗೊಳ್ಳದ ಸ್ಥಿರ ದ್ವಿ ಲವಣ; ಆದ್ದರಿಂದ ಮಾನಕವಾಗಿ ತೂಕ ಮಾಡಬಹುದು."}}]},{"id":"ph-metric-titration","bench":"ph-titration","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["ug"],"mode":"guided","curricula":["ug-chemistry"],"reviewed":false,"keywords":["potentiometric titration","ph metric titration","ph meter","weak acid","pka","acetic acid","buffer"],"title":{"en":"pH-metric titration of acetic acid","hi":"ऐसीटिक अम्ल का pH-मितीय अनुमापन","kn":"ಅಸಿಟಿಕ್ ಆಮ್ಲದ pH-ಮಾಪಕ ಅನುಮಾಪನ"},"summary":{"en":"Follow the pH as NaOH is added; find the end point from the steepest rise and pKa at half-neutralisation.","hi":"NaOH डालते हुए pH देखें; सबसे खड़े उभार से अंतिम बिंदु और अर्ध-उदासीनीकरण पर pKa ज्ञात करें।","kn":"NaOH ಸೇರಿಸುತ್ತಾ pH ಗಮನಿಸಿ; ಅತಿ ಕಡಿದಾದ ಏರಿಕೆಯಿಂದ ಅಂತ್ಯ ಬಿಂದು ಮತ್ತು ಅರ್ಧ-ತಟಸ್ಥೀಕರಣದಲ್ಲಿ pKa ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To titrate acetic acid with NaOH using a pH meter and find its concentration and dissociation constant.","hi":"pH मीटर से ऐसीटिक अम्ल का NaOH से अनुमापन कर उसकी सांद्रता और वियोजन नियतांक ज्ञात करना।","kn":"pH ಮಾಪಕ ಬಳಸಿ ಅಸಿಟಿಕ್ ಆಮ್ಲವನ್ನು NaOH ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ ಅದರ ಸಾಂದ್ರತೆ ಮತ್ತು ವಿಯೋಜನ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"The glass electrode’s EMF changes by 59 mV per pH unit. During the titration a buffer of CH₃COOH and CH₃COO⁻ forms; by the Henderson equation pH = pKa + log([A⁻]/[HA]), so at half-neutralisation pH = pKa. At equivalence the pH jumps most steeply (largest ΔpH/ΔV).","hi":"काँच इलेक्ट्रोड का EMF प्रति pH इकाई 59 mV बदलता है। अनुमापन में CH₃COOH और CH₃COO⁻ का बफ़र बनता है; हेंडरसन समीकरण pH = pKa + log([A⁻]/[HA]) से अर्ध-उदासीनीकरण पर pH = pKa. तुल्यता पर pH सबसे तेज़ी से उछलता है (सबसे बड़ा ΔpH/ΔV)।","kn":"ಗಾಜಿನ ವಿದ್ಯುದ್ವಾರದ EMF ಪ್ರತಿ pH ಏಕಮಾನಕ್ಕೆ 59 mV ಬದಲಾಗುತ್ತದೆ. ಅನುಮಾಪನದಲ್ಲಿ CH₃COOH ಮತ್ತು CH₃COO⁻ ಬಫರ್ ರೂಪುಗೊಳ್ಳುತ್ತದೆ; ಹೆಂಡರ್ಸನ್ ಸಮೀಕರಣ pH = pKa + log([A⁻]/[HA]) ಪ್ರಕಾರ ಅರ್ಧ-ತಟಸ್ಥೀಕರಣದಲ್ಲಿ pH = pKa. ಸಮತುಲ್ಯತೆಯಲ್ಲಿ pH ಅತಿ ಕಡಿದಾಗಿ ಜಿಗಿಯುತ್ತದೆ (ಅತಿ ದೊಡ್ಡ ΔpH/ΔV)."},"apparatus":[{"en":"pH meter with combined glass electrode","hi":"संयुक्त काँच इलेक्ट्रोड सहित pH मीटर","kn":"ಸಂಯುಕ್ತ ಗಾಜಿನ ವಿದ್ಯುದ್ವಾರ ಸಹಿತ pH ಮಾಪಕ"},{"en":"Buffer solutions of pH 4 and 9.2","hi":"pH 4 और 9.2 के बफ़र विलयन","kn":"pH 4 ಮತ್ತು 9.2 ರ ಬಫರ್ ದ್ರಾವಣಗಳು"},{"en":"Burette (50 mL) with stand","hi":"स्टैंड सहित ब्यूरेट (50 mL)","kn":"ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)"},{"en":"Beaker and magnetic stirrer","hi":"बीकर और चुंबकीय विलोडक","kn":"ಬೀಕರ್ ಮತ್ತು ಕಾಂತೀಯ ಕಲಕಿ"}],"steps":[{"en":"Calibrate the pH meter with the two buffers.","hi":"दोनों बफ़रों से pH मीटर का अंशांकन करें।","kn":"ಎರಡು ಬಫರ್‌ಗಳಿಂದ pH ಮಾಪಕವನ್ನು ಮಾಪನಾಂಕಗೊಳಿಸಿ."},{"en":"Take 25 mL of acetic acid in the beaker with the electrode dipping in.","hi":"बीकर में 25 mL ऐसीटिक अम्ल लें जिसमें इलेक्ट्रोड डूबा हो।","kn":"ವಿದ್ಯುದ್ವಾರ ಮುಳುಗಿರುವ ಬೀಕರ್‌ನಲ್ಲಿ 25 mL ಅಸಿಟಿಕ್ ಆಮ್ಲ ತೆಗೆದುಕೊಳ್ಳಿ."},{"en":"Add NaOH 1 mL at a time (0.2 mL near the end point), stirring, and record the pH.","hi":"हिलाते हुए एक बार में 1 mL NaOH डालें (अंतिम बिंदु के पास 0.2 mL), और pH लिखें।","kn":"ಕಲಕುತ್ತಾ ಒಮ್ಮೆಗೆ 1 mL NaOH ಸೇರಿಸಿ (ಅಂತ್ಯ ಬಿಂದುವಿನ ಹತ್ತಿರ 0.2 mL), pH ದಾಖಲಿಸಿ."},{"en":"Plot pH against V and ΔpH/ΔV against V; locate the equivalence point.","hi":"pH और V तथा ΔpH/ΔV और V के ग्राफ़ बनाएँ; तुल्यता बिंदु ढूँढें।","kn":"pH ಮತ್ತು V ಹಾಗೂ ΔpH/ΔV ಮತ್ತು V ನಕ್ಷೆಗಳನ್ನು ಎಳೆದು ಸಮತುಲ್ಯ ಬಿಂದು ಹುಡುಕಿ."},{"en":"Read pH at half the equivalence volume: that is pKa.","hi":"तुल्यता आयतन के आधे पर pH पढ़ें: वही pKa है।","kn":"ಸಮತುಲ್ಯ ಘನಫಲದ ಅರ್ಧದಲ್ಲಿ pH ಓದಿ: ಅದೇ pKa."},{"en":"Export the readings as CSV and fit the straight lines.","hi":"पाठ्यांक CSV में निर्यात कर सीधी रेखाएँ फ़िट करें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಸರಳರೇಖೆಗಳನ್ನು ಹೊಂದಿಸಿ."}],"precautions":[{"en":"Rinse the electrode with distilled water between solutions and never let it dry.","hi":"विलयनों के बीच इलेक्ट्रोड को आसुत जल से धोएँ और उसे कभी सूखने न दें।","kn":"ದ್ರಾವಣಗಳ ನಡುವೆ ವಿದ್ಯುದ್ವಾರವನ್ನು ಬಟ್ಟಿ ನೀರಿನಿಂದ ತೊಳೆಯಿರಿ, ಎಂದೂ ಒಣಗಲು ಬಿಡಬೇಡಿ."},{"en":"Wait for the reading to settle after each addition.","hi":"हर बार डालने के बाद पाठ्यांक स्थिर होने की प्रतीक्षा करें।","kn":"ಪ್ರತಿ ಸೇರ್ಪಡೆಯ ನಂತರ ಓದು ಸ್ಥಿರವಾಗಲು ಕಾಯಿರಿ."},{"en":"Keep the electrode clear of the stirrer bar.","hi":"इलेक्ट्रोड को विलोडक छड़ से दूर रखें।","kn":"ವಿದ್ಯುದ್ವಾರವನ್ನು ಕಲಕುವ ಸರಳಿನಿಂದ ದೂರವಿಡಿ."}],"conclusion":{"en":"The curve rises slowly through the buffer region and steeply at equivalence (pH ≈ 8.7, basic because acetate hydrolyses); the half-neutralisation pH gives pKa ≈ 4.74.","hi":"वक्र बफ़र क्षेत्र में धीरे और तुल्यता पर तेज़ी से उठता है (pH ≈ 8.7, क्षारीय क्योंकि ऐसीटेट जल-अपघटित होता है); अर्ध-उदासीनीकरण का pH, pKa ≈ 4.74 देता है।","kn":"ವಕ್ರ ಬಫರ್ ಪ್ರದೇಶದಲ್ಲಿ ನಿಧಾನವಾಗಿ, ಸಮತುಲ್ಯತೆಯಲ್ಲಿ ಕಡಿದಾಗಿ ಏರುತ್ತದೆ (pH ≈ 8.7, ಅಸಿಟೇಟ್ ಜಲವಿಭಜನೆಯಿಂದ ಕ್ಷಾರೀಯ); ಅರ್ಧ-ತಟಸ್ಥೀಕರಣದ pH, pKa ≈ 4.74 ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why is the pH at equivalence above 7?","hi":"तुल्यता पर pH 7 से अधिक क्यों है?","kn":"ಸಮತುಲ್ಯತೆಯಲ್ಲಿ pH 7 ಕ್ಕಿಂತ ಹೆಚ್ಚು ಏಕೆ?"},"a":{"en":"Sodium acetate hydrolyses: CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻.","hi":"सोडियम ऐसीटेट जल-अपघटित होता है: CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻.","kn":"ಸೋಡಿಯಂ ಅಸಿಟೇಟ್ ಜಲವಿಭಜನೆಯಾಗುತ್ತದೆ: CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻."}},{"q":{"en":"What is a buffer?","hi":"बफ़र क्या है?","kn":"ಬಫರ್ ಎಂದರೇನು?"},"a":{"en":"A solution that resists change of pH when a little acid or base is added.","hi":"ऐसा विलयन जो थोड़ा अम्ल या क्षार डालने पर pH परिवर्तन का विरोध करता है।","kn":"ಸ್ವಲ್ಪ ಆಮ್ಲ ಅಥವಾ ಕ್ಷಾರ ಸೇರಿಸಿದಾಗ pH ಬದಲಾವಣೆಯನ್ನು ವಿರೋಧಿಸುವ ದ್ರಾವಣ."}},{"q":{"en":"Why calibrate with two buffers?","hi":"दो बफ़रों से अंशांकन क्यों?","kn":"ಎರಡು ಬಫರ್‌ಗಳಿಂದ ಮಾಪನಾಂಕ ಏಕೆ?"},"a":{"en":"To set both the offset and the slope (mV per pH) of the electrode.","hi":"इलेक्ट्रोड का ऑफ़सेट और प्रवणता (mV प्रति pH) दोनों तय करने के लिए।","kn":"ವಿದ್ಯುದ್ವಾರದ ಆಫ್‌ಸೆಟ್ ಮತ್ತು ಇಳಿಜಾರು (ಪ್ರತಿ pH ಗೆ mV) ಎರಡನ್ನೂ ಹೊಂದಿಸಲು."}}]},{"id":"conductometric-titration","bench":"conductometric","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["ug"],"mode":"guided","curricula":["ug-chemistry"],"reviewed":false,"keywords":["conductometric titration","conductance","conductivity","strong acid","weak acid","electrochemistry"],"title":{"en":"Conductometric titration of acids with NaOH","hi":"NaOH से अम्लों का चालकतामितीय अनुमापन","kn":"NaOH ನಿಂದ ಆಮ್ಲಗಳ ವಾಹಕತಾಮಾಪಕ ಅನುಮಾಪನ"},"summary":{"en":"Follow the conductance as NaOH neutralises HCl or acetic acid; the two straight parts meet at the end point.","hi":"NaOH द्वारा HCl या ऐसीटिक अम्ल के उदासीनीकरण में चालकता देखें; दो सीधे भाग अंतिम बिंदु पर मिलते हैं।","kn":"NaOH, HCl ಅಥವಾ ಅಸಿಟಿಕ್ ಆಮ್ಲವನ್ನು ತಟಸ್ಥಗೊಳಿಸುವಾಗ ವಾಹಕತೆ ಗಮನಿಸಿ; ಎರಡು ನೇರ ಭಾಗಗಳು ಅಂತ್ಯ ಬಿಂದುವಿನಲ್ಲಿ ಸೇರುತ್ತವೆ."},"aim":{"en":"To find the strength of a strong and a weak acid by conductometric titration with NaOH.","hi":"NaOH से चालकतामितीय अनुमापन द्वारा एक प्रबल और एक दुर्बल अम्ल की प्रबलता ज्ञात करना।","kn":"NaOH ನಿಂದ ವಾಹಕತಾಮಾಪಕ ಅನುಮಾಪನ ಮಾಡಿ ಒಂದು ಪ್ರಬಲ ಮತ್ತು ಒಂದು ದುರ್ಬಲ ಆಮ್ಲದ ಪ್ರಬಲತೆ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Conductance is the sum of λc for the ions present. Adding NaOH to HCl replaces fast H⁺ (λ = 350) by slow Na⁺ (50), so conductance falls; after the end point free OH⁻ (198) makes it rise: a V-shape. With acetic acid, conductance rises gently as acetate ions form and then more steeply after the end point. Readings are corrected for dilution.","hi":"चालकता उपस्थित आयनों के λc का योग है। HCl में NaOH डालने से तेज़ H⁺ (λ = 350) की जगह धीमा Na⁺ (50) आता है, इसलिए चालकता घटती है; अंतिम बिंदु के बाद मुक्त OH⁻ (198) उसे बढ़ाता है: V-आकार। ऐसीटिक अम्ल में ऐसीटेट आयन बनने से चालकता धीरे बढ़ती है और अंतिम बिंदु के बाद तेज़ी से। पाठ्यांक तनुता के लिए संशोधित किए जाते हैं।","kn":"ವಾಹಕತೆ ಇರುವ ಅಯಾನುಗಳ λc ಯ ಮೊತ್ತ. HCl ಗೆ NaOH ಸೇರಿಸಿದಾಗ ವೇಗದ H⁺ (λ = 350) ಬದಲು ನಿಧಾನ Na⁺ (50) ಬರುತ್ತದೆ, ವಾಹಕತೆ ಇಳಿಯುತ್ತದೆ; ಅಂತ್ಯ ಬಿಂದುವಿನ ನಂತರ ಮುಕ್ತ OH⁻ (198) ಅದನ್ನು ಏರಿಸುತ್ತದೆ: V-ಆಕಾರ. ಅಸಿಟಿಕ್ ಆಮ್ಲದಲ್ಲಿ ಅಸಿಟೇಟ್ ಅಯಾನುಗಳು ಬಂದಂತೆ ವಾಹಕತೆ ನಿಧಾನವಾಗಿ, ಅಂತ್ಯ ಬಿಂದುವಿನ ನಂತರ ಕಡಿದಾಗಿ ಏರುತ್ತದೆ. ಓದುಗಳನ್ನು ವಿರಳೀಕರಣಕ್ಕೆ ತಿದ್ದುತ್ತಾರೆ."},"apparatus":[{"en":"Conductivity meter and cell","hi":"चालकता मीटर और सेल","kn":"ವಾಹಕತಾ ಮಾಪಕ ಮತ್ತು ಕೋಶ"},{"en":"Burette (50 mL) with stand","hi":"स्टैंड सहित ब्यूरेट (50 mL)","kn":"ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)"},{"en":"0.1 M NaOH; 0.01 M HCl and acetic acid","hi":"0.1 M NaOH; 0.01 M HCl और ऐसीटिक अम्ल","kn":"0.1 M NaOH; 0.01 M HCl ಮತ್ತು ಅಸಿಟಿಕ್ ಆಮ್ಲ"},{"en":"Beaker and stirrer","hi":"बीकर और विलोडक","kn":"ಬೀಕರ್ ಮತ್ತು ಕಲಕಿ"}],"steps":[{"en":"Put 100 mL of the acid in the beaker and dip the conductivity cell in it.","hi":"बीकर में 100 mL अम्ल लेकर उसमें चालकता सेल डुबाएँ।","kn":"ಬೀಕರ್‌ನಲ್ಲಿ 100 mL ಆಮ್ಲ ಹಾಕಿ ಅದರಲ್ಲಿ ವಾಹಕತಾ ಕೋಶ ಮುಳುಗಿಸಿ."},{"en":"Add NaOH 1 mL at a time, stir, and record the conductance.","hi":"एक बार में 1 mL NaOH डालें, हिलाएँ, और चालकता लिखें।","kn":"ಒಮ್ಮೆಗೆ 1 mL NaOH ಸೇರಿಸಿ, ಕಲಕಿ, ವಾಹಕತೆ ದಾಖಲಿಸಿ."},{"en":"Continue well past the turning point.","hi":"मोड़ बिंदु से काफ़ी आगे तक जारी रखें।","kn":"ತಿರುವು ಬಿಂದುವಿನ ಸಾಕಷ್ಟು ಆಚೆಯವರೆಗೆ ಮುಂದುವರಿಸಿ."},{"en":"Plot corrected conductance against V and draw the two straight lines; their meeting point is the end point.","hi":"संशोधित चालकता और V का ग्राफ़ बनाकर दो सीधी रेखाएँ खींचें; उनका मिलन बिंदु अंतिम बिंदु है।","kn":"ತಿದ್ದಿದ ವಾಹಕತೆ ಮತ್ತು V ನಕ್ಷೆ ಎಳೆದು ಎರಡು ಸರಳರೇಖೆಗಳನ್ನು ಎಳೆಯಿರಿ; ಅವು ಸೇರುವಲ್ಲಿ ಅಂತ್ಯ ಬಿಂದು."},{"en":"Repeat with acetic acid and compare the shapes.","hi":"ऐसीटिक अम्ल के साथ दोहराएँ और आकारों की तुलना करें।","kn":"ಅಸಿಟಿಕ್ ಆಮ್ಲದೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಆಕಾರಗಳನ್ನು ಹೋಲಿಸಿ."},{"en":"Export the readings as CSV and fit the straight lines.","hi":"पाठ्यांक CSV में निर्यात कर सीधी रेखाएँ फ़िट करें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಸರಳರೇಖೆಗಳನ್ನು ಹೊಂದಿಸಿ."}],"precautions":[{"en":"Use a titrant about ten times stronger than the acid so that dilution is small.","hi":"अम्ल से लगभग दस गुना प्रबल अनुमापक लें ताकि तनुता कम हो।","kn":"ವಿರಳೀಕರಣ ಕಡಿಮೆಯಿರಲು ಆಮ್ಲಕ್ಕಿಂತ ಸುಮಾರು ಹತ್ತು ಪಟ್ಟು ಪ್ರಬಲ ಅನುಮಾಪಕ ಬಳಸಿ."},{"en":"Keep the temperature constant: conductance rises about 2% per °C.","hi":"ताप नियत रखें: चालकता लगभग 2% प्रति °C बढ़ती है।","kn":"ತಾಪ ಸ್ಥಿರವಾಗಿರಲಿ: ವಾಹಕತೆ ಪ್ರತಿ °C ಗೆ ಸುಮಾರು 2% ಏರುತ್ತದೆ."},{"en":"Do not touch the platinised electrodes.","hi":"प्लैटिनीकृत इलेक्ट्रोडों को न छुएँ।","kn":"ಪ್ಲಾಟಿನೀಕೃತ ವಿದ್ಯುದ್ವಾರಗಳನ್ನು ಮುಟ್ಟಬೇಡಿ."}],"conclusion":{"en":"HCl gives a V-shaped curve and acetic acid a gentle rise then a steep one; in both the lines meet at the equivalence point, which gives the acid’s strength without any indicator.","hi":"HCl से V-आकार का वक्र और ऐसीटिक अम्ल से पहले धीमा फिर तेज़ उठाव मिलता है; दोनों में रेखाएँ तुल्यता बिंदु पर मिलती हैं, जिससे बिना सूचक के अम्ल की प्रबलता मिलती है।","kn":"HCl V-ಆಕಾರದ ವಕ್ರ, ಅಸಿಟಿಕ್ ಆಮ್ಲ ಮೊದಲು ನಿಧಾನ ನಂತರ ಕಡಿದಾದ ಏರಿಕೆ ನೀಡುತ್ತವೆ; ಎರಡರಲ್ಲೂ ರೇಖೆಗಳು ಸಮತುಲ್ಯ ಬಿಂದುವಿನಲ್ಲಿ ಸೇರುತ್ತವೆ; ಸೂಚಕವಿಲ್ಲದೆ ಆಮ್ಲದ ಪ್ರಬಲತೆ ಸಿಗುತ್ತದೆ."},"viva":[{"q":{"en":"Why does H⁺ conduct so well?","hi":"H⁺ इतना अच्छा चालक क्यों है?","kn":"H⁺ ಏಕೆ ಇಷ್ಟು ಉತ್ತಮ ವಾಹಕ?"},"a":{"en":"Protons hop from one water molecule to the next (Grotthuss mechanism).","hi":"प्रोटॉन एक जल अणु से अगले पर कूदते हैं (ग्रॉटस क्रियाविधि)।","kn":"ಪ್ರೋಟಾನ್‌ಗಳು ಒಂದು ನೀರಿನ ಅಣುವಿನಿಂದ ಮುಂದಿನದಕ್ಕೆ ಜಿಗಿಯುತ್ತವೆ (ಗ್ರೋಟಸ್ ಕಾರ್ಯವಿಧಾನ)."}},{"q":{"en":"Give one advantage of conductometric titration.","hi":"चालकतामितीय अनुमापन का एक लाभ बताइए।","kn":"ವಾಹಕತಾಮಾಪಕ ಅನುಮಾಪನದ ಒಂದು ಲಾಭ ತಿಳಿಸಿ."},"a":{"en":"It works for coloured or very dilute solutions, where indicators fail.","hi":"यह रंगीन या बहुत तनु विलयनों के लिए काम करता है, जहाँ सूचक विफल रहते हैं।","kn":"ಸೂಚಕಗಳು ವಿಫಲವಾಗುವ ಬಣ್ಣದ ಅಥವಾ ಅತಿ ವಿರಳ ದ್ರಾವಣಗಳಿಗೆ ಇದು ಕೆಲಸ ಮಾಡುತ್ತದೆ."}},{"q":{"en":"What is the unit of conductance?","hi":"चालकता का मात्रक क्या है?","kn":"ವಾಹಕತೆಯ ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"Siemens (S), the reciprocal of ohm.","hi":"सीमेंस (S), ओम का व्युत्क्रम।","kn":"ಸೀಮೆನ್ಸ್ (S), ಓಮ್‌ನ ವಿಲೋಮ."}}]},{"id":"reaction-rate-thiosulphate","bench":"reaction-rate","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["chemical kinetics","rate of reaction","sodium thiosulphate","sodium thiosulfate","concentration","temperature"],"title":{"en":"Rate of reaction: sodium thiosulphate and acid","hi":"अभिक्रिया की दर: सोडियम थायोसल्फ़ेट और अम्ल","kn":"ಪ್ರತಿಕ್ರಿಯೆಯ ದರ: ಸೋಡಿಯಂ ಥಯೋಸಲ್ಫೇಟ್ ಮತ್ತು ಆಮ್ಲ"},"summary":{"en":"Time how long the sulphur takes to hide a cross, at different concentrations and temperatures.","hi":"अलग-अलग सांद्रता और ताप पर गंधक को एक क्रॉस छिपाने में लगने वाला समय मापें।","kn":"ಬೇರೆ ಬೇರೆ ಸಾಂದ್ರತೆ ಮತ್ತು ತಾಪಗಳಲ್ಲಿ ಗಂಧಕ ಒಂದು ಅಡ್ಡಗುರುತು ಮುಚ್ಚಲು ತೆಗೆದುಕೊಳ್ಳುವ ಸಮಯ ಅಳೆಯಿರಿ."},"aim":{"en":"To study the effect of concentration and temperature on the rate of reaction between sodium thiosulphate and hydrochloric acid.","hi":"सोडियम थायोसल्फ़ेट और हाइड्रोक्लोरिक अम्ल की अभिक्रिया की दर पर सांद्रता और ताप के प्रभाव का अध्ययन करना।","kn":"ಸೋಡಿಯಂ ಥಯೋಸಲ್ಫೇಟ್ ಮತ್ತು ಹೈಡ್ರೋಕ್ಲೋರಿಕ್ ಆಮ್ಲದ ಪ್ರತಿಕ್ರಿಯಾ ದರದ ಮೇಲೆ ಸಾಂದ್ರತೆ ಮತ್ತು ತಾಪದ ಪರಿಣಾಮ ಅಧ್ಯಯನ ಮಾಡುವುದು."},"principle":{"en":"Na₂S₂O₃ + 2HCl → 2NaCl + SO₂ + S + H₂O. Colloidal sulphur clouds the solution; the time t for a fixed amount of sulphur to hide the cross is inversely proportional to the rate, so 1/t is a measure of the rate. 1/t ∝ [S₂O₃²⁻], and the rate roughly doubles for every 10 °C rise.","hi":"Na₂S₂O₃ + 2HCl → 2NaCl + SO₂ + S + H₂O. कोलॉइडी गंधक विलयन को धुँधला कर देता है; निश्चित मात्रा में गंधक को क्रॉस छिपाने में लगा समय t दर के व्युत्क्रमानुपाती है, इसलिए 1/t दर का माप है। 1/t ∝ [S₂O₃²⁻], और हर 10 °C वृद्धि पर दर लगभग दोगुनी होती है।","kn":"Na₂S₂O₃ + 2HCl → 2NaCl + SO₂ + S + H₂O. ಕಲಿಲ ಗಂಧಕ ದ್ರಾವಣವನ್ನು ಮಬ್ಬಾಗಿಸುತ್ತದೆ; ನಿಗದಿತ ಪ್ರಮಾಣದ ಗಂಧಕ ಅಡ್ಡಗುರುತು ಮುಚ್ಚಲು ಬೇಕಾದ ಸಮಯ t ದರಕ್ಕೆ ವಿಲೋಮಾನುಪಾತೀಯ; ಆದ್ದರಿಂದ 1/t ದರದ ಅಳತೆ. 1/t ∝ [S₂O₃²⁻], ಪ್ರತಿ 10 °C ಏರಿಕೆಗೆ ದರ ಸುಮಾರು ಎರಡು ಪಟ್ಟು."},"apparatus":[{"en":"0.1 M sodium thiosulphate and 1 M HCl","hi":"0.1 M सोडियम थायोसल्फ़ेट और 1 M HCl","kn":"0.1 M ಸೋಡಿಯಂ ಥಯೋಸಲ್ಫೇಟ್ ಮತ್ತು 1 M HCl"},{"en":"Conical flasks and measuring cylinders","hi":"शंक्वाकार फ्लास्क और मापक सिलिंडर","kn":"ಶಂಕುವಿನಾಕಾರದ ಫ್ಲಾಸ್ಕ್‌ಗಳು ಮತ್ತು ಅಳತೆ ಸಿಲಿಂಡರ್‌ಗಳು"},{"en":"Paper marked with a cross","hi":"क्रॉस बने कागज़","kn":"ಅಡ್ಡಗುರುತು ಹಾಕಿದ ಕಾಗದ"},{"en":"Stopwatch and water bath","hi":"विराम घड़ी और जल ऊष्मक","kn":"ನಿಲುಗಡಿಯಾರ ಮತ್ತು ನೀರಿನ ತೊಟ್ಟಿ"}],"steps":[{"en":"Put 50 mL of thiosulphate in the flask on the cross.","hi":"क्रॉस पर रखे फ्लास्क में 50 mL थायोसल्फ़ेट डालें।","kn":"ಅಡ್ಡಗುರುತಿನ ಮೇಲಿನ ಫ್ಲಾಸ್ಕ್‌ಗೆ 50 mL ಥಯೋಸಲ್ಫೇಟ್ ಹಾಕಿ."},{"en":"Add 5 mL of HCl, start the stopwatch and swirl.","hi":"5 mL HCl डालें, विराम घड़ी चालू करें और घुमाएँ।","kn":"5 mL HCl ಸೇರಿಸಿ, ನಿಲುಗಡಿಯಾರ ಆರಂಭಿಸಿ ತಿರುಗಿಸಿ."},{"en":"Looking from above, stop the watch when the cross can no longer be seen.","hi":"ऊपर से देखते हुए, क्रॉस न दिखने पर घड़ी रोकें।","kn":"ಮೇಲಿನಿಂದ ನೋಡುತ್ತಾ ಅಡ್ಡಗುರುತು ಕಾಣದಾದಾಗ ಗಡಿಯಾರ ನಿಲ್ಲಿಸಿ."},{"en":"Repeat with 40, 30, 20 and 10 mL thiosulphate made up to 50 mL with water.","hi":"40, 30, 20 और 10 mL थायोसल्फ़ेट को पानी से 50 mL बनाकर दोहराएँ।","kn":"40, 30, 20 ಮತ್ತು 10 mL ಥಯೋಸಲ್ಫೇಟನ್ನು ನೀರಿನಿಂದ 50 mL ಮಾಡಿ ಪುನರಾವರ್ತಿಸಿ."},{"en":"Repeat the 50 mL run at higher temperatures; plot 1/t against concentration.","hi":"50 mL वाला प्रयोग अधिक ताप पर दोहराएँ; 1/t और सांद्रता का ग्राफ़ बनाएँ।","kn":"50 mL ಪ್ರಯೋಗವನ್ನು ಹೆಚ್ಚು ತಾಪದಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ; 1/t ಮತ್ತು ಸಾಂದ್ರತೆ ನಕ್ಷೆ ಎಳೆಯಿರಿ."}],"precautions":[{"en":"Keep the total volume the same in every run.","hi":"हर प्रयोग में कुल आयतन समान रखें।","kn":"ಪ್ರತಿ ಪ್ರಯೋಗದಲ್ಲೂ ಒಟ್ಟು ಘನಫಲ ಒಂದೇ ಇರಲಿ."},{"en":"Work in a ventilated room: sulphur dioxide is given off.","hi":"हवादार कमरे में काम करें: सल्फ़र डाइऑक्साइड निकलती है।","kn":"ಗಾಳಿಯಾಡುವ ಕೋಣೆಯಲ್ಲಿ ಕೆಲಸ ಮಾಡಿ: ಸಲ್ಫರ್ ಡೈಆಕ್ಸೈಡ್ ಬಿಡುಗಡೆಯಾಗುತ್ತದೆ."},{"en":"Use the same cross and the same observer.","hi":"एक ही क्रॉस और एक ही प्रेक्षक रखें।","kn":"ಒಂದೇ ಅಡ್ಡಗುರುತು ಮತ್ತು ಒಂದೇ ವೀಕ್ಷಕ ಇರಲಿ."}],"conclusion":{"en":"The rate (1/t) is directly proportional to the thiosulphate concentration, and it about doubles for a 10 °C rise in temperature.","hi":"दर (1/t) थायोसल्फ़ेट की सांद्रता के अनुक्रमानुपाती है, और ताप में 10 °C वृद्धि पर लगभग दोगुनी होती है।","kn":"ದರ (1/t) ಥಯೋಸಲ್ಫೇಟ್ ಸಾಂದ್ರತೆಗೆ ನೇರ ಅನುಪಾತೀಯ; ತಾಪದಲ್ಲಿ 10 °C ಏರಿಕೆಗೆ ಸುಮಾರು ಎರಡು ಪಟ್ಟಾಗುತ್ತದೆ."},"viva":[{"q":{"en":"Why does temperature increase the rate so much?","hi":"ताप दर को इतना क्यों बढ़ाता है?","kn":"ತಾಪ ದರವನ್ನು ಇಷ್ಟು ಏಕೆ ಹೆಚ್ಚಿಸುತ್ತದೆ?"},"a":{"en":"Many more molecules have at least the activation energy (Arrhenius).","hi":"कहीं अधिक अणुओं के पास कम से कम सक्रियण ऊर्जा होती है (आर्हीनियस)।","kn":"ಹೆಚ್ಚು ಅಣುಗಳಿಗೆ ಕನಿಷ್ಠ ಸಕ್ರಿಯಗೊಳಿಸುವ ಶಕ್ತಿ ಇರುತ್ತದೆ (ಆರ್ಹೇನಿಯಸ್)."}},{"q":{"en":"What is the order with respect to thiosulphate?","hi":"थायोसल्फ़ेट के सापेक्ष कोटि क्या है?","kn":"ಥಯೋಸಲ್ಫೇಟ್‌ಗೆ ಸಂಬಂಧಿಸಿ ಕ್ರಮಾಂಕ ಏನು?"},"a":{"en":"First order: 1/t is proportional to its concentration.","hi":"प्रथम कोटि: 1/t उसकी सांद्रता के अनुक्रमानुपाती है।","kn":"ಪ್ರಥಮ ಕ್ರಮಾಂಕ: 1/t ಅದರ ಸಾಂದ್ರತೆಗೆ ಅನುಪಾತೀಯ."}},{"q":{"en":"What makes the solution cloudy?","hi":"विलयन को धुँधला क्या बनाता है?","kn":"ದ್ರಾವಣವನ್ನು ಮಬ್ಬಾಗಿಸುವುದು ಯಾವುದು?"},"a":{"en":"Fine particles of sulphur (a colloid).","hi":"गंधक के बारीक कण (कोलॉइड)।","kn":"ಗಂಧಕದ ಸೂಕ್ಷ್ಮ ಕಣಗಳು (ಕಲಿಲ)."}}]},{"id":"leaf-pigment-chromatography","bench":"chromatography","setup":{"mixture":"leaf"},"subject":"Chemistry","domain":"chemistry","levels":["11","12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["chromatography","paper chromatography","leaf pigments","chlorophyll","rf value","photosynthesis","purification"],"title":{"en":"Separating leaf pigments by paper chromatography","hi":"कागज़ वर्णलेखन से पत्ती के वर्णक अलग करना","kn":"ಕಾಗದ ವರ್ಣರೇಖನದಿಂದ ಎಲೆಯ ವರ್ಣದ್ರವ್ಯಗಳನ್ನು ಬೇರ್ಪಡಿಸುವುದು"},"summary":{"en":"Run a spot of spinach extract up a paper strip and measure the Rf of each pigment.","hi":"पालक के सत्त के धब्बे को कागज़ की पट्टी पर चढ़ाएँ और हर वर्णक का Rf मापें।","kn":"ಪಾಲಕ್ ಸಾರದ ಚುಕ್ಕೆಯನ್ನು ಕಾಗದದ ಪಟ್ಟಿಯ ಮೇಲೆ ಏರಿಸಿ ಪ್ರತಿ ವರ್ಣದ್ರವ್ಯದ Rf ಅಳೆಯಿರಿ."},"aim":{"en":"To separate the pigments of a green leaf by paper chromatography and find their Rf values.","hi":"कागज़ वर्णलेखन द्वारा हरी पत्ती के वर्णकों को अलग करना और उनके Rf मान ज्ञात करना।","kn":"ಕಾಗದ ವರ್ಣರೇಖನದಿಂದ ಹಸಿರು ಎಲೆಯ ವರ್ಣದ್ರವ್ಯಗಳನ್ನು ಬೇರ್ಪಡಿಸಿ ಅವುಗಳ Rf ಮೌಲ್ಯಗಳನ್ನು ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"The solvent rises through the paper by capillary action. Each pigment is shared between the moving solvent and the stationary water in the paper; the more it prefers the solvent, the further it travels. Rf = distance moved by the spot ÷ distance moved by the solvent front, a constant for a given pigment, paper and solvent.","hi":"विलायक केशिका क्रिया से कागज़ में ऊपर चढ़ता है। हर वर्णक चलते विलायक और कागज़ के स्थिर जल के बीच बँटता है; जितना वह विलायक को पसंद करता है, उतना आगे जाता है। Rf = धब्बे द्वारा तय दूरी ÷ विलायक अग्र द्वारा तय दूरी, जो किसी वर्णक, कागज़ और विलायक के लिए नियत है।","kn":"ದ್ರಾವಕ ಲೋಮನಾಳ ಕ್ರಿಯೆಯಿಂದ ಕಾಗದದಲ್ಲಿ ಏರುತ್ತದೆ. ಪ್ರತಿ ವರ್ಣದ್ರವ್ಯ ಚಲಿಸುವ ದ್ರಾವಕ ಮತ್ತು ಕಾಗದದ ಸ್ಥಿರ ನೀರಿನ ನಡುವೆ ಹಂಚಿಕೊಳ್ಳುತ್ತದೆ; ದ್ರಾವಕವನ್ನು ಎಷ್ಟು ಇಷ್ಟಪಡುತ್ತದೋ ಅಷ್ಟು ದೂರ ಹೋಗುತ್ತದೆ. Rf = ಚುಕ್ಕೆ ಕ್ರಮಿಸಿದ ದೂರ ÷ ದ್ರಾವಕ ಮುಂಚೂಣಿ ಕ್ರಮಿಸಿದ ದೂರ; ಒಂದು ವರ್ಣದ್ರವ್ಯ, ಕಾಗದ ಮತ್ತು ದ್ರಾವಕಕ್ಕೆ ಸ್ಥಿರ."},"apparatus":[{"en":"Chromatography paper strips","hi":"क्रोमैटोग्राफ़ी कागज़ की पट्टियाँ","kn":"ವರ್ಣರೇಖನ ಕಾಗದದ ಪಟ್ಟಿಗಳು"},{"en":"Glass jar with lid","hi":"ढक्कन सहित काँच का जार","kn":"ಮುಚ್ಚಳ ಸಹಿತ ಗಾಜಿನ ಜಾಡಿ"},{"en":"Capillary tube for spotting","hi":"धब्बा लगाने के लिए केशिका नली","kn":"ಚುಕ್ಕೆ ಇಡಲು ಲೋಮನಾಳ"},{"en":"Pencil and scale","hi":"पेंसिल और पैमाना","kn":"ಪೆನ್ಸಿಲ್ ಮತ್ತು ಅಳತೆಪಟ್ಟಿ"},{"en":"Spinach leaves, acetone, and petroleum ether–acetone (9 : 1)","hi":"पालक की पत्तियाँ, ऐसीटोन, और पेट्रोलियम ईथर–ऐसीटोन (9 : 1)","kn":"ಪಾಲಕ್ ಎಲೆಗಳು, ಅಸಿಟೋನ್, ಮತ್ತು ಪೆಟ್ರೋಲಿಯಂ ಈಥರ್–ಅಸಿಟೋನ್ (9 : 1)"}],"steps":[{"en":"Grind the leaves with a little acetone to get a dark green extract.","hi":"पत्तियों को थोड़े ऐसीटोन के साथ पीसकर गहरा हरा सत्त बनाएँ।","kn":"ಎಲೆಗಳನ್ನು ಸ್ವಲ್ಪ ಅಸಿಟೋನ್ ಜೊತೆ ಅರೆದು ಗಾಢ ಹಸಿರು ಸಾರ ಪಡೆಯಿರಿ."},{"en":"Put a small concentrated spot of extract on the pencil line, drying between applications.","hi":"पेंसिल रेखा पर सत्त का छोटा, गाढ़ा धब्बा लगाएँ, हर बार बीच में सुखाएँ।","kn":"ಪೆನ್ಸಿಲ್ ರೇಖೆಯ ಮೇಲೆ ಸಾರದ ಸಣ್ಣ ಸಾಂದ್ರ ಚುಕ್ಕೆ ಇಡಿ, ಪ್ರತಿ ಬಾರಿ ಒಣಗಿಸಿ."},{"en":"Hang the strip in the jar with its end in the solvent and close the lid.","hi":"पट्टी को जार में ऐसे लटकाएँ कि उसका सिरा विलायक में हो, और ढक्कन बंद करें।","kn":"ಪಟ್ಟಿಯನ್ನು ಅದರ ತುದಿ ದ್ರಾವಕದಲ್ಲಿರುವಂತೆ ಜಾಡಿಯಲ್ಲಿ ತೂಗುಹಾಕಿ ಮುಚ್ಚಳ ಮುಚ್ಚಿ."},{"en":"When the front is near the top, take the strip out and mark the front.","hi":"अग्र ऊपर के पास पहुँचने पर पट्टी निकालें और अग्र पर निशान लगाएँ।","kn":"ಮುಂಚೂಣಿ ಮೇಲ್ಭಾಗದ ಹತ್ತಿರ ಬಂದಾಗ ಪಟ್ಟಿ ತೆಗೆದು ಮುಂಚೂಣಿ ಗುರುತಿಸಿ."},{"en":"Measure the distance of each coloured band and work out its Rf.","hi":"हर रंगीन पट्टी की दूरी मापकर उसका Rf निकालें।","kn":"ಪ್ರತಿ ಬಣ್ಣದ ಪಟ್ಟೆಯ ದೂರ ಅಳೆದು ಅದರ Rf ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Draw the starting line in pencil, not ink.","hi":"आरंभिक रेखा पेंसिल से खींचें, स्याही से नहीं।","kn":"ಆರಂಭಿಕ ರೇಖೆಯನ್ನು ಶಾಯಿಯಿಂದಲ್ಲ, ಪೆನ್ಸಿಲ್‌ನಿಂದ ಎಳೆಯಿರಿ."},{"en":"Keep the spot above the solvent level.","hi":"धब्बे को विलायक स्तर से ऊपर रखें।","kn":"ಚುಕ್ಕೆಯನ್ನು ದ್ರಾವಕ ಮಟ್ಟಕ್ಕಿಂತ ಮೇಲಿಡಿ."},{"en":"Keep the jar covered so the solvent vapour saturates it.","hi":"जार ढका रखें ताकि विलायक वाष्प उसे संतृप्त कर दे।","kn":"ದ್ರಾವಕ ಆವಿ ತುಂಬುವಂತೆ ಜಾಡಿಯನ್ನು ಮುಚ್ಚಿಡಿ."}],"conclusion":{"en":"Leaf extract separates into carotene, xanthophyll, chlorophyll a and chlorophyll b, each with its own Rf: green leaves contain several pigments.","hi":"पत्ती का सत्त कैरोटीन, ज़ैंथोफ़िल, क्लोरोफ़िल a और क्लोरोफ़िल b में अलग होता है, हर एक का अपना Rf: हरी पत्तियों में कई वर्णक होते हैं।","kn":"ಎಲೆಯ ಸಾರ ಕ್ಯಾರೋಟಿನ್, ಕ್ಸಾಂಥೋಫಿಲ್, ಕ್ಲೋರೋಫಿಲ್ a ಮತ್ತು ಕ್ಲೋರೋಫಿಲ್ b ಆಗಿ ಬೇರ್ಪಡುತ್ತದೆ, ಪ್ರತಿಯೊಂದಕ್ಕೂ ತನ್ನದೇ Rf: ಹಸಿರು ಎಲೆಗಳಲ್ಲಿ ಹಲವು ವರ್ಣದ್ರವ್ಯಗಳಿವೆ."},"viva":[{"q":{"en":"Can an Rf value be greater than 1?","hi":"क्या Rf मान 1 से अधिक हो सकता है?","kn":"Rf ಮೌಲ್ಯ 1 ಕ್ಕಿಂತ ಹೆಚ್ಚಿರಬಹುದೇ?"},"a":{"en":"No: no spot can move further than the solvent.","hi":"नहीं: कोई धब्बा विलायक से आगे नहीं जा सकता।","kn":"ಇಲ್ಲ: ಯಾವ ಚುಕ್ಕೆಯೂ ದ್ರಾವಕಕ್ಕಿಂತ ಮುಂದೆ ಹೋಗಲಾರದು."}},{"q":{"en":"Which pigment travels furthest, and why?","hi":"कौन-सा वर्णक सबसे दूर जाता है, और क्यों?","kn":"ಯಾವ ವರ್ಣದ್ರವ್ಯ ಅತಿ ದೂರ ಹೋಗುತ್ತದೆ, ಏಕೆ?"},"a":{"en":"Carotene: it is the least polar, so it stays with the non-polar solvent.","hi":"कैरोटीन: यह सबसे कम ध्रुवीय है, इसलिए अध्रुवीय विलायक के साथ रहता है।","kn":"ಕ್ಯಾರೋಟಿನ್: ಅದು ಅತಿ ಕಡಿಮೆ ಧ್ರುವೀಯ, ಆದ್ದರಿಂದ ಅಧ್ರುವೀಯ ದ್ರಾವಕದೊಂದಿಗೆ ಇರುತ್ತದೆ."}},{"q":{"en":"What is the stationary phase in paper chromatography?","hi":"कागज़ वर्णलेखन में स्थिर प्रावस्था क्या है?","kn":"ಕಾಗದ ವರ್ಣರೇಖನದಲ್ಲಿ ಸ್ಥಿರ ಪ್ರಾವಸ್ಥೆ ಯಾವುದು?"},"a":{"en":"Water held in the cellulose fibres of the paper.","hi":"कागज़ के सेलुलोज़ रेशों में रुका जल।","kn":"ಕಾಗದದ ಸೆಲ್ಯುಲೋಸ್ ನಾರುಗಳಲ್ಲಿ ಹಿಡಿದಿರುವ ನೀರು."}}]},{"id":"ink-chromatography","bench":"chromatography","setup":{"mixture":"inks"},"subject":"Forensics","domain":"forensics","levels":["9","10","11","12","ug"],"mode":"guided","curricula":["forensics"],"reviewed":false,"keywords":["forensic","ink analysis","questioned document","chromatography","forgery","rf value"],"title":{"en":"Forensic ink analysis by chromatography","hi":"वर्णलेखन द्वारा न्यायालयिक स्याही विश्लेषण","kn":"ವರ್ಣರೇಖನದಿಂದ ವಿಧಿವಿಜ್ಞಾನ ಶಾಯಿ ವಿಶ್ಲೇಷಣೆ"},"summary":{"en":"Separate the ink of a ransom note and of three suspects’ pens, and see which pen matches.","hi":"फिरौती के पत्र की और तीन संदिग्धों के पेनों की स्याही अलग करें, और देखें कि कौन-सा पेन मेल खाता है।","kn":"ಸುಲಿಗೆ ಪತ್ರದ ಮತ್ತು ಮೂವರು ಶಂಕಿತರ ಪೆನ್ನುಗಳ ಶಾಯಿಯನ್ನು ಬೇರ್ಪಡಿಸಿ, ಯಾವ ಪೆನ್ ಹೊಂದುತ್ತದೆ ನೋಡಿ."},"aim":{"en":"To compare the ink on a questioned document with inks from suspects’ pens using paper chromatography.","hi":"कागज़ वर्णलेखन से संदिग्ध दस्तावेज़ की स्याही की तुलना संदिग्धों के पेनों की स्याही से करना।","kn":"ಕಾಗದ ವರ್ಣರೇಖನದಿಂದ ಪ್ರಶ್ನಿತ ದಾಖಲೆಯ ಶಾಯಿಯನ್ನು ಶಂಕಿತರ ಪೆನ್ನುಗಳ ಶಾಯಿಯೊಂದಿಗೆ ಹೋಲಿಸುವುದು."},"principle":{"en":"Most inks are mixtures of dyes. Chromatography separates them into spots with characteristic Rf values. If the note’s ink gives the same dyes at the same Rf values as a pen’s ink, that pen (or one with the same ink) could have been used; a different pattern rules the pen out.","hi":"अधिकांश स्याहियाँ रंजकों का मिश्रण होती हैं। वर्णलेखन उन्हें विशिष्ट Rf मानों वाले धब्बों में अलग करता है। यदि पत्र की स्याही किसी पेन की स्याही जैसे ही रंजक समान Rf पर देती है, तो वह पेन (या उसी स्याही वाला) प्रयुक्त हो सकता है; भिन्न प्रतिरूप उस पेन को बाहर कर देता है।","kn":"ಹೆಚ್ಚಿನ ಶಾಯಿಗಳು ಬಣ್ಣಗಳ ಮಿಶ್ರಣ. ವರ್ಣರೇಖನ ಅವುಗಳನ್ನು ವಿಶಿಷ್ಟ Rf ಮೌಲ್ಯಗಳ ಚುಕ್ಕೆಗಳಾಗಿ ಬೇರ್ಪಡಿಸುತ್ತದೆ. ಪತ್ರದ ಶಾಯಿ ಒಂದು ಪೆನ್ನಿನ ಶಾಯಿಯಂತೆಯೇ ಅದೇ Rf ನಲ್ಲಿ ಅದೇ ಬಣ್ಣಗಳನ್ನು ನೀಡಿದರೆ ಆ ಪೆನ್ (ಅಥವಾ ಅದೇ ಶಾಯಿಯದು) ಬಳಸಿರಬಹುದು; ಬೇರೆ ಮಾದರಿ ಆ ಪೆನ್ನನ್ನು ಹೊರಗಿಡುತ್ತದೆ."},"apparatus":[{"en":"Chromatography paper strips","hi":"क्रोमैटोग्राफ़ी कागज़ की पट्टियाँ","kn":"ವರ್ಣರೇಖನ ಕಾಗದದ ಪಟ್ಟಿಗಳು"},{"en":"Glass jar with lid","hi":"ढक्कन सहित काँच का जार","kn":"ಮುಚ್ಚಳ ಸಹಿತ ಗಾಜಿನ ಜಾಡಿ"},{"en":"Capillary tube for spotting","hi":"धब्बा लगाने के लिए केशिका नली","kn":"ಚುಕ್ಕೆ ಇಡಲು ಲೋಮನಾಳ"},{"en":"Pencil and scale","hi":"पेंसिल और पैमाना","kn":"ಪೆನ್ಸಿಲ್ ಮತ್ತು ಅಳತೆಪಟ್ಟಿ"},{"en":"Ink sample cut from the note; pens A, B and C","hi":"पत्र से काटा स्याही नमूना; पेन A, B और C","kn":"ಪತ್ರದಿಂದ ಕತ್ತರಿಸಿದ ಶಾಯಿ ಮಾದರಿ; ಪೆನ್ನುಗಳು A, B ಮತ್ತು C"},{"en":"Solvent: water–ethanol (or butanol–ethanol–ammonia)","hi":"विलायक: जल–एथेनॉल (या ब्यूटेनॉल–एथेनॉल–अमोनिया)","kn":"ದ್ರಾವಕ: ನೀರು–ಎಥೆನಾಲ್ (ಅಥವಾ ಬ್ಯೂಟನಾಲ್–ಎಥೆನಾಲ್–ಅಮೋನಿಯಾ)"}],"steps":[{"en":"Spot the note’s ink and each pen’s ink on separate strips (or side by side on one sheet).","hi":"पत्र की स्याही और हर पेन की स्याही अलग पट्टियों पर (या एक ही शीट पर साथ-साथ) लगाएँ।","kn":"ಪತ್ರದ ಶಾಯಿ ಮತ್ತು ಪ್ರತಿ ಪೆನ್ನಿನ ಶಾಯಿಯನ್ನು ಬೇರೆ ಪಟ್ಟಿಗಳ ಮೇಲೆ (ಅಥವಾ ಒಂದೇ ಹಾಳೆಯಲ್ಲಿ ಪಕ್ಕಪಕ್ಕ) ಇಡಿ."},{"en":"Develop all the strips together in the same solvent.","hi":"सभी पट्टियों को एक ही विलायक में साथ विकसित करें।","kn":"ಎಲ್ಲ ಪಟ್ಟಿಗಳನ್ನು ಒಂದೇ ದ್ರಾವಕದಲ್ಲಿ ಒಟ್ಟಿಗೆ ಅಭಿವೃದ್ಧಿಪಡಿಸಿ."},{"en":"Mark the solvent front and measure every spot.","hi":"विलायक अग्र पर निशान लगाकर हर धब्बा मापें।","kn":"ದ್ರಾವಕ ಮುಂಚೂಣಿ ಗುರುತಿಸಿ ಪ್ರತಿ ಚುಕ್ಕೆ ಅಳೆಯಿರಿ."},{"en":"Compare the colours and Rf values of the note with each pen.","hi":"पत्र के रंगों और Rf मानों की हर पेन से तुलना करें।","kn":"ಪತ್ರದ ಬಣ್ಣಗಳು ಮತ್ತು Rf ಮೌಲ್ಯಗಳನ್ನು ಪ್ರತಿ ಪೆನ್ನಿನೊಂದಿಗೆ ಹೋಲಿಸಿ."},{"en":"Record which pens are excluded and which cannot be excluded.","hi":"लिखें कि कौन-से पेन बाहर हुए और कौन-से बाहर नहीं किए जा सकते।","kn":"ಯಾವ ಪೆನ್ನುಗಳು ಹೊರಗುಳಿದವು, ಯಾವುವು ಹೊರಗಿಡಲಾಗದು ಬರೆಯಿರಿ."}],"precautions":[{"en":"Draw the starting line in pencil, not ink.","hi":"आरंभिक रेखा पेंसिल से खींचें, स्याही से नहीं।","kn":"ಆರಂಭಿಕ ರೇಖೆಯನ್ನು ಶಾಯಿಯಿಂದಲ್ಲ, ಪೆನ್ಸಿಲ್‌ನಿಂದ ಎಳೆಯಿರಿ."},{"en":"Keep the spot above the solvent level.","hi":"धब्बे को विलायक स्तर से ऊपर रखें।","kn":"ಚುಕ್ಕೆಯನ್ನು ದ್ರಾವಕ ಮಟ್ಟಕ್ಕಿಂತ ಮೇಲಿಡಿ."},{"en":"Keep the jar covered so the solvent vapour saturates it.","hi":"जार ढका रखें ताकि विलायक वाष्प उसे संतृप्त कर दे।","kn":"ದ್ರಾವಕ ಆವಿ ತುಂಬುವಂತೆ ಜಾಡಿಯನ್ನು ಮುಚ್ಚಿಡಿ."},{"en":"Handle evidence with gloves and label every sample.","hi":"साक्ष्य को दस्ताने पहनकर संभालें और हर नमूने पर लेबल लगाएँ।","kn":"ಸಾಕ್ಷ್ಯವನ್ನು ಕೈಗವಸು ಧರಿಸಿ ನಿರ್ವಹಿಸಿ, ಪ್ರತಿ ಮಾದರಿಗೆ ಹಣೆಪಟ್ಟಿ ಹಾಕಿ."}],"conclusion":{"en":"Only one pen’s ink gives the same dyes at the same Rf values as the note; the others are excluded. A match is supporting evidence, since many pens can share one ink.","hi":"केवल एक पेन की स्याही पत्र जैसे ही रंजक समान Rf पर देती है; बाकी बाहर हो जाते हैं। मेल केवल सहायक साक्ष्य है, क्योंकि कई पेनों में एक ही स्याही हो सकती है।","kn":"ಒಂದೇ ಪೆನ್ನಿನ ಶಾಯಿ ಮಾತ್ರ ಪತ್ರದಂತೆಯೇ ಅದೇ Rf ನಲ್ಲಿ ಅದೇ ಬಣ್ಣಗಳನ್ನು ನೀಡುತ್ತದೆ; ಉಳಿದವು ಹೊರಗುಳಿಯುತ್ತವೆ. ಹೊಂದಿಕೆ ಪೂರಕ ಸಾಕ್ಷ್ಯ ಮಾತ್ರ, ಏಕೆಂದರೆ ಹಲವು ಪೆನ್ನುಗಳಲ್ಲಿ ಒಂದೇ ಶಾಯಿ ಇರಬಹುದು."},"viva":[{"q":{"en":"Why is a match not proof that the suspect wrote the note?","hi":"मेल यह प्रमाण क्यों नहीं कि संदिग्ध ने पत्र लिखा?","kn":"ಹೊಂದಿಕೆ ಶಂಕಿತನೇ ಪತ್ರ ಬರೆದನೆಂಬುದಕ್ಕೆ ಪುರಾವೆ ಏಕೆ ಅಲ್ಲ?"},"a":{"en":"Many pens of the same brand share the same ink; it only shows the pen could have been used.","hi":"एक ही ब्रांड के कई पेनों में एक ही स्याही होती है; यह केवल दिखाता है कि वह पेन प्रयुक्त हो सकता था।","kn":"ಒಂದೇ ಬ್ರ್ಯಾಂಡ್‌ನ ಹಲವು ಪೆನ್ನುಗಳಲ್ಲಿ ಒಂದೇ ಶಾಯಿ; ಆ ಪೆನ್ ಬಳಸಿರಬಹುದು ಎಂದು ಮಾತ್ರ ತೋರಿಸುತ್ತದೆ."}},{"q":{"en":"Why are all samples run on the same sheet?","hi":"सभी नमूने एक ही शीट पर क्यों चलाए जाते हैं?","kn":"ಎಲ್ಲ ಮಾದರಿಗಳನ್ನು ಒಂದೇ ಹಾಳೆಯಲ್ಲಿ ಏಕೆ ಓಡಿಸುತ್ತಾರೆ?"},"a":{"en":"So the paper, solvent and conditions are identical and Rf values can be compared directly.","hi":"ताकि कागज़, विलायक और परिस्थितियाँ एक-सी हों और Rf मान सीधे तुलनीय हों।","kn":"ಕಾಗದ, ದ್ರಾವಕ ಮತ್ತು ಪರಿಸ್ಥಿತಿಗಳು ಒಂದೇ ಆಗಿದ್ದು Rf ಮೌಲ್ಯಗಳನ್ನು ನೇರವಾಗಿ ಹೋಲಿಸಲು."}},{"q":{"en":"Name a more sensitive method used in forensic labs.","hi":"न्यायालयिक प्रयोगशालाओं में प्रयुक्त अधिक संवेदनशील विधि बताइए।","kn":"ವಿಧಿವಿಜ್ಞಾನ ಪ್ರಯೋಗಾಲಯಗಳಲ್ಲಿ ಬಳಸುವ ಹೆಚ್ಚು ಸಂವೇದಿ ವಿಧಾನ ಹೆಸರಿಸಿ."},"a":{"en":"Thin-layer chromatography (TLC) or HPLC.","hi":"पतली परत वर्णलेखन (TLC) या HPLC.","kn":"ತೆಳು ಪದರ ವರ್ಣರೇಖನ (TLC) ಅಥವಾ HPLC."}}]},{"id":"enthalpy-neutralisation","bench":"neutralisation","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["11","12"],"mode":"guided","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["thermochemistry","enthalpy of neutralisation","enthalpy of neutralization","calorimetry","thermodynamics","heat of reaction"],"title":{"en":"Enthalpy of neutralisation","hi":"उदासीनीकरण की एन्थैल्पी","kn":"ತಟಸ್ಥೀಕರಣದ ಎಂಥಾಲ್ಪಿ"},"summary":{"en":"Mix acid and alkali in an insulated cup, read the temperature rise and work out ΔH.","hi":"ऊष्मारोधी कप में अम्ल और क्षार मिलाएँ, ताप वृद्धि पढ़ें और ΔH निकालें।","kn":"ಉಷ್ಣನಿರೋಧಕ ಕಪ್‌ನಲ್ಲಿ ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರ ಬೆರೆಸಿ, ತಾಪ ಏರಿಕೆ ಓದಿ ΔH ಲೆಕ್ಕಿಸಿ."},"aim":{"en":"To find the enthalpy of neutralisation of a strong acid (HCl) and a weak acid (acetic acid) with sodium hydroxide.","hi":"सोडियम हाइड्रॉक्साइड से प्रबल अम्ल (HCl) और दुर्बल अम्ल (ऐसीटिक अम्ल) के उदासीनीकरण की एन्थैल्पी ज्ञात करना।","kn":"ಸೋಡಿಯಂ ಹೈಡ್ರಾಕ್ಸೈಡ್‌ನೊಂದಿಗೆ ಪ್ರಬಲ ಆಮ್ಲ (HCl) ಮತ್ತು ದುರ್ಬಲ ಆಮ್ಲ (ಅಸಿಟಿಕ್ ಆಮ್ಲ) ದ ತಟಸ್ಥೀಕರಣ ಎಂಥಾಲ್ಪಿ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Neutralisation is H⁺ + OH⁻ → H₂O, ΔH ≈ −57 kJ per mole of water for any strong acid and strong base. The heat raises the temperature of the solution and the calorimeter: q = (mc + W)ΔT, and ΔH = −q ÷ moles of water. A weak acid gives a little less, because some heat is used to ionise it.","hi":"उदासीनीकरण H⁺ + OH⁻ → H₂O है, किसी भी प्रबल अम्ल-प्रबल क्षार के लिए प्रति मोल जल ΔH ≈ −57 kJ. ऊष्मा विलयन और कैलोरीमीटर का ताप बढ़ाती है: q = (mc + W)ΔT, और ΔH = −q ÷ जल के मोल। दुर्बल अम्ल थोड़ा कम देता है, क्योंकि कुछ ऊष्मा उसे आयनित करने में लगती है।","kn":"ತಟಸ್ಥೀಕರಣ H⁺ + OH⁻ → H₂O, ಯಾವುದೇ ಪ್ರಬಲ ಆಮ್ಲ-ಪ್ರಬಲ ಕ್ಷಾರಕ್ಕೆ ಪ್ರತಿ ಮೋಲ್ ನೀರಿಗೆ ΔH ≈ −57 kJ. ಉಷ್ಣ ದ್ರಾವಣ ಮತ್ತು ಕ್ಯಾಲೊರಿಮೀಟರ್‌ನ ತಾಪ ಏರಿಸುತ್ತದೆ: q = (mc + W)ΔT, ΔH = −q ÷ ನೀರಿನ ಮೋಲ್. ದುರ್ಬಲ ಆಮ್ಲ ಸ್ವಲ್ಪ ಕಡಿಮೆ ನೀಡುತ್ತದೆ, ಏಕೆಂದರೆ ಸ್ವಲ್ಪ ಉಷ್ಣ ಅದನ್ನು ಅಯಾನೀಕರಿಸಲು ಬಳಕೆಯಾಗುತ್ತದೆ."},"apparatus":[{"en":"Polystyrene cup calorimeter with lid","hi":"ढक्कन सहित पॉलीस्टाइरीन कप कैलोरीमीटर","kn":"ಮುಚ್ಚಳ ಸಹಿತ ಪಾಲಿಸ್ಟೈರೀನ್ ಕಪ್ ಕ್ಯಾಲೊರಿಮೀಟರ್"},{"en":"Thermometer (0.1 °C)","hi":"तापमापी (0.1 °C)","kn":"ತಾಪಮಾಪಕ (0.1 °C)"},{"en":"1 M HCl, 1 M acetic acid and 1 M NaOH","hi":"1 M HCl, 1 M ऐसीटिक अम्ल और 1 M NaOH","kn":"1 M HCl, 1 M ಅಸಿಟಿಕ್ ಆಮ್ಲ ಮತ್ತು 1 M NaOH"},{"en":"Measuring cylinders (50 mL)","hi":"मापक सिलिंडर (50 mL)","kn":"ಅಳತೆ ಸಿಲಿಂಡರ್‌ಗಳು (50 mL)"}],"steps":[{"en":"Find the water equivalent of the calorimeter (or use the value given).","hi":"कैलोरीमीटर का जल तुल्यांक ज्ञात करें (या दिया गया मान लें)।","kn":"ಕ್ಯಾಲೊರಿಮೀಟರ್‌ನ ಜಲ ಸಮಾನಾಂಕ ಕಂಡುಹಿಡಿಯಿರಿ (ಅಥವಾ ಕೊಟ್ಟ ಮೌಲ್ಯ ಬಳಸಿ)."},{"en":"Put 50 mL of 1 M HCl in the cup and note its temperature; check the NaOH is at the same temperature.","hi":"कप में 50 mL 1 M HCl डालकर उसका ताप लिखें; जाँचें कि NaOH उसी ताप पर है।","kn":"ಕಪ್‌ನಲ್ಲಿ 50 mL 1 M HCl ಹಾಕಿ ಅದರ ತಾಪ ಬರೆಯಿರಿ; NaOH ಅದೇ ತಾಪದಲ್ಲಿದೆಯೇ ಪರಿಶೀಲಿಸಿ."},{"en":"Pour in 50 mL of 1 M NaOH, stir and record the highest temperature.","hi":"50 mL 1 M NaOH डालें, हिलाएँ और सबसे अधिक ताप लिखें।","kn":"50 mL 1 M NaOH ಸುರಿದು ಕಲಕಿ ಅತಿ ಹೆಚ್ಚಿನ ತಾಪ ದಾಖಲಿಸಿ."},{"en":"Work out q and ΔH per mole of water formed.","hi":"q और बने जल के प्रति मोल ΔH निकालें।","kn":"q ಮತ್ತು ಉಂಟಾದ ನೀರಿನ ಪ್ರತಿ ಮೋಲ್‌ಗೆ ΔH ಲೆಕ್ಕಿಸಿ."},{"en":"Repeat with acetic acid and compare.","hi":"ऐसीटिक अम्ल के साथ दोहराएँ और तुलना करें।","kn":"ಅಸಿಟಿಕ್ ಆಮ್ಲದೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಹೋಲಿಸಿ."}],"precautions":[{"en":"Keep the cup covered and stir gently to lose little heat.","hi":"ऊष्मा हानि कम रखने के लिए कप ढका रखें और धीरे हिलाएँ।","kn":"ಉಷ್ಣ ನಷ್ಟ ಕಡಿಮೆ ಇರಲು ಕಪ್ ಮುಚ್ಚಿ ನಿಧಾನವಾಗಿ ಕಲಕಿ."},{"en":"Start with both solutions at the same temperature.","hi":"दोनों विलयन एक ही ताप से शुरू करें।","kn":"ಎರಡೂ ದ್ರಾವಣಗಳನ್ನು ಒಂದೇ ತಾಪದಿಂದ ಆರಂಭಿಸಿ."},{"en":"Wear safety goggles; acids and alkalis harm the eyes.","hi":"सुरक्षा चश्मा पहनें; अम्ल और क्षार आँखों को हानि पहुँचाते हैं।","kn":"ಸುರಕ್ಷಾ ಕನ್ನಡಕ ಧರಿಸಿ; ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರಗಳು ಕಣ್ಣಿಗೆ ಹಾನಿ ಮಾಡುತ್ತವೆ."}],"conclusion":{"en":"The strong acid gives about −57 kJ per mole of water; acetic acid a little less, as part of the heat goes to ionising the weak acid.","hi":"प्रबल अम्ल प्रति मोल जल लगभग −57 kJ देता है; ऐसीटिक अम्ल थोड़ा कम, क्योंकि ऊष्मा का कुछ भाग दुर्बल अम्ल को आयनित करने में जाता है।","kn":"ಪ್ರಬಲ ಆಮ್ಲ ಪ್ರತಿ ಮೋಲ್ ನೀರಿಗೆ ಸುಮಾರು −57 kJ ನೀಡುತ್ತದೆ; ಅಸಿಟಿಕ್ ಆಮ್ಲ ಸ್ವಲ್ಪ ಕಡಿಮೆ, ಏಕೆಂದರೆ ಉಷ್ಣದ ಭಾಗ ದುರ್ಬಲ ಆಮ್ಲವನ್ನು ಅಯಾನೀಕರಿಸಲು ಹೋಗುತ್ತದೆ."},"viva":[{"q":{"en":"Why is ΔH the same for every strong acid and strong base?","hi":"हर प्रबल अम्ल-प्रबल क्षार के लिए ΔH समान क्यों है?","kn":"ಪ್ರತಿ ಪ್ರಬಲ ಆಮ್ಲ-ಪ್ರಬಲ ಕ್ಷಾರಕ್ಕೆ ΔH ಏಕೆ ಒಂದೇ?"},"a":{"en":"Both are fully ionised, so the only reaction is H⁺ + OH⁻ → H₂O.","hi":"दोनों पूर्णतः आयनित हैं, इसलिए एकमात्र अभिक्रिया H⁺ + OH⁻ → H₂O है।","kn":"ಎರಡೂ ಸಂಪೂರ್ಣ ಅಯಾನೀಕೃತ; ಆದ್ದರಿಂದ ಇರುವ ಪ್ರತಿಕ್ರಿಯೆ H⁺ + OH⁻ → H₂O ಮಾತ್ರ."}},{"q":{"en":"Is neutralisation exothermic or endothermic?","hi":"उदासीनीकरण ऊष्माक्षेपी है या ऊष्माशोषी?","kn":"ತಟಸ್ಥೀಕರಣ ಉಷ್ಣವಿಮೋಚಕವೇ ಉಷ್ಣಶೋಷಕವೇ?"},"a":{"en":"Exothermic: ΔH is negative.","hi":"ऊष्माक्षेपी: ΔH ऋणात्मक है।","kn":"ಉಷ್ಣವಿಮೋಚಕ: ΔH ಋಣ."}},{"q":{"en":"Why use a polystyrene cup?","hi":"पॉलीस्टाइरीन कप क्यों?","kn":"ಪಾಲಿಸ್ಟೈರೀನ್ ಕಪ್ ಏಕೆ?"},"a":{"en":"It is a poor conductor with a small heat capacity, so little heat is lost.","hi":"यह कम ऊष्मा धारिता वाला कुचालक है, इसलिए कम ऊष्मा खोती है।","kn":"ಅದು ಕಡಿಮೆ ಉಷ್ಣ ಧಾರಣಶಕ್ತಿಯ ಅವಾಹಕ; ಆದ್ದರಿಂದ ಕಡಿಮೆ ಉಷ್ಣ ನಷ್ಟ."}}]},{"id":"ester-hydrolysis","bench":"ester-hydrolysis","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["ug"],"mode":"guided","curricula":["ug-chemistry"],"reviewed":false,"keywords":["chemical kinetics","ester hydrolysis","methyl acetate","first order reaction","rate constant","acid catalysis"],"title":{"en":"Kinetics of acid hydrolysis of methyl acetate","hi":"मेथिल ऐसीटेट के अम्लीय जल-अपघटन की गतिकी","kn":"ಮೀಥೈಲ್ ಅಸಿಟೇಟ್‌ನ ಆಮ್ಲ ಜಲವಿಭಜನೆಯ ಚಲನಶಾಸ್ತ್ರ"},"summary":{"en":"Titrate samples of the reaction mixture over time; the log plot gives the first-order rate constant.","hi":"समय के साथ अभिक्रिया मिश्रण के नमूनों का अनुमापन करें; लघुगणक ग्राफ़ से प्रथम कोटि दर नियतांक मिलता है।","kn":"ಸಮಯದೊಂದಿಗೆ ಪ್ರತಿಕ್ರಿಯಾ ಮಿಶ್ರಣದ ಮಾದರಿಗಳನ್ನು ಅನುಮಾಪನ ಮಾಡಿ; ಲಾಗ್ ನಕ್ಷೆ ಪ್ರಥಮ ಕ್ರಮಾಂಕ ದರ ಸ್ಥಿರಾಂಕ ನೀಡುತ್ತದೆ."},"aim":{"en":"To find the rate constant of the acid-catalysed hydrolysis of methyl acetate at two temperatures.","hi":"दो तापों पर मेथिल ऐसीटेट के अम्ल-उत्प्रेरित जल-अपघटन का दर नियतांक ज्ञात करना।","kn":"ಎರಡು ತಾಪಗಳಲ್ಲಿ ಮೀಥೈಲ್ ಅಸಿಟೇಟ್‌ನ ಆಮ್ಲ-ವೇಗವರ್ಧಿತ ಜಲವಿಭಜನೆಯ ದರ ಸ್ಥಿರಾಂಕ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"CH₃COOCH₃ + H₂O → CH₃COOH + CH₃OH, catalysed by H⁺. Water is in large excess, so the reaction is pseudo-first order. The acetic acid formed raises the titre against NaOH: k = (2.303/t) log((V∞ − V₀)/(V∞ − Vt)), so log(V∞ − Vt) against t is a straight line of slope −k/2.303.","hi":"CH₃COOCH₃ + H₂O → CH₃COOH + CH₃OH, H⁺ द्वारा उत्प्रेरित। जल बहुत अधिक मात्रा में है, इसलिए अभिक्रिया छद्म-प्रथम कोटि की है। बना ऐसीटिक अम्ल NaOH से अनुमापांक बढ़ाता है: k = (2.303/t) log((V∞ − V₀)/(V∞ − Vt)), अतः log(V∞ − Vt) और t का ग्राफ़ −k/2.303 प्रवणता की सीधी रेखा है।","kn":"CH₃COOCH₃ + H₂O → CH₃COOH + CH₃OH, H⁺ ವೇಗವರ್ಧಿತ. ನೀರು ಅತಿ ಹೆಚ್ಚು ಪ್ರಮಾಣದಲ್ಲಿರುವುದರಿಂದ ಪ್ರತಿಕ್ರಿಯೆ ಹುಸಿ-ಪ್ರಥಮ ಕ್ರಮಾಂಕ. ಉಂಟಾದ ಅಸಿಟಿಕ್ ಆಮ್ಲ NaOH ವಿರುದ್ಧ ಅನುಮಾಪನಾಂಕ ಏರಿಸುತ್ತದೆ: k = (2.303/t) log((V∞ − V₀)/(V∞ − Vt)); ಆದ್ದರಿಂದ log(V∞ − Vt) ಮತ್ತು t ನಕ್ಷೆ −k/2.303 ಇಳಿಜಾರಿನ ಸರಳರೇಖೆ."},"apparatus":[{"en":"Methyl acetate and 0.5 M HCl","hi":"मेथिल ऐसीटेट और 0.5 M HCl","kn":"ಮೀಥೈಲ್ ಅಸಿಟೇಟ್ ಮತ್ತು 0.5 M HCl"},{"en":"0.2 M NaOH and phenolphthalein","hi":"0.2 M NaOH और फ़िनॉल्फ़्थेलिन","kn":"0.2 M NaOH ಮತ್ತು ಫೀನಾಲ್ಫ್ತಲೀನ್"},{"en":"Burette (50 mL) with stand","hi":"स्टैंड सहित ब्यूरेट (50 mL)","kn":"ಸ್ಟ್ಯಾಂಡ್ ಸಹಿತ ಬ್ಯೂರೆಟ್ (50 mL)"},{"en":"Thermostat bath, ice and stopwatch","hi":"थर्मोस्टैट ऊष्मक, बर्फ़ और विराम घड़ी","kn":"ಥರ್ಮೋಸ್ಟಾಟ್ ತೊಟ್ಟಿ, ಮಂಜುಗಡ್ಡೆ ಮತ್ತು ನಿಲುಗಡಿಯಾರ"}],"steps":[{"en":"Mix 5 mL of ester with 100 mL of HCl in the bath and start the clock.","hi":"ऊष्मक में 5 mL एस्टर को 100 mL HCl के साथ मिलाकर घड़ी चालू करें।","kn":"ತೊಟ್ಟಿಯಲ್ಲಿ 5 mL ಎಸ್ಟರನ್ನು 100 mL HCl ಜೊತೆ ಬೆರೆಸಿ ಗಡಿಯಾರ ಆರಂಭಿಸಿ."},{"en":"At once, and every 10–20 minutes, pipette 5 mL into ice water and titrate with NaOH (Vt).","hi":"तुरंत और हर 10–20 मिनट पर 5 mL बर्फ़ीले पानी में पिपेट से लें और NaOH से अनुमापन करें (Vt)।","kn":"ತಕ್ಷಣ ಮತ್ತು ಪ್ರತಿ 10–20 ನಿಮಿಷಕ್ಕೆ 5 mL ಅನ್ನು ಮಂಜುಗಡ್ಡೆ ನೀರಿಗೆ ಪಿಪೆಟ್ ಮಾಡಿ NaOH ನಿಂದ ಅನುಮಾಪನ ಮಾಡಿ (Vt)."},{"en":"Heat a sample to complete the reaction and titrate it for V∞.","hi":"एक नमूने को गरम कर अभिक्रिया पूरी करें और V∞ के लिए अनुमापन करें।","kn":"ಒಂದು ಮಾದರಿಯನ್ನು ಬಿಸಿಮಾಡಿ ಪ್ರತಿಕ್ರಿಯೆ ಪೂರ್ಣಗೊಳಿಸಿ V∞ ಗಾಗಿ ಅನುಮಾಪನ ಮಾಡಿ."},{"en":"Plot log(V∞ − Vt) against t; k = −2.303 × slope.","hi":"log(V∞ − Vt) और t का ग्राफ़ बनाएँ; k = −2.303 × प्रवणता।","kn":"log(V∞ − Vt) ಮತ್ತು t ನಕ್ಷೆ ಎಳೆಯಿರಿ; k = −2.303 × ಇಳಿಜಾರು."},{"en":"Repeat at 35 °C and estimate the activation energy from the two k values.","hi":"35 °C पर दोहराएँ और दो k मानों से सक्रियण ऊर्जा का अनुमान लगाएँ।","kn":"35 °C ನಲ್ಲಿ ಪುನರಾವರ್ತಿಸಿ ಎರಡು k ಮೌಲ್ಯಗಳಿಂದ ಸಕ್ರಿಯಗೊಳಿಸುವ ಶಕ್ತಿ ಅಂದಾಜಿಸಿ."},{"en":"Export the readings as CSV and fit the straight lines.","hi":"पाठ्यांक CSV में निर्यात कर सीधी रेखाएँ फ़िट करें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಸರಳರೇಖೆಗಳನ್ನು ಹೊಂದಿಸಿ."}],"precautions":[{"en":"Quench each sample in ice water to stop the reaction before titrating.","hi":"अनुमापन से पहले हर नमूने को बर्फ़ीले पानी में डालकर अभिक्रिया रोकें।","kn":"ಅನುಮಾಪನದ ಮೊದಲು ಪ್ರತಿ ಮಾದರಿಯನ್ನು ಮಂಜುಗಡ್ಡೆ ನೀರಿನಲ್ಲಿ ಹಾಕಿ ಪ್ರತಿಕ್ರಿಯೆ ನಿಲ್ಲಿಸಿ."},{"en":"Keep the bath temperature constant.","hi":"ऊष्मक का ताप नियत रखें।","kn":"ತೊಟ್ಟಿಯ ತಾಪ ಸ್ಥಿರವಾಗಿರಲಿ."},{"en":"Note the exact time each sample is taken.","hi":"हर नमूना लेने का सटीक समय लिखें।","kn":"ಪ್ರತಿ ಮಾದರಿ ತೆಗೆದ ನಿಖರ ಸಮಯ ಬರೆಯಿರಿ."}],"conclusion":{"en":"log(V∞ − Vt) falls linearly with time, so the hydrolysis is (pseudo) first order; k is a few × 10⁻³ per minute at 25 °C and larger at 35 °C.","hi":"log(V∞ − Vt) समय के साथ रैखिक रूप से घटता है, इसलिए जल-अपघटन (छद्म) प्रथम कोटि का है; 25 °C पर k कुछ × 10⁻³ प्रति मिनट और 35 °C पर अधिक है।","kn":"log(V∞ − Vt) ಸಮಯದೊಂದಿಗೆ ರೇಖೀಯವಾಗಿ ಇಳಿಯುತ್ತದೆ; ಆದ್ದರಿಂದ ಜಲವಿಭಜನೆ (ಹುಸಿ) ಪ್ರಥಮ ಕ್ರಮಾಂಕ; 25 °C ನಲ್ಲಿ k ಕೆಲವು × 10⁻³ ಪ್ರತಿ ನಿಮಿಷ, 35 °C ನಲ್ಲಿ ಹೆಚ್ಚು."},"viva":[{"q":{"en":"Why is it called pseudo-first order?","hi":"इसे छद्म-प्रथम कोटि क्यों कहते हैं?","kn":"ಇದನ್ನು ಹುಸಿ-ಪ್ರಥಮ ಕ್ರಮಾಂಕ ಏಕೆ ಎನ್ನುತ್ತಾರೆ?"},"a":{"en":"Water takes part but is in such excess that its concentration hardly changes.","hi":"जल भाग लेता है पर इतना अधिक है कि उसकी सांद्रता लगभग नहीं बदलती।","kn":"ನೀರು ಭಾಗವಹಿಸುತ್ತದೆ, ಆದರೆ ಅಷ್ಟು ಹೆಚ್ಚಿರುವುದರಿಂದ ಅದರ ಸಾಂದ್ರತೆ ಬಹುತೇಕ ಬದಲಾಗುವುದಿಲ್ಲ."}},{"q":{"en":"What does V₀ measure?","hi":"V₀ क्या मापता है?","kn":"V₀ ಏನನ್ನು ಅಳೆಯುತ್ತದೆ?"},"a":{"en":"The HCl catalyst only, before any acetic acid has formed.","hi":"केवल HCl उत्प्रेरक, कोई ऐसीटिक अम्ल बनने से पहले।","kn":"ಯಾವುದೇ ಅಸಿಟಿಕ್ ಆಮ್ಲ ಉಂಟಾಗುವ ಮೊದಲು HCl ವೇಗವರ್ಧಕ ಮಾತ್ರ."}},{"q":{"en":"How is the half-life related to k?","hi":"अर्ध-आयु का k से क्या संबंध है?","kn":"ಅರ್ಧಾಯುಷ್ಯ k ಯೊಂದಿಗೆ ಹೇಗೆ ಸಂಬಂಧಿಸಿದೆ?"},"a":{"en":"t½ = 0.693 ÷ k, independent of concentration.","hi":"t½ = 0.693 ÷ k, सांद्रता से स्वतंत्र।","kn":"t½ = 0.693 ÷ k, ಸಾಂದ್ರತೆಯಿಂದ ಸ್ವತಂತ್ರ."}}]},{"id":"beer-lambert","bench":"beer-lambert","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["ug"],"mode":"guided","curricula":["ug-chemistry"],"reviewed":false,"keywords":["colorimetry","spectrophotometry","beer-lambert law","beer lambert","absorbance","potassium permanganate","calibration curve"],"title":{"en":"Beer–Lambert law with a colorimeter","hi":"वर्णमापी से बीयर–लैम्बर्ट नियम","kn":"ವರ್ಣಮಾಪಕದಿಂದ ಬಿಯರ್–ಲ್ಯಾಂಬರ್ಟ್ ನಿಯಮ"},"summary":{"en":"Find λmax for KMnO₄, make a calibration line from standards and read an unknown concentration.","hi":"KMnO₄ के लिए λmax ज्ञात करें, मानकों से अंशांकन रेखा बनाएँ और अज्ञात सांद्रता पढ़ें।","kn":"KMnO₄ ಗೆ λmax ಕಂಡುಹಿಡಿದು, ಮಾನಕಗಳಿಂದ ಮಾಪನಾಂಕ ರೇಖೆ ರಚಿಸಿ ಅಜ್ಞಾತ ಸಾಂದ್ರತೆ ಓದಿ."},"aim":{"en":"To verify the Beer–Lambert law for potassium permanganate and find the concentration of an unknown solution.","hi":"पोटैशियम परमैंगनेट के लिए बीयर–लैम्बर्ट नियम का सत्यापन करना और अज्ञात विलयन की सांद्रता ज्ञात करना।","kn":"ಪೊಟ್ಯಾಸಿಯಂ ಪರ್ಮ್ಯಾಂಗನೇಟ್‌ಗೆ ಬಿಯರ್–ಲ್ಯಾಂಬರ್ಟ್ ನಿಯಮ ಪರಿಶೀಲಿಸಿ ಅಜ್ಞಾತ ದ್ರಾವಣದ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"Absorbance A = log(I₀/I) = εlc: at a fixed wavelength and path length, A is proportional to concentration. Measuring at the wavelength of maximum absorbance (λmax ≈ 525 nm for KMnO₄) gives the steepest, most sensitive line.","hi":"अवशोषणांक A = log(I₀/I) = εlc: नियत तरंगदैर्घ्य और पथ लंबाई पर A सांद्रता के अनुक्रमानुपाती है। अधिकतम अवशोषण की तरंगदैर्घ्य (KMnO₄ के लिए λmax ≈ 525 nm) पर मापने से सबसे खड़ी, सबसे संवेदनशील रेखा मिलती है।","kn":"ಹೀರಿಕೆ A = log(I₀/I) = εlc: ನಿಗದಿತ ತರಂಗಾಂತರ ಮತ್ತು ಪಥ ಉದ್ದದಲ್ಲಿ A ಸಾಂದ್ರತೆಗೆ ಅನುಪಾತೀಯ. ಗರಿಷ್ಠ ಹೀರಿಕೆಯ ತರಂಗಾಂತರದಲ್ಲಿ (KMnO₄ ಗೆ λmax ≈ 525 nm) ಅಳೆದರೆ ಅತಿ ಕಡಿದಾದ, ಅತಿ ಸಂವೇದಿ ರೇಖೆ ಸಿಗುತ್ತದೆ."},"apparatus":[{"en":"Colorimeter (or spectrophotometer) with 1 cm cuvettes","hi":"1 cm क्यूवेट सहित वर्णमापी (या स्पेक्ट्रोफ़ोटोमीटर)","kn":"1 cm ಕ್ಯುವೆಟ್‌ಗಳ ಸಹಿತ ವರ್ಣಮಾಪಕ (ಅಥವಾ ಸ್ಪೆಕ್ಟ್ರೋಫೋಟೋಮೀಟರ್)"},{"en":"KMnO₄ standards (1–5 × 10⁻⁴ M) and an unknown","hi":"KMnO₄ मानक (1–5 × 10⁻⁴ M) और एक अज्ञात","kn":"KMnO₄ ಮಾನಕಗಳು (1–5 × 10⁻⁴ M) ಮತ್ತು ಒಂದು ಅಜ್ಞಾತ"},{"en":"Distilled water as the blank","hi":"रिक्त के रूप में आसुत जल","kn":"ಖಾಲಿಯಾಗಿ ಬಟ್ಟಿ ನೀರು"},{"en":"Volumetric flasks and pipettes","hi":"आयतनमितीय फ्लास्क और पिपेट","kn":"ಘನಫಲಮಾಪಕ ಫ್ಲಾಸ್ಕ್‌ಗಳು ಮತ್ತು ಪಿಪೆಟ್‌ಗಳು"}],"steps":[{"en":"Set zero absorbance with the blank.","hi":"रिक्त से अवशोषणांक शून्य करें।","kn":"ಖಾಲಿಯಿಂದ ಹೀರಿಕೆಯನ್ನು ಶೂನ್ಯಗೊಳಿಸಿ."},{"en":"With one standard, read A from 400 to 700 nm and find λmax.","hi":"एक मानक के साथ 400 से 700 nm तक A पढ़ें और λmax ज्ञात करें।","kn":"ಒಂದು ಮಾನಕದೊಂದಿಗೆ 400 ರಿಂದ 700 nm ವರೆಗೆ A ಓದಿ λmax ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"At λmax, read every standard and plot A against c.","hi":"λmax पर हर मानक पढ़ें और A तथा c का ग्राफ़ बनाएँ।","kn":"λmax ನಲ್ಲಿ ಪ್ರತಿ ಮಾನಕ ಓದಿ A ಮತ್ತು c ನಕ್ಷೆ ಎಳೆಯಿರಿ."},{"en":"Read the unknown and find its concentration from the line.","hi":"अज्ञात को पढ़ें और रेखा से उसकी सांद्रता ज्ञात करें।","kn":"ಅಜ್ಞಾತವನ್ನು ಓದಿ ರೇಖೆಯಿಂದ ಅದರ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Export the readings as CSV and fit the straight lines.","hi":"पाठ्यांक CSV में निर्यात कर सीधी रेखाएँ फ़िट करें।","kn":"ಓದುಗಳನ್ನು CSV ಆಗಿ ರಫ್ತು ಮಾಡಿ ಸರಳರೇಖೆಗಳನ್ನು ಹೊಂದಿಸಿ."}],"precautions":[{"en":"Hold cuvettes by their frosted sides and wipe the clear faces.","hi":"क्यूवेट को उनकी खुरदरी सतहों से पकड़ें और पारदर्शी सतहें पोंछें।","kn":"ಕ್ಯುವೆಟ್‌ಗಳನ್ನು ಮಬ್ಬು ಬದಿಗಳಿಂದ ಹಿಡಿದು ಪಾರದರ್ಶಕ ಮುಖಗಳನ್ನು ಒರೆಸಿ."},{"en":"Rinse the cuvette with each solution before filling.","hi":"भरने से पहले क्यूवेट को हर विलयन से धोएँ।","kn":"ತುಂಬುವ ಮೊದಲು ಕ್ಯುವೆಟನ್ನು ಪ್ರತಿ ದ್ರಾವಣದಿಂದ ತೊಳೆಯಿರಿ."},{"en":"Keep absorbances below about 1 where the law holds best.","hi":"अवशोषणांक लगभग 1 से कम रखें जहाँ नियम सबसे अच्छा लागू होता है।","kn":"ನಿಯಮ ಉತ್ತಮವಾಗಿ ಅನ್ವಯಿಸುವ ಸುಮಾರು 1 ಕ್ಕಿಂತ ಕಡಿಮೆ ಹೀರಿಕೆಯಲ್ಲಿರಲಿ."}],"conclusion":{"en":"Absorbance is proportional to concentration at λmax (Beer–Lambert law); the calibration line gives ε and the unknown concentration.","hi":"λmax पर अवशोषणांक सांद्रता के अनुक्रमानुपाती है (बीयर–लैम्बर्ट नियम); अंशांकन रेखा ε और अज्ञात सांद्रता देती है।","kn":"λmax ನಲ್ಲಿ ಹೀರಿಕೆ ಸಾಂದ್ರತೆಗೆ ಅನುಪಾತೀಯ (ಬಿಯರ್–ಲ್ಯಾಂಬರ್ಟ್ ನಿಯಮ); ಮಾಪನಾಂಕ ರೇಖೆ ε ಮತ್ತು ಅಜ್ಞಾತ ಸಾಂದ್ರತೆ ನೀಡುತ್ತದೆ."},"viva":[{"q":{"en":"Why does KMnO₄ look purple if it absorbs at 525 nm?","hi":"KMnO₄ 525 nm पर अवशोषित करता है तो बैंगनी क्यों दिखता है?","kn":"KMnO₄ 525 nm ನಲ್ಲಿ ಹೀರಿದರೆ ನೇರಳೆಯಾಗಿ ಏಕೆ ಕಾಣುತ್ತದೆ?"},"a":{"en":"It absorbs green light; we see the complementary colours, red and blue: purple.","hi":"यह हरा प्रकाश अवशोषित करता है; हम पूरक रंग, लाल और नीला, देखते हैं: बैंगनी।","kn":"ಅದು ಹಸಿರು ಬೆಳಕನ್ನು ಹೀರುತ್ತದೆ; ನಾವು ಪೂರಕ ಬಣ್ಣಗಳಾದ ಕೆಂಪು ಮತ್ತು ನೀಲಿ ನೋಡುತ್ತೇವೆ: ನೇರಳೆ."}},{"q":{"en":"What is the unit of ε?","hi":"ε का मात्रक क्या है?","kn":"ε ದ ಏಕಮಾನ ಯಾವುದು?"},"a":{"en":"L mol⁻¹ cm⁻¹.","hi":"L mol⁻¹ cm⁻¹ (लीटर प्रति मोल प्रति सेंटीमीटर)।","kn":"L mol⁻¹ cm⁻¹ (ಪ್ರತಿ ಮೋಲ್ ಪ್ರತಿ ಸೆಂಟಿಮೀಟರ್‌ಗೆ ಲೀಟರ್)."}},{"q":{"en":"Why is a blank used?","hi":"रिक्त क्यों प्रयोग होता है?","kn":"ಖಾಲಿಯನ್ನು ಏಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"To cancel absorption by the solvent and the cuvette.","hi":"विलायक और क्यूवेट द्वारा अवशोषण को निरस्त करने के लिए।","kn":"ದ್ರಾವಕ ಮತ್ತು ಕ್ಯುವೆಟ್‌ನ ಹೀರಿಕೆಯನ್ನು ರದ್ದುಗೊಳಿಸಲು."}}]},{"id":"ostwald-viscosity","bench":"ostwald","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["ug"],"mode":"guided","curricula":["ug-chemistry"],"reviewed":false,"keywords":["viscosity","ostwald viscometer","relative viscosity","liquids","physical chemistry"],"title":{"en":"Viscosity of liquids with an Ostwald viscometer","hi":"ऑस्टवाल्ड श्यानतामापी से द्रवों की श्यानता","kn":"ಆಸ್ಟ್‌ವಾಲ್ಡ್ ಸ್ನಿಗ್ಧತಾಮಾಪಕದಿಂದ ದ್ರವಗಳ ಸ್ನಿಗ್ಧತೆ"},"summary":{"en":"Time each liquid between the two marks and compare with water to find its viscosity.","hi":"हर द्रव का दो निशानों के बीच समय लें और पानी से तुलना करके उसकी श्यानता ज्ञात करें।","kn":"ಪ್ರತಿ ದ್ರವದ ಎರಡು ಗುರುತುಗಳ ನಡುವಿನ ಸಮಯ ಅಳೆದು ನೀರಿನೊಂದಿಗೆ ಹೋಲಿಸಿ ಅದರ ಸ್ನಿಗ್ಧತೆ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To find the viscosity of given liquids relative to water using an Ostwald viscometer.","hi":"ऑस्टवाल्ड श्यानतामापी से पानी के सापेक्ष दिए गए द्रवों की श्यानता ज्ञात करना।","kn":"ಆಸ್ಟ್‌ವಾಲ್ಡ್ ಸ್ನಿಗ್ಧತಾಮಾಪಕದಿಂದ ನೀರಿಗೆ ಸಾಪೇಕ್ಷವಾಗಿ ಕೊಟ್ಟ ದ್ರವಗಳ ಸ್ನಿಗ್ಧತೆ ಕಂಡುಹಿಡಿಯುವುದು."},"principle":{"en":"By Poiseuille’s law the time for a fixed volume to flow through the capillary under its own weight is proportional to η/ρ. So η₁/η₂ = ρ₁t₁ / ρ₂t₂, and with water as the reference η = η_water × ρt ÷ (ρ_w t_w).","hi":"प्वाज़ॉय नियम से निश्चित आयतन के अपने भार से केशिका में बहने का समय η/ρ के अनुक्रमानुपाती है। अतः η₁/η₂ = ρ₁t₁ / ρ₂t₂, और पानी को संदर्भ लेकर η = η_water × ρt ÷ (ρ_w t_w).","kn":"ಪಾಯ್ಸೆಲ್ ನಿಯಮದಂತೆ ನಿಗದಿತ ಘನಫಲ ತನ್ನ ತೂಕದಿಂದ ಲೋಮನಾಳದಲ್ಲಿ ಹರಿಯುವ ಸಮಯ η/ρ ಗೆ ಅನುಪಾತೀಯ. ಆದ್ದರಿಂದ η₁/η₂ = ρ₁t₁ / ρ₂t₂; ನೀರನ್ನು ಉಲ್ಲೇಖವಾಗಿಟ್ಟು η = η_water × ρt ÷ (ρ_w t_w)."},"apparatus":[{"en":"Ostwald viscometer","hi":"ऑस्टवाल्ड श्यानतामापी","kn":"ಆಸ್ಟ್‌ವಾಲ್ಡ್ ಸ್ನಿಗ್ಧತಾಮಾಪಕ"},{"en":"Thermostat bath","hi":"थर्मोस्टैट ऊष्मक","kn":"ಥರ್ಮೋಸ್ಟಾಟ್ ತೊಟ್ಟಿ"},{"en":"Stopwatch","hi":"विराम घड़ी","kn":"ನಿಲುಗಡಿಯಾರ"},{"en":"Specific gravity bottle (for densities)","hi":"विशिष्ट गुरुत्व बोतल (घनत्व के लिए)","kn":"ವಿಶಿಷ್ಟ ಗುರುತ್ವ ಬಾಟಲಿ (ಸಾಂದ್ರತೆಗಾಗಿ)"}],"steps":[{"en":"Clean and dry the viscometer and clamp it vertically in the bath.","hi":"श्यानतामापी साफ़ और सूखा करके ऊष्मक में ऊर्ध्वाधर क्लैंप करें।","kn":"ಸ್ನಿಗ್ಧತಾಮಾಪಕವನ್ನು ಸ್ವಚ್ಛ, ಒಣಗಿಸಿ ತೊಟ್ಟಿಯಲ್ಲಿ ಲಂಬವಾಗಿ ಕ್ಲ್ಯಾಂಪ್ ಮಾಡಿ."},{"en":"Fill a fixed volume of water, suck it above the upper mark, and time its fall from the upper to the lower mark.","hi":"पानी का नियत आयतन भरें, उसे ऊपरी निशान से ऊपर खींचें, और ऊपरी से निचले निशान तक गिरने का समय लें।","kn":"ನೀರಿನ ನಿಗದಿತ ಘನಫಲ ತುಂಬಿ, ಮೇಲಿನ ಗುರುತಿನ ಮೇಲಕ್ಕೆ ಎಳೆದು, ಮೇಲಿನಿಂದ ಕೆಳಗಿನ ಗುರುತಿನವರೆಗೆ ಇಳಿಯುವ ಸಮಯ ಅಳೆಯಿರಿ."},{"en":"Repeat three times and take the mean.","hi":"तीन बार दोहराकर माध्य लें।","kn":"ಮೂರು ಬಾರಿ ಪುನರಾವರ್ತಿಸಿ ಸರಾಸರಿ ತೆಗೆಯಿರಿ."},{"en":"Do the same with each liquid (the same volume), and find its density.","hi":"हर द्रव के साथ (समान आयतन) यही करें, और उसका घनत्व ज्ञात करें।","kn":"ಪ್ರತಿ ದ್ರವದೊಂದಿಗೆ (ಅದೇ ಘನಫಲ) ಹೀಗೆಯೇ ಮಾಡಿ ಅದರ ಸಾಂದ್ರತೆ ಕಂಡುಹಿಡಿಯಿರಿ."},{"en":"Work out each viscosity relative to water.","hi":"हर श्यानता पानी के सापेक्ष निकालें।","kn":"ಪ್ರತಿ ಸ್ನಿಗ್ಧತೆಯನ್ನು ನೀರಿಗೆ ಸಾಪೇಕ್ಷವಾಗಿ ಲೆಕ್ಕಿಸಿ."}],"precautions":[{"en":"Use exactly the same volume of every liquid.","hi":"हर द्रव का ठीक समान आयतन लें।","kn":"ಪ್ರತಿ ದ್ರವದ ನಿಖರವಾಗಿ ಅದೇ ಘನಫಲ ಬಳಸಿ."},{"en":"Keep the temperature constant: viscosity changes quickly with it.","hi":"ताप नियत रखें: श्यानता उसके साथ तेज़ी से बदलती है।","kn":"ತಾಪ ಸ್ಥಿರವಾಗಿರಲಿ: ಸ್ನಿಗ್ಧತೆ ಅದರೊಂದಿಗೆ ವೇಗವಾಗಿ ಬದಲಾಗುತ್ತದೆ."},{"en":"The viscometer must be clean: dust in the capillary changes the time.","hi":"श्यानतामापी साफ़ हो: केशिका में धूल समय बदल देती है।","kn":"ಸ್ನಿಗ್ಧತಾಮಾಪಕ ಸ್ವಚ್ಛವಾಗಿರಲಿ: ಲೋಮನಾಳದಲ್ಲಿನ ಧೂಳು ಸಮಯ ಬದಲಿಸುತ್ತದೆ."}],"conclusion":{"en":"Flow time depends on η/ρ; acetone is far less viscous than water, while ethanol and glycerol solutions are more viscous.","hi":"बहाव समय η/ρ पर निर्भर करता है; ऐसीटोन पानी से कहीं कम श्यान है, जबकि एथेनॉल और ग्लिसरॉल विलयन अधिक श्यान हैं।","kn":"ಹರಿವಿನ ಸಮಯ η/ρ ಅನ್ನು ಅವಲಂಬಿಸಿದೆ; ಅಸಿಟೋನ್ ನೀರಿಗಿಂತ ಬಹಳ ಕಡಿಮೆ ಸ್ನಿಗ್ಧ, ಎಥೆನಾಲ್ ಮತ್ತು ಗ್ಲಿಸರಾಲ್ ದ್ರಾವಣಗಳು ಹೆಚ್ಚು ಸ್ನಿಗ್ಧ."},"viva":[{"q":{"en":"What is viscosity?","hi":"श्यानता क्या है?","kn":"ಸ್ನಿಗ್ಧತೆ ಎಂದರೇನು?"},"a":{"en":"A liquid’s internal friction: its resistance to flow.","hi":"द्रव का आंतरिक घर्षण: बहाव का उसका प्रतिरोध।","kn":"ದ್ರವದ ಆಂತರಿಕ ಘರ್ಷಣೆ: ಹರಿವಿಗೆ ಅದರ ಪ್ರತಿರೋಧ."}},{"q":{"en":"How does the viscosity of a liquid change with temperature?","hi":"ताप के साथ द्रव की श्यानता कैसे बदलती है?","kn":"ತಾಪದೊಂದಿಗೆ ದ್ರವದ ಸ್ನಿಗ್ಧತೆ ಹೇಗೆ ಬದಲಾಗುತ್ತದೆ?"},"a":{"en":"It decreases as the temperature rises.","hi":"ताप बढ़ने पर यह घटती है।","kn":"ತಾಪ ಏರಿದಂತೆ ಅದು ಕಡಿಮೆಯಾಗುತ್ತದೆ."}},{"q":{"en":"Why is glycerol so viscous?","hi":"ग्लिसरॉल इतना श्यान क्यों है?","kn":"ಗ್ಲಿಸರಾಲ್ ಏಕೆ ಇಷ್ಟು ಸ್ನಿಗ್ಧ?"},"a":{"en":"Its three OH groups form many hydrogen bonds between molecules.","hi":"इसके तीन OH समूह अणुओं के बीच अनेक हाइड्रोजन बंध बनाते हैं।","kn":"ಅದರ ಮೂರು OH ಗುಂಪುಗಳು ಅಣುಗಳ ನಡುವೆ ಹಲವು ಹೈಡ್ರೋಜನ್ ಬಂಧಗಳನ್ನು ರೂಪಿಸುತ್ತವೆ."}}]},{"id":"flame-test","bench":"flame-test","setup":{},"subject":"Chemistry","domain":"chemistry","levels":["11","12"],"mode":"explore","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["flame test","metal ions","salt analysis","cations","s-block elements","emission"],"title":{"en":"Flame tests for metal ions","hi":"धातु आयनों के लिए ज्वाला परीक्षण","kn":"ಲೋಹ ಅಯಾನುಗಳ ಜ್ವಾಲಾ ಪರೀಕ್ಷೆ"},"summary":{"en":"Hold salts in a Bunsen flame on a nichrome wire and match each colour to its metal ion.","hi":"नाइक्रोम तार पर लवणों को बुन्सन ज्वाला में रखें और हर रंग को उसके धातु आयन से मिलाएँ।","kn":"ನೈಕ್ರೋಮ್ ತಂತಿಯ ಮೇಲೆ ಲವಣಗಳನ್ನು ಬನ್ಸನ್ ಜ್ವಾಲೆಯಲ್ಲಿ ಹಿಡಿದು ಪ್ರತಿ ಬಣ್ಣವನ್ನು ಅದರ ಲೋಹ ಅಯಾನಿಗೆ ಹೊಂದಿಸಿ."},"aim":{"en":"To identify metal ions from the colours they give to a flame.","hi":"धातु आयनों द्वारा ज्वाला को दिए गए रंगों से उन्हें पहचानना।","kn":"ಲೋಹ ಅಯಾನುಗಳು ಜ್ವಾಲೆಗೆ ನೀಡುವ ಬಣ್ಣಗಳಿಂದ ಅವುಗಳನ್ನು ಗುರುತಿಸುವುದು."},"principle":{"en":"Heat excites electrons in the metal atoms to higher energy levels. As they fall back they give out light of particular wavelengths, so each metal colours the flame in its own way: sodium golden yellow, potassium lilac, calcium brick red, strontium crimson, barium apple green, copper blue-green.","hi":"ऊष्मा धातु परमाणुओं के इलेक्ट्रॉनों को उच्च ऊर्जा स्तरों पर उत्तेजित करती है। लौटते समय वे विशेष तरंगदैर्घ्य का प्रकाश देते हैं, इसलिए हर धातु ज्वाला को अपने ढंग से रंगती है: सोडियम सुनहरा पीला, पोटैशियम लाइलक, कैल्शियम ईंट जैसा लाल, स्ट्रॉन्शियम किरमिजी, बेरियम सेब जैसा हरा, ताँबा नीला-हरा।","kn":"ಉಷ್ಣ ಲೋಹ ಪರಮಾಣುಗಳ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳನ್ನು ಹೆಚ್ಚಿನ ಶಕ್ತಿ ಮಟ್ಟಗಳಿಗೆ ಉದ್ರೇಕಿಸುತ್ತದೆ. ಹಿಂತಿರುಗುವಾಗ ಅವು ನಿರ್ದಿಷ್ಟ ತರಂಗಾಂತರದ ಬೆಳಕು ನೀಡುತ್ತವೆ; ಆದ್ದರಿಂದ ಪ್ರತಿ ಲೋಹ ಜ್ವಾಲೆಗೆ ತನ್ನದೇ ಬಣ್ಣ ನೀಡುತ್ತದೆ: ಸೋಡಿಯಂ ಚಿನ್ನದ ಹಳದಿ, ಪೊಟ್ಯಾಸಿಯಂ ತಿಳಿ ನೇರಳೆ, ಕ್ಯಾಲ್ಸಿಯಂ ಇಟ್ಟಿಗೆ ಕೆಂಪು, ಸ್ಟ್ರಾನ್ಷಿಯಂ ಕಡುಗೆಂಪು, ಬೇರಿಯಂ ಸೇಬು ಹಸಿರು, ತಾಮ್ರ ನೀಲಿ-ಹಸಿರು."},"apparatus":[{"en":"Bunsen burner","hi":"बुन्सन बर्नर","kn":"ಬನ್ಸನ್ ಬರ್ನರ್"},{"en":"Nichrome wire loop on a glass rod","hi":"काँच की छड़ पर नाइक्रोम तार का फंदा","kn":"ಗಾಜಿನ ಕಡ್ಡಿಯ ಮೇಲೆ ನೈಕ್ರೋಮ್ ತಂತಿಯ ಕುಣಿಕೆ"},{"en":"Concentrated HCl in a watch glass","hi":"वॉच ग्लास में सांद्र HCl","kn":"ವಾಚ್ ಗ್ಲಾಸ್‌ನಲ್ಲಿ ಸಾಂದ್ರ HCl"},{"en":"Chlorides of Na, K, Ca, Sr, Ba, Cu, Li; blue cobalt glass","hi":"Na, K, Ca, Sr, Ba, Cu, Li के क्लोराइड; नीला कोबाल्ट काँच","kn":"Na, K, Ca, Sr, Ba, Cu, Li ಕ್ಲೋರೈಡ್‌ಗಳು; ನೀಲಿ ಕೋಬಾಲ್ಟ್ ಗಾಜು"}],"steps":[{"en":"Clean the wire by dipping it in HCl and heating until it gives no colour.","hi":"तार को HCl में डुबोकर तब तक गरम करें जब तक वह कोई रंग न दे।","kn":"ತಂತಿಯನ್ನು HCl ನಲ್ಲಿ ಅದ್ದಿ ಯಾವ ಬಣ್ಣವೂ ನೀಡದವರೆಗೆ ಬಿಸಿಮಾಡಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ."},{"en":"Make a paste of the salt with HCl on the wire.","hi":"तार पर लवण का HCl के साथ लेप बनाएँ।","kn":"ತಂತಿಯ ಮೇಲೆ ಲವಣವನ್ನು HCl ಜೊತೆ ಪೇಸ್ಟ್ ಮಾಡಿ."},{"en":"Hold it in the edge of the non-luminous flame and note the colour.","hi":"इसे अदीप्त ज्वाला के किनारे पर रखें और रंग देखें।","kn":"ಅದನ್ನು ಪ್ರಕಾಶರಹಿತ ಜ್ವಾಲೆಯ ಅಂಚಿನಲ್ಲಿ ಹಿಡಿದು ಬಣ್ಣ ಗಮನಿಸಿ."},{"en":"Clean the wire and repeat for every salt; view potassium through cobalt glass.","hi":"तार साफ़ करें और हर लवण के लिए दोहराएँ; पोटैशियम को कोबाल्ट काँच से देखें।","kn":"ತಂತಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ ಪ್ರತಿ ಲವಣಕ್ಕೆ ಪುನರಾವರ್ತಿಸಿ; ಪೊಟ್ಯಾಸಿಯಂ ಅನ್ನು ಕೋಬಾಲ್ಟ್ ಗಾಜಿನ ಮೂಲಕ ನೋಡಿ."}],"precautions":[{"en":"Clean the wire well between salts; traces of sodium hide other colours.","hi":"लवणों के बीच तार अच्छी तरह साफ़ करें; सोडियम के अंश दूसरे रंग छिपा देते हैं।","kn":"ಲವಣಗಳ ನಡುವೆ ತಂತಿಯನ್ನು ಚೆನ್ನಾಗಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ; ಸೋಡಿಯಂ ಕುರುಹುಗಳು ಇತರ ಬಣ್ಣಗಳನ್ನು ಮರೆಮಾಡುತ್ತವೆ."},{"en":"Handle concentrated HCl with care, away from the face.","hi":"सांद्र HCl को सावधानी से, चेहरे से दूर संभालें।","kn":"ಸಾಂದ್ರ HCl ಅನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ, ಮುಖದಿಂದ ದೂರ ನಿರ್ವಹಿಸಿ."},{"en":"Barium salts are poisonous: wash hands afterwards.","hi":"बेरियम लवण विषैले हैं: बाद में हाथ धोएँ।","kn":"ಬೇರಿಯಂ ಲವಣಗಳು ವಿಷಕಾರಿ: ನಂತರ ಕೈ ತೊಳೆಯಿರಿ."}],"conclusion":{"en":"Each metal ion gives a characteristic flame colour, which helps identify the cation in salt analysis (and is the basis of fireworks and flame photometry).","hi":"हर धातु आयन विशिष्ट ज्वाला रंग देता है, जो लवण विश्लेषण में धनायन पहचानने में सहायक है (और आतिशबाज़ी तथा ज्वाला प्रकाशमिति का आधार है)।","kn":"ಪ್ರತಿ ಲೋಹ ಅಯಾನು ವಿಶಿಷ್ಟ ಜ್ವಾಲಾ ಬಣ್ಣ ನೀಡುತ್ತದೆ; ಇದು ಲವಣ ವಿಶ್ಲೇಷಣೆಯಲ್ಲಿ ಧನಾಯನ ಗುರುತಿಸಲು ಸಹಾಯಕ (ಮತ್ತು ಪಟಾಕಿ ಹಾಗೂ ಜ್ವಾಲಾ ಫೋಟೋಮಿತಿಯ ಆಧಾರ)."},"viva":[{"q":{"en":"Why is concentrated HCl used?","hi":"सांद्र HCl क्यों प्रयोग होता है?","kn":"ಸಾಂದ್ರ HCl ಏಕೆ ಬಳಸುತ್ತಾರೆ?"},"a":{"en":"Metal chlorides are volatile, so they reach the flame easily.","hi":"धातु क्लोराइड वाष्पशील होते हैं, इसलिए आसानी से ज्वाला तक पहुँचते हैं।","kn":"ಲೋಹ ಕ್ಲೋರೈಡ್‌ಗಳು ಬಾಷ್ಪಶೀಲ; ಆದ್ದರಿಂದ ಸುಲಭವಾಗಿ ಜ್ವಾಲೆ ತಲುಪುತ್ತವೆ."}},{"q":{"en":"Why look at potassium through cobalt glass?","hi":"पोटैशियम को कोबाल्ट काँच से क्यों देखते हैं?","kn":"ಪೊಟ್ಯಾಸಿಯಂ ಅನ್ನು ಕೋಬಾಲ್ಟ್ ಗಾಜಿನ ಮೂಲಕ ಏಕೆ ನೋಡುತ್ತಾರೆ?"},"a":{"en":"The blue glass absorbs the yellow of any sodium impurity.","hi":"नीला काँच किसी भी सोडियम अशुद्धि का पीला रंग सोख लेता है।","kn":"ನೀಲಿ ಗಾಜು ಯಾವುದೇ ಸೋಡಿಯಂ ಕಲ್ಮಶದ ಹಳದಿಯನ್ನು ಹೀರುತ್ತದೆ."}},{"q":{"en":"Why does Mg not colour the flame?","hi":"Mg ज्वाला को रंग क्यों नहीं देता?","kn":"Mg ಜ್ವಾಲೆಗೆ ಬಣ್ಣ ಏಕೆ ನೀಡುವುದಿಲ್ಲ?"},"a":{"en":"Its electrons are held too strongly to be excited by the flame’s energy.","hi":"इसके इलेक्ट्रॉन इतने दृढ़ता से बँधे हैं कि ज्वाला की ऊर्जा उन्हें उत्तेजित नहीं कर पाती।","kn":"ಅದರ ಎಲೆಕ್ಟ್ರಾನ್‌ಗಳು ಜ್ವಾಲೆಯ ಶಕ್ತಿಯಿಂದ ಉದ್ರೇಕಗೊಳ್ಳಲಾಗದಷ್ಟು ಬಿಗಿಯಾಗಿ ಹಿಡಿಯಲ್ಪಟ್ಟಿವೆ."}}]},{"id":"salt-analysis","bench":"spot-test","setup":{"kit":"salt"},"subject":"Chemistry","domain":"chemistry","levels":["11","12"],"mode":"assessment","curricula":["cbse","ncert","ka-puc"],"reviewed":false,"keywords":["salt analysis","qualitative analysis","systematic analysis","cation","anion","acid radical","basic radical","group reagent"],"title":{"en":"Systematic salt analysis","hi":"क्रमबद्ध लवण विश्लेषण","kn":"ಕ್ರಮಬದ್ಧ ಲವಣ ವಿಶ್ಲೇಷಣೆ"},"summary":{"en":"Identify the cation and anion in unknown salts A–G with group reagents and confirmatory tests.","hi":"समूह अभिकर्मकों और पुष्टिकारी परीक्षणों से अज्ञात लवण A–G के धनायन और ऋणायन पहचानें।","kn":"ಗುಂಪು ಕಾರಕಗಳು ಮತ್ತು ದೃಢೀಕರಣ ಪರೀಕ್ಷೆಗಳಿಂದ ಅಜ್ಞಾತ ಲವಣ A–G ಯ ಧನಾಯನ ಮತ್ತು ಋಣಾಯನ ಗುರುತಿಸಿ."},"aim":{"en":"To identify one cation and one anion in a given salt by systematic qualitative analysis.","hi":"क्रमबद्ध गुणात्मक विश्लेषण से दिए गए लवण में एक धनायन और एक ऋणायन पहचानना।","kn":"ಕ್ರಮಬದ್ಧ ಗುಣಾತ್ಮಕ ವಿಶ್ಲೇಷಣೆಯಿಂದ ಕೊಟ್ಟ ಲವಣದಲ್ಲಿ ಒಂದು ಧನಾಯನ ಮತ್ತು ಒಂದು ಋಣಾಯನ ಗುರುತಿಸುವುದು."},"principle":{"en":"Anions are found with dilute and concentrated H₂SO₄ and specific reagents (BaCl₂ for sulphate, AgNO₃ for chloride). Cations are separated into groups by the solubility of their compounds: dil. HCl (group I), H₂S in acid (II), NH₄OH with NH₄Cl (III), H₂S in alkali (IV), (NH₄)₂CO₃ (V), and the rest (VI). A confirmatory test then names the ion.","hi":"ऋणायन तनु और सांद्र H₂SO₄ तथा विशिष्ट अभिकर्मकों (सल्फ़ेट के लिए BaCl₂, क्लोराइड के लिए AgNO₃) से पहचाने जाते हैं। धनायनों को उनके यौगिकों की विलेयता से समूहों में बाँटा जाता है: तनु HCl (समूह I), अम्ल में H₂S (II), NH₄Cl सहित NH₄OH (III), क्षार में H₂S (IV), (NH₄)₂CO₃ (V), और शेष (VI)। फिर पुष्टिकारी परीक्षण आयन का नाम बताता है।","kn":"ಋಣಾಯನಗಳನ್ನು ವಿರಳ ಮತ್ತು ಸಾಂದ್ರ H₂SO₄ ಹಾಗೂ ನಿರ್ದಿಷ್ಟ ಕಾರಕಗಳಿಂದ (ಸಲ್ಫೇಟ್‌ಗೆ BaCl₂, ಕ್ಲೋರೈಡ್‌ಗೆ AgNO₃) ಕಂಡುಹಿಡಿಯುತ್ತಾರೆ. ಧನಾಯನಗಳನ್ನು ಅವುಗಳ ಸಂಯುಕ್ತಗಳ ವಿಲೇಯತೆಯಿಂದ ಗುಂಪುಗಳಾಗಿ ವಿಂಗಡಿಸುತ್ತಾರೆ: ವಿರಳ HCl (ಗುಂಪು I), ಆಮ್ಲದಲ್ಲಿ H₂S (II), NH₄Cl ಸಹಿತ NH₄OH (III), ಕ್ಷಾರದಲ್ಲಿ H₂S (IV), (NH₄)₂CO₃ (V), ಮತ್ತು ಉಳಿದವು (VI). ನಂತರ ದೃಢೀಕರಣ ಪರೀಕ್ಷೆ ಅಯಾನನ್ನು ಹೆಸರಿಸುತ್ತದೆ."},"apparatus":[{"en":"Test tubes, rack and holder","hi":"परखनलियाँ, स्टैंड और धारक","kn":"ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು, ಸ್ಟ್ಯಾಂಡ್ ಮತ್ತು ಹಿಡಿಕೆ"},{"en":"Group reagents and confirmatory reagents","hi":"समूह अभिकर्मक और पुष्टिकारी अभिकर्मक","kn":"ಗುಂಪು ಕಾರಕಗಳು ಮತ್ತು ದೃಢೀಕರಣ ಕಾರಕಗಳು"},{"en":"Bunsen burner and red litmus","hi":"बुन्सन बर्नर और लाल लिटमस","kn":"ಬನ್ಸನ್ ಬರ್ನರ್ ಮತ್ತು ಕೆಂಪು ಲಿಟ್ಮಸ್"},{"en":"Salts A–G","hi":"लवण A–G","kn":"ಲವಣಗಳು A–G"}],"steps":[{"en":"Note the colour of the salt and its solution.","hi":"लवण और उसके विलयन का रंग लिखें।","kn":"ಲವಣ ಮತ್ತು ಅದರ ದ್ರಾವಣದ ಬಣ್ಣ ಬರೆಯಿರಿ."},{"en":"Test for the anion: dil. H₂SO₄, conc. H₂SO₄, then BaCl₂ or AgNO₃.","hi":"ऋणायन के लिए परीक्षण: तनु H₂SO₄, सांद्र H₂SO₄, फिर BaCl₂ या AgNO₃.","kn":"ಋಣಾಯನ ಪರೀಕ್ಷೆ: ವಿರಳ H₂SO₄, ಸಾಂದ್ರ H₂SO₄, ನಂತರ BaCl₂ ಅಥವಾ AgNO₃."},{"en":"Test for NH₄⁺ by warming with NaOH.","hi":"NaOH के साथ गरम करके NH₄⁺ का परीक्षण करें।","kn":"NaOH ಜೊತೆ ಬಿಸಿಮಾಡಿ NH₄⁺ ಪರೀಕ್ಷಿಸಿ."},{"en":"Add the group reagents in order until one gives a precipitate.","hi":"समूह अभिकर्मक क्रम से डालें जब तक कोई अवक्षेप न दे।","kn":"ಒಂದು ಅವಕ್ಷೇಪ ನೀಡುವವರೆಗೆ ಗುಂಪು ಕಾರಕಗಳನ್ನು ಕ್ರಮವಾಗಿ ಸೇರಿಸಿ."},{"en":"Confirm the cation with its special test and write the formula of the salt.","hi":"धनायन की उसके विशेष परीक्षण से पुष्टि करें और लवण का सूत्र लिखें।","kn":"ಧನಾಯನವನ್ನು ಅದರ ವಿಶೇಷ ಪರೀಕ್ಷೆಯಿಂದ ದೃಢಪಡಿಸಿ ಲವಣದ ಸೂತ್ರ ಬರೆಯಿರಿ."}],"precautions":[{"en":"Use small quantities and add reagents drop by drop.","hi":"कम मात्रा लें और अभिकर्मक बूँद-बूँद डालें।","kn":"ಸಣ್ಣ ಪ್ರಮಾಣ ಬಳಸಿ ಕಾರಕಗಳನ್ನು ಹನಿ ಹನಿಯಾಗಿ ಸೇರಿಸಿ."},{"en":"Never smell gases directly: waft them towards you.","hi":"गैसों को कभी सीधे न सूँघें: उन्हें हाथ से अपनी ओर लाएँ।","kn":"ಅನಿಲಗಳನ್ನು ಎಂದೂ ನೇರವಾಗಿ ಮೂಸಬೇಡಿ: ಕೈಯಿಂದ ನಿಮ್ಮತ್ತ ಬೀಸಿ."},{"en":"Work with H₂S and concentrated acids in the fume cupboard.","hi":"H₂S और सांद्र अम्लों के साथ धूम्र कक्ष में काम करें।","kn":"H₂S ಮತ್ತು ಸಾಂದ್ರ ಆಮ್ಲಗಳೊಂದಿಗೆ ಧೂಮ ಕಪಾಟಿನಲ್ಲಿ ಕೆಲಸ ಮಾಡಿ."},{"en":"Wear safety goggles; acids and alkalis harm the eyes.","hi":"सुरक्षा चश्मा पहनें; अम्ल और क्षार आँखों को हानि पहुँचाते हैं।","kn":"ಸುರಕ್ಷಾ ಕನ್ನಡಕ ಧರಿಸಿ; ಆಮ್ಲ ಮತ್ತು ಕ್ಷಾರಗಳು ಕಣ್ಣಿಗೆ ಹಾನಿ ಮಾಡುತ್ತವೆ."}],"conclusion":{"en":"By testing systematically, each unknown salt’s anion and cation are identified and confirmed (for example salt A is copper(II) sulphate).","hi":"क्रमबद्ध परीक्षण से हर अज्ञात लवण के ऋणायन और धनायन पहचाने और पुष्ट किए जाते हैं (उदाहरण के लिए लवण A कॉपर(II) सल्फ़ेट है)।","kn":"ಕ್ರಮಬದ್ಧ ಪರೀಕ್ಷೆಯಿಂದ ಪ್ರತಿ ಅಜ್ಞಾತ ಲವಣದ ಋಣಾಯನ ಮತ್ತು ಧನಾಯನ ಗುರುತಿಸಿ ದೃಢಪಡಿಸಲಾಗುತ್ತದೆ (ಉದಾಹರಣೆಗೆ ಲವಣ A ತಾಮ್ರ(II) ಸಲ್ಫೇಟ್)."},"viva":[{"q":{"en":"Why is NH₄Cl added before NH₄OH in group III?","hi":"समूह III में NH₄OH से पहले NH₄Cl क्यों डालते हैं?","kn":"ಗುಂಪು III ರಲ್ಲಿ NH₄OH ಮೊದಲು NH₄Cl ಏಕೆ ಸೇರಿಸುತ್ತಾರೆ?"},"a":{"en":"Common-ion effect: it lowers [OH⁻] so only group III hydroxides precipitate, not Mg(OH)₂.","hi":"समान आयन प्रभाव: यह [OH⁻] घटाता है ताकि केवल समूह III के हाइड्रॉक्साइड अवक्षेपित हों, Mg(OH)₂ नहीं।","kn":"ಸಮಾನ ಅಯಾನು ಪರಿಣಾಮ: ಅದು [OH⁻] ಕಡಿಮೆ ಮಾಡುತ್ತದೆ; ಗುಂಪು III ಹೈಡ್ರಾಕ್ಸೈಡ್‌ಗಳು ಮಾತ್ರ ಅವಕ್ಷೇಪಗೊಳ್ಳುತ್ತವೆ, Mg(OH)₂ ಅಲ್ಲ."}},{"q":{"en":"What is the group reagent for group I?","hi":"समूह I का समूह अभिकर्मक क्या है?","kn":"ಗುಂಪು I ರ ಗುಂಪು ಕಾರಕ ಯಾವುದು?"},"a":{"en":"Dilute HCl (it precipitates Pb²⁺ as PbCl₂).","hi":"तनु HCl (यह Pb²⁺ को PbCl₂ के रूप में अवक्षेपित करता है)।","kn":"ವಿರಳ HCl (ಅದು Pb²⁺ ಅನ್ನು PbCl₂ ಆಗಿ ಅವಕ್ಷೇಪಿಸುತ್ತದೆ)."}},{"q":{"en":"Which test confirms Fe³⁺?","hi":"Fe³⁺ की पुष्टि कौन-सा परीक्षण करता है?","kn":"Fe³⁺ ಅನ್ನು ಯಾವ ಪರೀಕ್ಷೆ ದೃಢಪಡಿಸುತ್ತದೆ?"},"a":{"en":"Potassium ferrocyanide gives Prussian blue.","hi":"पोटैशियम फ़ेरोसायनाइड प्रशियन नीला देता है।","kn":"ಪೊಟ್ಯಾಸಿಯಂ ಫೆರೋಸಯನೈಡ್ ಪ್ರಷ್ಯನ್ ನೀಲಿ ನೀಡುತ್ತದೆ."}}]},{"id":"food-tests","bench":"spot-test","setup":{"kit":"food"},"subject":"Biology","domain":"biology","levels":["9","12"],"mode":"guided","curricula":["cbse","ncert"],"reviewed":false,"keywords":["food tests","carbohydrates","proteins","fats","starch","reducing sugar","biuret","benedict's test","biomolecules","nutrition"],"title":{"en":"Tests for starch, sugar, protein and fat","hi":"स्टार्च, शर्करा, प्रोटीन और वसा के परीक्षण","kn":"ಪಿಷ್ಟ, ಸಕ್ಕರೆ, ಪ್ರೋಟೀನ್ ಮತ್ತು ಕೊಬ್ಬಿನ ಪರೀಕ್ಷೆಗಳು"},"summary":{"en":"Use iodine, Benedict’s, biuret and Sudan III to find what each food contains.","hi":"आयोडीन, बेनेडिक्ट, बाइयूरेट और सूडान III से पता करें कि हर खाद्य में क्या है।","kn":"ಅಯೋಡಿನ್, ಬೆನೆಡಿಕ್ಟ್, ಬೈಯುರೆಟ್ ಮತ್ತು ಸೂಡಾನ್ III ಬಳಸಿ ಪ್ರತಿ ಆಹಾರದಲ್ಲಿ ಏನಿದೆ ಕಂಡುಹಿಡಿಯಿರಿ."},"aim":{"en":"To test for the presence of starch, reducing sugar, protein and fat in given foods.","hi":"दिए गए खाद्यों में स्टार्च, अपचायी शर्करा, प्रोटीन और वसा की उपस्थिति का परीक्षण करना।","kn":"ಕೊಟ್ಟ ಆಹಾರಗಳಲ್ಲಿ ಪಿಷ್ಟ, ಅಪಕರ್ಷಕ ಸಕ್ಕರೆ, ಪ್ರೋಟೀನ್ ಮತ್ತು ಕೊಬ್ಬಿನ ಇರುವಿಕೆ ಪರೀಕ್ಷಿಸುವುದು."},"principle":{"en":"Iodine forms a blue-black complex with starch. Reducing sugars reduce blue Cu²⁺ in Benedict’s solution to brick-red Cu₂O on boiling. Peptide bonds give a violet colour with Cu²⁺ in alkali (biuret). Fats dissolve the red dye Sudan III and leave translucent spots on paper.","hi":"आयोडीन स्टार्च के साथ नीला-काला संकुल बनाता है। अपचायी शर्करा उबालने पर बेनेडिक्ट विलयन के नीले Cu²⁺ को ईंट-लाल Cu₂O में अपचयित करती है। पेप्टाइड बंध क्षार में Cu²⁺ के साथ बैंगनी रंग देते हैं (बाइयूरेट)। वसा लाल रंजक सूडान III को घोल लेती है और कागज़ पर पारभासी धब्बे छोड़ती है।","kn":"ಅಯೋಡಿನ್ ಪಿಷ್ಟದೊಂದಿಗೆ ನೀಲಿ-ಕಪ್ಪು ಸಂಕೀರ್ಣ ರೂಪಿಸುತ್ತದೆ. ಅಪಕರ್ಷಕ ಸಕ್ಕರೆಗಳು ಕುದಿಸಿದಾಗ ಬೆನೆಡಿಕ್ಟ್ ದ್ರಾವಣದ ನೀಲಿ Cu²⁺ ಅನ್ನು ಇಟ್ಟಿಗೆ-ಕೆಂಪು Cu₂O ಆಗಿ ಅಪಕರ್ಷಿಸುತ್ತವೆ. ಪೆಪ್ಟೈಡ್ ಬಂಧಗಳು ಕ್ಷಾರದಲ್ಲಿ Cu²⁺ ಜೊತೆ ನೇರಳೆ ಬಣ್ಣ ನೀಡುತ್ತವೆ (ಬೈಯುರೆಟ್). ಕೊಬ್ಬುಗಳು ಕೆಂಪು ಬಣ್ಣ ಸೂಡಾನ್ III ಅನ್ನು ಕರಗಿಸುತ್ತವೆ, ಕಾಗದದ ಮೇಲೆ ಅರೆಪಾರದರ್ಶಕ ಕಲೆ ಬಿಡುತ್ತವೆ."},"apparatus":[{"en":"Test tubes and a water bath","hi":"परखनलियाँ और जल ऊष्मक","kn":"ಪರೀಕ್ಷಾ ನಳಿಕೆಗಳು ಮತ್ತು ನೀರಿನ ತೊಟ್ಟಿ"},{"en":"Iodine, Benedict's solution, NaOH and CuSO₄, Sudan III","hi":"आयोडीन, बेनेडिक्ट विलयन, NaOH और CuSO₄, सूडान III","kn":"ಅಯೋಡಿನ್, ಬೆನೆಡಿಕ್ಟ್ ದ್ರಾವಣ, NaOH ಮತ್ತು CuSO₄, ಸೂಡಾನ್ III"},{"en":"Food samples: glucose, starch, egg albumin, oil, milk","hi":"खाद्य नमूने: ग्लूकोज़, स्टार्च, अंडे का एल्ब्यूमिन, तेल, दूध","kn":"ಆಹಾರ ಮಾದರಿಗಳು: ಗ್ಲೂಕೋಸ್, ಪಿಷ್ಟ, ಮೊಟ್ಟೆಯ ಆಲ್ಬುಮಿನ್, ಎಣ್ಣೆ, ಹಾಲು"},{"en":"Brown paper","hi":"भूरा कागज़","kn":"ಕಂದು ಕಾಗದ"}],"steps":[{"en":"Put a little of a food in a tube and add a few drops of iodine; note the colour.","hi":"परखनली में थोड़ा खाद्य लेकर आयोडीन की कुछ बूँदें डालें; रंग लिखें।","kn":"ನಳಿಕೆಯಲ್ಲಿ ಸ್ವಲ್ಪ ಆಹಾರ ಹಾಕಿ ಕೆಲವು ಹನಿ ಅಯೋಡಿನ್ ಸೇರಿಸಿ; ಬಣ್ಣ ಬರೆಯಿರಿ."},{"en":"Boil a fresh sample with Benedict's solution for 2 minutes.","hi":"नए नमूने को बेनेडिक्ट विलयन के साथ 2 मिनट उबालें।","kn":"ಹೊಸ ಮಾದರಿಯನ್ನು ಬೆನೆಡಿಕ್ಟ್ ದ್ರಾವಣದೊಂದಿಗೆ 2 ನಿಮಿಷ ಕುದಿಸಿ."},{"en":"Add NaOH and then a drop of CuSO₄ to a third sample (biuret test).","hi":"तीसरे नमूने में NaOH और फिर CuSO₄ की एक बूँद डालें (बाइयूरेट परीक्षण)।","kn":"ಮೂರನೇ ಮಾದರಿಗೆ NaOH ಮತ್ತು ನಂತರ ಒಂದು ಹನಿ CuSO₄ ಸೇರಿಸಿ (ಬೈಯುರೆಟ್ ಪರೀಕ್ಷೆ)."},{"en":"Shake a fourth sample with Sudan III, and rub some on paper.","hi":"चौथे नमूने को सूडान III के साथ हिलाएँ, और थोड़ा कागज़ पर रगड़ें।","kn":"ನಾಲ್ಕನೇ ಮಾದರಿಯನ್ನು ಸೂಡಾನ್ III ಜೊತೆ ಅಲುಗಾಡಿಸಿ, ಸ್ವಲ್ಪ ಕಾಗದದ ಮೇಲೆ ಉಜ್ಜಿ."},{"en":"Record what each food contains.","hi":"लिखें कि हर खाद्य में क्या है।","kn":"ಪ್ರತಿ ಆಹಾರದಲ್ಲಿ ಏನಿದೆ ದಾಖಲಿಸಿ."}],"precautions":[{"en":"Use clean tubes for every test.","hi":"हर परीक्षण के लिए साफ़ परखनलियाँ लें।","kn":"ಪ್ರತಿ ಪರೀಕ್ಷೆಗೆ ಸ್ವಚ್ಛ ನಳಿಕೆಗಳನ್ನು ಬಳಸಿ."},{"en":"Point the tube away from people when heating.","hi":"गरम करते समय परखनली का मुँह लोगों से दूर रखें।","kn":"ಬಿಸಿಮಾಡುವಾಗ ನಳಿಕೆಯ ಬಾಯಿ ಜನರಿಂದ ದೂರವಿರಲಿ."},{"en":"Add only a drop of CuSO₄ in the biuret test.","hi":"बाइयूरेट परीक्षण में CuSO₄ की केवल एक बूँद डालें।","kn":"ಬೈಯುರೆಟ್ ಪರೀಕ್ಷೆಯಲ್ಲಿ CuSO₄ ಒಂದೇ ಹನಿ ಸೇರಿಸಿ."}],"conclusion":{"en":"Starch gives blue-black with iodine, glucose brick-red with Benedict’s, albumin violet with biuret and oil a red layer with Sudan III; milk contains sugar, protein and fat.","hi":"स्टार्च आयोडीन से नीला-काला, ग्लूकोज़ बेनेडिक्ट से ईंट-लाल, एल्ब्यूमिन बाइयूरेट से बैंगनी और तेल सूडान III से लाल परत देता है; दूध में शर्करा, प्रोटीन और वसा हैं।","kn":"ಪಿಷ್ಟ ಅಯೋಡಿನ್‌ನಿಂದ ನೀಲಿ-ಕಪ್ಪು, ಗ್ಲೂಕೋಸ್ ಬೆನೆಡಿಕ್ಟ್‌ನಿಂದ ಇಟ್ಟಿಗೆ-ಕೆಂಪು, ಆಲ್ಬುಮಿನ್ ಬೈಯುರೆಟ್‌ನಿಂದ ನೇರಳೆ, ಎಣ್ಣೆ ಸೂಡಾನ್ III ನಿಂದ ಕೆಂಪು ಪದರ ನೀಡುತ್ತವೆ; ಹಾಲಿನಲ್ಲಿ ಸಕ್ಕರೆ, ಪ್ರೋಟೀನ್ ಮತ್ತು ಕೊಬ್ಬು ಇವೆ."},"viva":[{"q":{"en":"Is sucrose a reducing sugar?","hi":"क्या सुक्रोज़ अपचायी शर्करा है?","kn":"ಸುಕ್ರೋಸ್ ಅಪಕರ್ಷಕ ಸಕ್ಕರೆಯೇ?"},"a":{"en":"No: it gives a negative Benedict’s test unless first hydrolysed.","hi":"नहीं: पहले जल-अपघटन के बिना यह बेनेडिक्ट परीक्षण में ऋणात्मक है।","kn":"ಇಲ್ಲ: ಮೊದಲು ಜಲವಿಭಜನೆ ಮಾಡದಿದ್ದರೆ ಬೆನೆಡಿಕ್ಟ್ ಪರೀಕ್ಷೆ ಋಣಾತ್ಮಕ."}},{"q":{"en":"Which nutrient gives energy fastest?","hi":"कौन-सा पोषक सबसे जल्दी ऊर्जा देता है?","kn":"ಯಾವ ಪೋಷಕಾಂಶ ಅತಿ ಬೇಗ ಶಕ್ತಿ ನೀಡುತ್ತದೆ?"},"a":{"en":"Carbohydrates such as glucose.","hi":"ग्लूकोज़ जैसे कार्बोहाइड्रेट।","kn":"ಗ್ಲೂಕೋಸ್‌ನಂತಹ ಕಾರ್ಬೋಹೈಡ್ರೇಟ್‌ಗಳು."}},{"q":{"en":"What does the biuret test detect?","hi":"बाइयूरेट परीक्षण क्या पहचानता है?","kn":"ಬೈಯುರೆಟ್ ಪರೀಕ್ಷೆ ಏನನ್ನು ಪತ್ತೆಹಚ್ಚುತ್ತದೆ?"},"a":{"en":"Peptide bonds, so proteins.","hi":"पेप्टाइड बंध, अर्थात प्रोटीन।","kn":"ಪೆಪ್ಟೈಡ್ ಬಂಧಗಳು, ಅಂದರೆ ಪ್ರೋಟೀನ್‌ಗಳು."}}]},{"id":"toxicology-spot-tests","bench":"spot-test","setup":{"kit":"toxicology"},"subject":"Forensics","domain":"forensics","levels":["11","12","ug"],"mode":"assessment","curricula":["forensics"],"reviewed":false,"keywords":["forensic toxicology","toxicology","presumptive test","spot test","colour test","poison","drugs"],"title":{"en":"Forensic toxicology: presumptive colour tests","hi":"न्यायालयिक विषविज्ञान: प्रारंभिक रंग परीक्षण","kn":"ವಿಧಿವಿಜ್ಞಾನ ವಿಷಶಾಸ್ತ್ರ: ಪ್ರಾಥಮಿಕ ಬಣ್ಣ ಪರೀಕ್ಷೆಗಳು"},"summary":{"en":"Screen seized exhibits with Marquis, ferric chloride, Scott and Reinsch tests and decide which need laboratory confirmation.","hi":"जब्त प्रदर्शों की मार्क्विस, फ़ेरिक क्लोराइड, स्कॉट और राइन्श परीक्षणों से जाँच करें और तय करें कि किनकी प्रयोगशाला पुष्टि चाहिए।","kn":"ವಶಪಡಿಸಿದ ವಸ್ತುಗಳನ್ನು ಮಾರ್ಕ್ವಿಸ್, ಫೆರಿಕ್ ಕ್ಲೋರೈಡ್, ಸ್ಕಾಟ್ ಮತ್ತು ರೈನ್ಶ್ ಪರೀಕ್ಷೆಗಳಿಂದ ಪರೀಕ್ಷಿಸಿ ಯಾವುದಕ್ಕೆ ಪ್ರಯೋಗಾಲಯ ದೃಢೀಕರಣ ಬೇಕು ನಿರ್ಧರಿಸಿ."},"aim":{"en":"To screen unknown exhibits for drugs and poisons with presumptive colour tests.","hi":"प्रारंभिक रंग परीक्षणों से अज्ञात प्रदर्शों में औषधियों और विषों की जाँच करना।","kn":"ಪ್ರಾಥಮಿಕ ಬಣ್ಣ ಪರೀಕ್ಷೆಗಳಿಂದ ಅಜ್ಞಾತ ವಸ್ತುಗಳಲ್ಲಿ ಔಷಧ ಮತ್ತು ವಿಷಗಳನ್ನು ಪರೀಕ್ಷಿಸುವುದು."},"principle":{"en":"A presumptive test gives a colour with a class of compounds: Marquis (formaldehyde in sulphuric acid) turns purple with opiates and orange-brown with amphetamines; ferric chloride turns violet with salicylates; cobalt thiocyanate (Scott) turns blue with cocaine; in the Reinsch test arsenic or mercury deposits on copper. A positive result only narrows the possibilities; confirmation needs chromatography or spectroscopy.","hi":"प्रारंभिक परीक्षण यौगिकों के एक वर्ग के साथ रंग देता है: मार्क्विस (सल्फ़्यूरिक अम्ल में फ़ॉर्मैल्डिहाइड) ओपिएट के साथ बैंगनी और ऐम्फ़ेटामीन के साथ नारंगी-भूरा; फ़ेरिक क्लोराइड सैलिसिलेट के साथ बैंगनी; कोबाल्ट थायोसायनेट (स्कॉट) कोकेन के साथ नीला; राइन्श परीक्षण में आर्सेनिक या पारा ताँबे पर जमता है। धनात्मक परिणाम केवल संभावनाएँ घटाता है; पुष्टि के लिए वर्णलेखन या स्पेक्ट्रमिकी चाहिए।","kn":"ಪ್ರಾಥಮಿಕ ಪರೀಕ್ಷೆ ಒಂದು ವರ್ಗದ ಸಂಯುಕ್ತಗಳೊಂದಿಗೆ ಬಣ್ಣ ನೀಡುತ್ತದೆ: ಮಾರ್ಕ್ವಿಸ್ (ಸಲ್ಫ್ಯೂರಿಕ್ ಆಮ್ಲದಲ್ಲಿ ಫಾರ್ಮಾಲ್ಡಿಹೈಡ್) ಓಪಿಯೇಟ್‌ಗಳೊಂದಿಗೆ ನೇರಳೆ, ಆಂಫೆಟಮೀನ್‌ಗಳೊಂದಿಗೆ ಕಿತ್ತಳೆ-ಕಂದು; ಫೆರಿಕ್ ಕ್ಲೋರೈಡ್ ಸ್ಯಾಲಿಸಿಲೇಟ್‌ಗಳೊಂದಿಗೆ ನೇರಳೆ; ಕೋಬಾಲ್ಟ್ ಥಯೋಸಯನೇಟ್ (ಸ್ಕಾಟ್) ಕೊಕೇನ್‌ನೊಂದಿಗೆ ನೀಲಿ; ರೈನ್ಶ್ ಪರೀಕ್ಷೆಯಲ್ಲಿ ಆರ್ಸೆನಿಕ್ ಅಥವಾ ಪಾದರಸ ತಾಮ್ರದ ಮೇಲೆ ಶೇಖರಣೆಯಾಗುತ್ತದೆ. ಧನಾತ್ಮಕ ಫಲಿತಾಂಶ ಸಾಧ್ಯತೆಗಳನ್ನು ಕಿರಿದಾಗಿಸುತ್ತದೆ ಅಷ್ಟೇ; ದೃಢೀಕರಣಕ್ಕೆ ವರ್ಣರೇಖನ ಅಥವಾ ರೋಹಿತಮಾಪನ ಬೇಕು."},"apparatus":[{"en":"Spot plate and droppers","hi":"स्पॉट प्लेट और ड्रॉपर","kn":"ಸ್ಪಾಟ್ ಪ್ಲೇಟ್ ಮತ್ತು ಡ್ರಾಪರ್‌ಗಳು"},{"en":"Marquis, ferric chloride and Scott reagents","hi":"मार्क्विस, फ़ेरिक क्लोराइड और स्कॉट अभिकर्मक","kn":"ಮಾರ್ಕ್ವಿಸ್, ಫೆರಿಕ್ ಕ್ಲೋರೈಡ್ ಮತ್ತು ಸ್ಕಾಟ್ ಕಾರಕಗಳು"},{"en":"Copper strips and dilute HCl (Reinsch)","hi":"ताँबे की पट्टियाँ और तनु HCl (राइन्श)","kn":"ತಾಮ್ರದ ಪಟ್ಟಿಗಳು ಮತ್ತು ವಿರಳ HCl (ರೈನ್ಶ್)"},{"en":"Exhibits 1–6, gloves, goggles and evidence labels","hi":"प्रदर्श 1–6, दस्ताने, चश्मा और साक्ष्य लेबल","kn":"ವಸ್ತುಗಳು 1–6, ಕೈಗವಸು, ಕನ್ನಡಕ ಮತ್ತು ಸಾಕ್ಷ್ಯ ಹಣೆಪಟ್ಟಿಗಳು"}],"steps":[{"en":"Put a few milligrams of each exhibit in separate wells of the spot plate.","hi":"हर प्रदर्श के कुछ मिलीग्राम स्पॉट प्लेट के अलग गड्ढों में रखें।","kn":"ಪ್ರತಿ ವಸ್ತುವಿನ ಕೆಲವು ಮಿಲಿಗ್ರಾಂ ಅನ್ನು ಸ್ಪಾಟ್ ಪ್ಲೇಟ್‌ನ ಬೇರೆ ಬೇರೆ ಗುಂಡಿಗಳಲ್ಲಿಡಿ."},{"en":"Add one drop of reagent and note any colour within a minute.","hi":"अभिकर्मक की एक बूँद डालें और एक मिनट के भीतर कोई रंग देखें।","kn":"ಕಾರಕದ ಒಂದು ಹನಿ ಸೇರಿಸಿ ಒಂದು ನಿಮಿಷದೊಳಗಿನ ಯಾವುದೇ ಬಣ್ಣ ಗಮನಿಸಿ."},{"en":"Run a blank (reagent alone) and a known control alongside.","hi":"साथ में एक रिक्त (केवल अभिकर्मक) और एक ज्ञात नियंत्रण चलाएँ।","kn":"ಜೊತೆಗೆ ಒಂದು ಖಾಲಿ (ಕಾರಕ ಮಾತ್ರ) ಮತ್ತು ತಿಳಿದ ನಿಯಂತ್ರಣ ನಡೆಸಿ."},{"en":"Repeat with each reagent and record every result.","hi":"हर अभिकर्मक के साथ दोहराएँ और हर परिणाम लिखें।","kn":"ಪ್ರತಿ ಕಾರಕದೊಂದಿಗೆ ಪುನರಾವರ್ತಿಸಿ ಪ್ರತಿ ಫಲಿತಾಂಶ ದಾಖಲಿಸಿ."},{"en":"List which exhibits must go for confirmatory analysis.","hi":"सूची बनाएँ कि किन प्रदर्शों को पुष्टिकारी विश्लेषण के लिए भेजना है।","kn":"ಯಾವ ವಸ್ತುಗಳು ದೃಢೀಕರಣ ವಿಶ್ಲೇಷಣೆಗೆ ಹೋಗಬೇಕು ಪಟ್ಟಿ ಮಾಡಿ."}],"precautions":[{"en":"Marquis reagent contains concentrated sulphuric acid: wear gloves and goggles.","hi":"मार्क्विस अभिकर्मक में सांद्र सल्फ़्यूरिक अम्ल है: दस्ताने और चश्मा पहनें।","kn":"ಮಾರ್ಕ್ವಿಸ್ ಕಾರಕದಲ್ಲಿ ಸಾಂದ್ರ ಸಲ್ಫ್ಯೂರಿಕ್ ಆಮ್ಲ ಇದೆ: ಕೈಗವಸು ಮತ್ತು ಕನ್ನಡಕ ಧರಿಸಿ."},{"en":"Never taste or smell exhibits; keep the chain of custody.","hi":"प्रदर्शों को कभी न चखें या सूँघें; अभिरक्षा की शृंखला बनाए रखें।","kn":"ವಸ್ತುಗಳನ್ನು ಎಂದೂ ರುಚಿ ನೋಡಬೇಡಿ ಅಥವಾ ಮೂಸಬೇಡಿ; ಕಸ್ಟಡಿ ಸರಪಳಿ ಕಾಪಾಡಿ."},{"en":"Use the smallest amount so the rest is kept for the laboratory.","hi":"सबसे कम मात्रा लें ताकि शेष प्रयोगशाला के लिए बचे।","kn":"ಉಳಿದುದು ಪ್ರಯೋಗಾಲಯಕ್ಕೆ ಉಳಿಯುವಂತೆ ಅತಿ ಕಡಿಮೆ ಪ್ರಮಾಣ ಬಳಸಿ."}],"conclusion":{"en":"The colour tests sort the exhibits into presumptive classes (opiate, amphetamine, salicylate, cocaine, arsenic) and show which are negative; every positive must be confirmed by laboratory analysis before it is reported.","hi":"रंग परीक्षण प्रदर्शों को प्रारंभिक वर्गों (ओपिएट, ऐम्फ़ेटामीन, सैलिसिलेट, कोकेन, आर्सेनिक) में बाँटते हैं और दिखाते हैं कि कौन ऋणात्मक हैं; हर धनात्मक की रिपोर्ट से पहले प्रयोगशाला विश्लेषण से पुष्टि आवश्यक है।","kn":"ಬಣ್ಣ ಪರೀಕ್ಷೆಗಳು ವಸ್ತುಗಳನ್ನು ಪ್ರಾಥಮಿಕ ವರ್ಗಗಳಾಗಿ (ಓಪಿಯೇಟ್, ಆಂಫೆಟಮೀನ್, ಸ್ಯಾಲಿಸಿಲೇಟ್, ಕೊಕೇನ್, ಆರ್ಸೆನಿಕ್) ವಿಂಗಡಿಸಿ ಯಾವುವು ಋಣಾತ್ಮಕ ಎಂದು ತೋರಿಸುತ್ತವೆ; ಪ್ರತಿ ಧನಾತ್ಮಕವನ್ನು ವರದಿ ಮಾಡುವ ಮೊದಲು ಪ್ರಯೋಗಾಲಯ ವಿಶ್ಲೇಷಣೆಯಿಂದ ದೃಢಪಡಿಸಬೇಕು."},"viva":[{"q":{"en":"Why is a presumptive test not enough in court?","hi":"न्यायालय में प्रारंभिक परीक्षण पर्याप्त क्यों नहीं?","kn":"ನ್ಯಾಯಾಲಯದಲ್ಲಿ ಪ್ರಾಥಮಿಕ ಪರೀಕ್ಷೆ ಏಕೆ ಸಾಕಾಗುವುದಿಲ್ಲ?"},"a":{"en":"Many harmless substances give similar colours (false positives); only a confirmatory test identifies the compound.","hi":"कई हानिरहित पदार्थ समान रंग देते हैं (मिथ्या धनात्मक); केवल पुष्टिकारी परीक्षण यौगिक पहचानता है।","kn":"ಹಲವು ನಿರುಪದ್ರವ ವಸ್ತುಗಳು ಇದೇ ಬಣ್ಣ ನೀಡುತ್ತವೆ (ತಪ್ಪು ಧನಾತ್ಮಕ); ದೃಢೀಕರಣ ಪರೀಕ್ಷೆ ಮಾತ್ರ ಸಂಯುಕ್ತವನ್ನು ಗುರುತಿಸುತ್ತದೆ."}},{"q":{"en":"Why run a blank?","hi":"रिक्त क्यों चलाते हैं?","kn":"ಖಾಲಿಯನ್ನು ಏಕೆ ನಡೆಸುತ್ತಾರೆ?"},"a":{"en":"To show the reagent itself gives no colour.","hi":"यह दिखाने के लिए कि अभिकर्मक स्वयं कोई रंग नहीं देता।","kn":"ಕಾರಕ ತಾನೇ ಯಾವ ಬಣ್ಣವೂ ನೀಡುವುದಿಲ್ಲ ಎಂದು ತೋರಿಸಲು."}},{"q":{"en":"Name a confirmatory technique.","hi":"एक पुष्टिकारी तकनीक बताइए।","kn":"ಒಂದು ದೃಢೀಕರಣ ತಂತ್ರ ಹೆಸರಿಸಿ."},"a":{"en":"Gas chromatography–mass spectrometry (GC–MS).","hi":"गैस वर्णलेखन–द्रव्यमान स्पेक्ट्रममिति (GC–MS)।","kn":"ಅನಿಲ ವರ್ಣರೇಖನ–ದ್ರವ್ಯರಾಶಿ ರೋಹಿತಮಾಪನ (GC–MS)."}}]}]}''';
